 return jsonb_build_object('tamam',true,'id',tid,'gonderen',p.kad,
  'hedef',hedef,'hedef_tur',p_tur,'tutar',m,
  'kalan', (select para from oyun.cuzdan where user_id=u));
end $function$
;

-- Seçim beyannamesi haberini resmi kaynaktan bir kere yayinla, olay logundan ikincisini uretme.
CREATE OR REPLACE FUNCTION oyun.ajans_derle()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t timestamptz:=oyun.simdi();e record; v_count bigint; v_before bigint;
  kind text; ttl text; summary text; article text; pp integer; name text;
begin
 -- pg_cron ayni anda veya oyun motorunda cagrilsa bile yarisma olmaz.
 if not pg_try_advisory_xact_lock(82771,808) then
   return jsonb_build_object('tamam',true,'mesaj','Başka haber taraması sürüyor');
 end if;
 select count(*) into v_before from oyun.ajans_haberleri;

 -- Kamuya acik parti olaylari: ic oylamalarin/tuzuklerin gizli metinlerini alma.
 for e in
   select o.id,o.zaman,o.metin,o.parti_id,o.il_id,coalesce(p.kisa,'Parti') parti
   from oyun.olaylar o left join oyun.partiler p on p.id=o.parti_id
   where o.zaman>=t-interval '21 days'
     and not (o.metin ilike '%beyannamesini açıkladı%' and exists(
       select 1 from oyun.parti_beyanname b where b.parti_id=o.parti_id
       and b.zaman>=o.zaman-interval '2 days'))
     and (o.metin ilike '%beyannamesini açıkladı%'
      or o.metin ilike '%genel başkanlığını üstlendi%'
      or o.metin ilike '%adını%olarak değiştirdi%'
      or o.metin ilike '%adayını açıkladı%'
      or o.metin ilike '%adayını destekliyor%'
      or o.metin ilike '%parti amblemini değiştirdi%'
      or o.metin ilike '%genel başkan yardımcılığına atandı%')
   order by o.zaman,o.id
 loop
   kind:='siyaset';pp:=64;
   if e.metin ilike '%beyannamesini açıkladı%' then
     kind:='secim';pp:=90;ttl:=e.parti||' seçim beyannamesini yayımladı';
   elsif e.metin ilike '%genel başkanlığını üstlendi%' then
     ttl:=e.parti||' yönetiminde yeni genel başkan';pp:=86;
   elsif e.metin ilike '%adını%olarak değiştirdi%' then
     ttl:=e.parti||' siyasi kimliğini yeniledi';pp:=77;
   elsif e.metin ilike '%adayını açıkladı%' or e.metin ilike '%adayını destekliyor%' then
     kind:='adaylar';pp:=85;ttl:=e.parti||' adaylık konusunda karar açıkladı';
   elsif e.metin ilike '%genel başkan yardımcılığına atandı%' then
     ttl:=e.parti||' yönetim kadrosuna yeni atama';pp:=65;
   else
     ttl:=e.parti||' amblemini değiştirdi';pp:=60;
   end if;
   summary:=e.metin;
   article:='Türkiye Gündem haber merkezinin oyun içi resmî olay kaydına göre '||
     e.metin||E'\n\n'||
     'Bu gelişme '||to_char(e.zaman at time zone 'Europe/Istanbul','DD.MM.YYYY HH24:MI')||
     ' tarihinde kayda geçti. Haberdeki açıklama oyun verilerinden aktarılmıştır. '||
     'Seçim sonucu veya oy oranı konusunda henüz doğrulanmamış bir tahmin yapılmamıştır.';
   perform oyun.ajans_yayinla('olay:'||e.id,kind,ttl,summary,article,pp,e.parti_id,e.il_id,e.zaman);
 end loop;

 -- Parti beyannameleri: metin resmi tabloya kaydedildiyse tam metni de ver.
 for e in select b.parti_id,b.donem,b.zaman,b.metin,p.kisa,p.ad
   from oyun.parti_beyanname b join oyun.partiler p on p.id=b.parti_id
   where b.zaman>=t-interval '21 days' order by b.zaman
 loop
   ttl:=e.kisa||' '||e.donem||' seçim beyannamesini açıkladı';
   summary:=e.ad||' seçim vaat ve programını duyurdu.';
   article:=e.ad||' tarafından '||e.donem||' dönemi için seçim beyannamesi yayımlandı.'||
    E'\n\n'||case when nullif(btrim(coalesce(e.metin,'')),'') is not null
      then 'Beyanname açıklaması:'||E'\n'||e.metin
      else 'Yazılı beyanname özeti bulunmuyor; partinin oyun içi vaatleri kendi parti sayfasında incelenebilir.' end||
    E'\n\n'||'Bu bir parti açıklamasıdır; gazetenin desteği ya da görüşü değildir.';
   perform oyun.ajans_yayinla('beyanname:'||e.parti_id||':'||e.donem,'secim',ttl,summary,article,92,e.parti_id,null,e.zaman);
 end loop;

 -- Cumhurbaskani kararlari. Sadece KESIN ve gercek aday kaydi olan adaylar.
 for e in
  select k.donem,k.parti_id,k.yontem,k.destek_parti,k.zaman,
   p.kisa,p.ad,coalesce(h.kisa,'') hedef_kisa,
   a.user_id,pr.kad, a.id aday_id
  from oyun.cb_kararlar k
  join oyun.partiler p on p.id=k.parti_id
  join oyun.secimler s on s.tur='cb' and s.donem=k.donem
  left join oyun.partiler h on h.id=k.destek_parti
  left join lateral (
    select aa.id,aa.user_id from oyun.adaylar aa
    where aa.secim_id=s.id and aa.parti_id=case when k.yontem='destek' then k.destek_parti else k.parti_id end
    order by aa.id limit 1
  ) a on true
  left join oyun.profiller pr on pr.id=a.user_id
  where k.zaman>=t-interval '21 days' and a.id is not null
  order by k.zaman
 loop
  if e.yontem='destek' then
    ttl:=e.kisa||' Cumhurbaşkanlığında '||e.hedef_kisa||' adayını destekleyecek';
    summary:=e.kisa||', '||e.kad||' adlı gerçek oyuncunun ortak adaylığını destekleme kararı aldı.';
    kind:='ittifak';
    article:=e.ad||', '||e.donem||' Cumhurbaşkanlığı seçimi için '||
      e.hedef_kisa||' adayı '||e.kad||' lehine destek kararı açıkladı.'||
      E'\n\n'||'Destek veren partinin ayrıca ikinci bir Cumhurbaşkanı adayı bulunmuyor. '||
      'Seçmenler oylarını tek gerçek oyuncu adaya verecek.';
  else
    ttl:=e.kisa||' Cumhurbaşkanı adayını açıkladı: '||e.kad;
    summary:=e.ad||', Cumhurbaşkanı adayı olarak '||e.kad||' adlı oyuncunun ismini kesinleştirdi.';
    kind:='adaylar';
    article:=e.ad||', '||e.donem||' dönemi Cumhurbaşkanlığı seçiminde '||
      e.kad||' adlı oyuncuyu aday gösterdi.'||E'\n\n'||
      'Adayın ve varsa kendisini destekleyen partilerin ayrıntıları parti sayfasından takip edilebilir.';
  end if;
  perform oyun.ajans_yayinla('cb:'||e.donem||':'||e.parti_id||':'||e.yontem||':'||coalesce(e.aday_id::text,''),
      kind,ttl,summary,article,96,e.parti_id,null,e.zaman);
 end loop;

 -- Belediye kesin adaylari ilan edildikce il odakli haber.
 for e in
 select a.id,a.parti_id,a.il_id,a.basvuru_at,s.donem,p.kisa,p.ad,
   pr.kad,i.ad il
 from oyun.adaylar a join oyun.secimler s on s.id=a.secim_id and s.tur='bel'
 join oyun.partiler p on p.id=a.parti_id join oyun.profiller pr on pr.id=a.user_id
 left join oyun.iller i on i.id=a.il_id
 where a.basvuru_at>=t-interval '21 days'
 order by a.basvuru_at
 loop
  ttl:=e.il||' için '||e.kisa||' adayı: '||e.kad;
  summary:=e.ad||', '||e.il||' belediye başkanlığına '||e.kad||' adlı oyuncuyu aday gösterdi.';
  article:=summary||E'\n\n'||e.donem||' belediye seçiminde adaylık kesinleşti. '||
    'Oy verme ve seçim sonucuna ilişkin bilgiler oyundaki resmî takvimden takip edilmelidir.';
  perform oyun.ajans_yayinla('bel_aday:'||e.id,'adaylar',ttl,summary,article,73,e.parti_id,e.il_id,e.basvuru_at);
 end loop;

 -- Il bazinda ortak belediye baskan adayi desteği.
 for e in
 select b.secim_id,b.il_id,b.parti_id,b.hedef_parti_id,b.zaman,src.kisa src,
 target.kisa hedef, pr.kad, il.ad il
 from oyun.bel_aday_destek b
 join oyun.partiler src on src.id=b.parti_id
 join oyun.partiler target on target.id=b.hedef_parti_id
 join oyun.adaylar a on a.id=b.aday_id join oyun.profiller pr on pr.id=a.user_id
 join oyun.iller il on il.id=b.il_id
 where b.zaman>=t-interval '21 days'
 loop
   ttl:=e.il||' seçimi: '||e.src||' ile '||e.hedef||' ortak adayda buluştu';
   summary:=e.src||', '||e.il||' belediye seçiminde '||e.kad||
     ' adayını destekliyor.';
   article:=e.src||', '||e.hedef||' partisinin '||e.il||' belediye başkanı adayı '||e.kad||
      ' lehine destek kararı açıkladı.'||E'\n\n'||
      'Destek veren parti aynı ilde ayrı adayla yarışmıyor; seçmenler ortak adaya oy verecek.';
   perform oyun.ajans_yayinla('bel_destek:'||e.secim_id||':'||e.il_id||':'||e.parti_id||':'||e.hedef_parti_id,
      'ittifak',ttl,summary,article,88,e.parti_id,e.il_id,e.zaman);
 end loop;

 -- Genel baskanin tum oyunculara yaptigi ADAY tanitimlari; uyeye ozel yayinlar yayinlanmaz.
 for e in
 select a.id,a.parti_id,a.zaman,a.metin,p.kisa,p.ad,pr.kad
 from oyun.parti_aday_tanitim a
 join oyun.partiler p on p.id=a.parti_id
 join oyun.adaylar ad on ad.id=a.aday_id
 join oyun.profiller pr on pr.id=ad.user_id
 where a.kitle='herkes' and a.zaman>=t-interval '21 days'
 loop
  ttl:=e.kisa||' adayını kamuoyuna tanıttı: '||e.kad;
  summary:=e.ad||', adaylık sürecindeki '||e.kad||' için tanıtım duyurusu yayımladı.';
  article:=summary||E'\n\n'||'Partinin açıklaması:'||E'\n'||e.metin||
      E'\n\n'||'Bu metin ilgili partinin kendi tanıtım duyurusudur.';
  perform oyun.ajans_yayinla('aday_tanitim:'||e.id,'adaylar',ttl,summary,article,70,e.parti_id,null,e.zaman);
 end loop;

 -- Ekonomi: yüksek tutarlı bagislar kamuya acik parti kasa hareketlerinden.
 -- Her bagisi paylasmak yerine asgari ucretin 5 kati ustu haberlestirilir.
 for e in
 select h.id,h.parti_id,h.zaman,h.tutar,h.aciklama,p.kisa
 from oyun.parti_hareket h join oyun.partiler p on p.id=h.parti_id
 where h.tur='bagis' and h.tutar>=5*(select asgari from oyun.ulke where id=1)
 and h.zaman>=t-interval '21 days'
 loop
  ttl:=e.kisa||' kasasına önemli bağış: '||oyun.tl(e.tutar)||' ₺';
  summary:='Partinin mali kayıtlarında '||oyun.tl(e.tutar)||' ₺ bağış işlendi.';
  article:=summary||E'\n\n'||e.aciklama||
   E'\n\n'||'Bu tutar parti kasasına geçen oyun içi paradır.';
  perform oyun.ajans_yayinla('parti_bagis:'||e.id,'ekonomi',ttl,summary,article,68,e.parti_id,null,e.zaman);
 end loop;

 -- Secim sonuclari: kanitlanan resmî sonuc aciklamasi; sonucu olmayan secimi haber yapma.
 for e in
 select id,tur,donem,sonuc_at,sonuc from oyun.secimler
 where sonuc is not null and durum<>'bekliyor' and sonuc_at>=t-interval '21 days'
 loop
  ttl:=case e.tur when 'cb' then 'Cumhurbaşkanlığı' when 'mv' then 'Genel'
      when 'bel' then 'Belediye' else 'Ön' end||' seçiminin sonuçları açıklandı';
  summary:=e.donem||' dönemi için resmî seçim sonuçları yayımlandı.';
  article:=summary||E'\n\n'||'Ayrıntılı aday ve oy sonuçları için oyunun Seçimler bölümündeki sonuç ekranına bakın.';
  perform oyun.ajans_yayinla('secim_sonuc:'||e.id,'secim',ttl,summary,article,98,null,null,e.sonuc_at);
 end loop;

 select count(*)-v_before into v_count from oyun.ajans_haberleri;
 return jsonb_build_object('tamam',true,'yeni_haber',v_count,
   'toplam',(select count(*) from oyun.ajans_haberleri));
end $function$
;

delete from oyun.ajans_haberleri h
using oyun.olaylar o
where h.kaynak_anahtar='olay:'||o.id
  and o.metin ilike '%beyannamesini açıkladı%'
  and exists(select 1 from oyun.parti_beyanname b
     where b.parti_id=o.parti_id and b.zaman>=o.zaman-interval '2 days');


-- ---- 20261008_serbest_bagis_bagli_hesap_duzeltme ----
-- Oyuncudan oyuncuya bağış: bağlı hesaplar scalar UUID döndürür.
CREATE OR REPLACE FUNCTION public.serbest_bagis(p_tur text, p_id text, p_tutar numeric, p_aciklama text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid(); p oyun.profiller; t timestamptz:=oyun.simdi();
 m numeric; tid bigint; v_id bigint; v_uuid uuid; hedef text;
 note text:=btrim(coalesce(p_aciklama,'')); c oyun.cuzdan; v_min numeric;
begin
 if u is null then raise exception 'Oturum açmalısın';end if;
 if p_tutar is null or p_tutar::text !~ '^[0-9]+(\.[0-9]+)?$'
   or p_tutar<>trunc(p_tutar) or p_tutar<1 then
   raise exception 'Bağış tutarı en az 1 TL, pozitif tam sayı olmalı';end if;
 m:=p_tutar;
 if length(note)>150 then raise exception 'Bağış notu en fazla 150 karakter';end if;
 select * into p from oyun.profiller where id=u;
 if not found or p.yasakli then raise exception 'Hesabın bağış yapmaya uygun değil';end if;
 perform oyun.takip_engel(u,'bağış yapamazsın');
 if p_tur not in ('oyuncu','parti','sirket','gazete','il','devlet') then raise exception 'Geçersiz bağış hedefi';end if;
 -- Para transferinin alıcısı bulunmadan göndericiden tahsilat yapılmaz.
 if p_tur='oyuncu' then
   select id,kad into v_uuid,hedef from oyun.profiller
    where lower(kad)=lower(btrim(coalesce(p_id,''))) and not yasakli limit 1;
   if v_uuid is null then raise exception 'Alıcı oyuncu bulunamadı';end if;
   if v_uuid=u then raise exception 'Kendine bağış yapamazsın';end if;
   if exists(select 1 from oyun.ayarlar where id=1 and coklu_kontrol)
     and exists(select 1 from oyun.bagli_hesaplar(u) b where b=v_uuid) then
      raise exception 'Aynı cihazdaki bağlı hesaplara bağış yapılamaz';end if;
   if oyun.engelli(v_uuid,u) then raise exception 'Bu oyuncu seni engelledi';end if;
 elsif p_tur in ('parti','sirket','gazete','il') then
   if p_id is null or p_id !~ '^[0-9]{1,15}$' then raise exception 'Geçerli hedef numarası gir';end if;
   v_id:=p_id::bigint;
   if p_tur='parti' then
     select ad into hedef from oyun.partiler where id=v_id and not kapali;
   elsif p_tur='sirket' then
     select ad into hedef from oyun.sirketler where id=v_id and aktif;
   elsif p_tur='gazete' then
     select ad into hedef from oyun.oyuncu_gazeteleri where id=v_id and aktif;
   else
     select ad into hedef from oyun.iller where id=v_id;
   end if;
   if hedef is null then raise exception 'Bağış yapılacak kurum bulunamadı';end if;
 else
   hedef:='Türkiye Cumhuriyeti Hazinesi';
 end if;
 -- Gonderenin bakiyesi oyun.para_islem tarafindan atomik ve kilitli UPDATE ile kontrol edilir.
 perform oyun.para_islem(u,-m,'bagis',left(hedef||' için bağış'||case when note<>'' then ': '||note else '' end,170),t);
 if p_tur='oyuncu' then
   perform oyun.para_islem(v_uuid,m,'bagis',left(p.kad||' tarafından bağış'||case when note<>'' then ': '||note else '' end,170),t);
   perform oyun.bildir(v_uuid,format('%s sana %s ₺ bağışladı.',p.kad,oyun.tl(m)),t);
 elsif p_tur='parti' then
   update oyun.partiler set kasa=kasa+m where id=v_id;
   insert into oyun.parti_hareket(parti_id,zaman,tutar,aciklama,tur)
     values(v_id,t,m,format('%s bağış yaptı',p.kad),'bagis');
 elsif p_tur='sirket' then
   update oyun.sirketler set kasa=kasa+m where id=v_id;
   insert into oyun.sirket_hareket(sirket_id,zaman,tutar,aciklama)
     values(v_id,t,m,p.kad||' oyuncusundan sermaye niteliğinde olmayan karşılıksız bağış');
 elsif p_tur='gazete' then
   update oyun.oyuncu_gazeteleri set kasa=kasa+m where id=v_id;
   insert into oyun.gazete_hareket(gazete_id,zaman,tutar,tur,aciklama)
     values(v_id,t,m,'bagis',p.kad||' bağış yaptı');
 elsif p_tur='il' then
   select asgari into v_min from oyun.ulke where id=1;
   update oyun.il_durum set kasa=kasa+m,gelisim=least(100,gelisim+0.005*m/greatest(1,v_min)) where il_id=v_id;
   insert into oyun.il_bagis_kayit(il_id,user_id,tutar,zaman) values(v_id::smallint,u,m,t);
 else
   update oyun.ulke set hazine=hazine+m where id=1;
 end if;
 insert into oyun.serbest_bagis_kayit(gonderen,alici_tur,alici_id,alici_adi,tutar,aciklama,zaman)
 values(u,p_tur,case when p_tur='oyuncu' then v_uuid::text when p_tur='devlet' then '1' else v_id::text end,hedef,m,nullif(note,''),t)
 returning id into tid;
 -- Kıdem kazanımı para miktarıyla sonsuz ölçeklenmez: bağıştan en fazla günlük 1 puan.
 select * into c from oyun.cuzdan where user_id=u for update;
 select asgari into v_min from oyun.ulke where id=1;
 update oyun.cuzdan
 set kidem=kidem+greatest(0,
   least(1,(coalesce(c.bagis_bugun,0)+m)/greatest(1,v_min))
    -least(1,coalesce(c.bagis_bugun,0)/greatest(1,v_min))),
   bagis_bugun=coalesce(bagis_bugun,0)+m where user_id=u;
 return jsonb_build_object('tamam',true,'id',tid,'gonderen',p.kad,
  'hedef',hedef,'hedef_tur',p_tur,'tutar',m,
  'kalan', (select para from oyun.cuzdan where user_id=u));
end $function$
;
-- =====================================================================
--  SEÇİM SİMÜLASYONU ONLINE — 39) OYUNCU DENEYİMİ GÜNCELLEMESİ (2026-10-09)
--  Oyunu sıfırlamaz; yalnızca ekler. Tekrar çalıştırılabilir.
--   1. Yeni oyuncu: ilk il seçiminde kütük beklemesi yok, varsayılan kıdem şartı 3
--   2. Meclis oyuncu sayısına göre ölçeklenir (anayasadaki sayı üst sınırdır)
--   3. Sandık 08:00–22:00, sonuç 22:30; aday adaylığı başvuruları 3 gün
--   4. Oyuncuya / şirkete / gazeteye para hediyesi, havaleyle ortak günlük sınıra tabi
--   5. İlk adımlar listesi, Cumhuriyet tarihi arşivi
--   6. Kumbara 16 saat, seri kaçırılınca sıfırlanmaz
--   7. Görev ihmali: 3 gün girmeyen bakan/GBY, 7 gün girmeyen CB/GB/belediye başkanı görevden düşer
--   8. Parti kimliği (ekonomi/toplum ekseni + slogan), oyuncu avatarı ve biyografisi
--   9. Seçim mitingleri
-- =====================================================================

-- ---------- Ayarlar ----------
alter table oyun.ayarlar alter column oy_min_kidem set default 3;
alter table oyun.ayarlar add column if not exists meclis_olcek     numeric  not null default 0.25;  -- aktif oyuncu başına sandalye (0: kapalı)
alter table oyun.ayarlar add column if not exists ihmal_gun_atama  smallint not null default 3;     -- bakan / GBY (0: kapalı)
alter table oyun.ayarlar add column if not exists ihmal_gun_secim  smallint not null default 7;     -- CB / GB / belediye başkanı (0: kapalı)

-- ---------- Yeni tablolar ----------
create table if not exists oyun.meclis_olcek_kayit(
  secim_id bigint primary key references oyun.secimler(id),
  aktif    int not null,
  sandalye int not null,
  anayasal int not null,
  zaman    timestamptz not null default now()
);
create table if not exists oyun.ihmal_uyari(
  user_id uuid not null references oyun.profiller(id) on delete cascade,
  tur     text not null,
  zaman   timestamptz not null,
  primary key (user_id, tur)
);
create table if not exists oyun.oyuncu_kimlik(
  user_id   uuid primary key references oyun.profiller(id) on delete cascade,
  avatar    text check (avatar ~ '^[0-9]{1,2}(-[0-9]{1,2}){5}$'),
  biyografi text check (length(biyografi) <= 160),
  guncelleme timestamptz not null default now()
);
create table if not exists oyun.parti_kimlik(
  parti_id  bigint primary key references oyun.partiler(id) on delete cascade,
  eko       smallint not null default 0 check (eko between -5 and 5),      -- -5 devletçi … +5 serbest piyasa
  toplum    smallint not null default 0 check (toplum between -5 and 5),   -- -5 özgürlükçü … +5 muhafazakâr
  slogan    text check (length(slogan) <= 80),
  guncelleme timestamptz not null default now()
);
create table if not exists oyun.mitingler(
  id        bigint generated always as identity primary key,
  user_id   uuid not null references oyun.profiller(id) on delete cascade,
  secim_id  bigint not null references oyun.secimler(id),
  il_id     smallint not null references oyun.iller(id),
  parti_id  bigint references oyun.partiler(id),
  baslik    text not null check (length(baslik) between 3 and 80),
  bas       timestamptz not null,
  bit       timestamptz not null,
  bedel     numeric not null default 0,
  duyuruldu boolean not null default false,
  sonuc_yazildi boolean not null default false,
  olusturma timestamptz not null default now(),
  unique (user_id, secim_id)
);
create index if not exists mitingler_bas on oyun.mitingler(bas);
create index if not exists mitingler_il on oyun.mitingler(il_id, bas);
create table if not exists oyun.miting_katilim(
  miting_id bigint not null references oyun.mitingler(id) on delete cascade,
  user_id   uuid not null references oyun.profiller(id) on delete cascade,
  zaman     timestamptz not null default now(),
  primary key (miting_id, user_id)
);
do $$ declare t text; begin
  foreach t in array array['meclis_olcek_kayit','ihmal_uyari','oyuncu_kimlik','parti_kimlik','mitingler','miting_katilim'] loop
    execute format('alter table oyun.%I enable row level security', t);
    execute format('revoke all on oyun.%I from public, anon, authenticated', t);
  end loop;
end $$;

-- Takvim: sandık 08:00–22:00, sonuç 22:30; belediye başvurusu 4–6, vekil başvurusu 24–26, CB ön seçim başvurusu 26–27
CREATE OR REPLACE FUNCTION oyun.donem_olustur(p_ay date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m date:=date_trunc('month',p_ay)::date; n date:=(date_trunc('month',p_ay)+interval '1 month')::date;
  dm text:=to_char(m,'YYYY-MM'); dn text:=to_char(n,'YYYY-MM'); b timestamptz:=(select baslangic from oyun.ayarlar where id=1);
begin
  if oyun.tr_an(m+3,0)>=b then
    insert into oyun.secimler(tur,donem,basvuru_bas,basvuru_bit,oy_bas,oy_bit,sonuc_at,goreve_bas) values
      ('bel_on',dm,oyun.tr_an(m+3,0),oyun.tr_an(m+6,0),oyun.tr_an(m+7,8),oyun.tr_an(m+7,22),oyun.tr_an(m+7,22,30),null),
      ('bel',dm,null,null,oyun.tr_an(m+9,8),oyun.tr_an(m+9,22),oyun.tr_an(m+9,22,30),oyun.tr_an(m+10,0))
    on conflict(tur,donem) do nothing;
  end if;
  if oyun.tr_an(m+14,0)>=b then
    insert into oyun.secimler(tur,donem,basvuru_bas,basvuru_bit,oy_bas,oy_bit,sonuc_at,goreve_bas) values
      ('kurultay',dm,oyun.tr_an(m+14,0),oyun.tr_an(m+17,0),oyun.tr_an(m+17,8),oyun.tr_an(m+17,22),oyun.tr_an(m+17,22,30),oyun.tr_an(m+18,0))
    on conflict(tur,donem) do nothing;
  end if;
  if oyun.tr_an(m+23,0)>=b then
    insert into oyun.secimler(tur,donem,basvuru_bas,basvuru_bit,oy_bas,oy_bit,sonuc_at,goreve_bas) values
      ('mv_on',dn,oyun.tr_an(m+23,0),oyun.tr_an(m+26,0),oyun.tr_an(m+27,8),oyun.tr_an(m+27,22),oyun.tr_an(m+27,22,30),null),
      ('mv',dn,null,null,oyun.tr_an(n,8),oyun.tr_an(n,22),oyun.tr_an(n,22,30),oyun.tr_an(n+1,0))
    on conflict(tur,donem) do nothing;
    if oyun.cb_secim_gerekli(oyun.tr_an(n,8)) then
      insert into oyun.secimler(tur,donem,basvuru_bas,basvuru_bit,oy_bas,oy_bit,sonuc_at,goreve_bas) values
        ('cb',dn,oyun.tr_an(m+18,0),oyun.tr_an(m+25,0),oyun.tr_an(n,8),oyun.tr_an(n,22),oyun.tr_an(n,22,30),oyun.tr_an(n+1,0)),
        ('cb_on',dn,oyun.tr_an(m+25,0),oyun.tr_an(m+27,0),oyun.tr_an(m+27,8),oyun.tr_an(m+27,22),oyun.tr_an(m+27,22,30),null)
      on conflict(tur,donem) do nothing;
    end if;
  end if;
end $function$;

-- CB 2. turu: aynı saatler
CREATE OR REPLACE FUNCTION oyun._sonuc_cb(s oyun.secimler)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare
  toplam bigint;
  n int;
  birinci record;
  ikinci record;
  t2 oyun.secimler;
  gun date := (s.oy_bas at time zone 'Europe/Istanbul')::date;
  adaylar_j jsonb;
begin
  perform oyun.aday_oylarini_say(s.id);

  select count(*) into toplam
  from oyun.oylar
  where secim_id = s.id;

  select count(*) into n
  from oyun.adaylar
  where secim_id = s.id;

  select coalesce(
    jsonb_agg(
      oyun.aday_json(a.id)
      order by a.oy desc, a.basvuru_at
    ),
    '[]'::jsonb
  )
  into adaylar_j
  from oyun.adaylar a
  where a.secim_id = s.id;

  if n = 0 then
    perform oyun.olay(
      'secim',
      'Cumhurbaşkanlığı seçiminde aday yoktu; makam boş kalacak.',
      null, null, s.sonuc_at
    );

    return jsonb_build_object(
      'toplam', toplam,
      'adaylar', adaylar_j,
      'ikinci_tur', false
    );
  end if;

  select * into birinci
  from oyun.adaylar
  where secim_id = s.id
  order by oy desc, basvuru_at, id
  limit 1;

  if n = 1 or (toplam > 0 and birinci.oy * 2 > toplam) then
    insert into oyun.kazananlar
    values (s.id, birinci.user_id, null, birinci.parti_id)
    on conflict do nothing;

    perform oyun.olay(
      'secim',
      format(
        'Cumhurbaşkanı ilk turda seçildi: %s (%%%s).',
        (select kad from oyun.profiller where id = birinci.user_id),
        case
          when toplam > 0 then round(birinci.oy * 100.0 / toplam,1)
          else 100
        end
      ),
      null, birinci.parti_id, s.sonuc_at
    );

    return jsonb_build_object(
      'toplam', toplam,
      'adaylar', adaylar_j,
      'ikinci_tur', false,
      'kazanan', oyun.aday_json(birinci.id)
    );
  end if;

  select * into ikinci
  from oyun.adaylar
  where secim_id = s.id
    and id <> birinci.id
  order by oy desc, basvuru_at, id
  limit 1;

  insert into oyun.secimler(
    tur, donem, oy_bas, oy_bit, sonuc_at, goreve_bas,
    ara, ara_neden
  )
  values (
    'cb2',
    s.donem,
    oyun.tr_an(gun+1,8),
    oyun.tr_an(gun+1,22),
    oyun.tr_an(gun+1,22,30),
    oyun.tr_an(gun+2,0),
    s.ara,
    s.ara_neden
  )
  on conflict(tur,donem) do nothing
  returning * into t2;

  if t2.id is not null then
    insert into oyun.adaylar(
      secim_id,user_id,parti_id,il_id,basvuru_at,vaat
    )
    values
      (
        t2.id,birinci.user_id,birinci.parti_id,null,
        birinci.basvuru_at,birinci.vaat
      ),
      (
        t2.id,ikinci.user_id,ikinci.parti_id,null,
        ikinci.basvuru_at,ikinci.vaat
      );
  end if;

  perform oyun.olay(
    'secim',
    format(
      'Cumhurbaşkanlığı seçimi ikinci tura kaldı: %s ve %s yarın sandıkta.',
      (select kad from oyun.profiller where id = birinci.user_id),
      (select kad from oyun.profiller where id = ikinci.user_id)
    ),
    null, null, s.sonuc_at
  );

  return jsonb_build_object(
    'toplam', toplam,
    'adaylar', adaylar_j,
    'ikinci_tur', true
  );
end $function$;

-- Erken seçim: aynı saatler
CREATE OR REPLACE FUNCTION oyun.erken_genel_secim_olustur(t timestamp with time zone, p_teklif bigint)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ilk date; ongun date; secgun date; dm text; eski text;
begin
  ilk:=(t at time zone 'Europe/Istanbul')::date;
  if oyun.tr_an(ilk,8)<t+interval '8 hours' then ilk:=ilk+1; end if;
  ongun:=ilk; secgun:=ilk+1;
  dm:='erken-genel-'||p_teklif||'-'||to_char(t at time zone 'Europe/Istanbul','YYYYMMDDHH24MISS');
  select donem into eski from oyun.secimler where tur='mv' and not ara and durum='bekliyor' and oy_bas>t order by oy_bas limit 1;
  if eski is not null then
    update oyun.secimler set durum='tamam',sonuc=coalesce(sonuc,'{}'::jsonb)||jsonb_build_object('iptal','erken_secim')
    where donem=eski and durum='bekliyor' and tur in ('mv_on','mv','cb_on','cb','cb2');
  end if;
  insert into oyun.secimler(tur,donem,basvuru_bas,basvuru_bit,oy_bas,oy_bit,sonuc_at,goreve_bas,ara,ara_neden) values
   ('mv_on',dm,t,oyun.tr_an(ongun,8),oyun.tr_an(ongun,8),oyun.tr_an(ongun,22),oyun.tr_an(ongun,22,30),null,true,'erken_secim'),
   ('mv',dm,null,null,oyun.tr_an(secgun,8),oyun.tr_an(secgun,22),oyun.tr_an(secgun,22,30),oyun.tr_an(secgun+1,0),true,'erken_secim');
  if oyun.hukumet_sistemi()=0 then
    insert into oyun.secimler(tur,donem,basvuru_bas,basvuru_bit,oy_bas,oy_bit,sonuc_at,goreve_bas,ara,ara_neden) values
     ('cb_on',dm,t,oyun.tr_an(ongun,8),oyun.tr_an(ongun,8),oyun.tr_an(ongun,22),oyun.tr_an(ongun,22,30),null,true,'erken_secim'),
     ('cb',dm,t,oyun.tr_an(ongun,8),oyun.tr_an(secgun,8),oyun.tr_an(secgun,22),oyun.tr_an(secgun,22,30),oyun.tr_an(secgun+1,0),true,'erken_secim');
  end if;
  perform oyun.olay('secim',format('TBMM erken seçim kararı aldı. Erken genel seçim %s günü yapılacak.',to_char(secgun,'DD.MM.YYYY')),null,null,t);
  return dm;
end $function$;

-- Ara seçimler: aynı saatler; göreve başlama 23:00
CREATE OR REPLACE FUNCTION oyun.ara_secim_olustur(p_tur text, p_parti bigint, p_il smallint, t timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  ilk_gun date;
  ikinci_gun date;
  o oyun.secimler;
  dm text;
  on_id bigint;
  asil_id bigint;
  asil_bas timestamptz;
begin
  if p_tur not in ('gb','cb','bel') then
    raise exception 'Geçersiz ara seçim türü.';
  end if;

  -- En yakın makul pencere: adaylık süresi en az yaklaşık 8 saat olsun.
  ilk_gun := (t at time zone 'Europe/Istanbul')::date;
  if oyun.tr_an(ilk_gun, 8) < t + interval '8 hours' then
    ilk_gun := ilk_gun + 1;
  end if;
  ikinci_gun := ilk_gun + 1;

  if p_tur = 'gb' then
    if p_parti is null then
      raise exception 'Genel başkan ara seçimi için parti gerekli.';
    end if;

    select * into o
    from oyun.secimler
    where tur = 'kurultay'
      and ara
      and hedef_parti_id = p_parti
      and durum <> 'tamam'
      and coalesce(goreve_bas, sonuc_at) > t
    order by coalesce(goreve_bas, sonuc_at)
    limit 1;

    if o.id is not null then
      return jsonb_build_object(
        'secim_id', o.id, 'tur', 'kurultay', 'ara', true, 'mevcut', true,
        'oy_bas', o.oy_bas, 'goreve_bas', o.goreve_bas
      );
    end if;

    asil_bas := oyun.tr_an(ilk_gun, 23);

    -- Zaten bundan daha erken bitecek olağan kurultay varsa ikinci seçim yaratma.
    select * into o
    from oyun.secimler
    where tur = 'kurultay'
      and not ara
      and durum <> 'tamam'
      and goreve_bas > t
    order by goreve_bas
    limit 1;

    if o.id is not null and o.goreve_bas <= asil_bas then
      return jsonb_build_object(
        'secim_id', o.id, 'tur', 'kurultay', 'ara', false, 'mevcut', true,
        'oy_bas', o.oy_bas, 'goreve_bas', o.goreve_bas
      );
    end if;

    dm := 'ara-gb-' || p_parti || '-' ||
          to_char(t at time zone 'Europe/Istanbul','YYYYMMDDHH24MISS');

    insert into oyun.secimler(
      tur, donem, basvuru_bas, basvuru_bit, oy_bas, oy_bit, sonuc_at, goreve_bas,
      ara, hedef_parti_id, ara_neden
    ) values (
      'kurultay', dm,
      t, oyun.tr_an(ilk_gun,8),
      oyun.tr_an(ilk_gun,8), oyun.tr_an(ilk_gun,22),
      oyun.tr_an(ilk_gun,22,30), asil_bas,
      true, p_parti, 'genel_baskan_istifa'
    )
    returning id into asil_id;

    return jsonb_build_object(
      'secim_id', asil_id, 'tur', 'kurultay', 'ara', true, 'mevcut', false,
      'oy_bas', oyun.tr_an(ilk_gun,8), 'goreve_bas', asil_bas
    );

  elsif p_tur = 'bel' then
    if p_il is null then
      raise exception 'Belediye ara seçimi için il gerekli.';
    end if;

    select * into o
    from oyun.secimler
    where tur = 'bel'
      and ara
      and hedef_il_id = p_il
      and durum <> 'tamam'
      and coalesce(goreve_bas, sonuc_at) > t
    order by coalesce(goreve_bas, sonuc_at)
    limit 1;

    if o.id is not null then
      return jsonb_build_object(
        'secim_id', o.id, 'tur', 'bel', 'ara', true, 'mevcut', true,
        'oy_bas', o.oy_bas, 'goreve_bas', o.goreve_bas
      );
    end if;

    asil_bas := oyun.tr_an(ikinci_gun, 23);

    -- Yaklaşan olağan belediye seçimi daha erken başkan çıkaracaksa onu kullan.
    select * into o
    from oyun.secimler
    where tur = 'bel'
      and not ara
      and durum <> 'tamam'
      and goreve_bas > t
    order by goreve_bas
    limit 1;

    if o.id is not null and o.goreve_bas <= asil_bas then
      return jsonb_build_object(
        'secim_id', o.id, 'tur', 'bel', 'ara', false, 'mevcut', true,
        'oy_bas', o.oy_bas, 'goreve_bas', o.goreve_bas
      );
    end if;

    dm := 'ara-bel-' || p_il || '-' ||
          to_char(t at time zone 'Europe/Istanbul','YYYYMMDDHH24MISS');

    insert into oyun.secimler(
      tur, donem, basvuru_bas, basvuru_bit, oy_bas, oy_bit, sonuc_at, goreve_bas,
      ara, hedef_il_id, ara_neden
    ) values (
      'bel_on', dm,
      t, oyun.tr_an(ilk_gun,8),
      oyun.tr_an(ilk_gun,8), oyun.tr_an(ilk_gun,22),
      oyun.tr_an(ilk_gun,22,30), null,
      true, p_il, 'belediye_baskani_istifa'
    )
    returning id into on_id;

    insert into oyun.secimler(
      tur, donem, basvuru_bas, basvuru_bit, oy_bas, oy_bit, sonuc_at, goreve_bas,
      ara, hedef_il_id, ara_neden
    ) values (
      'bel', dm,
      null, null,
      oyun.tr_an(ikinci_gun,8), oyun.tr_an(ikinci_gun,22),
      oyun.tr_an(ikinci_gun,22,30), asil_bas,
      true, p_il, 'belediye_baskani_istifa'
    )
    returning id into asil_id;

    return jsonb_build_object(
      'secim_id', asil_id, 'on_secim_id', on_id,
      'tur', 'bel', 'ara', true, 'mevcut', false,
      'oy_bas', oyun.tr_an(ikinci_gun,8), 'goreve_bas', asil_bas
    );

  else
    select * into o
    from oyun.secimler
    where tur in ('cb','cb2')
      and ara
      and durum <> 'tamam'
      and coalesce(goreve_bas, sonuc_at) > t
    order by coalesce(goreve_bas, sonuc_at)
    limit 1;

    if o.id is not null then
      return jsonb_build_object(
        'secim_id', o.id, 'tur', o.tur, 'ara', true, 'mevcut', true,
        'oy_bas', o.oy_bas, 'goreve_bas', o.goreve_bas
      );
    end if;

    asil_bas := oyun.tr_an(ikinci_gun, 23);

    -- Yaklaşan olağan CB seçimi daha erken sonuç verecekse onu kullan.
    select * into o
    from oyun.secimler
    where tur in ('cb','cb2')
      and not ara
      and durum <> 'tamam'
      and goreve_bas > t
    order by goreve_bas
    limit 1;

    if o.id is not null and o.goreve_bas <= asil_bas then
      return jsonb_build_object(
        'secim_id', o.id, 'tur', o.tur, 'ara', false, 'mevcut', true,
        'oy_bas', o.oy_bas, 'goreve_bas', o.goreve_bas
      );
    end if;

    dm := 'ara-cb-' ||
          to_char(t at time zone 'Europe/Istanbul','YYYYMMDDHH24MISS');

    insert into oyun.secimler(
      tur, donem, basvuru_bas, basvuru_bit, oy_bas, oy_bit, sonuc_at, goreve_bas,
      ara, ara_neden
    ) values (
      'cb_on', dm,
      t, oyun.tr_an(ilk_gun,8),
      oyun.tr_an(ilk_gun,8), oyun.tr_an(ilk_gun,22),
      oyun.tr_an(ilk_gun,22,30), null,
      true, 'cumhurbaskani_istifa'
    )
    returning id into on_id;

    insert into oyun.secimler(
      tur, donem, basvuru_bas, basvuru_bit, oy_bas, oy_bit, sonuc_at, goreve_bas,
      ara, ara_neden
    ) values (
      'cb', dm,
      t, oyun.tr_an(ilk_gun,8),
      oyun.tr_an(ikinci_gun,8), oyun.tr_an(ikinci_gun,22),
      oyun.tr_an(ikinci_gun,22,30), asil_bas,
      true, 'cumhurbaskani_istifa'
    )
    returning id into asil_id;

    return jsonb_build_object(
      'secim_id', asil_id, 'on_secim_id', on_id,
      'tur', 'cb', 'ara', true, 'mevcut', false,
      'oy_bas', oyun.tr_an(ikinci_gun,8), 'goreve_bas', asil_bas
    );
  end if;
end $function$;

-- İl değiştirme kilidi metni
CREATE OR REPLACE FUNCTION oyun.il_kilit_nedeni(t timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case s.tur when 'mv_on' then 'Genel seçim dönemi (24''ünden ayın 2''sine kadar) il değiştirilemez.'
                    else 'Belediye seçim dönemi (4''ünden 11''ine kadar) il değiştirilemez.' end
  from oyun.secimler s join oyun.secimler g on g.donem = s.donem and g.tur = case s.tur when 'mv_on' then 'mv' else 'bel' end
  where s.tur in ('mv_on','bel_on') and t >= s.basvuru_bas and t < g.goreve_bas
  limit 1
$function$;

-- Push hatırlatma metinleri
CREATE OR REPLACE FUNCTION oyun.push_hatirlatmalar(t timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare
  s oyun.secimler;
  pid bigint;
  v jsonb;
  kosul text;
begin
  if not oyun.push_acik() then return; end if;

  -- Başvuru açılışları
  for s in
    select *
    from oyun.secimler
    where durum = 'bekliyor'
      and basvuru_bas is not null
      and t >= basvuru_bas
      and t < basvuru_bit
      and tur in ('bel_on','mv_on','kurultay')
      and not (hatirlatma ? 'basvuru')
  loop
    v := jsonb_build_object('ekran','gundem');

    if s.ara and s.tur = 'bel_on' and s.hedef_il_id is not null then
      perform oyun.push_konuya(
        's_il_' || s.hedef_il_id,
        null,
        'Olağanüstü belediye seçimi',
        format('%s için belediye başkanlığı aday adaylığı başvuruları açıldı.',
               (select ad from oyun.iller where id = s.hedef_il_id)),
        v
      );
    elsif s.ara and s.tur = 'kurultay' and s.hedef_parti_id is not null then
      perform oyun.push_konuya(
        's_parti_' || s.hedef_parti_id,
        null,
        'Olağanüstü kurultay',
        'Genel başkan istifası sonrası adaylık başvuruları açıldı.',
        v
      );
    else
      perform oyun.push_konuya(
        's_tum',
        null,
        'Başvurular açıldı',
        case s.tur
          when 'bel_on' then 'Belediye başkanlığı aday adaylığı başvuruları açıldı (3 gün). Adayını çıkar!'
          when 'mv_on' then 'Milletvekili aday adaylığı başvuruları açıldı (3 gün). Listeye girmek için başvur!'
          else 'Genel başkanlık başvuruları açıldı. Kurultay ayın 18''inde.'
        end,
        v
      );
    end if;

    update oyun.secimler
    set hatirlatma = hatirlatma || '{"basvuru":true}'
    where id = s.id;
  end loop;

  -- Sandık açılışları
  for s in
    select *
    from oyun.secimler
    where durum = 'bekliyor'
      and t >= oy_bas
      and t < oy_bit
      and not (hatirlatma ? 'oy')
  loop
    v := jsonb_build_object('ekran','secim','id',s.id);

    if s.tur = 'mv' then
      perform oyun.push_konuya(
        's_tum', null,
        'Bugün seçim var! 🗳️',
        'Genel seçim ve cumhurbaşkanlığı seçimi sandıkları 22:00''ye kadar açık.',
        v
      );

    elsif s.tur in ('cb','cb2') then
      perform oyun.push_konuya(
        's_tum', null,
        case when s.tur = 'cb2' then 'Cumhurbaşkanlığı 2. turu'
             when s.ara then 'Olağanüstü cumhurbaşkanlığı seçimi'
             else 'Cumhurbaşkanlığı seçimi' end,
        'Sandıklar 22:00''de kapanıyor. Oyunu kullanmayı unutma!',
        v
      );

    elsif s.tur = 'bel' then
      if s.ara and s.hedef_il_id is not null then
        perform oyun.push_konuya(
          's_il_' || s.hedef_il_id,
          null,
          'Olağanüstü belediye seçimi 🗳️',
          format('%s belediye başkanlığı sandığı 22:00''ye kadar açık.',
                 (select ad from oyun.iller where id = s.hedef_il_id)),
          v
        );
      else
        perform oyun.push_konuya(
          's_tum', null,
          'Bugün belediye seçimi var! 🗳️',
          'İl belediye başkanlığı sandıkları 22:00''ye kadar açık.',
          v
        );
      end if;

    elsif s.tur in ('bel_on','mv_on','kurultay','cb_on') then
      if s.ara and s.tur = 'kurultay' and s.hedef_parti_id is not null then
        perform oyun.push_konuya(
          's_parti_' || s.hedef_parti_id,
          null,
          'Olağanüstü kurultay başladı',
          'Yeni genel başkanı seçmek için oyunu 22:00''ye kadar kullan.',
          v
        );
      elsif s.ara and s.tur = 'bel_on' and s.hedef_il_id is not null then
        for pid in
          select distinct parti_id
          from oyun.adaylar
          where secim_id = s.id and parti_id is not null
        loop
          kosul := format(
            '''s_parti_%s'' in topics && ''s_il_%s'' in topics',
            pid, s.hedef_il_id
          );
          perform oyun.push_konuya(
            's_tum',
            kosul,
            'Partinde olağanüstü ön seçim var',
            format('%s belediye başkanı ön seçimi 22:00''ye kadar.',
                   (select ad from oyun.iller where id = s.hedef_il_id)),
            v
          );
        end loop;
      else
        for pid in
          select distinct parti_id
          from oyun.adaylar
          where secim_id = s.id and parti_id is not null
        loop
          perform oyun.push_konuya(
            's_parti_' || pid,
            null,
            'Partinde seçim var',
            case s.tur
              when 'bel_on' then 'Belediye başkanı ön seçimi bugün 22:00''ye kadar.'
              when 'mv_on' then 'Milletvekili ön seçimi bugün 22:00''ye kadar. Liste sırasını sen belirle!'
              when 'cb_on' then 'Cumhurbaşkanı aday ön seçimi bugün 22:00''ye kadar.'
              else 'Kurultay bugün! Genel başkanını seç.'
            end,
            v
          );
        end loop;
      end if;
    end if;

    update oyun.secimler
    set hatirlatma = hatirlatma || '{"oy":true}'
    where id = s.id;
  end loop;

  -- Sonuçlar
  for s in
    select *
    from oyun.secimler
    where durum <> 'bekliyor'
      and tur in ('mv','bel','cb','cb2')
      and t >= sonuc_at
      and t < sonuc_at + interval '3 hours'
      and not (hatirlatma ? 'sonuc')
  loop
    if s.tur <> 'cb' then
      if s.ara and s.tur = 'bel' and s.hedef_il_id is not null then
        perform oyun.push_konuya(
          's_il_' || s.hedef_il_id,
          null,
          'Olağanüstü seçim sonucu',
          format('%s belediye başkanlığı seçiminin sonucu açıklandı.',
                 (select ad from oyun.iller where id = s.hedef_il_id)),
          jsonb_build_object('ekran','secim','id',s.id)
        );
      else
        perform oyun.push_konuya(
          's_tum',
          null,
          'Sonuçlar açıklandı',
          case s.tur
            when 'mv' then 'Genel seçim ve cumhurbaşkanlığı sonuçları açıklandı. Meclis''in yeni dağılımını gör!'
            when 'bel' then 'Belediye seçimi sonuçları açıklandı. İlini kim kazandı?'
            else 'Cumhurbaşkanlığı ikinci tur sonucu açıklandı.'
          end,
          jsonb_build_object('ekran','secim','id',s.id)
        );
      end if;
    end if;

    update oyun.secimler
    set hatirlatma = hatirlatma || '{"sonuc":true}'
    where id = s.id;
  end loop;

  perform oyun.kumbara_hatirlat(t);
end $function$;

-- Oy verme hata metni
CREATE OR REPLACE FUNCTION public.oy_ver(p_secim bigint, p_hedef bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare
  p oyun.profiller:=oyun.profilim();
  t timestamptz:=oyun.simdi();
  s oyun.secimler;
  a oyun.adaylar;
  e text;
  onsecim bigint;
begin
  select * into s from oyun.secimler where id=p_secim;
  if s.id is null then raise exception 'Seçim bulunamadı.'; end if;
  if s.durum<>'bekliyor' or t<s.oy_bas or t>=s.oy_bit then
    raise exception 'Sandık şu anda kapalı (oy saatleri 08:00–22:00).';
  end if;
  e:=oyun.oy_engeli(p,s);
  if e is not null then raise exception '%',e; end if;
  if exists(select 1 from oyun.oylar where secim_id=s.id and secmen=p.id) then
    raise exception 'Bu seçimde zaten oy kullandın.';
  end if;

  if s.tur='mv' then
    if p_hedef<0 then
      select * into a
      from oyun.adaylar
      where id=-p_hedef
        and secim_id=s.id
        and parti_id is null
        and il_id=p.il_id;
      if a.id is null then raise exception 'Bağımsız aday bulunamadı.'; end if;
      insert into oyun.oylar(secim_id,secmen,il_id,parti_id,aday_id,zaman)
      values(s.id,p.id,p.il_id,null,a.id,t);
    else
      select id into onsecim from oyun.secimler where tur='mv_on' and donem=s.donem;
      if not exists(
        select 1 from oyun.adaylar
        where secim_id=onsecim and il_id=p.il_id
          and parti_id=p_hedef and sira is not null
      ) then
        raise exception 'Bu partinin ilinde aday listesi yok.';
      end if;
      insert into oyun.oylar(secim_id,secmen,il_id,parti_id,zaman)
      values(s.id,p.id,p.il_id,p_hedef,t);
    end if;
  else
    select * into a from oyun.adaylar where id=p_hedef and secim_id=s.id;
    if a.id is null then raise exception 'Aday bulunamadı.'; end if;
    if s.tur in ('mv_on','bel_on')
       and (a.il_id<>p.il_id or a.parti_id<>p.parti_id) then
      raise exception 'Ön seçimde yalnızca kendi ilindeki kendi partinin adaylarına oy verebilirsin.';
    end if;
    if s.tur in ('kurultay','cb_on') and a.parti_id<>p.parti_id then
      raise exception 'Yalnızca kendi partinin seçiminde oy kullanabilirsin.';
    end if;
    if s.tur='bel' and a.il_id<>p.il_id then
      raise exception 'Yalnızca kendi ilinin belediye seçiminde oy kullanabilirsin.';
    end if;
    insert into oyun.oylar(secim_id,secmen,il_id,parti_id,aday_id,zaman)
    values(s.id,p.id,p.il_id,a.parti_id,a.id,t);
  end if;
  return public.durum();
end $function$;

-- Seçmen kütüğü yalnızca il değiştirenlere
CREATE OR REPLACE FUNCTION oyun.oy_engeli(p oyun.profiller, s oyun.secimler)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(
    oyun.uyari(p, s.oy_bas),

    case
      when s.ara
       and s.hedef_il_id is not null
       and p.il_id is distinct from s.hedef_il_id
      then format(
        'Bu olağanüstü seçim yalnızca %s ili içindir.',
        (select ad from oyun.iller where id = s.hedef_il_id)
      )
    end,

    case
      when s.ara
       and s.hedef_parti_id is not null
       and p.parti_id is distinct from s.hedef_parti_id
      then format(
        'Bu olağanüstü kurultay yalnızca %s üyeleri içindir.',
        (select kisa from oyun.partiler where id = s.hedef_parti_id)
      )
    end,

    case
      when s.tur in ('mv','bel','mv_on','bel_on')
       and p.son_il_degis is not null   -- ilk il seçimi kütük beklemesi gerektirmez (hesap yaşı şartı yeter)
       and p.il_at > s.oy_bas - make_interval(
         days => (select oy_il_gun from oyun.ayarlar where id = 1)
       )
      then format(
        'Seçmen kütüğü: bu ilde oy kullanabilmek için seçimden en az %s gün önce bu ile kayıtlı olmalısın.',
        (select oy_il_gun from oyun.ayarlar where id = 1)
      )
    end,

    case
      when s.tur in ('mv_on','bel_on','kurultay','cb_on') then
        case
          when p.parti_id is null
            then 'Bu parti içi seçimde oy için bir partiye üye olmalısın.'
          when p.parti_at > s.basvuru_bas
            then 'Parti içi seçimde oy için başvurular açılmadan önce üye olmuş olmalısın.'
        end
    end
  )
$function$;

-- Kıdem uyarısı metni
CREATE OR REPLACE FUNCTION oyun.uyari(p oyun.profiller, ref timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(
    case when p.olusturma > ref - make_interval(days => a.min_hesap_gun)
         then format('Hesabın en az %s günlük olmalı.', a.min_hesap_gun) end,
    case when a.eposta_zorunlu and not exists (select 1 from auth.users u where u.id = p.id and u.email_confirmed_at is not null)
         then 'E-posta adresini doğrulamalısın.' end,
    case when a.cihaz_zorunlu and not exists (select 1 from oyun.oturumlar o where o.user_id = p.id)
         then 'Cihaz doğrulaması gerekiyor: uygulamayı güncelleyip yeniden aç.' end,
    oyun.suphe(p.id),
    case when oyun.kidem_puani(p.id) < a.oy_min_kidem
         then format('En az %s kıdem puanın olmalı (şu an %s). Oyuna girdiğin her gün maaşını topla: +1 kıdem.', a.oy_min_kidem, oyun.kidem_puani(p.id)) end)
  from oyun.ayarlar a where a.id = 1
$function$;

-- Seçmen kartı şartları ekranı
CREATE OR REPLACE FUNCTION public.vatandaslik()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); a oyun.ayarlar; k numeric := oyun.kidem_puani(p.id);
begin
  select * into a from oyun.ayarlar where id = 1;
  return jsonb_build_object(
    'uygun', oyun.uyari(p, t) is null, 'engel', oyun.uyari(p, t),
    'sartlar', jsonb_build_array(
      jsonb_build_object('ad', format('Hesap en az %s günlük', a.min_hesap_gun), 'tamam', p.olusturma <= t - make_interval(days => a.min_hesap_gun),
                         'not', case when p.olusturma > t - make_interval(days => a.min_hesap_gun) then 'Tamamlanma: ' || to_char((p.olusturma + make_interval(days => a.min_hesap_gun)) at time zone 'Europe/Istanbul', 'DD.MM HH24:MI') end),
      jsonb_build_object('ad', 'E-posta doğrulanmış', 'tamam', not a.eposta_zorunlu or exists (select 1 from auth.users u where u.id = p.id and u.email_confirmed_at is not null)),
      jsonb_build_object('ad', 'Cihaz doğrulanmış', 'tamam', not a.cihaz_zorunlu or exists (select 1 from oyun.oturumlar o where o.user_id = p.id)),
      jsonb_build_object('ad', 'Tek hesap (bu cihazda önceden açılmış hesap yok ya da yönetici onaylı)', 'tamam', oyun.suphe(p.id) is null),
      jsonb_build_object('ad', format('En az %s kıdem puanı (her gün maaşını topla: +1)', a.oy_min_kidem), 'tamam', k >= a.oy_min_kidem, 'not', format('Kıdemin: %s', k)),
      jsonb_build_object('ad', format('Seçmen kütüğü: il değiştirdiysen yeni ilinde en az %s gün', a.oy_il_gun), 'tamam', p.son_il_degis is null or p.il_at <= t - make_interval(days => a.oy_il_gun),
                         'not', case when p.son_il_degis is not null and p.il_at > t - make_interval(days => a.oy_il_gun) then 'Bu ilde oy hakkı: ' || to_char((p.il_at + make_interval(days => a.oy_il_gun)) at time zone 'Europe/Istanbul', 'DD.MM') end)),
    'parti_kurma', jsonb_build_object('kidem', a.parti_kurucu_kidem, 'kurucu', a.parti_kurucu_sayi, 'gun', a.parti_kurulus_gun, 'benim_kidem', k,
                                      'ucret', oyun.parti_kur_ucreti(), 'para', (select para from oyun.cuzdanim(p.id))));
end $function$;

-- Seri: kaçırılan gün sıfırlamaz, bir basamak düşürür
CREATE OR REPLACE FUNCTION oyun.gelir_hesap(u uuid, t timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare p oyun.profiller; c oyun.cuzdan; ul oyun.ulke; st jsonb; ilc numeric; ub numeric; seri_y int; seri_b numeric;
        maas numeric; makam numeric; brut numeric; vergi numeric; kent numeric; gecim numeric; gecim_ind numeric; net numeric;
        saat numeric; v_hiz numeric := coalesce((select maas_hizi from oyun.ayarlar where id = 1), 1); bugun date := (t at time zone 'Europe/Istanbul')::date; destek numeric := 0; hem numeric := 0; asg_saat numeric; kv numeric;
begin
  select * into p from oyun.profiller where id = u;
  select * into c from oyun.cuzdan where user_id = u;
  select * into ul from oyun.ulke where id = 1;
  st := oyun.statu_json(u);
  ilc := oyun.il_carpan(p.il_id);
  ub := oyun.bonus(p.il_id, 'ucret', t) + case when (st ->> 'basamak')::int <= 1 then oyun.bonus(p.il_id, 'ucret_yeni', t) else 0 end;
  -- seri: bir sonraki (ya da bugünkü) toplamada geçerli olan seri
  seri_y := case when c.seri_gun = bugun then c.seri when c.seri_gun = bugun - 1 then c.seri + 1
                when c.seri_gun is null then 1
                else greatest(1, coalesce(c.seri, 1) - (bugun - c.seri_gun - 1)) end;   -- kaçırılan her gün bir basamak
  seri_b := least(oyun.duz('seri_tavan'), 5 * (seri_y - 1));
  asg_saat := ul.asgari / 720;
  maas := asg_saat * v_hiz * (st ->> 'carpan')::numeric * ilc * (1 + ub / 100);
  -- Meclis devamsızlık kesintisi (mevzuat): vekilin katılmadığı oylamalar oranında
  makam := coalesce((select sum(oyun.makam_maasi(m.tur, m.il_id) * case when m.tur = 'mv' then 1 - oyun.vekil_kesinti_orani(u, t) / 100 else 1 end)
                     from oyun.makamlar m where m.user_id = u and m.bit is null), 0) / 720;
  brut := (maas + makam) * (1 + seri_b / 100);
  vergi := greatest(0, brut - asg_saat) * ul.vergi / 100;                 -- asgari ücret gelir vergisinden muaftır
  kv := (select kent_vergisi from oyun.il_durum where il_id = p.il_id);
  kent := brut * kv / 100;
  gecim_ind := least(60, oyun.bonus(p.il_id, 'gecim', t));
  gecim := 350.0 / 24 * ul.endeks * (1 - gecim_ind / 100);
  net := greatest(0, brut - vergi - kent - gecim);
  saat := least(oyun.kumbara_saat(), greatest(0, extract(epoch from (t - c.son_toplama)) / 3600));
  if c.seri_gun is distinct from bugun then
    destek := case when (st ->> 'basamak')::int <= 1 then ul.destek else 0 end;
    hem := (select hemsehri from oyun.il_durum where il_id = p.il_id);
  end if;
  return jsonb_build_object(
    'saat', round(saat, 3), 'dolu', saat >= oyun.kumbara_saat(), 'dolma_an', c.son_toplama + make_interval(hours => oyun.kumbara_saat()::int),
    'kapasite', oyun.kumbara_saat(), 'seri_tavan', oyun.duz('seri_tavan'),
    'vekil_kesinti', case when exists (select 1 from oyun.makamlar where user_id = u and tur = 'mv' and bit is null) then oyun.vekil_kesinti_orani(u, t) end,
    'birikmis', round(net * saat), 'brut_birikmis', round(brut * saat), 'vergi_birikmis', round(vergi * saat),
    'saatlik', jsonb_build_object('maas', round(maas, 2), 'makam', round(makam, 2), 'brut', round(brut, 2), 'vergi', round(vergi, 2),
                                  'kent', round(kent, 2), 'gecim', round(gecim, 2), 'net', round(net, 2)),
    'gunluk_net', round(net * 24), 'asgari', ul.asgari, 'statu_carpan', (st ->> 'carpan')::numeric, 'il_carpan', ilc,
    'ucret_bonus', ub, 'seri', seri_y, 'seri_bonus', seri_b, 'vergi_oran', ul.vergi, 'kent_oran', kv, 'gecim_indirim', gecim_ind,
    'gecim_gunluk', round(350 * ul.endeks * (1 - gecim_ind / 100)),
    'gunluk_destek', jsonb_build_object('devlet', destek, 'belediye', hem),
    'reklam_odul', round(maas * 2));
end $function$;

-- Dakikalık motor: meclis ölçeği, görev ihmali, mitingler
CREATE OR REPLACE FUNCTION oyun.tick()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare t timestamptz:=oyun.simdi(); ay date; r record; n int:=0;
begin
  if not pg_try_advisory_xact_lock(424242) then return 0; end if;
  ay:=date_trunc('month',t at time zone 'Europe/Istanbul')::date;
  perform oyun.donem_olustur(ay); perform oyun.donem_olustur((ay+interval '1 month')::date);
  if (select son_temizlik from oyun.ayarlar where id=1) is distinct from (t at time zone 'Europe/Istanbul')::date then
    delete from oyun.mesajlar where zaman<t-interval '30 days'; delete from oyun.yayinlar where zaman<t-interval '30 days'; delete from oyun.bildirimler where zaman<t-interval '60 days';
    delete from oyun.ozel where zaman<t-interval '90 days'; delete from oyun.push_kuyruk where olusturma<now()-interval '7 days';
    update oyun.ayarlar set son_temizlik=(t at time zone 'Europe/Istanbul')::date where id=1;
  end if;
  loop
    select * into r from (
      select id,sonuc_at as zaman,0 as asama,oyun.oncelik(tur)o from oyun.secimler where durum='bekliyor' and sonuc_at<=t
      union all select id,goreve_bas,1,oyun.oncelik(tur) from oyun.secimler where durum='sonuclandi' and goreve_bas<=t
    )x order by zaman,asama,o limit 1;
    exit when not found;
    if r.asama=0 then perform oyun.sonuclandir(r.id); else perform oyun.goreve_baslat(r.id); end if;
    n:=n+1; exit when n>200;
  end loop;
  perform oyun.kanun_tick(t); perform oyun.mevzuat_tick(t); perform oyun.meclis_tick(t); perform oyun.parti_tuzuk_tick(t); perform oyun.siyasi_tick(t);
  perform oyun.guvenlik_tick(t); perform oyun.gunluk_ekonomi(t); perform oyun.banka_tick(t); perform oyun.meclis_olcek_uygula(t); perform oyun.ihmal_tick(t); perform oyun.miting_tick(t);
  perform oyun.push_hatirlatmalar(t); perform oyun.push_tetikle();
  return n;
end $function$;

-- Meclis: bu dönemki sandalye sayısı
CREATE OR REPLACE FUNCTION public.meclis()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'toplam',coalesce((select sum(coalesce(mv_secim,mv))::int from oyun.iller),600),
    'anayasal',coalesce((select deger::int from oyun.anayasa where kod='milletvekili_sayisi'),600),
    'dolu',(select count(*) from oyun.makamlar where tur='mv' and bit is null),
    'bagimsiz',(select count(*) from oyun.makamlar where tur='mv' and bit is null and parti_id is null),
    'partiler',coalesce((
      select jsonb_agg(oyun.parti_json(x.parti_id)||jsonb_build_object('n',x.n) order by x.n desc)
      from (
        select parti_id,count(*) n
        from oyun.makamlar
        where tur='mv' and bit is null and parti_id is not null
        group by parti_id
      ) x
    ),'[]'::jsonb),
    'vekiller',coalesce((
      select jsonb_agg(jsonb_build_object(
        'kad',oyun.kad(m.user_id),
        'il',i.ad,
        'parti_id',m.parti_id,
        'bagimsiz',m.parti_id is null
      ) order by i.ad,m.parti_id nulls last)
      from oyun.makamlar m
      join oyun.iller i on i.id=m.il_id
      where m.tur='mv' and m.bit is null
    ),'[]'::jsonb)
  )
$function$;

-- Harita: bu dönemin sandalye sayısı
CREATE OR REPLACE FUNCTION public.harita()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',i.id,
    'ad',i.ad,
    'mv',coalesce(i.mv_secim,i.mv),'mv_nufus',i.mv,
    'oyuncu',(select count(*) from oyun.profiller pr where pr.il_id=i.id),
    'gelisim',(select round(gelisim,1) from oyun.il_durum d where d.il_id=i.id),
    'bel',(select jsonb_build_object('kad',oyun.kad(m.user_id),'parti',oyun.parti_json(m.parti_id))
           from oyun.makamlar m where m.tur='bel' and m.il_id=i.id and m.bit is null limit 1),
    'vekil',(
      select coalesce(jsonb_agg(jsonb_build_object(
        'parti_id',x.parti_id,
        'renk',coalesce(pa.renk,'#8e8e93'),
        'kisa',coalesce(pa.kisa,'Bağımsız'),
        'n',x.n
      ) order by x.n desc),'[]'::jsonb)
      from (
        select parti_id,count(*) n
        from oyun.makamlar m
        where m.tur='mv' and m.il_id=i.id and m.bit is null
        group by parti_id
      ) x
      left join oyun.partiler pa on pa.id=x.parti_id
    )
  ) order by i.id),'[]'::jsonb)
  from oyun.iller i
$function$;

-- Yönetici: yeni kurallar
CREATE OR REPLACE FUNCTION public.admin_kurallar(p jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare y oyun.profiller := oyun.yetki_zorunlu('kurallar'); a oyun.ayarlar;
begin
  if p is not null then
    update oyun.ayarlar set
      min_hesap_gun      = oyun.sinir(coalesce((p ->> 'min_hesap_gun')::int, min_hesap_gun), 0, 30),
      oy_min_kidem       = oyun.sinir(coalesce((p ->> 'oy_min_kidem')::int, oy_min_kidem), 0, 100),
      oy_il_gun          = oyun.sinir(coalesce((p ->> 'oy_il_gun')::int, oy_il_gun), 0, 30),
      cihaz_max_hesap    = oyun.sinir(coalesce((p ->> 'cihaz_max_hesap')::int, cihaz_max_hesap), 1, 5),
      parti_kurucu_sayi  = oyun.sinir(coalesce((p ->> 'parti_kurucu_sayi')::int, parti_kurucu_sayi), 1, 30),
      parti_kurucu_kidem = oyun.sinir(coalesce((p ->> 'parti_kurucu_kidem')::int, parti_kurucu_kidem), 0, 300),
      parti_kurulus_gun  = oyun.sinir(coalesce((p ->> 'parti_kurulus_gun')::int, parti_kurulus_gun), 1, 30),
      -- 15_ekonomi3: parti ücreti, teşkilat, havale, banka
      parti_kur_ucret    = oyun.sinir(coalesce((p ->> 'parti_kur_ucret')::numeric, parti_kur_ucret), 0, 1000000),
      teskilat_ucret     = oyun.sinir(coalesce((p ->> 'teskilat_ucret')::numeric, teskilat_ucret), 0, 100000),
      teskilat_zorunlu   = coalesce((p ->> 'teskilat_zorunlu')::boolean, teskilat_zorunlu),
      havale_sinir       = oyun.sinir(coalesce((p ->> 'havale_sinir')::numeric, havale_sinir), 0, 10),
      banka_acik         = coalesce((p ->> 'banka_acik')::boolean, banka_acik),
      banka_reel_faiz    = oyun.sinir(coalesce((p ->> 'banka_reel_faiz')::numeric, banka_reel_faiz), -10, 30),
      banka_tavan        = oyun.sinir(coalesce((p ->> 'banka_tavan')::numeric, banka_tavan), 0, 100000000),
      meclis_olcek       = oyun.sinir(coalesce((p ->> 'meclis_olcek')::numeric, meclis_olcek), 0, 5),
      ihmal_gun_atama    = oyun.sinir(coalesce((p ->> 'ihmal_gun_atama')::int, ihmal_gun_atama), 0, 30),
      ihmal_gun_secim    = oyun.sinir(coalesce((p ->> 'ihmal_gun_secim')::int, ihmal_gun_secim), 0, 30)
    where id = 1;
    perform oyun.mod_log(y, 'kurallar', null, p::text);
  end if;
  select * into a from oyun.ayarlar where id = 1;
  return jsonb_build_object('min_hesap_gun', a.min_hesap_gun, 'oy_min_kidem', a.oy_min_kidem, 'oy_il_gun', a.oy_il_gun,
    'cihaz_max_hesap', a.cihaz_max_hesap, 'parti_kurucu_sayi', a.parti_kurucu_sayi, 'parti_kurucu_kidem', a.parti_kurucu_kidem,
    'parti_kurulus_gun', a.parti_kurulus_gun,
    'parti_kur_ucret', a.parti_kur_ucret, 'teskilat_ucret', a.teskilat_ucret, 'teskilat_zorunlu', a.teskilat_zorunlu,
    'havale_sinir', a.havale_sinir, 'banka_acik', a.banka_acik, 'banka_reel_faiz', a.banka_reel_faiz, 'banka_tavan', a.banka_tavan,
    'meclis_olcek', a.meclis_olcek, 'ihmal_gun_atama', a.ihmal_gun_atama, 'ihmal_gun_secim', a.ihmal_gun_secim);
end $function$;

-- Havale: hediyelerle ortak günlük sınır
CREATE OR REPLACE FUNCTION public.para_gonder(p_kad text, p_miktar numeric, p_aciklama text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p oyun.profiller:=oyun.profilim();
  t timestamptz:=oyun.simdi();
  h oyun.profiller;
  m numeric:=round(coalesce(p_miktar,0));
  ack text;
  bugun numeric;
  tavan numeric;
  gm oyun.banka_musteri;
  am oyun.banka_musteri;
  tid bigint;
begin
  perform oyun.banka_acik_mi();
  h:=oyun.profil_bul(p_kad);
  if h.id=p.id then raise exception 'Kendine para gönderemezsin.'; end if;
  if h.yasakli then raise exception 'Bu oyuncunun hesabı kapatılmış.'; end if;
  if m<100 then raise exception 'En az 100 ₺ gönderebilirsin.'; end if;
  if oyun.uyari(p,t) is not null then raise exception 'Para göndermek için seçmen kartın hazır olmalı: %',oyun.uyari(p,t); end if;
  if (select coklu_kontrol from oyun.ayarlar where id=1)
     and exists(select 1 from oyun.bagli_hesaplar(p.id) b where b=h.id) then
    raise exception 'Aynı cihazda açılmış hesaplar arasında banka transferi yapılamaz.';
  end if;
  if oyun.engelli(h.id,p.id) then raise exception 'Bu oyuncu seni engellediği için ona para gönderemezsin.'; end if;
  perform oyun.takip_engel(p.id,'banka transferi yapamazsın');

  bugun:=oyun.gunluk_aktarim(p.id,t);   -- havale + oyuncu/şirket/gazeteye hediye ortak sınır
  tavan:=round((select asgari from oyun.ulke where id=1)*(select havale_sinir from oyun.ayarlar where id=1));
  if bugun+m>tavan then
    raise exception 'Günlük para aktarma sınırı % ₺ (bugün havale ve hediyeyle % ₺ gönderdin).',oyun.tl(tavan),oyun.tl(bugun);
  end if;

  if nullif(btrim(coalesce(p_aciklama,'')),'') is not null then ack:=oyun.metin_temizle(p_aciklama,100); end if;

  gm:=oyun.vadesiz_isle(p.id,t);
  am:=oyun.vadesiz_isle(h.id,t);
  if gm.vadesiz<m then
    raise exception 'Transfer için vadesiz hesabında yeterli para yok. Bakiye: % ₺.',oyun.tl(gm.vadesiz);
  end if;
  if oyun.mevduat_toplam(h.id)+m>oyun.banka_tavani() then
    raise exception 'Alıcının banka mevduatı üst sınıra çok yakın. Bu transfer alıcının mevduat tavanını aşar.';
  end if;

  update oyun.banka_musteri set vadesiz=vadesiz-m where user_id=p.id;
  update oyun.banka_musteri set vadesiz=vadesiz+m where user_id=h.id;

  insert into oyun.banka_transfer(gonderen,alici,tutar,aciklama,zaman)
  values(p.id,h.id,m,ack,t) returning id into tid;

  perform oyun.banka_kayit(p.id,'vadesiz',-m,
    format('%s adlı oyuncuya banka transferi%s',h.kad,coalesce(': '||ack,'')),t);
  perform oyun.banka_kayit(h.id,'vadesiz',m,
    format('%s adlı oyuncudan banka transferi%s',p.kad,coalesce(': '||ack,'')),t);

  perform oyun.bildir(h.id,format('%s sana banka yoluyla %s ₺ gönderdi.%s',
    p.kad,oyun.tl(m),coalesce(' Not: “'||ack||'”','')),t);

  return jsonb_build_object(
    'tamam',true,'transfer_id',tid,'alici',h.kad,'miktar',m,
    'bakiye',(select vadesiz from oyun.banka_musteri where user_id=p.id),
    'bugun',bugun+m,'tavan',tavan
  );
end $function$;

-- Mevzuat makro etkisi: kumbara taban değeri tanımdan okunur
CREATE OR REPLACE FUNCTION oyun.mevzuat_makro()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select jsonb_build_object(
    'buyume', -0.08 * oyun.duz('servet_vergisi') - 0.1 * (oyun.duz('kumbara_saat') - (select varsayilan from oyun.duzenleme_tanim where kod = 'kumbara_saat')),
    'enflasyon', 0.05 * (oyun.duz('seri_tavan') - 30) + 0.02 * oyun.duz('yeni_hibe') / 1000,
    'memnuniyet', 0.15 * oyun.duz('servet_vergisi') - 0.4 * oyun.duz('oy_cezasi') / 1000 + 0.04 * oyun.duz('yeni_hibe') / 1000
                  + 0.03 * (oyun.duz('seri_tavan') - 30) + 0.5 * (oyun.duz('kumbara_saat') - (select varsayilan from oyun.duzenleme_tanim where kod = 'kumbara_saat')) + 0.04 * oyun.duz('vekil_kesinti'))
$function$;

-- İl detayı: bu dönemin sandalye sayısı
CREATE OR REPLACE FUNCTION public.il_detay(p_il integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare p oyun.profiller := oyun.profilim(); i oyun.iller; t timestamptz := oyun.simdi();
begin
  select * into i from oyun.iller where id = p_il;
  if i.id is null then raise exception 'İl bulunamadı.'; end if;
  return jsonb_build_object(
    'id', i.id, 'ad', i.ad, 'mv', coalesce(i.mv_secim, i.mv), 'mv_nufus', i.mv,
    'oyuncu', (select count(*) from oyun.profiller where il_id = i.id),
    'partiler', coalesce((select jsonb_agg(oyun.parti_json(x.parti_id) || jsonb_build_object('uye', x.n) order by x.n desc)
                 from (select parti_id, count(*) n from oyun.profiller where il_id = i.id and parti_id is not null group by parti_id) x), '[]'::jsonb),
    'bel', (select jsonb_build_object('kad', oyun.kad(m.user_id), 'parti', oyun.parti_json(m.parti_id), 'bas', m.bas)
            from oyun.makamlar m where m.tur = 'bel' and m.il_id = i.id and m.bit is null limit 1),
    'vekiller', coalesce((select jsonb_agg(jsonb_build_object('kad', oyun.kad(m.user_id), 'parti', oyun.parti_json(m.parti_id), 'kaynak', m.kaynak) order by m.parti_id, m.bas)
                 from oyun.makamlar m where m.tur = 'mv' and m.il_id = i.id and m.bit is null), '[]'::jsonb),
    'adaylar', coalesce((select jsonb_agg(oyun.aday_json(a.id) || jsonb_build_object('tur', s.tur) order by s.tur, a.parti_id, a.sira nulls last, a.basvuru_at)
                 from oyun.adaylar a join oyun.secimler s on s.id = a.secim_id
                 where a.il_id = i.id and (s.durum = 'bekliyor' or (s.tur = 'mv_on' and exists
                   (select 1 from oyun.secimler m where m.tur = 'mv' and m.donem = s.donem and m.durum = 'bekliyor')))), '[]'::jsonb),
    'benim_ilim', p.il_id = i.id,
    'durum', (select jsonb_build_object('gelisim', round(d.gelisim, 1), 'memnuniyet', round(d.memnuniyet, 1), 'kasa', round(d.kasa, 2))
              from oyun.il_durum d where d.il_id = i.id),
    'projeler', coalesce((select jsonb_agg(jsonb_build_object('ad', k.ad, 'zaman', k.zaman, 'baskan', oyun.kad(k.baskan)) order by k.zaman desc)
                 from (select x.*, coalesce(b.ad, y.ad) ad from oyun.belediye_proje_kayit x
                       left join oyun.belediye_hizmetleri b on b.kod = x.kod left join oyun.belediye_yatirimlari y on y.kod = x.kod
                       where x.il_id = i.id order by x.zaman desc limit 5) k), '[]'::jsonb),
    -- ilde yaşayanlara şu an işleyen belediye hizmetleri ve bakanlık tedbirleri
    'hizmetler', oyun.il_hizmet_json(i.id, t),
    'il_carpan', oyun.il_carpan(i.id),
    'kent_vergisi', (select kent_vergisi from oyun.il_durum where il_id = i.id),
    'hemsehri', (select hemsehri from oyun.il_durum where il_id = i.id),
    'tasinma', case when p.il_id <> i.id then oyun.tasinma_ucreti(p.il_id, i.id, t) end,
    'bel_vaatler', (select oyun.vaat_listesi_makam(m.id) from oyun.makamlar m where m.tur = 'bel' and m.il_id = i.id and m.bit is null limit 1));
end $function$;

-- =====================================================================
--  Para aktarma: havale ve hediyeler aynı günlük sınıra tabi
-- =====================================================================
create or replace function oyun.gunluk_aktarim(u uuid, t timestamptz) returns numeric language sql stable set search_path = '' as $$
  select coalesce((select sum(tutar) from oyun.banka_transfer where gonderen = u and zaman >= oyun.bugun_bas(t)), 0)
       + coalesce((select sum(tutar) from oyun.serbest_bagis_kayit where gonderen = u and alici_tur in ('oyuncu','sirket','gazete')
                   and zaman >= oyun.bugun_bas(t)), 0)
$$;

create or replace function oyun.aktarim_tavani() returns numeric language sql stable set search_path = '' as $$
  select round((select asgari from oyun.ulke where id = 1) * (select havale_sinir from oyun.ayarlar where id = 1))
$$;

CREATE OR REPLACE FUNCTION public.serbest_bagis(p_tur text, p_id text, p_tutar numeric, p_aciklama text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid(); p oyun.profiller; t timestamptz:=oyun.simdi();
 m numeric; tid bigint; v_id bigint; v_uuid uuid; hedef text;
 note text:=btrim(coalesce(p_aciklama,'')); c oyun.cuzdan; v_min numeric;
 kisisel boolean:=p_tur in ('oyuncu','sirket','gazete'); bugun numeric; tavan numeric;
begin
 if u is null then raise exception 'Oturum açmalısın';end if;
 if p_tutar is null or p_tutar::text !~ '^[0-9]+(\.[0-9]+)?$'
   or p_tutar<>trunc(p_tutar) or p_tutar<1 then
   raise exception 'Bağış tutarı en az 1 TL, pozitif tam sayı olmalı';end if;
 m:=p_tutar;
 if length(note)>150 then raise exception 'Bağış notu en fazla 150 karakter';end if;
 if note<>'' and oyun.kufurlu(note) then raise exception 'Notunda uygunsuz bir ifade var.';end if;
 select * into p from oyun.profiller where id=u;
 if not found or p.yasakli then raise exception 'Hesabın bağış yapmaya uygun değil';end if;
 perform oyun.takip_engel(u,'bağış yapamazsın');
 if p_tur not in ('oyuncu','parti','sirket','gazete','il','devlet') then raise exception 'Geçersiz bağış hedefi';end if;
 -- Kişilere ve kişilerin kurumlarına (şirket, gazete) aktarılan para, havaleyle aynı kurallara tabidir:
 -- seçmen kartı hazır olmalı ve günlük aktarma sınırı aşılamaz. Böylece satın alınan para sınırsızca
 -- başka hesaplara taşınamaz; oy ve makam parayla toplanamaz.
 if kisisel then
   if oyun.uyari(p,t) is not null then
     raise exception 'Başka oyunculara para aktarmak için seçmen kartın hazır olmalı: %', oyun.uyari(p,t);
   end if;
   bugun:=oyun.gunluk_aktarim(u,t); tavan:=oyun.aktarim_tavani();
   if bugun+m>tavan then
     raise exception 'Günlük para aktarma sınırı % ₺ (bugün havale ve hediyeyle % ₺ gönderdin; kalan % ₺). Partiye, şehre ve hazineye bağış sınırsızdır.',
       oyun.tl(tavan), oyun.tl(bugun), oyun.tl(greatest(0,tavan-bugun));
   end if;
 end if;
 if p_tur='oyuncu' then
   select id,kad into v_uuid,hedef from oyun.profiller
    where lower(kad)=lower(btrim(coalesce(p_id,''))) and not yasakli limit 1;
   if v_uuid is null then raise exception 'Alıcı oyuncu bulunamadı';end if;
   if v_uuid=u then raise exception 'Kendine bağış yapamazsın';end if;
   if exists(select 1 from oyun.ayarlar where id=1 and coklu_kontrol)
     and exists(select 1 from oyun.bagli_hesaplar(u) b where b=v_uuid) then
      raise exception 'Aynı cihazdaki bağlı hesaplara bağış yapılamaz';end if;
   if oyun.engelli(v_uuid,u) then raise exception 'Bu oyuncu seni engelledi';end if;
 elsif p_tur in ('parti','sirket','gazete','il') then
   if p_id is null or p_id !~ '^[0-9]{1,15}$' then raise exception 'Geçerli hedef numarası gir';end if;
   v_id:=p_id::bigint;
   if p_tur='parti' then
     select ad into hedef from oyun.partiler where id=v_id and not kapali;
   elsif p_tur='sirket' then
     select ad into hedef from oyun.sirketler where id=v_id and aktif;
     if exists(select 1 from oyun.ayarlar where id=1 and coklu_kontrol)
       and exists(select 1 from oyun.sirket_ortaklari o join oyun.bagli_hesaplar(u) b on b=o.user_id where o.sirket_id=v_id and o.pay>0) then
       raise exception 'Aynı cihazdaki bağlı hesapların şirketine bağış yapılamaz';end if;
   elsif p_tur='gazete' then
     select ad into hedef from oyun.oyuncu_gazeteleri where id=v_id and aktif;
   else
     select ad into hedef from oyun.iller where id=v_id;
   end if;
   if hedef is null then raise exception 'Bağış yapılacak kurum bulunamadı';end if;
 else
   hedef:='Türkiye Cumhuriyeti Hazinesi';
 end if;
 perform oyun.para_islem(u,-m,'bagis',left(hedef||' için bağış'||case when note<>'' then ': '||note else '' end,170),t);
 if p_tur='oyuncu' then
   perform oyun.para_islem(v_uuid,m,'bagis',left(p.kad||' tarafından hediye'||case when note<>'' then ': '||note else '' end,170),t);
   perform oyun.bildir(v_uuid,format('%s sana %s ₺ hediye etti.%s',p.kad,oyun.tl(m),case when note<>'' then ' Not: “'||note||'”' else '' end),t);
 elsif p_tur='parti' then
   update oyun.partiler set kasa=kasa+m where id=v_id;
   insert into oyun.parti_hareket(parti_id,zaman,tutar,aciklama,tur)
     values(v_id,t,m,format('%s bağış yaptı',p.kad),'bagis');
 elsif p_tur='sirket' then
   update oyun.sirketler set kasa=kasa+m where id=v_id;
   insert into oyun.sirket_hareket(sirket_id,zaman,tutar,aciklama)
     values(v_id,t,m,p.kad||' oyuncusundan sermaye niteliğinde olmayan karşılıksız bağış');
 elsif p_tur='gazete' then
   update oyun.oyuncu_gazeteleri set kasa=kasa+m where id=v_id;
   insert into oyun.gazete_hareket(gazete_id,zaman,tutar,tur,aciklama)
     values(v_id,t,m,'bagis',p.kad||' bağış yaptı');
 elsif p_tur='il' then
   select asgari into v_min from oyun.ulke where id=1;
   update oyun.il_durum set kasa=kasa+m,gelisim=least(100,gelisim+0.005*m/greatest(1,v_min)) where il_id=v_id;
   insert into oyun.il_bagis_kayit(il_id,user_id,tutar,zaman) values(v_id::smallint,u,m,t);
 else
   update oyun.ulke set hazine=hazine+m where id=1;
 end if;
 insert into oyun.serbest_bagis_kayit(gonderen,alici_tur,alici_id,alici_adi,tutar,aciklama,zaman)
 values(u,p_tur,case when p_tur='oyuncu' then v_uuid::text when p_tur='devlet' then '1' else v_id::text end,hedef,m,nullif(note,''),t)
 returning id into tid;
 -- Kıdem yalnızca kamusal bağıştan (parti, şehir, hazine) ve günde en fazla 1 puan.
 if not kisisel then
   select * into c from oyun.cuzdan where user_id=u for update;
   select asgari into v_min from oyun.ulke where id=1;
   update oyun.cuzdan
   set kidem=kidem+greatest(0,
     least(1,(coalesce(c.bagis_bugun,0)+m)/greatest(1,v_min))
      -least(1,coalesce(c.bagis_bugun,0)/greatest(1,v_min))),
     bagis_bugun=coalesce(bagis_bugun,0)+m where user_id=u;
 end if;
 return jsonb_build_object('tamam',true,'id',tid,'gonderen',p.kad,
  'hedef',hedef,'hedef_tur',p_tur,'tutar',m,
  'kalan', (select para from oyun.cuzdan where user_id=u),
  'aktarim_kalan', case when kisisel then greatest(0,oyun.aktarim_tavani()-oyun.gunluk_aktarim(u,t)) end);
end $function$;
revoke all on function public.serbest_bagis(text,text,numeric,text) from public,anon;
grant execute on function public.serbest_bagis(text,text,numeric,text) to authenticated;

-- Oyuncunun bugünkü aktarma hakkı (bağış ekranı gösterir)
create or replace function public.aktarim_hakki() returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); b numeric; v numeric;
begin
  b := oyun.gunluk_aktarim(p.id, t); v := oyun.aktarim_tavani();
  return jsonb_build_object('bugun', b, 'tavan', v, 'kalan', greatest(0, v - b), 'engel', oyun.uyari(p, t));
end $$;

-- Yönetici transfer listesi: havaleler + oyunculara hediyeler (kanal sütunuyla)
CREATE OR REPLACE FUNCTION public.admin_transferler_sayfa(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_ara text DEFAULT NULL::text, p_min numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p oyun.profiller:=oyun.yonetici_zorunlu();
  lim int:=least(greatest(coalesce(p_limit,100),1),250);
  off int:=greatest(coalesce(p_offset,0),0);
  ara text:=lower(btrim(coalesce(p_ara,'')));
  toplam int;
  satirlar jsonb;
begin
  create temp table if not exists _aktarim(id bigint, kanal text, gonderen uuid, alici uuid, tutar numeric, aciklama text, zaman timestamptz) on commit drop;
  delete from _aktarim;
  insert into _aktarim
    select bt.id,'havale',bt.gonderen,bt.alici,bt.tutar,bt.aciklama,bt.zaman from oyun.banka_transfer bt
    union all
    select sb.id,'hediye',sb.gonderen,sb.alici_id::uuid,sb.tutar,sb.aciklama,sb.zaman from oyun.serbest_bagis_kayit sb where sb.alici_tur='oyuncu';

  select count(*) into toplam
  from _aktarim bt
  join oyun.profiller gp on gp.id=bt.gonderen
  join oyun.profiller ap on ap.id=bt.alici
  where (ara='' or lower(gp.kad) like '%'||ara||'%' or lower(ap.kad) like '%'||ara||'%')
    and (p_min is null or bt.tutar>=p_min);

  select coalesce(jsonb_agg(jsonb_build_object(
      'id',t.id,'kanal',t.kanal,'zaman',t.zaman,'gonderen',g.kad,'alici',a.kad,'tutar',t.tutar,'aciklama',t.aciklama,
      'gonderen_olusturma',g.olusturma,'alici_olusturma',a.olusturma,
      'ikili_30gun',(select count(*) from _aktarim z
        where z.zaman>oyun.simdi()-interval '30 days'
          and ((z.gonderen=t.gonderen and z.alici=t.alici) or (z.gonderen=t.alici and z.alici=t.gonderen))),
      'ikili_tutar_30gun',(select coalesce(sum(z.tutar),0) from _aktarim z
        where z.zaman>oyun.simdi()-interval '30 days'
          and ((z.gonderen=t.gonderen and z.alici=t.alici) or (z.gonderen=t.alici and z.alici=t.gonderen))),
      'bagli_hesap',exists(select 1 from oyun.bagli_hesaplar(t.gonderen)b where b=t.alici)
    ) order by t.zaman desc,t.id desc),'[]'::jsonb)
  into satirlar
  from (
    select bt.* from _aktarim bt
    join oyun.profiller gp on gp.id=bt.gonderen
    join oyun.profiller ap on ap.id=bt.alici
    where (ara='' or lower(gp.kad) like '%'||ara||'%' or lower(ap.kad) like '%'||ara||'%')
      and (p_min is null or bt.tutar>=p_min)
    order by bt.zaman desc,bt.id desc
    limit lim offset off
  )t
  join oyun.profiller g on g.id=t.gonderen
  join oyun.profiller a on a.id=t.alici;

  return jsonb_build_object('toplam',toplam,'offset',off,'limit',lim,'satirlar',satirlar);
end $function$;

-- =====================================================================
--  Meclis ölçeği: genel seçim başvurusu açılınca sandalyeler aktif oyuncuya göre dağıtılır
-- =====================================================================
create or replace function oyun.meclis_olcek_hesap(t timestamptz) returns jsonb language plpgsql stable set search_path = '' as $$
declare a numeric := (select meclis_olcek from oyun.ayarlar where id = 1);
        anayasal int := coalesce((select round(deger)::int from oyun.anayasa where kod = 'milletvekili_sayisi'), 600);
        aktif int := (select count(*) from oyun.profiller where not yasakli and son_gorulme > t - interval '14 days');
        n int;
begin
  n := case when coalesce(a, 0) <= 0 then anayasal else least(anayasal, greatest(81, ceil(aktif * a)::int)) end;
  return jsonb_build_object('aktif', aktif, 'sandalye', n, 'anayasal', anayasal, 'olcek', a);
end $$;

create or replace function oyun.meclis_olcek_uygula(t timestamptz) returns void language plpgsql set search_path = '' as $$
declare s oyun.secimler; h jsonb;
begin
  for s in select * from oyun.secimler x where x.tur = 'mv_on' and x.durum = 'bekliyor' and x.basvuru_bas <= t
             and not exists (select 1 from oyun.meclis_olcek_kayit k where k.secim_id = x.id) order by x.id loop
    h := oyun.meclis_olcek_hesap(t);
    perform oyun.dagit_mv_sandalye((h->>'sandalye')::int);
    insert into oyun.meclis_olcek_kayit(secim_id, aktif, sandalye, anayasal, zaman)
      values (s.id, (h->>'aktif')::int, (h->>'sandalye')::int, (h->>'anayasal')::int, t) on conflict do nothing;
    if (h->>'sandalye')::int < (h->>'anayasal')::int then
      perform oyun.olay('meclis', format('Yeni dönem TBMM %s sandalyeden oluşacak: son iki haftada oyuna giren %s vatandaşa göre dağıtıldı (anayasal üst sınır %s).',
        h->>'sandalye', h->>'aktif', h->>'anayasal'), null, null, t);
    end if;
  end loop;
end $$;

-- =====================================================================
--  Görev ihmali: uzun süre oyuna girmeyen makam sahibi görevden düşer (önce uyarılır)
-- =====================================================================
create or replace function oyun.ihmal_tick(t timestamptz) returns void language plpgsql set search_path = '' as $$
declare ga int; gs int; r record; sec jsonb;
begin
  select ihmal_gun_atama, ihmal_gun_secim into ga, gs from oyun.ayarlar where id = 1;
  -- Geri dönen oyuncunun uyarı kaydı silinir (bir sonraki ihmalde yeniden uyarılır)
  delete from oyun.ihmal_uyari u using oyun.profiller p where p.id = u.user_id and p.son_gorulme > u.zaman;

  -- Atanmış görevler: bakan ve genel başkan yardımcısı
  if ga > 0 then
    for r in select m.id, m.user_id, m.bakanlik, p.kad, p.parti_id, p.son_gorulme from oyun.makamlar m join oyun.profiller p on p.id = m.user_id
             where m.tur = 'bakan' and m.bit is null and coalesce(p.son_gorulme, m.bas) < t - make_interval(days => ga)
               and m.bas < t - make_interval(days => ga)
               and exists (select 1 from oyun.ihmal_uyari u where u.user_id = m.user_id and u.tur = 'atama' and u.zaman <= t - interval '1 day') loop
      perform oyun.makam_bitir(r.id, t, 'ihmal');
      perform oyun.bildir(r.user_id, format('%s gündür oyuna girmediğin için %s görevin sona erdi.', ga, oyun.makam_ad('bakan', null, r.bakanlik)), t);
      perform oyun.bildir(m2.user_id, format('%s, %s gündür oyuna girmediği için %s görevinden düştü. Yerine yeni bakan atayabilirsin.', r.kad, ga, oyun.makam_ad('bakan', null, r.bakanlik)), t)
        from oyun.makamlar m2 where m2.tur = 'cb' and m2.bit is null;
      perform oyun.olay('makam', format('%s, görevini ihmal ettiği için %s görevinden düştü.', r.kad, oyun.makam_ad('bakan', null, r.bakanlik)), null, r.parti_id, t);
    end loop;
    for r in select g.parti_id, g.user_id, p.kad, pa.gb from oyun.parti_gby g join oyun.profiller p on p.id = g.user_id join oyun.partiler pa on pa.id = g.parti_id
             where coalesce(p.son_gorulme, g.atama) < t - make_interval(days => ga) and g.atama < t - make_interval(days => ga)
               and exists (select 1 from oyun.ihmal_uyari u where u.user_id = g.user_id and u.tur = 'atama' and u.zaman <= t - interval '1 day') loop
      delete from oyun.parti_gby where user_id = r.user_id;
      perform oyun.bildir(r.user_id, format('%s gündür oyuna girmediğin için genel başkan yardımcılığın sona erdi.', ga), t);
      if r.gb is not null then perform oyun.bildir(r.gb, format('%s, %s gündür oyuna girmediği için yardımcılıktan düştü. Yerine yeni bir yardımcı atayabilirsin.', r.kad, ga), t); end if;
    end loop;
    -- Uyarı: sürenin bitmesine 1 gün kala
    insert into oyun.ihmal_uyari(user_id, tur, zaman)
      select x.user_id, 'atama', t from (
        select m.user_id from oyun.makamlar m join oyun.profiller p on p.id = m.user_id
          where m.tur = 'bakan' and m.bit is null and coalesce(p.son_gorulme, m.bas) < t - make_interval(days => ga) + interval '1 day'
        union select g.user_id from oyun.parti_gby g join oyun.profiller p on p.id = g.user_id
          where coalesce(p.son_gorulme, g.atama) < t - make_interval(days => ga) + interval '1 day') x
      where not exists (select 1 from oyun.ihmal_uyari u where u.user_id = x.user_id and u.tur = 'atama')
      on conflict do nothing;
  end if;

  -- Seçilmiş görevler: cumhurbaşkanı, belediye başkanı, genel başkan
  if gs > 0 then
    for r in select m.id, m.tur, m.user_id, m.il_id, p.kad, p.parti_id from oyun.makamlar m join oyun.profiller p on p.id = m.user_id
             where m.tur in ('cb','bel') and m.bit is null and coalesce(p.son_gorulme, m.bas) < t - make_interval(days => gs)
               and m.bas < t - make_interval(days => gs)
               and exists (select 1 from oyun.ihmal_uyari u where u.user_id = m.user_id and u.tur = 'secim' and u.zaman <= t - interval '2 days') loop
      perform oyun.makam_bitir(r.id, t, 'ihmal');
      sec := oyun.ara_secim_olustur(r.tur, null, case when r.tur = 'bel' then r.il_id end, t);
      perform oyun.bildir(r.user_id, format('%s gündür oyuna girmediğin için %s görevin sona erdi.', gs, oyun.makam_ad(r.tur, r.il_id, null)), t);
      perform oyun.olay('makam', format('%s, %s gündür ortada olmadığı için %s görevinden düştü. Olağanüstü seçim takvimi oluşturuldu.',
        r.kad, gs, oyun.makam_ad(r.tur, r.il_id, null)), r.il_id, r.parti_id, t);
    end loop;
    for r in select pa.id, pa.ad, pa.gb, p.kad from oyun.partiler pa join oyun.profiller p on p.id = pa.gb
             where not pa.kapali and coalesce(p.son_gorulme, p.olusturma) < t - make_interval(days => gs)
               and exists (select 1 from oyun.ihmal_uyari u where u.user_id = pa.gb and u.tur = 'secim' and u.zaman <= t - interval '2 days') loop
      update oyun.partiler set gb = null where id = r.id;
      sec := oyun.ara_secim_olustur('gb', r.id, null, t);
      perform oyun.bildir(r.gb, format('%s gündür oyuna girmediğin için %s Genel Başkanlığın sona erdi.', gs, r.ad), t);
      insert into oyun.bildirimler(user_id, zaman, metin)
        select id, t, format('%s Genel Başkanı %s gündür ortada olmadığı için görevden düştü. Olağanüstü kurultay başladı; genel başkanlığı üstlenebilir ya da aday olabilirsin.', r.ad, gs)
        from oyun.profiller where parti_id = r.id and id <> r.gb;
      perform oyun.olay('parti', format('%s, %s Genel Başkanlığından ihmal nedeniyle düştü. Olağanüstü kurultay takvimi oluşturuldu.', r.kad, r.ad), null, r.id, t);
    end loop;
    insert into oyun.ihmal_uyari(user_id, tur, zaman)
      select x.user_id, 'secim', t from (
        select m.user_id from oyun.makamlar m join oyun.profiller p on p.id = m.user_id
          where m.tur in ('cb','bel') and m.bit is null and coalesce(p.son_gorulme, m.bas) < t - make_interval(days => gs) + interval '2 days'
        union select pa.gb from oyun.partiler pa join oyun.profiller p on p.id = pa.gb
          where not pa.kapali and coalesce(p.son_gorulme, p.olusturma) < t - make_interval(days => gs) + interval '2 days') x
      where not exists (select 1 from oyun.ihmal_uyari u where u.user_id = x.user_id and u.tur = 'secim')
      on conflict do nothing;
  end if;
end $$;

-- Uyarı kaydı eklendiğinde oyuncuya bildirim (telefonuna da düşer)
create or replace function oyun.ihmal_uyari_tg() returns trigger language plpgsql set search_path = '' as $$
begin
  perform oyun.bildir(new.user_id, case new.tur
    when 'atama' then 'Uzun süredir oyuna girmedin. Bir gün içinde girmezsen atandığın görevden (bakanlık / genel başkan yardımcılığı) düşeceksin.'
    else 'Uzun süredir oyuna girmedin. İki gün içinde girmezsen seçildiğin görevden düşeceksin ve olağanüstü seçim yapılacak.' end, new.zaman);
  return new;
end $$;
drop trigger if exists ihmal_uyari_bildir on oyun.ihmal_uyari;
create trigger ihmal_uyari_bildir after insert on oyun.ihmal_uyari for each row execute function oyun.ihmal_uyari_tg();

-- =====================================================================
--  İlk adımlar: yeni oyuncunun ilk günü için görev listesi
-- =====================================================================
create or replace function public.ilk_adimlar() returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); u text; adimlar jsonb;
begin
  u := oyun.uyari(p, t);
  adimlar := jsonb_build_array(
    jsonb_build_object('kod','maas','ad','İlk maaşını topla','tamam', exists(select 1 from oyun.hesap_hareket where user_id = p.id and tur = 'maas')),
    jsonb_build_object('kod','kimlik','ad','Portreni ve kısa biyografini hazırla','tamam', exists(select 1 from oyun.oyuncu_kimlik where user_id = p.id and avatar is not null)),
    jsonb_build_object('kod','parti','ad','Sana yakın bir partiye katıl','tamam', p.parti_id is not null),
    jsonb_build_object('kod','sohbet','ad','İl kahvesinde kendini tanıt','tamam', exists(select 1 from oyun.mesajlar where user_id = p.id)),
    jsonb_build_object('kod','anket','ad','Haftalık siyasi ankete katıl','tamam', exists(select 1 from oyun.haftalik_anket_oy where user_id = p.id)),
    jsonb_build_object('kod','oy','ad','İlk oyunu kullan','tamam', exists(select 1 from oyun.oylar where secmen = p.id), 'not', u));
  return jsonb_build_object('adimlar', adimlar, 'secmen_karti', u is null, 'engel', u,
    'yeni', p.olusturma > t - interval '14 days',
    'bitti', not exists (select 1 from jsonb_array_elements(adimlar) x where not (x->>'tamam')::boolean));
end $$;

-- =====================================================================
--  Cumhuriyet tarihi: oyunun hiç silinmeyen geçmişi
-- =====================================================================
create or replace function public.tarih_arsivi() returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'baslangic', (select min(olusturma) from oyun.profiller),
    'cumhurbaskanlari', coalesce((select jsonb_agg(jsonb_build_object('kad', p.kad, 'parti', oyun.parti_json(m.parti_id), 'bas', m.bas, 'bit', m.bit,
        'neden', m.bitis_neden, 'gun', round(extract(epoch from coalesce(m.bit, oyun.simdi()) - m.bas) / 86400, 1)) order by m.bas)
      from oyun.makamlar m join oyun.profiller p on p.id = m.user_id where m.tur = 'cb'), '[]'::jsonb),
    'meclis_baskanlari', coalesce((select jsonb_agg(jsonb_build_object('kad', p.kad, 'parti', oyun.parti_json(m.parti_id), 'bas', m.bas, 'bit', m.bit) order by m.bas)
      from oyun.makamlar m join oyun.profiller p on p.id = m.user_id where m.tur = 'tbmm'), '[]'::jsonb),
    'meclisler', coalesce((select jsonb_agg(jsonb_build_object('donem', s.donem, 'tarih', s.sonuc_at, 'oy', s.sonuc -> 'toplam',
        'dolu', s.sonuc -> 'dolu', 'partiler', (select coalesce(jsonb_agg(jsonb_build_object('parti', oyun.parti_json((x ->> 'parti_id')::bigint),
            'yuzde', x -> 'yuzde', 'sandalye', x -> 'sandalye') order by (x ->> 'sandalye')::int desc), '[]'::jsonb)
          from jsonb_array_elements(coalesce(s.sonuc -> 'ulusal', '[]'::jsonb)) x where (x ->> 'sandalye')::int > 0)) order by s.sonuc_at desc)
      from oyun.secimler s where s.tur = 'mv' and s.durum <> 'bekliyor' and s.sonuc is not null), '[]'::jsonb),
    'kanunlar', jsonb_build_object('toplam', (select count(*) from oyun.kanunlar where no is not null),
      'son', coalesce((select jsonb_agg(x) from (select jsonb_build_object('no', k.no, 'baslik', k.baslik, 'tarih', k.sonuc_at, 'teklif_eden', oyun.kad(k.teklif_eden),
          'parti', oyun.parti_json(k.teklif_parti)) x from oyun.kanunlar k where k.no is not null order by k.no desc limit 12) y), '[]'::jsonb)),
    'partiler', coalesce((select jsonb_agg(jsonb_build_object('parti', oyun.parti_json(pa.id), 'kurulus', pa.kurulus, 'sistem', pa.sistem, 'kapali', pa.kapali,
        'uye', (select count(*) from oyun.profiller pr where pr.parti_id = pa.id and not pr.yasakli)) order by pa.kurulus)
      from oyun.partiler pa where pa.kurulus_bit is null or pa.kapali or pa.sistem or exists (select 1 from oyun.profiller pr where pr.parti_id = pa.id)), '[]'::jsonb),
    'rekorlar', jsonb_build_object(
      'en_cok_oy', (select jsonb_build_object('kad', p.kad, 'oy', a.oy, 'secim', s.tur, 'donem', s.donem) from oyun.adaylar a join oyun.secimler s on s.id = a.secim_id
         join oyun.profiller p on p.id = a.user_id where s.tur in ('cb','cb2','bel','kurultay') and a.oy is not null order by a.oy desc, a.id limit 1),
      'en_uzun_cb', (select jsonb_build_object('kad', p.kad, 'gun', round(extract(epoch from coalesce(m.bit, oyun.simdi()) - m.bas) / 86400, 1)) from oyun.makamlar m
         join oyun.profiller p on p.id = m.user_id where m.tur = 'cb' order by coalesce(m.bit, oyun.simdi()) - m.bas desc limit 1),
      'en_cok_kanun', (select jsonb_build_object('kad', oyun.kad(k.teklif_eden), 'sayi', count(*)) from oyun.kanunlar k where k.no is not null
         group by k.teklif_eden order by count(*) desc limit 1),
      'en_kalabalik_miting', (select jsonb_build_object('kad', p.kad, 'il', i.ad, 'kisi', (select count(*) from oyun.miting_katilim c where c.miting_id = mt.id))
         from oyun.mitingler mt join oyun.profiller p on p.id = mt.user_id join oyun.iller i on i.id = mt.il_id where mt.bit < oyun.simdi()
         order by (select count(*) from oyun.miting_katilim c where c.miting_id = mt.id) desc, mt.id limit 1),
      'en_yuksek_katilim', (select jsonb_build_object('donem', s.donem, 'oy', (s.sonuc ->> 'toplam')::int) from oyun.secimler s
         where s.tur = 'mv' and s.sonuc ? 'toplam' order by (s.sonuc ->> 'toplam')::int desc limit 1)))
$$;

-- =====================================================================
--  Parti kimliği: iki eksenli siyasi konum + slogan (genel başkan belirler)
-- =====================================================================
insert into oyun.parti_kimlik(parti_id, eko, toplum, slogan)
select pa.id, v.eko, v.toplum, v.slogan from oyun.partiler pa join (values
  ('CYP', -1::smallint, -3::smallint, 'Cumhuriyetin yolunda, herkes için adalet'),
  ('ABP',  2::smallint,  3::smallint, 'Anadolu''nun gücü, milletin birliği'),
  ('YDP',  4::smallint, -2::smallint, 'Özgür birey, güçlü ekonomi'),
  ('MKP',  0::smallint,  4::smallint, 'Önce millet, önce kalkınma'),
  ('EÖP', -5::smallint, -4::smallint, 'Emeğin, doğanın ve özgürlüğün partisi')
) v(kisa, eko, toplum, slogan) on v.kisa = pa.kisa
where pa.sistem
on conflict (parti_id) do nothing;

create or replace function public.parti_kimlikleri() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('parti', oyun.parti_json(pa.id), 'eko', coalesce(k.eko, 0), 'toplum', coalesce(k.toplum, 0),
      'belirlendi', k.parti_id is not null, 'slogan', k.slogan,
      'uye', (select count(*) from oyun.profiller pr where pr.parti_id = pa.id and not pr.yasakli),
      'vekil', (select count(*) from oyun.makamlar m where m.tur = 'mv' and m.bit is null and m.parti_id = pa.id),
      'gb', oyun.kad(pa.gb)) order by (select count(*) from oyun.profiller pr where pr.parti_id = pa.id) desc, pa.id), '[]'::jsonb)
  from oyun.partiler pa left join oyun.parti_kimlik k on k.parti_id = pa.id
  where not pa.kapali
$$;

create or replace function public.parti_kimlik_ayarla(p_eko int, p_toplum int, p_slogan text) returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); pa oyun.partiler; s text; eski oyun.parti_kimlik;
begin
  select * into pa from oyun.partiler where gb = p.id and not kapali;
  if pa.id is null then raise exception 'Parti kimliğini yalnızca genel başkan belirler.'; end if;
  if p_eko not between -5 and 5 or p_toplum not between -5 and 5 then raise exception 'Eksen değerleri -5 ile 5 arasında olmalı.'; end if;
  s := nullif(btrim(coalesce(p_slogan, '')), '');
  if s is not null then s := oyun.metin_temizle(s, 80); end if;
  select * into eski from oyun.parti_kimlik where parti_id = pa.id;
  if eski.parti_id is not null and eski.guncelleme > t - interval '24 hours' and (eski.eko <> p_eko or eski.toplum <> p_toplum) then
    raise exception 'Partinin siyasi konumu günde en fazla bir kez değiştirilebilir.';
  end if;
  insert into oyun.parti_kimlik(parti_id, eko, toplum, slogan, guncelleme) values (pa.id, p_eko, p_toplum, s, t)
    on conflict (parti_id) do update set eko = excluded.eko, toplum = excluded.toplum, slogan = excluded.slogan,
      guncelleme = case when oyun.parti_kimlik.eko <> excluded.eko or oyun.parti_kimlik.toplum <> excluded.toplum then excluded.guncelleme else oyun.parti_kimlik.guncelleme end;
  if eski.parti_id is null or eski.eko <> p_eko or eski.toplum <> p_toplum then
    perform oyun.olay('parti', format('%s siyasi konumunu açıkladı: ekonomide %s, toplumsal konularda %s.', pa.ad,
      case when p_eko <= -3 then 'devletçi' when p_eko < 0 then 'sosyal devletçi' when p_eko = 0 then 'merkez' when p_eko < 3 then 'piyasa yanlısı' else 'serbest piyasacı' end,
      case when p_toplum <= -3 then 'özgürlükçü' when p_toplum < 0 then 'ılımlı özgürlükçü' when p_toplum = 0 then 'merkez' when p_toplum < 3 then 'ılımlı muhafazakâr' else 'muhafazakâr' end),
      null, pa.id, t);
  end if;
  return public.parti_kimlikleri();
end $$;

-- =====================================================================
--  Oyuncu kimliği: portre (avatar kodu) ve kısa biyografi
-- =====================================================================
create or replace function public.kimlik_guncelle(p_avatar text, p_biyografi text) returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); b text;
begin
  if p_avatar is not null and p_avatar !~ '^[0-9]{1,2}(-[0-9]{1,2}){5}$' then raise exception 'Geçersiz portre.'; end if;
  b := nullif(btrim(coalesce(p_biyografi, '')), '');
  if b is not null then b := oyun.metin_temizle(b, 160); end if;
  insert into oyun.oyuncu_kimlik(user_id, avatar, biyografi, guncelleme) values (p.id, p_avatar, b, oyun.simdi())
    on conflict (user_id) do update set avatar = excluded.avatar, biyografi = excluded.biyografi, guncelleme = excluded.guncelleme;
  return jsonb_build_object('avatar', p_avatar, 'biyografi', b);
end $$;

-- Birden çok oyuncunun portresi (sohbet, listeler). En fazla 100 ad.
create or replace function public.kimlikler(p_kadlar text[]) returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_object_agg(p.kad, jsonb_build_object('avatar', k.avatar, 'biyografi', k.biyografi,
      'aktif', case when p.son_gorulme > oyun.simdi() - interval '10 minutes' then 'cevrimici'
                    when p.son_gorulme > oyun.simdi() - interval '1 day' then 'bugun'
                    when p.son_gorulme > oyun.simdi() - interval '7 days' then 'hafta' else 'uzun' end)), '{}'::jsonb)
  from oyun.profiller p left join oyun.oyuncu_kimlik k on k.user_id = p.id
  where lower(p.kad) = any (select lower(x) from unnest(p_kadlar[1:100]) x) and not p.yasakli
$$;

-- =====================================================================
--  Seçim mitingleri: aday ilinde 1 saatlik miting düzenler, ildeki oyuncular katılır
-- =====================================================================
create or replace function oyun.miting_bedel(p_il smallint) returns numeric language sql stable set search_path = '' as $$
  select round(1500 * oyun.il_buyukluk(p_il) * coalesce((select endeks from oyun.ulke where id = 1), 1) / 100) * 100
$$;

create or replace function oyun.miting_son_an(s oyun.secimler) returns timestamptz language sql stable set search_path = '' as $$
  select coalesce((select f.oy_bit from oyun.secimler f where f.donem = s.donem and f.durum = 'bekliyor'
                     and f.tur = case s.tur when 'mv_on' then 'mv' when 'bel_on' then 'bel' when 'cb_on' then 'cb' else s.tur end
                     and f.ara = s.ara order by f.oy_bit desc limit 1), s.oy_bit)
$$;

create or replace function public.miting_duzenle(p_secim bigint, p_bas timestamptz, p_baslik text) returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); s oyun.secimler; a oyun.adaylar; b text; bedel numeric; son timestamptz; il smallint; mid bigint;
begin
  select * into s from oyun.secimler where id = p_secim;
  if s.id is null then raise exception 'Seçim bulunamadı.'; end if;
  select * into a from oyun.adaylar where secim_id = s.id and user_id = p.id;
  if a.id is null then raise exception 'Miting yalnızca bu seçimin adayları tarafından düzenlenebilir.'; end if;
  son := oyun.miting_son_an(s);
  if son <= t then raise exception 'Bu seçimin oylaması bitti.'; end if;
  if p_bas is null or p_bas < t + interval '15 minutes' then raise exception 'Mitingi en erken 15 dakika sonrasına koyabilirsin.'; end if;
  if p_bas > t + interval '3 days' then raise exception 'Mitingi en fazla 3 gün sonrasına planlayabilirsin.'; end if;
  if p_bas + interval '1 hour' > son then raise exception 'Miting oylama bitmeden sona ermeli.'; end if;
  if exists (select 1 from oyun.mitingler where user_id = p.id and secim_id = s.id) then raise exception 'Bu seçim için zaten bir miting düzenledin.'; end if;
  b := oyun.metin_temizle(p_baslik, 80);
  if length(b) < 3 then raise exception 'Miting başlığı en az 3 karakter olmalı.'; end if;
  il := coalesce(a.il_id, p.il_id);
  if exists (select 1 from oyun.mitingler m where m.il_id = il and m.bas < p_bas + interval '1 hour' and m.bit > p_bas) then
    raise exception 'Bu saatte ilde başka bir miting var. Meydan dolu; başka bir saat seç.';
  end if;
  bedel := oyun.miting_bedel(il);
  perform oyun.para_islem(p.id, -bedel, 'miting', format('%s mitingi (ses sistemi, sahne, ulaşım)', (select ad from oyun.iller where id = il)), t);
  insert into oyun.mitingler(user_id, secim_id, il_id, parti_id, baslik, bas, bit, bedel)
    values (p.id, s.id, il, p.parti_id, b, p_bas, p_bas + interval '1 hour', bedel) returning id into mid;
  perform oyun.olay('secim', format('%s, %s mitingi düzenleyecek: “%s” (%s).', p.kad,
    (select ad from oyun.iller where id = il), b, to_char(p_bas at time zone 'Europe/Istanbul', 'DD.MM HH24:MI')), il, p.parti_id, t);
  return jsonb_build_object('id', mid, 'bedel', bedel);
end $$;

create or replace function public.miting_katil(p_id bigint) returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); m oyun.mitingler; n int; odul boolean := false;
begin
  select * into m from oyun.mitingler where id = p_id;
  if m.id is null then raise exception 'Miting bulunamadı.'; end if;
  if t < m.bas then raise exception 'Miting henüz başlamadı.'; end if;
  if t >= m.bit then raise exception 'Miting sona erdi.'; end if;
  if p.il_id <> m.il_id then raise exception 'Yalnızca bu ilde yaşayan oyuncular mitinge katılabilir.'; end if;
  insert into oyun.miting_katilim(miting_id, user_id, zaman) values (m.id, p.id, t) on conflict do nothing;
  if found and m.user_id <> p.id and not exists (select 1 from oyun.miting_katilim c join oyun.mitingler x on x.id = c.miting_id
      where c.user_id = p.id and c.miting_id <> m.id and c.zaman >= oyun.bugun_bas(t) and x.user_id <> p.id) then
    update oyun.cuzdan set kidem = kidem + 1 where user_id = p.id; odul := true;   -- günde bir miting: +1 kıdem (siyasi katılım)
  end if;
  select count(*) into n from oyun.miting_katilim where miting_id = m.id;
  return jsonb_build_object('katilim', n, 'kidem', odul);
end $$;

create or replace function public.mitingler() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kad', p.kad, 'parti', oyun.parti_json(m.parti_id), 'il_id', m.il_id,
      'il', (select ad from oyun.iller where id = m.il_id), 'baslik', m.baslik, 'bas', m.bas, 'bit', m.bit,
      'katilim', (select count(*) from oyun.miting_katilim c where c.miting_id = m.id),
      'katildim', exists (select 1 from oyun.miting_katilim c where c.miting_id = m.id and c.user_id = auth.uid()),
      'benim_ilim', m.il_id = (select il_id from oyun.profiller where id = auth.uid()),
      'benim', m.user_id = auth.uid(),
      'secim_tur', (select tur from oyun.secimler where id = m.secim_id)) order by m.bas), '[]'::jsonb)
  from oyun.mitingler m join oyun.profiller p on p.id = m.user_id
  where m.bit > oyun.simdi() - interval '6 hours' and m.bas < oyun.simdi() + interval '3 days'
$$;

-- Adayın düzenleyebileceği mitingler (Gündem kartı ve aday ekranı için)
create or replace function public.miting_haklarim() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('secim_id', s.id, 'tur', s.tur, 'son', oyun.miting_son_an(s),
      'bedel', oyun.miting_bedel(coalesce(a.il_id, p.il_id)), 'il', (select ad from oyun.iller where id = coalesce(a.il_id, p.il_id)),
      'duzenledi', exists (select 1 from oyun.mitingler m where m.user_id = p.id and m.secim_id = s.id)) order by s.id), '[]'::jsonb)
  from oyun.adaylar a join oyun.secimler s on s.id = a.secim_id join oyun.profiller p on p.id = a.user_id
  where a.user_id = auth.uid() and s.durum = 'bekliyor' and oyun.miting_son_an(s) > oyun.simdi() + interval '75 minutes'
$$;

create or replace function oyun.miting_tick(t timestamptz) returns void language plpgsql set search_path = '' as $$
declare m record; n int;
begin
  for m in select x.*, p.kad, i.ad il_ad from oyun.mitingler x join oyun.profiller p on p.id = x.user_id join oyun.iller i on i.id = x.il_id
           where not x.duyuruldu and x.bas <= t and x.bit > t loop
    update oyun.mitingler set duyuruldu = true where id = m.id;
    insert into oyun.bildirimler(user_id, zaman, metin)
      select pr.id, t, format('%s şu an %s mitinginde: “%s”. Bir saat içinde Gündem''den katılabilirsin.', m.kad, m.il_ad, m.baslik)
      from oyun.profiller pr where pr.il_id = m.il_id and pr.id <> m.user_id and not pr.yasakli;
    if oyun.push_acik() then
      perform oyun.push_konuya('s_il_' || m.il_id, null, format('%s meydanda!', m.kad),
        format('%s mitingi başladı: “%s”. Katılmak için dokun.', m.il_ad, m.baslik), jsonb_build_object('ekran', 'gundem'));
    end if;
  end loop;
  for m in select x.*, p.kad, i.ad il_ad from oyun.mitingler x join oyun.profiller p on p.id = x.user_id join oyun.iller i on i.id = x.il_id
           where not x.sonuc_yazildi and x.bit <= t loop
    select count(*) into n from oyun.miting_katilim where miting_id = m.id;
    update oyun.mitingler set sonuc_yazildi = true, duyuruldu = true where id = m.id;
    perform oyun.olay('secim', format('%s, %s mitinginde %s kişiye seslendi: “%s”.', m.kad, m.il_ad, n, m.baslik), m.il_id, m.parti_id, t);
    perform oyun.bildir(m.user_id, format('%s mitingin sona erdi: %s kişi katıldı.', m.il_ad, n), t);
  end loop;
end $$;

-- =====================================================================
--  Yetkiler
-- =====================================================================
do $$
declare f text;
begin
  foreach f in array array['aktarim_hakki()','ilk_adimlar()','tarih_arsivi()','parti_kimlikleri()','parti_kimlik_ayarla(int,int,text)',
    'kimlik_guncelle(text,text)','kimlikler(text[])','miting_duzenle(bigint,timestamptz,text)','miting_katil(bigint)','mitingler()',
    'miting_haklarim()','admin_transferler_sayfa(integer,integer,text,numeric)','para_gonder(text,numeric,text)','meclis()','harita()',
    'admin_kurallar(jsonb)','vatandaslik()','oy_ver(bigint,bigint)','il_detay(integer)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- =====================================================================
--  Veri güncellemeleri (tekrar çalıştırılınca bir şey değiştirmez)
-- =====================================================================
-- Kumbara: 16 saat (yasayla 12–24 arası değiştirilebilir). Kabul edilmiş bir yasa değeri varsa ona dokunulmaz.
update oyun.duzenleme_tanim set varsayilan = 16, min = 12, max = 24, adim = 1,
  aciklama = 'Maaşın en fazla kaç saat birikir. Günde bir kez giren oyuncu kaybetmesin diye 16 saat.'
where kod = 'kumbara_saat' and (varsayilan, min, max) is distinct from (16::numeric, 12::numeric, 24::numeric);

-- Henüz kapanmamış seçimlerin sandık saatleri: 08:00–22:00, sonuç 22:30 (ara seçimde göreve başlama 23:00)
update oyun.secimler s set
  oy_bit   = oyun.tr_an((s.oy_bas at time zone 'Europe/Istanbul')::date, 22),
  sonuc_at = oyun.tr_an((s.oy_bas at time zone 'Europe/Istanbul')::date, 22, 30),
  goreve_bas = case when s.goreve_bas is not null and extract(hour from s.goreve_bas at time zone 'Europe/Istanbul') = 19
                    then oyun.tr_an((s.goreve_bas at time zone 'Europe/Istanbul')::date, 23) else s.goreve_bas end
where s.durum = 'bekliyor' and s.oy_bit > oyun.simdi()
  and extract(hour from s.oy_bit at time zone 'Europe/Istanbul') = 17;

-- Henüz açılmamış aday adaylığı başvuruları 3 güne çıkar
update oyun.secimler s set basvuru_bas = greatest(oyun.simdi(), s.basvuru_bas - interval '2 days')
where s.durum = 'bekliyor' and not s.ara and s.tur in ('bel_on','mv_on') and s.basvuru_bas > oyun.simdi()
  and extract(day from s.basvuru_bas at time zone 'Europe/Istanbul') in (6, 26);
update oyun.secimler s set basvuru_bit = s.basvuru_bit + interval '1 day'
where s.durum = 'bekliyor' and not s.ara and s.tur = 'cb_on' and s.basvuru_bit > oyun.simdi()
  and extract(day from s.basvuru_bit at time zone 'Europe/Istanbul') = 27;

-- Genel başkansız kalan partide otomatik halef: önce son 7 günde oyuna girmiş üyeler arasından en kıdemlisi
CREATE OR REPLACE FUNCTION oyun.gb_halef(t timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare pa record; aday uuid;
begin
  for pa in select id, ad from oyun.partiler where not kapali and gb is null loop
    select pr.id into aday from oyun.profiller pr
     where pr.parti_id = pa.id and not pr.yasakli
       and not exists (select 1 from oyun.makamlar m where m.user_id = pr.id and m.bit is null and m.tur not in ('cb','mv'))
     order by (coalesce(pr.son_gorulme, pr.olusturma) > t - interval '7 days') desc, oyun.kidem_puani(pr.id) desc, pr.parti_at, pr.id limit 1;
    continue when aday is null;
    delete from oyun.parti_gby where user_id = aday;       -- genel başkan aynı zamanda yardımcı olamaz
    update oyun.partiler set gb = aday where id = pa.id and gb is null;
    perform oyun.bildir(aday, format('%s kurultayda genel başkansız kaldığı için kıdemin en yüksek olduğu üye olarak genel başkan oldun. Bir sonraki kurultayda üyeler genel başkanı yeniden seçecek; 6 genel başkan yardımcını atayabilirsin.', pa.ad), t);
    perform oyun.olay('parti', format('%s genel başkansız kaldı; kıdemi en yüksek üye %s genel başkan oldu.', pa.ad, (select kad from oyun.profiller where id = aday)), null, pa.id, t);
  end loop;
end $function$;

-- HATA DÜZELTMESİ: genel seçim sayımı "l.aday_id is ambiguous" hatasıyla duruyordu (ilk genel seçimde motor kilitlenirdi)
CREATE OR REPLACE FUNCTION oyun._sonuc_mv(s oyun.secimler)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  baraj numeric:=(select baraj from oyun.ayarlar where id=1);
  onsecim oyun.secimler;
  toplam bigint;
  il record;
  l record;
  k int;
  ana bigint;
  iller_j jsonb:='{}'::jsonb;
  ilj jsonb;
  bos int:=0;
  dolu int:=0;
  sandalye_top int;
  bag_oy bigint;
  bag_sandalye int;
begin
  select * into onsecim from oyun.secimler where tur='mv_on' and donem=s.donem;
  select count(*) into toplam from oyun.oylar where secim_id=s.id;
  sandalye_top:=coalesce((select sum(mv_secim) from oyun.iller),600);

  create temp table if not exists _b23_ulusal(
    parti_id bigint primary key,
    oy bigint,
    yuzde numeric,
    gecti boolean,
    sandalye int default 0
  ) on commit drop;
  delete from _b23_ulusal;

  insert into _b23_ulusal(parti_id,oy)
  select parti_id,count(*)
  from oyun.oylar
  where secim_id=s.id and parti_id is not null
  group by parti_id;

  update _b23_ulusal
  set yuzde=case when toplam>0 then round(oy*100.0/toplam,2) else 0 end;

  update _b23_ulusal u
  set gecti=(u.yuzde>=baraj) or coalesce((
    select sum(u2.oy)*100.0/nullif(toplam,0)>=baraj
    from oyun.ittifak_uyeler iu
    join oyun.ittifak_uyeler iu2 on iu2.ittifak_id=iu.ittifak_id
    join _b23_ulusal u2 on u2.parti_id=iu2.parti_id
    where iu.parti_id=u.parti_id
  ),false);

  create temp table if not exists _b23_kaz(
    user_id uuid,
    il_id smallint,
    parti_id bigint,
    aday_id bigint
  ) on commit drop;
  delete from _b23_kaz;

  create temp table if not exists _b23_liste(
    anahtar bigint primary key,
    parti_id bigint,
    aday_id bigint,
    oy bigint,
    lim int,
    kaz int default 0
  ) on commit drop;

  for il in select * from oyun.iller order by id loop
    delete from _b23_liste;

    insert into _b23_liste(anahtar,parti_id,aday_id,oy,lim)
    select x.parti_id,x.parti_id,null,x.oy,x.lim
    from (
      select o.parti_id,
             count(*)::bigint oy,
             (select count(*)
              from oyun.adaylar a
              where a.secim_id=onsecim.id
                and a.il_id=il.id
                and a.parti_id=o.parti_id
                and a.sira is not null)::int lim
      from oyun.oylar o
      join _b23_ulusal u on u.parti_id=o.parti_id and u.gecti
      where o.secim_id=s.id and o.il_id=il.id and o.parti_id is not null
      group by o.parti_id
    ) x
    where x.lim>0 and x.oy>0;

    insert into _b23_liste(anahtar,parti_id,aday_id,oy,lim)
    select -a.id,null,a.id,count(o.*)::bigint,1
    from oyun.adaylar a
    join oyun.oylar o
      on o.secim_id=s.id and o.aday_id=a.id
    where a.secim_id=s.id
      and a.parti_id is null
      and a.il_id=il.id
    group by a.id
    having count(o.*)>0;

    for k in 1..coalesce(il.mv_secim,il.mv) loop
      ana:=null;
      select anahtar into ana
      from _b23_liste
      where kaz<lim and oy>0
      order by oy::numeric/(kaz+1) desc,oy desc,anahtar
      limit 1;
      exit when ana is null;
      update _b23_liste set kaz=kaz+1 where anahtar=ana;
    end loop;

    for l in select * from _b23_liste where parti_id is not null and kaz>0 loop
      insert into _b23_kaz(user_id,il_id,parti_id,aday_id)
      select a.user_id,il.id,l.parti_id,a.id
      from oyun.adaylar a
      where a.secim_id=onsecim.id
        and a.il_id=il.id
        and a.parti_id=l.parti_id
        and a.sira is not null
      order by a.sira
      limit l.kaz;

      update _b23_ulusal set sandalye=sandalye+l.kaz where parti_id=l.parti_id;
    end loop;

    insert into _b23_kaz(user_id,il_id,parti_id,aday_id)
    select a.user_id,il.id,null,a.id
    from _b23_liste bl                      -- "l" kayıt değişkeniyle çakışmasın (aday_id belirsizliği hatası)
    join oyun.adaylar a on a.id=bl.aday_id
    where bl.parti_id is null and bl.kaz>0;

    select jsonb_build_object(
      'gecerli',(select count(*) from oyun.oylar where secim_id=s.id and il_id=il.id),
      'partiler',coalesce((
        select jsonb_object_agg(o.parti_id::text,jsonb_build_object(
          'oy',o.n,
          'sandalye',(select count(*) from _b23_kaz z where z.il_id=il.id and z.parti_id=o.parti_id)
        ))
        from (
          select parti_id,count(*) n
          from oyun.oylar
          where secim_id=s.id and il_id=il.id and parti_id is not null
          group by parti_id
        ) o
      ),'{}'::jsonb),
      'bagimsizlar',coalesce((
        select jsonb_agg(jsonb_build_object(
          'aday_id',a.id,
          'kad',pr.kad,
          'oy',(select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id),
          'sandalye',case when exists(select 1 from _b23_kaz z where z.aday_id=a.id) then 1 else 0 end
        ) order by (select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id) desc,a.id)
        from oyun.adaylar a
        join oyun.profiller pr on pr.id=a.user_id
        where a.secim_id=s.id and a.parti_id is null and a.il_id=il.id
      ),'[]'::jsonb),
      'secilen',coalesce((
        select jsonb_agg(jsonb_build_object(
          'kad',pr.kad,
          'parti_id',z.parti_id,
          'bagimsiz',z.parti_id is null
        ) order by z.parti_id nulls last,pr.kad)
        from _b23_kaz z
        join oyun.profiller pr on pr.id=z.user_id
        where z.il_id=il.id
      ),'[]'::jsonb),
      'mv',coalesce(il.mv_secim,il.mv)
    ) into ilj;

    if (ilj->>'gecerli')::int>0 or jsonb_array_length(ilj->'secilen')>0 then
      iller_j:=iller_j||jsonb_build_object(il.id::text,ilj);
    end if;
  end loop;

  insert into oyun.kazananlar(secim_id,user_id,il_id,parti_id)
  select s.id,user_id,il_id,parti_id from _b23_kaz
  on conflict do nothing;

  select count(*) into dolu from _b23_kaz;
  bos:=sandalye_top-dolu;
  select count(*) into bag_oy
  from oyun.oylar where secim_id=s.id and parti_id is null and aday_id is not null;
  select count(*) into bag_sandalye
  from _b23_kaz where parti_id is null;

  perform oyun.olay(
    'secim',
    format('Genel seçim sonuçlandı: %s oy kullanıldı, %s sandalye doldu, %s sandalye boş kaldı.',toplam,dolu,bos),
    null,null,s.sonuc_at
  );

  return jsonb_build_object(
    'toplam',toplam,
    'baraj',baraj,
    'sandalye_toplam',sandalye_top,
    'dolu',dolu,
    'bos',bos,
    'bagimsiz_oy',bag_oy,
    'bagimsiz_sandalye',bag_sandalye,
    'bagimsizlar',coalesce((
      select jsonb_agg(jsonb_build_object(
        'aday_id',a.id,
        'kad',pr.kad,
        'il_id',a.il_id,
        'oy',(select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id),
        'sandalye',case when exists(select 1 from _b23_kaz z where z.aday_id=a.id) then 1 else 0 end
      ) order by (select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id) desc,a.id)
      from oyun.adaylar a
      join oyun.profiller pr on pr.id=a.user_id
      where a.secim_id=s.id and a.parti_id is null
    ),'[]'::jsonb),
    'ulusal',coalesce((
      select jsonb_agg(jsonb_build_object(
        'parti_id',u.parti_id,
        'kisa',p.kisa,
        'ad',p.ad,
        'renk',p.renk,
        'oy',u.oy,
        'yuzde',u.yuzde,
        'gecti',u.gecti,
        'sandalye',u.sandalye
      ) order by u.oy desc)
      from _b23_ulusal u
      join oyun.partiler p on p.id=u.parti_id
    ),'[]'::jsonb),
    'iller',iller_j
  );
end $function$;

-- HATA DÜZELTMESİ: yedekten dönüş, "generated always" kimlik sütunlu tablolarda (8 Ekim'den beri) hata veriyordu
create or replace function oyun.yedekten_don(p_sema text, p_onay text) returns text language plpgsql as $$
declare y text; t record; liste text; kalan text[]; tur int := 0; sutunlar text; ok boolean; n int;
begin
  if p_onay is distinct from 'GERİ YÜKLE' then
    raise exception 'Geri yüklemek için: select oyun.yedekten_don(''%'', ''GERİ YÜKLE'');', p_sema;
  end if;
  if p_sema !~ '^yedek_' or not exists (select 1 from pg_namespace where nspname = p_sema) then raise exception 'Yedek bulunamadı: %', p_sema; end if;
  y := oyun.yedek_al('Geri yükleme öncesi');
  perform set_config('oyun.sifirlama', 'evet', true);
  select array_agg(c.relname::text) into kalan from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'oyun' and c.relkind = 'r' and c.relname <> 'surumler'
     and exists (select 1 from pg_class c2 join pg_namespace n2 on n2.oid = c2.relnamespace where n2.nspname = p_sema and c2.relname = c.relname);
  select string_agg(format('oyun.%I', x), ', ') into liste from unnest(kalan) x;
  execute 'truncate ' || liste || ' cascade';
  foreach liste in array kalan loop execute format('alter table oyun.%I disable trigger user', liste); end loop;
  -- yabancı anahtar sırası bilinmediği için birkaç turda yükle
  while array_length(kalan, 1) > 0 and tur < 10 loop
    tur := tur + 1;
    foreach liste in array kalan loop
      select string_agg(format('%I', a.attname), ', ') into sutunlar
        from pg_attribute a join pg_class c on c.oid = a.attrelid join pg_namespace n on n.oid = c.relnamespace
       where n.nspname = 'oyun' and c.relname = liste and a.attnum > 0 and not a.attisdropped and a.attgenerated = ''
         and exists (select 1 from pg_attribute b join pg_class c2 on c2.oid = b.attrelid join pg_namespace n2 on n2.oid = c2.relnamespace
                     where n2.nspname = p_sema and c2.relname = liste and b.attname = a.attname and not b.attisdropped);
      ok := true;
      begin
        -- overriding system value: "generated always as identity" sütunlu tablolar da yedekten dönebilsin
        execute format('insert into oyun.%I (%s) overriding system value select %s from %I.%I', liste, sutunlar, sutunlar, p_sema, liste);
      exception when foreign_key_violation then ok := false;
      end;
      if ok then kalan := array_remove(kalan, liste); end if;
    end loop;
  end loop;
  for t in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'oyun' and c.relkind = 'r' loop
    execute format('alter table oyun.%I enable trigger user', t.relname);
  end loop;
  if array_length(kalan, 1) > 0 then raise exception 'Geri yükleme tamamlanamadı (%); hiçbir şey değişmedi.', array_to_string(kalan, ', '); end if;
  -- kimlik sayaçlarını yedekteki en büyük değere getir
  for t in select s.relname seq, tc.relname tablo, a.attname sutun from pg_class s
             join pg_depend d on d.objid = s.oid and d.deptype in ('a','i') join pg_class tc on tc.oid = d.refobjid
             join pg_attribute a on a.attrelid = tc.oid and a.attnum = d.refobjsubid join pg_namespace n on n.oid = tc.relnamespace
            where s.relkind = 'S' and n.nspname = 'oyun' loop
    execute format('select coalesce(max(%I), 0) from oyun.%I', t.sutun, t.tablo) into n;
    if n > 0 then execute format('select setval(%L, %s)', 'oyun.' || t.seq, n); end if;
  end loop;
  return format('%s yedeğine dönüldü. Dönüş öncesi durumun yedeği: %s', p_sema, y);
end $$;
-- 2026-10-09 - Portre ozellestirme: daha fazla erkek sac/sakal ve bagimsiz sac rengi.
-- Eski 6 bolumlu avatarlar gecerli kalir; yeni kodda 7. bolum sac rengidir.
alter table oyun.oyuncu_kimlik
  drop constraint if exists oyuncu_kimlik_avatar_check;
alter table oyun.oyuncu_kimlik
  add constraint oyuncu_kimlik_avatar_check
  check (avatar ~ '^[0-9]{1,2}(-[0-9]{1,2}){5,6}$');

create or replace function public.kimlik_guncelle(p_avatar text, p_biyografi text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); b text;
begin
  if p_avatar is not null and p_avatar !~ '^[0-9]{1,2}(-[0-9]{1,2}){5,6}$' then
    raise exception 'Geçersiz portre.';
  end if;
  b := nullif(btrim(coalesce(p_biyografi, '')), '');
  if b is not null then b := oyun.metin_temizle(b, 160); end if;
  insert into oyun.oyuncu_kimlik(user_id, avatar, biyografi, guncelleme)
    values (p.id, p_avatar, b, oyun.simdi())
    on conflict (user_id) do update
      set avatar = excluded.avatar, biyografi = excluded.biyografi, guncelleme = excluded.guncelleme;
  return jsonb_build_object('avatar', p_avatar, 'biyografi', b);
end $$;
revoke all on function public.kimlik_guncelle(text,text) from public,anon;
grant execute on function public.kimlik_guncelle(text,text) to authenticated;
-- 2026-10-09 | Seçmen ilk görevleri, ideolojiler, davetli kurucular kurulu
-- Canlı verileri sıfırlamaz. Eski partiler korunur. Tekrar çalıştırılabilir.
begin;
alter table oyun.ayarlar add column if not exists ilk_gorev_oy_bas timestamptz not null default now();
alter table oyun.parti_kimlik add column if not exists ideolojiler text[] not null default '{}';

create or replace function oyun.ideoloji_gecerli(v text[]) returns boolean
language sql immutable set search_path = '' as $$
 select v is not null and cardinality(v) between 1 and 3
 and not exists (select 1 from unnest(v) x where x not in
 ('merkez_sag','merkez_sol','sosyal_demokrat','muhafazakar','liberal','milliyetci','turk_milliyetcisi','sosyalist','kemalist','islamci','demokratik_sol','yesil_siyaset','populist','karma'))
 and cardinality(v)=(select count(distinct x) from unnest(v) x)
$$;
create table if not exists oyun.kurucu_basvuru(
 id bigint generated always as identity primary key,
 kurucu uuid not null references oyun.profiller(id),
 ad text not null, kisa text not null, renk text not null, amblem text not null,
 ideolojiler text[] not null check (oyun.ideoloji_gecerli(ideolojiler)),
 bas timestamptz not null default now(), bit timestamptz not null,
 durum text not null default 'bekliyor' check(durum in ('bekliyor','kuruldu','iptal','suresi_doldu')),
 parti_id bigint references oyun.partiler(id)
);
create unique index if not exists kurucu_aktif_tek on oyun.kurucu_basvuru(kurucu) where durum='bekliyor';
create unique index if not exists kurucu_aktif_ad on oyun.kurucu_basvuru(lower(ad)) where durum='bekliyor';
create unique index if not exists kurucu_aktif_kisa on oyun.kurucu_basvuru(lower(kisa)) where durum='bekliyor';
create table if not exists oyun.kurucu_davet(
 basvuru_id bigint not null references oyun.kurucu_basvuru(id) on delete cascade,
 user_id uuid not null references oyun.profiller(id) on delete cascade,
 durum text not null default 'bekliyor' check (durum in ('bekliyor','evet','hayir')),
 zaman timestamptz not null default now(), cevap_at timestamptz,
 primary key (basvuru_id,user_id)
);
create index if not exists kurucu_davet_user on oyun.kurucu_davet(user_id,durum);
create table if not exists oyun.ideoloji_teklif(
 id bigint generated always as identity primary key,
 parti_id bigint not null references oyun.partiler(id) on delete cascade,
 kurucu uuid not null references oyun.profiller(id),
 ideolojiler text[] not null check (oyun.ideoloji_gecerli(ideolojiler)),
 bas timestamptz not null default now(), bit timestamptz not null,
 durum text not null default 'acik' check (durum in ('acik','kabul','red'))
);
create table if not exists oyun.ideoloji_secmen(
 teklif_id bigint not null references oyun.ideoloji_teklif(id) on delete cascade,
 user_id uuid not null references oyun.profiller(id) on delete cascade,
 oy boolean,
 zaman timestamptz,
 primary key (teklif_id,user_id)
);
do $$ declare t text; begin
 foreach t in array array['kurucu_basvuru','kurucu_davet','ideoloji_teklif','ideoloji_secmen'] loop
  execute format('alter table oyun.%I enable row level security', t);
  execute format('revoke all on oyun.%I from public, anon, authenticated', t);
 end loop;
end $$;

-- Eski hesaplar etkilenmez; bu güncellemeden sonra gelenler ilk 3 görevi tamamlar.
create or replace function oyun.ilk_uc_gorev(p oyun.profiller)
returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object(
  'gerekli',p.olusturma >= (select ilk_gorev_oy_bas from oyun.ayarlar where id=1),
  'maas', exists (select 1 from oyun.hesap_hareket h where h.user_id=p.id and h.tur='maas'),
  'kimlik', exists (select 1 from oyun.oyuncu_kimlik k where k.user_id=p.id and k.avatar is not null and nullif(btrim(coalesce(k.biyografi,'')),'') is not null),
  'kahve', exists (select 1 from oyun.mesajlar m where m.user_id=p.id and m.kanal like 'il:%'))
$$;
create or replace function oyun.ilk_uc_gorev_engel(p oyun.profiller)
returns text language plpgsql stable set search_path='' as $$
declare d jsonb := oyun.ilk_uc_gorev(p); eksik text[] := '{}';
begin
 if not (d->>'gerekli')::boolean then return null; end if;
 if not (d->>'maas')::boolean then eksik:=array_append(eksik,'ilk maaşını toplamak'); end if;
 if not (d->>'kimlik')::boolean then eksik:=array_append(eksik,'portre ve biyografi hazırlamak'); end if;
 if not (d->>'kahve')::boolean then eksik:=array_append(eksik,'il kahvesine mesaj yazmak'); end if;
 if cardinality(eksik)>0 then return 'İlk oyun için 3 başlangıç görevini tamamla: '||array_to_string(eksik,', ')||'.'; end if;
 return null;
end $$;

-- Ana seçim ön koşulu: sunucuda denetlenir, istemci tarafından atlanamaz.
create or replace function oyun.oy_engeli(p oyun.profiller,s oyun.secimler)
returns text language sql stable set search_path='' as $$
 select coalesce(
  oyun.uyari(p,s.oy_bas),
  oyun.ilk_uc_gorev_engel(p),
  case when s.ara and s.hedef_il_id is not null and p.il_id is distinct from s.hedef_il_id
    then format('Bu olağanüstü seçim yalnızca %s ili içindir.',(select ad from oyun.iller where id=s.hedef_il_id)) end,
  case when s.ara and s.hedef_parti_id is not null and p.parti_id is distinct from s.hedef_parti_id
    then format('Bu olağanüstü kurultay yalnızca %s üyeleri içindir.',(select kisa from oyun.partiler where id=s.hedef_parti_id)) end,
  case when s.tur in ('mv','bel','mv_on','bel_on') and p.son_il_degis is not null
    and p.il_at > s.oy_bas - make_interval(days=>(select oy_il_gun from oyun.ayarlar where id=1))
    then format('Seçmen kütüğü: bu ilde en az %s gün kayıtlı olmalısın.',(select oy_il_gun from oyun.ayarlar where id=1)) end,
  case when s.tur in ('mv_on','bel_on','kurultay','cb_on') then
    case when p.parti_id is null then 'Bu parti içi seçimde parti üyesi olmalısın.'
      when p.parti_at > s.basvuru_bas then 'Başvurular açılmadan önce parti üyesi olmalısın.' end end)
$$;

create or replace function public.ilk_adimlar() returns jsonb
language plpgsql security definer set search_path='' as $$
declare p oyun.profiller:=oyun.profilim(); t timestamptz:=oyun.simdi(); d jsonb:=oyun.ilk_uc_gorev(p); u text;
adimlar jsonb;
begin
 u:=coalesce(oyun.uyari(p,t),oyun.ilk_uc_gorev_engel(p));
 adimlar:=jsonb_build_array(
 jsonb_build_object('kod','maas','ad','İlk maaşını topla','tamam',(d->>'maas')::boolean),
 jsonb_build_object('kod','kimlik','ad','Portreni ve kısa biyografini hazırla','tamam',(d->>'kimlik')::boolean),
 jsonb_build_object('kod','parti','ad','Bir partiye katıl','tamam',p.parti_id is not null),
 jsonb_build_object('kod','sohbet','ad','İl kahvesinde kendini tanıt','tamam',(d->>'kahve')::boolean),
 jsonb_build_object('kod','anket','ad','Haftalık siyasi ankete katıl','tamam',exists(select 1 from oyun.haftalik_anket_oy where user_id=p.id)),
 jsonb_build_object('kod','oy','ad','İlk oyunu kullan','tamam',exists(select 1 from oyun.oylar where secmen=p.id),'not',u));
 return jsonb_build_object('adimlar',adimlar,'secmen_karti',u is null,'engel',u,
 'oy_gorevleri',d,'yeni',p.olusturma > t-interval '14 days',
 'bitti',not exists(select 1 from jsonb_array_elements(adimlar) x where not (x->>'tamam')::boolean));
end $$;

-- Herkese açık seçimler için siyasi kimlik listesi; eski eko/toplum alanları korunur.
create or replace function public.parti_kimlikleri() returns jsonb
language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('parti',oyun.parti_json(pa.id),
  'ideolojiler',coalesce(k.ideolojiler,'{}'::text[]),
  'eko',coalesce(k.eko,0),'toplum',coalesce(k.toplum,0),'belirlendi',k.parti_id is not null,
  'slogan',k.slogan,
  'uye',(select count(*) from oyun.profiller pr where pr.parti_id=pa.id and not pr.yasakli),
  'vekil',(select count(*) from oyun.makamlar m where m.tur='mv' and m.bit is null and m.parti_id=pa.id),
  'gb',oyun.kad(pa.gb)) order by pa.id),'[]'::jsonb)
 from oyun.partiler pa left join oyun.parti_kimlik k on k.parti_id=pa.id where not pa.kapali
$$;

-- Genel başkan tüm mevcut üyelere 48 saatlik ideoloji değişikliği teklifi sunar.
create or replace function public.ideoloji_teklif_ver(p_ideolojiler text[]) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p oyun.profiller:=oyun.profilim(); pa oyun.partiler; idd bigint; t timestamptz:=oyun.simdi(); k uuid;
begin
 if not oyun.ideoloji_gecerli(p_ideolojiler) then raise exception 'En az 1, en çok 3 farklı ideoloji seçmelisin.'; end if;
 select * into pa from oyun.partiler where gb=p.id and not kapali and kurulus_bit is null for update;
 if pa.id is null then raise exception 'Yalnızca aktif partinin genel başkanı ideoloji oylaması açabilir.'; end if;
 if exists(select 1 from oyun.ideoloji_teklif where parti_id=pa.id and durum='acik' and bit>t) then
  raise exception 'Partinin devam eden bir ideoloji oylaması var.'; end if;
 if coalesce((select ideolojiler from oyun.parti_kimlik where parti_id=pa.id),'{}'::text[])=p_ideolojiler then
  raise exception 'Bu ideolojiler partide zaten geçerli.'; end if;
 insert into oyun.ideoloji_teklif(parti_id,kurucu,ideolojiler,bas,bit)
  values(pa.id,p.id,p_ideolojiler,t,t+interval '48 hours') returning id into idd;
 insert into oyun.ideoloji_secmen(teklif_id,user_id)
  select idd,id from oyun.profiller where parti_id=pa.id and not yasakli;
 for k in select user_id from oyun.ideoloji_secmen where teklif_id=idd loop
  perform oyun.bildir(k,format('%s genel başkanı parti ideolojilerini oylamaya sundu. 48 saat içinde oyunu kullan.',pa.ad),t);
 end loop;
 return jsonb_build_object('teklif_id',idd);
end $$;
create or replace function public.ideoloji_oyla(p_teklif bigint,p_evet boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p oyun.profiller:=oyun.profilim(); o oyun.ideoloji_teklif; uyeler int; evetler int; hayirlar int; t timestamptz:=oyun.simdi();
begin
 select * into o from oyun.ideoloji_teklif where id=p_teklif for update;
 if o.id is null or o.durum<>'acik' or o.bit<=t then raise exception 'Bu oylama kapanmış.'; end if;
 if p.parti_id is distinct from o.parti_id then raise exception 'Yalnızca parti üyesi oy kullanabilir.'; end if;
 if p_evet is null then raise exception 'Geçerli bir EVET veya HAYIR oyu seçmelisin.'; end if;
 update oyun.ideoloji_secmen set oy=p_evet,zaman=t
  where teklif_id=o.id and user_id=p.id and oy is null;
 if not found then raise exception 'Bu oylamada oy hakkın yok veya oyunu zaten kullandın.'; end if;
 select count(*),count(*) filter(where oy is true),count(*) filter(where oy is false)
 into uyeler,evetler,hayirlar from oyun.ideoloji_secmen where teklif_id=o.id;
 if evetler>uyeler/2 then
  insert into oyun.parti_kimlik(parti_id,ideolojiler,guncelleme)
   values(o.parti_id,o.ideolojiler,t)
   on conflict(parti_id) do update set ideolojiler=excluded.ideolojiler,guncelleme=t;
  update oyun.ideoloji_teklif set durum='kabul' where id=o.id;
  perform oyun.olay('parti',format('%s üyelerinin çoğunluk oyuyla yeni ideolojilerini kabul etti.',(select ad from oyun.partiler where id=o.parti_id)),null,o.parti_id,t);
 elsif hayirlar>=ceil(uyeler/2.0) then
  update oyun.ideoloji_teklif set durum='red' where id=o.id;
 end if;
 return jsonb_build_object('evet',evetler,'hayir',hayirlar,'gerekli',floor(uyeler/2.0)+1,'durum',(select durum from oyun.ideoloji_teklif where id=o.id));
end $$;
create or replace function public.ideoloji_durum(p_parti bigint) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object(
 'ideolojiler',coalesce((select ideolojiler from oyun.parti_kimlik where parti_id=p_parti),'{}'::text[]),
 'teklif',(select jsonb_build_object('id',o.id,'ideolojiler',o.ideolojiler,'bit',o.bit,
   'gerekli',(select floor(count(*)/2.0)::int+1 from oyun.ideoloji_secmen v where v.teklif_id=o.id),
   'evet',(select count(*) from oyun.ideoloji_secmen v where v.teklif_id=o.id and v.oy=true),
   'hayir',(select count(*) from oyun.ideoloji_secmen v where v.teklif_id=o.id and v.oy=false),
   'benim_oyum',(select v.oy from oyun.ideoloji_secmen v where v.teklif_id=o.id and v.user_id=auth.uid()),
   'oy_hakkim',exists(select 1 from oyun.ideoloji_secmen v where v.teklif_id=o.id and v.user_id=auth.uid()),
   'durum',case when o.durum='acik' and o.bit<=oyun.simdi() then 'red' else o.durum end)
  from oyun.ideoloji_teklif o where o.parti_id=p_parti order by o.id desc limit 1))
$$;

-- Doğrudan eski parti_kur yolunu kapat: davetsiz kuruluş mümkün olmasın.
create or replace function public.parti_kur(p_ad text,p_kisa text,p_renk text,p_amblem text)
returns jsonb language plpgsql security definer set search_path='' as $$
begin
 raise exception 'Yeni parti kurmak için önce kurucu davetleri gönder, en az 3 onay al.';
end $$;

create or replace function public.parti_kur_baslat(p_ad text,p_kisa text,p_renk text,p_amblem text,
  p_ideolojiler text[],p_kadlar text[]) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p oyun.profiller:=oyun.profilim(); t timestamptz:=oyun.simdi(); idd bigint; nick text; hedef oyun.profiller; sayi int:=0;
begin
 p_ad:=btrim(regexp_replace(coalesce(p_ad,''),'\s+',' ','g'));
 p_kisa:=upper(btrim(coalesce(p_kisa,'')));
 if length(p_ad) not between 5 and 40 or p_ad !~ '^[A-Za-zçğıöşüÇĞİÖŞÜâîûÂÎÛ'' .-]+$' then raise exception 'Parti adı 5-40 harften oluşmalı.'; end if;
 if p_kisa !~ '^[A-ZÇĞİÖŞÜ]{2,6}$' or p_renk !~ '^#[0-9a-fA-F]{6}$' or p_amblem !~ '^[a-z_]{2,20}$' then raise exception 'Kısaltma, renk veya amblem geçersiz.'; end if;
 if not oyun.ideoloji_gecerli(p_ideolojiler) then raise exception 'En az 1 en çok 3 ideoloji seç.'; end if;
 if coalesce(cardinality(p_kadlar),0) not between 3 and 20 then raise exception 'En az 3, en çok 20 farklı kurucu adayı davet et.'; end if;
 if oyun.yasakli_ad(p_ad) or oyun.yasakli_kisa(p_kisa) then raise exception 'Gerçek bir partiyi çağrıştıran ad kullanılamaz.'; end if;
 if exists(select 1 from oyun.partiler where not kapali and (lower(ad)=lower(p_ad) or lower(kisa)=lower(p_kisa))) then raise exception 'Parti adı veya kısaltması kullanımda.'; end if;
 if oyun.uyari(p,t) is not null then raise exception 'Parti kurma şartı: %',oyun.uyari(p,t); end if;
 if oyun.kidem_puani(p.id)<(select parti_kurucu_kidem from oyun.ayarlar where id=1) then raise exception 'Parti kurma kıdemin yetersiz.'; end if;
 if p.son_parti_kur is not null and p.son_parti_kur+make_interval(days=>(select parti_kur_gun from oyun.ayarlar where id=1))>t then
   raise exception 'Yeni parti kurmak için bekleme süren dolmalı.'; end if;
 if (select para from oyun.cuzdanim(p.id))<greatest(25000,oyun.parti_kur_ucreti()) then raise exception 'Parti için en az % ₺ sermaye gerekli.', oyun.tl(greatest(25000,oyun.parti_kur_ucreti())); end if;
 -- Yedi günlük süresi geçmiş başvuruları kapat; yeni başvuruyu engellemesinler.
 update oyun.kurucu_basvuru set durum='suresi_doldu' where durum='bekliyor' and bit<=t;
 insert into oyun.kurucu_basvuru(kurucu,ad,kisa,renk,amblem,ideolojiler,bas,bit)
 values(p.id,p_ad,p_kisa,lower(p_renk),p_amblem,p_ideolojiler,t,t+interval '7 days')
 returning id into idd;
 foreach nick in array p_kadlar loop
  nick:=btrim(nick);
  select * into hedef from oyun.profiller where lower(kad)=lower(nick) and not yasakli;
  if hedef.id is null or hedef.id=p.id then raise exception 'Kurucu adayı bulunamadı veya kendini davet ettin: %',nick; end if;
  insert into oyun.kurucu_davet(basvuru_id,user_id,zaman) values(idd,hedef.id,t)
   on conflict do nothing;
  if found then
   sayi:=sayi+1;
   perform oyun.bildir(hedef.id,format('%s seni %s (%s) partisinin kurucular kuruluna davet etti. Partiler > Kurucu davetleri ekranından evet/hayır yanıtla. Onay verirsen kuruluşta partiye katılırsın.',p.kad,p_ad,p_kisa),t);
  end if;
 end loop;
 if sayi<3 then raise exception 'En az 3 farklı kayıtlı oyuncuyu kurucular kuruluna davet etmelisin.'; end if;
 return jsonb_build_object('basvuru_id',idd,'davet',sayi,'gerekli',3,'sermaye',greatest(25000,oyun.parti_kur_ucreti()));
end $$;
create or replace function public.kurucu_davet_yanit(p_basvuru bigint,p_kabul boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p oyun.profiller:=oyun.profilim(); b oyun.kurucu_basvuru; n int;
begin
 select * into b from oyun.kurucu_basvuru where id=p_basvuru for update;
 if b.id is null or b.durum<>'bekliyor' or b.bit<=oyun.simdi() then raise exception 'Bu kurucu daveti geçerli değil.'; end if;
 if p_kabul and oyun.uyari(p,oyun.simdi()) is not null then raise exception 'Kurucu olmak için seçmen kartın hazır olmalı: %',oyun.uyari(p,oyun.simdi()); end if;
 update oyun.kurucu_davet set durum=case when p_kabul then 'evet' else 'hayir' end,cevap_at=oyun.simdi()
 where basvuru_id=b.id and user_id=p.id and durum='bekliyor';
 if not found then raise exception 'Davetin yok veya daha önce yanıtladın.'; end if;
 select count(*) into n from oyun.kurucu_davet where basvuru_id=b.id and durum='evet';
 perform oyun.bildir(b.kurucu,format('%s kurucu davetine %s yanıtı verdi. Onaylar: %s/3.',p.kad,case when p_kabul then 'EVET' else 'HAYIR' end,n));
 return jsonb_build_object('kabul',p_kabul,'onay',n,'gerekli',3);
end $$;
create or replace function public.kurucu_davetlerim() returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object(
  'gelen',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'ad',b.ad,'kisa',b.kisa,
    'kurucu',p.kad,'ideolojiler',b.ideolojiler,'bit',b.bit,'durum',d.durum) order by b.id desc)
    from oyun.kurucu_davet d join oyun.kurucu_basvuru b on b.id=d.basvuru_id
    join oyun.profiller p on p.id=b.kurucu
    where d.user_id=auth.uid() and d.durum='bekliyor' and b.durum='bekliyor' and b.bit>oyun.simdi()),'[]'::jsonb),
  'basvurum',(select jsonb_build_object('id',b.id,'ad',b.ad,'kisa',b.kisa,'bit',b.bit,
    'ideolojiler',b.ideolojiler,'onay',(select count(*) from oyun.kurucu_davet d where d.basvuru_id=b.id and d.durum='evet'),
    'davetler',(select coalesce(jsonb_agg(jsonb_build_object('kad',p.kad,'durum',d.durum) order by p.kad),'[]'::jsonb)
      from oyun.kurucu_davet d join oyun.profiller p on p.id=d.user_id where d.basvuru_id=b.id))
   from oyun.kurucu_basvuru b where b.kurucu=auth.uid() and b.durum='bekliyor' and b.bit>oyun.simdi() order by b.id desc limit 1))
$$;
create or replace function public.parti_kur_iptal(p_basvuru bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p oyun.profiller:=oyun.profilim();
begin
 update oyun.kurucu_basvuru set durum='iptal' where id=p_basvuru and kurucu=p.id and durum='bekliyor';
 if not found then raise exception 'İptal edilecek başvuru yok.'; end if;
 return jsonb_build_object('tamam',true);
end $$;
create or replace function public.parti_kur_tamamla(p_basvuru bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p oyun.profiller:=oyun.profilim(); b oyun.kurucu_basvuru; t timestamptz:=oyun.simdi();
 n int; yeni bigint; ucret numeric; uy uuid;
begin
 select * into b from oyun.kurucu_basvuru where id=p_basvuru for update;
 if b.id is null or b.kurucu is distinct from p.id or b.durum<>'bekliyor' or b.bit<=t then raise exception 'Aktif kurucu başvurun yok.'; end if;
 select count(*) into n from oyun.kurucu_davet d join oyun.profiller h on h.id=d.user_id
 where d.basvuru_id=b.id and d.durum='evet' and not h.yasakli
 and oyun.uyari(h,t) is null;
 if n<3 then raise exception 'Parti için senden başka en az 3 kişinin onayı gerekli. Şu an: %.',n; end if;
 if oyun.uyari(p,t) is not null then raise exception 'Kurucu şartı: %',oyun.uyari(p,t); end if;
 if p.son_parti_kur is not null and p.son_parti_kur+make_interval(days=>(select parti_kur_gun from oyun.ayarlar where id=1))>t then raise exception 'Parti kurma bekleme süren dolmadı.'; end if;
 if exists(select 1 from oyun.partiler where not kapali and (lower(ad)=lower(b.ad) or lower(kisa)=lower(b.kisa))) then raise exception 'Bu isim veya kısaltma artık kullanılıyor.'; end if;
 ucret:=greatest(25000,oyun.parti_kur_ucreti());
 if (select para from oyun.cuzdanim(p.id))<ucret then raise exception 'Partiyi kurmak için % ₺ nakit sermaye gerekiyor.',oyun.tl(ucret); end if;
 -- Davet verilen onay, kuruluşta partiye katılma iznini içerir.
 perform oyun.para_islem(p.id,-ucret,'parti_kur',format('%s kuruluş sermayesi',b.ad),t);
 perform oyun._ayril(p.id,t);
 insert into oyun.partiler(ad,kisa,renk,amblem,gb,kurucu,kurulus,kurulus_bit)
 values(b.ad,b.kisa,b.renk,b.amblem,p.id,p.id,t,null) returning id into yeni;
 perform oyun.genel_merkez_ac(yeni,p,ucret,t);
 update oyun.profiller set parti_id=yeni,parti_at=t,son_parti_kur=t where id=p.id;
 for uy in select d.user_id from oyun.kurucu_davet d join oyun.profiller h on h.id=d.user_id
   where d.basvuru_id=b.id and d.durum='evet' and not h.yasakli and oyun.uyari(h,t) is null loop
  perform oyun._ayril(uy,t);
  update oyun.profiller set parti_id=yeni,parti_at=t where id=uy and not yasakli;
  perform oyun.bildir(uy,format('%s kuruluşuna verdiğin onay kabul edildi. Kurucular kuruluna katıldın!',b.ad),t);
 end loop;
 insert into oyun.parti_kimlik(parti_id,ideolojiler,guncelleme) values(yeni,b.ideolojiler,t);
 update oyun.kurucu_basvuru set durum='kuruldu',parti_id=yeni where id=b.id;
 perform oyun.olay('parti',format('%s (%s), %s kurucunun onayı ve %s ₺ sermayeyle kuruldu.',b.ad,b.kisa,n+1,oyun.tl(ucret)),p.il_id,yeni,t);
 return jsonb_build_object('parti_id',yeni,'kurucu_sayi',n+1,'sermaye',ucret);
end $$;
do $$ declare s text; begin
 foreach s in array array[
 'ilk_adimlar()','parti_kimlikleri()',
 'ideoloji_teklif_ver(text[])','ideoloji_oyla(bigint,boolean)','ideoloji_durum(bigint)',
 'parti_kur_baslat(text,text,text,text,text[],text[])','kurucu_davet_yanit(bigint,boolean)',
 'kurucu_davetlerim()','parti_kur_iptal(bigint)','parti_kur_tamamla(bigint)'] loop
  execute format('revoke all on function public.%s from public,anon',s);
  execute format('grant execute on function public.%s to authenticated',s);
 end loop;
end $$;
-- Seçim Simülasyonu Online: Şirket keşfi ve gayrimenkul pazarlığı
-- Mevcut hesap, kasa, mülk ve tapu verilerini sıfırlamaz.
create table if not exists oyun.emlak_pazarlik (
 id bigint generated always as identity primary key,
 ilan_id bigint not null references oyun.mulk_ilan(id) on delete cascade,
 alici uuid not null references oyun.profiller(id),
 satici uuid not null references oyun.profiller(id),
 teklif numeric not null check (teklif between 10000 and 1000000000),
 karsi_teklif numeric check (karsi_teklif between 10000 and 1000000000),
 durum text not null default 'bekliyor' check (durum in ('bekliyor','karsi','kabul','red','iptal')),
 zaman timestamptz not null default now(), sonuc_at timestamptz
);
create index if not exists emlak_pazarlik_ilan on oyun.emlak_pazarlik(ilan_id);
create index if not exists emlak_pazarlik_satici on oyun.emlak_pazarlik(satici,durum);
create index if not exists emlak_pazarlik_alici on oyun.emlak_pazarlik(alici,durum);
alter table oyun.emlak_pazarlik enable row level security;
revoke all on oyun.emlak_pazarlik from public,anon,authenticated;

create or replace function public.sirket_vitrini()
returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('sirketler',
 coalesce((select jsonb_agg(jsonb_build_object(
   'id',s.id,'ad',s.ad,'sektor',s.sektor,'kurucu',p.kad,
   'sahip',coalesce((select x.kad from oyun.sirket_ortaklari o join oyun.profiller x on x.id=o.user_id
       where o.sirket_id=s.id and o.pay>0 order by o.pay desc,o.user_id limit 1),p.kad),
   'sermaye',s.sermaye,'kasa',s.kasa,'kurulus',s.kurulus,
   'aktif',s.aktif,'satilik',s.satilik,
   'ortaklar',coalesce((select jsonb_agg(jsonb_build_object('kad',x.kad,'pay',o.pay) order by o.pay desc)
      from oyun.sirket_ortaklari o join oyun.profiller x on x.id=o.user_id where o.sirket_id=s.id),'[]'::jsonb),
   'toplam_gelir',coalesce((select sum(greatest(0,h.faaliyet_gelir)) from oyun.sirket_hareket h where h.sirket_id=s.id),0),
   'net_kazanc',coalesce((select sum(h.tutar) from oyun.sirket_hareket h where h.sirket_id=s.id and h.faaliyet_gelir is not null),0),
   'vergi',coalesce((select sum(h.vergi) from oyun.hesap_hareket h
      where h.tur='sirket' and h.vergi>0 and h.aciklama like 'Sirket #'||s.id::text||' %'),0)
 ) order by s.id) from oyun.sirketler s join oyun.profiller p on p.id=s.kurucu where s.aktif and s.sektor<>'banka'),'[]'::jsonb),
 'vergi_notu','Sadece kayda alınmış gerçek şirket kazancı vergileri gösterilir; eski faaliyetler için şirket vergisi kaydı bulunmayabilir.')
$$;
revoke all on function public.sirket_vitrini() from public,anon;
grant execute on function public.sirket_vitrini() to authenticated;

create or replace function public.emlak_pazarliklarim()
returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object(
   'id',z.id,'ilan_id',z.ilan_id,'teklif',z.teklif,'karsi_teklif',z.karsi_teklif,
   'durum',z.durum,'zaman',z.zaman,'alici',a.kad,'satici',s.kad,
   'ben_aliciyim',z.alici=auth.uid(),'ben_saticiyim',z.satici=auth.uid(),
   'ilan_acik',i.durum='acik','mulk_id',i.mulk_id,
   'tip',m.tip,'il',il.ad) order by z.zaman desc),'[]'::jsonb)
 from oyun.emlak_pazarlik z
 join oyun.mulk_ilan i on i.id=z.ilan_id
 join oyun.yatirim_mulkleri m on m.id=i.mulk_id
 join oyun.iller il on il.id=m.il_id
 join oyun.profiller a on a.id=z.alici join oyun.profiller s on s.id=z.satici
 where (z.alici=auth.uid() or z.satici=auth.uid())
   and z.zaman>oyun.simdi()-interval '60 days'
$$;
revoke all on function public.emlak_pazarliklarim() from public,anon;
grant execute on function public.emlak_pazarliklarim() to authenticated;

create or replace function public.emlak_pazarlik_teklif(p_ilan bigint,p_fiyat numeric)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();i oyun.mulk_ilan; idd bigint; t timestamptz:=oyun.simdi();
begin
 if u is null or not exists(select 1 from oyun.profiller where id=u and not yasakli) then raise exception 'Oyuncu hesabı gerekli.'; end if;
 if p_fiyat is null or p_fiyat<10000 or p_fiyat>1000000000 or p_fiyat<>trunc(p_fiyat) then raise exception 'Teklif tutarı 10.000 ile 1 milyar ₺ arasında tam sayı olmalı.'; end if;
 select * into i from oyun.mulk_ilan where id=p_ilan for update;
 if i.id is null or i.durum<>'acik' then raise exception 'Bu ilan artık satılık değil.'; end if;
 if i.satici=u then raise exception 'Kendi mülküne teklif veremezsin.'; end if;
 if not exists(select 1 from oyun.yatirim_mulkleri where id=i.mulk_id and user_id=i.satici) then raise exception 'Mülk artık satıcının değil.'; end if;
 if exists(select 1 from oyun.emlak_pazarlik where ilan_id=p_ilan and alici=u and durum in ('bekliyor','karsi')) then raise exception 'Bu ilan için önceki pazarlığın sürüyor.'; end if;
 insert into oyun.emlak_pazarlik(ilan_id,alici,satici,teklif,zaman) values(p_ilan,u,i.satici,p_fiyat,t) returning id into idd;
 perform oyun.bildir(i.satici,format('%s mülk #%s için %s ₺ teklif verdi. Gayrimenkul > Pazarlıklarım bölümünden yanıtla.',
 (select kad from oyun.profiller where id=u),i.mulk_id,oyun.tl(p_fiyat)),t);
 return jsonb_build_object('id',idd,'durum','bekliyor');
end $$;
revoke all on function public.emlak_pazarlik_teklif(bigint,numeric) from public,anon;
grant execute on function public.emlak_pazarlik_teklif(bigint,numeric) to authenticated;

-- Gerçek satış, eski satış mantığıyla aynı biçimde kaydedilir. Yalnızca güvenli RPC çağırabilir.
create or replace function oyun._emlak_pazarlik_tamamla(p_teklif bigint,p_fiyat numeric)
returns void language plpgsql security definer set search_path='' as $$
declare z oyun.emlak_pazarlik;i oyun.mulk_ilan; m oyun.yatirim_mulkleri;
  vergi numeric;t timestamptz:=oyun.simdi();
begin
 select * into z from oyun.emlak_pazarlik where id=p_teklif for update;
 if z.id is null or z.durum not in ('bekliyor','karsi') then raise exception 'Teklif artık geçerli değil.'; end if;
 if p_fiyat is null or p_fiyat<10000 or p_fiyat>1000000000 then raise exception 'Geçersiz teklif bedeli.'; end if;
 select * into i from oyun.mulk_ilan where id=z.ilan_id for update;
 if i.id is null or i.durum<>'acik' or i.satici<>z.satici then raise exception 'İlan artık geçerli değil.'; end if;
 select * into m from oyun.yatirim_mulkleri where id=i.mulk_id for update;
 if m.id is null or m.user_id<>i.satici then raise exception 'Mülk artık satışta değil.'; end if;
 if z.alici=z.satici then raise exception 'Kendi mülkünü alamazsın.'; end if;
 perform oyun.mulk_kira_tahsil(z.satici);
 vergi:=round(p_fiyat*0.02);
 perform oyun.para_islem(z.alici,-p_fiyat,'emlak','Pazarlıkla mülk satın alındı #'||i.mulk_id,t);
 perform oyun.para_islem(z.satici,p_fiyat-vergi,'emlak','Pazarlıkla mülk satışı #'||i.mulk_id,t);
 update oyun.ulke set hazine=hazine+vergi/1000000.0 where id=1;
 update oyun.yatirim_mulkleri set user_id=z.alici,satin_alma=t,alis_bedeli=p_fiyat,sonraki_kira=t+interval '7 days',
   toplam_kira=0,kira_sayisi=0 where id=m.id;
 update oyun.mulk_ilan set durum='satildi',alici=z.alici,kapanma=t where id=i.id;
 update oyun.emlak_pazarlik set durum='kabul',sonuc_at=t where id=z.id;
 update oyun.emlak_pazarlik set durum='iptal',sonuc_at=t where ilan_id=i.id and id<>z.id and durum in ('bekliyor','karsi');
 perform oyun.bildir(z.alici,format('Pazarlık kabul edildi! Mülk #%s %s ₺ karşılığında senin.',i.mulk_id,oyun.tl(p_fiyat)),t);
 perform oyun.bildir(z.satici,format('Mülk #%s %s ₺ karşılığında satıldı; %%2 işlem vergisi kesildi.',i.mulk_id,oyun.tl(p_fiyat)),t);
end $$;
revoke all on function oyun._emlak_pazarlik_tamamla(bigint,numeric) from public,anon,authenticated;

create or replace function public.emlak_pazarlik_satici_yanit(p_teklif bigint,p_karar text,p_karsi numeric default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); z oyun.emlak_pazarlik; t timestamptz:=oyun.simdi();
begin
 select * into z from oyun.emlak_pazarlik where id=p_teklif for update;
 if z.id is null or z.satici is distinct from u or z.durum<>'bekliyor' then raise exception 'Yanıt verebileceğin açık teklif yok.'; end if;
 if p_karar not in ('kabul','red','karsi') then raise exception 'Geçersiz yanıt.'; end if;
 if p_karar='kabul' then
    perform oyun._emlak_pazarlik_tamamla(z.id,z.teklif);
 elsif p_karar='red' then
    update oyun.emlak_pazarlik set durum='red',sonuc_at=t where id=z.id;
    perform oyun.bildir(z.alici,'Mülk teklifin satıcı tarafından reddedildi.',t);
 else
    if p_karsi is null or p_karsi<10000 or p_karsi>1000000000 or p_karsi<>trunc(p_karsi) then raise exception 'Geçerli bir karşı teklif tutarı gir.'; end if;
    update oyun.emlak_pazarlik set durum='karsi',karsi_teklif=p_karsi where id=z.id;
    perform oyun.bildir(z.alici,format('Mülk teklifine karşı %s ₺ istendi. Gayrimenkul > Pazarlıklarım bölümünden yanıtla.',oyun.tl(p_karsi)),t);
 end if;
 return jsonb_build_object('durum',p_karar);
end $$;
revoke all on function public.emlak_pazarlik_satici_yanit(bigint,text,numeric) from public,anon;
grant execute on function public.emlak_pazarlik_satici_yanit(bigint,text,numeric) to authenticated;

create or replace function public.emlak_pazarlik_alici_yanit(p_teklif bigint,p_kabul boolean)
returns jsonb language plpgsql security definer set search_path='' as $$
declare z oyun.emlak_pazarlik;t timestamptz:=oyun.simdi();
begin
 select * into z from oyun.emlak_pazarlik where id=p_teklif for update;
 if z.id is null or z.alici is distinct from auth.uid() or z.durum<>'karsi' then raise exception 'Karşı teklif bulunamadı.'; end if;
 if p_kabul is null then raise exception 'Kabul veya ret seçmelisin.'; end if;
 if p_kabul then perform oyun._emlak_pazarlik_tamamla(z.id,z.karsi_teklif);
 else
   update oyun.emlak_pazarlik set durum='red',sonuc_at=t where id=z.id;
   perform oyun.bildir(z.satici,'Alıcı karşı teklifini reddetti.',t);
 end if;
 return jsonb_build_object('durum',case when p_kabul then 'kabul' else 'red' end);
end $$;
revoke all on function public.emlak_pazarlik_alici_yanit(bigint,boolean) from public,anon;
grant execute on function public.emlak_pazarlik_alici_yanit(bigint,boolean) to authenticated;
-- 600 potansiyel sandalye, dolu vekiller üzerinden salt çoğunluk.
CREATE OR REPLACE FUNCTION oyun.kanun_tick(t timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare k oyun.kanunlar; c record; dolu int; cb uuid; s record;
begin
  select * into s from oyun.kanun_suresi();
  -- anayasa değişikliği: görüşme bitince imza sayısı dolu sandalyelerin üçte birine ulaşmadıysa teklif düşer
  for k in select * from oyun.kanunlar where durum = 'gorusmede' and tur = 'anayasa' and t >= oy_bas order by oy_bas loop
    dolu := oyun.dolu_sandalye();
    if (select count(*) from oyun.kanun_oylari where kanun_id = k.id and asama = 'imza') < ceil(dolu / 3.0) then
      update oyun.kanunlar set durum = 'ret', sonuc_at = k.oy_bas,
        sonuc_metin = format('Yeterli imza toplanamadı: %s imza, en az %s gerekliydi (dolu sandalyelerin üçte biri).',
                             (select count(*) from oyun.kanun_oylari where kanun_id = k.id and asama = 'imza'), ceil(dolu / 3.0)) where id = k.id;
      perform oyun.bildir(k.teklif_eden, format('"%s" anayasa değişikliği teklifin yeterli imza toplayamadı.', k.baslik), k.oy_bas);
    end if;
  end loop;
  update oyun.kanunlar set durum = 'oylamada' where durum = 'gorusmede' and t >= oy_bas;
  for k in select * from oyun.kanunlar where durum = 'oylamada' and tur = 'anayasa' and t >= oy_bit order by oy_bit loop
    select * into c from oyun.kanun_say(k.id, 'ilk');
    dolu := oyun.dolu_sandalye();
    cb := oyun.aktif_cb();
    if dolu > 0 and c.kabul >= ceil(dolu * 2 / 3.0) and cb is not null then
      update oyun.kanunlar set durum = 'cb_onayinda', cb_bit = k.oy_bit + s.cb,
        sonuc_metin = format('Gizli oylamada %s kabul, %s ret, %s çekimser: üçte iki çoğunluk sağlandı.', c.kabul, c.ret, c.cekimser) where id = k.id;
      perform oyun.bildir(cb, format('"%s" anayasa değişikliği Meclis''ten üçte iki çoğunlukla geçti. 48 saat içinde yayımla ya da halkoyuna sun.', k.baslik), k.oy_bit);
      perform oyun.olay('meclis', format('"%s" anayasa değişikliği üçte iki çoğunlukla kabul edildi (%s kabul). Cumhurbaşkanına sunuldu.', k.baslik, c.kabul), null, k.teklif_parti, k.oy_bit);
    elsif dolu > 0 and c.kabul >= ceil(dolu * 3 / 5.0) then
      update oyun.kanunlar set sonuc_metin = format('Gizli oylamada %s kabul, %s ret, %s çekimser: beşte üç çoğunlukla kabul edildi, halkoyuna sunuluyor.', c.kabul, c.ret, c.cekimser) where id = k.id;
      perform oyun.referandum_baslat(k.id, k.oy_bit);
    else
      update oyun.kanunlar set durum = 'ret', sonuc_at = k.oy_bit,
        sonuc_metin = format('Reddedildi: gizli oylamada %s kabul oyu çıktı; halkoyuna sunulması için en az %s (beşte üç) gerekliydi.', c.kabul, ceil(dolu * 3 / 5.0)) where id = k.id;
      perform oyun.bildir(k.teklif_eden, format('"%s" anayasa değişikliği teklifin Meclis''te gerekli çoğunluğu alamadı.', k.baslik), k.oy_bit);
    end if;
  end loop;
  for k in select * from oyun.kanunlar where durum = 'oylamada' and tur <> 'anayasa' and t >= oy_bit order by oy_bit loop
    select * into c from oyun.kanun_say(k.id, 'ilk');
    dolu := oyun.dolu_sandalye();
    if dolu > 0 and c.kabul >= floor(dolu / 2.0) + 1 then
      cb := oyun.aktif_cb();
      if cb is null then
        perform oyun.kanun_yururluk(k.id, k.oy_bit, format('Meclis''te %s kabul, %s ret oyla kabul edildi (cumhurbaşkanı makamı boş).', c.kabul, c.ret));
      else
        update oyun.kanunlar set durum = 'cb_onayinda', cb_bit = k.oy_bit + s.cb,
          sonuc_metin = format('Meclis''te %s kabul, %s ret, %s çekimser oyla kabul edildi.', c.kabul, c.ret, c.cekimser) where id = k.id;
        perform oyun.bildir(cb, format('"%s" kanunu Meclis''ten geçti ve onayınızı bekliyor. 48 saat içinde onaylayın ya da veto edin.', k.baslik), k.oy_bit);
        perform oyun.olay('meclis', format('"%s" Meclis''te kabul edildi (%s kabul, %s ret). Cumhurbaşkanının onayına sunuldu.', k.baslik, c.kabul, c.ret), null, k.teklif_parti, k.oy_bit);
      end if;
    else
      update oyun.kanunlar set durum = 'ret', sonuc_at = k.oy_bit,
        sonuc_metin = format('Salt çoğunluk sağlanamadı: %s kabul, %s ret, %s çekimser (dolu %s sandalyeden en az %s EVET gerekir).', c.kabul, c.ret, c.cekimser, dolu, floor(dolu / 2.0) + 1)
      where id = k.id;
      perform oyun.bildir(k.teklif_eden, format('"%s" teklifin Meclis''te kabul edilmedi.', k.baslik), k.oy_bit);
    end if;
  end loop;
  for k in select * from oyun.kanunlar where durum = 'cb_onayinda' and t >= cb_bit order by cb_bit loop
    perform oyun.kanun_yururluk(k.id, k.cb_bit, case when k.tur = 'anayasa' then 'Cumhurbaşkanı süresi içinde halkoyuna sunmadığı için yayımlanarak yürürlüğe girdi.'
                                                    else 'Cumhurbaşkanı süresi içinde karar vermediği için kendiliğinden yürürlüğe girdi.' end);
  end loop;
  for k in select * from oyun.kanunlar where durum = 'israr' and t >= israr_bit order by israr_bit loop
    select * into c from oyun.kanun_say(k.id, 'israr');
    dolu := oyun.dolu_sandalye();
    if dolu > 0 and c.kabul >= floor(dolu / 2.0) + 1 then
      perform oyun.kanun_yururluk(k.id, k.israr_bit, format('Veto sonrası Meclis %s oyla ısrar etti.', c.kabul));
    else
      update oyun.kanunlar set durum = 'dustu', sonuc_at = k.israr_bit,
        sonuc_metin = format('Veto sonrası ısrar için %s oy gerekiyordu, %s kabul oyu çıktı. Kanun düştü.', floor(dolu / 2.0) + 1, c.kabul) where id = k.id;
      perform oyun.bildir(k.teklif_eden, format('"%s" veto sonrası ısrar oylamasında düştü.', k.baslik), k.israr_bit);
    end if;
  end loop;
  -- seçim döneminde kabul edilen baraj, seçim bitince uygulanır
  if (select bekleyen_baraj from oyun.ulke where id = 1) is not null
     and not exists (select 1 from oyun.secimler o join oyun.secimler g on g.donem = o.donem and g.tur = 'mv'
                     where o.tur = 'mv_on' and t >= o.basvuru_bas and g.durum = 'bekliyor') then
    update oyun.ayarlar set baraj = (select bekleyen_baraj from oyun.ulke where id = 1) where id = 1;
    update oyun.ulke set bekleyen_baraj = null where id = 1;
  end if;
end $function$
;

-- 600 milletvekili seçilebilecek; boş koltuklar yasama çoğunluğuna dahil edilmeyecek.
update oyun.ayarlar set meclis_olcek=0 where id=1;
select oyun.dagit_mv_sandalye(600);
update oyun.meclis_olcek_kayit set sandalye=600,anayasal=600
 where secim_id in (select id from oyun.secimler
                   where tur='mv_on' and durum='bekliyor' and oy_bas>oyun.simdi());
-- =====================================================================
--  44 · İL BAZLI EMLAK: SINIRLI STOK, İL FİYATI, HAFTALIK MÜLK VERGİSİ
--
--  • Her ilde satılık yeni mülk sayısı nüfusa göre sınırlı (İstanbul ~100 daire, Bayburt 8 daire).
--    Nüfus göstergesi: ilin 600 sandalyelik Meclis'teki ağırlığı (oyun.iller.mv).
--  • Fiyat ve kira ilin büyüklüğüne ve gelişmişliğine göre değişir.
--    Gelişmişlik = %60 ilin kalıcı kalkınma puanı (SEGE sıralamasına yakın 6 kademe)
--                + %40 belediyenin oyun içi gelişim puanı (yatırımlarla değişir).
--  • Oyuncu parası yettikçe yaşamadığı illerden de mülk alabilir, ilana koyup satabilir.
--  • Her mülkten haftalık mülk vergisi alınır, para mülkün bulunduğu ilin belediye kasasına gider.
--    Oran = Meclis'in kanunla belirlediği ulusal oran × o ilin belediye başkanının çarpanı.
--    Ulusal oranı cumhurbaşkanı kararnameyle değiştiremez; yalnız TBMM (ya da anayasa).
--  • Vergi matrahı mülkün bugünkü il rayiç bedelidir (alış fiyatı değil).
--  • Eski mülklerin sahibi ve kirası korunur; ilk vergi bu güncellemeden 7 gün sonra alınır.
-- =====================================================================

alter table oyun.yatirim_mulkleri add column if not exists vergi_sonraki timestamptz;
alter table oyun.yatirim_mulkleri add column if not exists vergi_borc numeric not null default 0;
update oyun.yatirim_mulkleri set vergi_sonraki = oyun.simdi() + interval '7 days' where vergi_sonraki is null;
alter table oyun.yatirim_mulkleri alter column vergi_sonraki set default now() + interval '7 days';

-- Belediye kasasına giden her vergi tahsilatı (belediye başkanı ve oyuncu ekranları için)
create table if not exists oyun.emlak_vergi_tahsilat(
  id       bigint generated always as identity primary key,
  il_id    smallint not null references oyun.iller(id),
  user_id  uuid not null references oyun.profiller(id),
  mulk_id  bigint not null,
  tutar    numeric not null check (tutar >= 0),
  zaman    timestamptz not null default now()
);
create index if not exists emlak_vergi_tahsilat_il_zaman on oyun.emlak_vergi_tahsilat(il_id, zaman);
alter table oyun.emlak_vergi_tahsilat enable row level security;

-- İllerin kalıcı kalkınma puanı (0-100). Kademeler SEGE il sıralamasına yakındır; gerekirse elle ayarlanabilir.
create table if not exists oyun.il_kalkinma(
  il_id smallint primary key references oyun.iller(id),
  puan  numeric not null check (puan between 0 and 100)
);
alter table oyun.il_kalkinma enable row level security;
insert into oyun.il_kalkinma(il_id, puan)
select i.id, case
  when i.id in (6,7,16,26,34,35,41,48,59) then 90
  when i.id in (9,10,11,14,17,20,22,32,33,38,39,42,45,54,77) then 75
  when i.id in (1,3,5,8,15,19,23,24,27,31,37,40,43,44,50,51,53,55,58,61,64,67,70,71,74,78,81) then 60
  when i.id in (18,25,28,29,46,52,57,60,62,66,68,69,79,80) then 45
  when i.id in (2,12,21,36,63,72,75,76) then 30
  else 15 end
from oyun.iller i
on conflict (il_id) do nothing;

-- Yeni tablolar da TRUNCATE korumasına girsin (tam kurulumda kalicilik_son zaten ekler; migration için burada)
do $$ begin
  if to_regproc('oyun.bosaltma_korumasi') is not null then
    drop trigger if exists bosaltma_korumasi on oyun.emlak_vergi_tahsilat;
    create trigger bosaltma_korumasi before truncate on oyun.emlak_vergi_tahsilat for each statement execute function oyun.bosaltma_korumasi();
    drop trigger if exists bosaltma_korumasi on oyun.il_kalkinma;
    create trigger bosaltma_korumasi before truncate on oyun.il_kalkinma for each statement execute function oyun.bosaltma_korumasi();
  end if;
end $$;

-- Kurallar: ulusal oran (Meclis) ve il çarpanı (belediye başkanı)
insert into oyun.duzenleme_tanim(kod, kapsam, ad, birim, varsayilan, min, max, adim, tur, aciklama, oyuncu, devlet, sira) values
('mulk_vergi_ulusal','ulke','Haftalık mülk vergisi','yuzde',0.5,0.1,3.0,0.1,'gelir',
 'Mülklerin il rayiç bedeli üzerinden her hafta alınan vergi. Yalnız TBMM kanunla değiştirir; illerde belediye çarpanıyla uygulanır.',
 'Sahip olduğun her mülk için haftada bir, mülkün bugünkü il değeri üzerinden vergi ödersin.',
 'Vergi hazineye değil, mülkün bulunduğu ilin belediye kasasına gider.',21),
('mulk_vergi_yerel','il','Mülk vergisi çarpanı','yuzde',100,50,200,10,'gelir',
 'Meclis''in belirlediği haftalık mülk vergisinin bu ilde uygulanan çarpanı. 100 değişiklik yok demektir, 150 vergiyi yarı yarıya artırır.',
 'Bu ildeki mülklerin vergisi değişir; mülk sahibi başka ilde yaşasa da vergiyi bu il alır.',
 'Gelir doğrudan bu ilin belediye kasasına girer.',22)
on conflict (kod) do update set kapsam = excluded.kapsam, ad = excluded.ad, birim = excluded.birim, varsayilan = excluded.varsayilan,
  min = excluded.min, max = excluded.max, adim = excluded.adim, tur = excluded.tur, aciklama = excluded.aciklama,
  oyuncu = excluded.oyuncu, devlet = excluded.devlet, sira = excluded.sira;

-- Ulusal oranı cumhurbaşkanı kararnameyle değiştiremez.
create or replace function oyun.duzenleme_engel(p_kod text, p_kaynak text) returns text language sql stable as $$
  select case when d.kaynak = 'anayasa' and p_kaynak <> 'anayasa'
                then 'Bu kural anayasada düzenlenmiş; ancak halk oylamasıyla yapılacak bir anayasa değişikliğiyle değiştirilebilir.'
              when p_kod = 'mulk_vergi_ulusal' and p_kaynak = 'kararname'
                then 'Haftalık mülk vergisi oranını yalnız TBMM kanunla değiştirebilir; kararnameyle değiştirilemez.'
              when d.kaynak = 'kanun' and p_kaynak = 'kararname'
                then 'Bu konu Meclis tarafından kanunla düzenlenmiş; kanunla düzenlenen konuda cumhurbaşkanlığı kararnamesi çıkarılamaz.' end
  from (select 1) x left join oyun.duzenlemeler d on d.kod = p_kod
$$;

-- ---------------------------------------------------------------------
-- HESAPLAR
-- ---------------------------------------------------------------------
create or replace function oyun.mulk_il_gelismislik(p_il smallint) returns numeric
language sql stable set search_path = '' as $$
  select round(0.6 * coalesce(k.puan, 50) + 0.4 * greatest(0, least(100, coalesce(d.gelisim, 50))), 1)
  from oyun.iller i left join oyun.il_kalkinma k on k.il_id = i.id left join oyun.il_durum d on d.il_id = i.id
  where i.id = p_il
$$;

create or replace function oyun.mulk_il_kota(p_il smallint, p_tip text) returns integer
language sql stable set search_path = '' as $$
  select case p_tip
    when 'daire'  then 8 + round((least(96, greatest(1, i.mv)) - 1) * 92.0 / 95)::int
    when 'dukkan' then 3 + round((least(96, greatest(1, i.mv)) - 1) * 32.0 / 95)::int
    when 'villa'  then 2 + round((least(96, greatest(1, i.mv)) - 1) * 18.0 / 95)::int
    else 0 end
  from oyun.iller i where i.id = p_il
$$;

create or replace function oyun.mulk_il_bedel(p_il smallint, p_tip text) returns numeric
language sql stable set search_path = '' as $$
  select round((case p_tip when 'daire' then 130000 when 'dukkan' then 260000 when 'villa' then 520000 end)
               * (0.55 + 1.10 * sqrt(least(96, greatest(1, i.mv))::numeric / 96.0))
               * (0.60 + oyun.mulk_il_gelismislik(p_il) / 125.0), -3)
  from oyun.iller i where i.id = p_il
$$;

-- Kira: il değerinin ~1/13'ü; gelişmiş ilde kira getirisi biraz daha yüksek.
create or replace function oyun.mulk_il_kira(p_il smallint, p_tip text) returns numeric
language sql stable set search_path = '' as $$
  select round(oyun.mulk_il_bedel(p_il, p_tip) / 13.0 * (0.85 + oyun.mulk_il_gelismislik(p_il) / 333.0), -1)
$$;

-- Bu ilde uygulanan haftalık oran (yüzde)
create or replace function oyun.mulk_vergi_oran(p_il smallint) returns numeric
language sql stable set search_path = '' as $$
  select round(oyun.duz('mulk_vergi_ulusal') * oyun.il_duz(p_il, 'mulk_vergi_yerel') / 100.0, 3)
$$;

create or replace function oyun.mulk_haftalik_vergi_tutar(p_mulk bigint) returns numeric
language sql stable set search_path = '' as $$
  select round(oyun.mulk_il_bedel(m.il_id, m.tip) * oyun.mulk_vergi_oran(m.il_id) / 100.0)
  from oyun.yatirim_mulkleri m where m.id = p_mulk
$$;

-- Vadesi gelen dönemleri tahakkuk ettirir, cüzdandaki parayla öder; yetmeyen kısım borç olarak kalır.
create or replace function oyun.mulk_haftalik_vergi(p_user uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare x record; t timestamptz := oyun.simdi(); donem int; tahakkuk numeric; odeme numeric; hazir numeric;
begin
  for x in select m.id, m.il_id, m.tip, m.vergi_sonraki, m.vergi_borc, i.ad il_ad
           from oyun.yatirim_mulkleri m join oyun.iller i on i.id = m.il_id
           where m.user_id = p_user and (m.vergi_sonraki <= t or m.vergi_borc > 0)
           order by m.id for update of m loop
    donem := case when x.vergi_sonraki <= t then least(520, floor(extract(epoch from (t - x.vergi_sonraki)) / 604800)::int + 1) else 0 end;
    tahakkuk := coalesce(oyun.mulk_haftalik_vergi_tutar(x.id), 0) * donem;
    hazir := greatest(0, coalesce((select para from oyun.cuzdan where user_id = p_user), 0));
    odeme := least(x.vergi_borc + tahakkuk, floor(hazir));
    update oyun.yatirim_mulkleri
       set vergi_borc = greatest(0, x.vergi_borc + tahakkuk - odeme),
           vergi_sonraki = x.vergi_sonraki + make_interval(days => donem * 7)
     where id = x.id;
    if odeme > 0 then
      perform oyun.para_islem(p_user, -odeme, 'emlak_vergi',
        format('%s Belediyesi mülk vergisi · mülk #%s%s', x.il_ad, x.id, case when donem > 1 then format(' (%s hafta)', donem) else '' end), t, odeme);
      update oyun.il_durum set kasa = coalesce(kasa, 0) + odeme / 1e9 where il_id = x.il_id;  -- belediye kasası milyar ₺
      insert into oyun.emlak_vergi_tahsilat(il_id, user_id, mulk_id, tutar, zaman) values (x.il_id, p_user, x.id, odeme, t);
    end if;
  end loop;
end $$;
revoke all on function oyun.mulk_haftalik_vergi(uuid) from public, anon, authenticated;

-- Kira tahsili (24'teki ile aynı) + haftalık mülk vergisi
create or replace function oyun.mulk_kira_tahsil(p_user uuid) returns void
language plpgsql security definer set search_path to 'oyun', 'public', 'pg_temp' as $function$
declare m record; n int; gross numeric; tax numeric; t timestamptz := oyun.simdi();
begin
  perform pg_advisory_xact_lock(hashtextextended(p_user::text, 78113));
  for m in select * from oyun.yatirim_mulkleri where user_id = p_user and sonraki_kira <= t order by id for update loop
    n := least(520, floor(extract(epoch from (t - m.sonraki_kira)) / 604800)::int + 1);
    gross := round(m.haftalik_kira * n, 2);
    tax := case when (select count(*) from oyun.yatirim_mulkleri x where x.user_id = p_user
                        and (x.satin_alma < m.satin_alma or (x.satin_alma = m.satin_alma and x.id <= m.id))) >= 3
                then round(gross * oyun.yasa_oran('coklu_mulk_vergi') / 100, 2) else 0 end;
    perform oyun.para_islem(p_user, gross - tax, 'kira', format('Mülk #%s: %s haftalık kira, vergi %s ₺', m.id, n, tax), t, tax);
    if tax > 0 then update oyun.ulke set hazine = hazine + tax / 1000000 where id = 1; end if;
    update oyun.yatirim_mulkleri set sonraki_kira = sonraki_kira + n * interval '7 days', toplam_kira = toplam_kira + gross - tax,
      kira_sayisi = kira_sayisi + n where id = m.id;
  end loop;
  perform oyun.mulk_haftalik_vergi(p_user);
end $function$;

-- Tapu devrinde vergi borcu satıcıdan kesilir (satış bedeli cüzdanına girdikten sonra çalışır).
create or replace function oyun.mulk_devir_vergi() returns trigger
language plpgsql security definer set search_path = '' as $$
declare ilad text;
begin
  if new.user_id is distinct from old.user_id and old.vergi_borc > 0 then
    select ad into ilad from oyun.iller where id = old.il_id;
    perform oyun.para_islem(old.user_id, -old.vergi_borc, 'emlak_vergi',
      format('%s Belediyesi mülk vergisi borcu (tapu devri) · mülk #%s', ilad, old.id), oyun.simdi(), old.vergi_borc);
    update oyun.il_durum set kasa = coalesce(kasa, 0) + old.vergi_borc / 1e9 where il_id = old.il_id;
    insert into oyun.emlak_vergi_tahsilat(il_id, user_id, mulk_id, tutar, zaman) values (old.il_id, old.user_id, old.id, old.vergi_borc, oyun.simdi());
    new.vergi_borc := 0;
  end if;
  return new;
end $$;
drop trigger if exists mulk_devir_vergi on oyun.yatirim_mulkleri;
create trigger mulk_devir_vergi before update of user_id on oyun.yatirim_mulkleri
  for each row execute function oyun.mulk_devir_vergi();

-- ---------------------------------------------------------------------
-- UYGULAMA (RPC)
-- ---------------------------------------------------------------------
-- Deneme sürümlerinden kalmış olabilecek farklı imzalı kopyalar (uygulama çağrısı belirsiz kalmasın)
do $$ declare r record; begin
  for r in select p.oid::regprocedure f from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('mulk_il_satin_al', 'mulk_il_stok') loop
    execute format('drop function %s', r.f);
  end loop;
end $$;

create or replace function public.mulk_il_stok() returns jsonb
language sql stable security definer set search_path = '' as $$
  with sahip as (select il_id, tip, count(*) n from oyun.yatirim_mulkleri group by il_id, tip)
  select coalesce(jsonb_agg(jsonb_build_object(
    'il_id', i.id, 'il', i.ad, 'nufus', i.mv, 'gelismislik', oyun.mulk_il_gelismislik(i.id),
    'benim_ilim', i.id = (select p.il_id from oyun.profiller p where p.id = auth.uid()),
    'vergi_oran', oyun.mulk_vergi_oran(i.id), 'carpan', oyun.il_duz(i.id, 'mulk_vergi_yerel'),
    'urunler', (select jsonb_agg(jsonb_build_object(
        'tip', v.tip, 'kontenjan', oyun.mulk_il_kota(i.id, v.tip),
        'kalan', greatest(0, oyun.mulk_il_kota(i.id, v.tip) - coalesce((select n from sahip s where s.il_id = i.id and s.tip = v.tip), 0)),
        'fiyat', oyun.mulk_il_bedel(i.id, v.tip), 'kira', oyun.mulk_il_kira(i.id, v.tip),
        'vergi', round(oyun.mulk_il_bedel(i.id, v.tip) * oyun.mulk_vergi_oran(i.id) / 100.0)) order by v.sira)
      from (values ('daire', 1), ('dukkan', 2), ('villa', 3)) v(tip, sira))
  )), '[]'::jsonb)
  from oyun.iller i
$$;
revoke all on function public.mulk_il_stok() from public, anon;
grant execute on function public.mulk_il_stok() to authenticated;

create or replace function public.mulk_il_satin_al(p_tip text, p_il integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_il smallint := p_il; u uuid := auth.uid(); t timestamptz := oyun.simdi(); c oyun.iller; f numeric; k numeric; yeni bigint; mevcut int;
  tipad text := case p_tip when 'daire' then 'daire' when 'dukkan' then 'dükkân' when 'villa' then 'villa' end;
begin
  if u is null or not exists (select 1 from oyun.profiller where id = u and not yasakli) then raise exception 'Oyuncu profili gerekli.'; end if;
  if tipad is null then raise exception 'Geçersiz mülk türü.'; end if;
  if v_il is null then raise exception 'Satın alacağın ili seç.'; end if;
  select * into c from oyun.iller where id = v_il for update;   -- aynı ilde eş zamanlı alımlar sırayla işlenir
  if c.id is null then raise exception 'İl bulunamadı.'; end if;
  select count(*) into mevcut from oyun.yatirim_mulkleri where il_id = v_il and tip = p_tip;
  if mevcut >= oyun.mulk_il_kota(v_il, p_tip) then
    raise exception '% ilinde satılık yeni % kalmadı. Oyuncuların ilanlarına bakabilirsin.', c.ad, tipad;
  end if;
  f := oyun.mulk_il_bedel(v_il, p_tip); k := oyun.mulk_il_kira(v_il, p_tip);
  perform oyun.mulk_kira_tahsil(u);
  perform oyun.para_islem(u, -f, 'emlak', format('%s: yeni %s satın alındı', c.ad, tipad), t);
  insert into oyun.yatirim_mulkleri(user_id, il_id, tip, alis_bedeli, haftalik_kira, satin_alma, sonraki_kira, vergi_sonraki)
  values (u, v_il, p_tip, f, k, t, t + interval '7 days', t + interval '7 days') returning id into yeni;
  insert into oyun.ticaret_devir_kayit(tur, varlik_id, satici, alici, bedel, zaman, aciklama)
  values ('mulk_devlet', yeni, null, u, f, t, format('%s ilinden %s satın alındı', c.ad, tipad));
  return public.mulk_liste();
end $$;
revoke all on function public.mulk_il_satin_al(text, integer) from public, anon;
grant execute on function public.mulk_il_satin_al(text, integer) to authenticated;

-- Eski uygulama sürümleri: kendi ilinden, aynı stok ve il fiyatıyla alır.
create or replace function public.mulk_satin_al(p_tip text) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  return public.mulk_il_satin_al(p_tip, (select p.il_id from oyun.profiller p where p.id = auth.uid()));
end $$;
revoke all on function public.mulk_satin_al(text) from public, anon;
grant execute on function public.mulk_satin_al(text) to authenticated;

create or replace function public.mulk_liste() returns jsonb
language plpgsql security definer set search_path to 'oyun', 'public', 'pg_temp' as $function$
declare u uuid := auth.uid(); p oyun.profiller; j jsonb;
begin
  if u is null then raise exception 'Oturum açmalısın'; end if;
  select * into p from oyun.profiller where id = u;
  if p.id is null then raise exception 'Önce profil oluşturmalısın'; end if;
  perform oyun.mulk_kira_tahsil(u);
  select jsonb_build_object(
    'mulkler', coalesce(jsonb_agg(jsonb_build_object(
       'id', m.id, 'tip', m.tip, 'il', i.ad, 'il_id', m.il_id, 'alis', m.alis_bedeli, 'deger', oyun.mulk_il_bedel(m.il_id, m.tip),
       'haftalik', m.haftalik_kira, 'sonraki', m.sonraki_kira,
       'toplam_kira', m.toplam_kira, 'kira_sayisi', m.kira_sayisi,
       'vergi', oyun.mulk_haftalik_vergi_tutar(m.id), 'vergi_sonraki', m.vergi_sonraki, 'vergi_borc', m.vergi_borc
    ) order by m.satin_alma desc, m.id desc), '[]'::jsonb),
    'adet', count(m.id),
    'haftalik_toplam', coalesce(sum(m.haftalik_kira), 0),
    'haftalik_vergi', coalesce(sum(oyun.mulk_haftalik_vergi_tutar(m.id)), 0),
    'vergi_borc', coalesce(sum(m.vergi_borc), 0),
    'mulk_degeri', coalesce(sum(m.alis_bedeli), 0),
    'piyasa_degeri', coalesce(sum(oyun.mulk_il_bedel(m.il_id, m.tip)), 0),
    'ulusal_oran', oyun.duz('mulk_vergi_ulusal'),
    'cuzdan', (select para from oyun.cuzdan where user_id = u)
  ) into j
  from oyun.yatirim_mulkleri m join oyun.iller i on i.id = m.il_id where m.user_id = u;
  return j;
end $function$;

-- Belediye başkanı için: ildeki mülkler ve son 7 günün vergi geliri
create or replace function public.belediye_emlak_ozet() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); il smallint; t timestamptz := oyun.simdi();
begin
  select m.il_id into il from oyun.makamlar m where m.user_id = p.id and m.tur = 'bel' and m.bit is null limit 1;
  il := coalesce(il, p.il_id);
  return jsonb_build_object('il_id', il, 'il', (select ad from oyun.iller where id = il),
    'mulk', (select count(*) from oyun.yatirim_mulkleri where il_id = il),
    'haftalik_vergi', (select coalesce(sum(tutar), 0) from oyun.emlak_vergi_tahsilat where il_id = il and zaman > t - interval '7 days'),
    'toplam_vergi', (select coalesce(sum(tutar), 0) from oyun.emlak_vergi_tahsilat where il_id = il),
    'oran', oyun.mulk_vergi_oran(il), 'ulusal_oran', oyun.duz('mulk_vergi_ulusal'), 'carpan', oyun.il_duz(il, 'mulk_vergi_yerel'));
end $$;
revoke all on function public.belediye_emlak_ozet() from public, anon;
grant execute on function public.belediye_emlak_ozet() to authenticated;
-- =====================================================================
--  45 · 9 EKİM DENEME GEÇİŞLERİNİN TEMİZLİĞİ
--  9 Ekim'de aynı emlak/meclis isteği için birbirinin yerine geçen ~20 deneme migration'ı üretildi.
--  Canlıda hangileri çalıştırılmış olursa olsun bu modül onların bıraktığı tetikleyicileri,
--  eski satın alma kapılarını ve ölü kuralları kaldırır; geçerli tanım 43 ve 44 modülleridir.
--  Temiz bir kurulumda hiçbir şey yapmaz.
-- =====================================================================
do $$
declare r record;
begin
  -- 1) Kanunlar ve mülk tablosundaki deneme tetikleyicileri (geçerli olan yalnız mulk_devir_vergi)
  for r in select tgname, tgrelid::regclass rel from pg_trigger
           where not tgisinternal and tgrelid in ('oyun.kanunlar'::regclass, 'oyun.yatirim_mulkleri'::regclass)
             and tgname like 'emlak%' loop
    execute format('drop trigger if exists %I on %s', r.tgname, r.rel);
  end loop;

  -- 2) Deneme sürümlerinde kalan, yeni stok/fiyat kuralını atlayabilecek fonksiyonlar
  --    (geçerli emlak_* fonksiyonları yalnız emlak_pazarlik_* ve _emlak_pazarlik_tamamla)
  for r in select p.oid::regprocedure f from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname in ('oyun','public')
             and ((p.proname ~ '^(emlak_|belediye_emlak_vergi)' and p.proname !~ '^emlak_pazarlik')
                  or p.proname in ('kanun_karar_yeter','mulk_il_fiyat','mulk_katalog','mulk_satin_al_il','mulk_sehir_satin_al')) loop
    execute format('drop function if exists %s cascade', r.f);
  end loop;

  -- 2b) Eski uygulamanın çağırdığı tek parametreli mulk_satin_al dışındaki deneme kopyaları
  for r in select p.oid::regprocedure f from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname = 'mulk_satin_al' and p.pronargs <> 1 loop
    execute format('drop function if exists %s', r.f);
  end loop;

  -- 3) Deneme sütunlarındaki NOT NULL kısıtları yeni mülk eklemeyi engellemesin
  for r in select attname from pg_attribute
           where attrelid = 'oyun.yatirim_mulkleri'::regclass and attnum > 0 and not attisdropped and attnotnull
             and attname in ('emlak_vergi_son','emlak_vergi_sonraki','sonraki_emlak_vergi','sonraki_vergi','vergi_borcu','toplam_vergi') loop
    execute format('alter table oyun.yatirim_mulkleri alter column %I drop not null', r.attname);
  end loop;
end $$;

-- 4) Deneme sürümlerinin bekleyen "emlak vergisi" serbest kanun teklifleri düşer (artık "Kural düzenlemesi" kanunuyla değişir)
update oyun.kanunlar set durum = 'dustu', sonuc_at = oyun.simdi(),
  sonuc_metin = 'Teklif, mülk vergisi sisteminin yenilenmesiyle düştü. Haftalık mülk vergisi artık "Kural düzenlemesi" kanunuyla değiştirilir.'
where tur = 'serbest' and durum in ('gorusmede','oylamada','cb_onayinda','israr')
  and (veri ->> 'ozel_tur' = 'emlak_vergisi' or baslik ilike '%emlak vergi%');

-- 5) Deneme kurallarının kalıntıları (geçerli kodlar: mulk_vergi_ulusal, mulk_vergi_yerel)
--    ('emlak' = ildeki herkesin günlük emlak vergisi, asıl kuraldır; ona dokunulmaz)
delete from oyun.il_duzenleme where kod ~ '^(emlak_|yatirim_emlak)';
delete from oyun.duzenlemeler where kod ~ '^(emlak_|yatirim_emlak)';
delete from oyun.duzenleme_tanim where kod ~ '^(emlak_|yatirim_emlak)';
delete from oyun.yasa_ekonomi_ayar where kod = 'emlak_haftalik_baz';

-- 6) Bir deneme sürümü Meclis ölçeğini sabit 600'e bağlamıştı; asıl tanım (39) geri yüklenir.
create or replace function oyun.meclis_olcek_hesap(t timestamptz) returns jsonb
language plpgsql stable set search_path = '' as $$
declare a numeric := (select meclis_olcek from oyun.ayarlar where id = 1);
        anayasal int := coalesce((select round(deger)::int from oyun.anayasa where kod = 'milletvekili_sayisi'), 600);
        aktif int := (select count(*) from oyun.profiller where not yasakli and son_gorulme > t - interval '14 days');
        n int;
begin
  n := case when coalesce(a, 0) <= 0 then anayasal else least(anayasal, greatest(81, ceil(aktif * a)::int)) end;
  return jsonb_build_object('aktif', aktif, 'sandalye', n, 'anayasal', anayasal, 'olcek', a);
end $$;
-- =====================================================================
--  46 · CANLI MİTİNG MEYDANI
--  Miting artık bir "katıl" düğmesinden ibaret değil:
--    • Düzenleyen aday miting süresince kürsüden konuşur (en fazla 20 konuşma, her biri 400 karakter).
--    • Katılanlar her konuşmaya tepki verir: alkış (+1), tezahürat (+2), ıslık (-1), yuh (-2).
--      Tepki değiştirilebilir, her konuşmaya kişi başı bir tepki.
--    • Katılanlar kısa slogan atabilir (80 karakter, 20 saniyede bir, mitingte en fazla 30).
--    • Meydanın coşkusu (0-100) tepkilerden hesaplanır; miting bitince Gündem'e
--      katılım, coşku ve en çok alkış alan cümle haber olur.
--    • Başka ilden oyuncular mitingi canlı izleyebilir; tepki ve slogan yalnız katılanlardan.
--  Mevcut mitingler, katılımlar ve kıdem ödülü aynen korunur.
-- =====================================================================

create table if not exists oyun.miting_konusma(
  id        bigint generated always as identity primary key,
  miting_id bigint not null references oyun.mitingler(id) on delete cascade,
  user_id   uuid not null references oyun.profiller(id) on delete cascade,
  metin     text not null check (length(metin) between 1 and 400),
  zaman     timestamptz not null default now(),
  silindi   boolean not null default false
);
create index if not exists miting_konusma_m on oyun.miting_konusma(miting_id, id);

create table if not exists oyun.miting_tepki(
  konusma_id bigint not null references oyun.miting_konusma(id) on delete cascade,
  miting_id  bigint not null references oyun.mitingler(id) on delete cascade,
  user_id    uuid not null references oyun.profiller(id) on delete cascade,
  tur        text not null check (tur in ('alkis','tezahurat','islik','yuh')),
  zaman      timestamptz not null default now(),
  primary key (konusma_id, user_id)
);
create index if not exists miting_tepki_m on oyun.miting_tepki(miting_id);

create table if not exists oyun.miting_slogan(
  id        bigint generated always as identity primary key,
  miting_id bigint not null references oyun.mitingler(id) on delete cascade,
  user_id   uuid not null references oyun.profiller(id) on delete cascade,
  metin     text not null check (length(metin) between 1 and 80),
  zaman     timestamptz not null default now(),
  silindi   boolean not null default false
);
create index if not exists miting_slogan_m on oyun.miting_slogan(miting_id, id);

alter table oyun.mitingler add column if not exists cosku smallint;   -- bitince yazılır

do $$ declare t text; begin
  foreach t in array array['miting_konusma','miting_tepki','miting_slogan'] loop
    execute format('alter table oyun.%I enable row level security', t);
    execute format('revoke all on oyun.%I from public, anon, authenticated', t);
    if to_regproc('oyun.bosaltma_korumasi') is not null then
      execute format('drop trigger if exists bosaltma_korumasi on oyun.%I', t);
      execute format('create trigger bosaltma_korumasi before truncate on oyun.%I for each statement execute function oyun.bosaltma_korumasi()', t);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Hesaplar
-- ---------------------------------------------------------------------
create or replace function oyun.miting_tepki_puan(p_tur text) returns int language sql immutable as $$
  select case p_tur when 'alkis' then 1 when 'tezahurat' then 2 when 'islik' then -1 when 'yuh' then -2 else 0 end
$$;

-- Coşku 0-100: herkes her konuşmayı alkışlasa 75, tezahürat etse 100, yuhalasa 0. Tepki yoksa 50.
create or replace function oyun.miting_cosku(p_miting bigint) returns int language sql stable set search_path = '' as $$
  with k as (select count(*) n from oyun.miting_konusma where miting_id = p_miting and not silindi),
       c as (select count(*) n from oyun.miting_katilim k join oyun.mitingler m on m.id = k.miting_id where k.miting_id = p_miting and k.user_id <> m.user_id),
       tp as (select coalesce(sum(oyun.miting_tepki_puan(t.tur)), 0) net
              from oyun.miting_tepki t join oyun.miting_konusma x on x.id = t.konusma_id and not x.silindi
              where t.miting_id = p_miting)
  select greatest(0, least(100, round(50 + 25.0 * tp.net / greatest(1, c.n * greatest(1, k.n)))))::int from k, c, tp
$$;

create or replace function oyun.miting_cosku_ad(c int) returns text language sql immutable as $$
  select case when c is null then null when c >= 85 then 'Meydan coştu' when c >= 65 then 'Coşkulu'
              when c >= 45 then 'Ilık' when c >= 25 then 'Soğuk' else 'Yuhalandı' end
$$;

create or replace function oyun.miting_canli_mi(m oyun.mitingler, t timestamptz) returns boolean language sql immutable as $$
  select t >= m.bas and t < m.bit
$$;

-- ---------------------------------------------------------------------
-- Meydan ekranı
-- ---------------------------------------------------------------------
create or replace function public.miting_meydan(p_id bigint) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u uuid := auth.uid(); t timestamptz := oyun.simdi(); m oyun.mitingler; ben oyun.profiller; n int; c int;
begin
  select * into m from oyun.mitingler where id = p_id;
  if m.id is null then raise exception 'Miting bulunamadı.'; end if;
  select * into ben from oyun.profiller where id = u;
  select count(*) into n from oyun.miting_katilim where miting_id = m.id and user_id <> m.user_id;
  c := coalesce(case when t >= m.bit then m.cosku end, oyun.miting_cosku(m.id));
  return jsonb_build_object(
    'id', m.id, 'baslik', m.baslik, 'bas', m.bas, 'bit', m.bit, 'simdi', t,
    'canli', t >= m.bas and t < m.bit, 'bitti', t >= m.bit,
    'il', (select ad from oyun.iller where id = m.il_id), 'il_id', m.il_id,
    'kad', (select kad from oyun.profiller where id = m.user_id),
    'unvan', oyun.unvan(m.user_id),
    'parti', oyun.parti_json(m.parti_id),
    'slogan', (select k.slogan from oyun.parti_kimlik k where k.parti_id = m.parti_id),
    'secim_tur', (select tur from oyun.secimler where id = m.secim_id),
    'katilim', n, 'cosku', c, 'cosku_ad', oyun.miting_cosku_ad(c),
    'benim', m.user_id = u,
    'katildim', exists (select 1 from oyun.miting_katilim where miting_id = m.id and user_id = u),
    'katilabilir', ben.id is not null and ben.il_id = m.il_id and m.user_id <> u,
    'konusma_kalan', greatest(0, 20 - (select count(*) from oyun.miting_konusma where miting_id = m.id)),
    'son_katilanlar', (select coalesce(jsonb_agg(x.kad order by x.zaman desc), '[]'::jsonb) from (
        select p.kad, k.zaman from oyun.miting_katilim k join oyun.profiller p on p.id = k.user_id
        where k.miting_id = m.id and k.user_id <> m.user_id order by k.zaman desc limit 12) x),
    'konusmalar', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'metin', x.metin, 'zaman', x.zaman,
        'alkis', (select count(*) from oyun.miting_tepki r where r.konusma_id = x.id and r.tur = 'alkis'),
        'tezahurat', (select count(*) from oyun.miting_tepki r where r.konusma_id = x.id and r.tur = 'tezahurat'),
        'islik', (select count(*) from oyun.miting_tepki r where r.konusma_id = x.id and r.tur = 'islik'),
        'yuh', (select count(*) from oyun.miting_tepki r where r.konusma_id = x.id and r.tur = 'yuh'),
        'tepkim', (select r.tur from oyun.miting_tepki r where r.konusma_id = x.id and r.user_id = u)) order by x.id), '[]'::jsonb)
      from oyun.miting_konusma x where x.miting_id = m.id and not x.silindi),
    'sloganlar', (select coalesce(jsonb_agg(jsonb_build_object('id', y.id, 'kad', y.kad, 'metin', y.metin, 'zaman', y.zaman) order by y.id), '[]'::jsonb) from (
        select s.id, p.kad, s.metin, s.zaman from oyun.miting_slogan s join oyun.profiller p on p.id = s.user_id
        where s.miting_id = m.id and not s.silindi order by s.id desc limit 40) y)
  );
end $$;

-- Düzenleyen aday kürsüden konuşur
create or replace function public.miting_konus(p_id bigint, p_metin text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); m oyun.mitingler; x text; son timestamptz;
begin
  select * into m from oyun.mitingler where id = p_id for update;
  if m.id is null then raise exception 'Miting bulunamadı.'; end if;
  if m.user_id <> p.id then raise exception 'Kürsüde yalnız mitingi düzenleyen aday konuşabilir.'; end if;
  if t < m.bas then raise exception 'Miting henüz başlamadı; konuşmanı başlangıç saatinde yapabilirsin.'; end if;
  if t >= m.bit then raise exception 'Miting sona erdi.'; end if;
  if (select count(*) from oyun.miting_konusma where miting_id = m.id) >= 20 then
    raise exception 'Bir mitingde en fazla 20 kez kürsüye çıkabilirsin.';
  end if;
  select max(zaman) into son from oyun.miting_konusma where miting_id = m.id;
  if son is not null and son > t - interval '15 seconds' then
    raise exception 'Meydan önceki sözünü alkışlıyor; 15 saniye bekle.';
  end if;
  perform oyun.yazabilir_mi(p, t);
  x := oyun.metin_temizle(p_metin, 400);
  insert into oyun.miting_konusma(miting_id, user_id, metin, zaman) values (m.id, p.id, x, t);
  insert into oyun.miting_katilim(miting_id, user_id, zaman) values (m.id, p.id, t) on conflict do nothing;
  update oyun.profiller set son_mesaj = t where id = p.id;
  return public.miting_meydan(m.id);
end $$;

-- Katılan oyuncu bir konuşmaya tepki verir (değiştirebilir)
create or replace function public.miting_tepki(p_konusma bigint, p_tur text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); k oyun.miting_konusma; m oyun.mitingler;
begin
  if p_tur not in ('alkis','tezahurat','islik','yuh') then raise exception 'Geçersiz tepki.'; end if;
  select * into k from oyun.miting_konusma where id = p_konusma and not silindi;
  if k.id is null then raise exception 'Konuşma bulunamadı.'; end if;
  select * into m from oyun.mitingler where id = k.miting_id;
  if t < m.bas or t >= m.bit then raise exception 'Miting canlı değil; tepki verilemez.'; end if;
  if m.user_id = p.id then raise exception 'Kendi konuşmana tepki veremezsin.'; end if;
  if not exists (select 1 from oyun.miting_katilim where miting_id = m.id and user_id = p.id) then
    raise exception 'Tepki vermek için önce mitinge katıl.';
  end if;
  insert into oyun.miting_tepki(konusma_id, miting_id, user_id, tur, zaman) values (k.id, m.id, p.id, p_tur, t)
  on conflict (konusma_id, user_id) do update set tur = excluded.tur, zaman = excluded.zaman;
  return public.miting_meydan(m.id);
end $$;

-- Katılan oyuncu kısa slogan atar
create or replace function public.miting_slogan_at(p_id bigint, p_metin text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); m oyun.mitingler; x text; son timestamptz;
begin
  select * into m from oyun.mitingler where id = p_id;
  if m.id is null then raise exception 'Miting bulunamadı.'; end if;
  if t < m.bas or t >= m.bit then raise exception 'Miting canlı değil.'; end if;
  if m.user_id = p.id then raise exception 'Kürsüdesin; meydana kürsüden seslen.'; end if;
  if not exists (select 1 from oyun.miting_katilim where miting_id = m.id and user_id = p.id) then
    raise exception 'Slogan atmak için önce mitinge katıl.';
  end if;
  select max(zaman) into son from oyun.miting_slogan where miting_id = m.id and user_id = p.id;
  if son is not null and son > t - interval '20 seconds' then raise exception 'Sesin kısıldı; 20 saniye sonra yeniden slogan atabilirsin.'; end if;
  if (select count(*) from oyun.miting_slogan where miting_id = m.id and user_id = p.id) >= 30 then
    raise exception 'Bu mitingde yeterince slogan attın.';
  end if;
  perform oyun.yazabilir_mi(p, t);
  x := oyun.metin_temizle(p_metin, 80);
  insert into oyun.miting_slogan(miting_id, user_id, metin, zaman) values (m.id, p.id, x, t);
  update oyun.profiller set son_mesaj = t where id = p.id;
  return public.miting_meydan(m.id);
end $$;

-- Moderatör: uygunsuz konuşma ya da sloganı kaldırır (şikâyet yetkisi)
create or replace function public.miting_icerik_sil(p_tur text, p_id bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare mid bigint;
begin
  perform oyun.yetki_zorunlu('sikayet');
  if p_tur = 'konusma' then update oyun.miting_konusma set silindi = true where id = p_id returning miting_id into mid;
  elsif p_tur = 'slogan' then update oyun.miting_slogan set silindi = true where id = p_id returning miting_id into mid;
  else raise exception 'Geçersiz içerik türü.'; end if;
  if mid is null then raise exception 'İçerik bulunamadı.'; end if;
  return public.miting_meydan(mid);
end $$;

-- ---------------------------------------------------------------------
-- Mevcut fonksiyonların genişletilmesi
-- ---------------------------------------------------------------------
create or replace function public.mitingler() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kad', p.kad, 'parti', oyun.parti_json(m.parti_id), 'il_id', m.il_id,
      'il', (select ad from oyun.iller where id = m.il_id), 'baslik', m.baslik, 'bas', m.bas, 'bit', m.bit,
      'katilim', (select count(*) from oyun.miting_katilim c where c.miting_id = m.id),
      'katildim', exists (select 1 from oyun.miting_katilim c where c.miting_id = m.id and c.user_id = auth.uid()),
      'benim_ilim', m.il_id = (select il_id from oyun.profiller where id = auth.uid()),
      'benim', m.user_id = auth.uid(),
      'konusma', (select count(*) from oyun.miting_konusma k where k.miting_id = m.id and not k.silindi),
      'cosku', coalesce(m.cosku, case when m.bas <= oyun.simdi() then oyun.miting_cosku(m.id) end),
      'secim_tur', (select tur from oyun.secimler where id = m.secim_id)) order by m.bas), '[]'::jsonb)
  from oyun.mitingler m join oyun.profiller p on p.id = m.user_id
  where m.bit > oyun.simdi() - interval '6 hours' and m.bas < oyun.simdi() + interval '3 days'
$$;

create or replace function oyun.miting_tick(t timestamptz) returns void language plpgsql set search_path = '' as $$
declare m record; n int; c int; enIyi text; konusma int;
begin
  for m in select x.*, p.kad, i.ad il_ad from oyun.mitingler x join oyun.profiller p on p.id = x.user_id join oyun.iller i on i.id = x.il_id
           where not x.duyuruldu and x.bas <= t and x.bit > t loop
    update oyun.mitingler set duyuruldu = true where id = m.id;
    insert into oyun.bildirimler(user_id, zaman, metin)
      select pr.id, t, format('%s şu an %s meydanında: “%s”. Bir saat içinde Gündem''den mitinge katılıp konuşmaları dinleyebilir, tepki verebilirsin.', m.kad, m.il_ad, m.baslik)
      from oyun.profiller pr where pr.il_id = m.il_id and pr.id <> m.user_id and not pr.yasakli;
    perform oyun.bildir(m.user_id, format('%s mitingin başladı. Meydan seni bekliyor: Gündem''den mitingine girip kürsüden konuş.', m.il_ad), t);
    if oyun.push_acik() then
      perform oyun.push_konuya('s_il_' || m.il_id, null, format('%s meydanda!', m.kad),
        format('%s mitingi başladı: “%s”. Katılmak için dokun.', m.il_ad, m.baslik), jsonb_build_object('ekran', 'gundem'));
    end if;
  end loop;
  for m in select x.*, p.kad, i.ad il_ad from oyun.mitingler x join oyun.profiller p on p.id = x.user_id join oyun.iller i on i.id = x.il_id
           where not x.sonuc_yazildi and x.bit <= t loop
    select count(*) into n from oyun.miting_katilim where miting_id = m.id and user_id <> m.user_id;
    select count(*) into konusma from oyun.miting_konusma where miting_id = m.id and not silindi;
    c := oyun.miting_cosku(m.id);
    select left(k.metin, 120) into enIyi from oyun.miting_konusma k
      where k.miting_id = m.id and not k.silindi
        and exists (select 1 from oyun.miting_tepki r where r.konusma_id = k.id and oyun.miting_tepki_puan(r.tur) > 0)
      order by (select sum(oyun.miting_tepki_puan(r.tur)) from oyun.miting_tepki r where r.konusma_id = k.id) desc, k.id limit 1;
    update oyun.mitingler set sonuc_yazildi = true, duyuruldu = true, cosku = c where id = m.id;
    if konusma = 0 then
      perform oyun.olay('secim', format('%s, %s meydanında %s kişiyi topladı ama kürsüye hiç çıkmadı: “%s”.', m.kad, m.il_ad, n, m.baslik), m.il_id, m.parti_id, t);
    else
      perform oyun.olay('secim', format('%s %s mitingi: %s kişi, coşku %s/100 (%s).%s', m.kad, m.il_ad, n, c, lower(oyun.miting_cosku_ad(c)),
        case when enIyi is not null then format(' En çok alkışlanan söz: “%s”', enIyi) else '' end), m.il_id, m.parti_id, t);
    end if;
    perform oyun.bildir(m.user_id, format('%s mitingin sona erdi: %s kişi katıldı, %s kez kürsüye çıktın, meydanın coşkusu %s/100.', m.il_ad, n, konusma, c), t);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Yetkiler
-- ---------------------------------------------------------------------
revoke all on function public.miting_meydan(bigint), public.miting_konus(bigint, text), public.miting_tepki(bigint, text),
  public.miting_slogan_at(bigint, text), public.miting_icerik_sil(text, bigint) from public, anon;
grant execute on function public.miting_meydan(bigint), public.miting_konus(bigint, text), public.miting_tepki(bigint, text),
  public.miting_slogan_at(bigint, text), public.miting_icerik_sil(text, bigint) to authenticated;
revoke all on function oyun.miting_cosku(bigint), oyun.miting_tick(timestamptz) from public, anon, authenticated;
-- Oyun test sifirlamasi sonrasi oncelikli 13 hesabin kimlik bazli acilis bakiyesi.
-- Ayrı yonetim semasi sifirlama tarafindan temizlenmez, oyunculara acik degildir.
create schema if not exists oyun_yonetim;
revoke all on schema oyun_yonetim from public, anon, authenticated;
create table if not exists oyun_yonetim.onceki_test_oyuncu (
  user_id uuid primary key references auth.users(id) on delete cascade,
  kad text not null,
  eklendi timestamptz not null default now()
);
alter table oyun_yonetim.onceki_test_oyuncu enable row level security;
revoke all on oyun_yonetim.onceki_test_oyuncu from public, anon, authenticated;

create or replace function oyun.test_oncelikli_baslangic()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  -- Yalnizca eski hesap kimligi eslesirse: kullanici adi taklidi bonus vermez.
  if exists (select 1 from oyun_yonetim.onceki_test_oyuncu o
             where o.user_id = new.user_id) then
    new.para := 1000000;
  end if;
  return new;
end
$$;
drop trigger if exists test_oncelikli_baslangic on oyun.cuzdan;
create trigger test_oncelikli_baslangic
before insert on oyun.cuzdan for each row
execute function oyun.test_oncelikli_baslangic();

create or replace function oyun.test_yonetici_profilini_koru()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if exists (select 1 from oyun.yonetici_kimlik k where k.user_id = new.id)
     and not new.yonetici then
    update oyun.profiller set yonetici = true where id = new.id;
  end if;
  return null;
end
$$;
drop trigger if exists test_yonetici_profilini_koru on oyun.profiller;
create trigger test_yonetici_profilini_koru
after insert on oyun.profiller for each row
execute function oyun.test_yonetici_profilini_koru();
-- 2026-10-09 · Eyetkin hesabina ozel ucretsiz ve tek kisilik parti kurma.
-- Genel kurucu daveti ve 25.000 TL kurallari diger oyuncular icin degismez.
-- Yetki kullanici adina degil, mevcut Supabase Auth kullanici kimligine baglidir.

create table if not exists oyun_yonetim.ozel_parti_kurma_izni (
  user_id uuid primary key references auth.users(id) on delete cascade,
  aciklama text not null default 'Eyetkin - test istisnasi',
  tanimlama timestamptz not null default now()
);
alter table oyun_yonetim.ozel_parti_kurma_izni enable row level security;
revoke all on oyun_yonetim.ozel_parti_kurma_izni from public, anon, authenticated;

do $eyetkin_kimlik$
begin
  -- Temiz kurulumda henuz Eyetkin profili yoksa atlanir (49_celal_parti ile ayni); canli veritabaninda zaten tanimli.
  if (select count(*) from oyun.profiller where lower(kad)=lower('Eyetkin'))<>1 then
    raise notice 'Eyetkin profili tekil bulunamadi; istisna yetkisi atlandi.';
    return;
  end if;
  insert into oyun_yonetim.ozel_parti_kurma_izni(user_id)
  select id from oyun.profiller where lower(kad)=lower('Eyetkin')
  on conflict (user_id) do nothing;
end
$eyetkin_kimlik$;

create or replace function public.eyetkin_parti_kur(
  p_ad text, p_kisa text, p_renk text, p_amblem text, p_ideolojiler text[]
) returns jsonb
language plpgsql security definer set search_path='' as $eyetkin$
declare
  p oyun.profiller;
  t timestamptz:=oyun.simdi();
  yeni bigint;
begin
  if auth.uid() is null or not exists (
      select 1 from oyun_yonetim.ozel_parti_kurma_izni k where k.user_id=auth.uid()
  ) then
    raise exception 'Bu parti kurma istisnasi sadece yetkili hesaba aciktir.';
  end if;
  p:=oyun.profilim();
  if p.id is distinct from auth.uid() then
    raise exception 'Hesap dogrulanamadi.';
  end if;

  -- Normal parti kurma akisi ile ayni ad, kisa ad, renk ve amblem kontrolleri.
  p_ad:=btrim(regexp_replace(coalesce(p_ad,''),'\s+',' ','g'));
  p_kisa:=upper(btrim(coalesce(p_kisa,'')));
  if length(p_ad) not between 5 and 40
      or p_ad !~ '^[A-Za-zçğıöşüÇĞİÖŞÜâîûÂÎÛ'' .-]+$' then
    raise exception 'Parti adi 5-40 harften olusmali.';
  end if;
  if p_kisa !~ '^[A-ZÇĞİÖŞÜ]{2,6}$'
      or p_renk !~ '^#[0-9a-fA-F]{6}$'
      or p_amblem !~ '^[a-z_]{2,20}$' then
    raise exception 'Parti kisaltmasi, rengi veya amblemi gecersiz.';
  end if;
  if not oyun.ideoloji_gecerli(p_ideolojiler) then
    raise exception '1 ile 3 arasinda gecerli ideoloji secmelisin.';
  end if;
  if oyun.yasakli_ad(p_ad) or oyun.yasakli_kisa(p_kisa) then
    raise exception 'Yasakli veya gercek siyasi partiyle karisabilecek ad kullanilamaz.';
  end if;
  if exists (
      select 1 from oyun.partiler
      where not kapali and (lower(ad)=lower(p_ad) or lower(kisa)=lower(p_kisa))
  ) then
    raise exception 'Bu parti adi veya kisaltmasi kullanimda.';
  end if;
  if oyun.uyari(p,t) is not null then
    raise exception 'Parti kurma sarti: %', oyun.uyari(p,t);
  end if;
  if oyun.kidem_puani(p.id)<(select parti_kurucu_kidem from oyun.ayarlar where id=1) then
    raise exception 'Parti kurma kidemin yetersiz.';
  end if;
  if p.son_parti_kur is not null
      and p.son_parti_kur + make_interval(days=>(select parti_kur_gun from oyun.ayarlar where id=1))>t then
    raise exception 'Parti kurma bekleme suren dolmadi.';
  end if;

  -- Yalnizca bu hesap icin: kurucu davetlerini ve para kesintisini atla.
  perform oyun._ayril(p.id,t);
  insert into oyun.partiler(ad,kisa,renk,amblem,gb,kurucu,kurulus,kurulus_bit,kurulus_ucret)
  values(p_ad,p_kisa,lower(p_renk),p_amblem,p.id,p.id,t,null,0)
  returning id into yeni;
  perform oyun.genel_merkez_ac(yeni,p,0,t);
  update oyun.profiller
     set parti_id=yeni,parti_at=t,son_parti_kur=t
   where id=p.id;
  insert into oyun.parti_kimlik(parti_id,ideolojiler,guncelleme)
  values(yeni,p_ideolojiler,t);
  update oyun.kurucu_basvuru
     set durum='iptal'
   where kurucu=p.id and durum='bekliyor';
  perform oyun.olay(
    'parti', format('%s (%s) partisi %s tarafindan kuruldu.',p_ad,p_kisa,p.kad),
    p.il_id,yeni,t
  );
  return jsonb_build_object('parti_id',yeni,'kurucu_sayi',1,'sermaye',0,'tamam',true);
end
$eyetkin$;

revoke all on function public.eyetkin_parti_kur(text,text,text,text,text[]) from public, anon, authenticated;
grant execute on function public.eyetkin_parti_kur(text,text,text,text,text[]) to authenticated;
-- CELAL ve Eyetkin parti kurulusu icin ayni 0 TL / 0 davet istisnasini kullanir.
-- Istisna oyuncu adina degil auth kullanici kimligine baglidir; diger oyunculara acilmaz.
-- Temiz kurulumda henuz CELAL profili yoksa atlanir; canli migrasyonda zaten eklenmistir.
insert into oyun_yonetim.ozel_parti_kurma_izni(user_id,aciklama)
select id,'CELAL - test istisnasi' from oyun.profiller
where lower(kad)=lower('CELAL')
on conflict (user_id) do update set aciklama=excluded.aciklama;
-- =====================================================================
--  50 · İL DIŞI PARTİ MİTİNGİ + BAĞIMSIZ ADAYIN PARTİYE KATILMASI
--
--  1) Parti mitingi
--    • Genel başkan 81 ilin herhangi birinde parti adına miting düzenler.
--    • Genel başkan yardımcıları, genel başkan "miting yetkisi" verirse aynı hakka sahip olur.
--      Yetki her an geri alınabilir; geri alınınca başlamamış mitingler iptal olur, para iade edilir.
--    • Bedel ilin büyüklüğüne göredir (aday mitinginin bedeliyle aynı); parti kasası ya da
--      düzenleyenin kendi cebi öder.
--    • Her yetkili günde en fazla 1 parti mitingi; aynı partiden aynı ilde 3 gün içinde ikinci
--      parti mitingi olmaz; genel / belediye / cumhurbaşkanlığı seçimlerinin oy verme saatlerinde
--      parti mitingi yapılamaz.
--    • Miting başlayınca o ildeki herkese ve partinin tüm üyelerine bildirim gider. Kürsü, tepki,
--      slogan ve coşku canlı miting meydanının (46) aynısıdır; tepkiyi yalnız o ilde yaşayanlar verir.
--    • Aday mitingleri (39/46) değişmeden çalışır.
--
--  2) Bağımsız aday partiye katılabilir
--    • Oy verme başlamadan önce partiye katılan (ya da parti kuran) bağımsız adayın adaylığı
--      kendiliğinden düşer; başvuru harcı iade edilmez.
--    • Oy verme sürerken pusula kilitlidir; sandık kapanınca katılabilir.
--    • Seçimi kazanmış bağımsız vekil partiye katılabilir; Meclis grubu üyeliğe göre sayıldığı
--      için sandalyesi yeni partisine geçer.
--  Mevcut mitingler, adaylıklar ve oyuncu verisi aynen korunur.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Şema (yalnız ekleme)
-- ---------------------------------------------------------------------
alter table oyun.mitingler alter column secim_id drop not null;      -- parti mitingi bir seçime bağlı değildir
alter table oyun.mitingler add column if not exists tur text not null default 'aday';
alter table oyun.mitingler add column if not exists odeyen text not null default 'kisi';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'mitingler_tur_chk') then
    alter table oyun.mitingler add constraint mitingler_tur_chk check (tur in ('aday','parti'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'mitingler_odeyen_chk') then
    alter table oyun.mitingler add constraint mitingler_odeyen_chk check (odeyen in ('kisi','parti'));
  end if;
end $$;
create index if not exists mitingler_parti on oyun.mitingler(parti_id, il_id, bas) where tur = 'parti';

alter table oyun.parti_gby add column if not exists miting_yetkisi boolean not null default false;

-- ---------------------------------------------------------------------
-- Yardımcılar
-- ---------------------------------------------------------------------
-- Oyuncunun parti mitingi yetkisi: 'gb', 'gby' ya da null
create or replace function oyun.parti_miting_yetki(u uuid) returns text language sql stable set search_path = '' as $$
  select case
    when exists (select 1 from oyun.profiller p join oyun.partiler pa on pa.id = p.parti_id
                 where p.id = u and pa.gb = u and not pa.kapali) then 'gb'
    when exists (select 1 from oyun.profiller p join oyun.parti_gby g on g.parti_id = p.parti_id and g.user_id = u
                 join oyun.partiler pa on pa.id = p.parti_id
                 where p.id = u and g.miting_yetkisi and not pa.kapali) then 'gby'
  end
$$;

-- [p_bas, p_bit) aralığı bir genel / belediye / CB seçiminin oy verme saatlerine değiyor mu?
create or replace function oyun.miting_secim_yasagi(p_bas timestamptz, p_bit timestamptz) returns text
language sql stable set search_path = '' as $$
  select case s.tur when 'mv' then 'genel seçim' when 'bel' then 'belediye seçimi' else 'cumhurbaşkanlığı seçimi' end
  from oyun.secimler s
  where s.tur in ('mv','bel','cb','cb2') and s.durum = 'bekliyor'
    and s.oy_bas < p_bit and s.oy_bit > p_bas
  order by s.oy_bas limit 1
$$;

-- Başlamamış bir parti mitingini iptal eder; parayı ödeyene geri verir
create or replace function oyun.parti_miting_iptal(p_id bigint, p_neden text, t timestamptz) returns void
language plpgsql set search_path = '' as $$
declare m oyun.mitingler; ilad text;
begin
  delete from oyun.mitingler where id = p_id and tur = 'parti' and bas > t returning * into m;
  if m.id is null then return; end if;
  select ad into ilad from oyun.iller where id = m.il_id;
  if m.bedel > 0 then
    if m.odeyen = 'parti' and exists (select 1 from oyun.partiler where id = m.parti_id) then
      update oyun.partiler set kasa = kasa + m.bedel where id = m.parti_id;
      insert into oyun.parti_hareket(parti_id, zaman, tutar, aciklama, tur)
        values (m.parti_id, t, m.bedel, format('%s mitingi iptal edildi, bedel iade', ilad), 'miting');
    else
      perform oyun.para_islem(m.user_id, m.bedel, 'miting', format('%s mitingi iptal edildi, bedel iade', ilad), t);
    end if;
  end if;
  perform oyun.bildir(m.user_id, format('%s mitingin iptal edildi: %s. Bedeli iade edildi.', ilad, p_neden), t);
end $$;

-- Yetkisini kaybedenin (yetki geri alındı, görev bitti, partiden ayrıldı) başlamamış mitingleri düşer
create or replace function oyun.parti_miting_temizle(t timestamptz) returns void language plpgsql set search_path = '' as $$
declare r record;
begin
  for r in select m.id, m.user_id, m.parti_id from oyun.mitingler m
           where m.tur = 'parti' and m.bas > t loop
    if (select parti_id from oyun.profiller where id = r.user_id) is distinct from r.parti_id
       or oyun.parti_miting_yetki(r.user_id) is null then
      perform oyun.parti_miting_iptal(r.id, 'parti adına miting yetkin kalmadı', t);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Parti mitingi düzenle
-- ---------------------------------------------------------------------
create or replace function public.parti_miting_duzenle(p_il int, p_bas timestamptz, p_baslik text, p_kasadan boolean default true)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); pa oyun.partiler; yetki text;
        ilad text; b text; bedel numeric; yasak text; mid bigint; gun date;
begin
  select * into pa from oyun.partiler where id = p.parti_id and not kapali for update;
  if pa.id is null then raise exception 'Parti mitingi için bir partiye üye olmalısın.'; end if;
  yetki := oyun.parti_miting_yetki(p.id);
  if yetki is null then
    raise exception 'Parti adına miting yalnız genel başkan ve miting yetkisi verilmiş genel başkan yardımcıları tarafından düzenlenebilir.';
  end if;
  select ad into ilad from oyun.iller where id = p_il;
  if ilad is null then raise exception 'Geçersiz il.'; end if;
  if p_bas is null or p_bas < t + interval '15 minutes' then raise exception 'Mitingi en erken 15 dakika sonrasına koyabilirsin.'; end if;
  if p_bas > t + interval '3 days' then raise exception 'Mitingi en fazla 3 gün sonrasına planlayabilirsin.'; end if;
  yasak := oyun.miting_secim_yasagi(p_bas, p_bas + interval '1 hour');
  if yasak is not null then raise exception 'Seçim yasağı: % oy verme saatlerinde miting yapılamaz. Başka bir saat seç.', yasak; end if;
  b := oyun.metin_temizle(p_baslik, 80);
  if length(b) < 3 then raise exception 'Miting başlığı en az 3 karakter olmalı.'; end if;
  gun := (p_bas at time zone 'Europe/Istanbul')::date;
  if exists (select 1 from oyun.mitingler m where m.user_id = p.id and m.tur = 'parti'
             and (m.bas at time zone 'Europe/Istanbul')::date = gun) then
    raise exception 'Aynı gün için zaten bir parti mitingi düzenledin. Günde en fazla 1 parti mitingi yapılabilir.';
  end if;
  if exists (select 1 from oyun.mitingler m where m.parti_id = pa.id and m.tur = 'parti' and m.il_id = p_il
             and m.bas > p_bas - interval '3 days' and m.bas < p_bas + interval '3 days') then
    raise exception 'Partin % ilinde 3 gün içinde zaten miting yapıyor ya da yaptı. Aynı ilde iki parti mitingi arasında en az 3 gün olmalı.', ilad;
  end if;
  if exists (select 1 from oyun.mitingler m where m.il_id = p_il and m.bas < p_bas + interval '1 hour' and m.bit > p_bas) then
    raise exception 'Bu saatte % meydanında başka bir miting var. Başka bir saat seç.', ilad;
  end if;
  bedel := oyun.miting_bedel(p_il::smallint);
  if coalesce(p_kasadan, true) then
    if pa.kasa < bedel then
      raise exception '% mitingi için parti kasasında % ₺ olmalı (kasada % ₺ var). Bedeli kendi cebinden de ödeyebilirsin.',
        ilad, oyun.tl(bedel), oyun.tl(pa.kasa);
    end if;
    update oyun.partiler set kasa = kasa - bedel where id = pa.id;
    insert into oyun.parti_hareket(parti_id, zaman, tutar, aciklama, tur)
      values (pa.id, t, -bedel, format('%s mitingi (sahne, ses, ulaşım) · %s', ilad, p.kad), 'miting');
  else
    perform oyun.para_islem(p.id, -bedel, 'miting', format('%s parti mitingi (sahne, ses, ulaşım)', ilad), t);
  end if;
  insert into oyun.mitingler(user_id, secim_id, il_id, parti_id, baslik, bas, bit, bedel, tur, odeyen)
    values (p.id, null, p_il, pa.id, b, p_bas, p_bas + interval '1 hour', bedel, 'parti',
            case when coalesce(p_kasadan, true) then 'parti' else 'kisi' end)
    returning id into mid;
  perform oyun.olay('parti', format('%s %s %s, %s mitingi düzenleyecek: “%s” (%s).', pa.kisa,
      case yetki when 'gb' then 'Genel Başkanı' else 'Genel Başkan Yardımcısı' end, p.kad, ilad, b,
      to_char(p_bas at time zone 'Europe/Istanbul', 'DD.MM HH24:MI')), p_il::smallint, pa.id, t);
  return jsonb_build_object('id', mid, 'bedel', bedel, 'il', ilad, 'odeyen', case when coalesce(p_kasadan, true) then 'parti' else 'kisi' end);
end $$;

-- Parti ekranı için: yetkim, kasa, il bedelleri, yaklaşan parti mitingleri, GB ise yardımcıların yetkileri
create or replace function public.parti_miting_bilgi() returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); pa oyun.partiler; yetki text;
begin
  select * into pa from oyun.partiler where id = p.parti_id;
  if pa.id is null then return jsonb_build_object('yetki', null); end if;
  yetki := oyun.parti_miting_yetki(p.id);
  return jsonb_build_object(
    'yetki', yetki,
    'kasa', round(pa.kasa),
    'cuzdan', (select round(para) from oyun.cuzdan where user_id = p.id),
    'il_id', p.il_id,
    'iller', case when yetki is not null then (select jsonb_agg(jsonb_build_object('id', i.id, 'ad', i.ad, 'bedel', oyun.miting_bedel(i.id)) order by i.ad)
                                               from oyun.iller i) end,
    'yaklasan', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kad', x.kad, 'il', i.ad, 'baslik', m.baslik, 'bas', m.bas, 'bit', m.bit,
                    'odeyen', m.odeyen, 'bedel', m.bedel) order by m.bas), '[]'::jsonb)
                 from oyun.mitingler m join oyun.profiller x on x.id = m.user_id join oyun.iller i on i.id = m.il_id
                 where m.tur = 'parti' and m.parti_id = pa.id and m.bit > oyun.simdi()),
    'yardimcilar', case when yetki = 'gb' then (select coalesce(jsonb_agg(jsonb_build_object('sira', g.sira, 'kad', x.kad, 'yetki', g.miting_yetkisi) order by g.sira), '[]'::jsonb)
                   from oyun.parti_gby g join oyun.profiller x on x.id = g.user_id where g.parti_id = pa.id) end
  );
end $$;

-- Genel başkan bir yardımcısına miting yetkisi verir / geri alır
create or replace function public.gby_miting_yetkisi(p_kad text, p_ver boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); pa oyun.partiler; h oyun.profiller; r record;
begin
  select * into pa from oyun.partiler where id = p.parti_id and not kapali for update;
  if pa.id is null or pa.gb is distinct from p.id then raise exception 'Miting yetkisini yalnız genel başkan verebilir.'; end if;
  select * into h from oyun.profiller where lower(kad) = lower(btrim(p_kad));
  if h.id is null or not exists (select 1 from oyun.parti_gby where parti_id = pa.id and user_id = h.id) then
    raise exception 'Bu oyuncu partinin genel başkan yardımcısı değil.';
  end if;
  update oyun.parti_gby set miting_yetkisi = coalesce(p_ver, false) where parti_id = pa.id and user_id = h.id;
  if coalesce(p_ver, false) then
    perform oyun.bildir(h.id, format('Genel Başkan %s sana parti adına miting yetkisi verdi: artık 81 ilin herhangi birinde %s mitingi düzenleyebilirsin.', p.kad, pa.kisa), t);
  else
    for r in select id from oyun.mitingler where user_id = h.id and tur = 'parti' and bas > t loop
      perform oyun.parti_miting_iptal(r.id, 'genel başkan miting yetkini geri aldı', t);
    end loop;
    perform oyun.bildir(h.id, format('Genel Başkan %s parti adına miting yetkini geri aldı.', p.kad), t);
  end if;
  return public.parti_miting_bilgi();
end $$;

-- ---------------------------------------------------------------------
-- Liste: parti mitingi işareti
-- ---------------------------------------------------------------------
create or replace function public.mitingler() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kad', p.kad, 'parti', oyun.parti_json(m.parti_id), 'il_id', m.il_id,
      'il', (select ad from oyun.iller where id = m.il_id), 'baslik', m.baslik, 'bas', m.bas, 'bit', m.bit,
      'katilim', (select count(*) from oyun.miting_katilim c where c.miting_id = m.id),
      'katildim', exists (select 1 from oyun.miting_katilim c where c.miting_id = m.id and c.user_id = auth.uid()),
      'benim_ilim', m.il_id = (select il_id from oyun.profiller where id = auth.uid()),
      'benim', m.user_id = auth.uid(),
      'tur', m.tur,
      'partim', m.parti_id is not null and m.parti_id = (select parti_id from oyun.profiller where id = auth.uid()),
      'konusma', (select count(*) from oyun.miting_konusma k where k.miting_id = m.id and not k.silindi),
      'cosku', coalesce(m.cosku, case when m.bas <= oyun.simdi() then oyun.miting_cosku(m.id) end),
      'secim_tur', (select tur from oyun.secimler where id = m.secim_id)) order by m.bas), '[]'::jsonb)
  from oyun.mitingler m join oyun.profiller p on p.id = m.user_id
  where m.bit > oyun.simdi() - interval '6 hours' and m.bas < oyun.simdi() + interval '3 days'
$$;

-- ---------------------------------------------------------------------
-- Dakikalık motor: parti mitingi başlayınca partinin başka illerdeki üyelerine de haber gider
-- ---------------------------------------------------------------------
create or replace function oyun.miting_tick(t timestamptz) returns void language plpgsql set search_path = '' as $$
declare m record; n int; c int; enIyi text; konusma int;
begin
  perform oyun.parti_miting_temizle(t);
  for m in select x.*, p.kad, i.ad il_ad, pa.kisa parti_kisa from oyun.mitingler x join oyun.profiller p on p.id = x.user_id join oyun.iller i on i.id = x.il_id
           left join oyun.partiler pa on pa.id = x.parti_id
           where not x.duyuruldu and x.bas <= t and x.bit > t loop
    update oyun.mitingler set duyuruldu = true where id = m.id;
    insert into oyun.bildirimler(user_id, zaman, metin)
      select pr.id, t, format('%s şu an %s meydanında: “%s”. Bir saat içinde Gündem''den mitinge katılıp konuşmaları dinleyebilir, tepki verebilirsin.', m.kad, m.il_ad, m.baslik)
      from oyun.profiller pr where pr.il_id = m.il_id and pr.id <> m.user_id and not pr.yasakli;
    if m.tur = 'parti' then
      insert into oyun.bildirimler(user_id, zaman, metin)
        select pr.id, t, format('%s mitingi başladı: %s, %s meydanında “%s”. Gündem''den canlı izleyebilirsin.', m.parti_kisa, m.kad, m.il_ad, m.baslik)
        from oyun.profiller pr where pr.parti_id = m.parti_id and pr.il_id <> m.il_id and pr.id <> m.user_id and not pr.yasakli;
    end if;
    perform oyun.bildir(m.user_id, format('%s mitingin başladı. Meydan seni bekliyor: Gündem''den mitingine girip kürsüden konuş.', m.il_ad), t);
    if oyun.push_acik() then
      perform oyun.push_konuya('s_il_' || m.il_id, null, format('%s meydanda!', m.kad),
        format('%s mitingi başladı: “%s”. Katılmak için dokun.', m.il_ad, m.baslik), jsonb_build_object('ekran', 'gundem'));
    end if;
  end loop;
  for m in select x.*, p.kad, i.ad il_ad from oyun.mitingler x join oyun.profiller p on p.id = x.user_id join oyun.iller i on i.id = x.il_id
           where not x.sonuc_yazildi and x.bit <= t loop
    select count(*) into n from oyun.miting_katilim where miting_id = m.id and user_id <> m.user_id;
    select count(*) into konusma from oyun.miting_konusma where miting_id = m.id and not silindi;
    c := oyun.miting_cosku(m.id);
    select left(k.metin, 120) into enIyi from oyun.miting_konusma k
      where k.miting_id = m.id and not k.silindi
        and exists (select 1 from oyun.miting_tepki r where r.konusma_id = k.id and oyun.miting_tepki_puan(r.tur) > 0)
      order by (select sum(oyun.miting_tepki_puan(r.tur)) from oyun.miting_tepki r where r.konusma_id = k.id) desc, k.id limit 1;
    update oyun.mitingler set sonuc_yazildi = true, duyuruldu = true, cosku = c where id = m.id;
    if konusma = 0 then
      perform oyun.olay('secim', format('%s, %s meydanında %s kişiyi topladı ama kürsüye hiç çıkmadı: “%s”.', m.kad, m.il_ad, n, m.baslik), m.il_id, m.parti_id, t);
    else
      perform oyun.olay('secim', format('%s %s mitingi: %s kişi, coşku %s/100 (%s).%s', m.kad, m.il_ad, n, c, lower(oyun.miting_cosku_ad(c)),
        case when enIyi is not null then format(' En çok alkışlanan söz: “%s”', enIyi) else '' end), m.il_id, m.parti_id, t);
    end if;
    perform oyun.bildir(m.user_id, format('%s mitingin sona erdi: %s kişi katıldı, %s kez kürsüye çıktın, meydanın coşkusu %s/100.', m.il_ad, n, konusma, c), t);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- 2) Bağımsız aday partiye katılır: adaylık düşer (eskiden katılım engelleniyordu)
-- ---------------------------------------------------------------------
create or replace function oyun.bagimsiz_parti_kilidi()
returns trigger language plpgsql set search_path = '' as $$
declare t timestamptz := oyun.simdi(); r record; gorev text;
begin
  if old.parti_id is null and new.parti_id is not null then
    if exists (select 1 from oyun.adaylar a join oyun.secimler s on s.id = a.secim_id
               where a.user_id = new.id and a.parti_id is null and s.tur in ('mv','bel','cb','cb2')
                 and s.durum = 'bekliyor' and t >= s.oy_bas and t < s.oy_bit) then
      raise exception 'Oy verme sürüyor; bağımsız adaylığın pusulada. Sandık kapandıktan sonra partiye katılabilirsin.';
    end if;
    for r in delete from oyun.adaylar a using oyun.secimler s
             where a.secim_id = s.id and a.user_id = new.id and a.parti_id is null
               and s.tur in ('mv','bel','cb','cb2') and s.durum = 'bekliyor' and t < s.oy_bas
             returning a.il_id, s.tur loop
      gorev := case r.tur when 'mv' then 'milletvekili' when 'bel' then 'belediye başkanı' else 'cumhurbaşkanı' end;
      perform oyun.olay('secim', format('%s, bağımsız %s adaylığından çekilip partiye katıldı.', new.kad, gorev), r.il_id, new.parti_id, t);
      perform oyun.bildir(new.id, format('Partiye katıldığın için bağımsız %s adaylığın düştü. Başvuru harcı iade edilmez.', gorev), t);
    end loop;
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------
-- Yetkiler
-- ---------------------------------------------------------------------
revoke all on function public.parti_miting_duzenle(int, timestamptz, text, boolean), public.parti_miting_bilgi(),
  public.gby_miting_yetkisi(text, boolean) from public, anon;
grant execute on function public.parti_miting_duzenle(int, timestamptz, text, boolean), public.parti_miting_bilgi(),
  public.gby_miting_yetkisi(text, boolean) to authenticated;
revoke all on function oyun.parti_miting_iptal(bigint, text, timestamptz), oyun.parti_miting_temizle(timestamptz),
  oyun.miting_tick(timestamptz) from public, anon, authenticated;
-- 10.10.2026 | MatesTappen: tek basina, 0 TL ve serbest parti adi.
-- Oyundaki diger oyuncularin sartlarini veya mevcut partilerini degistirmez.
-- Yetki sadece kayitli Auth UUID'si icindir; ayni adi sonradan alan alamaz.
insert into oyun_yonetim.ozel_parti_kurma_izni(user_id,aciklama)
select id,'matestappen - serbest adli parti istisnasi'
from oyun.profiller
where lower(kad)=lower('matestappen')
on conflict (user_id) do update set aciklama=excluded.aciklama;

create or replace function public.matestappen_parti_kur(
  p_ad text,p_kisa text,p_renk text,p_amblem text,p_ideolojiler text[] default null
) returns jsonb
language plpgsql security definer set search_path='' as $matestappen$
declare
  p oyun.profiller;
  t timestamptz := oyun.simdi();
  yeni bigint;
  v_ideolojiler text[];
begin
  if auth.uid() is null
    or not exists (
      select 1 from oyun_yonetim.ozel_parti_kurma_izni o
      where o.user_id=auth.uid()
        and o.aciklama='matestappen - serbest adli parti istisnasi'
    ) then
    raise exception 'Serbest parti kurma yetkisi bu hesapta yok.';
  end if;
  p := oyun.profilim(); -- Yasakli profil de burada reddedilir.
  if p.id is distinct from auth.uid() then
    raise exception 'Oturum kimligi eslesmiyor.';
  end if;

  -- Parti adi serbesttir: normalde yasakli sayilan gercek parti adlari,
  -- sayilar, semboller ve 5-40 karakter kisiti bu hesaba uygulanmaz.
  -- Bos ad/kontrol karakteri ve mevcut aktif partiyle ayni ad teknik olarak reddedilir.
  p_ad := btrim(regexp_replace(coalesce(p_ad,''),'\s+',' ','g'));
  if char_length(p_ad) not between 1 and 80 or p_ad ~ '[[:cntrl:]]' then
    raise exception 'Parti adi 1-80 gorunur karakter olmali.';
  end if;
  p_kisa := upper(btrim(coalesce(p_kisa,'')));
  if p_kisa !~ '^[A-ZÇĞİÖŞÜ]{2,6}$' then
    raise exception 'Kisaltma 2-6 buyuk harften olusmali.';
  end if;
  if p_renk !~ '^#[0-9a-fA-F]{6}$' or p_amblem !~ '^[a-z_]{2,20}$' then
    raise exception 'Parti rengi ya da amblemi gecersiz.';
  end if;
  if exists (
    select 1 from oyun.partiler
    where not kapali
      and (lower(ad)=lower(p_ad) or lower(kisa)=lower(p_kisa))
  ) then
    raise exception 'Secilen parti adi veya kisaltmasi zaten kullaniliyor.';
  end if;
  v_ideolojiler := case when oyun.ideoloji_gecerli(p_ideolojiler)
                       then p_ideolojiler else array['karma']::text[] end;

  -- 25 bin TL, 3 kurucu, kidem, hesap yasi ve parti kurma beklemesi aranmaz.
  perform oyun._ayril(p.id,t);
  insert into oyun.partiler
    (ad,kisa,renk,amblem,gb,kurucu,kurulus,kurulus_bit,kurulus_ucret)
  values
    (p_ad,p_kisa,lower(p_renk),p_amblem,p.id,p.id,t,null,0)
  returning id into yeni;
  perform oyun.genel_merkez_ac(yeni,p,0,t);
  update oyun.profiller
     set parti_id=yeni,parti_at=t,son_parti_kur=t
   where id=p.id;
  insert into oyun.parti_kimlik(parti_id,ideolojiler,guncelleme)
  values(yeni,v_ideolojiler,t);
  update oyun.kurucu_basvuru
    set durum='iptal'
  where kurucu=p.id and durum='bekliyor';
  perform oyun.olay('parti',format('%s (%s) partisi %s tarafindan kuruldu.',p_ad,p_kisa,p.kad),p.il_id,yeni,t);
  return jsonb_build_object('parti_id',yeni,'kurucu_sayi',1,'sermaye',0,'tamam',true);
end
$matestappen$;

revoke all on function public.matestappen_parti_kur(text,text,text,text,text[]) from public,anon,authenticated;
grant execute on function public.matestappen_parti_kur(text,text,text,text,text[]) to authenticated;
-- =====================================================================
--  52 · GENEL BAŞKAN YARDIMCILARINA GÖREV + MİTİNG TEPKİSİNDE KENDİLİĞİNDEN KATILIM
--
--  1) Genel başkan, her yardımcısına bir görev alanı verir:
--     "Teşkilattan Sorumlu", "Seçim İşlerinden Sorumlu", … ya da kendi yazdığı bir alan (en fazla 60 karakter).
--     Unvan her yerde görünür: "CYP Teşkilattan Sorumlu Genel Başkan Yardımcısı".
--     Yardımcı değişince görev de sıfırlanır (yeni kişiye yeniden verilir).
--  2) Mitinge katılmamış ama o ilde yaşayan oyuncu bir söze tepki verirse önce mitinge katılmış sayılır
--     (eskiden "önce mitinge katıl" hatası veriyordu).
--  Oyuncu verisi değişmez; yalnız sütun ve fonksiyon eklenir.
-- =====================================================================

alter table oyun.parti_gby add column if not exists gorev text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'parti_gby_gorev_uzunluk') then
    alter table oyun.parti_gby add constraint parti_gby_gorev_uzunluk check (gorev is null or char_length(gorev) between 2 and 60);
  end if;
end $$;

-- "Teşkilattan Sorumlu" → "CYP Teşkilattan Sorumlu Genel Başkan Yardımcısı"
create or replace function oyun.gby_unvan(u uuid) returns text language sql stable set search_path = '' as $$
  select pa.kisa || ' ' || coalesce(nullif(btrim(g.gorev), '') || ' ', '') || 'Genel Başkan Yardımcısı'
  from oyun.parti_gby g join oyun.partiler pa on pa.id = g.parti_id where g.user_id = u limit 1
$$;

-- 20_siyasi_sistem'deki unvanın aynısı; yalnız yardımcı satırı görev alanını gösterir
create or replace function oyun.unvan(u uuid) returns text
language sql stable set search_path='' as $body$
  select coalesce(
    (select 'Başbakan' from oyun.hukumetler h where h.basbakan=u and h.durum='gorevde' and h.bit is null limit 1),
    (select 'Cumhurbaşkanı' from oyun.makamlar where user_id=u and tur='cb' and bit is null limit 1),
    (select replace(b.ad,'Bakanlığı','Bakanı') from oyun.makamlar m join oyun.bakanliklar b on b.kod=m.bakanlik
       where m.user_id=u and m.tur='bakan' and m.bit is null limit 1),
    (select pa.kisa||' Genel Başkanı' from oyun.partiler pa where pa.gb=u and not pa.kapali limit 1),
    (select i.ad||' Milletvekili' from oyun.makamlar m join oyun.iller i on i.id=m.il_id where m.user_id=u and m.tur='mv' and m.bit is null limit 1),
    (select i.ad||' Belediye Başkanı' from oyun.makamlar m join oyun.iller i on i.id=m.il_id where m.user_id=u and m.tur='bel' and m.bit is null limit 1),
    oyun.gby_unvan(u)
  )
$body$;

-- Partinin yardımcıları, görevleri ve miting yetkileri (parti ekranı için; herkes görebilir)
create or replace function public.gby_gorevleri(p_parti bigint) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('sira', g.sira, 'kad', x.kad, 'gorev', g.gorev, 'miting', g.miting_yetkisi) order by g.sira), '[]'::jsonb)
  from oyun.parti_gby g join oyun.profiller x on x.id = g.user_id where g.parti_id = p_parti
$$;

-- Genel başkan bir yardımcısına görev alanı verir (boş = görevi kaldır)
create or replace function public.gby_gorev_ver(p_kad text, p_gorev text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); pa oyun.partiler; h oyun.profiller; gv text;
begin
  select * into pa from oyun.partiler where id = p.parti_id and not kapali for update;
  if pa.id is null or pa.gb is distinct from p.id then raise exception 'Yardımcılara görevi yalnız genel başkan verebilir.'; end if;
  select * into h from oyun.profiller where lower(kad) = lower(btrim(coalesce(p_kad, '')));
  if h.id is null or not exists (select 1 from oyun.parti_gby where parti_id = pa.id and user_id = h.id) then
    raise exception 'Bu oyuncu partinin genel başkan yardımcısı değil.';
  end if;
  if coalesce(btrim(p_gorev), '') = '' then
    update oyun.parti_gby set gorev = null where parti_id = pa.id and user_id = h.id;
    perform oyun.bildir(h.id, format('Genel Başkan %s görev alanını kaldırdı; %s genel başkan yardımcısı olarak devam ediyorsun.', p.kad, pa.kisa), t);
    return public.gby_gorevleri(pa.id);
  end if;
  gv := regexp_replace(oyun.metin_temizle(p_gorev, 60), '\s+', ' ', 'g');
  gv := regexp_replace(gv, '\s*genel başkan yardımcı(sı|lığı)?\s*$', '', 'i');   -- "… Genel Başkan Yardımcısı" yazıldıysa tekrarlanmasın
  if char_length(gv) < 2 then raise exception 'Görev alanı en az 2 karakter olmalı.'; end if;
  update oyun.parti_gby set gorev = gv where parti_id = pa.id and user_id = h.id;
  perform oyun.bildir(h.id, format('Genel Başkan %s sana görev verdi: artık %s %s Genel Başkan Yardımcısısın.', p.kad, pa.kisa, gv), t);
  perform oyun.olay('parti', format('%s, %s %s Genel Başkan Yardımcısı oldu.', h.kad, pa.kisa, gv), null, pa.id, t);
  return public.gby_gorevleri(pa.id);
end $$;

-- 46'daki tepki; katılmamış ama o ilde yaşayan oyuncu tepki verince önce mitinge katılır
create or replace function public.miting_tepki(p_konusma bigint, p_tur text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); k oyun.miting_konusma; m oyun.mitingler;
begin
  if p_tur not in ('alkis','tezahurat','islik','yuh') then raise exception 'Geçersiz tepki.'; end if;
  select * into k from oyun.miting_konusma where id = p_konusma and not silindi;
  if k.id is null then raise exception 'Konuşma bulunamadı.'; end if;
  select * into m from oyun.mitingler where id = k.miting_id;
  if t < m.bas or t >= m.bit then raise exception 'Miting canlı değil; tepki verilemez.'; end if;
  if m.user_id = p.id then raise exception 'Kendi konuşmana tepki veremezsin.'; end if;
  if not exists (select 1 from oyun.miting_katilim where miting_id = m.id and user_id = p.id) then
    if p.il_id is distinct from m.il_id then
      raise exception 'Tepki vermek için % ilinde yaşamalısın; başka ilden mitingi yalnız izleyebilirsin.', (select ad from oyun.iller where id = m.il_id);
    end if;
    perform public.miting_katil(m.id);
  end if;
  insert into oyun.miting_tepki(konusma_id, miting_id, user_id, tur, zaman) values (k.id, m.id, p.id, p_tur, t)
  on conflict (konusma_id, user_id) do update set tur = excluded.tur, zaman = excluded.zaman;
  return public.miting_meydan(m.id);
end $$;

revoke all on function public.gby_gorevleri(bigint), public.gby_gorev_ver(text, text) from public, anon;
grant execute on function public.gby_gorevleri(bigint), public.gby_gorev_ver(text, text) to authenticated;
-- =====================================================================
--  53 · GENEL BAŞKAN YARDIMCISI GÖREVLERİNE YETKİ
--  Görev alanı (52) artık yetki de verir. Genel başkan her işi yapmaya devam eder; ek olarak:
--    • Teşkilattan Sorumlu      → il teşkilatı açar, Parti İl Başkanı atar/görevden alır.
--        Partide bu görevde yardımcı yoksa il teşkilatını eskisi gibi tüm yardımcılar açabilir.
--        Bu görevde biri varsa teşkilatı yalnız genel başkan ve o yardımcı açar.
--    • Seçim İşlerinden Sorumlu → miting yetkisi beklemeden 81 ilde parti mitingi düzenler, aday tanıtır.
--    • Tanıtım ve Medyadan Sorumlu → grup konuşması (parti duyurusu) yayımlar, aday tanıtır.
--    • Mali İşlerden Sorumlu    → parti kasasından üyeye kampanya desteği verir, adaylık ücretlerini ayarlar.
--    • Siyasi ve Hukuki İşlerden Sorumlu → üyeyi disipline sevk eder (genel başkanı sevk edemez).
--  Diğer görevler (ve serbest yazılanlar) unvandır, ek yetki vermez.
--  Fonksiyonlar canlıdaki hâllerinin üzerine kuruldu; yalnız yetki satırları değişti.
-- =====================================================================

-- Görev metni → yetki alanı
create or replace function oyun.gby_alan(p_gorev text) returns text language sql immutable set search_path = '' as $$
  select case btrim(coalesce(p_gorev, ''))
    when 'Teşkilattan Sorumlu' then 'teskilat'
    when 'Seçim İşlerinden Sorumlu' then 'secim'
    when 'Tanıtım ve Medyadan Sorumlu' then 'tanitim'
    when 'Mali İşlerden Sorumlu' then 'mali'
    when 'Siyasi ve Hukuki İşlerden Sorumlu' then 'hukuk'
  end
$$;

-- u, verilen alanlardan birinde partisi adına iş yapabiliyorsa partinin id'si (genel başkan her alanda yetkili)
create or replace function oyun.parti_gorevli(u uuid, p_alanlar text[]) returns bigint language sql stable set search_path = '' as $$
  select coalesce(
    (select pa.id from oyun.profiller p join oyun.partiler pa on pa.id = p.parti_id
      where p.id = u and pa.gb = u and not pa.kapali limit 1),
    (select pa.id from oyun.profiller p join oyun.parti_gby g on g.parti_id = p.parti_id and g.user_id = u
       join oyun.partiler pa on pa.id = p.parti_id
      where p.id = u and not pa.kapali and oyun.gby_alan(g.gorev) = any (p_alanlar) limit 1))
$$;

-- İl teşkilatı yöneticisi: genel başkan, Teşkilattan Sorumlu yardımcı; partide o görevde kimse yoksa her yardımcı
create or replace function oyun.teskilat_yonetici(u uuid, p_parti bigint) returns boolean language sql stable set search_path = '' as $$
  select exists (select 1 from oyun.partiler where id = p_parti and gb = u and not kapali)
      or exists (select 1 from oyun.parti_gby g where g.parti_id = p_parti and g.user_id = u
                  and (oyun.gby_alan(g.gorev) = 'teskilat'
                       or not exists (select 1 from oyun.parti_gby x where x.parti_id = p_parti and oyun.gby_alan(x.gorev) = 'teskilat')))
$$;

-- Arayüz için: oturumdaki oyuncunun partide yetkili olduğu alanlar
create or replace function public.parti_yetkilerim() returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'parti_id', p.parti_id,
    'gb', exists (select 1 from oyun.partiler where id = p.parti_id and gb = p.id),
    'alanlar', to_jsonb(array(select a from unnest(array['teskilat','secim','tanitim','mali','hukuk']) a
                              where oyun.parti_gorevli(p.id, array[a]) = p.parti_id)),
    'teskilat_acar', p.parti_id is not null and oyun.teskilat_yonetici(p.id, p.parti_id))
  from oyun.profiller p where p.id = auth.uid()
$$;

-- Seçim İşlerinden Sorumlu yardımcı ayrıca miting yetkisi beklemez
create or replace function oyun.parti_miting_yetki(u uuid) returns text language sql stable set search_path = '' as $$
  select case
    when exists (select 1 from oyun.profiller p join oyun.partiler pa on pa.id = p.parti_id
                 where p.id = u and pa.gb = u and not pa.kapali) then 'gb'
    when exists (select 1 from oyun.profiller p join oyun.parti_gby g on g.parti_id = p.parti_id and g.user_id = u
                 join oyun.partiler pa on pa.id = p.parti_id
                 where p.id = u and (g.miting_yetkisi or oyun.gby_alan(g.gorev) = 'secim') and not pa.kapali) then 'gby'
  end
$$;


CREATE OR REPLACE FUNCTION public.teskilat_ac2(p_il integer, p_kaynak text DEFAULT 'parti'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p oyun.profiller := oyun.profilim();
  pa oyun.partiler;
  t timestamptz := oyun.simdi();
  ucret numeric;
  ilad text;
  yonetim boolean;
  gorevli boolean;
begin
  select * into pa
  from oyun.partiler
  where id = p.parti_id and not kapali
  for update;

  if pa.id is null then raise exception 'Bir partiye üye değilsin.'; end if;

  yonetim := oyun.teskilat_yonetici(p.id, pa.id);   -- 53
  gorevli := exists(
    select 1 from oyun.parti_teskilat_gorev
    where parti_id = pa.id
      and il_id = p_il
      and user_id = p.id
      and aktif
  );

  if not yonetim and not gorevli then
    raise exception 'Bu ilde teşkilat açma yetkin yok.';
  end if;

  select ad into ilad from oyun.iller where id = p_il;
  if ilad is null then raise exception 'Geçersiz il.'; end if;

  if gorevli and p.il_id is distinct from p_il::smallint then
    raise exception 'Teşkilat sorumlusu yalnızca kayıtlı olduğu il için ödeme yapabilir.';
  end if;

  if oyun.teskilat_var(pa.id, p_il::smallint) then
    raise exception 'Partinin % ilinde zaten teşkilatı var.', ilad;
  end if;

  ucret := oyun.teskilat_ucreti(p_il::smallint);

  if p_kaynak = 'parti' then
    if not yonetim then
      raise exception 'Parti kasasından ödemeyi yalnızca genel başkan veya yardımcısı yapabilir.';
    end if;
    if pa.kasa < ucret then
      raise exception 'Parti kasasında yeterli para yok (% ₺ gerekli).', oyun.tl(ucret);
    end if;

    update oyun.partiler set kasa = kasa - ucret where id = pa.id;
    insert into oyun.parti_hareket(parti_id, zaman, tutar, aciklama, tur)
    values (
      pa.id, t, -ucret,
      format('%s il teşkilatı açıldı · parti kasası · %s', ilad, p.kad),
      'teskilat'
    );

  elsif p_kaynak = 'kendi' then
    perform oyun.para_islem(
      p.id, -ucret, 'teskilat',
      format('%s %s il teşkilatı kuruluş bedeli', pa.kisa, ilad),
      t
    );
    insert into oyun.parti_hareket(parti_id, zaman, tutar, aciklama, tur)
    values (
      pa.id, t, 0,
      format('%s il teşkilatı açıldı · %s kendi cüzdanından ödedi', ilad, p.kad),
      'teskilat_uye'
    );
  else
    raise exception 'Ödeme kaynağı parti veya kendi olmalı.';
  end if;

  insert into oyun.parti_teskilat(
    parti_id, il_id, kurulus, kuran, bedel
  ) values (pa.id, p_il, t, p.id, ucret);

  perform oyun.olay(
    'parti',
    format('%s, %s il teşkilatını açtı.', pa.kisa, ilad),
    p_il::smallint,
    pa.id,
    t
  );

  insert into oyun.bildirimler(user_id, zaman, metin)
  select
    id,
    t,
    format(
      '%s artık %s ilinde teşkilatlı: partin bu ilde milletvekili ve belediye başkanı adayı gösterebilir.',
      pa.kisa,
      ilad
    )
  from oyun.profiller
  where parti_id = pa.id
    and il_id = p_il
    and id <> p.id;

  return oyun.teskilat_json(pa.id, p);
end $function$;

CREATE OR REPLACE FUNCTION oyun.teskilat_json(p_parti bigint, p oyun.profiller)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'sayi', (select count(*) from oyun.parti_teskilat where parti_id = p_parti),
    'iller', coalesce((
      select jsonb_agg(jsonb_build_object(
        'il_id', t.il_id,
        'ad', i.ad,
        'kurulus', t.kurulus,
        'genel_merkez', t.genel_merkez,
        'uye', (select count(*) from oyun.profiller pr
                where pr.parti_id = p_parti and pr.il_id = t.il_id),
        'gorevli', (select oyun.kad(g.user_id)
                    from oyun.parti_teskilat_gorev g
                    where g.parti_id = p_parti
                      and g.il_id = t.il_id
                      and g.aktif)
      ) order by t.genel_merkez desc, i.ad)
      from oyun.parti_teskilat t
      join oyun.iller i on i.id = t.il_id
      where t.parti_id = p_parti
    ), '[]'::jsonb),
    'gorevler', coalesce((
      select jsonb_agg(jsonb_build_object(
        'il_id', g.il_id,
        'ad', i.ad,
        'kad', oyun.kad(g.user_id),
        'atama', g.atama,
        'teskilat_acik', oyun.teskilat_var(p_parti, g.il_id)
      ) order by i.ad)
      from oyun.parti_teskilat_gorev g
      join oyun.iller i on i.id = g.il_id
      where g.parti_id = p_parti and g.aktif
    ), '[]'::jsonb),
    'benim_gorevler', coalesce((
      select jsonb_agg(jsonb_build_object(
        'il_id', g.il_id,
        'ad', i.ad,
        'teskilat_acik', oyun.teskilat_var(p_parti, g.il_id),
        'ucret', oyun.teskilat_ucreti(g.il_id)
      ) order by i.ad)
      from oyun.parti_teskilat_gorev g
      join oyun.iller i on i.id = g.il_id
      where g.parti_id = p_parti and g.user_id = p.id and g.aktif
    ), '[]'::jsonb),
    'yetkili', p.parti_id = p_parti and oyun.teskilat_yonetici(p.id, p_parti),
    'gorev_verebilir', p.parti_id = p_parti and oyun.parti_gorevli(p.id, array['teskilat']) = p_parti,
    'zorunlu', (select teskilat_zorunlu from oyun.ayarlar where id = 1),
    'ucretler', jsonb_build_object(
      '1', round(a.teskilat_ucret * u.endeks),
      '2', round(a.teskilat_ucret * 2 * u.endeks),
      '3', round(a.teskilat_ucret * 3 * u.endeks)
    ),
    'kasa', (select round(kasa) from oyun.partiler where id = p_parti),
    'cuzdan', coalesce((select round(para) from oyun.cuzdan where user_id = p.id), 0),
    'benim_ilim_var', p.parti_id = p_parti
      and oyun.teskilat_var(p_parti, p.il_id)
  )
  from oyun.ayarlar a, oyun.ulke u
  where a.id = 1 and u.id = 1
$function$;

CREATE OR REPLACE FUNCTION public.teskilat_gorev_ver(p_il integer, p_kad text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p oyun.profiller:=oyun.profilim();
  h oyun.profiller;
  pa oyun.partiler;
  t timestamptz:=oyun.simdi();
  ilad text;
begin
  select * into pa from oyun.partiler where id=p.parti_id and not kapali;
  if pa.id is null or oyun.parti_gorevli(p.id, array['teskilat']) is distinct from pa.id then
    raise exception 'Parti il başkanını yalnızca genel başkan ve Teşkilattan Sorumlu Genel Başkan Yardımcısı atayabilir.';
  end if;

  h:=oyun.profil_bul(p_kad);
  if h.parti_id is distinct from pa.id then raise exception 'Yalnızca kendi partinin üyesini il başkanı yapabilirsin.'; end if;
  if h.il_id is distinct from p_il::smallint then raise exception 'İl başkanı, görev yapacağı ilde kayıtlı olmalı.'; end if;

  select ad into ilad from oyun.iller where id=p_il;
  if ilad is null then raise exception 'Geçersiz il.'; end if;

  insert into oyun.parti_teskilat_gorev(parti_id,il_id,user_id,atayan,atama,aktif)
  values(pa.id,p_il,h.id,p.id,t,true)
  on conflict(parti_id,il_id) do update
    set user_id=excluded.user_id,atayan=excluded.atayan,atama=excluded.atama,aktif=true;

  perform oyun.bildir(h.id,
    format('%s %s seni %s Parti İl Başkanı yaptı. Milletvekili olsan da bu görev devam eder. Teşkilat henüz açılmadıysa kuruluş bedelini kendi cüzdanından ödeyebilirsin.',
      case when pa.gb=p.id then pa.kisa||' Genel Başkanı' else oyun.gby_unvan(p.id) end,p.kad,ilad),t);

  return oyun.teskilat_json(pa.id,p);
end $function$;

CREATE OR REPLACE FUNCTION public.teskilat_gorev_al(p_il integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p oyun.profiller:=oyun.profilim();
  pa oyun.partiler;
  h uuid;
  t timestamptz:=oyun.simdi();
begin
  select * into pa from oyun.partiler where id=p.parti_id and not kapali;
  if pa.id is null or oyun.parti_gorevli(p.id, array['teskilat']) is distinct from pa.id then
    raise exception 'Bu görevi yalnızca genel başkan ve Teşkilattan Sorumlu Genel Başkan Yardımcısı kaldırabilir.';
  end if;

  select user_id into h from oyun.parti_teskilat_gorev
  where parti_id=pa.id and il_id=p_il and aktif for update;

  update oyun.parti_teskilat_gorev set aktif=false
  where parti_id=pa.id and il_id=p_il and aktif;

  if h is not null then perform oyun.bildir(h,'Parti İl Başkanlığı görevin sona erdirildi.',t); end if;
  return oyun.teskilat_json(pa.id,p);
end $function$;

CREATE OR REPLACE FUNCTION public.parti_destek(p_kad text, p_miktar numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); h oyun.profiller; pa oyun.partiler; m numeric := round(coalesce(p_miktar, 0));
begin
  select * into pa from oyun.partiler where id = p.parti_id for update;
  if pa.id is null or oyun.parti_gorevli(p.id, array['mali']) is distinct from pa.id then
    raise exception 'Parti kasasını yalnızca genel başkan ve Mali İşlerden Sorumlu Genel Başkan Yardımcısı kullanabilir.';
  end if;
  h := oyun.profil_bul(p_kad);
  if h.parti_id is distinct from pa.id then raise exception 'Yalnızca kendi partinin üyelerine destek verebilirsin.'; end if;
  if m < 100 then raise exception 'En az 100 ₺ destek verebilirsin.'; end if;
  if pa.kasa < m then raise exception 'Parti kasasında yeterli para yok (kasada % ₺ var).', oyun.tl(pa.kasa); end if;
  update oyun.partiler set kasa = kasa - m where id = pa.id;
  insert into oyun.parti_hareket(parti_id, zaman, tutar, aciklama, tur) values (pa.id, t, -m, format('%s üyesine kampanya desteği', h.kad), 'destek');
  perform oyun.para_islem(h.id, m, 'parti_destek', format('%s kampanya desteği', pa.kisa), t);
  perform oyun.bildir(h.id, format('%s %s, parti kasasından sana %s ₺ kampanya desteği gönderdi.', coalesce(oyun.unvan(p.id), 'Parti yönetiminden'), p.kad, oyun.tl(m)), t);
  return public.parti_kasa(pa.id);
end $function$;

CREATE OR REPLACE FUNCTION public.parti_ucret_ayarla(p_ucret jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); pa oyun.partiler; k text; v jsonb := '{}'; x numeric;
begin
  select * into pa from oyun.partiler where id = p.parti_id for update;
  if pa.id is null or oyun.parti_gorevli(p.id, array['mali']) is distinct from pa.id then
    raise exception 'Aday ücretlerini yalnızca genel başkan ve Mali İşlerden Sorumlu Genel Başkan Yardımcısı belirler.';
  end if;
  foreach k in array array['mv_on','bel_on','kurultay','cb_on'] loop
    x := round(coalesce((p_ucret ->> k)::numeric, (pa.aday_ucret ->> k)::numeric, 1), 2);
    if x < 0 or x > 3 then raise exception 'Çarpanlar 0 ile 3 arasında olmalı.'; end if;
    v := v || jsonb_build_object(k, x);
  end loop;
  update oyun.partiler set aday_ucret = v where id = pa.id;
  perform oyun.olay('parti', format('%s aday adaylığı ücretlerini güncelledi.', pa.kisa), null, pa.id, t);
  return public.parti_kasa(pa.id);
end $function$;

CREATE OR REPLACE FUNCTION public.parti_aday_tanit(p_aday bigint, p_kitle text, p_metin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid(); p oyun.partiler; a oyun.adaylar; s oyun.secimler;
 t timestamptz:=oyun.simdi(); metin text:=btrim(coalesce(p_metin,'')); newid bigint;
begin
 if u is null then raise exception 'Oturum açmalısın';end if;
 select * into p from oyun.partiler where id=oyun.parti_gorevli(u, array['secim','tanitim']) and not kapali;
 if not found then raise exception 'Adayları genel başkan ile Seçim İşlerinden ya da Tanıtım ve Medyadan Sorumlu Genel Başkan Yardımcısı tanıtabilir';end if;
 if p_kitle not in ('herkes','uyeler') or p_kitle is null then raise exception 'Tanıtım kitlesi geçersiz';end if;
 if length(metin)<20 or length(metin)>600 then raise exception 'Tanıtım 20-600 karakter olmalı';end if;
 select * into a from oyun.adaylar where id=p_aday;
 if not found then raise exception 'Aday kaydı bulunamadı';end if;
 select * into s from oyun.secimler where id=a.secim_id;
 if s.tur not in ('mv_on','cb_on','cb','bel_on','bel')
   or s.durum<>'bekliyor' or s.oy_bit<=t or s.basvuru_bas>t and s.tur in ('mv_on','cb_on','bel_on')
 then raise exception 'Bu seçimde aday tanıtım zamanı kapalı';end if;
 if a.parti_id is distinct from p.id
 and not (
   (s.tur='cb' and exists(select 1 from oyun.cb_kararlar k
      where k.donem=s.donem and k.parti_id=p.id and k.yontem='destek' and k.destek_parti=a.parti_id))
   or
   (s.tur='bel' and exists(select 1 from oyun.bel_aday_destek b
      where b.secim_id=s.id and b.parti_id=p.id and b.aday_id=a.id))
 ) then raise exception 'Yalnızca kendi partinin veya resmen desteklediğin adayı tanıtabilirsin';end if;
 if (select count(*) from oyun.parti_aday_tanitim where parti_id=p.id and zaman>=t-interval '24 hours')>=3
 then raise exception 'Partin 24 saatte en fazla 3 aday tanıtımı yapabilir';end if;
 insert into oyun.parti_aday_tanitim(parti_id,aday_id,kitle,metin,yayinlayan,zaman)
 values(p.id,a.id,p_kitle,metin,u,t) returning id into newid;
 if p_kitle='herkes' then
  perform oyun.olay('parti',left(p.kisa||' aday tanıtımı: '||oyun.kad(a.user_id),120),null,p.id,t);
 end if;
 return jsonb_build_object('tamam',true,'id',newid,'parti_id',p.id,'kitle',p_kitle);
end $function$;

CREATE OR REPLACE FUNCTION public.grup_duyuru_yayinla(p_baslik text, p_metin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare u uuid:=auth.uid(); pid bigint; bas text:=btrim(coalesce(p_baslik,'')); msg text:=btrim(coalesce(p_metin,''));
begin
 pid := oyun.parti_gorevli(u, array['tanitim']);
 if u is null or pid is null then raise exception 'Grup konuşmasını genel başkan ve Tanıtım ve Medyadan Sorumlu Genel Başkan Yardımcısı yayımlayabilir'; end if;
 if length(bas) not between 5 and 120 or length(msg) not between 10 and 3000 then raise exception 'Başlık 5-120, metin 10-3000 karakter olmalı'; end if;
 if (select count(*) from oyun.parti_grup_duyuru where yazan=u and zaman>now()-interval '1 day')>=3 then raise exception '24 saatte en çok 3 konuşma yayımlayabilirsin'; end if;
 insert into oyun.parti_grup_duyuru(parti_id,yazan,baslik,metin) values(pid,u,bas,msg);
 insert into oyun.bildirimler(user_id,zaman,metin)
 select id,now(),coalesce(oyun.unvan(u),'Partinin yönetimi')||' yeni grup konuşması yayımladı: '||left(bas,80)
 from oyun.profiller where parti_id=pid and id<>u;
 perform oyun.olay('parti','Yeni grup toplantısı konuşması: '||left(bas,100),null,pid,now());
 return public.grup_duyurulari(pid);
end $function$;

CREATE OR REPLACE FUNCTION public.disiplin_baslat(p_hedef text, p_gerekce text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'oyun', 'public', 'pg_temp'
AS $function$
declare u uuid:=auth.uid(); pid bigint; hedef uuid; cnt int; gerekce text:=btrim(coalesce(p_gerekce,''));
begin
 perform oyun.disiplin_sonuclandir();
 pid := oyun.parti_gorevli(u, array['hukuk']);
 if u is null or pid is null then raise exception 'Disiplin sürecini genel başkan ve Siyasi ve Hukuki İşlerden Sorumlu Genel Başkan Yardımcısı başlatabilir'; end if;
 if length(gerekce) not between 10 and 500 then raise exception 'Gerekçe 10-500 karakter olmalı'; end if;
 select id into hedef from oyun.profiller where lower(kad)=lower(btrim(p_hedef)) and parti_id=pid;
 if hedef is null or hedef=u then raise exception 'Bu partideki başka bir üyeyi seçmelisin'; end if;
 if exists (select 1 from oyun.partiler where id=pid and gb=hedef) then raise exception 'Genel başkan disipline sevk edilemez'; end if;
 select count(*) into cnt from oyun.profiller where parti_id=pid and id<>hedef;
 if cnt<1 then raise exception 'Oylamaya katılacak üye yok'; end if;
 insert into oyun.parti_disiplin(parti_id,hedef,baslatan,gerekce,bit,uyeler)
 values(pid,hedef,u,gerekce,now()+interval '24 hours',cnt);
 perform oyun.bildir(hedef,'Hakkında 24 saatlik parti disiplin oylaması başlatıldı.',now());
 return public.disiplin_durum(pid);
end $function$;


revoke all on function public.parti_yetkilerim() from public, anon;
grant execute on function public.parti_yetkilerim() to authenticated;
revoke all on function oyun.parti_gorevli(uuid, text[]), oyun.teskilat_yonetici(uuid, bigint) from public, anon, authenticated;
-- =====================================================================
--  54 · İTTİFAK TEKLİFİ VE İTTİFAK İÇİ ORTAK ADAY
--
--  1) Doğrudan ittifak teklifi
--     Genel başkan başka bir partinin sayfasından "İttifak teklif et" der.
--     Partisi bir ittifakta değilse ittifak (verdiği adla) kurulur ve teklif gider; ittifaktaysa davet gider.
--     Karşı partinin genel başkanı kabul ya da reddeder (07'deki ittifak_davet_yanit).
--
--  2) Ortak aday teklifi (ittifak ortakları arasında)
--     İttifaktaki bir partinin genel başkanı, ortak aday önerir:
--       • Cumhurbaşkanlığı: "X partisinin adayı ittifakın ortak adayı olsun"
--       • Belediye (il il): "<il>'de X partisinin adayı ittifakın ortak adayı olsun"
--     Öneren parti adayı çıkaran parti değilse kendi adayını o anda çeker ve destek verir.
--     Diğer ortaklar kabul edince kendi adayları çekilir, ortak adayı desteklerler (cb_destek / bel_aday_destek).
--     Reddeden ortak kendi adayıyla yarışmaya devam eder. Tüm ortaklar kabul edince "ittifakın ortak adayı" ilan edilir.
--     Zamanlama mevcut kurallara bağlıdır: CB kararı ayın 19-25'i, belediye ön seçim sonucundan oy verme başlayana kadar.
--  Oyuncu verisi değişmez; yalnız tablo ve fonksiyon eklenir.
-- =====================================================================

create table if not exists oyun.ittifak_ortak_teklif(
  id           bigint generated always as identity primary key,
  ittifak_id   bigint not null references oyun.ittifaklar(id) on delete cascade,
  tur          text not null check (tur in ('cb','bel')),
  secim_id     bigint not null references oyun.secimler(id) on delete cascade,
  il_id        smallint references oyun.iller(id),
  aday_parti   bigint not null references oyun.partiler(id) on delete cascade,
  aday_id      bigint references oyun.adaylar(id) on delete set null,
  teklif_eden  bigint not null references oyun.partiler(id) on delete cascade,
  zaman        timestamptz not null default now(),
  durum        text not null default 'bekliyor' check (durum in ('bekliyor','kabul','iptal'))
);
create index if not exists ittifak_ortak_teklif_i on oyun.ittifak_ortak_teklif(ittifak_id, durum);
create table if not exists oyun.ittifak_ortak_yanit(
  teklif_id bigint not null references oyun.ittifak_ortak_teklif(id) on delete cascade,
  parti_id  bigint not null references oyun.partiler(id) on delete cascade,
  kabul     boolean not null,
  zaman     timestamptz not null default now(),
  primary key (teklif_id, parti_id)
);
do $$ declare t text; begin
  foreach t in array array['ittifak_ortak_teklif','ittifak_ortak_yanit'] loop
    execute format('alter table oyun.%I enable row level security', t);
    execute format('revoke all on oyun.%I from public, anon, authenticated', t);
    if to_regproc('oyun.bosaltma_korumasi') is not null then
      execute format('drop trigger if exists bosaltma_korumasi on oyun.%I', t);
      execute format('create trigger bosaltma_korumasi before truncate on oyun.%I for each statement execute function oyun.bosaltma_korumasi()', t);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- 1) Doğrudan teklif
-- ---------------------------------------------------------------------
create or replace function public.ittifak_teklif(p_parti bigint, p_ad text default null) returns jsonb
language plpgsql security definer set search_path = oyun, public, pg_temp as $$
declare p oyun.profiller := oyun.profilim(); pa oyun.partiler; hedef oyun.partiler;
begin
  pa := oyun.gb_partim(p);
  select * into hedef from oyun.partiler where id = p_parti and not kapali;
  if hedef.id is null or hedef.id = pa.id then raise exception 'Geçersiz parti.'; end if;
  if exists (select 1 from oyun.ittifak_uyeler a join oyun.ittifak_uyeler b on a.ittifak_id = b.ittifak_id
             where a.parti_id = pa.id and b.parti_id = hedef.id) then
    raise exception '% ile zaten aynı ittifaktasınız.', hedef.kisa;
  end if;
  if exists (select 1 from oyun.ittifak_uyeler where parti_id = hedef.id) then
    raise exception '% başka bir ittifakta (%). Önce o ittifaktan ayrılması gerekir.', hedef.kisa,
      (select i.ad from oyun.ittifak_uyeler u join oyun.ittifaklar i on i.id = u.ittifak_id where u.parti_id = hedef.id);
  end if;
  if not exists (select 1 from oyun.ittifak_uyeler where parti_id = pa.id) then
    if coalesce(btrim(p_ad), '') = '' then raise exception 'Partin henüz bir ittifakta değil; kurulacak ittifaka bir ad ver.'; end if;
    perform public.ittifak_kur(p_ad);
  end if;
  perform public.ittifak_davet(hedef.id);
  return public.ittifak_bilgi(hedef.id);
end $$;

-- ---------------------------------------------------------------------
-- 2) Ortak aday
-- ---------------------------------------------------------------------
-- Bir partinin ittifak adına ortak adayı desteklemesi (kendi adayı çekilir)
create or replace function oyun.ortak_aday_uygula(o oyun.ittifak_ortak_teklif) returns void
language plpgsql set search_path = oyun, public, pg_temp as $$
begin
  if o.tur = 'cb' then perform public.cb_destek(o.aday_parti);
  else perform public.bel_aday_destek(o.il_id, o.aday_parti);
  end if;
end $$;

create or replace function oyun.ortak_teklif_json(o oyun.ittifak_ortak_teklif, benim bigint) returns jsonb
language sql stable set search_path = '' as $$
  select jsonb_build_object('id', o.id, 'tur', o.tur, 'il', (select ad from oyun.iller where id = o.il_id), 'il_id', o.il_id,
    'aday_parti', oyun.parti_json(o.aday_parti), 'aday', (select oyun.kad(a.user_id) from oyun.adaylar a where a.id = o.aday_id),
    'teklif_eden', oyun.parti_json(o.teklif_eden), 'zaman', o.zaman, 'durum', o.durum,
    'yanitlar', coalesce((select jsonb_agg(jsonb_build_object('parti', (select kisa from oyun.partiler where id = y.parti_id), 'kabul', y.kabul))
                          from oyun.ittifak_ortak_yanit y where y.teklif_id = o.id), '[]'::jsonb),
    'bekleyenler', coalesce((select jsonb_agg(pa.kisa) from oyun.ittifak_uyeler u join oyun.partiler pa on pa.id = u.parti_id
                             where u.ittifak_id = o.ittifak_id and u.parti_id <> o.aday_parti
                               and not exists (select 1 from oyun.ittifak_ortak_yanit y where y.teklif_id = o.id and y.parti_id = u.parti_id)), '[]'::jsonb),
    'yanit_bekliyor_benden', o.durum = 'bekliyor' and benim is not null and benim <> o.aday_parti
       and exists (select 1 from oyun.ittifak_uyeler u where u.ittifak_id = o.ittifak_id and u.parti_id = benim)
       and not exists (select 1 from oyun.ittifak_ortak_yanit y where y.teklif_id = o.id and y.parti_id = benim))
$$;

-- Tüm ortaklar kabul ettiyse ortak aday ilan edilir
create or replace function oyun.ortak_teklif_kontrol(p_id bigint, t timestamptz) returns void
language plpgsql set search_path = '' as $$
declare o oyun.ittifak_ortak_teklif; iad text; ne text;
begin
  select * into o from oyun.ittifak_ortak_teklif where id = p_id;
  if o.durum <> 'bekliyor' then return; end if;
  if exists (select 1 from oyun.ittifak_uyeler u where u.ittifak_id = o.ittifak_id and u.parti_id <> o.aday_parti
             and not exists (select 1 from oyun.ittifak_ortak_yanit y where y.teklif_id = o.id and y.parti_id = u.parti_id and y.kabul)) then
    return;
  end if;
  update oyun.ittifak_ortak_teklif set durum = 'kabul' where id = o.id;
  select ad into iad from oyun.ittifaklar where id = o.ittifak_id;
  ne := case o.tur when 'cb' then 'cumhurbaşkanı' else (select ad from oyun.iller where id = o.il_id) || ' belediye başkanı' end;
  perform oyun.olay('ittifak', format('%s, %s ortak adayını açıkladı: %s (%s).', iad, ne,
    (select oyun.kad(a.user_id) from oyun.adaylar a where a.id = o.aday_id), (select kisa from oyun.partiler where id = o.aday_parti)),
    o.il_id, o.aday_parti, t);
  insert into oyun.bildirimler(user_id, zaman, metin)
    select x.gb, t, format('%s ittifakının %s ortak adayı kesinleşti.', iad, ne)
    from oyun.ittifak_uyeler u join oyun.partiler x on x.id = u.parti_id where u.ittifak_id = o.ittifak_id and x.gb is not null;
end $$;

create or replace function public.ittifak_ortak_aday_teklif(p_tur text, p_il int, p_aday_parti bigint) returns jsonb
language plpgsql security definer set search_path = oyun, public, pg_temp as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); pa oyun.partiler; iid bigint; s oyun.secimler;
        a oyun.adaylar; o oyun.ittifak_ortak_teklif; ne text; ilad text;
begin
  pa := oyun.gb_partim(p);
  select ittifak_id into iid from oyun.ittifak_uyeler where parti_id = pa.id;
  if iid is null then raise exception 'Ortak aday önermek için partin bir ittifakta olmalı.'; end if;
  if not exists (select 1 from oyun.ittifak_uyeler where ittifak_id = iid and parti_id = p_aday_parti) then
    raise exception 'Ortak aday yalnız ittifaktaki bir partinin adayı olabilir.';
  end if;
  if (select count(*) from oyun.ittifak_uyeler where ittifak_id = iid) < 2 then raise exception 'İttifakta henüz ortağın yok.'; end if;
  if p_tur = 'cb' then
    select * into s from oyun.secimler where tur = 'cb' and t >= basvuru_bas and t < basvuru_bit order by ara desc, basvuru_bit limit 1;
    if s.id is null then raise exception 'Cumhurbaşkanı ortak adayı, aday belirleme döneminde (ayın 19-25''i) önerilebilir.'; end if;
    select * into a from oyun.adaylar where secim_id = s.id and parti_id = p_aday_parti order by basvuru_at, id limit 1;
    if a.id is null then raise exception '% henüz cumhurbaşkanı adayını açıklamadı.', (select kisa from oyun.partiler where id = p_aday_parti); end if;
    p_il := null; ne := 'cumhurbaşkanı';
  elsif p_tur = 'bel' then
    select ad into ilad from oyun.iller where id = p_il;
    if ilad is null then raise exception 'Geçersiz il.'; end if;
    select * into s from oyun.secimler where tur = 'bel' and durum = 'bekliyor' and oy_bas > t and (not ara or hedef_il_id = p_il)
      order by ara desc, oy_bas limit 1;
    if s.id is null then raise exception 'Belediye seçiminde ortak aday için uygun dönem yok (oy verme başlamadan önce olmalı).'; end if;
    select * into a from oyun.adaylar where secim_id = s.id and il_id = p_il and parti_id = p_aday_parti order by basvuru_at, id limit 1;
    if a.id is null then raise exception '% partisinin % ilinde kesinleşmiş belediye başkanı adayı yok (ön seçim sonucundan sonra önerilebilir).',
      (select kisa from oyun.partiler where id = p_aday_parti), ilad; end if;
    ne := ilad || ' belediye başkanı';
  else
    raise exception 'Ortak aday türü cb ya da bel olmalı.';
  end if;
  if exists (select 1 from oyun.ittifak_ortak_teklif where ittifak_id = iid and secim_id = s.id and il_id is not distinct from p_il and durum in ('bekliyor','kabul')) then
    raise exception 'Bu seçim için ittifakta zaten bir ortak aday önerisi var.';
  end if;
  insert into oyun.ittifak_ortak_teklif(ittifak_id, tur, secim_id, il_id, aday_parti, aday_id, teklif_eden, zaman)
    values (iid, p_tur, s.id, p_il, p_aday_parti, a.id, pa.id, t) returning * into o;
  -- Öneren parti adayı çıkaran değilse kendi adayını çeker, desteği o anda verir
  if pa.id <> p_aday_parti then
    perform oyun.ortak_aday_uygula(o);
    insert into oyun.ittifak_ortak_yanit(teklif_id, parti_id, kabul, zaman) values (o.id, pa.id, true, t);
  end if;
  insert into oyun.bildirimler(user_id, zaman, metin)
    select x.gb, t, format('%s, ittifakın %s ortak adayı olarak %s (%s) önerdi. Parti sayfasındaki İttifak kartından yanıtla.', pa.kisa, ne, oyun.kad(a.user_id),
      (select kisa from oyun.partiler where id = p_aday_parti))
    from oyun.ittifak_uyeler u join oyun.partiler x on x.id = u.parti_id
    where u.ittifak_id = iid and x.id <> pa.id and x.gb is not null;
  perform oyun.ortak_teklif_kontrol(o.id, t);
  return public.ittifak_masasi(pa.id);
end $$;

create or replace function public.ittifak_ortak_aday_yanit(p_teklif bigint, p_kabul boolean) returns jsonb
language plpgsql security definer set search_path = oyun, public, pg_temp as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); pa oyun.partiler; o oyun.ittifak_ortak_teklif;
begin
  pa := oyun.gb_partim(p);
  select * into o from oyun.ittifak_ortak_teklif where id = p_teklif for update;
  if o.id is null or o.durum <> 'bekliyor' then raise exception 'Bu öneri artık yanıt beklemiyor.'; end if;
  if not exists (select 1 from oyun.ittifak_uyeler where ittifak_id = o.ittifak_id and parti_id = pa.id) then raise exception 'Bu öneri senin ittifakına ait değil.'; end if;
  if pa.id = o.aday_parti then raise exception 'Adayı önerilen parti olarak yanıt vermen gerekmiyor.'; end if;
  if exists (select 1 from oyun.ittifak_ortak_yanit where teklif_id = o.id and parti_id = pa.id) then raise exception 'Bu öneriye zaten yanıt verdin.'; end if;
  if p_kabul then perform oyun.ortak_aday_uygula(o); end if;
  insert into oyun.ittifak_ortak_yanit(teklif_id, parti_id, kabul, zaman) values (o.id, pa.id, p_kabul, t);
  insert into oyun.bildirimler(user_id, zaman, metin)
    select x.gb, t, format('%s, ortak aday önerisini %s.', pa.kisa, case when p_kabul then 'kabul etti' else 'reddetti; kendi adayıyla yarışacak' end)
    from oyun.ittifak_uyeler u join oyun.partiler x on x.id = u.parti_id where u.ittifak_id = o.ittifak_id and x.id <> pa.id and x.gb is not null;
  perform oyun.ortak_teklif_kontrol(o.id, t);
  return public.ittifak_masasi(pa.id);
end $$;

-- Öneren parti bekleyen önerisini geri çeker (kabul eden ortakların desteği yerinde kalır; geri almak için mevcut "geri çek" kullanılır)
create or replace function public.ittifak_ortak_aday_iptal(p_teklif bigint) returns jsonb
language plpgsql security definer set search_path = oyun, public, pg_temp as $$
declare p oyun.profiller := oyun.profilim(); pa oyun.partiler;
begin
  pa := oyun.gb_partim(p);
  update oyun.ittifak_ortak_teklif set durum = 'iptal' where id = p_teklif and teklif_eden = pa.id and durum = 'bekliyor';
  if not found then raise exception 'Geri çekilecek bekleyen bir önerin yok.'; end if;
  return public.ittifak_masasi(pa.id);
end $$;

-- İttifak masası: öneriler, ortak adaylar, önerilebilecek adaylar
create or replace function public.ittifak_masasi(p_parti bigint) returns jsonb
language plpgsql security definer set search_path = oyun, public, pg_temp as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); iid bigint; cbs oyun.secimler; bels oyun.secimler; benim bigint;
begin
  select ittifak_id into iid from oyun.ittifak_uyeler where parti_id = p_parti;
  if iid is null then return jsonb_build_object('ittifak', null); end if;
  benim := case when exists (select 1 from oyun.partiler where id = p.parti_id and gb = p.id) then p.parti_id end;
  select * into cbs from oyun.secimler where tur = 'cb' and t >= basvuru_bas and t < basvuru_bit order by ara desc, basvuru_bit limit 1;
  select * into bels from oyun.secimler where tur = 'bel' and durum = 'bekliyor' and oy_bas > t order by ara desc, oy_bas limit 1;
  return jsonb_build_object(
    'ittifak', iid,
    'uyem', exists (select 1 from oyun.ittifak_uyeler where ittifak_id = iid and parti_id = p.parti_id),
    'gb', benim is not null and exists (select 1 from oyun.ittifak_uyeler where ittifak_id = iid and parti_id = benim),
    'oneriler', coalesce((select jsonb_agg(oyun.ortak_teklif_json(o, benim) order by o.durum = 'bekliyor' desc, o.zaman desc)
                          from oyun.ittifak_ortak_teklif o where o.ittifak_id = iid and o.durum <> 'iptal'
                            and exists (select 1 from oyun.secimler s where s.id = o.secim_id and s.durum = 'bekliyor')), '[]'::jsonb),
    'cb_acik', cbs.id is not null,
    'cb_adaylar', case when cbs.id is null then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('parti_id', a.parti_id,
        'parti', (select kisa from oyun.partiler where id = a.parti_id), 'kad', oyun.kad(a.user_id)))
        from oyun.adaylar a join oyun.ittifak_uyeler u on u.parti_id = a.parti_id and u.ittifak_id = iid where a.secim_id = cbs.id), '[]'::jsonb) end,
    'bel_acik', bels.id is not null,
    'bel_adaylar', case when bels.id is null then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('il_id', a.il_id, 'il', i.ad,
        'parti_id', a.parti_id, 'parti', (select kisa from oyun.partiler where id = a.parti_id), 'kad', oyun.kad(a.user_id)) order by i.ad)
        from oyun.adaylar a join oyun.ittifak_uyeler u on u.parti_id = a.parti_id and u.ittifak_id = iid join oyun.iller i on i.id = a.il_id
        where a.secim_id = bels.id), '[]'::jsonb) end
  );
end $$;

-- Ortaklıktan ayrılan partinin bekleyen önerileri düşer
create or replace function oyun.ortak_teklif_temizle() returns trigger language plpgsql set search_path = '' as $$
begin
  update oyun.ittifak_ortak_teklif set durum = 'iptal'
   where durum = 'bekliyor' and ittifak_id = old.ittifak_id and (teklif_eden = old.parti_id or aday_parti = old.parti_id);
  return old;
end $$;
drop trigger if exists ortak_teklif_temizle on oyun.ittifak_uyeler;
create trigger ortak_teklif_temizle after delete on oyun.ittifak_uyeler for each row execute function oyun.ortak_teklif_temizle();

revoke all on function public.ittifak_teklif(bigint, text), public.ittifak_ortak_aday_teklif(text, int, bigint),
  public.ittifak_ortak_aday_yanit(bigint, boolean), public.ittifak_ortak_aday_iptal(bigint), public.ittifak_masasi(bigint) from public, anon;
grant execute on function public.ittifak_teklif(bigint, text), public.ittifak_ortak_aday_teklif(text, int, bigint),
  public.ittifak_ortak_aday_yanit(bigint, boolean), public.ittifak_ortak_aday_iptal(bigint), public.ittifak_masasi(bigint) to authenticated;
revoke all on function oyun.ortak_aday_uygula(oyun.ittifak_ortak_teklif), oyun.ortak_teklif_kontrol(bigint, timestamptz) from public, anon, authenticated;
-- =====================================================================
--  55 · DERNEKLER VE SİVİL TOPLUM KURULUŞLARI
--
--  • Kuruluş: her oyuncu bir dernek kurabilir (kuruluş harcı 5.000 ₺ × fiyat düzeyi). Kurucu başkan olur,
--    kayıtlı olduğu il merkez şube olur. Bir oyuncu aynı anda yalnız bir derneğin başkanı olabilir.
--  • Üyelik: herkes ücretsiz üye olur (en fazla 5 dernek). Başkan en fazla 4 kişilik yönetim kurulu atar,
--    başkanlığı devredebilir. Son üye ayrılırsa dernek kapanır.
--  • Kasa: herkes bağış yapabilir (en az 100 ₺). Şubeler kasadan açılır.
--  • Şube: başkan/yönetim her ilde şube açar (1.000 ₺ × il büyüklüğü × fiyat düzeyi).
--  • Eylemler (başkan/yönetim):
--      basin    → basın açıklaması
--      bildiri  → bildiri
--      destek   → bir partiye ya da oyuncuya (adaya) destek açıklaması
--      protesto → şubesi olan bir ilde 1 saatlik protesto; o ilde yaşayan herkes katılabilir
--    Konu (hedef): genel bir konu, bir kanun, bir parti, başka bir dernek ya da bir oyuncu.
--    Yazılı açıklamalar derneğe günde en fazla 3; protesto derneğe günde 1, aynı ilde 3 günde 1; seçim günlerinin oy saatlerinde protesto yok.
--    Hedefteki parti genel başkanına / oyuncuya / dernek başkanına / kanunu teklif edene bildirim gider; her eylem Gündem'e haber olur.
--  Oyuncu verisi değişmez; yalnız tablo ve fonksiyon eklenir.
-- =====================================================================

create table if not exists oyun.dernekler(
  id        bigint generated always as identity primary key,
  ad        text not null check (char_length(ad) between 4 and 50),
  alan      text not null default 'genel',
  amac      text not null default '' check (char_length(amac) <= 600),
  baskan    uuid references oyun.profiller(id) on delete set null,
  kurucu    uuid references oyun.profiller(id) on delete set null,
  merkez_il smallint references oyun.iller(id),
  kasa      numeric not null default 0 check (kasa >= 0),
  kurulus   timestamptz not null default now(),
  kapali    boolean not null default false
);
create unique index if not exists dernek_ad_tek on oyun.dernekler(lower(ad)) where not kapali;

create table if not exists oyun.dernek_uyeler(
  dernek_id bigint not null references oyun.dernekler(id) on delete cascade,
  user_id   uuid not null references oyun.profiller(id) on delete cascade,
  rol       text not null default 'uye' check (rol in ('baskan','yonetim','uye')),
  katilim   timestamptz not null default now(),
  primary key (dernek_id, user_id)
);
create index if not exists dernek_uyeler_u on oyun.dernek_uyeler(user_id);

create table if not exists oyun.dernek_sube(
  dernek_id bigint not null references oyun.dernekler(id) on delete cascade,
  il_id     smallint not null references oyun.iller(id),
  kurulus   timestamptz not null default now(),
  kuran     uuid,
  bedel     numeric not null default 0,
  primary key (dernek_id, il_id)
);

create table if not exists oyun.dernek_hareket(
  id        bigint generated always as identity primary key,
  dernek_id bigint not null references oyun.dernekler(id) on delete cascade,
  zaman     timestamptz not null default now(),
  tutar     numeric not null,
  tur       text not null,
  aciklama  text not null,
  user_id   uuid
);
create index if not exists dernek_hareket_d on oyun.dernek_hareket(dernek_id, zaman desc);

create table if not exists oyun.dernek_eylem(
  id         bigint generated always as identity primary key,
  dernek_id  bigint not null references oyun.dernekler(id) on delete cascade,
  tur        text not null check (tur in ('basin','bildiri','destek','protesto')),
  baslik     text not null check (char_length(baslik) between 4 and 100),
  metin      text not null check (char_length(metin) between 10 and 2000),
  hedef_tur  text not null default 'genel' check (hedef_tur in ('genel','kanun','parti','dernek','oyuncu')),
  hedef_id   text,
  hedef_ad   text,
  il_id      smallint references oyun.iller(id),
  bas        timestamptz,
  bit        timestamptz,
  yazan      uuid,
  zaman      timestamptz not null default now(),
  duyuruldu  boolean not null default false,
  sonuc_yazildi boolean not null default false,
  silindi    boolean not null default false
);
create index if not exists dernek_eylem_d on oyun.dernek_eylem(dernek_id, zaman desc);
create index if not exists dernek_eylem_z on oyun.dernek_eylem(zaman desc);
create index if not exists dernek_eylem_p on oyun.dernek_eylem(il_id, bas) where tur = 'protesto';

create table if not exists oyun.dernek_protesto_katilim(
  eylem_id bigint not null references oyun.dernek_eylem(id) on delete cascade,
  user_id  uuid not null references oyun.profiller(id) on delete cascade,
  zaman    timestamptz not null default now(),
  primary key (eylem_id, user_id)
);

do $$ declare t text; begin
  foreach t in array array['dernekler','dernek_uyeler','dernek_sube','dernek_hareket','dernek_eylem','dernek_protesto_katilim'] loop
    execute format('alter table oyun.%I enable row level security', t);
    execute format('revoke all on oyun.%I from public, anon, authenticated', t);
    if to_regproc('oyun.bosaltma_korumasi') is not null then
      execute format('drop trigger if exists bosaltma_korumasi on oyun.%I', t);
      execute format('create trigger bosaltma_korumasi before truncate on oyun.%I for each statement execute function oyun.bosaltma_korumasi()', t);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Yardımcılar
-- ---------------------------------------------------------------------
create or replace function oyun.dernek_alan_ad(a text) returns text language sql immutable as $$
  select case a when 'genel' then 'Genel' when 'emek' then 'Emek ve Sendika' when 'cevre' then 'Çevre' when 'hak' then 'İnsan Hakları'
    when 'genclik' then 'Gençlik' when 'kadin' then 'Kadın' when 'egitim' then 'Eğitim' when 'esnaf' then 'Esnaf ve Meslek'
    when 'hayvan' then 'Hayvan Hakları' when 'kultur' then 'Kültür ve Sanat' when 'yerel' then 'Kent ve Yerel' else 'Genel' end
$$;

create or replace function oyun.dernek_json(p_id bigint) returns jsonb language sql stable set search_path = '' as $$
  select case when d.id is null then null else jsonb_build_object('id', d.id, 'ad', d.ad, 'alan', d.alan, 'alan_ad', oyun.dernek_alan_ad(d.alan)) end
  from (select 1) x left join oyun.dernekler d on d.id = p_id
$$;

create or replace function oyun.dernek_harci() returns numeric language sql stable set search_path = '' as $$
  select round(5000 * coalesce((select endeks from oyun.ulke where id = 1), 1) / 100) * 100
$$;
create or replace function oyun.dernek_sube_ucreti(p_il smallint) returns numeric language sql stable set search_path = '' as $$
  select round(1000 * oyun.il_buyukluk(p_il) * coalesce((select endeks from oyun.ulke where id = 1), 1) / 100) * 100
$$;

-- Başkan ya da yönetim kurulu üyesi mi? Değilse hata.
create or replace function oyun.dernek_yetkili(p_dernek bigint, u uuid) returns oyun.dernekler
language plpgsql stable set search_path = '' as $$
declare d oyun.dernekler;
begin
  select * into d from oyun.dernekler where id = p_dernek and not kapali;
  if d.id is null then raise exception 'Dernek bulunamadı.'; end if;
  if not exists (select 1 from oyun.dernek_uyeler where dernek_id = d.id and user_id = u and rol in ('baskan','yonetim')) then
    raise exception 'Bu işlemi derneğin başkanı ya da yönetim kurulu yapabilir.';
  end if;
  return d;
end $$;

-- ---------------------------------------------------------------------
-- Kuruluş, üyelik, yönetim
-- ---------------------------------------------------------------------
create or replace function public.dernek_kur(p_ad text, p_alan text, p_amac text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); v_ad text; harc numeric; yeni bigint; amac text;
begin
  if oyun.uyari(p, t) is not null then raise exception 'Dernek kurmak için: %', oyun.uyari(p, t); end if;
  if exists (select 1 from oyun.dernekler where baskan = p.id and not kapali) then raise exception 'Zaten bir derneğin başkanısın.'; end if;
  if (select count(*) from oyun.dernek_uyeler u join oyun.dernekler d on d.id = u.dernek_id where u.user_id = p.id and not d.kapali) >= 5 then
    raise exception 'En fazla 5 derneğe üye olabilirsin.';
  end if;
  v_ad := btrim(regexp_replace(coalesce(p_ad, ''), '\s+', ' ', 'g'));
  if char_length(v_ad) < 4 or char_length(v_ad) > 50 then raise exception 'Dernek adı 4-50 karakter olmalı.'; end if;
  if v_ad !~ '^[A-Za-zçğıöşüÇĞİÖŞÜâîûÂÎÛ0-9'' .,&-]+$' then raise exception 'Dernek adında yalnız harf, rakam ve noktalama kullanılabilir.'; end if;
  if oyun.yasakli_ad(v_ad) then raise exception 'Gerçek kurumları çağrıştıran ya da uygunsuz adlar kullanılamaz.'; end if;
  perform oyun.metin_temizle(v_ad, 50);
  if exists (select 1 from oyun.dernekler d where not d.kapali and lower(d.ad) = lower(v_ad)) then
    raise exception 'Bu adla bir dernek zaten var.';
  end if;
  amac := case when coalesce(btrim(p_amac), '') = '' then '' else oyun.metin_temizle(p_amac, 600) end;
  harc := oyun.dernek_harci();
  perform oyun.para_islem(p.id, -harc, 'dernek', format('%s kuruluş harcı', v_ad), t);
  insert into oyun.dernekler(ad, alan, amac, baskan, kurucu, merkez_il, kurulus)
    values (v_ad, case when p_alan in ('genel','emek','cevre','hak','genclik','kadin','egitim','esnaf','hayvan','kultur','yerel') then p_alan else 'genel' end,
            amac, p.id, p.id, p.il_id, t) returning id into yeni;
  insert into oyun.dernek_uyeler(dernek_id, user_id, rol, katilim) values (yeni, p.id, 'baskan', t);
  insert into oyun.dernek_sube(dernek_id, il_id, kurulus, kuran, bedel) values (yeni, p.il_id, t, p.id, 0);
  perform oyun.olay('dernek', format('%s, %s adıyla yeni bir sivil toplum kuruluşu kurdu (%s).', p.kad, v_ad, oyun.dernek_alan_ad(p_alan)), p.il_id, null, t);
  return public.dernek_detay(yeni);
end $$;

create or replace function public.dernek_katil(p_dernek bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); d oyun.dernekler;
begin
  select * into d from oyun.dernekler where id = p_dernek and not kapali;
  if d.id is null then raise exception 'Dernek bulunamadı.'; end if;
  if exists (select 1 from oyun.dernek_uyeler where dernek_id = d.id and user_id = p.id) then raise exception 'Zaten bu derneğin üyesisin.'; end if;
  if (select count(*) from oyun.dernek_uyeler u join oyun.dernekler x on x.id = u.dernek_id where u.user_id = p.id and not x.kapali) >= 5 then
    raise exception 'En fazla 5 derneğe üye olabilirsin.';
  end if;
  insert into oyun.dernek_uyeler(dernek_id, user_id, rol, katilim) values (d.id, p.id, 'uye', t);
  if d.baskan is not null then perform oyun.bildir(d.baskan, format('%s, %s derneğine üye oldu.', p.kad, d.ad), t); end if;
  return public.dernek_detay(d.id);
end $$;

create or replace function public.dernek_ayril(p_dernek bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); d oyun.dernekler; r text;
begin
  select * into d from oyun.dernekler where id = p_dernek and not kapali for update;
  if d.id is null then raise exception 'Dernek bulunamadı.'; end if;
  select rol into r from oyun.dernek_uyeler where dernek_id = d.id and user_id = p.id;
  if r is null then raise exception 'Bu derneğin üyesi değilsin.'; end if;
  if r = 'baskan' and exists (select 1 from oyun.dernek_uyeler where dernek_id = d.id and user_id <> p.id) then
    raise exception 'Başkan ayrılmadan önce başkanlığı bir üyeye devretmeli.';
  end if;
  delete from oyun.dernek_uyeler where dernek_id = d.id and user_id = p.id;
  if r = 'baskan' then
    update oyun.dernekler set kapali = true, baskan = null where id = d.id;
    perform oyun.olay('dernek', format('%s kapandı: son üyesi de ayrıldı.', d.ad), d.merkez_il, null, t);
  end if;
  return public.dernek_detay(d.id);
end $$;

-- Başkan bir üyeyi yönetim kuruluna alır (p_yonetim = true) ya da çıkarır
create or replace function public.dernek_yonetim_ata(p_dernek bigint, p_kad text, p_yonetim boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); d oyun.dernekler; h oyun.profiller;
begin
  select * into d from oyun.dernekler where id = p_dernek and not kapali for update;
  if d.id is null or d.baskan is distinct from p.id then raise exception 'Yönetim kurulunu yalnız derneğin başkanı belirler.'; end if;
  h := oyun.profil_bul(p_kad);
  if not exists (select 1 from oyun.dernek_uyeler where dernek_id = d.id and user_id = h.id and rol <> 'baskan') then
    raise exception 'Bu oyuncu derneğin üyesi değil.';
  end if;
  if p_yonetim and (select count(*) from oyun.dernek_uyeler where dernek_id = d.id and rol = 'yonetim') >= 4 then
    raise exception 'Yönetim kurulu en fazla 4 kişidir.';
  end if;
  update oyun.dernek_uyeler set rol = case when p_yonetim then 'yonetim' else 'uye' end where dernek_id = d.id and user_id = h.id;
  perform oyun.bildir(h.id, format(case when p_yonetim then '%s yönetim kuruluna alındın.' else '%s yönetim kurulundaki görevin sona erdi.' end, d.ad), t);
  return public.dernek_detay(d.id);
end $$;

create or replace function public.dernek_baskan_devret(p_dernek bigint, p_kad text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); d oyun.dernekler; h oyun.profiller;
begin
  select * into d from oyun.dernekler where id = p_dernek and not kapali for update;
  if d.id is null or d.baskan is distinct from p.id then raise exception 'Başkanlığı yalnız başkan devredebilir.'; end if;
  h := oyun.profil_bul(p_kad);
  if h.id = p.id or not exists (select 1 from oyun.dernek_uyeler where dernek_id = d.id and user_id = h.id) then raise exception 'Başkanlık yalnız derneğin başka bir üyesine devredilebilir.'; end if;
  if exists (select 1 from oyun.dernekler where baskan = h.id and not kapali) then raise exception '% zaten başka bir derneğin başkanı.', h.kad; end if;
  update oyun.dernek_uyeler set rol = 'yonetim' where dernek_id = d.id and user_id = p.id;
  update oyun.dernek_uyeler set rol = 'baskan' where dernek_id = d.id and user_id = h.id;
  update oyun.dernekler set baskan = h.id where id = d.id;
  perform oyun.bildir(h.id, format('%s başkanlığı sana devredildi.', d.ad), t);
  perform oyun.olay('dernek', format('%s başkanlığını %s devraldı.', d.ad, h.kad), d.merkez_il, null, t);
  return public.dernek_detay(d.id);
end $$;

-- ---------------------------------------------------------------------
-- Kasa ve şubeler
-- ---------------------------------------------------------------------
create or replace function public.dernek_bagis(p_dernek bigint, p_tutar numeric) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); d oyun.dernekler; m numeric := round(coalesce(p_tutar, 0));
begin
  select * into d from oyun.dernekler where id = p_dernek and not kapali for update;
  if d.id is null then raise exception 'Dernek bulunamadı.'; end if;
  if m < 100 then raise exception 'En az 100 ₺ bağış yapabilirsin.'; end if;
  perform oyun.para_islem(p.id, -m, 'dernek', format('%s derneğine bağış', d.ad), t);
  update oyun.dernekler set kasa = kasa + m where id = d.id;
  insert into oyun.dernek_hareket(dernek_id, zaman, tutar, tur, aciklama, user_id) values (d.id, t, m, 'bagis', format('%s bağış yaptı', p.kad), p.id);
  if d.baskan is not null and d.baskan <> p.id then perform oyun.bildir(d.baskan, format('%s, %s derneğine %s ₺ bağış yaptı.', p.kad, d.ad, oyun.tl(m)), t); end if;
  return public.dernek_detay(d.id);
end $$;

create or replace function public.dernek_sube_ac(p_dernek bigint, p_il int) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); d oyun.dernekler; u numeric; ilad text;
begin
  d := oyun.dernek_yetkili(p_dernek, p.id);
  select ad into ilad from oyun.iller where id = p_il;
  if ilad is null then raise exception 'Geçersiz il.'; end if;
  if exists (select 1 from oyun.dernek_sube where dernek_id = d.id and il_id = p_il) then raise exception 'Derneğin % ilinde zaten şubesi var.', ilad; end if;
  u := oyun.dernek_sube_ucreti(p_il::smallint);
  update oyun.dernekler set kasa = kasa - u where id = d.id and kasa >= u;
  if not found then raise exception '% şubesi için dernek kasasında % ₺ olmalı (kasada % ₺ var). Üyeler bağış yaparak kasayı doldurabilir.', ilad, oyun.tl(u), oyun.tl(d.kasa); end if;
  insert into oyun.dernek_hareket(dernek_id, zaman, tutar, tur, aciklama, user_id) values (d.id, t, -u, 'sube', format('%s şubesi açıldı · %s', ilad, p.kad), p.id);
  insert into oyun.dernek_sube(dernek_id, il_id, kurulus, kuran, bedel) values (d.id, p_il, t, p.id, u);
  perform oyun.olay('dernek', format('%s, %s şubesini açtı.', d.ad, ilad), p_il::smallint, null, t);
  return public.dernek_detay(d.id);
end $$;

-- ---------------------------------------------------------------------
-- Eylemler: basın açıklaması, bildiri, destek, protesto
-- ---------------------------------------------------------------------
create or replace function public.dernek_eylem(p_dernek bigint, p_tur text, p_baslik text, p_metin text,
  p_hedef_tur text default 'genel', p_hedef text default null, p_il int default null, p_bas timestamptz default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); d oyun.dernekler; b text; m text; hid text; had text;
        bildir_u uuid; ilad text; yasak text; eid bigint; tur_ad text; ht text := coalesce(p_hedef_tur, 'genel');
begin
  d := oyun.dernek_yetkili(p_dernek, p.id);
  if p_tur not in ('basin','bildiri','destek','protesto') then raise exception 'Geçersiz eylem türü.'; end if;
  perform oyun.yazabilir_mi(p, t);
  b := oyun.metin_temizle(p_baslik, 100);
  if char_length(b) < 4 then raise exception 'Başlık en az 4 karakter olmalı.'; end if;
  m := oyun.metin_temizle(p_metin, 2000);
  if char_length(m) < 10 then raise exception 'Metin en az 10 karakter olmalı.'; end if;

  -- Konu / hedef
  if ht = 'genel' then
    hid := null; had := case when coalesce(btrim(p_hedef), '') = '' then null else oyun.metin_temizle(p_hedef, 80) end;
  elsif ht = 'kanun' then
    select k.id::text, k.baslik, k.teklif_eden into hid, had, bildir_u from oyun.kanunlar k where k.id = nullif(p_hedef, '')::bigint;
    if hid is null then raise exception 'Kanun bulunamadı.'; end if;
  elsif ht = 'parti' then
    select x.id::text, x.ad, x.gb into hid, had, bildir_u from oyun.partiler x where x.id = nullif(p_hedef, '')::bigint and not x.kapali;
    if hid is null then raise exception 'Parti bulunamadı.'; end if;
  elsif ht = 'dernek' then
    select x.id::text, x.ad, x.baskan into hid, had, bildir_u from oyun.dernekler x where x.id = nullif(p_hedef, '')::bigint and not x.kapali;
    if hid is null then raise exception 'Dernek bulunamadı.'; end if;
    if hid = d.id::text then raise exception 'Derneğin kendisini hedef gösteremezsin.'; end if;
  elsif ht = 'oyuncu' then
    select x.id::text, x.kad, x.id into hid, had, bildir_u from oyun.profiller x where lower(x.kad) = lower(btrim(coalesce(p_hedef, ''))) and not x.yasakli;
    if hid is null then raise exception 'Oyuncu bulunamadı.'; end if;
  else
    raise exception 'Geçersiz konu türü.';
  end if;
  if p_tur = 'destek' and ht not in ('parti','oyuncu') then raise exception 'Destek açıklaması bir partiye ya da bir oyuncuya (adaya) yapılır.'; end if;

  if p_tur in ('basin','bildiri','destek') then
    if (select count(*) from oyun.dernek_eylem where dernek_id = d.id and tur <> 'protesto' and zaman >= t - interval '24 hours') >= 3 then
      raise exception 'Dernek 24 saatte en fazla 3 açıklama yapabilir.';
    end if;
    insert into oyun.dernek_eylem(dernek_id, tur, baslik, metin, hedef_tur, hedef_id, hedef_ad, yazan, zaman, duyuruldu, sonuc_yazildi)
      values (d.id, p_tur, b, m, ht, hid, had, p.id, t, true, true) returning id into eid;
    tur_ad := case p_tur when 'basin' then 'basın açıklaması yaptı' when 'bildiri' then 'bildiri yayımladı' else 'destek açıkladı' end;
    perform oyun.olay('dernek', format('%s %s%s: “%s”', d.ad, tur_ad, case when had is not null then format(' (%s)', had) else '' end, b),
      d.merkez_il, case when ht = 'parti' then hid::bigint end, t);
  else
    -- Protesto
    if p_il is null then p_il := d.merkez_il; end if;
    select ad into ilad from oyun.iller where id = p_il;
    if ilad is null then raise exception 'Geçersiz il.'; end if;
    if not exists (select 1 from oyun.dernek_sube where dernek_id = d.id and il_id = p_il) then
      raise exception 'Protesto yalnız derneğin şubesi olan illerde düzenlenebilir (% ilinde şube yok).', ilad;
    end if;
    if p_bas is null or p_bas < t + interval '15 minutes' then raise exception 'Protestoyu en erken 15 dakika sonrasına koyabilirsin.'; end if;
    if p_bas > t + interval '3 days' then raise exception 'Protestoyu en fazla 3 gün sonrasına planlayabilirsin.'; end if;
    yasak := oyun.miting_secim_yasagi(p_bas, p_bas + interval '1 hour');
    if yasak is not null then raise exception 'Seçim yasağı: % oy verme saatlerinde protesto yapılamaz.', yasak; end if;
    if exists (select 1 from oyun.dernek_eylem where dernek_id = d.id and tur = 'protesto' and not silindi
               and (bas at time zone 'Europe/Istanbul')::date = (p_bas at time zone 'Europe/Istanbul')::date) then
      raise exception 'Dernek aynı gün için zaten bir protesto düzenledi.';
    end if;
    if exists (select 1 from oyun.dernek_eylem where dernek_id = d.id and tur = 'protesto' and not silindi and il_id = p_il
               and bas > p_bas - interval '3 days' and bas < p_bas + interval '3 days') then
      raise exception 'Dernek % ilinde 3 gün içinde zaten protesto yapıyor ya da yaptı.', ilad;
    end if;
    insert into oyun.dernek_eylem(dernek_id, tur, baslik, metin, hedef_tur, hedef_id, hedef_ad, il_id, bas, bit, yazan, zaman)
      values (d.id, 'protesto', b, m, ht, hid, had, p_il, p_bas, p_bas + interval '1 hour', p.id, t) returning id into eid;
    perform oyun.olay('dernek', format('%s, %s''de protesto düzenleyecek: “%s”%s (%s).', d.ad, ilad, b,
      case when had is not null then format(' · %s', had) else '' end, to_char(p_bas at time zone 'Europe/Istanbul', 'DD.MM HH24:MI')), p_il::smallint, null, t);
  end if;

  if bildir_u is not null and bildir_u <> p.id then
    perform oyun.bildir(bildir_u, format('%s %s hakkında %s: “%s”', d.ad,
      case ht when 'parti' then 'partin' when 'oyuncu' then 'senin' when 'dernek' then 'derneğin' else 'teklif ettiğin kanun' end,
      case p_tur when 'basin' then 'basın açıklaması yaptı' when 'bildiri' then 'bildiri yayımladı' when 'destek' then 'destek açıkladı' else 'protesto düzenliyor' end, b), t);
  end if;
  return public.dernek_detay(d.id);
end $$;

create or replace function public.dernek_protesto_katil(p_eylem bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); e oyun.dernek_eylem; n int;
begin
  select * into e from oyun.dernek_eylem where id = p_eylem and tur = 'protesto' and not silindi;
  if e.id is null then raise exception 'Protesto bulunamadı.'; end if;
  if t < e.bas then raise exception 'Protesto henüz başlamadı.'; end if;
  if t >= e.bit then raise exception 'Protesto sona erdi.'; end if;
  if p.il_id is distinct from e.il_id then
    raise exception 'Protestoya yalnız % ilinde yaşayanlar katılabilir; başka ilden izleyebilirsin.', (select ad from oyun.iller where id = e.il_id);
  end if;
  insert into oyun.dernek_protesto_katilim(eylem_id, user_id, zaman) values (e.id, p.id, t) on conflict do nothing;
  select count(*) into n from oyun.dernek_protesto_katilim where eylem_id = e.id;
  return jsonb_build_object('katilim', n);
end $$;

-- Moderatör: uygunsuz eylemi kaldırır (şikâyet yetkisi)
create or replace function public.dernek_eylem_sil(p_eylem bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform oyun.yetki_zorunlu('sikayet');
  update oyun.dernek_eylem set silindi = true where id = p_eylem;
  if not found then raise exception 'Eylem bulunamadı.'; end if;
  return jsonb_build_object('tamam', true);
end $$;

-- ---------------------------------------------------------------------
-- Okuma
-- ---------------------------------------------------------------------
create or replace function oyun.dernek_eylem_json(e oyun.dernek_eylem, u uuid, t timestamptz) returns jsonb language sql stable set search_path = '' as $$
  select jsonb_build_object('id', e.id, 'dernek', oyun.dernek_json(e.dernek_id), 'tur', e.tur, 'baslik', e.baslik, 'metin', e.metin,
    'hedef_tur', e.hedef_tur, 'hedef_id', e.hedef_id, 'hedef_ad', e.hedef_ad, 'il', (select ad from oyun.iller where id = e.il_id), 'il_id', e.il_id,
    'bas', e.bas, 'bit', e.bit, 'zaman', e.zaman, 'yazan', oyun.kad(e.yazan),
    'canli', e.tur = 'protesto' and t >= e.bas and t < e.bit, 'bitti', e.tur = 'protesto' and t >= e.bit,
    'katilim', case when e.tur = 'protesto' then (select count(*) from oyun.dernek_protesto_katilim k where k.eylem_id = e.id) end,
    'katildim', e.tur = 'protesto' and exists (select 1 from oyun.dernek_protesto_katilim k where k.eylem_id = e.id and k.user_id = u),
    'benim_ilim', e.il_id is not null and e.il_id = (select il_id from oyun.profiller where id = u))
$$;

create or replace function public.dernekler() returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'ad', d.ad, 'alan', d.alan, 'alan_ad', oyun.dernek_alan_ad(d.alan),
      'merkez', (select ad from oyun.iller where id = d.merkez_il), 'baskan', oyun.kad(d.baskan),
      'uye', (select count(*) from oyun.dernek_uyeler u where u.dernek_id = d.id),
      'sube', (select count(*) from oyun.dernek_sube s where s.dernek_id = d.id),
      'uyesiyim', exists (select 1 from oyun.dernek_uyeler u where u.dernek_id = d.id and u.user_id = auth.uid()))
    order by (select count(*) from oyun.dernek_uyeler u where u.dernek_id = d.id) desc, d.id), '[]'::jsonb)
  from oyun.dernekler d where not d.kapali
$$;

create or replace function public.dernek_detay(p_dernek bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); t timestamptz := oyun.simdi(); d oyun.dernekler; rol text;
begin
  select * into d from oyun.dernekler where id = p_dernek;
  if d.id is null then raise exception 'Dernek bulunamadı.'; end if;
  select x.rol into rol from oyun.dernek_uyeler x where x.dernek_id = d.id and x.user_id = u;
  return jsonb_build_object('id', d.id, 'ad', d.ad, 'alan', d.alan, 'alan_ad', oyun.dernek_alan_ad(d.alan), 'amac', d.amac,
    'kapali', d.kapali, 'kurulus', d.kurulus, 'kurucu', oyun.kad(d.kurucu), 'baskan', oyun.kad(d.baskan),
    'merkez', (select ad from oyun.iller where id = d.merkez_il), 'merkez_il', d.merkez_il,
    'kasa', round(d.kasa), 'rolum', rol, 'yetkili', rol in ('baskan','yonetim'),
    'harc', oyun.dernek_harci(),
    'uyeler', coalesce((select jsonb_agg(jsonb_build_object('kad', pr.kad, 'il', i.ad, 'rol', x.rol) order by (x.rol = 'baskan') desc, (x.rol = 'yonetim') desc, x.katilim)
               from oyun.dernek_uyeler x join oyun.profiller pr on pr.id = x.user_id join oyun.iller i on i.id = pr.il_id where x.dernek_id = d.id), '[]'::jsonb),
    'subeler', coalesce((select jsonb_agg(jsonb_build_object('il_id', s.il_id, 'il', i.ad, 'merkez', s.il_id = d.merkez_il) order by s.il_id <> d.merkez_il, i.ad)
               from oyun.dernek_sube s join oyun.iller i on i.id = s.il_id where s.dernek_id = d.id), '[]'::jsonb),
    'sube_ucretleri', (select jsonb_build_object('1', round(1000 * e / 100) * 100, '2', round(2000 * e / 100) * 100, '3', round(3000 * e / 100) * 100)
                       from (select coalesce((select endeks from oyun.ulke where id = 1), 1) e) z),
    'hareketler', case when rol in ('baskan','yonetim') then coalesce((select jsonb_agg(jsonb_build_object('zaman', h.zaman, 'tutar', h.tutar, 'aciklama', h.aciklama) order by h.zaman desc)
               from (select * from oyun.dernek_hareket where dernek_id = d.id order by zaman desc limit 15) h), '[]'::jsonb) end,
    'eylemler', coalesce((select jsonb_agg(oyun.dernek_eylem_json(e, u, t) order by coalesce(e.bas, e.zaman) desc)
               from (select * from oyun.dernek_eylem where dernek_id = d.id and not silindi order by coalesce(bas, zaman) desc limit 30) e), '[]'::jsonb));
end $$;

-- Gündem için: son açıklamalar ve yaklaşan/canlı protestolar
create or replace function public.dernek_akis(p_limit int default 20) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'protestolar', coalesce((select jsonb_agg(oyun.dernek_eylem_json(e, auth.uid(), oyun.simdi()) order by e.bas)
       from oyun.dernek_eylem e where e.tur = 'protesto' and not e.silindi and e.bit > oyun.simdi() - interval '6 hours' and e.bas < oyun.simdi() + interval '3 days'), '[]'::jsonb),
    'aciklamalar', coalesce((select jsonb_agg(oyun.dernek_eylem_json(e, auth.uid(), oyun.simdi()) order by e.zaman desc)
       from (select * from oyun.dernek_eylem where tur <> 'protesto' and not silindi order by zaman desc limit least(greatest(coalesce(p_limit, 20), 1), 50)) e), '[]'::jsonb))
$$;

-- ---------------------------------------------------------------------
-- Dakikalık motor: protesto başlayınca ve bitince
-- ---------------------------------------------------------------------
create or replace function oyun.dernek_tick(t timestamptz) returns void language plpgsql set search_path = '' as $$
declare e record; n int;
begin
  for e in select x.*, d.ad dernek_ad, i.ad il_ad from oyun.dernek_eylem x join oyun.dernekler d on d.id = x.dernek_id join oyun.iller i on i.id = x.il_id
           where x.tur = 'protesto' and not x.silindi and not x.duyuruldu and x.bas <= t and x.bit > t loop
    update oyun.dernek_eylem set duyuruldu = true where id = e.id;
    insert into oyun.bildirimler(user_id, zaman, metin)
      select pr.id, t, format('%s şu an %s''de protesto düzenliyor: “%s”. Bir saat içinde Gündem''den katılabilirsin.', e.dernek_ad, e.il_ad, e.baslik)
      from oyun.profiller pr where pr.il_id = e.il_id and not pr.yasakli;
    insert into oyun.bildirimler(user_id, zaman, metin)
      select u.user_id, t, format('Derneğin %s %s''de protestoda: “%s”.', e.dernek_ad, e.il_ad, e.baslik)
      from oyun.dernek_uyeler u join oyun.profiller pr on pr.id = u.user_id where u.dernek_id = e.dernek_id and pr.il_id <> e.il_id;
    if oyun.push_acik() then
      perform oyun.push_konuya('s_il_' || e.il_id, null, format('%s sokakta!', e.dernek_ad),
        format('%s protestosu başladı: “%s”. Katılmak için dokun.', e.il_ad, e.baslik), jsonb_build_object('ekran', 'gundem'));
    end if;
  end loop;
  for e in select x.*, d.ad dernek_ad, i.ad il_ad from oyun.dernek_eylem x join oyun.dernekler d on d.id = x.dernek_id join oyun.iller i on i.id = x.il_id
           where x.tur = 'protesto' and not x.silindi and not x.sonuc_yazildi and x.bit <= t loop
    select count(*) into n from oyun.dernek_protesto_katilim where eylem_id = e.id;
    update oyun.dernek_eylem set sonuc_yazildi = true, duyuruldu = true where id = e.id;
    perform oyun.olay('dernek', format('%s''deki %s protestosu %s kişiyle tamamlandı: “%s”%s.', e.il_ad, e.dernek_ad, n, e.baslik,
      case when e.hedef_ad is not null then format(' · %s', e.hedef_ad) else '' end), e.il_id, case when e.hedef_tur = 'parti' then e.hedef_id::bigint end, t);
  end loop;
end $$;

-- 50'deki miting motoruna dernek motoru eklenir (miting davranışı aynı)
create or replace function oyun.miting_tick(t timestamptz) returns void language plpgsql set search_path = '' as $$
declare m record; n int; c int; enIyi text; konusma int;
begin
  perform oyun.dernek_tick(t);
  perform oyun.parti_miting_temizle(t);
  for m in select x.*, p.kad, i.ad il_ad, pa.kisa parti_kisa from oyun.mitingler x join oyun.profiller p on p.id = x.user_id join oyun.iller i on i.id = x.il_id
           left join oyun.partiler pa on pa.id = x.parti_id
           where not x.duyuruldu and x.bas <= t and x.bit > t loop
    update oyun.mitingler set duyuruldu = true where id = m.id;
    insert into oyun.bildirimler(user_id, zaman, metin)
      select pr.id, t, format('%s şu an %s meydanında: “%s”. Bir saat içinde Gündem''den mitinge katılıp konuşmaları dinleyebilir, tepki verebilirsin.', m.kad, m.il_ad, m.baslik)
      from oyun.profiller pr where pr.il_id = m.il_id and pr.id <> m.user_id and not pr.yasakli;
    if m.tur = 'parti' then
      insert into oyun.bildirimler(user_id, zaman, metin)
        select pr.id, t, format('%s mitingi başladı: %s, %s meydanında “%s”. Gündem''den canlı izleyebilirsin.', m.parti_kisa, m.kad, m.il_ad, m.baslik)
        from oyun.profiller pr where pr.parti_id = m.parti_id and pr.il_id <> m.il_id and pr.id <> m.user_id and not pr.yasakli;
    end if;
    perform oyun.bildir(m.user_id, format('%s mitingin başladı. Meydan seni bekliyor: Gündem''den mitingine girip kürsüden konuş.', m.il_ad), t);
    if oyun.push_acik() then
      perform oyun.push_konuya('s_il_' || m.il_id, null, format('%s meydanda!', m.kad),
        format('%s mitingi başladı: “%s”. Katılmak için dokun.', m.il_ad, m.baslik), jsonb_build_object('ekran', 'gundem'));
    end if;
  end loop;
  for m in select x.*, p.kad, i.ad il_ad from oyun.mitingler x join oyun.profiller p on p.id = x.user_id join oyun.iller i on i.id = x.il_id
           where not x.sonuc_yazildi and x.bit <= t loop
    select count(*) into n from oyun.miting_katilim where miting_id = m.id and user_id <> m.user_id;
    select count(*) into konusma from oyun.miting_konusma where miting_id = m.id and not silindi;
    c := oyun.miting_cosku(m.id);
    select left(k.metin, 120) into enIyi from oyun.miting_konusma k
      where k.miting_id = m.id and not k.silindi
        and exists (select 1 from oyun.miting_tepki r where r.konusma_id = k.id and oyun.miting_tepki_puan(r.tur) > 0)
      order by (select sum(oyun.miting_tepki_puan(r.tur)) from oyun.miting_tepki r where r.konusma_id = k.id) desc, k.id limit 1;
    update oyun.mitingler set sonuc_yazildi = true, duyuruldu = true, cosku = c where id = m.id;
    if konusma = 0 then
      perform oyun.olay('secim', format('%s, %s meydanında %s kişiyi topladı ama kürsüye hiç çıkmadı: “%s”.', m.kad, m.il_ad, n, m.baslik), m.il_id, m.parti_id, t);
    else
      perform oyun.olay('secim', format('%s %s mitingi: %s kişi, coşku %s/100 (%s).%s', m.kad, m.il_ad, n, c, lower(oyun.miting_cosku_ad(c)),
        case when enIyi is not null then format(' En çok alkışlanan söz: “%s”', enIyi) else '' end), m.il_id, m.parti_id, t);
    end if;
    perform oyun.bildir(m.user_id, format('%s mitingin sona erdi: %s kişi katıldı, %s kez kürsüye çıktın, meydanın coşkusu %s/100.', m.il_ad, n, konusma, c), t);
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- Yetkiler
-- ---------------------------------------------------------------------
do $$ declare f text; begin
  foreach f in array array['dernek_kur(text,text,text)','dernek_katil(bigint)','dernek_ayril(bigint)','dernek_yonetim_ata(bigint,text,boolean)',
    'dernek_baskan_devret(bigint,text)','dernek_bagis(bigint,numeric)','dernek_sube_ac(bigint,integer)',
    'dernek_eylem(bigint,text,text,text,text,text,integer,timestamptz)','dernek_protesto_katil(bigint)','dernek_eylem_sil(bigint)',
    'dernekler()','dernek_detay(bigint)','dernek_akis(integer)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
revoke all on function oyun.dernek_tick(timestamptz), oyun.miting_tick(timestamptz) from public, anon, authenticated;
-- Geçici MV test modu + gerçek %7 baraj altyapısı + herkese açık ittifak listesi.
-- Oyuncu, oy, makam, para veya mevcut ittifak verisi değiştirilmez.
begin;

create table if not exists oyun.mv_secim_modu(
  id int primary key check (id=1),
  her_aday_vekil boolean not null default true,
  aciklama text not null default 'Test: bütün kesinleşmiş adaylar seçilir; normalde tek parti/ittifak barajı %7.'
);
insert into oyun.mv_secim_modu(id,her_aday_vekil)
values (1,true) on conflict(id) do nothing;
alter table oyun.mv_secim_modu enable row level security;
revoke all on oyun.mv_secim_modu from public, anon, authenticated;
do $$ begin
  if to_regproc('oyun.bosaltma_korumasi') is not null then
    drop trigger if exists bosaltma_korumasi on oyun.mv_secim_modu;
    create trigger bosaltma_korumasi before truncate on oyun.mv_secim_modu
      for each statement execute function oyun.bosaltma_korumasi();
  end if;
end $$;

-- Düşük oyuncu sayılı testte bütün kesinleşmiş parti ve bağımsız MV adaylarını seç.
-- Testte il kontenjanı gerekirse aşılabilir; bu yalnız deneme moduna özgüdür.
create or replace function oyun._sonuc_mv_test(s oyun.secimler)
returns jsonb language plpgsql set search_path = '' as $$
declare 
  onsecim oyun.secimler;
  toplam bigint;
  sandalye_top int;
  dolu int;
  bos int;
  bag_oy bigint;
  bag_sandalye int;
  iller_j jsonb := '{}'::jsonb;
  ilj jsonb;
  il record;
  gercek_baraj numeric := (select baraj from oyun.ayarlar where id=1);
begin
  select * into onsecim from oyun.secimler where tur='mv_on' and donem=s.donem;
  if onsecim.id is null then
    raise exception 'Milletvekili önseçimi bulunamadı.';
  end if;
  select count(*) into toplam from oyun.oylar where secim_id=s.id;
  sandalye_top := coalesce((select sum(mv_secim) from oyun.iller),600);

  create temp table if not exists _test_mv_kaz(
    user_id uuid primary key, il_id smallint, parti_id bigint, aday_id bigint
  ) on commit drop;
  delete from _test_mv_kaz;

  -- Parti listesinde önseçim sonucuyla kesinleşmiş adayların tamamı.
  insert into _test_mv_kaz(user_id,il_id,parti_id,aday_id)
  select distinct on (a.user_id) a.user_id,a.il_id,a.parti_id,a.id
  from oyun.adaylar a
  where a.secim_id=onsecim.id and a.parti_id is not null and a.sira is not null
  order by a.user_id,a.sira,a.id;

  -- Doğrudan genel seçimde aday olan bağımsız adayların tamamı.
  insert into _test_mv_kaz(user_id,il_id,parti_id,aday_id)
  select distinct on (a.user_id) a.user_id,a.il_id,null::bigint,a.id
  from oyun.adaylar a
  where a.secim_id=s.id and a.parti_id is null
    and not exists (select 1 from _test_mv_kaz x where x.user_id=a.user_id)
  order by a.user_id,a.id
  on conflict(user_id) do nothing;

  for il in select * from oyun.iller order by id loop
    select jsonb_build_object(
      'gecerli',(select count(*) from oyun.oylar where secim_id=s.id and il_id=il.id),
      'partiler',coalesce((
        select jsonb_object_agg(v.parti_id::text,jsonb_build_object(
          'oy',v.oy,'sandalye',(select count(*) from _test_mv_kaz z where z.il_id=il.id and z.parti_id=v.parti_id)))
        from (
          select x.parti_id,(select count(*) from oyun.oylar o where o.secim_id=s.id and o.il_id=il.id and o.parti_id=x.parti_id) oy
          from (
            select parti_id from oyun.oylar where secim_id=s.id and il_id=il.id and parti_id is not null
            union
            select parti_id from _test_mv_kaz where il_id=il.id and parti_id is not null
          ) x
        ) v
      ),'{}'::jsonb),
      'bagimsizlar',coalesce((
        select jsonb_agg(jsonb_build_object(
          'aday_id',a.id,'kad',pr.kad,
          'oy',(select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id),
          'sandalye',case when exists(select 1 from _test_mv_kaz z where z.aday_id=a.id) then 1 else 0 end
        ) order by a.id)
        from oyun.adaylar a join oyun.profiller pr on pr.id=a.user_id
        where a.secim_id=s.id and a.parti_id is null and a.il_id=il.id
      ),'[]'::jsonb),
      'secilen',coalesce((
        select jsonb_agg(jsonb_build_object(
          'kad',pr.kad,'parti_id',z.parti_id,'bagimsiz',z.parti_id is null
        ) order by z.parti_id nulls last,pr.kad)
        from _test_mv_kaz z join oyun.profiller pr on pr.id=z.user_id where z.il_id=il.id
      ),'[]'::jsonb),
      'mv',coalesce(il.mv_secim,il.mv)
    ) into ilj;
    if (ilj->>'gecerli')::int>0 or jsonb_array_length(ilj->'secilen')>0 then
      iller_j := iller_j || jsonb_build_object(il.id::text,ilj);
    end if;
  end loop;

  insert into oyun.kazananlar(secim_id,user_id,il_id,parti_id)
    select s.id,user_id,il_id,parti_id from _test_mv_kaz
    on conflict do nothing;

  select count(*) into dolu from _test_mv_kaz;
  bos := greatest(0,sandalye_top-dolu);
  select count(*) into bag_oy from oyun.oylar where secim_id=s.id and parti_id is null and aday_id is not null;
  select count(*) into bag_sandalye from _test_mv_kaz where parti_id is null;

  perform oyun.olay('secim',
    format('Test genel seçimi sonuçlandı: %s oy, %s aday milletvekili seçildi. Geçici baraj kaldırıldı.',toplam,dolu),
    null,null,s.sonuc_at);

  return jsonb_build_object(
    'toplam',toplam,'baraj',0,'gercek_baraj',gercek_baraj,'test_modu',true,
    'sandalye_toplam',greatest(sandalye_top,dolu),'dolu',dolu,'bos',bos,
    'test_kontenjan_asimi',greatest(0,dolu-sandalye_top),
    'bagimsiz_oy',bag_oy,'bagimsiz_sandalye',bag_sandalye,
    'bagimsizlar',coalesce((
      select jsonb_agg(jsonb_build_object(
        'aday_id',a.id,'kad',pr.kad,'il_id',a.il_id,
        'oy',(select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id),
        'sandalye',case when exists (select 1 from _test_mv_kaz z where z.aday_id=a.id) then 1 else 0 end
      ) order by a.id)
      from oyun.adaylar a join oyun.profiller pr on pr.id=a.user_id
      where a.secim_id=s.id and a.parti_id is null
    ),'[]'::jsonb),
    'ulusal',coalesce((
      select jsonb_agg(jsonb_build_object(
        'parti_id',pa.id,'kisa',pa.kisa,'ad',pa.ad,'renk',pa.renk,
        'oy',coalesce(v.oy,0),
        'yuzde',case when toplam>0 then round(coalesce(v.oy,0)*100.0/toplam,2) else 0 end,
        'gecti',true,
        'sandalye',(select count(*) from _test_mv_kaz z where z.parti_id=pa.id)
      ) order by coalesce(v.oy,0) desc,pa.id)
      from oyun.partiler pa
      left join (select parti_id,count(*) as oy from oyun.oylar
                 where secim_id=s.id and parti_id is not null group by parti_id) v on v.parti_id=pa.id
      where v.parti_id is not null or exists(select 1 from _test_mv_kaz z where z.parti_id=pa.id)
    ),'[]'::jsonb),
    'iller',iller_j);
end $$;

create or replace function oyun._sonuc_mv(s oyun.secimler)
returns jsonb
language plpgsql set search_path='' as $$
declare
  baraj numeric:=(select baraj from oyun.ayarlar where id=1);
  onsecim oyun.secimler;
  toplam bigint;
  il record;
  l record;
  k int;
  ana bigint;
  iller_j jsonb:='{}'::jsonb;
  ilj jsonb;
  bos int:=0;
  dolu int:=0;
  sandalye_top int;
  bag_oy bigint;
  bag_sandalye int;
begin
  -- Geçici düşük oyuncu sayısı test modu: her kesinleşmiş aday seçilir.
  if exists (select 1 from oyun.mv_secim_modu where id = 1 and her_aday_vekil) then
    return oyun._sonuc_mv_test(s);
  end if;
  select * into onsecim from oyun.secimler where tur='mv_on' and donem=s.donem;
  select count(*) into toplam from oyun.oylar where secim_id=s.id;
  sandalye_top:=coalesce((select sum(mv_secim) from oyun.iller),600);

  create temp table if not exists _b23_ulusal(
    parti_id bigint primary key,
    oy bigint,
    yuzde numeric,
    gecti boolean,
    sandalye int default 0
  ) on commit drop;
  delete from _b23_ulusal;

  insert into _b23_ulusal(parti_id,oy)
  select parti_id,count(*)
  from oyun.oylar
  where secim_id=s.id and parti_id is not null
  group by parti_id;

  update _b23_ulusal
  set yuzde=case when toplam>0 then round(oy*100.0/toplam,2) else 0 end;

  update _b23_ulusal u
  set gecti=(coalesce(u.oy*100.0/nullif(toplam,0),0)>=baraj) or coalesce((
    select sum(u2.oy)*100.0/nullif(toplam,0)>=baraj
    from oyun.ittifak_uyeler iu
    join oyun.ittifak_uyeler iu2 on iu2.ittifak_id=iu.ittifak_id
    join _b23_ulusal u2 on u2.parti_id=iu2.parti_id
    where iu.parti_id=u.parti_id
  ),false);

  create temp table if not exists _b23_kaz(
    user_id uuid,
    il_id smallint,
    parti_id bigint,
    aday_id bigint
  ) on commit drop;
  delete from _b23_kaz;

  create temp table if not exists _b23_liste(
    anahtar bigint primary key,
    parti_id bigint,
    aday_id bigint,
    oy bigint,
    lim int,
    kaz int default 0
  ) on commit drop;

  for il in select * from oyun.iller order by id loop
    delete from _b23_liste;

    insert into _b23_liste(anahtar,parti_id,aday_id,oy,lim)
    select x.parti_id,x.parti_id,null,x.oy,x.lim
    from (
      select o.parti_id,
             count(*)::bigint oy,
             (select count(*)
              from oyun.adaylar a
              where a.secim_id=onsecim.id
                and a.il_id=il.id
                and a.parti_id=o.parti_id
                and a.sira is not null)::int lim
      from oyun.oylar o
      join _b23_ulusal u on u.parti_id=o.parti_id and u.gecti
      where o.secim_id=s.id and o.il_id=il.id and o.parti_id is not null
      group by o.parti_id
    ) x
    where x.lim>0 and x.oy>0;

    insert into _b23_liste(anahtar,parti_id,aday_id,oy,lim)
    select -a.id,null,a.id,count(o.*)::bigint,1
    from oyun.adaylar a
    join oyun.oylar o
      on o.secim_id=s.id and o.aday_id=a.id
    where a.secim_id=s.id
      and a.parti_id is null
      and a.il_id=il.id
    group by a.id
    having count(o.*)>0;

    for k in 1..coalesce(il.mv_secim,il.mv) loop
      ana:=null;
      select anahtar into ana
      from _b23_liste
      where kaz<lim and oy>0
      order by oy::numeric/(kaz+1) desc,oy desc,anahtar
      limit 1;
      exit when ana is null;
      update _b23_liste set kaz=kaz+1 where anahtar=ana;
    end loop;

    for l in select * from _b23_liste where parti_id is not null and kaz>0 loop
      insert into _b23_kaz(user_id,il_id,parti_id,aday_id)
      select a.user_id,il.id,l.parti_id,a.id
      from oyun.adaylar a
      where a.secim_id=onsecim.id
        and a.il_id=il.id
        and a.parti_id=l.parti_id
        and a.sira is not null
      order by a.sira
      limit l.kaz;

      update _b23_ulusal set sandalye=sandalye+l.kaz where parti_id=l.parti_id;
    end loop;

    insert into _b23_kaz(user_id,il_id,parti_id,aday_id)
    select a.user_id,il.id,null,a.id
    from _b23_liste l
    join oyun.adaylar a on a.id=l.aday_id
    where l.parti_id is null and l.kaz>0;

    select jsonb_build_object(
      'gecerli',(select count(*) from oyun.oylar where secim_id=s.id and il_id=il.id),
      'partiler',coalesce((
        select jsonb_object_agg(o.parti_id::text,jsonb_build_object(
          'oy',o.n,
          'sandalye',(select count(*) from _b23_kaz z where z.il_id=il.id and z.parti_id=o.parti_id)
        ))
        from (
          select parti_id,count(*) n
          from oyun.oylar
          where secim_id=s.id and il_id=il.id and parti_id is not null
          group by parti_id
        ) o
      ),'{}'::jsonb),
      'bagimsizlar',coalesce((
        select jsonb_agg(jsonb_build_object(
          'aday_id',a.id,
          'kad',pr.kad,
          'oy',(select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id),
          'sandalye',case when exists(select 1 from _b23_kaz z where z.aday_id=a.id) then 1 else 0 end
        ) order by (select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id) desc,a.id)
        from oyun.adaylar a
        join oyun.profiller pr on pr.id=a.user_id
        where a.secim_id=s.id and a.parti_id is null and a.il_id=il.id
      ),'[]'::jsonb),
      'secilen',coalesce((
        select jsonb_agg(jsonb_build_object(
          'kad',pr.kad,
          'parti_id',z.parti_id,
          'bagimsiz',z.parti_id is null
        ) order by z.parti_id nulls last,pr.kad)
        from _b23_kaz z
        join oyun.profiller pr on pr.id=z.user_id
        where z.il_id=il.id
      ),'[]'::jsonb),
      'mv',coalesce(il.mv_secim,il.mv)
    ) into ilj;

    if (ilj->>'gecerli')::int>0 or jsonb_array_length(ilj->'secilen')>0 then
      iller_j:=iller_j||jsonb_build_object(il.id::text,ilj);
    end if;
  end loop;

  insert into oyun.kazananlar(secim_id,user_id,il_id,parti_id)
  select s.id,user_id,il_id,parti_id from _b23_kaz
  on conflict do nothing;

  select count(*) into dolu from _b23_kaz;
  bos:=sandalye_top-dolu;
  select count(*) into bag_oy
  from oyun.oylar where secim_id=s.id and parti_id is null and aday_id is not null;
  select count(*) into bag_sandalye
  from _b23_kaz where parti_id is null;

  perform oyun.olay(
    'secim',
    format('Genel seçim sonuçlandı: %s oy kullanıldı, %s sandalye doldu, %s sandalye boş kaldı.',toplam,dolu,bos),
    null,null,s.sonuc_at
  );

  return jsonb_build_object(
    'toplam',toplam,
    'baraj',baraj,
    'sandalye_toplam',sandalye_top,
    'dolu',dolu,
    'bos',bos,
    'bagimsiz_oy',bag_oy,
    'bagimsiz_sandalye',bag_sandalye,
    'bagimsizlar',coalesce((
      select jsonb_agg(jsonb_build_object(
        'aday_id',a.id,
        'kad',pr.kad,
        'il_id',a.il_id,
        'oy',(select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id),
        'sandalye',case when exists(select 1 from _b23_kaz z where z.aday_id=a.id) then 1 else 0 end
      ) order by (select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id) desc,a.id)
      from oyun.adaylar a
      join oyun.profiller pr on pr.id=a.user_id
      where a.secim_id=s.id and a.parti_id is null
    ),'[]'::jsonb),
    'ulusal',coalesce((
      select jsonb_agg(jsonb_build_object(
        'parti_id',u.parti_id,
        'kisa',p.kisa,
        'ad',p.ad,
        'renk',p.renk,
        'oy',u.oy,
        'yuzde',u.yuzde,
        'gecti',u.gecti,
        'sandalye',u.sandalye
      ) order by u.oy desc)
      from _b23_ulusal u
      join oyun.partiler p on p.id=u.parti_id
    ),'[]'::jsonb),
    'iller',iller_j
  );
end $$;

-- Herkes Partiler ekranında ittifak adını ve tüm üye partileri görebilir.
create or replace function public.partiler() returns jsonb
language sql security definer set search_path = oyun, public, pg_temp as $$
  select coalesce(jsonb_agg(oyun.parti_json(pa.id) || jsonb_build_object(
    'uye',(select count(*) from oyun.profiller where parti_id=pa.id),
    'gb',oyun.kad(pa.gb),'sistem',pa.sistem,'kurulus_bit',pa.kurulus_bit,
    'vekil',(select count(*) from oyun.makamlar m where m.tur='mv' and m.bit is null and m.parti_id=pa.id),
    'belediye',(select count(*) from oyun.makamlar m where m.tur='bel' and m.bit is null and m.parti_id=pa.id),
    'test_baraj_kapali',coalesce((select her_aday_vekil from oyun.mv_secim_modu where id=1),false),
    'ittifak',(select jsonb_build_object('id',i.id,'ad',i.ad,
      'uyeler',coalesce((select jsonb_agg(jsonb_build_object(
        'id',p2.id,'ad',p2.ad,'kisa',p2.kisa,'renk',p2.renk) order by p2.kisa,p2.id)
        from oyun.ittifak_uyeler u2 join oyun.partiler p2 on p2.id=u2.parti_id
        where u2.ittifak_id=i.id and not p2.kapali),'[]'::jsonb))
      from oyun.ittifak_uyeler u join oyun.ittifaklar i on i.id=u.ittifak_id
      where u.parti_id=pa.id)
  ) order by (select count(*) from oyun.profiller where parti_id=pa.id) desc,pa.id),'[]'::jsonb)
  from oyun.partiler pa where not pa.kapali
$$;

commit;
-- 2026-10-10 Dernek üyelerine özel sohbet kanalları
-- Var olan mesajlar, okuma işaretleri ve oyuncu bilgileri korunur.
-- Dernek sohbetine yalnızca halen üye olan kullanıcı erişebilir.
create or replace function oyun.dernek_sohbet_adi(p_dernek bigint, p_uye uuid)
returns text language plpgsql stable set search_path = '' as $$
declare v_ad text;
begin
  if p_dernek is null or p_uye is null then
    raise exception 'Sohbet için dernek üyesi olmalısın.';
  end if;
  select d.ad into v_ad
    from oyun.dernekler d
    join oyun.dernek_uyeler u on u.dernek_id=d.id
    where d.id=p_dernek and not d.kapali and u.user_id=p_uye;
  if v_ad is null then
    raise exception 'Bu dernek sohbetine yalnızca derneğin aktif üyeleri katılabilir.';
  end if;
  return v_ad;
end $$;

create or replace function public.dernek_sohbetler()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi();
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', d.id, 'ad', d.ad, 'rol', u.rol,
      'uye', (select count(*) from oyun.dernek_uyeler du where du.dernek_id=d.id),
      'okunmamis', (
        select count(*) from (
          select 1 from oyun.mesajlar m
          where m.kanal='dernek:'||d.id::text
            and m.id > coalesce((select ko.son_id from oyun.kanal_okuma ko where ko.user_id=p.id and ko.kanal='dernek:'||d.id::text),0)
            and m.user_id<>p.id and not m.gizli and m.zaman<=t
            and m.zaman>t-interval '3 days'
            and not oyun.engelli(p.id,m.user_id)
          limit 100
        ) okunmamislar
      ),
      'son', (
        select jsonb_build_object('kad',coalesce(pr.kad,'(silinmiş)'),'metin',m.metin,'zaman',m.zaman)
        from oyun.mesajlar m left join oyun.profiller pr on pr.id=m.user_id
        where m.kanal='dernek:'||d.id::text and not m.gizli and m.zaman<=t
          and not oyun.engelli(p.id,m.user_id)
        order by m.id desc limit 1
      )
    ) order by d.ad,d.id)
    from oyun.dernek_uyeler u join oyun.dernekler d on d.id=u.dernek_id
    where u.user_id=p.id and not d.kapali
  ),'[]'::jsonb);
end $$;

create or replace function public.dernek_sohbet_oku(
  p_dernek bigint,
  p_once bigint default null,
  p_sonra bigint default null
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi();
  ad text; kanal text; liste jsonb; son bigint;
begin
  ad := oyun.dernek_sohbet_adi(p_dernek,p.id);
  kanal := 'dernek:'||p_dernek::text;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id',x.id,'kad',coalesce(pr.kad,'(silinmiş)'),'metin',x.metin,'zaman',x.zaman,
      'parti',oyun.parti_json(pr.parti_id),'unvan',oyun.unvan(x.user_id),
      'benim',x.user_id=p.id
  ) order by x.id),'[]'::jsonb) into liste
  from (
    select * from oyun.mesajlar m
    where m.kanal=kanal and not m.gizli and m.zaman<=t
      and not oyun.engelli(p.id,m.user_id)
      and (p_sonra is null or m.id>p_sonra)
      and (p_once is null or m.id<p_once)
    order by case when p_sonra is null then -m.id else m.id end
    limit case when p_sonra is null then 40 else 100 end
  ) x left join oyun.profiller pr on pr.id=x.user_id;
  if p_once is null then
    select max(id) into son from oyun.mesajlar m
      where m.kanal=kanal and not m.gizli and m.zaman<=t;
    if son is not null then
      insert into oyun.kanal_okuma(user_id,kanal,son_id) values(p.id,kanal,son)
      on conflict(user_id,kanal)
      do update set son_id=greatest(oyun.kanal_okuma.son_id,excluded.son_id);
    end if;
  end if;
  return jsonb_build_object('kanal',kanal,'baslik',ad||' · Dernek sohbeti',
                            'mesajlar',liste,'yazabilir',true);
end $$;

create or replace function public.dernek_sohbet_yaz(p_dernek bigint,p_metin text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi();
  ad text; metin text;
begin
  ad := oyun.dernek_sohbet_adi(p_dernek,p.id);
  perform oyun.yazabilir_mi(p,t);
  metin := oyun.metin_temizle(p_metin,500);
  insert into oyun.mesajlar(kanal,user_id,metin,zaman)
    values('dernek:'||p_dernek::text,p.id,metin,t);
  update oyun.profiller set son_mesaj=t where id=p.id;
  return jsonb_build_object('tamam',true);
end $$;

-- Mesajlara yalnızca üyelik kontrolü bulunan RPC'ler üzerinden erişilir.
revoke all on function oyun.dernek_sohbet_adi(bigint,uuid) from public, anon, authenticated;
revoke all on function public.dernek_sohbetler() from public, anon;
revoke all on function public.dernek_sohbet_oku(bigint,bigint,bigint) from public, anon;
revoke all on function public.dernek_sohbet_yaz(bigint,text) from public, anon;
grant execute on function public.dernek_sohbetler() to authenticated;
grant execute on function public.dernek_sohbet_oku(bigint,bigint,bigint) to authenticated;
grant execute on function public.dernek_sohbet_yaz(bigint,text) to authenticated;
-- Seçim Online / Dernek genel kurulları, üye imzaları ve parti kurultayı
-- Sadece ek tablo ve RPC: oyuncu/para/oy/geçmiş silinmez.
create table if not exists oyun.sos_dernek_secim (
 id bigint generated always as identity primary key,
 dernek_id bigint not null references oyun.dernekler(id) on delete cascade,
 bas timestamptz not null default now(),
 aday_bit timestamptz not null,
 oy_bit timestamptz not null,
 durum text not null default 'acik' check (durum in ('acik','bitti')),
 eski_baskan uuid references oyun.profiller(id),
 yeni_baskan uuid references oyun.profiller(id)
);
create unique index if not exists sos_dernek_tek_acik on oyun.sos_dernek_secim(dernek_id) where durum='acik';
create table if not exists oyun.sos_dernek_aday(
 secim_id bigint not null references oyun.sos_dernek_secim(id) on delete cascade,
 user_id uuid not null references oyun.profiller(id),
 gorev text not null check (gorev in ('baskan','yonetim')),
 primary key(secim_id,user_id)
);
create table if not exists oyun.sos_dernek_oy(
 secim_id bigint not null references oyun.sos_dernek_secim(id) on delete cascade,
 user_id uuid not null references oyun.profiller(id),
 gorev text not null check(gorev in ('baskan','yonetim')),
 aday_id uuid not null references oyun.profiller(id),
 primary key(secim_id,user_id,gorev),
 foreign key(secim_id,aday_id) references oyun.sos_dernek_aday(secim_id,user_id)
);
create table if not exists oyun.sos_dernek_talep(
 id bigint generated always as identity primary key,
 dernek_id bigint not null references oyun.dernekler(id) on delete cascade,
 bas timestamptz not null default now(),
 bit timestamptz not null default (now()+interval '7 days'),
 durum text not null default 'acik' check(durum in ('acik','kabul','sure_doldu'))
);
create unique index if not exists sos_dernek_talep_acik on oyun.sos_dernek_talep(dernek_id) where durum='acik';
create table if not exists oyun.sos_dernek_talep_imza(
 talep_id bigint not null references oyun.sos_dernek_talep(id) on delete cascade,
 user_id uuid not null references oyun.profiller(id),
 primary key(talep_id,user_id)
);
do $$ declare n text; begin
 foreach n in array array['sos_dernek_secim','sos_dernek_aday','sos_dernek_oy','sos_dernek_talep','sos_dernek_talep_imza'] loop
  execute format('alter table oyun.%I enable row level security',n);
  execute format('revoke all on oyun.%I from public,anon,authenticated',n);
 end loop;
end $$;

create or replace function oyun.sos_dernek_baslat(p_dernek bigint,t timestamptz)
returns bigint language plpgsql set search_path='' as $$
declare d oyun.dernekler; sid bigint; son timestamptz;
begin
 select * into d from oyun.dernekler where id=p_dernek and not kapali for update;
 if d.id is null then raise exception 'Dernek bulunamadı.'; end if;
 select id into sid from oyun.sos_dernek_secim where dernek_id=d.id and durum='acik';
 if sid is not null then return sid; end if;
 select max(oy_bit) into son from oyun.sos_dernek_secim where dernek_id=d.id;
 if son>t-interval '7 days' then raise exception 'Son genel kurulun üzerinden en az 7 gün geçmeli.'; end if;
 if (select count(*) from oyun.dernek_uyeler where dernek_id=d.id)<2 then raise exception 'Genel kurul için en az iki üye gerekli.'; end if;
 insert into oyun.sos_dernek_secim(dernek_id,bas,aday_bit,oy_bit,eski_baskan)
 values(d.id,t,t+interval '12 hours',t+interval '36 hours',d.baskan) returning id into sid;
 if d.baskan is not null and exists(select 1 from oyun.dernek_uyeler where dernek_id=d.id and user_id=d.baskan) then
  insert into oyun.sos_dernek_aday(secim_id,user_id,gorev) values(sid,d.baskan,'baskan');
 end if;
 perform oyun.olay('dernek',format('%s genel kurulu açıldı. Üyeler başkan ve yönetim kurulu için aday olabilir.',d.ad),d.merkez_il,null,t);
 return sid;
end $$;
revoke all on function oyun.sos_dernek_baslat(bigint,timestamptz) from public,anon,authenticated;

create or replace function oyun.sos_dernek_bitir(p_id bigint,t timestamptz)
returns void language plpgsql set search_path='' as $$
declare s oyun.sos_dernek_secim; d oyun.dernekler; h uuid; y record;
begin
 select * into s from oyun.sos_dernek_secim where id=p_id for update;
 if s.id is null or s.durum<>'acik' or s.oy_bit>t then return; end if;
 select * into d from oyun.dernekler where id=s.dernek_id for update;
 if d.id is null or d.kapali then update oyun.sos_dernek_secim set durum='bitti' where id=s.id; return; end if;
 select a.user_id into h
 from oyun.sos_dernek_aday a
 join oyun.dernek_uyeler u on u.dernek_id=d.id and u.user_id=a.user_id
 left join oyun.sos_dernek_oy v on v.secim_id=a.secim_id and v.gorev='baskan' and v.aday_id=a.user_id
 where a.secim_id=s.id and a.gorev='baskan'
   and not exists(select 1 from oyun.dernekler x where x.baskan=a.user_id and x.id<>d.id and not x.kapali)
 group by a.user_id order by count(v.user_id) desc,(a.user_id=d.baskan) desc,a.user_id limit 1;
 h:=coalesce(h,d.baskan);
 update oyun.dernek_uyeler set rol='uye' where dernek_id=d.id and rol in ('baskan','yonetim');
 if h is not null and exists(select 1 from oyun.dernek_uyeler where dernek_id=d.id and user_id=h) then
  update oyun.dernek_uyeler set rol='baskan' where dernek_id=d.id and user_id=h;
  update oyun.dernekler set baskan=h where id=d.id;
 end if;
 for y in
  select a.user_id from oyun.sos_dernek_aday a
  join oyun.dernek_uyeler u on u.dernek_id=d.id and u.user_id=a.user_id
  left join oyun.sos_dernek_oy v on v.secim_id=a.secim_id and v.gorev='yonetim' and v.aday_id=a.user_id
  where a.secim_id=s.id and a.gorev='yonetim' and a.user_id<>h
  group by a.user_id order by count(v.user_id) desc,a.user_id limit 4
 loop update oyun.dernek_uyeler set rol='yonetim' where dernek_id=d.id and user_id=y.user_id; end loop;
 update oyun.sos_dernek_secim set durum='bitti',yeni_baskan=h where id=s.id;
 perform oyun.olay('dernek',format('%s genel kurulunda yeni başkan %s oldu.',d.ad,oyun.kad(h)),d.merkez_il,null,t);
 if h is distinct from s.eski_baskan and h is not null then perform oyun.bildir(h,format('%s genel kurulunda başkan seçildin.',d.ad),t); end if;
end $$;
revoke all on function oyun.sos_dernek_bitir(bigint,timestamptz) from public,anon,authenticated;

create or replace function public.sos_dernek_durum(p_dernek bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); d oyun.dernekler; s oyun.sos_dernek_secim; tal oyun.sos_dernek_talep; n int; son timestamptz;
begin
 if u is null then raise exception 'Oturum açmalısın.'; end if;
 select * into d from oyun.dernekler where id=p_dernek and not kapali;
 if d.id is null then raise exception 'Dernek bulunamadı.'; end if;
 select * into s from oyun.sos_dernek_secim where dernek_id=d.id order by id desc limit 1;
 if s.durum='acik' and s.oy_bit<=t then perform oyun.sos_dernek_bitir(s.id,t); select * into s from oyun.sos_dernek_secim where id=s.id; end if;
 if (s.id is null or s.durum='bitti') and (coalesce(s.oy_bit,d.kurulus)<=t-interval '30 days') and
   (select count(*) from oyun.dernek_uyeler where dernek_id=d.id)>=2 then
   perform oyun.sos_dernek_baslat(d.id,t);
   select * into s from oyun.sos_dernek_secim where dernek_id=d.id order by id desc limit 1;
 end if;
 update oyun.sos_dernek_talep set durum='sure_doldu' where dernek_id=d.id and durum='acik' and bit<=t;
 select * into tal from oyun.sos_dernek_talep where dernek_id=d.id and durum='acik' limit 1;
 select count(*) into n from oyun.dernek_uyeler where dernek_id=d.id;
 return jsonb_build_object(
 'dernek_id',d.id,'rolum',(select rol from oyun.dernek_uyeler where dernek_id=d.id and user_id=u),
 'uye_sayisi',n,'esik',greatest(2,ceil(n::numeric/3)::int),
 'talep',case when tal.id is null then null else jsonb_build_object('id',tal.id,'bit',tal.bit,'imza',(select count(*) from oyun.sos_dernek_talep_imza where talep_id=tal.id),'imzaladim',exists(select 1 from oyun.sos_dernek_talep_imza where talep_id=tal.id and user_id=u)) end,
 'secim',case when s.id is null then null else jsonb_build_object(
  'id',s.id,'bas',s.bas,'aday_bit',s.aday_bit,'oy_bit',s.oy_bit,'durum',s.durum,
  'baskan',oyun.kad(coalesce(s.yeni_baskan,d.baskan)),
  'adaylar',coalesce((select jsonb_agg(jsonb_build_object('kad',oyun.kad(a.user_id),'user_id',a.user_id,'gorev',a.gorev,'oy',case when s.durum='bitti' then (select count(*) from oyun.sos_dernek_oy v where v.secim_id=s.id and v.gorev=a.gorev and v.aday_id=a.user_id) end,'benim',a.user_id=u) order by a.gorev,a.user_id)
    from oyun.sos_dernek_aday a where a.secim_id=s.id),'[]'::jsonb),
  'oylarim',coalesce((select jsonb_object_agg(v.gorev,v.aday_id) from oyun.sos_dernek_oy v where v.secim_id=s.id and v.user_id=u),'{}'::jsonb),
  'oy_hakkim',exists(select 1 from oyun.dernek_uyeler m where m.dernek_id=d.id and m.user_id=u and m.katilim<=s.bas)
 ) end);
end $$;

create or replace function public.sos_dernek_secim_ac(p_dernek bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); d oyun.dernekler;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into d from oyun.dernekler where id=p_dernek and not kapali;
 if d.id is null or d.baskan is distinct from u then raise exception 'Genel kurulu yalnızca başkan açabilir.'; end if;
 perform oyun.sos_dernek_baslat(p_dernek,oyun.simdi());
 return public.sos_dernek_durum(p_dernek);
end $$;

create or replace function public.sos_dernek_imza(p_dernek bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); d oyun.dernekler; tal oyun.sos_dernek_talep; n int; toplam int;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into d from oyun.dernekler where id=p_dernek and not kapali for update;
 if d.id is null or not exists(select 1 from oyun.dernek_uyeler where dernek_id=d.id and user_id=u) then raise exception 'Yalnızca dernek üyeleri imzalayabilir.'; end if;
 if exists(select 1 from oyun.sos_dernek_secim where dernek_id=d.id and durum='acik') then raise exception 'Zaten genel kurul yapılıyor.'; end if;
 update oyun.sos_dernek_talep set durum='sure_doldu' where dernek_id=d.id and durum='acik' and bit<=t;
 select * into tal from oyun.sos_dernek_talep where dernek_id=d.id and durum='acik' for update;
 if tal.id is null then insert into oyun.sos_dernek_talep(dernek_id,bas,bit) values(d.id,t,t+interval '7 days') returning * into tal; end if;
 insert into oyun.sos_dernek_talep_imza(talep_id,user_id) values(tal.id,u) on conflict do nothing;
 if not found then raise exception 'Bu talebi zaten imzaladın.'; end if;
 select count(*) into n from oyun.sos_dernek_talep_imza where talep_id=tal.id;
 select count(*) into toplam from oyun.dernek_uyeler where dernek_id=d.id;
 if n>=greatest(2,ceil(toplam::numeric/3)::int) then
  perform oyun.sos_dernek_baslat(d.id,t);
  update oyun.sos_dernek_talep set durum='kabul' where id=tal.id;
  perform oyun.bildir(d.baskan,format('%s üyelerinin imzalarıyla olağanüstü genel kurul açıldı.',d.ad),t);
 end if;
 return public.sos_dernek_durum(d.id);
end $$;

create or replace function public.sos_dernek_aday(p_secim bigint,p_gorev text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); s oyun.sos_dernek_secim; t timestamptz:=oyun.simdi();
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into s from oyun.sos_dernek_secim where id=p_secim for update;
 if s.id is null or s.durum<>'acik' or t>=s.aday_bit then raise exception 'Adaylık süresi kapalı.'; end if;
 if p_gorev not in ('baskan','yonetim') then raise exception 'Geçersiz görev.'; end if;
 if not exists(select 1 from oyun.dernek_uyeler where dernek_id=s.dernek_id and user_id=u and katilim<=s.bas) then raise exception 'Genel kurul başlamadan önce üye olmalısın.'; end if;
 if p_gorev='baskan' and exists(select 1 from oyun.dernekler where baskan=u and id<>s.dernek_id and not kapali) then raise exception 'Başka derneğin başkanısın.'; end if;
 insert into oyun.sos_dernek_aday(secim_id,user_id,gorev) values(s.id,u,p_gorev) on conflict (secim_id,user_id) do update set gorev=excluded.gorev;
 return public.sos_dernek_durum(s.dernek_id);
end $$;

create or replace function public.sos_dernek_oyla(p_secim bigint,p_gorev text,p_aday uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); s oyun.sos_dernek_secim; t timestamptz:=oyun.simdi();
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into s from oyun.sos_dernek_secim where id=p_secim for update;
 if s.id is null or s.durum<>'acik' or t<s.aday_bit or t>=s.oy_bit then raise exception 'Oy verme süresi kapalı.'; end if;
 if p_gorev not in ('baskan','yonetim') or not exists(select 1 from oyun.sos_dernek_aday where secim_id=s.id and user_id=p_aday and gorev=p_gorev) then raise exception 'Geçersiz aday.'; end if;
 if not exists(select 1 from oyun.dernek_uyeler where dernek_id=s.dernek_id and user_id=u and katilim<=s.bas) then raise exception 'Oy kullanma hakkın yok.'; end if;
 insert into oyun.sos_dernek_oy(secim_id,user_id,gorev,aday_id) values(s.id,u,p_gorev,p_aday)
 on conflict (secim_id,user_id,gorev) do update set aday_id=excluded.aday_id;
 return public.sos_dernek_durum(s.dernek_id);
end $$;

-- Parti üyelerinin imzasıyla olağanüstü kurultay: mevcut kurultay seçim motorunu kullanır.
create table if not exists oyun.sos_parti_imza(
 id bigint generated always as identity primary key,
 parti_id bigint not null references oyun.partiler(id),
 acan uuid not null references oyun.profiller(id),
 bas timestamptz not null default now(),
 bit timestamptz not null default (now()+interval '7 days'),
 durum text not null default 'acik' check(durum in ('acik','basarili','sure_doldu')),
 secim_id bigint references oyun.secimler(id)
);
create unique index if not exists sos_parti_imza_acik on oyun.sos_parti_imza(parti_id) where durum='acik';
create table if not exists oyun.sos_parti_imzaci(
 kampanya_id bigint not null references oyun.sos_parti_imza(id) on delete cascade,
 user_id uuid not null references oyun.profiller(id),
 primary key(kampanya_id,user_id)
);
alter table oyun.sos_parti_imza enable row level security;
alter table oyun.sos_parti_imzaci enable row level security;
revoke all on oyun.sos_parti_imza,oyun.sos_parti_imzaci from public,anon,authenticated;

create or replace function public.sos_parti_imza_durum(p_parti bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); c oyun.sos_parti_imza; n int;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 update oyun.sos_parti_imza set durum='sure_doldu' where parti_id=p_parti and durum='acik' and bit<=t;
 select * into c from oyun.sos_parti_imza where parti_id=p_parti order by id desc limit 1;
 select count(*) into n from oyun.profiller where parti_id=p_parti;
 return jsonb_build_object('parti_id',p_parti,'uye_sayisi',n,'esik',greatest(2,ceil(n::numeric/3)::int),
 'uyeyim',exists(select 1 from oyun.profiller where id=u and parti_id=p_parti),
 'kampanya',case when c.id is null then null else jsonb_build_object('id',c.id,'bas',c.bas,'bit',c.bit,'durum',c.durum,'secim_id',c.secim_id,
 'imza',(select count(*) from oyun.sos_parti_imzaci where kampanya_id=c.id),
 'imzaladim',exists(select 1 from oyun.sos_parti_imzaci where kampanya_id=c.id and user_id=u)) end);
end $$;
create or replace function public.sos_parti_imzala(p_parti bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); p oyun.partiler; c oyun.sos_parti_imza; n int; toplam int; o jsonb;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into p from oyun.partiler where id=p_parti and not kapali for update;
 if p.id is null or not exists(select 1 from oyun.profiller where id=u and parti_id=p.id) then raise exception 'Yalnızca bu partinin üyeleri imzalayabilir.'; end if;
 if exists(select 1 from oyun.secimler where tur='kurultay' and ara and hedef_parti_id=p.id and durum<>'tamam' and goreve_bas>t) then raise exception 'Parti için zaten olağanüstü kurultay var.'; end if;
 update oyun.sos_parti_imza set durum='sure_doldu' where parti_id=p.id and durum='acik' and bit<=t;
 select * into c from oyun.sos_parti_imza where parti_id=p.id and durum='acik' for update;
 if c.id is null then insert into oyun.sos_parti_imza(parti_id,acan,bas,bit) values(p.id,u,t,t+interval '7 days') returning * into c; end if;
 if not exists(select 1 from oyun.profiller where id=u and parti_id=p.id and parti_at<=c.bas) and c.acan<>u then raise exception 'İmza kampanyası açıldıktan sonra katılan üyeler bu kampanyada imza atamaz.'; end if;
 insert into oyun.sos_parti_imzaci(kampanya_id,user_id) values(c.id,u) on conflict do nothing;
 if not found then raise exception 'Bu kampanyayı zaten imzaladın.'; end if;
 select count(*) into n from oyun.sos_parti_imzaci where kampanya_id=c.id;
 select count(*) into toplam from oyun.profiller where parti_id=p.id;
 if n>=greatest(2,ceil(toplam::numeric/3)::int) then
   o:=oyun.ara_secim_olustur('gb',p.id,null::smallint,t);
   update oyun.secimler set ara_neden='uye_imza_kampanyasi' where id=(o->>'secim_id')::bigint and ara and ara_neden='genel_baskan_istifa';
   update oyun.sos_parti_imza set durum='basarili',secim_id=(o->>'secim_id')::bigint where id=c.id;
   perform oyun.olay('parti',format('%s üyelerinin imzasıyla olağanüstü kurultay kararı alındı.',p.ad),null,p.id,t);
   if p.gb is not null then perform oyun.bildir(p.gb,format('%s üyeleri olağanüstü kurultay topladı.',p.ad),t); end if;
 end if;
 return public.sos_parti_imza_durum(p.id);
end $$;

do $$ declare f text; begin
 foreach f in array array[
 'sos_dernek_durum(bigint)','sos_dernek_secim_ac(bigint)','sos_dernek_imza(bigint)','sos_dernek_aday(bigint,text)','sos_dernek_oyla(bigint,text,uuid)',
 'sos_parti_imza_durum(bigint)','sos_parti_imzala(bigint)'
 ] loop
 execute 'revoke all on function public.'||f||' from public,anon';
 execute 'grant execute on function public.'||f||' to authenticated';
 end loop;
end $$;
-- Seçim Online: gazeteci röportajları, haberlerde cevap hakkı, canlı siyasi düellolar
create table if not exists oyun.sos_roportaj (
 id bigint generated always as identity primary key,
 gazete_id bigint not null references oyun.oyuncu_gazeteleri(id),
 gazeteci uuid not null references oyun.profiller(id),
 konuk uuid not null references oyun.profiller(id),
 baslik text not null check(char_length(baslik) between 5 and 120),
 soru text not null check(char_length(soru) between 10 and 3000),
 yanit text,
 durum text not null default 'bekliyor' check(durum in ('bekliyor','yanitlandi','reddedildi','yayinlandi')),
 acilis timestamptz not null default now(),
 yanit_at timestamptz,
 yayin_id bigint unique references oyun.gazete_yayinlari(id)
);
create index if not exists sos_roportaj_z on oyun.sos_roportaj(acilis desc);
create table if not exists oyun.sos_haber_cevap (
 yayin_id bigint not null references oyun.gazete_yayinlari(id) on delete cascade,
 oyuncu_id uuid not null references oyun.profiller(id),
 metin text check(char_length(metin) between 10 and 3000),
 zaman timestamptz,
 ekleyen uuid references oyun.profiller(id),
 primary key(yayin_id,oyuncu_id)
);
create table if not exists oyun.sos_duello (
 id bigint generated always as identity primary key,
 davet_eden uuid not null references oyun.profiller(id),
 davet_edilen uuid not null references oyun.profiller(id),
 baslik text not null check(char_length(baslik) between 5 and 120),
 durum text not null default 'davet' check(durum in ('davet','reddedildi','canli','oylama','bitti')),
 olusturma timestamptz not null default now(),
 kabul_at timestamptz,
 oylama_bas timestamptz,
 bitti_at timestamptz,
 siradaki uuid references oyun.profiller(id),
 tur_sayisi int not null default 0,
 check(davet_eden<>davet_edilen)
);
create index if not exists sos_duello_durum on oyun.sos_duello(durum,olusturma desc);
create table if not exists oyun.sos_duello_soz(
 id bigint generated always as identity primary key,
 duello_id bigint not null references oyun.sos_duello(id) on delete cascade,
 konusan uuid not null references oyun.profiller(id),
 metin text not null check(char_length(metin) between 10 and 2000),
 zaman timestamptz not null default now(),
 tur int not null,
 unique(duello_id,tur)
);
create table if not exists oyun.sos_duello_oy(
 duello_id bigint not null references oyun.sos_duello(id) on delete cascade,
 user_id uuid not null references oyun.profiller(id),
 tercih uuid not null references oyun.profiller(id),
 zaman timestamptz not null default now(),
 primary key(duello_id,user_id)
);
do $$ declare n text; begin
 foreach n in array array['sos_roportaj','sos_haber_cevap','sos_duello','sos_duello_soz','sos_duello_oy'] loop
 execute format('alter table oyun.%I enable row level security',n);
 execute format('revoke all on oyun.%I from public,anon,authenticated',n);
 end loop;
end $$;

create or replace function public.sos_roportajlar() returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'gazete',g.ad,'gazete_id',g.id,'gazeteci',oyun.kad(r.gazeteci),'konuk',oyun.kad(r.konuk),
 'baslik',r.baslik,'soru',r.soru,'yanit',r.yanit,'durum',r.durum,'acilis',r.acilis,'yayin_id',r.yayin_id,
 'benim_gorusmem',r.gazeteci=u,'cevaplayabilirim',r.konuk=u and r.durum='bekliyor','yayinlayabilirim',r.gazeteci=u and r.durum in ('yanitlandi','reddedildi'),
 'ilgiliyim',r.gazeteci=u or r.konuk=u) order by r.id desc)
 from (select * from oyun.sos_roportaj where durum='yayinlandi' or gazeteci=u or konuk=u order by id desc limit 80) r
 join oyun.oyuncu_gazeteleri g on g.id=r.gazete_id),'[]'::jsonb);
end $$;
create or replace function public.sos_roportaj_davet(p_gazete bigint,p_kad text,p_baslik text,p_soru text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); h oyun.profiller; b text:=btrim(coalesce(p_baslik,'')); s text:=btrim(coalesce(p_soru,'')); v_gazete oyun.oyuncu_gazeteleri; rid bigint;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into v_gazete from oyun.oyuncu_gazeteleri where id=p_gazete and aktif;
 if v_gazete.id is null or not(v_gazete.sahip=u or exists(select 1 from oyun.gazete_yazarlar where gazete_id=p_gazete and user_id=u and aktif)) then
 raise exception 'Bu gazetede yazı yayımlama yetkin yok.'; end if;
 h:=oyun.profil_bul(p_kad);
 if h.id=u then raise exception 'Kendine röportaj daveti gönderemezsin.'; end if;
 if char_length(b) not between 5 and 120 or char_length(s) not between 10 and 3000 then raise exception 'Başlık 5–120, soru 10–3000 karakter olmalı.'; end if;
 if (select count(*) from oyun.sos_roportaj where gazeteci=u and acilis>t-interval '24 hours')>=5 then raise exception '24 saatte en fazla 5 röportaj daveti gönderebilirsin.'; end if;
 insert into oyun.sos_roportaj(gazete_id,gazeteci,konuk,baslik,soru,acilis) values(p_gazete,u,h.id,b,s,t) returning id into rid;
 perform oyun.bildir(h.id,format('%s, %s gazetesi adına röportaj daveti gönderdi: %s',oyun.kad(u),v_gazete.ad,b),t);
 return public.sos_roportajlar();
end $$;
create or replace function public.sos_roportaj_yanit(p_id bigint,p_kabul boolean,p_yanit text default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); r oyun.sos_roportaj; t timestamptz:=oyun.simdi(); yan text:=btrim(coalesce(p_yanit,''));
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into r from oyun.sos_roportaj where id=p_id for update;
 if r.id is null or r.konuk<>u or r.durum<>'bekliyor' then raise exception 'Yanıt bekleyen bir röportaj davetin yok.'; end if;
 if p_kabul and char_length(yan) not between 10 and 3000 then raise exception 'Yanıt 10–3000 karakter olmalı.'; end if;
 update oyun.sos_roportaj set durum=case when p_kabul then 'yanitlandi' else 'reddedildi' end,yanit=case when p_kabul then yan else null end,yanit_at=t where id=p_id;
 perform oyun.bildir(r.gazeteci,format('%s röportaj davetini %s.',oyun.kad(u),case when p_kabul then 'yanıtladı' else 'reddetti' end),t);
 return public.sos_roportajlar();
end $$;
create or replace function public.sos_roportaj_yayinla(p_id bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); r oyun.sos_roportaj; g oyun.oyuncu_gazeteleri; t timestamptz:=oyun.simdi(); vid bigint;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into r from oyun.sos_roportaj where id=p_id for update;
 if r.id is null or r.gazeteci<>u or r.durum not in ('yanitlandi','reddedildi') then raise exception 'Röportaj henüz yayına uygun değil.'; end if;
 select * into g from oyun.oyuncu_gazeteleri where id=r.gazete_id;
 if g.id is null or not g.aktif or not(g.sahip=u or exists(select 1 from oyun.gazete_yazarlar where gazete_id=g.id and user_id=u and aktif)) then raise exception 'Gazetecilik yetkin sona ermiş.'; end if;
 insert into oyun.gazete_yayinlari(gazete_id,yazar,tur,baslik,metin,zaman)
 values(r.gazete_id,u,'haber',r.baslik,
 'Gazeteci: '||oyun.kad(u)||E'\nKonuk: '||oyun.kad(r.konuk)||E'\n\nSoru: '||r.soru||E'\n\n'||case when r.durum='reddedildi' then 'Konuk röportajı yanıtlamayı reddetti.' else 'Yanıt: '||r.yanit end,t)
 returning id into vid;
 update oyun.sos_roportaj set durum='yayinlandi',yayin_id=vid where id=p_id;
 insert into oyun.sos_haber_cevap(yayin_id,oyuncu_id,ekleyen) values(vid,r.konuk,u) on conflict do nothing;
 perform oyun.bildir(r.konuk,format('%s gazetesinde röportajın yayımlandı. Bir kez cevap hakkını kullanabilirsin.',g.ad),t);
 perform oyun.olay('basin',format('%s gazetesinde %s ile röportaj yayımlandı: %s',g.ad,oyun.kad(r.konuk),r.baslik),null,null,t);
 return public.sos_roportajlar();
end $$;
create or replace function public.sos_haberler() returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',y.id,'gazete',g.ad,'gazete_id',g.id,'yazar',oyun.kad(y.yazar),'baslik',y.baslik,
 'metin',y.metin,'zaman',y.zaman,'hedef',oyun.kad(h.oyuncu_id),'cevap',h.metin,'cevap_at',h.zaman,
 'cevaplayabilirim',h.oyuncu_id=u and h.metin is null,'etiketleyebilirim',h.oyuncu_id is null and (g.sahip=u or y.yazar=u))
 order by y.id desc)
 from (select * from oyun.gazete_yayinlari where tur='haber' order by id desc limit 70) y
 join oyun.oyuncu_gazeteleri g on g.id=y.gazete_id
 left join lateral (select * from oyun.sos_haber_cevap where yayin_id=y.id order by oyuncu_id limit 1) h on true),'[]'::jsonb);
end $$;
create or replace function public.sos_haber_hedefle(p_yayin bigint,p_kad text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); y oyun.gazete_yayinlari; h oyun.profiller;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into y from oyun.gazete_yayinlari where id=p_yayin and tur='haber' for update;
 if y.id is null or not exists(select 1 from oyun.oyuncu_gazeteleri g where g.id=y.gazete_id and (g.sahip=u or y.yazar=u)) then raise exception 'Bu haberin sahibi veya yazarı değilsin.'; end if;
 h:=oyun.profil_bul(p_kad);
 if exists(select 1 from oyun.sos_haber_cevap where yayin_id=p_yayin) then raise exception 'Bu haberin muhatabı zaten belirlendi.'; end if;
 insert into oyun.sos_haber_cevap(yayin_id,oyuncu_id,ekleyen) values(p_yayin,h.id,u);
 perform oyun.bildir(h.id,format('“%s” haberinde muhatap gösterildin. Bir kez cevap hakkı kullanabilirsin.',y.baslik),oyun.simdi());
 return public.sos_haberler();
end $$;
create or replace function public.sos_haber_cevapla(p_yayin bigint,p_metin text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); m text:=btrim(coalesce(p_metin,'')); n int;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 if char_length(m) not between 10 and 3000 then raise exception 'Cevap 10–3000 karakter olmalı.'; end if;
 update oyun.sos_haber_cevap set metin=m,zaman=t where yayin_id=p_yayin and oyuncu_id=u and metin is null;
 get diagnostics n=row_count;
 if n<>1 then raise exception 'Bu haberde cevap hakkın yok veya daha önce kullandın.'; end if;
 return public.sos_haberler();
end $$;

create or replace function oyun.sos_duello_guncelle(p_id bigint,t timestamptz)
returns void language plpgsql set search_path='' as $$
declare d oyun.sos_duello; a int; b int; kaz text;
begin
 select * into d from oyun.sos_duello where id=p_id for update;
 if d.id is null then return; end if;
 if d.durum='davet' and t>d.olusturma+interval '24 hours' then
  update oyun.sos_duello set durum='reddedildi',bitti_at=t where id=d.id;
 elsif d.durum='canli' and (d.tur_sayisi>=6 or t>d.kabul_at+interval '24 hours') then
  update oyun.sos_duello set durum='oylama',oylama_bas=t,siradaki=null where id=d.id;
 elsif d.durum='oylama' and t>=d.oylama_bas+interval '24 hours' then
  select count(*) into a from oyun.sos_duello_oy where duello_id=d.id and tercih=d.davet_eden;
  select count(*) into b from oyun.sos_duello_oy where duello_id=d.id and tercih=d.davet_edilen;
  kaz:=case when a=b then 'Berabere' when a>b then oyun.kad(d.davet_eden) else oyun.kad(d.davet_edilen) end;
  update oyun.sos_duello set durum='bitti',bitti_at=t where id=d.id;
  perform oyun.olay('siyaset',format('“%s” siyasi tartışması sonuçlandı: %s (%s–%s).',d.baslik,kaz,a,b),null,null,t);
 end if;
end $$;
revoke all on function oyun.sos_duello_guncelle(bigint,timestamptz) from public,anon,authenticated;
create or replace function public.sos_duellolar() returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); d record;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 for d in select id from oyun.sos_duello where durum in ('davet','canli','oylama') and
 (durum<>'davet' or davet_eden=u or davet_edilen=u) order by id desc limit 80 loop
 perform oyun.sos_duello_guncelle(d.id,t);
 end loop;
 return coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'baslik',d.baslik,'birinci',oyun.kad(d.davet_eden),'ikinci',oyun.kad(d.davet_edilen),
 'davet_eden',d.davet_eden,'davet_edilen',d.davet_edilen,'durum',d.durum,'olusturma',d.olusturma,'kabul_at',d.kabul_at,
 'oylama_bas',d.oylama_bas,'tur_sayisi',d.tur_sayisi,'sira_bende',d.durum='canli' and d.siradaki=u,
 'davet_bende',d.durum='davet' and d.davet_edilen=u,'benim_oyum',(select tercih from oyun.sos_duello_oy where duello_id=d.id and user_id=u),
 'oy_bir',(select count(*) from oyun.sos_duello_oy where duello_id=d.id and tercih=d.davet_eden),
 'oy_iki',(select count(*) from oyun.sos_duello_oy where duello_id=d.id and tercih=d.davet_edilen),
 'sozler',coalesce((select jsonb_agg(jsonb_build_object('kad',oyun.kad(s.konusan),'metin',s.metin,'tur',s.tur,'zaman',s.zaman) order by s.tur)
 from oyun.sos_duello_soz s where s.duello_id=d.id),'[]'::jsonb)) order by d.id desc)
 from (select * from oyun.sos_duello where durum<>'davet' or davet_eden=u or davet_edilen=u order by id desc limit 80) d),'[]'::jsonb);
end $$;
create or replace function public.sos_duello_davet(p_kad text,p_baslik text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); h oyun.profiller; b text:=btrim(coalesce(p_baslik,'')); pid bigint;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 h:=oyun.profil_bul(p_kad);
 if h.id=u then raise exception 'Kendinle tartışamazsın.'; end if;
 if char_length(b) not between 5 and 120 then raise exception 'Konu 5–120 karakter olmalı.'; end if;
 if (select count(*) from oyun.sos_duello where davet_eden=u and olusturma>t-interval '24 hours')>=3 then raise exception '24 saatte en fazla üç düello daveti gönderebilirsin.'; end if;
 if not(exists(select 1 from oyun.partiler where gb=u and not kapali)
 or exists(select 1 from oyun.makamlar where user_id=u and tur in ('cb','bel','mv','bakan') and bit is null)
 or exists(select 1 from oyun.adaylar a join oyun.secimler s on s.id=a.secim_id where a.user_id=u and s.durum='bekliyor' and s.oy_bit>t)) then raise exception 'Canlı siyasi tartışma davetini yalnız parti başkanları, adaylar veya görevdeki siyasetçiler gönderebilir.'; end if;
 insert into oyun.sos_duello(davet_eden,davet_edilen,baslik,olusturma) values(u,h.id,b,t) returning id into pid;
 perform oyun.bildir(h.id,format('%s seni canlı siyasi tartışmaya davet etti: %s',oyun.kad(u),b),t);
 return public.sos_duellolar();
end $$;
create or replace function public.sos_duello_yanit(p_id bigint,p_kabul boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); d oyun.sos_duello; t timestamptz:=oyun.simdi();
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into d from oyun.sos_duello where id=p_id for update;
 if d.id is null or d.davet_edilen<>u or d.durum<>'davet' or d.olusturma<t-interval '24 hours' then raise exception 'Geçerli tartışma davetin yok.'; end if;
 update oyun.sos_duello set durum=case when p_kabul then 'canli' else 'reddedildi' end,kabul_at=case when p_kabul then t else null end,siradaki=case when p_kabul then d.davet_eden else null end,bitti_at=case when not p_kabul then t else null end where id=p_id;
 perform oyun.bildir(d.davet_eden,format('%s tartışma davetini %s.',oyun.kad(u),case when p_kabul then 'kabul etti' else 'reddetti' end),t);
 if p_kabul then perform oyun.olay('siyaset',format('%s ve %s arasında canlı siyasi tartışma başladı: %s',oyun.kad(d.davet_eden),oyun.kad(u),d.baslik),null,null,t); end if;
 return public.sos_duellolar();
end $$;
create or replace function public.sos_duello_konus(p_id bigint,p_metin text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); d oyun.sos_duello; t timestamptz:=oyun.simdi(); msg text:=btrim(coalesce(p_metin,''));
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into d from oyun.sos_duello where id=p_id for update;
 if d.id is null or d.durum<>'canli' or d.siradaki is distinct from u or d.tur_sayisi>=6 or t>d.kabul_at+interval '24 hours' then raise exception 'Şu anda konuşma sırası sende değil.'; end if;
 if char_length(msg) not between 10 and 2000 then raise exception 'Konuşma 10–2000 karakter olmalı.'; end if;
 insert into oyun.sos_duello_soz(duello_id,konusan,metin,zaman,tur) values(d.id,u,msg,t,d.tur_sayisi+1);
 update oyun.sos_duello set tur_sayisi=tur_sayisi+1,siradaki=case when u=d.davet_eden then d.davet_edilen else d.davet_eden end where id=d.id;
 perform oyun.sos_duello_guncelle(d.id,t);
 return public.sos_duellolar();
end $$;
create or replace function public.sos_duello_oyla(p_id bigint,p_aday uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); d oyun.sos_duello; t timestamptz:=oyun.simdi();
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into d from oyun.sos_duello where id=p_id for update;
 if d.id is null or d.durum<>'oylama' or t>=d.oylama_bas+interval '24 hours' then raise exception 'Halk oylaması açık değil.'; end if;
 if u in (d.davet_eden,d.davet_edilen) then raise exception 'Tartışmanın tarafları oy veremez.'; end if;
 if p_aday is distinct from d.davet_eden and p_aday is distinct from d.davet_edilen then raise exception 'Geçersiz tercih.'; end if;
 insert into oyun.sos_duello_oy(duello_id,user_id,tercih,zaman) values(d.id,u,p_aday,t) on conflict do nothing;
 if not found then raise exception 'Bu tartışmada oyun zaten kayıtlı.'; end if;
 return public.sos_duellolar();
end $$;
do $$ declare f text; begin
 foreach f in array array[
 'sos_roportajlar()','sos_roportaj_davet(bigint,text,text,text)','sos_roportaj_yanit(bigint,boolean,text)','sos_roportaj_yayinla(bigint)',
 'sos_haberler()','sos_haber_hedefle(bigint,text)','sos_haber_cevapla(bigint,text)',
 'sos_duellolar()','sos_duello_davet(text,text)','sos_duello_yanit(bigint,boolean)','sos_duello_konus(bigint,text)','sos_duello_oyla(bigint,uuid)'
 ] loop execute 'revoke all on function public.'||f||' from public,anon'; execute 'grant execute on function public.'||f||' to authenticated'; end loop;
end $$;
-- Seçim Online: herkes için imza kampanyaları ve resmi vatandaş dilekçeleri
create table if not exists oyun.sos_dilekce(
 id bigint generated always as identity primary key,
 gonderen uuid not null references oyun.profiller(id),
 makam text not null check(makam in ('cb','bel','mv')),
 muhatap uuid not null references oyun.profiller(id),
 il_id smallint references oyun.iller(id),
 baslik text not null check(char_length(baslik) between 5 and 120),
 metin text not null check(char_length(metin) between 10 and 3000),
 olusturma timestamptz not null default now(),
 durum text not null default 'bekliyor' check(durum in ('bekliyor','islemde','kabul','ret')),
 cevap text,
 cevap_at timestamptz,
 imza_kamp_id bigint unique
);
create index if not exists sos_dilekce_z on oyun.sos_dilekce(olusturma desc);
create table if not exists oyun.sos_imza_kamp (
 id bigint generated always as identity primary key,
 acan uuid not null references oyun.profiller(id),
 makam text not null check(makam in ('cb','bel','mv')),
 muhatap uuid not null references oyun.profiller(id),
 il_id smallint references oyun.iller(id),
 baslik text not null check(char_length(baslik) between 5 and 120),
 metin text not null check(char_length(metin) between 10 and 3000),
 bas timestamptz not null default now(),
 bit timestamptz not null default (now()+interval '72 hours'),
 esik int not null check(esik>0),
 durum text not null default 'acik' check(durum in ('acik','basarili','sure_doldu')),
 dilekce_id bigint unique references oyun.sos_dilekce(id)
);
create table if not exists oyun.sos_imza(
 kampanya_id bigint not null references oyun.sos_imza_kamp(id) on delete cascade,
 user_id uuid not null references oyun.profiller(id),
 zaman timestamptz not null default now(),
 primary key(kampanya_id,user_id)
);
create index if not exists sos_imza_kamp_z on oyun.sos_imza_kamp(bas desc);
alter table oyun.sos_dilekce enable row level security;
alter table oyun.sos_imza_kamp enable row level security;
alter table oyun.sos_imza enable row level security;
revoke all on oyun.sos_dilekce,oyun.sos_imza_kamp,oyun.sos_imza from public,anon,authenticated;
do $$ begin
 if not exists(select 1 from pg_constraint where conname='sos_dilekce_kamp_ref' and conrelid='oyun.sos_dilekce'::regclass) then
 alter table oyun.sos_dilekce add constraint sos_dilekce_kamp_ref foreign key (imza_kamp_id) references oyun.sos_imza_kamp(id);
 end if;
end $$;

create or replace function oyun.sos_muhatap(p_makam text,p_kad text,p_il int) returns oyun.makamlar
language plpgsql stable set search_path='' as $$
declare m oyun.makamlar;
begin
 if p_makam not in ('cb','bel','mv') then raise exception 'Yalnızca cumhurbaşkanına, belediye başkanına veya milletvekiline başvurabilirsin.'; end if;
 if p_makam='cb' then
 select * into m from oyun.makamlar where tur='cb' and bit is null order by bas desc limit 1;
 elsif p_makam='bel' then
 if p_il is null or not exists(select 1 from oyun.iller where id=p_il) then raise exception 'Belediye ilini seçmelisin.'; end if;
 select * into m from oyun.makamlar where tur='bel' and il_id=p_il and bit is null order by bas desc limit 1;
 elsif p_makam='mv' then
 if nullif(btrim(coalesce(p_kad,'')),'') is null then raise exception 'Milletvekilinin kullanıcı adını yazmalısın.'; end if;
 select m1.* into m from oyun.makamlar m1 join oyun.profiller p on p.id=m1.user_id
 where m1.tur='mv' and m1.bit is null and lower(p.kad)=lower(btrim(p_kad)) order by m1.bas desc limit 1;
 end if;
 if m.id is null then raise exception 'Seçilen makamda şu anda görev yapan oyuncu bulunamadı.'; end if;
 return m;
end $$;
revoke all on function oyun.sos_muhatap(text,text,integer) from public,anon,authenticated;

create or replace function public.sos_dilekceler() returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi();
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object(
 'id',d.id,'gonderen',oyun.kad(d.gonderen),'muhatap',oyun.kad(d.muhatap),'makam',d.makam,'il_id',d.il_id,
 'baslik',d.baslik,'metin',d.metin,'olusturma',d.olusturma,'durum',d.durum,'cevap',d.cevap,'cevap_at',d.cevap_at,
 'imza_kamp_id',d.imza_kamp_id,
 'cevaplayabilirim',d.muhatap=u and d.durum in ('bekliyor','islemde')
 and exists(select 1 from oyun.makamlar m where m.tur=d.makam and m.user_id=u and m.bit is null and (d.makam<>'bel' or m.il_id=d.il_id)))
 order by d.id desc)
 from (select * from oyun.sos_dilekce order by id desc limit 100) d),'[]'::jsonb);
end $$;

create or replace function public.sos_dilekce_gonder(p_makam text,p_kad text,p_il int,p_baslik text,p_metin text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); m oyun.makamlar;
 b text:=btrim(coalesce(p_baslik,'')); a text:=btrim(coalesce(p_metin,''));
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 m:=oyun.sos_muhatap(p_makam,p_kad,p_il);
 if char_length(b) not between 5 and 120 or char_length(a) not between 10 and 3000 then raise exception 'Başlık 5–120, dilekçe 10–3000 karakter olmalı.'; end if;
 if (select count(*) from oyun.sos_dilekce where gonderen=u and olusturma>t-interval '24 hours' and imza_kamp_id is null)>=5 then raise exception '24 saatte en fazla 5 doğrudan dilekçe gönderebilirsin.'; end if;
 insert into oyun.sos_dilekce(gonderen,makam,muhatap,il_id,baslik,metin,olusturma)
 values(u,m.tur,m.user_id,m.il_id,b,a,t);
 perform oyun.bildir(m.user_id,format('%s sana resmi dilekçe gönderdi: %s',oyun.kad(u),b),t);
 return public.sos_dilekceler();
end $$;

create or replace function public.sos_dilekce_yanit(p_id bigint,p_durum text,p_cevap text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); d oyun.sos_dilekce; a text:=btrim(coalesce(p_cevap,''));
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into d from oyun.sos_dilekce where id=p_id for update;
 if d.id is null or d.muhatap<>u or d.durum not in ('bekliyor','islemde') then raise exception 'Bu dilekçeye cevap verme hakkın yok.'; end if;
 if not exists(select 1 from oyun.makamlar where user_id=u and tur=d.makam and bit is null and (d.makam<>'bel' or il_id=d.il_id)) then raise exception 'Artık bu makamda görev yapmıyorsun.'; end if;
 if p_durum not in ('islemde','kabul','ret') then raise exception 'Geçersiz durum.'; end if;
 if char_length(a) not between 5 and 3000 then raise exception 'Resmi açıklama 5–3000 karakter olmalı.'; end if;
 update oyun.sos_dilekce set durum=p_durum,cevap=a,cevap_at=t where id=p_id;
 perform oyun.bildir(d.gonderen,format('“%s” dilekçen yanıtlandı. Durum: %s.',d.baslik,p_durum),t);
 return public.sos_dilekceler();
end $$;

create or replace function public.sos_imza_kampanyalari() returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi();
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 update oyun.sos_imza_kamp set durum='sure_doldu' where durum='acik' and bit<=t;
 return coalesce((select jsonb_agg(jsonb_build_object(
 'id',k.id,'acan',oyun.kad(k.acan),'muhatap',oyun.kad(k.muhatap),'makam',k.makam,'il_id',k.il_id,
 'baslik',k.baslik,'metin',k.metin,'bas',k.bas,'bit',k.bit,'esik',k.esik,'durum',k.durum,
 'imza',(select count(*) from oyun.sos_imza where kampanya_id=k.id),'imzaladim',exists(select 1 from oyun.sos_imza where kampanya_id=k.id and user_id=u),
 'dilekce_id',k.dilekce_id
 ) order by k.id desc)
 from (select * from oyun.sos_imza_kamp order by id desc limit 100) k),'[]'::jsonb);
end $$;
create or replace function public.sos_imza_baslat(p_makam text,p_kad text,p_il int,p_baslik text,p_metin text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); m oyun.makamlar; b text:=btrim(coalesce(p_baslik,'')); a text:=btrim(coalesce(p_metin,'')); es int; kid bigint;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 m:=oyun.sos_muhatap(p_makam,p_kad,p_il);
 if char_length(b) not between 5 and 120 or char_length(a) not between 10 and 3000 then raise exception 'Başlık 5–120, kampanya metni 10–3000 karakter olmalı.'; end if;
 if (select count(*) from oyun.sos_imza_kamp where acan=u and bas>t-interval '24 hours')>=3 then raise exception '24 saatte en fazla 3 imza kampanyası açabilirsin.'; end if;
 select greatest(3,ceil(count(*)::numeric*0.15)::int) into es from oyun.profiller where not yasakli;
 insert into oyun.sos_imza_kamp(acan,makam,muhatap,il_id,baslik,metin,bas,bit,esik)
 values(u,m.tur,m.user_id,m.il_id,b,a,t,t+interval '72 hours',es) returning id into kid;
 perform oyun.olay('siyaset',format('%s imza kampanyası açtı: %s',oyun.kad(u),b),m.il_id,null,t);
 return public.sos_imza_kampanyalari();
end $$;
create or replace function public.sos_imza_at(p_id bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); k oyun.sos_imza_kamp; n int; did bigint;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into k from oyun.sos_imza_kamp where id=p_id for update;
 if k.id is null or k.durum<>'acik' or k.bit<=t then raise exception 'Kampanya imzaya kapalı.'; end if;
 insert into oyun.sos_imza(kampanya_id,user_id,zaman) values(k.id,u,t) on conflict do nothing;
 if not found then raise exception 'Bu kampanyayı zaten imzaladın.'; end if;
 select count(*) into n from oyun.sos_imza where kampanya_id=k.id;
 if n>=k.esik then
  insert into oyun.sos_dilekce(gonderen,makam,muhatap,il_id,baslik,metin,olusturma,imza_kamp_id)
  values(k.acan,k.makam,k.muhatap,k.il_id,k.baslik,k.metin,t,k.id) returning id into did;
  update oyun.sos_imza_kamp set durum='basarili',dilekce_id=did where id=k.id;
  perform oyun.bildir(k.muhatap,format('“%s” kampanyası %s imzayla resmi dilekçe olarak makamına sunuldu.',k.baslik,n),t);
  perform oyun.bildir(k.acan,format('“%s” kampanyan hedefe ulaştı ve resmi dilekçeye dönüştü.',k.baslik),t);
  perform oyun.olay('siyaset',format('%s imzayla “%s” kampanyası resmi dilekçeye dönüştü.',n,k.baslik),k.il_id,null,t);
 end if;
 return public.sos_imza_kampanyalari();
end $$;

do $$ declare f text; begin
 foreach f in array array[
 'sos_dilekceler()','sos_dilekce_gonder(text,text,integer,text,text)','sos_dilekce_yanit(bigint,text,text)',
 'sos_imza_kampanyalari()','sos_imza_baslat(text,text,integer,text,text)','sos_imza_at(bigint)'
 ] loop execute 'revoke all on function public.'||f||' from public,anon'; execute 'grant execute on function public.'||f||' to authenticated'; end loop;
end $$;
create or replace function public.sos_duellolar() returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); rec record;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 for rec in select id from oyun.sos_duello where durum in ('davet','canli','oylama') and
 (durum<>'davet' or davet_eden=u or davet_edilen=u) order by id desc limit 80 loop
 perform oyun.sos_duello_guncelle(rec.id,t);
 end loop;
 return coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'baslik',d.baslik,'birinci',oyun.kad(d.davet_eden),'ikinci',oyun.kad(d.davet_edilen),
 'davet_eden',d.davet_eden,'davet_edilen',d.davet_edilen,'durum',d.durum,'olusturma',d.olusturma,'kabul_at',d.kabul_at,
 'oylama_bas',d.oylama_bas,'tur_sayisi',d.tur_sayisi,'sira_bende',d.durum='canli' and d.siradaki=u,
 'davet_bende',d.durum='davet' and d.davet_edilen=u,'benim_oyum',(select tercih from oyun.sos_duello_oy where duello_id=d.id and user_id=u),
 'oy_bir',(select count(*) from oyun.sos_duello_oy where duello_id=d.id and tercih=d.davet_eden),
 'oy_iki',(select count(*) from oyun.sos_duello_oy where duello_id=d.id and tercih=d.davet_edilen),
 'sozler',coalesce((select jsonb_agg(jsonb_build_object('kad',oyun.kad(s.konusan),'metin',s.metin,'tur',s.tur,'zaman',s.zaman) order by s.tur)
 from oyun.sos_duello_soz s where s.duello_id=d.id),'[]'::jsonb)) order by d.id desc)
 from (select * from oyun.sos_duello where durum<>'davet' or davet_eden=u or davet_edilen=u order by id desc limit 80) d),'[]'::jsonb);
end $$;
create or replace function public.sos_parti_imzala(p_parti bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); t timestamptz:=oyun.simdi(); p oyun.partiler; c oyun.sos_parti_imza; n int; toplam int; o jsonb;
begin
 if u is null then raise exception 'Oturum gerekli.'; end if;
 select * into p from oyun.partiler where id=p_parti and not kapali for update;
 if p.id is null or not exists(select 1 from oyun.profiller where id=u and parti_id=p.id) then raise exception 'Yalnızca bu partinin üyeleri imzalayabilir.'; end if;
 if exists(select 1 from oyun.secimler where tur='kurultay' and ara and hedef_parti_id=p.id and durum<>'tamam' and goreve_bas>t) then raise exception 'Parti için zaten olağanüstü kurultay var.'; end if;
 update oyun.sos_parti_imza set durum='sure_doldu' where parti_id=p.id and durum='acik' and bit<=t;
 select * into c from oyun.sos_parti_imza where parti_id=p.id and durum='acik' for update;
 if c.id is null then insert into oyun.sos_parti_imza(parti_id,acan,bas,bit) values(p.id,u,t,t+interval '7 days') returning * into c; end if;
 if not exists(select 1 from oyun.profiller where id=u and parti_id=p.id and coalesce(parti_at,olusturma)<=c.bas) and c.acan<>u then raise exception 'İmza kampanyası açıldıktan sonra katılan üyeler bu kampanyada imza atamaz.'; end if;
 insert into oyun.sos_parti_imzaci(kampanya_id,user_id) values(c.id,u) on conflict do nothing;
 if not found then raise exception 'Bu kampanyayı zaten imzaladın.'; end if;
 select count(*) into n from oyun.sos_parti_imzaci where kampanya_id=c.id;
 select count(*) into toplam from oyun.profiller where parti_id=p.id;
 if n>=greatest(2,ceil(toplam::numeric/3)::int) then
   o:=oyun.ara_secim_olustur('gb',p.id,null::smallint,t);
   update oyun.secimler set ara_neden='uye_imza_kampanyasi' where id=(o->>'secim_id')::bigint and ara and ara_neden='genel_baskan_istifa';
   update oyun.sos_parti_imza set durum='basarili',secim_id=(o->>'secim_id')::bigint where id=c.id;
   perform oyun.olay('parti',format('%s üyelerinin imzasıyla olağanüstü kurultay kararı alındı.',p.ad),null,p.id,t);
   if p.gb is not null then perform oyun.bildir(p.gb,format('%s üyeleri olağanüstü kurultay topladı.',p.ad),t); end if;
 end if;
 return public.sos_parti_imza_durum(p.id);
end $$;
-- Modül 62: Şirket halka arzı (yeni pay satışıyla sermaye toplama) ve yatırım hesaplayıcısı.
-- Mevcut şirketlere, ortaklara, kasalara ve paylara dokunmaz; yalnız yeni tablo/sütun/fonksiyon ekler.
--
-- Kurallar:
--  * Halka arzı, şirketin en az %50'sine sahip ortak başlatır (aynı anda tek açık arz).
--  * Şirket değeri (arz öncesi) ortakça belirlenir: en az sermaye, en çok max(2 × sermaye, 52 × ortalama haftalık net).
--  * Satılan yeni pay en fazla %49; toplam sermaye 100 milyon ₺'yi aşamaz.
--  * Talep toplama 24/48/72 saat. Talep eden oyuncunun parası arz bitene kadar emanette tutulur.
--  * Süre dolunca toplanan tutar asgari tutara ulaştıysa arz gerçekleşir: para şirketin sermayesine ve
--    kasasına girer, eski ortakların payı oranla seyrelir, yatırımcılar yatırdıkları oranda ortak olur.
--    Ulaşmadıysa ya da arz iptal edilirse herkesin parası iade edilir.
--  * Hedef tutar dolarsa arz beklemeden tamamlanır.
--  * Toplanan para sermayeye eklendiği için kâr payı olarak dağıtılamaz; ortaklar haftalık kârdan
--    paylarına göre pay alır.

alter table oyun.sirketler add column if not exists halka_acik boolean not null default false;

create table if not exists oyun.halka_arz(
  id bigint generated always as identity primary key,
  sirket_id bigint not null references oyun.sirketler(id),
  baslatan uuid not null references auth.users(id),
  deger numeric not null check (deger > 0),
  hedef numeric not null check (hedef > 0),
  asgari numeric not null check (asgari > 0),
  toplanan numeric not null default 0,
  bas timestamptz not null,
  bit timestamptz not null,
  durum text not null default 'acik' check (durum in ('acik','tamam','basarisiz','iptal')),
  sonuc_zaman timestamptz,
  aciklama text
);
create index if not exists halka_arz_sirket on oyun.halka_arz(sirket_id, bas desc);
create index if not exists halka_arz_acik on oyun.halka_arz(bit) where durum = 'acik';
create unique index if not exists halka_arz_tek_acik on oyun.halka_arz(sirket_id) where durum = 'acik';

create table if not exists oyun.halka_arz_talep(
  id bigint generated always as identity primary key,
  arz_id bigint not null references oyun.halka_arz(id),
  user_id uuid not null references auth.users(id),
  tutar numeric not null check (tutar > 0),
  zaman timestamptz not null,
  pay numeric,
  unique (arz_id, user_id)
);
create index if not exists halka_arz_talep_user on oyun.halka_arz_talep(user_id);

alter table oyun.halka_arz enable row level security;
alter table oyun.halka_arz_talep enable row level security;
revoke all on oyun.halka_arz, oyun.halka_arz_talep from public, anon, authenticated;
do $$ begin
  if to_regproc('oyun.bosaltma_korumasi') is not null then
    drop trigger if exists bosaltma_korumasi on oyun.halka_arz;
    create trigger bosaltma_korumasi before truncate on oyun.halka_arz for each statement execute function oyun.bosaltma_korumasi();
    drop trigger if exists bosaltma_korumasi on oyun.halka_arz_talep;
    create trigger bosaltma_korumasi before truncate on oyun.halka_arz_talep for each statement execute function oyun.bosaltma_korumasi();
  end if;
end $$;

-- HATA DÜZELTMESİ: haftalık şirket hesabı ilk kez çalıştığında "round(double precision, integer) does not exist"
-- hatasıyla duruyordu (random() double döndürür). Bu yüzden hiçbir şirkete haftalık kâr yazılmamıştı ve
-- 7. gün dolunca "Şirketlerim" ekranı açılmayacaktı. Mantık canlıdakiyle aynı; yalnız random() numeric'e çevrildi.
create or replace function oyun.sirket_hesapla(p_id bigint)
returns void language plpgsql security definer set search_path to 'oyun', 'public', 'pg_temp' as $function$
declare s oyun.sirketler;n int;i int;net numeric;income numeric;cost numeric;w numeric;t timestamptz:=oyun.simdi();x record;distributed numeric;rate numeric;v_taahhut numeric;v_mevduat numeric;
begin
 perform pg_advisory_xact_lock(98763,hashtext(p_id::text));
 select * into s from oyun.sirketler where id=p_id for update;
 if s.id is null or not s.aktif or s.sonraki_kazanc>t then return;end if;
 n:=least(52,floor(extract(epoch from (t-s.sonraki_kazanc))/604800)::int+1);
 w:=(select asgari from oyun.ulke where id=1);
 rate:=case s.sektor when 'tarim' then .12 when 'sanayi' then .15 when 'teknoloji' then .20 when 'ticaret' then .14 when 'insaat' then .18 when 'medya' then .16 else .08 end;
 for i in 1..n loop
  income:=round(s.sermaye*rate*(0.6+random()::numeric*.8),2);
  cost:=round(s.sermaye*(.025+random()::numeric*.055)+w*(.5+random()::numeric),2);
  net:=income-cost;
  distributed:=0;
  -- Zararda sirket kasasi erir. Karda dagitilabilir para ortaklara aktarilir.
  if net<0 then
   if s.sektor='banka' then
     select coalesce(sum(round(m.anapara*(1+m.faiz/100),2)),0),coalesce(sum(m.anapara),0) into v_taahhut,v_mevduat from oyun.banka_mevduat m where m.banka_id=p_id and not m.kapandi;
     net:=greatest(net,-greatest(0,(select kasa from oyun.sirketler where id=p_id)-v_taahhut-greatest(s.sermaye*0.10,v_mevduat*0.10)));
   end if;
   update oyun.sirketler set kasa=kasa+net where id=p_id;
  else
   distributed:=case when s.sektor='banka' then least(net,greatest(0,(select kasa from oyun.sirketler where id=p_id)+net-s.sermaye-coalesce((select sum(round(m.anapara*(1+m.faiz/100),2)) from oyun.banka_mevduat m where m.banka_id=p_id and not m.kapandi),0))) else least(net,greatest(0,(select kasa from oyun.sirketler where id=p_id)+net)) end;
   for x in select * from oyun.sirket_ortaklari where sirket_id=p_id loop
    perform oyun.para_islem(x.user_id,round(distributed*x.pay/100,2),'sirket',format('Sirket #%s haftalik net kar payi',p_id),t);
   end loop;
   update oyun.sirketler set kasa=kasa+net-distributed where id=p_id;
  end if;
  insert into oyun.sirket_hareket(sirket_id,zaman,tutar,aciklama,faaliyet_gelir,faaliyet_gider,dagitilan_kar)
 values(p_id,t,net,'7 günlük faaliyet: gelir - gider = net sonuç; gerçekleşen ortak ödemesi ayrıca kaydedildi',income,cost,distributed);
 end loop;
 update oyun.sirketler set sonraki_kazanc=sonraki_kazanc+n*interval '7 days',son_islem=t where id=p_id;
end $function$;

-- Haftalık ortalama net kâr: oyun formülüyle aynı (sirket_hesapla gelir/gider ortalaması).
create or replace function oyun.sirket_ort_net(p_sermaye numeric, p_sektor text)
returns numeric language sql stable set search_path = '' as $$
  select round(p_sermaye * (case p_sektor when 'tarim' then .12 when 'sanayi' then .15 when 'teknoloji' then .20
           when 'ticaret' then .14 when 'insaat' then .18 when 'medya' then .16 else .08 end)
         - p_sermaye * .0525 - (select u.asgari from oyun.ulke u where u.id = 1))
$$;

create or replace function oyun.halka_arz_deger_sinir(p_sermaye numeric, p_sektor text, out en_az numeric, out en_cok numeric, out onerilen numeric)
language sql stable set search_path = '' as $$
  select p_sermaye,
         least(500000000, greatest(p_sermaye * 2, 52 * oyun.sirket_ort_net(p_sermaye, p_sektor))),
         least(least(500000000, greatest(p_sermaye * 2, 52 * oyun.sirket_ort_net(p_sermaye, p_sektor))),
               greatest(p_sermaye, 26 * oyun.sirket_ort_net(p_sermaye, p_sektor)))
$$;

-- Arzı sonuçlandırır (süre doldu, hedef doldu ya da iptal).
create or replace function oyun.halka_arz_kapat(p_id bigint, p_iptal boolean default false)
returns text language plpgsql security definer set search_path = '' as $$
declare a oyun.halka_arz; s oyun.sirketler; t timestamptz := oyun.simdi(); x record; post numeric; f numeric; fark numeric; kisi int; v_sonuc text;
begin
  select * into a from oyun.halka_arz where id = p_id for update;
  if a.id is null or a.durum <> 'acik' then return coalesce(a.durum, 'yok'); end if;
  perform pg_advisory_xact_lock(98763, hashtext(a.sirket_id::text));
  select * into s from oyun.sirketler where id = a.sirket_id for update;
  select count(*) into kisi from oyun.halka_arz_talep where arz_id = a.id;

  if p_iptal or a.toplanan < a.asgari or kisi = 0 or not coalesce(s.aktif, false)
     or s.sermaye + a.toplanan > 100000000 then
    v_sonuc := case when p_iptal then 'iptal' else 'basarisiz' end;
    for x in select * from oyun.halka_arz_talep where arz_id = a.id loop
      perform oyun.para_islem(x.user_id, x.tutar, 'sirket', format('%s halka arzı %s: talep iadesi', s.ad,
        case when p_iptal then 'iptal edildi' else 'gerçekleşmedi' end), t);
      perform oyun.bildir(x.user_id, format('%s halka arzı %s. %s ₺ talebin cüzdanına iade edildi.', s.ad,
        case when p_iptal then 'iptal edildi' else format('yeterli talep toplayamadı (%s / %s ₺)', oyun.tl(a.toplanan), oyun.tl(a.asgari)) end,
        oyun.tl(x.tutar)), t);
    end loop;
    update oyun.halka_arz set durum = v_sonuc, sonuc_zaman = t,
      aciklama = case when p_iptal then 'Şirket tarafından iptal edildi' else 'Asgari talep tutarına ulaşılamadı' end
      where id = a.id;
    perform oyun.bildir(a.baslatan, format('%s halka arzı %s; toplanan %s ₺ yatırımcılara iade edildi.', s.ad,
      case when p_iptal then 'iptal edildi' else 'yeterli talep toplayamadı' end, oyun.tl(a.toplanan)), t);
    return v_sonuc;
  end if;

  -- Önce birikmiş haftalık faaliyetleri eski sermaye ve paylarla kapat.
  perform oyun.sirket_hesapla(a.sirket_id);
  post := a.deger + a.toplanan;
  f := a.deger / post;
  update oyun.sirket_ortaklari set pay = round(pay * f, 6) where sirket_id = a.sirket_id;
  for x in select * from oyun.halka_arz_talep where arz_id = a.id order by id loop
    update oyun.halka_arz_talep set pay = round(x.tutar / post * 100, 6) where id = x.id;
    insert into oyun.sirket_ortaklari(sirket_id, user_id, pay) values (a.sirket_id, x.user_id, round(x.tutar / post * 100, 6))
      on conflict (sirket_id, user_id) do update set pay = oyun.sirket_ortaklari.pay + excluded.pay;
  end loop;
  delete from oyun.sirket_ortaklari where sirket_id = a.sirket_id and pay <= 0;
  -- Yuvarlama farkı en büyük ortağa yazılır; paylar toplamı tam %100 olur.
  select 100 - sum(pay) into fark from oyun.sirket_ortaklari where sirket_id = a.sirket_id;
  if fark <> 0 then
    update oyun.sirket_ortaklari set pay = pay + fark
      where sirket_id = a.sirket_id and user_id = (select user_id from oyun.sirket_ortaklari where sirket_id = a.sirket_id order by pay desc, user_id limit 1);
  end if;
  update oyun.sirketler set sermaye = sermaye + a.toplanan, kasa = kasa + a.toplanan, halka_acik = true, satilik = null where id = a.sirket_id;
  insert into oyun.sirket_hareket(sirket_id, zaman, tutar, aciklama)
    values (a.sirket_id, t, a.toplanan, format('Halka arz: %s yatırımcıdan %s ₺ yeni sermaye (şirket değeri %s ₺, satılan pay %%%s)',
      kisi, oyun.tl(a.toplanan), oyun.tl(a.deger), round(a.toplanan / post * 100, 2)));
  update oyun.halka_arz set durum = 'tamam', sonuc_zaman = t,
    aciklama = format('%s yatırımcı, %s ₺, satılan pay %%%s', kisi, oyun.tl(a.toplanan), round(a.toplanan / post * 100, 2)) where id = a.id;
  for x in select h.user_id, h.tutar, h.pay from oyun.halka_arz_talep h where h.arz_id = a.id loop
    perform oyun.bildir(x.user_id, format('%s halka arzı tamamlandı: %s ₺ karşılığında şirketin %%%s ortağı oldun. Haftalık kârdan payına düşen tutar cüzdanına gelecek.',
      s.ad, oyun.tl(x.tutar), round(x.pay, 2)), t);
  end loop;
  for x in select o.user_id, o.pay from oyun.sirket_ortaklari o
           where o.sirket_id = a.sirket_id and not exists (select 1 from oyun.halka_arz_talep h where h.arz_id = a.id and h.user_id = o.user_id) loop
    perform oyun.bildir(x.user_id, format('%s halka arzı tamamlandı: %s ₺ yeni sermaye girdi (yeni sermaye %s ₺). Şirketteki payın artık %%%s.',
      s.ad, oyun.tl(a.toplanan), oyun.tl(s.sermaye + a.toplanan), round(x.pay, 2)), t);
  end loop;
  perform oyun.olay('ekonomi', format('%s halka arzı tamamlandı: %s yatırımcı %s ₺ yatırdı, şirket sermayesi %s ₺ oldu.',
    s.ad, kisi, oyun.tl(a.toplanan), oyun.tl(s.sermaye + a.toplanan)), null, null, t);
  return 'tamam';
end $$;

-- Süresi dolan arzları kapatır. Zamanlayıcı her dakika çağırır; listeleme fonksiyonları da çağırır.
create or replace function oyun.halka_arz_tick()
returns void language plpgsql security definer set search_path = '' as $$
declare x record;
begin
  for x in select id from oyun.halka_arz where durum = 'acik' and bit <= oyun.simdi() order by bit loop
    perform oyun.halka_arz_kapat(x.id, false);
  end loop;
end $$;

create or replace function oyun.halka_arz_json(a oyun.halka_arz, u uuid)
returns jsonb language sql stable set search_path = '' as $$
  select jsonb_build_object(
    'id', a.id, 'sirket_id', a.sirket_id, 'sirket', s.ad, 'sektor', s.sektor,
    'baslatan', (select kad from oyun.profiller where id = a.baslatan), 'ben_baslattim', a.baslatan = u,
    'deger', a.deger, 'hedef', a.hedef, 'asgari', a.asgari, 'toplanan', a.toplanan,
    'bas', a.bas, 'bit', a.bit, 'durum', a.durum, 'sonuc_zaman', a.sonuc_zaman, 'aciklama', a.aciklama,
    'sermaye', s.sermaye, 'kasa', s.kasa,
    'satilan_pay_hedef', round(a.hedef / (a.deger + a.hedef) * 100, 2),
    'pay_fiyati_1', round((a.deger + a.hedef) / 100, 2),
    'ort_net_simdi', oyun.sirket_ort_net(s.sermaye, s.sektor),
    'ort_net_hedef', oyun.sirket_ort_net(s.sermaye + case when a.durum = 'acik' then a.hedef else 0 end, s.sektor),
    'yatirimci', (select count(*) from oyun.halka_arz_talep h where h.arz_id = a.id),
    'talebim', coalesce((select h.tutar from oyun.halka_arz_talep h where h.arz_id = a.id and h.user_id = u), 0),
    'ortaklar', coalesce((select jsonb_agg(jsonb_build_object('kad', p.kad, 'pay', round(o.pay, 2)) order by o.pay desc)
                  from oyun.sirket_ortaklari o join oyun.profiller p on p.id = o.user_id where o.sirket_id = s.id), '[]'::jsonb))
  from oyun.sirketler s where s.id = a.sirket_id
$$;

-- Hesaplayıcı: "şu kadar yatırım gelse haftalık ortalama kâr kaça çıkar, payım ne olur?"
create or replace function public.halka_arz_hesapla(p_sirket bigint, p_tutar numeric, p_deger numeric default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); s oyun.sirketler; d record; v_deger numeric; v_tutar numeric; post numeric; benim numeric; once numeric; sonra numeric;
begin
  if u is null then raise exception 'Oturum açmalısın'; end if;
  select * into s from oyun.sirketler where id = p_sirket and aktif;
  if s.id is null then raise exception 'Şirket bulunamadı'; end if;
  select * into d from oyun.halka_arz_deger_sinir(s.sermaye, s.sektor);
  v_tutar := greatest(0, round(coalesce(p_tutar, 0)));
  v_deger := least(d.en_cok, greatest(d.en_az, round(coalesce(p_deger, d.onerilen))));
  post := v_deger + v_tutar;
  benim := coalesce((select pay from oyun.sirket_ortaklari where sirket_id = s.id and user_id = u), 0);
  once := oyun.sirket_ort_net(s.sermaye, s.sektor);
  sonra := oyun.sirket_ort_net(s.sermaye + v_tutar, s.sektor);
  return jsonb_build_object(
    'sirket', s.ad, 'sektor', s.sektor, 'sermaye', s.sermaye, 'yeni_sermaye', s.sermaye + v_tutar,
    'yatirim', v_tutar, 'deger', v_deger, 'deger_en_az', d.en_az, 'deger_en_cok', d.en_cok, 'deger_onerilen', d.onerilen,
    'asgari_ucret', (select asgari from oyun.ulke where id = 1),
    'ort_net_simdi', once, 'ort_net_sonra', sonra, 'ort_net_artis', sonra - once,
    'yatirimci_payi', round(v_tutar / post * 100, 2),
    'benim_payim_simdi', round(benim, 2), 'benim_payim_sonra', round(benim * v_deger / post, 2),
    'benim_haftalik_simdi', round(greatest(once, 0) * benim / 100), 'benim_haftalik_sonra', round(greatest(sonra, 0) * benim * v_deger / post / 100),
    'yatirimci_haftalik', round(greatest(sonra, 0) * v_tutar / post),
    'yatirimci_geri_donus_hafta', case when sonra > 0 and v_tutar > 0 then ceil(v_tutar / (sonra * v_tutar / post)) end,
    'sinir_asildi', s.sermaye + v_tutar > 100000000 or (v_tutar > 0 and v_tutar / post > .49));
end $$;

create or replace function public.halka_arz_baslat(p_sirket bigint, p_hedef numeric, p_deger numeric, p_asgari numeric default null, p_saat int default 72)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); s oyun.sirketler; d record; t timestamptz := oyun.simdi(); v_asgari numeric; v_id bigint;
begin
  if u is null or not exists (select 1 from oyun.profiller where id = u and not yasakli) then raise exception 'Oyuncu hesabı gerekli'; end if;
  perform pg_advisory_xact_lock(98763, hashtext(p_sirket::text));
  select * into s from oyun.sirketler where id = p_sirket and aktif for update;
  if s.id is null then raise exception 'Şirket bulunamadı'; end if;
  if not exists (select 1 from oyun.sirket_ortaklari where sirket_id = s.id and user_id = u and pay >= 50) then
    raise exception 'Halka arzı yalnız şirketin en az %%50''sine sahip ortak başlatabilir'; end if;
  if exists (select 1 from oyun.halka_arz where sirket_id = s.id and durum = 'acik') then raise exception 'Bu şirketin zaten açık bir halka arzı var'; end if;
  if p_hedef is null or p_hedef <> round(p_hedef) or p_hedef < 10000 then raise exception 'Halka arz tutarı en az 10.000 ₺ ve tam sayı olmalı'; end if;
  if s.sermaye + p_hedef > 100000000 then raise exception 'Halka arz sonrası sermaye 100.000.000 ₺''yi aşamaz (en fazla % ₺ toplanabilir)', oyun.tl(100000000 - s.sermaye); end if;
  select * into d from oyun.halka_arz_deger_sinir(s.sermaye, s.sektor);
  if p_deger is null or p_deger <> round(p_deger) or p_deger < d.en_az or p_deger > d.en_cok then
    raise exception 'Şirket değeri % ₺ ile % ₺ arasında olmalı', oyun.tl(d.en_az), oyun.tl(d.en_cok); end if;
  if p_hedef / (p_deger + p_hedef) > .49 then
    raise exception 'Halka arzda şirketin en fazla %%49''u satılabilir. Bu değerle en fazla % ₺ toplayabilirsin', oyun.tl(floor(p_deger * 49 / 51)); end if;
  v_asgari := coalesce(round(p_asgari), round(p_hedef / 2));
  if v_asgari < 10000 or v_asgari > p_hedef then raise exception 'Asgari tutar 10.000 ₺ ile hedef tutar arasında olmalı'; end if;
  if p_saat not in (24, 48, 72) then raise exception 'Talep süresi 24, 48 ya da 72 saat olmalı'; end if;
  update oyun.sirketler set satilik = null where id = s.id;
  insert into oyun.halka_arz(sirket_id, baslatan, deger, hedef, asgari, bas, bit)
    values (s.id, u, p_deger, p_hedef, v_asgari, t, t + make_interval(hours => p_saat)) returning id into v_id;
  perform oyun.olay('ekonomi', format('%s halka arz ediliyor: %s ₺ hedef, şirketin %%%s''i satışta. Talep toplama %s saat sürecek.',
    s.ad, oyun.tl(p_hedef), round(p_hedef / (p_deger + p_hedef) * 100, 2), p_saat), null, null, t);
  return oyun.halka_arz_json((select a from oyun.halka_arz a where a.id = v_id), u);
end $$;

create or replace function public.halka_arz_talep(p_arz bigint, p_tutar numeric)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); a oyun.halka_arz; t timestamptz := oyun.simdi(); v_ad text; v_mevcut numeric;
begin
  if u is null or not exists (select 1 from oyun.profiller where id = u and not yasakli) then raise exception 'Oyuncu hesabı gerekli'; end if;
  perform oyun.halka_arz_tick();
  select * into a from oyun.halka_arz where id = p_arz for update;
  if a.id is null or a.durum <> 'acik' or a.bit <= t then raise exception 'Bu halka arz artık talep toplamıyor'; end if;
  if a.baslatan = u then raise exception 'Kendi başlattığın halka arza talep veremezsin; şirketin tamamı sende ise sermaye artırımını kullan'; end if;
  if p_tutar is null or p_tutar <> round(p_tutar) or p_tutar < 1000 then raise exception 'Talep en az 1.000 ₺ ve tam sayı olmalı'; end if;
  if a.toplanan + p_tutar > a.hedef then raise exception 'Kalan talep miktarı % ₺', oyun.tl(a.hedef - a.toplanan); end if;
  select ad into v_ad from oyun.sirketler where id = a.sirket_id;
  perform oyun.para_islem(u, -p_tutar, 'sirket', format('%s halka arz talebi (emanet)', v_ad), t);
  select tutar into v_mevcut from oyun.halka_arz_talep where arz_id = a.id and user_id = u;
  insert into oyun.halka_arz_talep(arz_id, user_id, tutar, zaman) values (a.id, u, p_tutar, t)
    on conflict (arz_id, user_id) do update set tutar = oyun.halka_arz_talep.tutar + excluded.tutar, zaman = excluded.zaman;
  update oyun.halka_arz set toplanan = toplanan + p_tutar where id = a.id returning * into a;
  if v_mevcut is null then
    perform oyun.bildir(a.baslatan, format('%s halka arzına %s %s ₺ talep verdi (toplanan %s / %s ₺).', v_ad,
      (select kad from oyun.profiller where id = u), oyun.tl(p_tutar), oyun.tl(a.toplanan), oyun.tl(a.hedef)), t);
  end if;
  if a.toplanan >= a.hedef then perform oyun.halka_arz_kapat(a.id, false); end if;
  return oyun.halka_arz_json((select x from oyun.halka_arz x where x.id = a.id), u);
end $$;

create or replace function public.halka_arz_talep_geri(p_arz bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); a oyun.halka_arz; h oyun.halka_arz_talep; t timestamptz := oyun.simdi();
begin
  if u is null then raise exception 'Oturum açmalısın'; end if;
  perform oyun.halka_arz_tick();
  select * into a from oyun.halka_arz where id = p_arz for update;
  if a.id is null or a.durum <> 'acik' then raise exception 'Bu halka arz sonuçlandı; talep geri alınamaz'; end if;
  select * into h from oyun.halka_arz_talep where arz_id = a.id and user_id = u for update;
  if h.id is null then raise exception 'Bu halka arzda talebin yok'; end if;
  delete from oyun.halka_arz_talep where id = h.id;
  update oyun.halka_arz set toplanan = toplanan - h.tutar where id = a.id;
  perform oyun.para_islem(u, h.tutar, 'sirket', format('%s halka arz talebi geri alındı', (select ad from oyun.sirketler where id = a.sirket_id)), t);
  return oyun.halka_arz_json((select x from oyun.halka_arz x where x.id = a.id), u);
end $$;

create or replace function public.halka_arz_iptal(p_arz bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); a oyun.halka_arz;
begin
  if u is null then raise exception 'Oturum açmalısın'; end if;
  select * into a from oyun.halka_arz where id = p_arz;
  if a.id is null or a.durum <> 'acik' then raise exception 'Açık halka arz bulunamadı'; end if;
  if a.baslatan <> u and not exists (select 1 from oyun.sirket_ortaklari where sirket_id = a.sirket_id and user_id = u and pay >= 50) then
    raise exception 'Halka arzı yalnız başlatan ya da şirketin en az %%50 ortağı iptal edebilir'; end if;
  perform oyun.halka_arz_kapat(a.id, true);
  return oyun.halka_arz_json((select x from oyun.halka_arz x where x.id = a.id), u);
end $$;

-- Açık arzlar (herkes) + son sonuçlananlar + benim taleplerim.
create or replace function public.halka_arz_liste()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid();
begin
  if u is null then raise exception 'Oturum açmalısın'; end if;
  perform oyun.halka_arz_tick();
  return jsonb_build_object(
    'acik', coalesce((select jsonb_agg(oyun.halka_arz_json(a, u) order by a.bit) from oyun.halka_arz a where a.durum = 'acik'), '[]'::jsonb),
    'son', coalesce((select jsonb_agg(oyun.halka_arz_json(a, u) order by a.sonuc_zaman desc)
                     from (select * from oyun.halka_arz where durum <> 'acik' order by sonuc_zaman desc limit 10) a), '[]'::jsonb),
    'cuzdan', (select para from oyun.cuzdan where user_id = u));
end $$;

-- Bir şirketin halka arz durumu (şirket ekranı için).
create or replace function public.halka_arz_durum(p_sirket bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); s oyun.sirketler; d record;
begin
  if u is null then raise exception 'Oturum açmalısın'; end if;
  perform oyun.halka_arz_tick();
  select * into s from oyun.sirketler where id = p_sirket and aktif;
  if s.id is null then raise exception 'Şirket bulunamadı'; end if;
  select * into d from oyun.halka_arz_deger_sinir(s.sermaye, s.sektor);
  return jsonb_build_object(
    'id', s.id, 'ad', s.ad, 'sektor', s.sektor, 'sermaye', s.sermaye, 'kasa', s.kasa, 'halka_acik', s.halka_acik,
    'payim', coalesce((select pay from oyun.sirket_ortaklari where sirket_id = s.id and user_id = u), 0),
    'asgari_ucret', (select asgari from oyun.ulke where id = 1),
    'ort_net', oyun.sirket_ort_net(s.sermaye, s.sektor),
    'deger_en_az', d.en_az, 'deger_en_cok', d.en_cok, 'deger_onerilen', d.onerilen,
    'en_fazla_tutar', least(100000000 - s.sermaye, floor(d.en_cok * 49 / 51)),
    'acik', (select oyun.halka_arz_json(a, u) from oyun.halka_arz a where a.sirket_id = s.id and a.durum = 'acik'),
    'gecmis', coalesce((select jsonb_agg(oyun.halka_arz_json(a, u) order by a.bas desc)
                        from (select * from oyun.halka_arz where sirket_id = s.id and durum <> 'acik' order by bas desc limit 5) a), '[]'::jsonb));
end $$;

revoke all on function oyun.sirket_ort_net(numeric, text), oyun.halka_arz_deger_sinir(numeric, text), oyun.halka_arz_kapat(bigint, boolean),
  oyun.halka_arz_tick(), oyun.halka_arz_json(oyun.halka_arz, uuid) from public, anon, authenticated;
revoke all on function public.halka_arz_hesapla(bigint, numeric, numeric), public.halka_arz_baslat(bigint, numeric, numeric, numeric, int),
  public.halka_arz_talep(bigint, numeric), public.halka_arz_talep_geri(bigint), public.halka_arz_iptal(bigint),
  public.halka_arz_liste(), public.halka_arz_durum(bigint) from public, anon;
grant execute on function public.halka_arz_hesapla(bigint, numeric, numeric), public.halka_arz_baslat(bigint, numeric, numeric, numeric, int),
  public.halka_arz_talep(bigint, numeric), public.halka_arz_talep_geri(bigint), public.halka_arz_iptal(bigint),
  public.halka_arz_liste(), public.halka_arz_durum(bigint) to authenticated;
-- 2026-10-10: Görev kataloğu ve doğrulanmış oyun para ödülleri
-- Görevler yalnızca oyun sunucusundaki kayıtlarla tamamlanabilir.
create table if not exists oyun.gorev_ayar(
 id integer primary key check (id=1),
 baslangic timestamptz not null default now()
);
insert into oyun.gorev_ayar(id) values(1) on conflict(id) do nothing;
create table if not exists oyun.gorev_katalog(
 id bigint generated always as identity primary key,
 kod text not null unique,
 kategori text not null,
 baslik text not null,
 aciklama text not null,
 metrik text not null,
 hedef integer not null check(hedef>0),
 odul integer not null check(odul between 50 and 3000),
 donem text not null check(donem in ('tek','gunluk','haftalik')),
 seviye smallint not null default 0,
 rota text not null,
 aktif boolean not null default true
);
create table if not exists oyun.gorev_oduller(
 id bigint generated always as identity primary key,
 user_id uuid not null references oyun.profiller(id) on delete cascade,
 gorev_id bigint not null references oyun.gorev_katalog(id),
 donem_anahtari text not null,
 odul integer not null check(odul>=0),
 zaman timestamptz not null default now(),
 unique(user_id,gorev_id,donem_anahtari)
);
create index if not exists gorev_oduller_user_zaman on oyun.gorev_oduller(user_id,zaman desc);
do $$ declare n text;begin
 foreach n in array array['gorev_ayar','gorev_katalog','gorev_oduller'] loop
  execute format('alter table oyun.%I enable row level security',n);
  execute format('revoke all on oyun.%I from public,anon,authenticated',n);
 end loop;
end $$;

create or replace function oyun.gorev_istatistik(p_user uuid,p_bas timestamptz)
returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object(
  'sohbet_gun', coalesce((select count(distinct (m.zaman at time zone 'Europe/Istanbul')::date) from oyun.mesajlar m where m.user_id=p_user and m.zaman>=p_bas and not m.gizli and m.kanal not like 'dernek:%' and m.kanal not like 'ozel:%' and char_length(m.metin)>=15),0),
  'sohbet_mesaj', coalesce((select count(*) from oyun.mesajlar m where m.user_id=p_user and m.zaman>=p_bas and not m.gizli and m.kanal not like 'dernek:%' and m.kanal not like 'ozel:%' and char_length(m.metin)>=30),0),
  'sohbet_kanal', coalesce((select count(distinct m.kanal) from oyun.mesajlar m where m.user_id=p_user and m.zaman>=p_bas and not m.gizli and m.kanal not like 'dernek:%' and m.kanal not like 'ozel:%' and char_length(m.metin)>=15),0),
  'dernek_sohbet_gun', coalesce((select count(distinct (m.zaman at time zone 'Europe/Istanbul')::date) from oyun.mesajlar m where m.user_id=p_user and m.zaman>=p_bas and not m.gizli and m.kanal like 'dernek:%' and char_length(m.metin)>=15),0),
  'dernek_sohbet_yazi', coalesce((select count(*) from oyun.mesajlar m where m.user_id=p_user and m.zaman>=p_bas and not m.gizli and m.kanal like 'dernek:%' and char_length(m.metin)>=30),0),
  'secim_oy', coalesce((select count(*) from oyun.oylar o where o.secmen=p_user and o.zaman>=p_bas),0),
  'secim_turleri', coalesce((select count(distinct s.tur) from oyun.oylar o join oyun.secimler s on s.id=o.secim_id where o.secmen=p_user and o.zaman>=p_bas),0),
  'aday_ol', coalesce((select count(*) from oyun.adaylar a where a.user_id=p_user and a.basvuru_at>=p_bas),0),
  'miting_katil', coalesce((select count(*) from oyun.miting_katilim x where x.user_id=p_user and x.zaman>=p_bas),0),
  'miting_il', coalesce((select count(distinct m.il_id) from oyun.miting_katilim x join oyun.mitingler m on m.id=x.miting_id where x.user_id=p_user and x.zaman>=p_bas),0),
  'miting_konus', coalesce((select count(*) from oyun.miting_konusma k where k.user_id=p_user and k.zaman>=p_bas and not k.silindi and char_length(k.metin)>=30),0),
  'miting_konus_gun', coalesce((select count(distinct (k.zaman at time zone 'Europe/Istanbul')::date) from oyun.miting_konusma k where k.user_id=p_user and k.zaman>=p_bas and not k.silindi and char_length(k.metin)>=30),0),
  'miting_duzen', coalesce((select count(*) from oyun.mitingler m where m.user_id=p_user and m.olusturma>=p_bas),0),
  'gazete_haber', coalesce((select count(*) from oyun.gazete_yayinlari y where y.yazar=p_user and y.zaman>=p_bas and y.tur='haber' and char_length(y.metin)>=50),0),
  'gazete_kose', coalesce((select count(*) from oyun.gazete_yayinlari y where y.yazar=p_user and y.zaman>=p_bas and y.tur='kose' and char_length(y.metin)>=50),0),
  'gazete_yayin_gun', coalesce((select count(distinct (y.zaman at time zone 'Europe/Istanbul')::date) from oyun.gazete_yayinlari y where y.yazar=p_user and y.zaman>=p_bas and char_length(y.metin)>=50),0),
  'gazete_yorum', coalesce((select count(distinct k.yayin_id) from oyun.gazete_kose_yorum k where k.user_id=p_user and k.zaman>=p_bas and not k.silindi and char_length(k.metin)>=15),0),
  'gazeteler_yayin', coalesce((select count(distinct y.gazete_id) from oyun.gazete_yayinlari y where y.yazar=p_user and y.zaman>=p_bas and char_length(y.metin)>=50),0),
  'roportaj_davet', coalesce((select count(*) from oyun.sos_roportaj r where r.gazeteci=p_user and r.acilis>=p_bas and r.konuk<>p_user),0),
  'roportaj_yayin', coalesce((select count(*) from oyun.sos_roportaj r join oyun.gazete_yayinlari y on y.id=r.yayin_id where r.gazeteci=p_user and r.durum='yayinlandi' and y.zaman>=p_bas),0),
  'roportaj_cevap', coalesce((select count(*) from oyun.sos_roportaj r where r.konuk=p_user and r.yanit_at>=p_bas and r.yanit is not null),0),
  'haber_cevap', coalesce((select count(*) from oyun.sos_haber_cevap h where h.oyuncu_id=p_user and h.zaman>=p_bas and h.metin is not null),0),
  'duello_davet', coalesce((select count(*) from oyun.sos_duello d where d.davet_eden=p_user and d.olusturma>=p_bas),0),
  'duello_konus', coalesce((select count(*) from oyun.sos_duello_soz s where s.konusan=p_user and s.zaman>=p_bas and char_length(s.metin)>=20),0),
  'duello_oy', coalesce((select count(*) from oyun.sos_duello_oy o where o.user_id=p_user and o.zaman>=p_bas),0),
  'duello_tamam', coalesce((select count(*) from oyun.sos_duello d where (d.davet_eden=p_user or d.davet_edilen=p_user) and d.durum='bitti' and d.bitti_at>=p_bas),0),
  'imza_baslat', coalesce((select count(*) from oyun.sos_imza_kamp c where c.acan=p_user and c.bas>=p_bas),0),
  'imza_kat', coalesce((select count(*) from oyun.sos_imza i join oyun.sos_imza_kamp c on c.id=i.kampanya_id where i.user_id=p_user and c.acan<>p_user and i.zaman>=p_bas),0),
  'imza_basari', coalesce((select count(*) from oyun.sos_imza_kamp c where c.acan=p_user and c.durum='basarili' and c.bas>=p_bas),0),
  'dilekce_gonder', coalesce((select count(*) from oyun.sos_dilekce d where d.gonderen=p_user and d.olusturma>=p_bas and d.imza_kamp_id is null),0),
  'dilekce_yanit', coalesce((select count(*) from oyun.sos_dilekce d where d.muhatap=p_user and d.cevap_at>=p_bas and d.cevap is not null),0),
  'dernek_uye', coalesce((select count(distinct x.dernek_id) from oyun.dernek_uyeler x where x.user_id=p_user and x.katilim>=p_bas),0),
  'dernek_eylem', coalesce((select count(*) from oyun.dernek_eylem x where x.yazan=p_user and x.zaman>=p_bas and not x.silindi),0),
  'dernek_eylem_tur', coalesce((select count(distinct x.tur) from oyun.dernek_eylem x where x.yazan=p_user and x.zaman>=p_bas and not x.silindi),0),
  'dernek_protesto_katil', coalesce((select count(*) from oyun.dernek_protesto_katilim x join oyun.dernek_eylem e on e.id=x.eylem_id where x.user_id=p_user and x.zaman>=p_bas and not e.silindi),0),
  'dernek_sube', coalesce((select count(*) from oyun.dernek_sube x where x.kuran=p_user and x.kurulus>=p_bas),0),
  'dernek_secim_oy', coalesce((select count(distinct x.secim_id) from oyun.sos_dernek_oy x join oyun.sos_dernek_secim s on s.id=x.secim_id where x.user_id=p_user and s.bas>=p_bas),0),
  'parti_kurultay_imza', coalesce((select count(*) from oyun.sos_parti_imzaci x join oyun.sos_parti_imza k on k.id=x.kampanya_id where x.user_id=p_user and k.bas>=p_bas),0),
  'sirket_kur', coalesce((select count(*) from oyun.sirketler s where s.kurucu=p_user and s.kurulus>=p_bas),0),
  'sirket_ortak', coalesce((select count(*) from oyun.sirket_ortaklari x where x.user_id=p_user),0),
  'emlak_sahip', coalesce((select count(*) from oyun.yatirim_mulkleri x where x.user_id=p_user),0),
  'emlak_il', coalesce((select count(distinct x.il_id) from oyun.yatirim_mulkleri x where x.user_id=p_user),0),
  'kanun_teklif', coalesce((select count(*) from oyun.kanunlar k where k.teklif_eden=p_user and k.teklif_at>=p_bas),0),
  'kanun_oy', coalesce((select count(*) from oyun.kanun_oylari k where k.vekil=p_user and k.zaman>=p_bas),0),
  'bakan_soru', coalesce((select count(*) from oyun.bakan_soru s where s.soran=p_user and s.zaman>=p_bas),0),
  'bakan_yanit', coalesce((select count(*) from oyun.bakan_soru s where s.yanitlayan=p_user and s.yanit_at>=p_bas),0),
  'anket_oy', coalesce((select count(*) from oyun.haftalik_anket_oy a where a.user_id=p_user and a.zaman>=p_bas),0),
  'parti_tuzuk_oy', coalesce((select count(*) from oyun.parti_tuzuk_oylari v where v.user_id=p_user and v.zaman>=p_bas),0),
  'yayin_yap', coalesce((select count(*) from oyun.yayinlar y where y.gonderen=p_user and y.zaman>=p_bas and not y.gizli and char_length(y.metin)>=30),0),
  'gazete_kur', coalesce((select count(*) from oyun.oyuncu_gazeteleri g where g.sahip=p_user and g.kurulus>=p_bas),0)
 );
$$;
revoke all on function oyun.gorev_istatistik(uuid,timestamptz) from public,anon,authenticated;

create or replace function public.gorevlerim()
returns jsonb language plpgsql security definer set search_path='' as $$
declare p oyun.profiller:=oyun.profilim(); t timestamptz:=oyun.simdi();
 bas timestamptz; d_bas timestamptz; w_bas timestamptz;
 bir jsonb; gun jsonb; hafta jsonb;
 gun_k text; hafta_k text; toplam numeric;
begin
 select baslangic into bas from oyun.gorev_ayar where id=1;
 d_bas:=date_trunc('day',t at time zone 'Europe/Istanbul') at time zone 'Europe/Istanbul';
 w_bas:=date_trunc('week',t at time zone 'Europe/Istanbul') at time zone 'Europe/Istanbul';
 gun_k:=to_char(t at time zone 'Europe/Istanbul','YYYY-MM-DD');
 hafta_k:=to_char(t at time zone 'Europe/Istanbul','IYYY-"W"IW');
 bir:=oyun.gorev_istatistik(p.id,bas);
 gun:=oyun.gorev_istatistik(p.id,greatest(d_bas,bas));
 hafta:=oyun.gorev_istatistik(p.id,greatest(w_bas,bas));
 select coalesce(sum(odul),0) into toplam from oyun.gorev_oduller where user_id=p.id and zaman>=d_bas;
 return jsonb_build_object(
  'gunluk_limit',10000,'bugun_kazanilan',toplam,
  'baslangic',bas,
  'gorevler',coalesce((
  select jsonb_agg(jsonb_build_object(
   'id',c.id,'kod',c.kod,'kategori',c.kategori,'baslik',c.baslik,'aciklama',c.aciklama,
   'hedef',c.hedef,'ilerleme',least(c.hedef,greatest(0,coalesce((case c.donem when 'gunluk' then gun when 'haftalik' then hafta else bir end->>c.metrik)::int,0))),
   'odul',c.odul,'donem',c.donem,'seviye',c.seviye,'rota',c.rota,
   'alindi',exists(select 1 from oyun.gorev_oduller o where o.gorev_id=c.id and o.user_id=p.id and o.donem_anahtari=
    case c.donem when 'gunluk' then gun_k when 'haftalik' then hafta_k else 'tek' end)
  ) order by case c.donem when 'gunluk' then 0 when 'haftalik' then 1 else 2 end,c.kategori,c.seviye,c.id)
  from oyun.gorev_katalog c where c.aktif),'[]'::jsonb)
 );
end $$;

create or replace function public.gorev_odul_al(p_gorev bigint)
returns jsonb language plpgsql security definer set search_path='' as $$
declare p oyun.profiller:=oyun.profilim(); t timestamptz:=oyun.simdi(); c oyun.gorev_katalog; v_bas timestamptz; p_bas timestamptz;
 k text; done integer; toplam numeric; d_bas timestamptz;
begin
 -- Aynı oyuncunun eşzamanlı istekleri arasında çift ödül engeli.
 perform pg_advisory_xact_lock(91720,hashtext(p.id::text));
 select * into c from oyun.gorev_katalog where id=p_gorev and aktif;
 if c.id is null then raise exception 'Görev bulunamadı.'; end if;
 select baslangic into v_bas from oyun.gorev_ayar where id=1;
 d_bas:=date_trunc('day',t at time zone 'Europe/Istanbul') at time zone 'Europe/Istanbul';
 k:=case c.donem when 'gunluk' then to_char(t at time zone 'Europe/Istanbul','YYYY-MM-DD')
 when 'haftalik' then to_char(t at time zone 'Europe/Istanbul','IYYY-"W"IW') else 'tek' end;
 if exists(select 1 from oyun.gorev_oduller where user_id=p.id and gorev_id=c.id and donem_anahtari=k)
 then raise exception 'Bu görevin ödülünü zaten aldın.'; end if;
 p_bas:=case c.donem when 'gunluk' then greatest(d_bas,v_bas)
 when 'haftalik' then greatest(date_trunc('week',t at time zone 'Europe/Istanbul') at time zone 'Europe/Istanbul',v_bas)
 else v_bas end;
 done:=coalesce((oyun.gorev_istatistik(p.id,p_bas)->>c.metrik)::int,0);
 if done<c.hedef then raise exception 'Görev tamamlanmadı: % / % ilerleme.',done,c.hedef; end if;
 select coalesce(sum(odul),0) into toplam from oyun.gorev_oduller where user_id=p.id and zaman>=d_bas;
 if toplam+c.odul>10000 then raise exception 'Günlük görev ödülü limiti 10.000 TL. Yarın tekrar dene.'; end if;
 insert into oyun.gorev_oduller(user_id,gorev_id,donem_anahtari,odul,zaman) values(p.id,c.id,k,c.odul,t);
 perform oyun.para_islem(p.id,c.odul,'gorev',format('Görev ödülü: %s',c.baslik),t);
 return jsonb_build_object('tamam',true,'odul',c.odul,'gorev',c.baslik,'bugun_kazanilan',toplam+c.odul);
end $$;

revoke all on function public.gorevlerim(),public.gorev_odul_al(bigint) from public,anon;
grant execute on function public.gorevlerim(),public.gorev_odul_al(bigint) to authenticated;

