-- ---------------------------------------------------------------- karne
-- Büyük ilin aynı puan için daha çok yatırıma ihtiyacı var.
create or replace function oyun.belediye_olcek(p_il smallint) returns numeric
language sql stable set search_path = '' as $$
  select greatest(0.7, least(2.2, sqrt(greatest(1, i.mv)::numeric / 7.4))) from oyun.iller i where i.id = p_il
$$;

create or replace function oyun.belediye_karne_katki(p_il smallint)
returns table(alan text, kaynak text, puan numeric)
language sql stable set search_path = '' as $$
  with t as (select oyun.simdi() s)
  select m.alan, k.ad || ' · ' || b.seviye || '. seviye',
         m.puan * (case b.seviye when 1 then 1 when 2 then 1.6 else 2.1 end)
    from oyun.belediye_bina b join oyun.belediye_bina_katalog k on k.kod = b.kod
    join oyun.belediye_karne_harita m on m.kaynak = 'bina:' || b.kod
   where b.il_id = p_il and b.durum = 'aktif' and b.seviye > 0
  union all
  select m.alan, bh.ad, m.puan
    from oyun.il_hizmet h join oyun.belediye_hizmetleri bh on bh.kod = h.kod
    join oyun.belediye_karne_harita m on m.kaynak = 'hizmet:' || h.kod
   where h.il_id = p_il
  union all
  select m.alan, k.ad || ' (program)',
         m.puan * greatest(0, 1 - extract(epoch from (t.s - x.zaman)) / (7 * 86400.0))
    from oyun.belediye_ekonomi_karar x join oyun.belediye_ekonomi_katalog k on k.kod = x.kod
    join oyun.belediye_karne_harita m on m.kaynak = 'program:' || x.kod, t
   where x.il_id = p_il and x.zaman > t.s - interval '7 days'
  union all
  select m.alan, y.ad,
         case when x.kod = 'rayli' then m.puan
              else m.puan * greatest(0, 1 - extract(epoch from (t.s - x.zaman)) / (30 * 86400.0)) end
    from (select kod, zaman, row_number() over (partition by kod order by zaman desc) n
            from oyun.belediye_proje_kayit where il_id = p_il) x
    join oyun.belediye_yatirimlari y on y.kod = x.kod
    join oyun.belediye_karne_harita m on m.kaynak = 'yatirim:' || x.kod, t
   where (x.kod = 'rayli' and x.n <= 2) or (x.kod <> 'rayli' and x.zaman > t.s - interval '30 days')
  union all
  select e.alan, e.kaynak, e.puan from oyun.belediye_karne_etki e, t
   where e.il_id = p_il and e.bitis > t.s
$$;

create or replace function oyun.belediye_karne(p_il smallint) returns jsonb
language plpgsql stable set search_path = '' as $$
declare taban numeric; olcek numeric; sonuc jsonb; ort numeric;
begin
  select 30 + 0.3 * coalesce(d.gelisim, 50) into taban from oyun.il_durum d where d.il_id = p_il;
  olcek := oyun.belediye_olcek(p_il);
  with k as (select * from oyun.belediye_karne_katki(p_il)),
  a as (
    select al.kod, al.ad, al.aciklama, al.sira,
           round(oyun.sinir(coalesce(taban, 45) + coalesce((select sum(k.puan) from k where k.alan = al.kod), 0) / olcek, 0, 100), 1) puan,
           coalesce((select jsonb_agg(jsonb_build_object('kaynak', z.kaynak, 'puan', round(z.p / olcek, 1)) order by abs(z.p) desc)
                       from (select k.kaynak, sum(k.puan) p from k where k.alan = al.kod group by k.kaynak
                             order by abs(sum(k.puan)) desc limit 6) z), '[]'::jsonb) katkilar
      from oyun.belediye_karne_alan al)
  select jsonb_agg(jsonb_build_object('kod', kod, 'ad', ad, 'aciklama', aciklama, 'puan', puan, 'katkilar', katkilar) order by sira),
         round(avg(puan), 1)
    into sonuc, ort from a;
  return jsonb_build_object('alanlar', coalesce(sonuc, '[]'::jsonb), 'ortalama', ort,
                            'taban', round(coalesce(taban, 45), 1), 'olcek', round(olcek, 2));
end $$;

create or replace function oyun.belediye_karne_ort(p_il smallint) returns numeric
language sql stable set search_path = '' as $$
  select coalesce((oyun.belediye_karne(p_il)->>'ortalama')::numeric, 45)
$$;

-- ---------------------------------------------------------------- kredi
create or replace function oyun.belediye_kredi_faiz(p_gun int) returns numeric
language sql stable set search_path = '' as $$
  -- dönemin tamamı için: aylık (enflasyon/12 + 1) puan, güne oranlanır
  select round(((coalesce(u.enflasyon, 30) / 12 + 1) / 100) * p_gun / 30.0, 4) from oyun.ulke u where u.id = 1
$$;

create or replace function oyun.belediye_kredi_limit(p_il smallint) returns numeric
language sql stable set search_path = '' as $$
  select round(greatest(0, 20 * oyun.il_gelir(p_il)
           - coalesce((select sum(kalan) from oyun.belediye_borc where il_id = p_il and durum = 'aktif'), 0)), 4)
$$;

create or replace function public.belediye_kredi_al(p_tutar numeric, p_gun int)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); m oyun.makamlar := oyun.baskan_zorunlu(p);
  t timestamptz := oyun.simdi(); lim numeric; f numeric; toplam numeric; yid bigint; ilad text;
begin
  if p_gun is null or p_gun not in (10, 20, 30) then raise exception 'Vade 10, 20 ya da 30 gün olabilir'; end if;
  if p_tutar is null or p_tutar < 0.01 then raise exception 'Kredi en az 0,01 milyar ₺ (10 milyon ₺) olmalı'; end if;
  p_tutar := round(p_tutar, 4);
  perform pg_advisory_xact_lock(772922, m.il_id::integer);
  if (select count(*) from oyun.belediye_borc where il_id = m.il_id and durum = 'aktif') >= 3 then
    raise exception 'Aynı anda en fazla 3 kredi kullanılabilir'; end if;
  if exists (select 1 from oyun.belediye_borc where il_id = m.il_id and baslangic > t - interval '24 hours') then
    raise exception 'İller Bankası 24 saatte bir kredi verir'; end if;
  if exists (select 1 from oyun.belediye_borc where il_id = m.il_id and durum = 'aktif' and gecikme >= 3) then
    raise exception 'Gecikmedeki taksitler ödenmeden yeni kredi verilmez'; end if;
  lim := oyun.belediye_kredi_limit(m.il_id);
  if p_tutar > lim then
    raise exception 'Kredi limiti: % milyar ₺ (20 günlük gelirden mevcut borç düşülür)', to_char(lim, 'FM999990.0000'); end if;
  f := oyun.belediye_kredi_faiz(p_gun);
  toplam := round(p_tutar * (1 + f), 6);
  insert into oyun.belediye_borc(il_id, baskan, anapara, toplam, kalan, taksit, gun, faiz, baslangic, son_odeme)
  values (m.il_id, p.id, p_tutar, toplam, toplam, round(toplam / p_gun, 6), p_gun, f, t, (t at time zone 'Europe/Istanbul')::date)
  returning id into yid;
  update oyun.il_durum set kasa = kasa + p_tutar where il_id = m.il_id;
  insert into oyun.belediye_sehir_hareket(il_id, tur, tutar, aciklama, zaman)
  values (m.il_id, 'kredi', p_tutar, format('İller Bankası kredisi · %s gün · geri ödeme %s milyar ₺', p_gun, to_char(toplam, 'FM999990.0000')), t);
  select ad into ilad from oyun.iller where id = m.il_id;
  perform oyun.olay('belediye', format('%s Belediyesi İller Bankası''ndan %s milyar ₺ kredi çekti (%s gün vadeli).',
                    ilad, to_char(p_tutar, 'FM999990.00##'), p_gun), m.il_id, p.parti_id, t);
  return jsonb_build_object('tamam', true, 'id', yid, 'anapara', p_tutar, 'toplam', toplam,
                            'taksit', round(toplam / p_gun, 6), 'faiz', f);
end $$;

create or replace function public.belediye_kredi_kapat(p_id bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); m oyun.makamlar := oyun.baskan_zorunlu(p);
  b oyun.belediye_borc; t timestamptz := oyun.simdi(); v_kasa numeric;
begin
  perform pg_advisory_xact_lock(772922, m.il_id::integer);
  select * into b from oyun.belediye_borc where id = p_id and il_id = m.il_id and durum = 'aktif' for update;
  if b.id is null then raise exception 'Kapatılacak kredi bulunamadı'; end if;
  select kasa into v_kasa from oyun.il_durum where il_id = m.il_id for update;
  if v_kasa < b.kalan then
    raise exception 'Kasa yetersiz: kalan borç % milyar ₺', to_char(b.kalan, 'FM999990.0000'); end if;
  update oyun.il_durum set kasa = kasa - b.kalan where il_id = m.il_id;
  update oyun.belediye_borc set kalan = 0, durum = 'kapandi', kapanis = t where id = b.id;
  insert into oyun.belediye_sehir_hareket(il_id, tur, tutar, aciklama, zaman)
  values (m.il_id, 'kredi_kapama', -b.kalan, 'İller Bankası kredisi erken kapatıldı', t);
  return jsonb_build_object('tamam', true, 'odenen', b.kalan);
end $$;

-- ---------------------------------------------------------------- kriz masası
create or replace function oyun.belediye_kriz_etki(p_il smallint, p_etki jsonb, p_kaynak text, p_t timestamptz)
returns void language plpgsql set search_path = '' as $$
declare k text; v text;
begin
  for k, v in select * from jsonb_each_text(coalesce(p_etki, '{}'::jsonb)) loop
    if exists (select 1 from oyun.belediye_karne_alan where kod = k) and v::numeric <> 0 then
      insert into oyun.belediye_karne_etki(il_id, alan, puan, kaynak, bitis)
      values (p_il, k, v::numeric, left(p_kaynak, 120), p_t + interval '14 days');
    end if;
  end loop;
end $$;

create or replace function oyun.belediye_kriz_baslat(p_il smallint, p_kod text default null)
returns bigint language plpgsql set search_path = '' as $$
declare t timestamptz := oyun.simdi(); ay int := extract(month from (oyun.simdi() at time zone 'Europe/Istanbul'));
  v_kod text := p_kod; k oyun.belediye_kriz_katalog; bas uuid; ilad text; yid bigint;
begin
  select user_id into bas from oyun.makamlar where tur = 'bel' and il_id = p_il and bit is null order by id desc limit 1;
  if bas is null or exists (select 1 from oyun.belediye_kriz where il_id = p_il and durum = 'acik') then return null; end if;
  if v_kod is null then
    select c.kod into v_kod from oyun.belediye_kriz_katalog c
     where (c.aylar is null or ay = any(c.aylar))
       and c.kod not in (select x.kod from oyun.belediye_kriz x where x.il_id = p_il order by x.id desc limit 4)
     order by -ln(greatest(random(), 1e-9)) / c.agirlik limit 1;
  end if;
  select * into k from oyun.belediye_kriz_katalog where kod = v_kod;
  if k.kod is null then return null; end if;
  insert into oyun.belediye_kriz(il_id, kod, baskan, baslangic, son)
  values (p_il, k.kod, bas, t, t + interval '24 hours') returning id into yid;
  select ad into ilad from oyun.iller where id = p_il;
  perform oyun.bildir(bas, format('Kriz masası: %s. 24 saat içinde karar ver (Yönetim › Belediye › Kriz masası).', k.baslik), t);
  perform oyun.olay('belediye', format('%s''da kriz: %s. Gözler belediye başkanında.', ilad, k.baslik), p_il, null, t);
  return yid;
end $$;

create or replace function oyun.belediye_kriz_uygula(p_kriz bigint, p_secim text, p_t timestamptz)
returns jsonb language plpgsql set search_path = '' as $$
declare x oyun.belediye_kriz; k oyun.belediye_kriz_katalog; s jsonb; v_maliyet numeric := 0; basarili boolean := true;
  mem numeric; gel numeric; etki jsonb; metin text; ilad text; v_durum text; secad text; bkad text;
begin
  select * into x from oyun.belediye_kriz where id = p_kriz and durum = 'acik' for update;
  if x.id is null then raise exception 'Bu kriz kapanmış'; end if;
  select * into k from oyun.belediye_kriz_katalog where kod = x.kod;
  select ad into ilad from oyun.iller where id = x.il_id;
  if p_secim is null then
    v_durum := 'sessiz'; s := k.sessiz; mem := coalesce((s->>'mem')::numeric, 0); gel := 0;
    etki := s->'etki'; metin := s->>'metin'; secad := 'Karar verilmedi';
  else
    select e into s from jsonb_array_elements(k.secenekler) e where e->>'k' = p_secim;
    if s is null then raise exception 'Geçersiz seçenek'; end if;
    v_durum := 'cozuldu'; secad := s->>'ad';
    v_maliyet := round(coalesce((s->>'gun')::numeric, 0) * oyun.il_gelir(x.il_id), 6);
    if v_maliyet > 0 and (select kasa from oyun.il_durum where il_id = x.il_id) < v_maliyet then
      raise exception 'Belediye kasası yetersiz: % milyar ₺ gerekli. İller Bankası''ndan kredi çekebilirsin.',
        to_char(v_maliyet, 'FM999990.0000'); end if;
    basarili := random() < coalesce((s->>'sans')::numeric, 1);
    if basarili then
      mem := coalesce((s->>'mem')::numeric, 0); gel := coalesce((s->>'gel')::numeric, 0); etki := s->'etki';
      metin := format('%s: %s', ilad, s->>'ad');
    else
      mem := coalesce((s->'basarisiz'->>'mem')::numeric, 0); gel := 0; etki := s->'basarisiz'->'etki';
      metin := format('%s: %s', ilad, s->'basarisiz'->>'metin');
    end if;
  end if;
  update oyun.il_durum set kasa = kasa - v_maliyet,
         memnuniyet = oyun.sinir(memnuniyet + mem, 0, 100), gelisim = oyun.sinir(gelisim + gel, 0, 100)
   where il_id = x.il_id;
  perform oyun.belediye_kriz_etki(x.il_id, etki, k.baslik, p_t);
  if v_maliyet <> 0 then
    insert into oyun.belediye_sehir_hareket(il_id, tur, tutar, aciklama, zaman)
    values (x.il_id, 'kriz', -v_maliyet, left(k.baslik || ' · ' || secad, 170), p_t);
  end if;
  update oyun.belediye_kriz set durum = v_durum, secim = p_secim, maliyet = v_maliyet,
         sonuc = case when v_durum = 'sessiz' then metin when basarili then 'Başarılı' else s->'basarisiz'->>'metin' end,
         karar_zamani = p_t
   where id = x.id;
  select kad into bkad from oyun.profiller where id = x.baskan;
  perform oyun.olay('belediye',
    case when v_durum = 'sessiz' then format('%s: %s — %s', ilad, k.baslik, metin)
         else format('%s Belediye Başkanı %s, %s krizinde kararını verdi: %s.%s', ilad, coalesce(bkad, ''), lower(k.baslik), secad,
                     case when basarili then '' else ' Ancak sonuç beklendiği gibi olmadı.' end) end,
    x.il_id, (select parti_id from oyun.profiller where id = x.baskan), p_t);
  if v_durum = 'sessiz' and x.baskan is not null then
    perform oyun.bildir(x.baskan, format('Kriz masası: %s için 24 saatte karar vermedin. %s', k.baslik, metin), p_t);
  end if;
  return jsonb_build_object('tamam', true, 'durum', v_durum, 'basarili', basarili, 'maliyet', v_maliyet,
                            'memnuniyet', mem, 'sonuc', metin);
end $$;

create or replace function oyun.belediye_kriz_tick(p_olasilik numeric default 0.06)
returns integer language plpgsql set search_path = '' as $$
declare t timestamptz := oyun.simdi(); r record; n int := 0;
begin
  if not pg_try_advisory_xact_lock(772923, 1) then return 0; end if;
  for r in select id from oyun.belediye_kriz where durum = 'acik' and son <= t order by id loop
    perform oyun.belediye_kriz_uygula(r.id, null, t); n := n + 1;
  end loop;
  -- Görevde başkan yoksa açık kriz yöneticisiz kalmasın: başkanı düşen ilin krizi kapanır.
  update oyun.belediye_kriz k set durum = 'sessiz', sonuc = 'Başkanlık boşaldı', karar_zamani = t
   where k.durum = 'acik' and not exists (select 1 from oyun.makamlar m where m.tur = 'bel' and m.il_id = k.il_id and m.bit is null);
  for r in select m.il_id from oyun.makamlar m
            where m.tur = 'bel' and m.bit is null
              and not exists (select 1 from oyun.belediye_kriz k where k.il_id = m.il_id
                                and (k.durum = 'acik' or k.baslangic > t - interval '36 hours'))
              and random() < p_olasilik loop
    if oyun.belediye_kriz_baslat(r.il_id) is not null then n := n + 1; end if;
  end loop;
  return n;
end $$;

create or replace function public.belediye_kriz_karar(p_id bigint, p_secim text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); m oyun.makamlar := oyun.baskan_zorunlu(p);
  t timestamptz := oyun.simdi();
begin
  if p_secim is null or btrim(p_secim) = '' then raise exception 'Bir seçenek seç'; end if;
  perform pg_advisory_xact_lock(772922, m.il_id::integer);
  if not exists (select 1 from oyun.belediye_kriz where id = p_id and il_id = m.il_id and durum = 'acik' and son > t) then
    raise exception 'Bu kriz için karar süresi doldu ya da kriz senin ilinde değil'; end if;
  return oyun.belediye_kriz_uygula(p_id, p_secim, t);
end $$;

-- ---------------------------------------------------------------- paneller
create or replace function oyun.belediye_kriz_json(x oyun.belediye_kriz) returns jsonb
language sql stable set search_path = '' as $$
  select jsonb_build_object('id', x.id, 'kod', x.kod, 'baslik', k.baslik, 'metin', k.metin,
    'baslangic', x.baslangic, 'son', x.son, 'durum', x.durum, 'secim', x.secim, 'maliyet', x.maliyet,
    'sonuc', x.sonuc, 'karar_zamani', x.karar_zamani,
    'secim_ad', (select e->>'ad' from jsonb_array_elements(k.secenekler) e where e->>'k' = x.secim),
    'secenekler', (select jsonb_agg(e || jsonb_build_object('maliyet', round(coalesce((e->>'gun')::numeric, 0) * oyun.il_gelir(x.il_id), 6)))
                     from jsonb_array_elements(k.secenekler) e))
  from oyun.belediye_kriz_katalog k where k.kod = x.kod
$$;

create or replace function public.belediye_detay_paneli()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); m oyun.makamlar; d oyun.il_durum;
begin
  select * into m from oyun.makamlar where user_id = p.id and tur = 'bel' and bit is null order by id desc limit 1;
  if m.id is null then return null; end if;
  select * into d from oyun.il_durum where il_id = m.il_id;
  return jsonb_build_object(
    'il_id', m.il_id, 'il_ad', (select ad from oyun.iller where id = m.il_id),
    'kasa', d.kasa, 'memnuniyet', d.memnuniyet, 'gelisim', d.gelisim,
    'gunluk_gelir', oyun.il_gelir(m.il_id), 'gunluk_gider', oyun.il_gider(m.il_id),
    'tl_milyar', oyun.pazar_tl_milyar(),
    'karne', oyun.belediye_karne(m.il_id),
    'kredi', jsonb_build_object(
       'limit', oyun.belediye_kredi_limit(m.il_id),
       'faiz', jsonb_build_object('10', oyun.belediye_kredi_faiz(10), '20', oyun.belediye_kredi_faiz(20), '30', oyun.belediye_kredi_faiz(30)),
       'son_kredi', (select max(baslangic) from oyun.belediye_borc where il_id = m.il_id),
       'borclar', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'anapara', anapara, 'toplam', toplam, 'kalan', kalan,
            'taksit', taksit, 'gun', gun, 'faiz', faiz, 'baslangic', baslangic, 'gecikme', gecikme, 'durum', durum) order by id desc)
          from (select * from oyun.belediye_borc where il_id = m.il_id and (durum = 'aktif' or kapanis > oyun.simdi() - interval '7 days')
                order by id desc limit 8) b), '[]'::jsonb),
       'toplam_borc', coalesce((select sum(kalan) from oyun.belediye_borc where il_id = m.il_id and durum = 'aktif'), 0)),
    'kriz', (select oyun.belediye_kriz_json(x) from oyun.belediye_kriz x where x.il_id = m.il_id and x.durum = 'acik' order by id desc limit 1),
    'kriz_gecmis', coalesce((select jsonb_agg(oyun.belediye_kriz_json(x) order by x.id desc)
          from (select * from oyun.belediye_kriz where il_id = m.il_id and durum <> 'acik' order by id desc limit 8) x), '[]'::jsonb));
end $$;

-- Herkese açık belediye karnesi: seçmen başkanı hizmetle, borçla, krizlerdeki kararlarıyla görür.
create or replace function public.belediye_karnesi(p_il integer)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare d oyun.il_durum; bas record;
begin
  if auth.uid() is null then raise exception 'Oturum açmalısın'; end if;
  select * into d from oyun.il_durum where il_id = p_il;
  if d.il_id is null then raise exception 'İl bulunamadı'; end if;
  select pr.kad, pr.id, pa.kisa parti, m.bas into bas from oyun.makamlar m join oyun.profiller pr on pr.id = m.user_id
    left join oyun.partiler pa on pa.id = pr.parti_id
   where m.tur = 'bel' and m.il_id = p_il and m.bit is null order by m.id desc limit 1;
  return jsonb_build_object('il_id', p_il, 'il_ad', (select ad from oyun.iller where id = p_il),
    'baskan', case when bas.kad is null then null else jsonb_build_object('kad', bas.kad, 'parti', bas.parti, 'bas', bas.bas) end,
    'kasa', d.kasa, 'memnuniyet', d.memnuniyet, 'gelisim', d.gelisim,
    'borc', coalesce((select sum(kalan) from oyun.belediye_borc where il_id = p_il and durum = 'aktif'), 0),
    'gecikme', coalesce((select sum(gecikme) from oyun.belediye_borc where il_id = p_il and durum = 'aktif'), 0),
    'aktif_bina', (select count(*) from oyun.belediye_bina where il_id = p_il and durum = 'aktif'),
    'karne', oyun.belediye_karne(p_il::smallint),
    'krizler', coalesce((select jsonb_agg(jsonb_build_object('baslik', k.baslik, 'durum', x.durum, 'zaman', coalesce(x.karar_zamani, x.baslangic),
           'secim_ad', (select e->>'ad' from jsonb_array_elements(k.secenekler) e where e->>'k' = x.secim), 'sonuc', x.sonuc) order by x.id desc)
        from (select * from oyun.belediye_kriz where il_id = p_il order by id desc limit 6) x
        join oyun.belediye_kriz_katalog k on k.kod = x.kod), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------- gece hesabı
create or replace function oyun.belediye_gunluk(t timestamptz) returns void language plpgsql as $$
declare r record; h record; b record; v_kasa numeric; bas uuid; g numeric; pay numeric;
  bugun date := (t at time zone 'Europe/Istanbul')::date;
begin
  for r in select d.il_id, i.ad, i.mv from oyun.il_durum d join oyun.iller i on i.id = d.il_id loop
    g := oyun.il_gelir(r.il_id);
    -- Vergi geliri 60 günlük gelire kadar birikir; bağış ve kredi gibi dış kaynaklar kesilmez.
    update oyun.il_durum set kasa = coalesce(kasa, 0) + least(g, greatest(0, 60 * g - coalesce(kasa, 0))) - oyun.il_gider(r.il_id)
     where il_id = r.il_id returning kasa into v_kasa;
    -- İller Bankası taksitleri
    for b in select * from oyun.belediye_borc where il_id = r.il_id and durum = 'aktif' and son_odeme < bugun order by id loop
      pay := least(b.taksit, b.kalan);
      if v_kasa >= pay then
        update oyun.il_durum set kasa = kasa - pay where il_id = r.il_id returning kasa into v_kasa;
        update oyun.belediye_borc set kalan = round(kalan - pay, 6), son_odeme = bugun,
               durum = case when kalan - pay <= 0.000001 then 'kapandi' else 'aktif' end,
               kapanis = case when kalan - pay <= 0.000001 then t end
         where id = b.id;
        insert into oyun.belediye_sehir_hareket(il_id, tur, tutar, aciklama, zaman)
        values (r.il_id, 'kredi_taksit', -pay, 'İller Bankası taksiti', t);
      else
        update oyun.belediye_borc set kalan = round(kalan + b.taksit * 0.05, 6), gecikme = gecikme + 1, son_odeme = bugun
         where id = b.id;
        update oyun.il_durum set memnuniyet = oyun.sinir(memnuniyet - 1, 0, 100) where il_id = r.il_id;
        insert into oyun.belediye_sehir_hareket(il_id, tur, tutar, aciklama, zaman)
        values (r.il_id, 'kredi_gecikme', 0, 'İller Bankası taksiti ödenemedi; %5 gecikme cezası borca eklendi', t);
        bas := (select user_id from oyun.makamlar where tur = 'bel' and il_id = r.il_id and bit is null limit 1);
        if bas is not null then
          perform oyun.bildir(bas, 'İller Bankası taksiti kasada para olmadığı için ödenemedi; %5 gecikme cezası eklendi.', t);
        end if;
        if (b.gecikme + 1) % 3 = 0 then
          perform oyun.olay('belediye', format('Sayıştay uyarısı: %s Belediyesi İller Bankası borcunu %s gündür ödeyemiyor.', r.ad, b.gecikme + 1), r.il_id, null, t);
        end if;
      end if;
    end loop;
    if v_kasa < 0 then
      bas := (select user_id from oyun.makamlar where tur = 'bel' and il_id = r.il_id and bit is null limit 1);
      update oyun.il_durum set hemsehri = 0 where il_id = r.il_id and hemsehri > 0;
      for h in select k.kod, bh.ad from oyun.il_hizmet k join oyun.belediye_hizmetleri bh on bh.kod = k.kod
               where k.il_id = r.il_id order by bh.oran desc loop
        exit when (select kasa from oyun.il_durum where il_id = r.il_id) >= 0;
        delete from oyun.il_hizmet where il_id = r.il_id and kod = h.kod;
        update oyun.il_durum set kasa = kasa + oyun.hizmet_gider(r.il_id, h.kod) where il_id = r.il_id;
        perform oyun.olay('belediye', format('%s Belediyesi kasası yetmediği için %s hizmetini kapattı.', r.ad, h.ad), r.il_id, null, t);
      end loop;
      if bas is not null then perform oyun.bildir(bas, 'Belediye kasası eksiye düştü: hemşehri desteği durduruldu, gerekirse hizmetler kapatıldı.', t); end if;
      update oyun.il_durum set kasa = greatest(kasa, 0) where il_id = r.il_id;
    end if;
  end loop;
  delete from oyun.belediye_karne_etki where bitis < t - interval '30 days';
  -- gelişmişlik yatırım almazsa yavaşça ortalamaya döner; memnuniyet hizmetlere, desteğe, vergiye
  -- ve hizmet karnesine (binalar, programlar, kriz kararları) göre şekillenir
  update oyun.il_durum d set gelisim = gelisim + (50 - gelisim) * 0.01,
    memnuniyet = oyun.sinir(memnuniyet + (50 + 4 * (select count(*) from oyun.il_hizmet ih where ih.il_id = d.il_id) + least(10, hemsehri / 30)
                                          - kent_vergisi * 2 - oyun.il_duz(d.il_id, 'emlak') / 30
                                          + (oyun.belediye_karne_ort(d.il_id) - 45) * 0.5 - memnuniyet) * 0.05, 0, 100);
end $$;

-- ---------------------------------------------------------------- yetkiler
revoke all on function public.belediye_kredi_al(numeric, int), public.belediye_kredi_kapat(bigint),
  public.belediye_kriz_karar(bigint, text), public.belediye_detay_paneli(), public.belediye_karnesi(integer)
  from public, anon, authenticated;
grant execute on function public.belediye_kredi_al(numeric, int), public.belediye_kredi_kapat(bigint),
  public.belediye_kriz_karar(bigint, text), public.belediye_detay_paneli(), public.belediye_karnesi(integer)
  to authenticated;
revoke all on function oyun.belediye_kriz_tick(numeric), oyun.belediye_kriz_baslat(smallint, text),
  oyun.belediye_kriz_uygula(bigint, text, timestamptz), oyun.belediye_kriz_etki(smallint, jsonb, text, timestamptz)
  from public, anon, authenticated;
-- =====================================================================
--  93) EKONOMİ KURUMLARI: Merkez Bankası, belediye tahvili, SPK, konkordato/iflas
--  - Merkez Bankası: başkanı yürütme başı atar (aday kabul eder, tarafsız olmalı).
--    PPK haftada bir politika faizini belirler (tek kararda en fazla ±10 puan).
--    Faiz oyun.banka_oranlar() üzerinden devlet bankası mevduat/kredi oranlarını,
--    reel faiz de her gün enflasyon ve büyümeyi etkiler. Karar verilene kadar
--    eski formül (enflasyon + banka_reel_faiz, en az %15) geçerlidir.
--  - Belediye tahvili: belediye başkanı 14/30/60 gün vadeli tahvil ihraç eder,
--    oyuncular 48 saat içinde alır; para il kasasına girer, vadede faiziyle
--    kasadan ödenir. Kasa yetmezse temerrüt (kısmi ödeme, memnuniyet −5).
--  - SPK: bağlantılı hesaplar arası ya da 48 saatte karşılıklı hisse işlemleri
--    otomatik incelenir; Hazine ve Maliye Bakanı 72 saatte karar verir. Ceza
--    işlem tutarının %20'si (en az 10.000 ₺) + 7 gün borsa işlem yasağı.
--  - Konkordato/iflas: kasası eksiye düşen şirket konkordato ilan eder (açık
--    sermayenin yarısını geçerse kendiliğinden başlar); 14 günde açık kapanmazsa
--    şirket iflas eder, borsadan çıkar. Bankalar kapsam dışıdır.
--  Oyuncu verisini değiştirmez; yalnız yeni tablo, fonksiyon ve tetik ekler.
--  Canlıya 2026-10-13'te uygulandı (migrations/20261013_ekonomi_kurumlar.sql).
-- =====================================================================

-- ------------------------------------------------------------ Merkez Bankası
create table if not exists oyun.merkez_bankasi(
  id int primary key default 1 check (id=1),
  baskan uuid references oyun.profiller(id),
  atama timestamptz,
  politika_faiz numeric,
  son_karar timestamptz,
  son_etki_gun date,
  son_maas_gun date
);
insert into oyun.merkez_bankasi(id) values(1) on conflict do nothing;
create table if not exists oyun.ppk_kararlari(
  id bigserial primary key, zaman timestamptz not null, baskan uuid, onceki numeric, yeni numeric not null,
  enflasyon numeric, gerekce text
);
create table if not exists oyun.tcmb_teklifleri(
  id bigserial primary key, teklif_eden uuid not null, aday uuid not null, durum text not null default 'bekliyor',
  zaman timestamptz not null
);
create unique index if not exists tcmb_teklif_tek on oyun.tcmb_teklifleri(aday) where durum='bekliyor';
revoke all on oyun.merkez_bankasi, oyun.ppk_kararlari, oyun.tcmb_teklifleri from anon, authenticated;
alter table oyun.merkez_bankasi enable row level security;
alter table oyun.ppk_kararlari enable row level security;
alter table oyun.tcmb_teklifleri enable row level security;

create or replace function oyun.politika_faizi() returns numeric language sql stable set search_path to '' as $$
  select coalesce((select politika_faiz from oyun.merkez_bankasi where id=1),
                  (select greatest(15,round(u.enflasyon+a.banka_reel_faiz,1)) from oyun.ulke u, oyun.ayarlar a where u.id=1 and a.id=1))
$$;

create or replace function oyun.banka_oranlar() returns jsonb language sql stable set search_path to '' as $function$
  with x as (select oyun.politika_faizi() py)
  select jsonb_build_object(
    'politika',py,'vadesiz',0,
    'vadeli1s',round(py / 365.0 / 24.0,3),
    'vadeli3s',round(py / 365.0 * 3 / 24.0,3),
    'vadeli6s',round(py / 365.0 * 6 / 24.0,3),
    'vadeli12s',round(py / 365.0 * 12 / 24.0,3),
    'vadeli24s',round(py / 365.0,3),
    'vadeli7',round(py / 365.0 * 7,3),
    'vadeli30',round(py / 365.0 * 30,3),
    'kredi',round(py/12*1.60,2),
    'gecikme_gunluk',1
  ) from x
$function$;

create or replace function public.tcmb_baskan_ata(p_kad text) returns jsonb language plpgsql security definer set search_path to '' as $$
declare p oyun.profiller := oyun.profilim(); h oyun.profiller; t timestamptz := oyun.simdi(); v_id bigint;
begin
  perform oyun.cb_zorunlu(p);
  h := oyun.profil_bul(p_kad);
  if h.yasakli then raise exception 'Yasaklı hesaba teklif gönderilemez.'; end if;
  if (select baskan from oyun.merkez_bankasi where id=1) = h.id then raise exception 'Bu oyuncu zaten Merkez Bankası Başkanı.'; end if;
  if exists(select 1 from oyun.makamlar where user_id=h.id and bit is null) then
    raise exception 'Merkez Bankası Başkanı tarafsız olmalı: adayın aktif bir siyasi görevi var.'; end if;
  insert into oyun.tcmb_teklifleri(teklif_eden,aday,zaman) values(p.id,h.id,t)
    on conflict (aday) where durum='bekliyor' do update set teklif_eden=excluded.teklif_eden, zaman=excluded.zaman
    returning id into v_id;
  perform oyun.bildir(h.id, format('%s %s, seni Merkez Bankası Başkanı olarak atamak istiyor. Hayat › Ekonomi merkezi › Merkez Bankası ekranından kabul edebilir ya da reddedebilirsin. Kabul edersen siyasi görev alamazsın; seçilirsen bankadaki görevin biter.', oyun.yurutme_unvan(), p.kad), t);
  return jsonb_build_object('durum','bekliyor','teklif_id',v_id,'aday',h.kad);
end $$;

create or replace function public.tcmb_teklif_yanit(p_teklif bigint, p_kabul boolean) returns jsonb language plpgsql security definer set search_path to '' as $$
declare p oyun.profiller := oyun.profilim(); k oyun.tcmb_teklifleri; t timestamptz := oyun.simdi(); eski uuid;
begin
  select * into k from oyun.tcmb_teklifleri where id=p_teklif and aday=p.id and durum='bekliyor' for update;
  if k.id is null then raise exception 'Teklif bulunamadı.'; end if;
  if not p_kabul then
    update oyun.tcmb_teklifleri set durum='red' where id=k.id;
    perform oyun.bildir(k.teklif_eden, format('%s, Merkez Bankası Başkanlığı teklifini reddetti.', p.kad), t);
    return jsonb_build_object('durum','red');
  end if;
  if oyun.yurutme_user() is distinct from k.teklif_eden then
    update oyun.tcmb_teklifleri set durum='gecersiz' where id=k.id;
    raise exception 'Teklifi yapan kişi artık yürütmenin başında değil; teklif geçersiz.';
  end if;
  if exists(select 1 from oyun.makamlar where user_id=p.id and bit is null) then
    raise exception 'Aktif siyasi görevin varken Merkez Bankası Başkanı olamazsın.'; end if;
  select baskan into eski from oyun.merkez_bankasi where id=1 for update;
  update oyun.merkez_bankasi set baskan=p.id, atama=t, son_maas_gun=(t at time zone 'Europe/Istanbul')::date where id=1;
  update oyun.tcmb_teklifleri set durum='kabul' where id=k.id;
  update oyun.tcmb_teklifleri set durum='gecersiz' where durum='bekliyor';
  if eski is not null and eski<>p.id then perform oyun.bildir(eski, 'Merkez Bankası Başkanlığı görevin sona erdi; yerine yeni başkan atandı.', t); end if;
  perform oyun.olay('ekonomi', format('%s, Merkez Bankası Başkanı olarak göreve başladı.', p.kad), null, null, t);
  perform oyun.gazete_ekle('icraat', 'Merkez Bankası''na yeni başkan', format('%s atamasıyla %s, Merkez Bankası Başkanlığı görevine getirildi. Piyasalar ilk faiz kararını bekliyor.', oyun.yurutme_unvan(), p.kad), null, t);
  return public.merkez_bankasi();
end $$;

create or replace function public.tcmb_baskan_gorevden_al() returns jsonb language plpgsql security definer set search_path to '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); eski uuid;
begin
  perform oyun.cb_zorunlu(p);
  select baskan into eski from oyun.merkez_bankasi where id=1 for update;
  if eski is null then raise exception 'Merkez Bankası Başkanlığı zaten boş.'; end if;
  update oyun.merkez_bankasi set baskan=null, atama=null where id=1;
  perform oyun.bildir(eski, format('%s kararıyla Merkez Bankası Başkanlığı görevinden alındın.', oyun.yurutme_unvan()), t);
  perform oyun.olay('ekonomi', format('Merkez Bankası Başkanı %s görevden alındı. Piyasalarda belirsizlik.', oyun.kad(eski)), null, null, t);
  update oyun.pazar_ayar set endeks = round(endeks*0.98,4) where id=1;
  return public.merkez_bankasi();
end $$;

create or replace function public.ppk_faiz_karari(p_faiz numeric, p_gerekce text default null) returns jsonb language plpgsql security definer set search_path to '' as $$
declare p oyun.profiller := oyun.profilim(); m oyun.merkez_bankasi; t timestamptz := oyun.simdi(); eski numeric; enf numeric;
begin
  select * into m from oyun.merkez_bankasi where id=1 for update;
  if m.baskan is distinct from p.id then raise exception 'Faiz kararını yalnızca Merkez Bankası Başkanı verir.'; end if;
  if p_faiz is null or p_faiz<0 or p_faiz>100 or p_faiz<>round(p_faiz,2) then raise exception 'Politika faizi %%0 ile %%100 arasında, en fazla iki ondalıklı olmalı.'; end if;
  if m.son_karar is not null and m.son_karar > t - interval '7 days' then
    raise exception 'Para Politikası Kurulu haftada bir toplanır. Sonraki karar: %', to_char((m.son_karar + interval '7 days') at time zone 'Europe/Istanbul','DD.MM HH24:MI'); end if;
  eski := oyun.politika_faizi();
  if abs(p_faiz-eski) > 10 then raise exception 'Tek kararda en fazla 10 puan değişiklik yapılabilir (şu an %%%s).', eski; end if;
  select enflasyon into enf from oyun.ulke where id=1;
  update oyun.merkez_bankasi set politika_faiz=p_faiz, son_karar=t,
    son_etki_gun=coalesce(son_etki_gun,(t at time zone 'Europe/Istanbul')::date) where id=1;
  insert into oyun.ppk_kararlari(zaman,baskan,onceki,yeni,enflasyon,gerekce) values(t,p.id,eski,p_faiz,round(enf,2),left(nullif(btrim(p_gerekce),''),500));
  update oyun.pazar_ayar set endeks = round(oyun.sinir(endeks*(1 + (eski-p_faiz)*0.002),0.3,3),4) where id=1;
  perform oyun.olay('ekonomi', format('Merkez Bankası politika faizini %%%s''ten %%%s''e %s.', eski, p_faiz,
    case when p_faiz>eski then 'yükseltti' when p_faiz<eski then 'indirdi' else 'sabit bıraktı' end), null, null, t);
  perform oyun.gazete_ekle('icraat', format('PPK kararı: politika faizi %%%s', p_faiz),
    format('Merkez Bankası Para Politikası Kurulu, politika faizini %%%s seviyesinden %%%s seviyesine getirdi. Yıllık enflasyon %%%s.%s', eski, p_faiz, round(enf,1),
      coalesce(' Gerekçe: '||left(nullif(btrim(p_gerekce),''),300),'')), null, t);
  return public.merkez_bankasi();
end $$;

create or replace function public.merkez_bankasi() returns jsonb language plpgsql security definer set search_path to '' as $$
declare me uuid := oyun.ben(); m oyun.merkez_bankasi; u oyun.ulke; pf numeric;
begin
  select * into m from oyun.merkez_bankasi where id=1;
  select * into u from oyun.ulke where id=1;
  pf := oyun.politika_faizi();
  return jsonb_build_object(
    'baskan', case when m.baskan is null then null else jsonb_build_object('id',m.baskan,'kad',oyun.kad(m.baskan),'atama',m.atama) end,
    'politika_faiz', pf, 'tcmb_karari', m.politika_faiz is not null,
    'enflasyon', round(u.enflasyon,2), 'buyume', round(u.buyume,2), 'reel_faiz', round(pf-u.enflasyon,2),
    'oranlar', oyun.banka_oranlar(),
    'sonraki_karar', case when m.son_karar is null then null else m.son_karar + interval '7 days' end,
    'ben_baskan', m.baskan is not distinct from me and me is not null,
    'ben_atayabilir', oyun.yurutme_user() is not distinct from me and me is not null,
    'yurutme_unvan', oyun.yurutme_unvan(),
    'bekleyen_teklifim', (select jsonb_build_object('id',id,'teklif_eden',oyun.kad(teklif_eden),'zaman',zaman) from oyun.tcmb_teklifleri where aday=me and durum='bekliyor' limit 1),
    'kararlar', coalesce((select jsonb_agg(jsonb_build_object('zaman',zaman,'baskan',oyun.kad(baskan),'onceki',onceki,'yeni',yeni,'enflasyon',enflasyon,'gerekce',gerekce) order by zaman desc)
                 from (select * from oyun.ppk_kararlari order by zaman desc limit 20) k),'[]'::jsonb),
    'kural', 'PPK haftada bir toplanır; tek kararda en fazla 10 puan. Reel faiz (faiz − enflasyon) yüksekse enflasyon düşer ama büyüme yavaşlar; düşükse tersi.'
  );
end $$;

create or replace function oyun.merkez_bankasi_tick(t timestamptz) returns void language plpgsql set search_path to '' as $$
declare m oyun.merkez_bankasi; bugun date := (t at time zone 'Europe/Istanbul')::date; g date; reel numeric; maas numeric;
begin
  select * into m from oyun.merkez_bankasi where id=1 for update;
  if m.baskan is not null and (exists(select 1 from oyun.makamlar where user_id=m.baskan and bit is null)
       or (select yasakli from oyun.profiller where id=m.baskan)) then
    perform oyun.bildir(m.baskan, 'Siyasi görev aldığın için Merkez Bankası Başkanlığın sona erdi.', t);
    perform oyun.olay('ekonomi', format('%s, siyasi görev aldığı için Merkez Bankası Başkanlığından ayrıldı.', oyun.kad(m.baskan)), null, null, t);
    update oyun.merkez_bankasi set baskan=null, atama=null where id=1 returning * into m;
  end if;
  if m.politika_faiz is not null and m.son_etki_gun is not null and m.son_etki_gun < bugun then
    g := greatest(m.son_etki_gun, bugun-31);
    while g < bugun loop
      g := g+1;
      select oyun.politika_faizi() - enflasyon into reel from oyun.ulke where id=1;
      reel := oyun.sinir(reel,-40,40);
      update oyun.ulke set enflasyon = oyun.sinir(enflasyon - reel*0.01, 0, 200),
                           buyume   = oyun.sinir(buyume - reel*0.006, -10, 15) where id=1;
    end loop;
    update oyun.merkez_bankasi set son_etki_gun=bugun where id=1;
  end if;
  if m.baskan is not null and coalesce(m.son_maas_gun, bugun-1) < bugun then
    maas := round(oyun.makam_maasi('bakan', null) / 30);
    perform oyun.para_islem(m.baskan, maas, 'maas', 'Merkez Bankası Başkanlığı günlük maaşı', t);
    update oyun.merkez_bankasi set son_maas_gun=bugun where id=1;
  end if;
end $$;

-- ------------------------------------------------------------ Belediye tahvili
create table if not exists oyun.belediye_tahvil(
  id bigserial primary key, il_id smallint not null references oyun.iller(id), ihrac_eden uuid not null,
  hedef numeric not null, toplanan numeric not null default 0, faiz numeric not null, vade_gun int not null,
  bas timestamptz not null, satis_bit timestamptz not null, vade timestamptz,
  durum text not null default 'satista' check (durum in ('satista','tutuluyor','odendi','temerrut','iptal')),
  odenen numeric, sonuc_zaman timestamptz
);
create index if not exists belediye_tahvil_durum on oyun.belediye_tahvil(durum, satis_bit, vade);
create table if not exists oyun.belediye_tahvil_pay(
  tahvil_id bigint not null references oyun.belediye_tahvil(id), user_id uuid not null, tutar numeric not null, alis timestamptz not null,
  primary key(tahvil_id,user_id)
);
revoke all on oyun.belediye_tahvil, oyun.belediye_tahvil_pay from anon, authenticated;
alter table oyun.belediye_tahvil enable row level security;
alter table oyun.belediye_tahvil_pay enable row level security;

create or replace function oyun.bel_tahvil_tavan(p_il smallint) returns numeric language sql stable set search_path to '' as $$
  select round(greatest(1, coalesce((select kasa from oyun.il_durum where il_id=p_il),0)) * oyun.pazar_tl_milyar())
$$;

create or replace function public.belediye_tahvil_ihrac(p_hedef numeric, p_faiz numeric, p_vade_gun int) returns jsonb language plpgsql security definer set search_path to '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); v_il smallint; tavan numeric; acik numeric; yillik numeric; v_id bigint; ilad text;
begin
  select il_id into v_il from oyun.makamlar where tur='bel' and user_id=p.id and bit is null limit 1;
  if v_il is null then raise exception 'Belediye tahvilini yalnızca görevdeki belediye başkanı ihraç edebilir.'; end if;
  if p_vade_gun not in (14,30,60) then raise exception 'Vade 14, 30 veya 60 gün olabilir.'; end if;
  if p_faiz is null or p_faiz<=0 or p_faiz<>round(p_faiz,2) then raise exception 'Dönem faizi pozitif ve en fazla iki ondalıklı olmalı.'; end if;
  yillik := p_faiz*365.0/p_vade_gun;
  if yillik > oyun.politika_faizi()+25 then
    raise exception 'Yıllık karşılığı %%%s; politika faizinin 25 puan üstüne çıkamaz (en fazla %%%s dönem faizi).', round(yillik,1), round((oyun.politika_faizi()+25)*p_vade_gun/365.0,2); end if;
  tavan := oyun.bel_tahvil_tavan(v_il);
  if p_hedef is null or p_hedef<100000 or p_hedef<>round(p_hedef) or p_hedef>tavan then
    raise exception 'Tahvil tutarı 100.000 ₺ ile %s ₺ arasında olmalı (sınır belediye kasasına göre belirlenir).', oyun.tl(tavan); end if;
  select coalesce(sum(case when durum='satista' then hedef else toplanan end),0) into acik from oyun.belediye_tahvil where il_id=v_il and durum in ('satista','tutuluyor');
  if acik + p_hedef > tavan*2 then raise exception 'Belediyenin ödenmemiş tahvil stoku sınırı aşar (en fazla %s ₺ daha).', oyun.tl(greatest(0,tavan*2-acik)); end if;
  if exists(select 1 from oyun.belediye_tahvil where il_id=v_il and durum='satista') then raise exception 'Satışta olan bir tahvil varken yenisi ihraç edilemez.'; end if;
  insert into oyun.belediye_tahvil(il_id,ihrac_eden,hedef,faiz,vade_gun,bas,satis_bit)
    values(v_il,p.id,p_hedef,p_faiz,p_vade_gun,t,t+interval '48 hours') returning id into v_id;
  select ad into ilad from oyun.iller where id=v_il;
  perform oyun.olay('ekonomi', format('%s Belediyesi %s ₺ tutarında, %s gün vadeli, %%%s getirili tahvil ihraç etti. Satış 48 saat sürecek.', ilad, oyun.tl(p_hedef), p_vade_gun, p_faiz), v_il, p.parti_id, t);
  perform oyun.gazete_ekle('icraat', format('%s Belediyesi borçlanmaya gidiyor', ilad),
    format('Belediye Başkanı %s, %s ₺ tutarında %s gün vadeli tahvil ihraç etti. Yatırımcılara dönem sonunda %%%s getiri vaat ediliyor.', p.kad, oyun.tl(p_hedef), p_vade_gun, p_faiz), v_id, t);
  return public.belediye_tahvilleri();
end $$;

create or replace function public.belediye_tahvil_al(p_tahvil bigint, p_tutar numeric) returns jsonb language plpgsql security definer set search_path to '' as $$
declare p oyun.profiller := oyun.profilim(); t timestamptz := oyun.simdi(); b oyun.belediye_tahvil; ilad text;
begin
  select * into b from oyun.belediye_tahvil where id=p_tahvil for update;
  if b.id is null or b.durum<>'satista' or b.satis_bit<=t then raise exception 'Bu tahvilin satışı kapandı.'; end if;
  if p_tutar is null or p_tutar<1000 or p_tutar<>round(p_tutar) then raise exception 'En az 1.000 ₺, tam sayı tutar gir.'; end if;
  if b.toplanan+p_tutar > b.hedef then raise exception 'Kalan tahvil miktarı %s ₺.', oyun.tl(b.hedef-b.toplanan); end if;
  select ad into ilad from oyun.iller where id=b.il_id;
  perform oyun.para_islem(p.id,-p_tutar,'tahvil',format('%s Belediyesi tahvili #%s alımı',ilad,b.id),t);
  insert into oyun.belediye_tahvil_pay(tahvil_id,user_id,tutar,alis) values(b.id,p.id,p_tutar,t)
    on conflict (tahvil_id,user_id) do update set tutar=oyun.belediye_tahvil_pay.tutar+excluded.tutar;
  update oyun.belediye_tahvil set toplanan=toplanan+p_tutar where id=b.id;
  return public.belediye_tahvilleri();
end $$;

create or replace function public.belediye_tahvilleri() returns jsonb language plpgsql security definer set search_path to '' as $$
declare me uuid := oyun.ben(); v_il smallint;
begin
  select il_id into v_il from oyun.makamlar where tur='bel' and user_id=me and bit is null limit 1;
  return jsonb_build_object(
    'tahviller', coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'il_id',b.il_id,'il',i.ad,'ihrac_eden',oyun.kad(b.ihrac_eden),
        'hedef',b.hedef,'toplanan',b.toplanan,'faiz',b.faiz,'yillik',round(b.faiz*365.0/b.vade_gun,1),'vade_gun',b.vade_gun,
        'satis_bit',b.satis_bit,'vade',b.vade,'durum',b.durum,'odenen',b.odenen,
        'payim',(select tutar from oyun.belediye_tahvil_pay x where x.tahvil_id=b.id and x.user_id=me)) order by b.bas desc)
      from (select * from oyun.belediye_tahvil where durum in ('satista','tutuluyor') or bas > oyun.simdi()-interval '30 days' order by bas desc limit 60) b
      join oyun.iller i on i.id=b.il_id),'[]'::jsonb),
    'belediyem', case when v_il is null then null else jsonb_build_object('il_id',v_il,'il',(select ad from oyun.iller where id=v_il),'tavan',oyun.bel_tahvil_tavan(v_il),
       'acik_stok',(select coalesce(sum(case when durum='satista' then hedef else toplanan end),0) from oyun.belediye_tahvil where il_id=v_il and durum in ('satista','tutuluyor')),
       'max_yillik_faiz', oyun.politika_faizi()+25) end,
    'politika_faiz', oyun.politika_faizi(),
    'kural','Satış 48 saat sürer; hedefin %30''u toplanmazsa iptal edilip para iade edilir. Vadede belediye kasası yetmezse tahvil temerrüde düşer ve yatırımcılar kasadaki kadarını alır.'
  );
end $$;

create or replace function oyun.belediye_tahvil_tick(t timestamptz) returns void language plpgsql set search_path to '' as $$
declare b oyun.belediye_tahvil; x record; ilad text; kur numeric; borc numeric; v_kasa numeric; oran numeric; od numeric; toplam_od numeric; bb uuid;
begin
  kur := oyun.pazar_tl_milyar();
  for b in select * from oyun.belediye_tahvil where durum='satista' and satis_bit<=t order by id for update loop
    select ad into ilad from oyun.iller where id=b.il_id;
    if b.toplanan < b.hedef*0.3 then
      for x in select * from oyun.belediye_tahvil_pay where tahvil_id=b.id loop
        perform oyun.para_islem(x.user_id, x.tutar, 'tahvil', format('%s Belediyesi tahvili #%s iptal: iade', ilad, b.id), t);
      end loop;
      update oyun.belediye_tahvil set durum='iptal', sonuc_zaman=t where id=b.id;
      perform oyun.bildir(b.ihrac_eden, format('%s Belediyesi tahvili yeterli talep görmedi (%s / %s ₺); iptal edildi, paralar iade edildi.', ilad, oyun.tl(b.toplanan), oyun.tl(b.hedef)), t);
      perform oyun.olay('ekonomi', format('%s Belediyesi tahvili yeterli talep görmediği için iptal edildi.', ilad), b.il_id, null, t);
    else
      update oyun.il_durum set kasa=coalesce(kasa,0)+b.toplanan/kur where il_id=b.il_id;
      update oyun.belediye_tahvil set durum='tutuluyor', vade=t+make_interval(days=>b.vade_gun) where id=b.id;
      perform oyun.bildir(b.ihrac_eden, format('%s Belediyesi tahvil satışı tamamlandı: %s ₺ belediye kasasına girdi. Vadede %s ₺ geri ödenecek.', ilad, oyun.tl(b.toplanan), oyun.tl(round(b.toplanan*(1+b.faiz/100)))), t);
      perform oyun.olay('ekonomi', format('%s Belediyesi tahvil satışında %s ₺ topladı.', ilad, oyun.tl(b.toplanan)), b.il_id, null, t);
    end if;
  end loop;
  for b in select * from oyun.belediye_tahvil where durum='tutuluyor' and vade<=t order by vade for update loop
    select ad into ilad from oyun.iller where id=b.il_id;
    borc := round(b.toplanan*(1+b.faiz/100));
    select coalesce(d.kasa,0) into v_kasa from oyun.il_durum d where d.il_id=b.il_id for update;
    v_kasa := coalesce(v_kasa,0);
    oran := case when v_kasa*kur >= borc then 1 else greatest(0, v_kasa*kur/borc) end;
    toplam_od := 0;
    for x in select * from oyun.belediye_tahvil_pay where tahvil_id=b.id loop
      od := floor(x.tutar*(1+b.faiz/100)*oran);
      if od>0 then
        perform oyun.para_islem(x.user_id, od, 'tahvil', format('%s Belediyesi tahvili #%s vade ödemesi%s', ilad, b.id, case when oran<1 then ' (kısmi — temerrüt)' else '' end), t);
        toplam_od := toplam_od+od;
      end if;
      if oran<1 then perform oyun.bildir(x.user_id, format('%s Belediyesi tahvil borcunu ödeyemedi. Alacağının yalnızca %%%s''i ödendi.', ilad, round(oran*100)), t); end if;
    end loop;
    update oyun.il_durum d set kasa=greatest(0,coalesce(d.kasa,0)-toplam_od/kur) where d.il_id=b.il_id;
    if oran<1 then
      update oyun.belediye_tahvil set durum='temerrut', odenen=toplam_od, sonuc_zaman=t where id=b.id;
      update oyun.il_durum d set memnuniyet=greatest(0,d.memnuniyet-5) where d.il_id=b.il_id;
      perform oyun.olay('ekonomi', format('%s Belediyesi tahvil borcunu ödeyemedi: temerrüt! Yatırımcılar alacağının %%%s''ini alabildi.', ilad, round(oran*100)), b.il_id, null, t);
      perform oyun.gazete_ekle('icraat', format('%s Belediyesi temerrüde düştü', ilad),
        format('%s Belediyesi, %s ₺ tutarındaki tahvil borcunu vadesinde ödeyemedi. Yatırımcılar alacağının ancak %%%s''ini tahsil edebildi; kent halkında memnuniyetsizlik büyüyor.', ilad, oyun.tl(borc), round(oran*100)), b.id, t);
      bb := oyun.makam_sahibi('bel',null,b.il_id);
      if bb is not null then perform oyun.bildir(bb, format('%s Belediyesi tahvil borcunu ödeyemedi; kentte memnuniyet 5 puan düştü.', ilad), t); end if;
    else
      update oyun.belediye_tahvil set durum='odendi', odenen=toplam_od, sonuc_zaman=t where id=b.id;
      perform oyun.olay('ekonomi', format('%s Belediyesi %s ₺ tahvil borcunu vadesinde ödedi.', ilad, oyun.tl(toplam_od)), b.il_id, null, t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------ SPK
create table if not exists oyun.spk_inceleme(
  id bigserial primary key, sirket_id bigint references oyun.sirketler(id), taraf1 uuid not null, taraf2 uuid,
  tur text not null check (tur in ('bagli_hesap','karsilikli_islem','manipulasyon')),
  kanit jsonb not null default '{}'::jsonb, acan uuid, bas timestamptz not null, bit timestamptz not null,
  durum text not null default 'acik' check (durum in ('acik','ceza','beraat')),
  ceza numeric, karar_veren uuid, karar_not text, karar_zaman timestamptz
);
create index if not exists spk_acik on oyun.spk_inceleme(durum, bit);
create table if not exists oyun.spk_yasak(user_id uuid primary key, bit timestamptz not null, neden text);
revoke all on oyun.spk_inceleme, oyun.spk_yasak from anon, authenticated;
alter table oyun.spk_inceleme enable row level security;
alter table oyun.spk_yasak enable row level security;

create or replace function oyun.spk_yasakli_mi(u uuid) returns boolean language sql stable set search_path to '' as $$
  select exists(select 1 from oyun.spk_yasak where user_id=u and bit>oyun.simdi())
$$;

create or replace function oyun.bagli_hesap_mi(a uuid, b uuid) returns boolean language sql stable set search_path to '' as $$
  select exists(select 1 from oyun.oturumlar x join oyun.oturumlar y on y.user_id=b
                where x.user_id=a and ((x.cihaz is not null and x.cihaz<>'' and x.cihaz=y.cihaz) or (x.iz is not null and x.iz<>'' and x.iz=y.iz)))
$$;

create or replace function oyun.tg_spk_emir() returns trigger language plpgsql set search_path to '' as $$
begin
  if oyun.spk_yasakli_mi(new.satici) then raise exception 'SPK işlem yasağın sürüyor; borsada emir veremezsin.'; end if;
  return new;
end $$;
create or replace function oyun.tg_spk_islem_once() returns trigger language plpgsql set search_path to '' as $$
begin
  if oyun.spk_yasakli_mi(new.alici) then raise exception 'SPK işlem yasağın sürüyor; borsada alım yapamazsın.'; end if;
  if oyun.spk_yasakli_mi(new.satici) then raise exception 'Satıcıya SPK işlem yasağı getirildi; bu emir işlem göremez.'; end if;
  return new;
end $$;

create or replace function oyun.tg_spk_gozetim() returns trigger language plpgsql set search_path to '' as $$
declare v_tur text; k jsonb; t timestamptz := oyun.simdi(); sad text;
begin
  if new.alici is null or new.satici is null or new.alici=new.satici then return new; end if;
  if exists(select 1 from oyun.spk_inceleme where durum='acik' and sirket_id=new.sirket_id
            and ((taraf1=new.alici and taraf2=new.satici) or (taraf1=new.satici and taraf2=new.alici))) then return new; end if;
  if oyun.bagli_hesap_mi(new.alici,new.satici) then
    v_tur := 'bagli_hesap';
  elsif exists(select 1 from oyun.borsa_islem b where b.sirket_id=new.sirket_id and b.alici=new.satici and b.satici=new.alici
               and b.zaman > t - interval '48 hours' and b.id<>new.id) then
    v_tur := 'karsilikli_islem';
  else
    return new;
  end if;
  k := jsonb_build_object('islem_id',new.id,'pay',new.pay,'birim',new.birim,'tutar',new.tutar,
       'iliskili_tutar',(select coalesce(sum(tutar),0) from oyun.borsa_islem b where b.sirket_id=new.sirket_id and b.zaman>t-interval '7 days'
                          and ((b.alici=new.alici and b.satici=new.satici) or (b.alici=new.satici and b.satici=new.alici))));
  insert into oyun.spk_inceleme(sirket_id,taraf1,taraf2,tur,kanit,bas,bit) values(new.sirket_id,new.alici,new.satici,v_tur,k,t,t+interval '72 hours');
  select ad into sad from oyun.sirketler where id=new.sirket_id;
  perform oyun.olay('ekonomi', format('SPK, %s hisselerinde olağandışı işlemler tespit etti ve inceleme başlattı.', sad), null, null, t);
  perform oyun.bildir(new.alici, format('SPK, %s hisselerindeki işlemin hakkında inceleme başlattı. Karar 72 saat içinde.', sad), t);
  perform oyun.bildir(new.satici, format('SPK, %s hisselerindeki işlemin hakkında inceleme başlattı. Karar 72 saat içinde.', sad), t);
  return new;
end $$;

drop trigger if exists spk_emir on oyun.borsa_emir;
create trigger spk_emir before insert on oyun.borsa_emir for each row execute function oyun.tg_spk_emir();
drop trigger if exists spk_islem_once on oyun.borsa_islem;
create trigger spk_islem_once before insert on oyun.borsa_islem for each row execute function oyun.tg_spk_islem_once();
drop trigger if exists spk_gozetim on oyun.borsa_islem;
create trigger spk_gozetim after insert on oyun.borsa_islem for each row execute function oyun.tg_spk_gozetim();

create or replace function oyun.spk_sonuclandir(p_id bigint, p_ceza boolean, p_karar_veren uuid, p_not text, t timestamptz) returns void language plpgsql set search_path to '' as $$
declare i oyun.spk_inceleme; tutar numeric; c numeric; odenen numeric; u uuid; sad text; toplam numeric := 0;
begin
  select * into i from oyun.spk_inceleme where id=p_id and durum='acik' for update;
  if i.id is null then return; end if;
  select ad into sad from oyun.sirketler where id=i.sirket_id;
  if p_ceza then
    tutar := greatest(coalesce((i.kanit->>'iliskili_tutar')::numeric,(i.kanit->>'tutar')::numeric,0), coalesce((i.kanit->>'tutar')::numeric,0));
    c := greatest(10000, round(tutar*0.20));
    foreach u in array array_remove(array[i.taraf1,i.taraf2],null) loop
      odenen := oyun.tahsil_et(u, c, false, format('SPK idari para cezası (%s, inceleme #%s)', coalesce(sad,'borsa'), i.id), t);
      toplam := toplam + coalesce(odenen,0);
      insert into oyun.spk_yasak(user_id,bit,neden) values(u,t+interval '7 days',format('SPK inceleme #%s',i.id))
        on conflict (user_id) do update set bit=greatest(oyun.spk_yasak.bit,excluded.bit), neden=excluded.neden;
      perform oyun.bildir(u, format('SPK kararı: %s hisselerindeki işlemlerin piyasa dolandırıcılığı sayıldı. %s ₺ idari para cezası ve 7 gün borsa işlem yasağı.', coalesce(sad,'—'), oyun.tl(c)), t);
    end loop;
    if toplam>0 then update oyun.ulke set hazine=hazine+toplam/oyun.pazar_tl_milyar() where id=1; end if;
    update oyun.spk_inceleme set durum='ceza', ceza=c, karar_veren=p_karar_veren, karar_not=p_not, karar_zaman=t where id=i.id;
    perform oyun.olay('ekonomi', format('SPK, %s hisselerinde işlem yapan %s hakkında ceza kararı verdi: kişi başı %s ₺ ve 7 gün işlem yasağı.', coalesce(sad,'—'),
       concat_ws(' ve ', oyun.kad(i.taraf1), case when i.taraf2 is not null then oyun.kad(i.taraf2) end), oyun.tl(c)), null, null, t);
    perform oyun.gazete_ekle('icraat', 'SPK''dan borsa cezası', format('Sermaye Piyasası Kurulu, %s hisselerindeki şüpheli işlemlerle ilgili incelemesini cezayla sonuçlandırdı.', coalesce(sad,'—')), i.id, t);
  else
    update oyun.spk_inceleme set durum='beraat', karar_veren=p_karar_veren, karar_not=p_not, karar_zaman=t where id=i.id;
    foreach u in array array_remove(array[i.taraf1,i.taraf2],null) loop
      perform oyun.bildir(u, format('SPK, %s hisselerindeki işlemlerin hakkındaki incelemeyi kapattı; ihlal bulunmadı.', coalesce(sad,'—')), t);
    end loop;
  end if;
end $$;

create or replace function public.spk_inceleme_ac(p_sirket bigint, p_kad text, p_aciklama text) returns jsonb language plpgsql security definer set search_path to '' as $$
declare p oyun.profiller := oyun.profilim(); h oyun.profiller; t timestamptz := oyun.simdi(); s oyun.sirketler; v_tutar numeric;
begin
  if oyun.bakanlik_yetkilisi('maliye') is distinct from p.id then raise exception 'SPK incelemesini Hazine ve Maliye Bakanı başlatır (bakanlık boşsa yürütme başı).'; end if;
  select * into s from oyun.sirketler where id=p_sirket and aktif and halka_acik;
  if s.id is null then raise exception 'Borsada işlem gören şirket bulunamadı.'; end if;
  h := oyun.profil_bul(p_kad);
  select coalesce(sum(tutar),0) into v_tutar from oyun.borsa_islem where sirket_id=s.id and (alici=h.id or satici=h.id) and zaman>t-interval '14 days';
  if v_tutar=0 then raise exception 'Bu oyuncunun son 14 günde bu şirkette borsa işlemi yok.'; end if;
  if exists(select 1 from oyun.spk_inceleme where durum='acik' and sirket_id=s.id and (taraf1=h.id or taraf2=h.id)) then raise exception 'Bu konuda açık inceleme zaten var.'; end if;
  if (select count(*) from oyun.spk_inceleme where acan=p.id and bas>t-interval '24 hours')>=3 then raise exception 'Günde en fazla 3 inceleme başlatılabilir.'; end if;
  update oyun.bakanlik_kasa set kasa=kasa-0.5 where kod='maliye' and kasa>=0.5;
  if not found then raise exception 'Maliye Bakanlığı kasasında 0,5 milyar ₺ gerekli.'; end if;
  insert into oyun.spk_inceleme(sirket_id,taraf1,tur,kanit,acan,bas,bit)
    values(s.id,h.id,'manipulasyon',jsonb_build_object('tutar',v_tutar,'iliskili_tutar',v_tutar,'iddia',left(coalesce(p_aciklama,''),500)),p.id,t,t+interval '72 hours');
  perform oyun.bildir(h.id, format('SPK, %s hisselerindeki işlemlerin hakkında manipülasyon incelemesi başlattı.', s.ad), t);
  perform oyun.olay('ekonomi', format('SPK, %s hisselerinde manipülasyon iddiasıyla inceleme başlattı.', s.ad), null, p.parti_id, t);
  return public.spk_ekrani();
end $$;

create or replace function public.spk_karar(p_id bigint, p_ceza boolean, p_not text default null) returns jsonb language plpgsql security definer set search_path to '' as $$
declare p oyun.profiller := oyun.profilim();
begin
  if oyun.bakanlik_yetkilisi('maliye') is distinct from p.id then raise exception 'SPK kararını Hazine ve Maliye Bakanı verir.'; end if;
  if not exists(select 1 from oyun.spk_inceleme where id=p_id and durum='acik') then raise exception 'Açık inceleme bulunamadı.'; end if;
  if exists(select 1 from oyun.spk_inceleme where id=p_id and (taraf1=p.id or taraf2=p.id)) then raise exception 'Taraf olduğun incelemede karar veremezsin.'; end if;
  perform oyun.spk_sonuclandir(p_id, p_ceza, p.id, left(nullif(btrim(p_not),''),500), oyun.simdi());
  return public.spk_ekrani();
end $$;

create or replace function public.spk_ekrani() returns jsonb language plpgsql security definer set search_path to '' as $$
declare me uuid := oyun.ben();
begin
  return jsonb_build_object(
    'yetkili', oyun.bakanlik_yetkilisi('maliye') is not distinct from me and me is not null,
    'yasagim', (select bit from oyun.spk_yasak where user_id=me and bit>oyun.simdi()),
    'sirketler', coalesce((select jsonb_agg(jsonb_build_object('id',id,'ad',ad) order by ad) from oyun.sirketler where aktif and halka_acik),'[]'::jsonb),
    'incelemeler', coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'sirket',s.ad,'sirket_id',i.sirket_id,'taraf1',oyun.kad(i.taraf1),
        'taraf2',case when i.taraf2 is null then null else oyun.kad(i.taraf2) end,'tur',i.tur,
        'tur_ad',case i.tur when 'bagli_hesap' then 'Bağlantılı hesaplar arası işlem' when 'karsilikli_islem' then 'Karşılıklı al-sat (fiyat şişirme şüphesi)' else 'Manipülasyon iddiası' end,
        'tutar',i.kanit->>'iliskili_tutar','iddia',i.kanit->>'iddia','acan',case when i.acan is null then 'Otomatik gözetim' else oyun.kad(i.acan) end,
        'taraf_benim', i.taraf1=me or i.taraf2=me,
        'bas',i.bas,'bit',i.bit,'durum',i.durum,'ceza',i.ceza,'karar_not',i.karar_not) order by i.bas desc)
      from (select * from oyun.spk_inceleme order by bas desc limit 40) i left join oyun.sirketler s on s.id=i.sirket_id),'[]'::jsonb),
    'kural','Bağlantılı hesaplar arasındaki veya 48 saat içinde karşılıklı yapılan hisse işlemleri otomatik incelemeye alınır. Hazine ve Maliye Bakanı 72 saat içinde karar verir; verilmezse bağlantılı hesap vakaları cezayla, diğerleri beraatle kapanır. Ceza: işlem tutarının %20''si (en az 10.000 ₺) ve 7 gün işlem yasağı.'
  );
end $$;

create or replace function oyun.spk_tick(t timestamptz) returns void language plpgsql set search_path to '' as $$
declare r record;
begin
  for r in select id, tur from oyun.spk_inceleme where durum='acik' and bit<=t order by bit limit 100 loop
    perform oyun.spk_sonuclandir(r.id, r.tur='bagli_hesap', null, 'Süre doldu: kurul otomatik karar verdi.', t);
  end loop;
  delete from oyun.spk_yasak where bit < t - interval '30 days';
end $$;

-- ------------------------------------------------------------ Konkordato / iflas
create table if not exists oyun.sirket_konkordato(
  id bigserial primary key, sirket_id bigint not null references oyun.sirketler(id), bas timestamptz not null, bit timestamptz not null,
  durum text not null default 'surec' check (durum in ('surec','kurtuldu','iflas')),
  baslatan uuid, baslangic_kasa numeric, sonuc_zaman timestamptz
);
create unique index if not exists konkordato_tek on oyun.sirket_konkordato(sirket_id) where durum='surec';
revoke all on oyun.sirket_konkordato from anon, authenticated;
alter table oyun.sirket_konkordato enable row level security;

create or replace function oyun.konkordato_baslat(p_sirket bigint, p_baslatan uuid, t timestamptz) returns void language plpgsql set search_path to '' as $$
declare s oyun.sirketler; x record;
begin
  select * into s from oyun.sirketler where id=p_sirket for update;
  if s.id is null or not s.aktif or s.kasa>=0 or s.sektor='banka' then return; end if;
  if exists(select 1 from oyun.sirket_konkordato where sirket_id=s.id and durum='surec') then return; end if;
  insert into oyun.sirket_konkordato(sirket_id,bas,bit,baslatan,baslangic_kasa) values(s.id,t,t+interval '14 days',p_baslatan,s.kasa);
  for x in select user_id from oyun.sirket_ortaklari where sirket_id=s.id loop
    perform oyun.bildir(x.user_id, format('%s konkordato sürecine girdi: kasa açığı %s ₺. 14 gün içinde sermaye artırımıyla açık kapatılmazsa şirket iflas eder ve paylar değersizleşir.', s.ad, oyun.tl(-s.kasa)), t);
  end loop;
  perform oyun.olay('ekonomi', format('%s konkordato ilan etti (kasa açığı %s ₺).', s.ad, oyun.tl(-s.kasa)), null, null, t);
  perform oyun.gazete_ekle('icraat', format('%s konkordato ilan etti', s.ad),
    format('Borç yükü altındaki %s, alacaklılardan koruma için konkordato süreci başlattı. Ortakların 14 gün içinde sermaye koyması bekleniyor.', s.ad), s.id, t);
end $$;

create or replace function public.sirket_konkordato_ilan(p_sirket bigint) returns jsonb language plpgsql security definer set search_path to '' as $$
declare p oyun.profiller := oyun.profilim(); s oyun.sirketler; t timestamptz := oyun.simdi();
begin
  select * into s from oyun.sirketler where id=p_sirket;
  if s.id is null or not s.aktif then raise exception 'Şirket bulunamadı.'; end if;
  if not oyun.sirket_yonetici_mi(s.id,p.id) then raise exception 'Konkordatoyu şirketin yöneticisi (en büyük ortak) ilan eder.'; end if;
  if s.sektor='banka' then raise exception 'Bankalar konkordato ilan edemez.'; end if;
  if s.kasa>=0 then raise exception 'Kasası artıda olan şirket konkordato ilan edemez.'; end if;
  if exists(select 1 from oyun.sirket_konkordato where sirket_id=s.id and durum='surec') then raise exception 'Şirket zaten konkordato sürecinde.'; end if;
  perform oyun.konkordato_baslat(s.id,p.id,t);
  return public.konkordato_durum(s.id);
end $$;

create or replace function public.konkordato_durum(p_sirket bigint default null) returns jsonb language plpgsql security definer set search_path to '' as $$
begin
  return coalesce((select jsonb_agg(jsonb_build_object('id',k.id,'sirket_id',k.sirket_id,'sirket',s.ad,'bas',k.bas,'bit',k.bit,'durum',k.durum,
      'kasa',s.kasa,'baslangic_kasa',k.baslangic_kasa,'sonuc_zaman',k.sonuc_zaman) order by k.bas desc)
    from oyun.sirket_konkordato k join oyun.sirketler s on s.id=k.sirket_id
    where (p_sirket is null and (k.durum='surec' or k.bas>oyun.simdi()-interval '30 days')) or k.sirket_id=p_sirket),'[]'::jsonb);
end $$;

-- Ekran: tüm süreçler + yönettiğim, kasası eksideki şirketler
create or replace function public.konkordato_ekrani() returns jsonb language plpgsql security definer set search_path to '' as $$
declare me uuid := oyun.ben();
begin
  return jsonb_build_object(
    'surecler', public.konkordato_durum(null),
    'riskli', coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'ad',s.ad,'kasa',s.kasa,'sermaye',s.sermaye,
        'surecte', exists(select 1 from oyun.sirket_konkordato k where k.sirket_id=s.id and k.durum='surec'),
        'otomatik_esik', round(-0.5*greatest(s.sermaye,1))) order by s.kasa)
      from oyun.sirketler s where s.aktif and s.kasa<0 and s.sektor<>'banka' and oyun.sirket_yonetici_mi(s.id,me)),'[]'::jsonb),
    'kural','Kasası eksiye düşen şirketin yöneticisi konkordato ilan edebilir; açık sermayenin yarısını geçerse süreç kendiliğinden başlar. 14 gün içinde ortaklar sermaye artırımıyla kasayı artıya çekerse şirket kurtulur; çekemezse iflas eder, hisseler borsadan çıkar ve paylar değersizleşir. Bankalar kapsam dışıdır.'
  );
end $$;

create or replace function oyun.konkordato_tick(t timestamptz) returns void language plpgsql set search_path to '' as $$
declare r record; k oyun.sirket_konkordato; s oyun.sirketler; x record;
begin
  for r in select sx.id from oyun.sirketler sx where sx.aktif and sx.sektor<>'banka' and sx.kasa < -0.5*greatest(sx.sermaye,1)
            and not exists(select 1 from oyun.sirket_konkordato kx where kx.sirket_id=sx.id and kx.durum='surec') limit 50 loop
    perform oyun.konkordato_baslat(r.id,null,t);
  end loop;
  for k in select * from oyun.sirket_konkordato kk where kk.durum='surec' and kk.bit<=t order by kk.bit for update loop
    select * into s from oyun.sirketler sx where sx.id=k.sirket_id for update;
    if s.kasa>=0 or not s.aktif then
      update oyun.sirket_konkordato set durum='kurtuldu', sonuc_zaman=t where id=k.id;
      if s.aktif then
        perform oyun.olay('ekonomi', format('%s konkordatodan başarıyla çıktı.', s.ad), null, null, t);
        for x in select o.user_id from oyun.sirket_ortaklari o where o.sirket_id=s.id loop
          perform oyun.bildir(x.user_id, format('%s konkordatodan çıktı; şirket faaliyetine devam ediyor.', s.ad), t);
        end loop;
      end if;
      continue;
    end if;
    if exists(select 1 from oyun.halka_arz h where h.sirket_id=s.id and h.durum='acik') then continue; end if;
    update oyun.borsa_emir e set durum='iptal' where e.sirket_id=s.id and e.durum='acik';
    begin
      update oyun.sirket_hisse_ilanlari i set durum='iptal', kapanis=t where i.sirket_id=s.id and i.kapanis is null;
    exception when others then null; end;
    update oyun.sirketler sx set aktif=false, halka_acik=false, satilik=null where sx.id=s.id;
    update oyun.sirket_konkordato kx set durum='iflas', sonuc_zaman=t where kx.id=k.id;
    for x in select o.user_id from oyun.sirket_ortaklari o where o.sirket_id=s.id loop
      perform oyun.bildir(x.user_id, format('%s iflas etti. Konkordato süresinde açık (%s ₺) kapatılamadı; payların değersiz hâle geldi.', s.ad, oyun.tl(-s.kasa)), t);
    end loop;
    perform oyun.olay('ekonomi', format('%s iflas etti; şirket tasfiye edildi.', s.ad), null, null, t);
    perform oyun.gazete_ekle('icraat', format('%s iflas etti', s.ad),
      format('Konkordato süresinde borçlarını yapılandıramayan %s için iflas kararı verildi. Hisseler borsadan çıkarıldı.', s.ad), s.id, t);
    update oyun.pazar_ayar pa set endeks=round(pa.endeks*0.995,4) where pa.id=1;
  end loop;
end $$;

-- ------------------------------------------------------------ motor
create or replace function oyun.ekonomi2_tick() returns void language plpgsql security definer set search_path to '' as $$
declare t timestamptz := oyun.simdi();
begin
  if not pg_try_advisory_xact_lock(424250) then return; end if;
  perform oyun.merkez_bankasi_tick(t);
  perform oyun.belediye_tahvil_tick(t);
  perform oyun.spk_tick(t);
  perform oyun.konkordato_tick(t);
end $$;

-- ------------------------------------------------------------ yetkiler
revoke all on function public.tcmb_baskan_ata(text), public.tcmb_teklif_yanit(bigint,boolean), public.tcmb_baskan_gorevden_al(),
  public.ppk_faiz_karari(numeric,text), public.merkez_bankasi(),
  public.belediye_tahvil_ihrac(numeric,numeric,int), public.belediye_tahvil_al(bigint,numeric), public.belediye_tahvilleri(),
  public.spk_inceleme_ac(bigint,text,text), public.spk_karar(bigint,boolean,text), public.spk_ekrani(),
  public.sirket_konkordato_ilan(bigint), public.konkordato_durum(bigint), public.konkordato_ekrani() from public, anon;
grant execute on function public.tcmb_baskan_ata(text), public.tcmb_teklif_yanit(bigint,boolean), public.tcmb_baskan_gorevden_al(),
  public.ppk_faiz_karari(numeric,text), public.merkez_bankasi(),
  public.belediye_tahvil_ihrac(numeric,numeric,int), public.belediye_tahvil_al(bigint,numeric), public.belediye_tahvilleri(),
  public.spk_inceleme_ac(bigint,text,text), public.spk_karar(bigint,boolean,text), public.spk_ekrani(),
  public.sirket_konkordato_ilan(bigint), public.konkordato_durum(bigint), public.konkordato_ekrani() to authenticated;
-- Çevrimiçi oyuncular: genel sohbetle aynı 5 dakikalık eşik.
-- Yeni salt okunur RPC; oyuncu verisine dokunmaz.
create or replace function public.cevrimici_oyuncular()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  t timestamptz := oyun.simdi();
  sonuc jsonb;
begin
  perform oyun.profilim();
  select jsonb_build_object(
    'cevrimici', count(*),
    'oyuncular', coalesce(jsonb_agg(
      jsonb_build_object(
        'kad', q.kad,
        'il', q.il_ad,
        'parti', q.parti_kisa,
        'renk', q.parti_renk
      ) order by lower(q.kad), q.kad
    ), '[]'::jsonb)
  )
  into sonuc
  from (
    select p.kad, il.ad as il_ad, pa.kisa as parti_kisa, pa.renk as parti_renk
    from oyun.profiller p
    left join oyun.iller il on il.id = p.il_id
    left join oyun.partiler pa on pa.id = p.parti_id
    where not p.yasakli and p.son_gorulme > t - interval '5 minutes'
  ) q;
  return sonuc;
end;
$$;
revoke all on function public.cevrimici_oyuncular() from public;
revoke execute on function public.cevrimici_oyuncular() from anon;
grant execute on function public.cevrimici_oyuncular() to authenticated;
-- =====================================================================
--  76 · GENEL SEÇİM SAYIM HATASI: "column reference l.aday_id is ambiguous"
--
--  KÖK NEDEN: oyun._sonuc_mv (56 ve 72) içinde plpgsql döngü değişkeni "l" ile,
--  bağımsız adayları seçen SQL ifadesindeki tablo takma adı "l" (from _b23_liste l)
--  çakışıyor. PostgreSQL bunu ilk çalıştırmada "column reference "l.aday_id" is
--  ambiguous" diye reddeder ve sayım hiç tamamlanmaz.
--  Canlıda bugüne kadar görünmedi çünkü "her aday vekil" test modu AÇIK
--  (oyun.mv_secim_modu): o modda oyun._sonuc_mv_test çalışır ve bu yola hiç girilmez.
--  Test modu kapatıldığı anda (gerçek oyuncular için kapatılacak) genel seçim,
--  1 Kasım dahil, sayılamazdı ve oyun motoru sonucu yazamazdı.
--
--  DÜZELTME: yalnızca o ifadenin takma adı "bl" yapıldı. Fonksiyonun geri kalanı,
--  canlıda çalışan sürümle (72_parti_birlesme_ortak_mv_listesi) birebir aynıdır.
--  Oyuncu verisine dokunmaz; iki kez çalıştırılabilir.
-- =====================================================================
CREATE OR REPLACE FUNCTION oyun._sonuc_mv(s oyun.secimler)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  baraj numeric:=(select baraj from oyun.ayarlar where id=1);
  onsecim oyun.secimler;
  toplam bigint;
  il record;
  l record;
  k int;
  ana bigint;
  iller_j jsonb:='{}'::jsonb;
  ilj jsonb;
  bos int:=0;
  dolu int:=0;
  sandalye_top int;
  bag_oy bigint;
  bag_sandalye int;
begin
  -- Geçici düşük oyuncu sayısı test modu: her kesinleşmiş aday seçilir.
  if exists (select 1 from oyun.mv_secim_modu where id = 1 and her_aday_vekil) then
    return oyun._sonuc_mv_test(s);
  end if;
  select * into onsecim from oyun.secimler where tur='mv_on' and donem=s.donem;
  select count(*) into toplam from oyun.oylar where secim_id=s.id;
  sandalye_top:=coalesce((select sum(mv_secim) from oyun.iller),600);

  create temp table if not exists _b23_ulusal(
    parti_id bigint primary key,
    oy bigint,
    yuzde numeric,
    gecti boolean,
    sandalye int default 0
  ) on commit drop;
  delete from _b23_ulusal;

  insert into _b23_ulusal(parti_id,oy)
  select parti_id,count(*)
  from oyun.oylar
  where secim_id=s.id and parti_id is not null
  group by parti_id;

  update _b23_ulusal
  set yuzde=case when toplam>0 then round(oy*100.0/toplam,2) else 0 end;

  update _b23_ulusal u
  set gecti=(coalesce(u.oy*100.0/nullif(toplam,0),0)>=baraj) or coalesce((
    select sum(u2.oy)*100.0/nullif(toplam,0)>=baraj
    from oyun.ittifak_uyeler iu
    join oyun.ittifak_uyeler iu2 on iu2.ittifak_id=iu.ittifak_id
    join _b23_ulusal u2 on u2.parti_id=iu2.parti_id
    where iu.parti_id=u.parti_id
  ),false);

  create temp table if not exists _b23_kaz(
    user_id uuid,
    il_id smallint,
    parti_id bigint,
    aday_id bigint
  ) on commit drop;
  delete from _b23_kaz;

  create temp table if not exists _b23_liste(
    anahtar bigint primary key,
    parti_id bigint,
    aday_id bigint,
    oy bigint,
    lim int,
    kaz int default 0
  ) on commit drop;

  for il in select * from oyun.iller order by id loop
    delete from _b23_liste;

    insert into _b23_liste(anahtar,parti_id,aday_id,oy,lim)
    select x.parti_id,x.parti_id,null,x.oy,x.lim
    from (
      select v.lider as parti_id,
             count(*)::bigint oy,
             (select count(*)
              from oyun.adaylar a
              where a.secim_id=onsecim.id
                and a.il_id=il.id
                and a.parti_id is not null
                and oyun.mv_ortak_liste_partisi(s.id,il.id,a.parti_id)=v.lider
                and a.sira is not null)::int lim
      from (
        select oyun.mv_ortak_liste_partisi(s.id,il.id,o.parti_id) as lider
        from oyun.oylar o
        join _b23_ulusal u on u.parti_id=o.parti_id and u.gecti
        where o.secim_id=s.id and o.il_id=il.id and o.parti_id is not null
      ) v
      group by v.lider
    ) x
    where x.lim>0 and x.oy>0;

    insert into _b23_liste(anahtar,parti_id,aday_id,oy,lim)
    select -a.id,null,a.id,count(o.*)::bigint,1
    from oyun.adaylar a
    join oyun.oylar o
      on o.secim_id=s.id and o.aday_id=a.id
    where a.secim_id=s.id
      and a.parti_id is null
      and a.il_id=il.id
    group by a.id
    having count(o.*)>0;

    for k in 1..coalesce(il.mv_secim,il.mv) loop
      ana:=null;
      select anahtar into ana
      from _b23_liste
      where kaz<lim and oy>0
      order by oy::numeric/(kaz+1) desc,oy desc,anahtar
      limit 1;
      exit when ana is null;
      update _b23_liste set kaz=kaz+1 where anahtar=ana;
    end loop;

    for l in select * from _b23_liste where parti_id is not null and kaz>0 loop
      insert into _b23_kaz(user_id,il_id,parti_id,aday_id)
      select a.user_id,il.id,a.parti_id,a.id
      from oyun.adaylar a
      where a.secim_id=onsecim.id
        and a.il_id=il.id
        and a.parti_id is not null
        and oyun.mv_ortak_liste_partisi(s.id,il.id,a.parti_id)=l.parti_id
        and a.sira is not null
      order by a.sira, case when a.parti_id=l.parti_id then 0 else 1 end, a.id
      limit l.kaz;
    end loop;

    insert into _b23_kaz(user_id,il_id,parti_id,aday_id)
    select a.user_id,il.id,null,a.id
    from _b23_liste bl
    join oyun.adaylar a on a.id=bl.aday_id
    where bl.parti_id is null and bl.kaz>0;

    select jsonb_build_object(
      'gecerli',(select count(*) from oyun.oylar where secim_id=s.id and il_id=il.id),
      'partiler',coalesce((
        select jsonb_object_agg(o.parti_id::text,jsonb_build_object(
          'oy',o.n,
          'sandalye',(select count(*) from _b23_kaz z where z.il_id=il.id and z.parti_id=o.parti_id)
        ))
        from (
          select parti_id,count(*) n
          from oyun.oylar
          where secim_id=s.id and il_id=il.id and parti_id is not null
          group by parti_id
        ) o
      ),'{}'::jsonb),
      'bagimsizlar',coalesce((
        select jsonb_agg(jsonb_build_object(
          'aday_id',a.id,
          'kad',pr.kad,
          'oy',(select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id),
          'sandalye',case when exists(select 1 from _b23_kaz z where z.aday_id=a.id) then 1 else 0 end
        ) order by (select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id) desc,a.id)
        from oyun.adaylar a
        join oyun.profiller pr on pr.id=a.user_id
        where a.secim_id=s.id and a.parti_id is null and a.il_id=il.id
      ),'[]'::jsonb),
      'secilen',coalesce((
        select jsonb_agg(jsonb_build_object(
          'kad',pr.kad,
          'parti_id',z.parti_id,
          'bagimsiz',z.parti_id is null
        ) order by z.parti_id nulls last,pr.kad)
        from _b23_kaz z
        join oyun.profiller pr on pr.id=z.user_id
        where z.il_id=il.id
      ),'[]'::jsonb),
      'mv',coalesce(il.mv_secim,il.mv)
    ) into ilj;

    if (ilj->>'gecerli')::int>0 or jsonb_array_length(ilj->'secilen')>0 then
      iller_j:=iller_j||jsonb_build_object(il.id::text,ilj);
    end if;
  end loop;

  -- Sandalyeler liste sahibine değil, seçilen adayların kendi partilerine yazılır.
  update _b23_ulusal u set sandalye=(select count(*) from _b23_kaz z where z.parti_id=u.parti_id);

  insert into oyun.kazananlar(secim_id,user_id,il_id,parti_id)
  select s.id,user_id,il_id,parti_id from _b23_kaz
  on conflict do nothing;

  select count(*) into dolu from _b23_kaz;
  bos:=sandalye_top-dolu;
  select count(*) into bag_oy
  from oyun.oylar where secim_id=s.id and parti_id is null and aday_id is not null;
  select count(*) into bag_sandalye
  from _b23_kaz where parti_id is null;

  perform oyun.olay(
    'secim',
    format('Genel seçim sonuçlandı: %s oy kullanıldı, %s sandalye doldu, %s sandalye boş kaldı.',toplam,dolu,bos),
    null,null,s.sonuc_at
  );

  return jsonb_build_object(
    'toplam',toplam,
    'baraj',baraj,
    'sandalye_toplam',sandalye_top,
    'dolu',dolu,
    'bos',bos,
    'bagimsiz_oy',bag_oy,
    'bagimsiz_sandalye',bag_sandalye,
    'bagimsizlar',coalesce((
      select jsonb_agg(jsonb_build_object(
        'aday_id',a.id,
        'kad',pr.kad,
        'il_id',a.il_id,
        'oy',(select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id),
        'sandalye',case when exists(select 1 from _b23_kaz z where z.aday_id=a.id) then 1 else 0 end
      ) order by (select count(*) from oyun.oylar o where o.secim_id=s.id and o.aday_id=a.id) desc,a.id)
      from oyun.adaylar a
      join oyun.profiller pr on pr.id=a.user_id
      where a.secim_id=s.id and a.parti_id is null
    ),'[]'::jsonb),
    'ulusal',coalesce((
      select jsonb_agg(jsonb_build_object(
        'parti_id',u.parti_id,
        'kisa',p.kisa,
        'ad',p.ad,
        'renk',p.renk,
        'oy',u.oy,
        'yuzde',u.yuzde,
        'gecti',u.gecti,
        'sandalye',u.sandalye
      ) order by u.oy desc)
      from _b23_ulusal u
      join oyun.partiler p on p.id=u.parti_id
    ),'[]'::jsonb),
    'iller',iller_j
  );
end $function$
;
-- 2026-10-13 · Genel başkan yardımcılığı parti içi ek bir görevdir.
-- Belediye başkanı, milletvekili, bakan, cumhurbaşkanı ve CB yardımcısı
-- mevcut makamını kaybetmeden kendi partisinin GBY'si atanabilir.
-- TBMM Başkanı ve TBMM Başkanvekili için mevcut ayrılık kuralı korunur.
-- Bu migration oyunculara yeni görev ATAMAZ; yalnız atama kuralını düzeltir.

create or replace function oyun.rol_uyumlu(a text, b text)
returns boolean language sql immutable set search_path = '' as $$
  select (a='bakan' or b='bakan')
    or (a=b and a in ('gb','gby'))
    or (a,b) in (
       ('mv','gby'),('gby','mv'),
       ('gb','mv'),('mv','gb'),
       ('gb','cb'),('cb','gb'),
       ('mv','tbmm'),('tbmm','mv'),
       ('mv','bskv'),('bskv','mv'),
       ('mv','grup_bskv'),('grup_bskv','mv'),
       ('gby','grup_bskv'),('grup_bskv','gby'),
       ('bel','gby'),('gby','bel'),
       ('cb','gby'),('gby','cb'),
       ('cb_yardimcisi','gby'),('gby','cb_yardimcisi')
    );
$$;

-- Yetkiyi sadece mevcut parti genel başkanı kullanabilir.
-- Aynı kullanıcı iki GBY sırasını dolduramaz; mevcut makamına dokunulmaz.
create or replace function public.gby_ata(p_sira integer, p_kad text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  p oyun.profiller := oyun.profilim();
  hedef oyun.profiller;
  pa oyun.partiler;
  eski uuid;
  cakisma text;
begin
  select * into pa from oyun.partiler where id=p.parti_id for update;
  if pa.id is null or pa.kapali or pa.gb is distinct from p.id then
    raise exception 'Yalnızca görevdeki parti genel başkanı yardımcı atayabilir.';
  end if;
  if p_sira is null or p_sira not between 1 and 6 then
    raise exception 'Geçersiz sıra (1-6).';
  end if;

  select user_id into eski
  from oyun.parti_gby where parti_id=pa.id and sira=p_sira;

  if coalesce(btrim(p_kad),'')='' then
    delete from oyun.parti_gby where parti_id=pa.id and sira=p_sira;
    if eski is not null then
      perform oyun.bildir(eski,format('%s genel başkan yardımcılığı görevin sona erdi.',pa.kisa));
    end if;
    return public.durum();
  end if;

  select * into hedef from oyun.profiller
  where lower(kad)=lower(btrim(p_kad));
  if hedef.id is null or hedef.parti_id is distinct from pa.id then
    raise exception 'Bu kişi partinin üyesi değil.';
  end if;
  if hedef.id=p.id then raise exception 'Kendini yardımcı atayamazsın.'; end if;
  if coalesce(hedef.yasakli,false) then
    raise exception 'Kısıtlanmış oyuncu genel başkan yardımcısı atanamaz.';
  end if;
  cakisma:=oyun.rol_cakisma(hedef.id,'gby');
  if cakisma is not null then
    raise exception '% şu anda % görevinde; bu görev genel başkan yardımcılığıyla birleştirilemez.',hedef.kad,cakisma;
  end if;
  if eski=hedef.id then return public.durum(); end if;

  delete from oyun.parti_gby
  where parti_id=pa.id and (sira=p_sira or user_id=hedef.id);
  insert into oyun.parti_gby(parti_id,sira,user_id,atama)
  values(pa.id,p_sira,hedef.id,oyun.simdi());

  if eski is not null then
    perform oyun.bildir(eski,format('%s genel başkan yardımcılığı görevin sona erdi.',pa.kisa));
  end if;
  perform oyun.bildir(hedef.id,format('%s Genel Başkanı seni genel başkan yardımcısı olarak atadı.',pa.kisa));
  perform oyun.olay('parti',format('%s, %s genel başkan yardımcılığına atandı.',hedef.kad,pa.kisa),null,pa.id);
  return public.durum();
end $$;

-- İşlem içi regresyon kontrolleri: makam uyumu ve korunacak istisnalar.
do $$
begin
  if not oyun.rol_uyumlu('bel','gby')
     or not oyun.rol_uyumlu('gby','bel')
     or not oyun.rol_uyumlu('mv','gby')
     or not oyun.rol_uyumlu('bakan','gby')
     or not oyun.rol_uyumlu('cb','gby')
     or not oyun.rol_uyumlu('cb_yardimcisi','gby') then
    raise exception 'GBY makam uyumluluğu testi başarısız';
  end if;
  if oyun.rol_uyumlu('gb','gby') or oyun.rol_uyumlu('tbmm','gby')
     or oyun.rol_uyumlu('bskv','gby') or oyun.rol_uyumlu('bel','mv') then
    raise exception 'GBY ayrı tutulacak makam kontrolü başarısız';
  end if;
end $$;
-- 97: Manipülasyona karşı kalıcı borsa fiyat tescili ve hacimli fiyat keşfi.
-- Tarihsel CELAL işlemleriyle ilgili düzeltmeler yalnızca 20261014 özel migrationlarında.
create table if not exists oyun.borsa_fiyat_referans (
  sirket_id bigint primary key references oyun.sirketler(id),
  fiyat numeric not null check (fiyat > 0),
  ilk_fiyat numeric not null check (ilk_fiyat > 0),
  ilk_koruma timestamptz not null default now(),
  son_fiyat_guncelleme timestamptz not null default now(),
  gerekce text not null default 'Korunmuş piyasa fiyatı'
);
create table if not exists oyun.borsa_fiyat_gecmis (
  id bigint generated always as identity primary key,
  sirket_id bigint not null references oyun.sirketler(id),
  fiyat numeric not null check (fiyat > 0),
  zaman timestamptz not null default now(),
  gerekce text not null
);
create index if not exists borsa_fiyat_gecmis_idx on oyun.borsa_fiyat_gecmis(sirket_id,zaman desc,id desc);
create index if not exists borsa_islem_fiyat_koruma_idx on oyun.borsa_islem(sirket_id,zaman desc);

create table if not exists oyun.borsa_supheli_islem (
  islem_id bigint primary key references oyun.borsa_islem(id),
  sirket_id bigint not null references oyun.sirketler(id),
  bulgu text not null,
  kayit_zamani timestamptz not null default now()
);


-- Geriden yükseltmede ilk defa halka açık her şirketin son borsa fiyatını güvenceye al.
-- Her zaman ON CONFLICT DO NOTHING: önceden düzeltilmiş fiyatlara dokunmaz.
insert into oyun.borsa_fiyat_referans(sirket_id,fiyat,ilk_fiyat,gerekce)
select s.id,
       greatest(1,coalesce(oyun.borsa_son_fiyat(s.id),round(s.sermaye/100))),
       greatest(1,coalesce(oyun.borsa_son_fiyat(s.id),round(s.sermaye/100))),
       'İlk sunucu tarafı onaylı fiyat kaydı'
from oyun.sirketler s where s.halka_acik
on conflict (sirket_id) do nothing;
insert into oyun.borsa_fiyat_gecmis(sirket_id,fiyat,gerekce)
select r.sirket_id,r.fiyat,'İlk onaylı fiyat kaydı'
from oyun.borsa_fiyat_referans r
where not exists (select 1 from oyun.borsa_fiyat_gecmis g where g.sirket_id=r.sirket_id);

-- Şirket bütünü asla son %0,1 pay işleminin tekil fiyatına göre değerlenemez.
-- Tarihsel karşılaştırma da onaylanmış fiyat geçmişini kullanır.
create or replace function oyun.borsa_son_fiyat(
  p_sirket bigint, t timestamptz default null
) returns numeric
language sql stable set search_path to ''
as $fn$
  select coalesce(
    (select h.fiyat from oyun.borsa_fiyat_gecmis h
     where h.sirket_id=p_sirket and (t is null or h.zaman<=t)
     order by h.zaman desc,h.id desc limit 1),
    (select r.fiyat from oyun.borsa_fiyat_referans r where r.sirket_id=p_sirket),
    (select round((h.deger+h.toplanan)/100) from oyun.halka_arz h
     where h.sirket_id=p_sirket and h.durum='tamam' order by h.id desc limit 1),
    (select round(greatest(s.sermaye,1)/100) from oyun.sirketler s where s.id=p_sirket)
  )
$fn$;

-- Her emir onaylanan fiyata göre SINIRLI; fiyat bandı ayarı kapatılsa bile açık kalır.
create or replace function oyun.tg_borsa_emir_bant()
returns trigger language plpgsql security definer set search_path to ''
as $fn$
declare f numeric; alt numeric; ust numeric;
begin
  f:=oyun.borsa_son_fiyat(new.sirket_id);
  if f is null or f<=0 then raise exception 'Şirket için fiyat referansı bulunamadı.'; end if;
  alt:=greatest(1,round(f*0.90));
  ust:=greatest(alt,round(f*1.10));
  if new.birim is null or new.birim<alt or new.birim>ust then
    raise exception 'Manipülasyon koruması: %%1 pay fiyatı % ₺ - % ₺ aralığında olmalı.', oyun.tl(alt), oyun.tl(ust);
  end if;
  return new;
end $fn$;

-- Emir listelendiği andaki bant yeterli değildir: alındığı anda da doğrulanır.
-- Aynı hesap, bağlantılı hesap, hızlı karşılıklı devir ve bant dışı fiyat reddedilir.
create or replace function oyun.tg_borsa_islem_koruma()
returns trigger language plpgsql security definer set search_path to ''
as $fn$
declare f numeric; alt numeric; ust numeric;
begin
  if new.satici is null or new.alici is null or new.satici=new.alici then
    raise exception 'Kendi hesabınla borsa işlemi yapamazsın.';
  end if;
  if oyun.bagli_hesap_mi(new.satici,new.alici) or oyun.iliskili(new.satici,new.alici) then
    raise exception 'Bağlantılı hesaplar arasında borsa işlemi yapılamaz.';
  end if;
  if exists (
    select 1 from oyun.borsa_islem i
    where i.sirket_id=new.sirket_id
      and i.satici=new.alici and i.alici=new.satici
      and i.zaman>now()-interval '7 days'
  ) then
    raise exception 'Karşılıklı pay devirleri 7 gün boyunca engellenir (SPK koruması).';
  end if;
  if exists (
    select 1 from oyun.borsa_islem i
    where i.sirket_id=new.sirket_id
      and i.satici=new.satici and i.alici=new.alici
      and i.zaman>now()-interval '12 hours'
  ) then
    raise exception 'Aynı iki hesap bu şirkette 12 saat içinde tekrar işlem yapamaz.';
  end if;
  f:=oyun.borsa_son_fiyat(new.sirket_id);
  if f is null or f<=0 then raise exception 'Fiyat referansı bulunamadı.'; end if;
  alt:=greatest(1,round(f*0.90)); ust:=greatest(alt,round(f*1.10));
  if new.birim<alt or new.birim>ust then
    raise exception 'Satış emri güncel güvenli fiyat bandının dışında; satıcının emri yenilemesi gerekir.';
  end if;
  return new;
end $fn$;

drop trigger if exists borsa_islem_ek_koruma on oyun.borsa_islem;
create trigger borsa_islem_ek_koruma before insert on oyun.borsa_islem
for each row execute function oyun.tg_borsa_islem_koruma();

-- Gerçek fiyat keşfi: son 24 saat içinde >= %2 pay, en az iki bağımsız
-- işlem (%0,5 pay altı fiyatı ASLA etkilemez) ve en az üç katılımcı.
-- Sadece GÜVENLİK SONRASI işlemler fiyat keşfine katılır.
-- Bir şirketin fiyatı 24 saatte en fazla bir kez ve en fazla %10 değişebilir.
create or replace function oyun.tg_borsa_fiyat_kesfi()
returns trigger language plpgsql security definer set search_path to ''
as $fn$
declare r oyun.borsa_fiyat_referans; v_pay numeric; v_fiyat numeric;
        v_islem int; v_alici int; v_satici int; v_kisi int;
        v_sermaye numeric; v_alt numeric; v_ust numeric; v_yeni numeric;
begin
  if new.pay<0.5 then return new; end if;
  select * into r from oyun.borsa_fiyat_referans where sirket_id=new.sirket_id for update;
  if r.sirket_id is null then return new; end if;
  if now() < r.son_fiyat_guncelleme+interval '24 hours' then return new; end if;

  with q as (
    select i.pay,i.birim,i.alici,i.satici from oyun.borsa_islem i
    where i.sirket_id=new.sirket_id
      and i.zaman>=greatest(r.ilk_koruma, now()-interval '24 hours')
      and i.pay>=0.5
  ), k as (
    select alici id from q union select satici id from q
  )
  select coalesce(sum(q.pay),0), count(*)::int,
         count(distinct q.alici)::int, count(distinct q.satici)::int,
         coalesce(round(sum(q.pay*q.birim)/nullif(sum(q.pay),0)),0),
         (select count(*) from k)::int
  into v_pay,v_islem,v_alici,v_satici,v_fiyat,v_kisi from q;
  if v_pay<2 or v_islem<2 or v_kisi<3 or (v_alici<2 and v_satici<2) then return new; end if;

  select sermaye into v_sermaye from oyun.sirketler where id=new.sirket_id;
  v_alt:=greatest(1,least(r.ilk_fiyat*0.5,coalesce(v_sermaye,1)/200));
  v_ust:=greatest(r.ilk_fiyat*2,coalesce(v_sermaye,1)/50);
  v_yeni:=round(greatest(v_alt,least(v_ust, greatest(round(r.fiyat*0.90),least(round(r.fiyat*1.10),v_fiyat)))));
  if v_yeni=r.fiyat then return new; end if;
  update oyun.borsa_fiyat_referans
    set fiyat=v_yeni,son_fiyat_guncelleme=now(),
        gerekce='Bağımsız katılımcılı asgari %2 pay hacmi ve günlük %10 tavanlı ağırlıklı fiyat'
    where sirket_id=new.sirket_id;
  insert into oyun.borsa_fiyat_gecmis(sirket_id,fiyat,gerekce)
  values(new.sirket_id,v_yeni,'Doğrulanmış 24 saatlik ağırlıklı fiyat; toplam pay %'||v_pay);
  return new;
end $fn$;

drop trigger if exists borsa_fiyat_kesfi on oyun.borsa_islem;
create trigger borsa_fiyat_kesfi after insert on oyun.borsa_islem
for each row execute function oyun.tg_borsa_fiyat_kesfi();

revoke all on oyun.borsa_fiyat_referans,oyun.borsa_fiyat_gecmis,oyun.borsa_supheli_islem from public,anon,authenticated;


-- Gelecekte tamamlanacak halka arzlar da fiyat tescil sistemine otomatik girsin.
create or replace function oyun.tg_borsa_yeni_sirket_fiyat()
returns trigger language plpgsql security definer set search_path to ''
as $fn$
declare fiyat numeric; eklendi bigint;
begin
  if exists (select 1 from oyun.borsa_fiyat_referans where sirket_id=new.sirket_id) then return new; end if;
  if not exists (select 1 from oyun.sirketler where id=new.sirket_id and halka_acik and aktif) then return new; end if;
  fiyat:=oyun.borsa_son_fiyat(new.sirket_id);
  if fiyat is null or fiyat<=0 then return new; end if;
  insert into oyun.borsa_fiyat_referans(sirket_id,fiyat,ilk_fiyat,gerekce)
    values(new.sirket_id,fiyat,fiyat,'Yeni halka açık şirkette ilk fiyat tescili')
    on conflict(sirket_id) do nothing
    returning sirket_id into eklendi;
  if eklendi is not null then
    insert into oyun.borsa_fiyat_gecmis(sirket_id,fiyat,gerekce)
    values(eklendi,fiyat,'Yeni halka açık şirkette ilk fiyat tescili');
  end if;
  return new;
end $fn$;

drop trigger if exists borsa_fiyat_yeni_sirket on oyun.borsa_emir;
create trigger borsa_fiyat_yeni_sirket after insert on oyun.borsa_emir
for each row execute function oyun.tg_borsa_yeni_sirket_fiyat();
-- 98) Gerçekçi SPK/Borsa gözetimi — 2026-10-14
-- Canlı veri koruması: para, sahiplik, geçmiş işlemler DEĞİŞMEZ.
-- Canlı yedek: yedek_20261014_174054_415830
-- İleriye dönük fiyat keşfi ve emir/işlem bütünlüğü.
create table if not exists oyun.borsa_devre_kesici (
  sirket_id bigint primary key references oyun.sirketler(id),
  bit timestamptz not null,
  neden text not null,
  olusma timestamptz not null default now()
);
create index if not exists borsa_devre_kesici_bit_idx on oyun.borsa_devre_kesici(bit);

create table if not exists oyun.borsa_gozetim_kayit (
  id bigint generated always as identity primary key,
  sirket_id bigint not null references oyun.sirketler(id),
  islem_id bigint references oyun.borsa_islem(id),
  tur text not null,
  aciklama text not null,
  zaman timestamptz not null default now(),
  unique (islem_id,tur)
);
create index if not exists borsa_gozetim_sirket_zaman_idx on oyun.borsa_gozetim_kayit(sirket_id,zaman desc);
revoke all on oyun.borsa_devre_kesici,oyun.borsa_gozetim_kayit from public,anon,authenticated;

-- Yalnız piyasanın ONAYLANMIŞ fiyatı şirket değerine ve 24 saatlik değişime yansır.
-- Ham işlemler tarihsel delil olarak ayrı tutulur.
create or replace function oyun.borsa_son_fiyat(p_sirket bigint,t timestamptz default null)
returns numeric language sql stable set search_path to '' as $fn$
 select coalesce(
  (select g.fiyat from oyun.borsa_fiyat_gecmis g
   where g.sirket_id=p_sirket and (t is null or g.zaman<=t)
   order by g.zaman desc,g.id desc limit 1),
  (select g.fiyat from oyun.borsa_fiyat_gecmis g
   where g.sirket_id=p_sirket and t is not null and g.zaman>t
   order by g.zaman asc,g.id asc limit 1),
  (select r.fiyat from oyun.borsa_fiyat_referans r where r.sirket_id=p_sirket),
  (select round((h.deger+h.toplanan)/100) from oyun.halka_arz h
   where h.sirket_id=p_sirket and h.durum='tamam' order by h.id desc limit 1),
  (select round(greatest(s.sermaye,1)/100) from oyun.sirketler s where s.id=p_sirket))
$fn$;

-- Manipülatörün sürekli emir açıp iptal ederek "tahta" yanıltması engellenir.
create or replace function oyun.tg_borsa_emir_bant()
returns trigger language plpgsql security definer set search_path to '' as $fn$
declare f numeric; alt numeric; ust numeric;
begin
  if exists(select 1 from oyun.borsa_devre_kesici h where h.sirket_id=new.sirket_id and h.bit>now()) then
    raise exception 'Borsada devre kesici: şirketin işlemleri geçici süre durdurulmuştur.';
  end if;
  f:=oyun.borsa_son_fiyat(new.sirket_id);
  if f is null or f<=0 then raise exception 'Onaylı fiyat referansı bulunamadı.'; end if;
  alt:=greatest(1,round(f*0.90));
  ust:=greatest(alt,round(f*1.10));
  if new.birim is null or new.birim<alt or new.birim>ust then
    raise exception 'Borsa fiyat bandı: %%1 pay % ₺ ile % ₺ arasında olmalı.',oyun.tl(alt),oyun.tl(ust);
  end if;
  if (select count(*) from oyun.borsa_emir e
      where e.satici=new.satici and e.sirket_id=new.sirket_id
        and e.zaman>now()-interval '15 minutes') >= 5 then
    raise exception 'SPK emir kısıtı: aynı şirket için 15 dakikada en fazla 5 yeni emir.';
  end if;
  return new;
end $fn$;

-- Para ve hisse değişimi gerçekleşmeden önce kontrol edilen atomik güvenlik.
create or replace function oyun.tg_borsa_islem_koruma()
returns trigger language plpgsql security definer set search_path to '' as $fn$
declare f numeric; alt numeric; ust numeric; tutulan numeric; son_alinan numeric;
begin
  if new.satici is null or new.alici is null or new.satici=new.alici then
    raise exception 'Kendi hesabınla borsa işlemi yapılamaz.';
  end if;
  if exists(select 1 from oyun.borsa_devre_kesici h where h.sirket_id=new.sirket_id and h.bit>now()) then
    raise exception 'Devre kesici etkin: işlemler geçici olarak durduruldu.';
  end if;
  if oyun.bagli_hesap_mi(new.satici,new.alici) or oyun.iliskili(new.satici,new.alici) then
    raise exception 'İlişkili oyuncu hesapları arasında borsa işlemi yasaktır.';
  end if;
  if exists(select 1 from oyun.borsa_islem i
      where i.sirket_id=new.sirket_id
        and i.satici=new.alici and i.alici=new.satici
        and i.zaman>now()-interval '7 days') then
    raise exception 'SPK: karşılıklı pay devirleri için 7 günlük engel uygulanır.';
  end if;
  if exists(select 1 from oyun.borsa_islem i
      where i.sirket_id=new.sirket_id
        and i.satici=new.satici and i.alici=new.alici
        and i.zaman>now()-interval '12 hours') then
    raise exception 'SPK: aynı iki hesap aynı şirket için 12 saatte tek işlem yapabilir.';
  end if;
  -- A->B yeni işlemiyle, önceki B->C ve C->A işlemlerinden halka oluşturulamaz.
  if exists(
     select 1 from oyun.borsa_islem i
     join oyun.borsa_islem j on j.sirket_id=i.sirket_id and j.satici=i.alici
     where i.sirket_id=new.sirket_id and i.satici=new.alici
       and j.alici=new.satici
       and i.zaman>now()-interval '7 days'
       and j.zaman>now()-interval '7 days'
  ) then raise exception 'SPK: üç hesap arasında döngüsel alım-satım tespit edildi.'; end if;
  -- Yeni satın alınan payları 24 saat tutma yükümlülüğü; eski mevcut payları kilitlemez.
  select coalesce(pay,0) into tutulan from oyun.sirket_ortaklari
   where sirket_id=new.sirket_id and user_id=new.satici;
  select coalesce(sum(i.pay),0) into son_alinan from oyun.borsa_islem i
   where i.sirket_id=new.sirket_id and i.alici=new.satici
     and i.zaman>now()-interval '24 hours';
  -- public.borsa_al önce satıcı payını düşürür, BEFORE INSERT yeni bakiye üzerinden çalışır.
  -- İşlem öncesi eski pay = işlem sonrası mevcut pay + new.pay;
  -- satılabilir bakiye için kalan payın 24 saatlik yeni alımları karşılaması gerekir.
  if coalesce(tutulan,0) < son_alinan-0.000001 then
    raise exception 'Manipülasyon koruması: son 24 saatte borsadan alınan pay hemen satılamaz. Eski satılabilir pay: %% %.',greatest(0,round(coalesce(tutulan,0)-son_alinan,2));
  end if;
  f:=oyun.borsa_son_fiyat(new.sirket_id);
  if f is null or f<=0 then raise exception 'Şirketin onaylı piyasa fiyatı bulunamadı.'; end if;
  alt:=greatest(1,round(f*0.90)); ust:=greatest(alt,round(f*1.10));
  if new.birim<alt or new.birim>ust then
    raise exception 'İşlem güncel fiyat bandı dışında: emrin yenilenmesi gerekir.';
  end if;
  return new;
end $fn$;

-- Alınan payların bekleme süresini emir oluşturulurken de kontrol et.
-- Böylece alıcı, satışta görünen ancak işlemde bloke olacak bir emre tıklamaz.
create or replace function oyun.tg_borsa_emir_hisse_bekleme()
returns trigger language plpgsql security definer set search_path to '' as $fn$
declare tutulan numeric; yeni numeric; acik numeric;
begin
  select coalesce(o.pay,0) into tutulan from oyun.sirket_ortaklari o
    where o.sirket_id=new.sirket_id and o.user_id=new.satici;
  select coalesce(sum(i.pay),0) into yeni from oyun.borsa_islem i
    where i.sirket_id=new.sirket_id and i.alici=new.satici and i.zaman>now()-interval '24 hours';
  select coalesce(sum(e.kalan),0) into acik from oyun.borsa_emir e
    where e.sirket_id=new.sirket_id and e.satici=new.satici and e.durum='acik';
  if greatest(0,coalesce(tutulan,0)-coalesce(yeni,0)) + 0.000001 < new.pay+coalesce(acik,0) then
    raise exception '24 saatlik pay koruması: henüz satılabilir olmayan payları emir olarak koyamazsın. Boşta pay: %% %.',
      greatest(0,round(coalesce(tutulan,0)-coalesce(yeni,0)-coalesce(acik,0),2));
  end if;
  return new;
end $fn$;
drop trigger if exists borsa_emir_hisse_bekleme on oyun.borsa_emir;
create trigger borsa_emir_hisse_bekleme before insert on oyun.borsa_emir
for each row execute function oyun.tg_borsa_emir_hisse_bekleme();

-- İşlem sonucunda fiyatı yalnız şirket kurucusu veya büyük ortağı DIŞINDAKİ
-- bağımsız oyuncuların işlem hacmi değiştirebilir.
-- Tek oyuncunun kendi çevresiyle hacim yapması fiyat keşfi sayılmaz.
create or replace function oyun.tg_borsa_fiyat_kesfi()
returns trigger language plpgsql security definer set search_path to '' as $fn$
declare r oyun.borsa_fiyat_referans; v_pay numeric; v_fiyat numeric;
        v_islem integer; v_alici integer; v_satici integer; v_kisi integer;
        v_sermaye numeric; v_kasa numeric; v_net numeric;
        v_ust numeric; v_yeni numeric; v_eski numeric;
begin
  if new.pay < 0.5 then return new; end if;
  select * into r from oyun.borsa_fiyat_referans
    where sirket_id=new.sirket_id for update;
  if r.sirket_id is null then return new; end if;
  if now() < r.son_fiyat_guncelleme+interval '24 hours' then return new; end if;

  with q as (
    select i.pay,i.birim,i.alici,i.satici from oyun.borsa_islem i
    join oyun.sirketler s on s.id=i.sirket_id
    where i.sirket_id=new.sirket_id
      and i.zaman>=greatest(r.ilk_koruma,now()-interval '24 hours')
      and i.pay>=0.5
      and i.alici<>s.kurucu and i.satici<>s.kurucu
      and not exists (select 1 from oyun.sirket_ortaklari o
        where o.sirket_id=i.sirket_id
          and o.user_id in (i.alici,i.satici) and o.pay>=20)
      and not exists (select 1 from oyun.borsa_supheli_islem si where si.islem_id=i.id)
  ), kisi as (
    select alici id from q union select satici id from q
  )
  select coalesce(sum(q.pay),0),count(*)::int,
         count(distinct q.alici)::int,count(distinct q.satici)::int,
         coalesce(round(sum(q.pay*q.birim)/nullif(sum(q.pay),0)),0),
         (select count(*) from kisi)::int
  into v_pay,v_islem,v_alici,v_satici,v_fiyat,v_kisi from q;
  -- Hem satıcı hem alıcı tarafında en az iki bağımsız oyuncu.
  if v_pay<2 or v_islem<3 or v_kisi<4 or v_alici<2 or v_satici<2 then
    return new;
  end if;
  select s.sermaye,s.kasa into v_sermaye,v_kasa from oyun.sirketler s where id=new.sirket_id;
  v_net:=greatest(0,coalesce(oyun.borsa_haftalik_net(new.sirket_id),0));
  -- Şirketin piyasa değeri sahte al-satla aşırı büyümesin:
  -- gerçek sermaye+kasaya ve kâra dayalı tavan veya ilk güvenli değerin %130'u.
  v_ust:=greatest(r.ilk_fiyat*1.30,
     (greatest(0,coalesce(v_sermaye,0),coalesce(v_kasa,0))+v_net*26)*1.50/100);
  v_eski:=r.fiyat;
  v_yeni:=round(greatest(100,least(v_ust,round(r.fiyat*1.05),
                                     greatest(round(r.fiyat*0.95),v_fiyat))));
  if v_yeni = v_eski then return new; end if;
  update oyun.borsa_fiyat_referans set fiyat=v_yeni,
    son_fiyat_guncelleme=now(), gerekce='SPK: bağımsız işlem hacmi ve ekonomik değerleme'
    where sirket_id=new.sirket_id;
  insert into oyun.borsa_fiyat_gecmis(sirket_id,fiyat,gerekce)
   values(new.sirket_id,v_yeni,'SPK: en az 4 kişi, 2%% pay ve 3 işlem; günlük %%5 limit, bilanço sınırı');
  if abs(v_yeni/v_eski-1)>=0.04 then
    insert into oyun.borsa_devre_kesici(sirket_id,bit,neden)
    values(new.sirket_id,now()+interval '30 minutes','Onaylı piyasa fiyatında güçlü hareket; 30 dakika devre kesici')
    on conflict (sirket_id) do update
       set bit=excluded.bit,neden=excluded.neden,olusma=now();
  end if;
  insert into oyun.borsa_gozetim_kayit(sirket_id,islem_id,tur,aciklama)
    values(new.sirket_id,new.id,'fiyat_kesfi',
      format('İşlem hacmi %s%%; işlem sayısı %s; bağımsız kişi %s; eski fiyat %s; yeni %s',
      v_pay,v_islem,v_kisi,v_eski,v_yeni))
    on conflict (islem_id,tur) do nothing;
  return new;
end $fn$;

-- Sabit fiyat bandı dışı eski bekleyen emirleri temizle; yeni emir oluşturma hakları korunur.
-- (Yalnız hâlâ açık ve yeni taban/tavan bandının dışındaki teklifler)
update oyun.borsa_emir e set durum='iptal'
where e.durum='acik' and exists (
 select 1 from oyun.borsa_fiyat_referans r where r.sirket_id=e.sirket_id
 and (e.birim<round(r.fiyat*0.90) or e.birim>round(r.fiyat*1.10))
);

-- Borsa şirket detayında son işlem fiyatları değil, onaylanmış fiyatlar grafikleştirilir.
-- Aynı zamanda ekran satılabilir hisseleri doğru gösterebilsin diye "kilitli_pay" verilir.
create or replace function public.borsa_sirket(p_sirket bigint)
returns jsonb language plpgsql security definer set search_path to '' as $fn$
declare p oyun.profiller := oyun.profilim(); s oyun.sirketler;
  t timestamptz := oyun.simdi(); kilitli numeric;
begin
  select * into s from oyun.sirketler where id=p_sirket;
  if s.id is null or not s.halka_acik then raise exception 'Bu şirket borsada işlem görmüyor.'; end if;
  select least(coalesce(o.pay,0),coalesce(sum(i.pay),0))
    into kilitli
    from oyun.sirket_ortaklari o left join oyun.borsa_islem i
      on i.sirket_id=o.sirket_id and i.alici=o.user_id and i.zaman>t-interval '24 hours'
    where o.sirket_id=s.id and o.user_id=p.id
    group by o.pay;
  return jsonb_build_object(
    'id',s.id,'ad',s.ad,'sektor',s.sektor,'aktif',s.aktif,
    'sermaye',s.sermaye,'kasa',round(s.kasa),
    'son',oyun.borsa_son_fiyat(s.id),
    'dun',oyun.borsa_son_fiyat(s.id,t-interval '24 hours'),
    'haftalik_net',oyun.borsa_haftalik_net(s.id),
    'komisyon',(select komisyon from oyun.pazar_ayar where id=1),
    'benim_pay',coalesce((select pay from oyun.sirket_ortaklari where sirket_id=s.id and user_id=p.id),0),
    'kilitli_pay',coalesce(kilitli,0),
    'devre_kesici',(select bit from oyun.borsa_devre_kesici where sirket_id=s.id and bit>now()),
    'benim_satista',coalesce((select sum(kalan) from oyun.borsa_emir where sirket_id=s.id and satici=p.id and durum='acik'),0),
    'cuzdan',(select para from oyun.cuzdan where user_id=p.id),
    'emirler',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'satici',oyun.kad(e.satici),
       'kalan',e.kalan,'birim',e.birim,'benim',e.satici=p.id) order by e.birim,e.id)
       from oyun.borsa_emir e where e.sirket_id=s.id and e.durum='acik'),'[]'::jsonb),
    'islemler',coalesce((select jsonb_agg(jsonb_build_object('zaman',i.zaman,'pay',i.pay,
       'birim',i.birim,'tutar',i.tutar,'satici',oyun.kad(i.satici),'alici',oyun.kad(i.alici))
        order by i.zaman desc) from (select * from oyun.borsa_islem
          where sirket_id=s.id order by zaman desc,id desc limit 20) i),'[]'::jsonb),
    'gunluk',coalesce((select jsonb_agg(jsonb_build_object('gun',g,'fiyat',f) order by g)
      from (select distinct on ((zaman at time zone 'Europe/Istanbul')::date)
       (zaman at time zone 'Europe/Istanbul')::date g,fiyat f
       from oyun.borsa_fiyat_gecmis where sirket_id=s.id and zaman>t-interval '30 days'
       order by (zaman at time zone 'Europe/Istanbul')::date,zaman desc,id desc) d),'[]'::jsonb),
    'haftalar',coalesce((select jsonb_agg(jsonb_build_object('zaman',h.zaman,'net',h.tutar) order by h.zaman)
       from (select zaman,tutar from oyun.sirket_hareket
         where sirket_id=s.id and faaliyet_gelir>0 and aciklama like '7 günlük%'
         order by zaman desc,id desc limit 8) h),'[]'::jsonb),
    'ortaklar',(select jsonb_agg(jsonb_build_object('kad',oyun.kad(o.user_id),'pay',o.pay)
       order by o.pay desc) from oyun.sirket_ortaklari o where o.sirket_id=s.id)
  );
end $fn$;

-- Yalnız servis ve sunucu fonksiyonları tablo değiştirebilir.
revoke all on oyun.borsa_devre_kesici,oyun.borsa_gozetim_kayit from public,anon,authenticated;
-- 99a · EKONOMİ 3.0 — para birimi ve kritik düzeltmeler (2026-10-15)
-- Oyunun resmî kuru: 1 milyar kamu ₺ = oyun.pazar_tl_milyar() oyuncu ₺ (≈150.000 × fiyat endeksi).
-- Sorun: şirket vergileri (eko_vergi_tahsil) oyuncu ₺'sini doğrudan milyar ₺ olarak hazineye ekliyordu
-- (5.351 ₺ vergi → hazine 250 → 5.600 milyar). Bazı eski fonksiyonlar da 1e6 / 1e9 kullanıyordu.
-- İki kez çalıştırılabilir. Oyuncu verisine dokunmaz; yalnız hazine fazlası bir kez düşülür.

-- 1) Şirket vergileri hazineye doğru birimle girer
create or replace function oyun.eko_vergi_tahsil(p_sirket bigint, p_matrah text, p_baza numeric, p_kaynak text, p_kaynak_id bigint, p_oyuncu uuid default null::uuid)
 returns numeric language plpgsql security definer set search_path to ''
as $function$
declare v record; odenen numeric:=0; x numeric; tlm numeric:=oyun.pazar_tl_milyar();
begin
 if p_sirket is null or p_kaynak_id is null or p_matrah not in ('satis','kar','dagitim','sozlesme')
 then raise exception 'Vergi matrahi veya kaynak kimligi gecersiz.';end if;
 for v in select kod,oran from oyun.eko_vergi_turleri
 where matrah=p_matrah and aktif and oran>0 order by kod
 loop
   x:=round(case when v.kod='kdv' and p_matrah='satis'
   then greatest(0,p_baza)*v.oran/(100+v.oran)
   else greatest(0,p_baza)*v.oran/100 end);
   if x<=0 then continue;end if;
   insert into oyun.eko_vergi_hareket(sirket_id,oyuncu,kod,matrah,oran,tutar,kaynak,kaynak_id)
   values(p_sirket,p_oyuncu,v.kod,greatest(0,p_baza),v.oran,x,p_kaynak,p_kaynak_id)
   on conflict do nothing;
   if found then
      update oyun.ulke set hazine=hazine+x/tlm where id=1;
      odenen:=odenen+x;
   end if;
 end loop;
 return odenen;
end $function$;

-- 2) Hazine fazlasını bir kez düzelt (yalnız ilk çalıştırmada)
create table if not exists oyun.ekonomi3_kayit(kod text primary key, deger numeric, zaman timestamptz default now());
do $$
declare toplam numeric; tlm numeric:=oyun.pazar_tl_milyar();
begin
  if exists(select 1 from oyun.ekonomi3_kayit where kod='hazine_vergi_duzeltme') then return; end if;
  select coalesce(sum(tutar),0) into toplam from oyun.eko_vergi_hareket;
  update oyun.ulke set hazine = hazine - toplam + toplam/tlm where id=1;
  insert into oyun.ekonomi3_kayit(kod,deger) values('hazine_vergi_duzeltme', toplam - toplam/tlm);
end $$;

-- 3) Eski 1e6 / 1e9 dönüşümleri tek resmî kura çekilir
do $$
declare r record; d text; e text;
begin
  for r in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace
           where n.nspname in ('oyun','public') and p.proname in
           ('eko_islem','mulk_kira_tahsil','piyango_bilet_al','tahvil_al','tahvil_portfoy',
            'belediye_is_tick','belediye_is_iptal','belediye_is_ihale_ac','kazikazan_oyna','piyasa_emir')
  loop
    d := pg_get_functiondef(r.oid);
    e := regexp_replace(d, '/\s*1000000000(\.0)?\M', '/oyun.pazar_tl_milyar()', 'g');
    e := regexp_replace(e, '\*\s*1000000000(\.0)?\M', '*oyun.pazar_tl_milyar()', 'g');
    e := regexp_replace(e, '/\s*1000000(\.0)?\M', '/oyun.pazar_tl_milyar()', 'g');
    if e <> d then execute e; end if;
  end loop;
end $$;

-- 4) Milli Piyango: gerçek usul — ikramiye bilet hasılatından, devir eden büyük ikramiye, amorti
--    Bilet 1.000 ₺: %50 ikramiye havuzu, %10 amorti, %40 hazine. Büyük ikramiye son 3 hane (1/1000);
--    kimse tutturamazsa ikramiye devreder. Son hane tutan bilet bedelini (amorti) geri alır.
--    Yeni dönem tabanı 100.000 ₺ (hazineden).
create or replace function oyun.piyango_guncelle()
 returns bigint language plpgsql security definer set search_path to 'oyun', 'public', 'pg_temp'
as $function$
declare
 t timestamptz:=now(); bas timestamptz; curid bigint;
 prev record; winning integer; first_winner uuid; cnt int; per_ticket numeric;
 b record; roll numeric; taban numeric:=100000;
begin
 perform pg_advisory_xact_lock(77890011);
 bas:=timestamptz '2026-10-08 00:00:00+00'+floor(extract(epoch from (t-timestamptz '2026-10-08 00:00:00+00'))/604800)*interval '7 days';
 for prev in select * from oyun.piyango_donem where bitis<=t and not cekildi order by baslangic for update loop
   winning:=floor(random()*1000000)::int;
   select count(*) into cnt from oyun.piyango_bilet
     where donem_id=prev.id and mod(numara,1000)=mod(winning,1000);
   per_ticket:=case when cnt>0 then trunc(prev.ikramiye/cnt,0) else 0 end;
   first_winner:=null;
   if cnt>0 then
     for b in select id,user_id from oyun.piyango_bilet
       where donem_id=prev.id and mod(numara,1000)=mod(winning,1000) order by id loop
       insert into oyun.piyango_odul(bilet_id,donem_id,user_id,tutar)
         values(b.id,prev.id,b.user_id,per_ticket) on conflict do nothing;
       if found and per_ticket>0 then
         perform oyun.para_islem(b.user_id,per_ticket,'piyango','Milli Piyango büyük ikramiyesi',t);
         perform oyun.bildir(b.user_id, format('Milli Piyango büyük ikramiyesi sana çıktı: %s ₺!', oyun.tl(per_ticket)), t);
       end if;
       first_winner:=coalesce(first_winner,b.user_id);
     end loop;
     perform oyun.olay('ekonomi', format('Milli Piyango çekildi: büyük ikramiye %s ₺, %s bilete çıktı (son üç hane %s).',
        oyun.tl(prev.ikramiye), cnt, lpad(mod(winning,1000)::text,3,'0')), null, null, t);
   else
     perform oyun.olay('ekonomi', format('Milli Piyango çekildi, büyük ikramiye kimseye çıkmadı: %s ₺ devretti (son üç hane %s).',
        oyun.tl(prev.ikramiye), lpad(mod(winning,1000)::text,3,'0')), null, null, t);
   end if;
   -- amorti: son hanesi tutan (büyük ikramiye almayan) biletlere bilet bedeli
   for b in select id,user_id,bedel from oyun.piyango_bilet
       where donem_id=prev.id and mod(numara,10)=mod(winning,10) and mod(numara,1000)<>mod(winning,1000) loop
     insert into oyun.piyango_odul(bilet_id,donem_id,user_id,tutar) values(b.id,prev.id,b.user_id,b.bedel) on conflict do nothing;
     if found then perform oyun.para_islem(b.user_id,b.bedel,'piyango','Milli Piyango amortisi',t); end if;
   end loop;
   update oyun.piyango_donem set cekildi=true,kazanan_no=winning,kazanan=first_winner,
     kazanan_adet=cnt,cekilis_at=t where id=prev.id;
 end loop;
 select id into curid from oyun.piyango_donem where baslangic=bas;
 if curid is null then
   select case when kazanan_adet=0 then ikramiye else null end
     into roll from oyun.piyango_donem where bitis<=bas order by bitis desc limit 1;
   if roll is null then
     roll := taban;
     update oyun.ulke set hazine=hazine-taban/oyun.pazar_tl_milyar() where id=1;
   end if;
   insert into oyun.piyango_donem(baslangic,bitis,ikramiye)
      values(bas,bas+interval '7 days',roll)
      on conflict(baslangic) do update set baslangic=excluded.baslangic returning id into curid;
 end if;
 return curid;
end $function$;

create or replace function public.piyango_bilet_al(p_adet integer default 1)
 returns jsonb language plpgsql security definer set search_path to 'oyun', 'public', 'pg_temp'
as $function$
declare u uuid:=auth.uid(); d bigint; k int;
begin
 if u is null or not exists(select 1 from oyun.profiller where id=u) then raise exception 'Profil gerekli'; end if;
 if p_adet is null or p_adet<1 or p_adet>10 then raise exception 'Bir işlemde 1-10 bilet alınabilir.'; end if;
 d:=oyun.piyango_guncelle();
 perform oyun.para_islem(u,-1000*p_adet,'piyango','Milli piyango biletleri',now());
 for k in 1..p_adet loop
   insert into oyun.piyango_bilet(donem_id,user_id,numara,bedel)
   values(d,u,floor(random()*1000000)::int,1000);
 end loop;
 -- %50 ikramiye havuzu, %10 amorti için ayrılır (ödenene kadar dolaşımdan çıkar), %40 hazine
 update oyun.piyango_donem set bilet_sayisi=bilet_sayisi+p_adet,ikramiye=ikramiye+500*p_adet where id=d;
 update oyun.ulke set hazine=hazine+(400*p_adet)/oyun.pazar_tl_milyar() where id=1;
 return public.piyango_durum();
end $function$;

-- Açık dönemin ikramiyesi eski kuralla 1.000.000 tabanından başladı; yeni tabana çekilir (bir kez).
do $$
begin
  if exists(select 1 from oyun.ekonomi3_kayit where kod='piyango_taban') then return; end if;
  update oyun.piyango_donem set ikramiye = 100000 + bilet_sayisi*500 where not cekildi;
  insert into oyun.ekonomi3_kayit(kod,deger) values('piyango_taban',1);
end $$;

-- 5) Zamanlanmış işleri aynı dakikaya yığılmayacak şekilde kaydır (job startup timeout azalır)
do $$
declare r record;
begin
  if not exists(select 1 from pg_namespace where nspname='cron') then return; end if;
  for r in select * from (values
      ('belediye-hizmet-ihale','1-59/5'), ('meclis-arastirma','2-59/5'), ('siyasi-kurumlar','3-59/5'),
      ('turkiye-gundem-otomatik-gazete','4-59/5'), ('yuksek-mahkeme','0-59/5'),
      ('ekonomi-pazar','5-59/10'), ('eko_otomatik_uretim_kendi_tedarik','6-59/10'), ('uc-etkinlik-bitir','7-59/10'),
      ('eko-ticaret-periyodik','8-59/10'), ('ekonomi-2','9-59/10'), ('uc-kitap-satis','3-59/10'),
      ('gun-sonu','11-59/15'), ('belediye-sehir-bina-tick','13,43 * * * *'), ('bos-makam-firsat','17,47 * * * *'),
      ('ulke_krizi_sure_20261010','19 * * * *')) v(ad, sch)
  loop
    perform cron.alter_job(j.jobid, schedule := case when r.sch like '% %' then r.sch else r.sch||' * * * *' end)
      from cron.job j where j.jobname = r.ad;
  end loop;
end $$;
-- 99b · EKONOMİ 3.0 — her şirkete günlük ana faaliyet (2026-10-15)
-- * Rekabetçi pazar modeli (pazar_tahmin) 5 sektörden 11 sektöre çıkar: teknoloji, sanayi, ticaret,
--   inşaat, medya, tarım da artık il pazarında fiyat/kalite/marka ile rekabet eder.
-- * Hesap kesimi haftalıktan GÜNLÜĞE iner (aynı haftalık tutar / 7). Geçmiş günler bir defada kapanır.
-- * Kapasite artık "hizmet hacmi"dir: gelir = min(talep, kapasite) × fiyat katsayısı → fiyat kararı
--   kapasite doluyken de anlamlı (yüksek fiyat daha çok kazandırır ama müşteri kaçırır, Rekabet Kurumu izler).
-- * Bölgesel teşvik (6 bölge, il kalkınma puanından): kurumlar vergisi indirimi + SGK işveren desteği.
-- * Şirketler arası gider zinciri: sabit giderin %30'u elektrik faturası (enerji şirketlerine),
--   %20'si lojistik (ulaşım şirketlerine), isteğe bağlı reklam bütçesi (medya şirketlerine) gerçek
--   oyuncu şirketlerine akar; oyuncu tedarikçi yoksa yurt içi NPC tedarikçilere gider.
-- * Kurumlar vergisi tek kaynaktan: eko_vergi_turleri 'kurumlar' (Meclis değiştirebilir).
-- İki kez çalıştırılabilir.

-- 1) Yeni sektör pazarları
insert into oyun.pazar_sektor(kod,ad,bakanlik,taban,esneklik,dis,sabit,kapasite,personel,min_sermaye,sira,aciklama) values
 ('teknoloji','Bilişim ve Yazılım','sanayi',160000,1.2,0.5,0.04,0.26,1.2,100000,6,
  'Yazılım, veri merkezi ve bilişim hizmetleri. Müşteri kaliteye ve markaya bakar; iyi ekip pahalıdır ama premium fiyatı taşır.'),
 ('sanayi','Sanayi Üretimi','sanayi',150000,1.5,0.6,0.05,0.26,1.4,100000,7,
  'Fabrika üretimi ve ara mallar. Büyüme ve dolar kuru talebi etkiler; ölçek büyüdükçe birim maliyet düşer.'),
 ('ticaret','Toptan ve Perakende Ticaret','ticaret',145000,2.0,0.5,0.04,0.28,1.0,100000,8,
  'Mağazalar, toptancılar ve e-ticaret. Fiyata duyarlı müşteri; ucuz olan çok satar.'),
 ('insaat','İnşaat ve Taahhüt','ulastirma',155000,1.3,0.8,0.05,0.25,1.3,100000,9,
  'Konut, iş yeri ve altyapı taahhüdü. Kamu yatırımları güçlüyse özel sektöre iş azalır; kamu ihaleleri ayrıca kazanılır.'),
 ('medya','Medya ve Yayıncılık','ulastirma',120000,1.4,0.7,0.045,0.26,1.1,100000,10,
  'Televizyon, gazete ve dijital yayın. Marka her şeydir; diğer şirketlerin reklam bütçeleri medya şirketlerine akar.'),
 ('tarim','Tarım ve Hayvancılık','tarim',130000,1.8,0.6,0.045,0.26,1.2,100000,11,
  'Tarla, sera ve hayvancılık. Doğu ve kırsal illerde teşvik yüksektir; fiyata duyarlı bir pazardır.')
on conflict (kod) do nothing;

-- 2) Yeni kolonlar ve tablolar
alter table oyun.pazar_sirket add column if not exists reklam smallint not null default 0;
do $$ begin
  alter table oyun.pazar_sirket add constraint pazar_sirket_reklam_ck check (reklam between 0 and 3);
exception when duplicate_object then null; end $$;

create table if not exists oyun.eko_gunluk(
  sirket_id bigint not null references oyun.sirketler(id) on delete cascade,
  gun date not null,
  gelir numeric not null default 0, gider numeric not null default 0, reklam numeric not null default 0,
  b2b_gider numeric not null default 0, b2b_gelir numeric not null default 0,
  ruhsat numeric not null default 0, ceza numeric not null default 0,
  vergi numeric not null default 0, tesvik numeric not null default 0,
  net numeric not null default 0, dagitilan numeric not null default 0,
  pazar numeric, pay numeric, rakip int, fiyat smallint, kalite smallint, il_id smallint,
  zaman timestamptz not null default now(),
  primary key(sirket_id, gun));
create index if not exists eko_gunluk_gun on oyun.eko_gunluk(gun);

create table if not exists oyun.eko_b2b(
  id bigserial primary key,
  zaman timestamptz not null default now(),
  gun date not null,
  alici bigint not null, satici bigint, kalem text not null,
  tutar numeric not null, islendi boolean not null default false);
create index if not exists eko_b2b_satici on oyun.eko_b2b(satici) where not islendi;
create index if not exists eko_b2b_alici on oyun.eko_b2b(alici, gun);

alter table oyun.eko_gunluk enable row level security;
alter table oyun.eko_b2b enable row level security;
alter table oyun.ekonomi3_kayit enable row level security;

-- 3) Bölgesel teşvik (Türkiye'nin 6 bölgeli teşvik sistemine benzer; il_kalkinma puanı 90/75/60/45/30/15)
create or replace function oyun.il_bolge(p_il smallint)
 returns smallint language sql stable set search_path to ''
as $$ select greatest(1, least(6, 7 - round(coalesce((select puan from oyun.il_kalkinma where il_id = p_il), 60) / 15.0)))::smallint $$;

create or replace function oyun.bolge_tesvik(p_il smallint)
 returns jsonb language sql stable set search_path to ''
as $$
  select jsonb_build_object('bolge', b,
    'vergi_indirim', (array[0,10,20,30,45,60])[b],
    'sgk_destek', (array[0,0,5,10,15,20])[b])
  from (select oyun.il_bolge(p_il) b) x
$$;

-- 4) Pazar tahmini (haftalık birimle; günlük kesimde /7 kullanılır)
create or replace function oyun.pazar_tahmin(p_sirket bigint, p_fiyat smallint default null::smallint, p_kalite smallint default null::smallint, p_kaynak text default null::text, t timestamp with time zone default null::timestamp with time zone)
 returns jsonb language plpgsql stable set search_path to ''
as $function$
declare s oyun.sirketler; ps oyun.pazar_sirket; k oyun.pazar_sektor; u oyun.ulke; zt timestamptz := coalesce(t, oyun.simdi());
  v_f smallint; v_k smallint; v_kay text; w numeric; makro numeric; pol numeric; pazar numeric; dis numeric; kamu numeric;
  ben numeric; toplam numeric; pay numeric; gelir numeric; kap numeric; gider numeric; personel numeric; ruh numeric; ruhsat numeric;
  vergi numeric; net numeric; ceza numeric := 0; kalite_gid numeric; kaynak_gid numeric := 0; rakip int; usd numeric; pold text;
  sabit numeric; talep numeric; reklam_oran numeric; reklam numeric; tes jsonb; kv numeric; sgk numeric; brut numeric;
begin
  select * into s from oyun.sirketler where id = p_sirket;
  select * into ps from oyun.pazar_sirket where sirket_id = p_sirket;
  select * into k from oyun.pazar_sektor where kod = s.sektor;
  if s.id is null or ps.sirket_id is null or k.kod is null then return null; end if;
  select * into u from oyun.ulke where id = 1;
  v_f := coalesce(p_fiyat, ps.fiyat); v_k := coalesce(p_kalite, ps.kalite);
  v_kay := case when s.sektor = 'enerji' then coalesce(p_kaynak, ps.kaynak, 'dogalgaz') else null end;

  w := oyun.pazar_il_agirlik(ps.il_id);
  makro := case when s.sektor in ('enerji','sanayi','insaat') then oyun.sinir(1 + (coalesce(u.buyume, 3) - 3) * 0.06, 0.7, 1.4)
                else oyun.sinir(1 + (coalesce(u.buyume, 3) - 3) * 0.03 + (coalesce(u.memnuniyet, 50) - 50) * 0.004, 0.8, 1.25) end;
  pold := oyun.sektor_pol_durum(s.sektor, zt);
  pol := case pold when 'tesvik' then 1.15 when 'denetim' then 0.92 else 1 end;
  pazar := k.taban * w * makro * pol * oyun.kriz_sektor_carpani(s.sektor, zt);

  kamu := coalesce((select kasa from oyun.bakanlik_kasa where kod = k.bakanlik), 20);
  dis := k.dis * (0.85 + least(greatest(kamu, 0), 60) / 100.0);

  ben := (1 + 0.35 * v_k + ps.marka / 100.0) / power(oyun.pazar_fiyat_katsayi(v_f), k.esneklik);
  select coalesce(sum((1 + 0.35 * p2.kalite + p2.marka / 100.0) / power(oyun.pazar_fiyat_katsayi(p2.fiyat), k.esneklik)), 0), count(*)
    into toplam, rakip
  from oyun.pazar_sirket p2 join oyun.sirketler s2 on s2.id = p2.sirket_id
  where p2.il_id = ps.il_id and s2.sektor = s.sektor and s2.aktif and p2.sirket_id <> s.id;
  pay := ben / (dis + toplam + ben);
  kap := s.sermaye * k.kapasite;
  talep := pazar * pay;
  -- kapasite hizmet hacmidir; fiyat katsayısı hacmin üstüne biner
  gelir := least(talep, kap) * oyun.pazar_fiyat_katsayi(v_f);

  tes := oyun.bolge_tesvik(ps.il_id);
  sgk := (tes->>'sgk_destek')::numeric;
  personel := coalesce(u.asgari, 30000) * k.personel * power(greatest(0.25, s.sermaye / 400000.0), 0.7) * (1 - sgk / 100);
  kalite_gid := s.sermaye * case v_k when 1 then 0.01 when 2 then 0.022 when 3 then 0.036 else 0 end;
  sabit := s.sermaye * k.sabit;
  if v_kay = 'komur' then sabit := sabit * 0.75;
  elsif v_kay = 'dogalgaz' then
    usd := coalesce((select fiyat from oyun.piyasa_varlik where kod = 'USD'), 42);
    kaynak_gid := s.sermaye * 0.015 * usd / 42.0;
  elsif v_kay = 'yenilenebilir' then sabit := sabit + s.sermaye * 0.02;
  end if;
  reklam_oran := (array[0, 0.015, 0.03, 0.05])[coalesce(ps.reklam, 0) + 1];
  reklam := gelir * reklam_oran;
  gider := sabit + personel + kalite_gid + kaynak_gid + reklam;

  if pold = 'denetim' and (v_k = 0 or v_kay = 'komur') then ceza := gelir * 0.12; end if;
  ruh := coalesce((select oran from oyun.il_ruhsat where il_id = ps.il_id), 0);
  ruhsat := gelir * ruh / 100;
  brut := gelir - gider - ruhsat - ceza;
  kv := coalesce(nullif(oyun.eko_vergi_oran('kurumlar'), 0), (select kurumlar from oyun.pazar_ayar where id = 1));
  vergi := greatest(0, brut) * kv / 100 * (1 - (tes->>'vergi_indirim')::numeric / 100);
  net := brut - vergi;
  return jsonb_build_object('pazar', round(pazar), 'pay', round(pay * 100, 1), 'rakip', rakip, 'gelir', round(gelir),
    'talep', round(talep), 'kapasite', round(kap), 'kapasite_dolu', talep >= kap - 1, 'gider', round(gider), 'personel', round(personel),
    'kalite_gider', round(kalite_gid), 'kaynak_gider', round(kaynak_gid), 'sabit', round(sabit), 'reklam', round(reklam),
    'reklam_seviye', coalesce(ps.reklam, 0),
    'ruhsat', round(ruhsat), 'ruhsat_oran', ruh, 'ceza', round(ceza), 'vergi', round(vergi), 'net', round(net),
    'gunluk_net', round(net / 7), 'kurumlar_orani', kv,
    'bolge', (tes->>'bolge')::int, 'vergi_indirim', (tes->>'vergi_indirim')::int, 'sgk_destek', (tes->>'sgk_destek')::int,
    'politika', pold, 'kamu_guc', round(dis, 2),
    'fiyat', v_f, 'kalite', v_k, 'kaynak', v_kay, 'getiri', round(net / s.sermaye * 100, 1));
end $function$;

-- 5) Şirketler arası ödeme: alıcının giderinden tedarikçi oyuncu şirketlerine pay
--    Tedarikçi ağırlığı = (1 + 0,35×kalite + marka/100) / fiyat^1,5 × (aynı il ise 3).
--    Oyuncu tedarikçilerin toplam payı = W / (W + 4) (geri kalanı yurt içi NPC tedarikçiler).
create or replace function oyun.b2b_ode(p_alici bigint, p_sektor text, p_tutar numeric, p_il smallint, p_kalem text, p_gun date)
 returns numeric language plpgsql security definer set search_path to ''
as $function$
declare toplam_w numeric; oyuncu_pay numeric; x record; dagit numeric := 0; parca numeric;
begin
  if coalesce(p_tutar, 0) <= 0 then return 0; end if;
  select coalesce(sum(w), 0) into toplam_w from (
    select (1 + 0.35 * p.kalite + p.marka / 100.0) / power(oyun.pazar_fiyat_katsayi(p.fiyat), 1.5)
           * case when p.il_id = p_il then 3 else 1 end w
    from oyun.pazar_sirket p join oyun.sirketler s on s.id = p.sirket_id
    where s.sektor = p_sektor and s.aktif and s.id <> p_alici) q;
  if toplam_w <= 0 then
    insert into oyun.eko_b2b(gun, alici, satici, kalem, tutar, islendi) values (p_gun, p_alici, null, p_kalem, round(p_tutar), true);
    return 0;
  end if;
  oyuncu_pay := p_tutar * toplam_w / (toplam_w + 4);
  for x in select s.id, (1 + 0.35 * p.kalite + p.marka / 100.0) / power(oyun.pazar_fiyat_katsayi(p.fiyat), 1.5)
           * case when p.il_id = p_il then 3 else 1 end w
    from oyun.pazar_sirket p join oyun.sirketler s on s.id = p.sirket_id
    where s.sektor = p_sektor and s.aktif and s.id <> p_alici
  loop
    parca := round(oyuncu_pay * x.w / toplam_w);
    if parca > 0 then
      update oyun.sirketler set kasa = kasa + parca where id = x.id;
      insert into oyun.eko_b2b(gun, alici, satici, kalem, tutar) values (p_gun, p_alici, x.id, p_kalem, parca);
      dagit := dagit + parca;
    end if;
  end loop;
  if p_tutar - dagit > 0 then
    insert into oyun.eko_b2b(gun, alici, satici, kalem, tutar, islendi) values (p_gun, p_alici, null, p_kalem, round(p_tutar - dagit), true);
  end if;
  return dagit;
end $function$;

-- 6) Günlük hesap kesimi
create or replace function oyun.pazar_hesapla(p_id bigint)
 returns void language plpgsql security definer set search_path to ''
as $function$
declare s oyun.sirketler; ps oyun.pazar_sirket; t timestamptz := oyun.simdi(); n int; i int; h jsonb; zt timestamptz; gun date;
  gurultu numeric; gelir numeric; gider numeric; ruhsat numeric; ceza numeric; v_vergi numeric; net numeric; oran numeric;
  x record; distributed numeric; distributable numeric; v_odeme numeric; tlm numeric; ilad text; kasa_son numeric;
  en jsonb; yonetim numeric; a oyun.pazar_ayar; sabit numeric; reklam numeric; enerji numeric; lojistik numeric;
  b2b_in numeric; brut numeric; kv numeric; tes jsonb; indirim numeric; net_op numeric; tesvik_tl numeric;
  reklam_bonus numeric; kalite_bonus numeric;
begin
  select * into s from oyun.sirketler where id = p_id for update;
  select * into ps from oyun.pazar_sirket where sirket_id = p_id for update;
  if s.id is null or ps.sirket_id is null or not s.aktif or s.sonraki_kazanc > t then return; end if;
  select * into a from oyun.pazar_ayar where id = 1;
  n := least(30, floor(extract(epoch from (t - s.sonraki_kazanc)) / 86400)::int + 1);
  tlm := oyun.pazar_tl_milyar();
  select ad into ilad from oyun.iller where id = ps.il_id;
  kv := coalesce(nullif(oyun.eko_vergi_oran('kurumlar'), 0), a.kurumlar);
  for i in 1..n loop
    zt := s.sonraki_kazanc + (i - 1) * interval '1 day';
    gun := (zt at time zone 'Europe/Istanbul')::date;
    if ps.otopilot and (ps.hafta % 7 = 0) then
      en := oyun.pazar_en_iyi(p_id, zt);
      if en is not null and ((en->>'fiyat')::int <> ps.fiyat or (en->>'kalite')::int <> ps.kalite) then
        update oyun.pazar_sirket set fiyat = (en->>'fiyat')::int, kalite = (en->>'kalite')::int where sirket_id = p_id;
        select * into ps from oyun.pazar_sirket where sirket_id = p_id;
      end if;
    end if;
    h := oyun.pazar_tahmin(p_id, null, null, null, zt);
    gurultu := 0.88 + random()::numeric * 0.24;
    gelir := round((h->>'gelir')::numeric / 7 * gurultu);
    yonetim := case when ps.otopilot then round(gelir * a.yonetici_ucret / 100) else 0 end;
    sabit := (h->>'sabit')::numeric / 7;
    reklam := round(gelir * (array[0, 0.015, 0.03, 0.05])[coalesce(ps.reklam, 0) + 1]);
    gider := round(((h->>'gider')::numeric - (h->>'reklam')::numeric) / 7) + reklam + yonetim;
    oran := coalesce((h->>'ruhsat_oran')::numeric, 0);
    ruhsat := round(gelir * oran / 100);
    ceza := case when (h->>'ceza')::numeric > 0 then round(gelir * 0.12) else 0 end;
    net_op := gelir - gider - ruhsat - ceza;

    -- şirketler arası gider zinciri (giderin bir parçası tedarikçi oyunculara akar)
    enerji := round(sabit * 0.30); lojistik := round(sabit * 0.20);
    if s.sektor <> 'enerji' then perform oyun.b2b_ode(p_id, 'enerji', enerji, ps.il_id, 'Elektrik faturası', gun); end if;
    if s.sektor <> 'ulasim' then perform oyun.b2b_ode(p_id, 'ulasim', lojistik, ps.il_id, 'Lojistik ve servis', gun); end if;
    if reklam > 0 and s.sektor <> 'medya' then perform oyun.b2b_ode(p_id, 'medya', reklam, ps.il_id, 'Reklam', gun); end if;

    -- müşteri olduğun şirketlerden gelen ödemeler (kasaya zaten girdi; burada vergilendirilir)
    with u as (update oyun.eko_b2b set islendi = true where satici = p_id and not islendi returning tutar)
    select coalesce(sum(tutar), 0) into b2b_in from u;

    brut := net_op + b2b_in;
    tes := oyun.bolge_tesvik(ps.il_id);
    indirim := (tes->>'vergi_indirim')::numeric;
    v_vergi := round(greatest(0, brut) * kv / 100 * (1 - indirim / 100));
    tesvik_tl := round(greatest(0, brut) * kv / 100) - v_vergi;
    net := brut - v_vergi;

    if v_vergi > 0 then update oyun.ulke set hazine = hazine + v_vergi / tlm where id = 1; end if;
    if ruhsat > 0 then
      update oyun.il_durum set kasa = coalesce(kasa, 0) + ruhsat / tlm where il_id = ps.il_id;
      insert into oyun.il_ruhsat(il_id, toplam) values (ps.il_id, ruhsat)
        on conflict (il_id) do update set toplam = oyun.il_ruhsat.toplam + excluded.toplam;
    end if;
    update oyun.il_durum set
      gelisim = oyun.sinir(gelisim + (0.03 + case ps.kaynak when 'yenilenebilir' then 0.05 else 0 end) / 7, 0, 100),
      memnuniyet = oyun.sinir(memnuniyet + (case when s.sektor = 'enerji' and ps.kaynak = 'komur' then -0.4 when ps.kalite >= 2 then 0.05 else 0 end) / 7, 0, 100)
    where il_id = ps.il_id;

    -- kasaya: faaliyet sonucu − vergi (b2b geliri zaten kasada)
    update oyun.sirketler set kasa = kasa + net_op - v_vergi where id = p_id;
    distributed := 0;
    if net > 0 then
      distributable := least(net, greatest(0, (select kasa from oyun.sirketler where id = p_id)));
      for x in select * from oyun.sirket_ortaklari where sirket_id = p_id loop
        if not x.kar_kasada then
          v_odeme := least(round(distributable * x.pay / 100, 2), greatest(0, distributable - distributed));
          if v_odeme > 0 then
            perform oyun.para_islem(x.user_id, v_odeme, 'sirket', format('%s günlük net kâr payı (%s)', s.ad, to_char(gun, 'DD.MM')), t);
            distributed := distributed + v_odeme;
          end if;
        end if;
      end loop;
      update oyun.sirketler set kasa = kasa - distributed where id = p_id;
    end if;
    insert into oyun.sirket_hareket(sirket_id, zaman, tutar, aciklama, faaliyet_gelir, faaliyet_gider, dagitilan_kar)
    values (p_id, t, net, format('Günlük faaliyet %s (%s): pazar payı %%%s, %s rakip%s%s', to_char(gun, 'DD.MM'),
            ilad, h->>'pay', h->>'rakip', case when ps.otopilot then ', otopilot' else '' end,
            case when b2b_in > 0 then format(', şirketlerden %s ₺ satış', oyun.tl(b2b_in)) else '' end),
            gelir + b2b_in, gider + ruhsat + ceza + v_vergi, distributed);
    insert into oyun.pazar_rapor(sirket_id, zaman, il_id, pazar, pay, rakip, gelir, gider, ruhsat, vergi, ceza, net, fiyat, kalite, kaynak)
    values (p_id, zt + interval '1 day', ps.il_id, round((h->>'pazar')::numeric / 7), (h->>'pay')::numeric, (h->>'rakip')::int,
            gelir + b2b_in, gider, ruhsat, v_vergi, ceza, net, ps.fiyat, ps.kalite, ps.kaynak);
    insert into oyun.eko_gunluk(sirket_id, gun, gelir, gider, reklam, b2b_gider, b2b_gelir, ruhsat, ceza, vergi, tesvik, net, dagitilan,
                                pazar, pay, rakip, fiyat, kalite, il_id, zaman)
    values (p_id, gun, gelir, gider, reklam, enerji + lojistik + reklam, b2b_in, ruhsat, ceza, v_vergi, tesvik_tl, net, distributed,
            round((h->>'pazar')::numeric / 7), (h->>'pay')::numeric, (h->>'rakip')::int, ps.fiyat, ps.kalite, ps.il_id, t)
    on conflict on constraint eko_gunluk_pkey do update set
      gelir = oyun.eko_gunluk.gelir + excluded.gelir, gider = oyun.eko_gunluk.gider + excluded.gider,
      reklam = oyun.eko_gunluk.reklam + excluded.reklam, b2b_gider = oyun.eko_gunluk.b2b_gider + excluded.b2b_gider,
      b2b_gelir = oyun.eko_gunluk.b2b_gelir + excluded.b2b_gelir, ruhsat = oyun.eko_gunluk.ruhsat + excluded.ruhsat,
      ceza = oyun.eko_gunluk.ceza + excluded.ceza, vergi = oyun.eko_gunluk.vergi + excluded.vergi,
      tesvik = oyun.eko_gunluk.tesvik + excluded.tesvik, net = oyun.eko_gunluk.net + excluded.net,
      dagitilan = oyun.eko_gunluk.dagitilan + excluded.dagitilan, zaman = excluded.zaman;

    reklam_bonus := (array[0, 3, 6, 10])[coalesce(ps.reklam, 0) + 1];
    kalite_bonus := 3 + 2.5 * ps.kalite + case ps.kaynak when 'yenilenebilir' then 3 else 0 end;
    update oyun.pazar_sirket set marka = least(100, marka * 0.985 + (kalite_bonus + reklam_bonus) / 7.0),
      hafta = hafta + 1 where sirket_id = p_id;
    select * into ps from oyun.pazar_sirket where sirket_id = p_id;

    select kasa into kasa_son from oyun.sirketler where id = p_id;
    if kasa_son <= 0 then
      update oyun.sirketler set aktif = false, kasa = 0, satilik = null, son_islem = t,
        sonraki_kazanc = s.sonraki_kazanc + i * interval '1 day' where id = p_id;
      update oyun.borsa_emir set durum = 'iptal' where sirket_id = p_id and durum = 'acik';
      perform oyun.olay('ekonomi', format('%s (%s, %s) iflas etti; kasası tükendi.', s.ad,
        (select ad from oyun.pazar_sektor where kod = s.sektor), ilad), ps.il_id, null, t);
      for x in select user_id from oyun.sirket_ortaklari where sirket_id = p_id loop
        perform oyun.bildir(x.user_id, format('%s iflas etti: şirket kasası tükendi ve faaliyet durdu.', s.ad), t);
      end loop;
      return;
    end if;
  end loop;
  update oyun.sirketler set sonraki_kazanc = sonraki_kazanc + n * interval '1 day', son_islem = t where id = p_id;
  if kasa_son < s.sermaye * 0.25 and (ps.son_uyari is null or ps.son_uyari < t - interval '2 days') then
    update oyun.pazar_sirket set son_uyari = t where sirket_id = p_id;
    for x in select user_id from oyun.sirket_ortaklari where sirket_id = p_id loop
      perform oyun.bildir(x.user_id, format('%s zarar ediyor: kasada %s ₺ kaldı. Fiyat/kaliteyi gözden geçir, otopilotu aç ya da ili değiştir; yoksa iflas edebilir.',
        s.ad, oyun.tl(kasa_son)), t);
    end loop;
  end if;
end $function$;

-- 7) Şirket hesap yönlendirmesi: pazar satırı olan her şirket önce günlük ana faaliyetini kapatır
create or replace function oyun.sirket_hesapla(p_id bigint)
 returns void language plpgsql security definer set search_path to 'oyun', 'public', 'pg_temp'
as $function$
declare s oyun.sirketler;n int;i int;net numeric;income numeric;cost numeric;w numeric;t timestamptz:=oyun.simdi();x record;distributed numeric;rate numeric;v_taahhut numeric;v_mevduat numeric;distributable numeric;v_odeme numeric;
begin
 perform pg_advisory_xact_lock(98763,hashtext(p_id::text));
 select * into s from oyun.sirketler where id=p_id for update;
 if s.id is null or not s.aktif or s.sonraki_kazanc>t then return;end if;
 if exists(select 1 from oyun.pazar_sirket where sirket_id=p_id) then perform oyun.pazar_hesapla(p_id); return; end if;
 if exists(select 1 from oyun.eko_isletmeler where sirket_id=p_id) then
  update oyun.sirketler set sonraki_kazanc=greatest(sonraki_kazanc,t)+interval '1 day',son_islem=t where id=p_id;
  return;
 end if;
 if s.sektor='ajans' then perform oyun.ajans_hesapla(p_id); return; end if;
 -- Buraya yalnız bankalar ve henüz pazar satırı açılmamış eski şirketler düşer (eski haftalık usul).
 n:=least(52,floor(extract(epoch from (t-s.sonraki_kazanc))/604800)::int+1);
 w:=(select asgari from oyun.ulke where id=1);
 rate:=case s.sektor when 'tarim' then .12 when 'sanayi' then .15 when 'teknoloji' then .20 when 'ticaret' then .14 when 'insaat' then .18 when 'medya' then .16 else .08 end;
 for i in 1..n loop
  income:=round(s.sermaye*rate*(0.6+random()::numeric*.8),2);
  cost:=round(s.sermaye*(.025+random()::numeric*.055)+w*(.5+random()::numeric),2);
  income:=round(income * oyun.kriz_sektor_carpani(s.sektor,s.sonraki_kazanc + (i-1) * interval '7 days')
                       * oyun.sektor_pol_carpan(s.sektor,s.sonraki_kazanc + (i-1) * interval '7 days'),2); net:=income-cost;
  distributed:=0;
  if net<0 then
   if s.sektor='banka' then
     select coalesce(sum(round(m.anapara*(1+m.faiz/100),2)),0),coalesce(sum(m.anapara),0) into v_taahhut,v_mevduat from oyun.banka_mevduat m where m.banka_id=p_id and not m.kapandi;
     net:=greatest(net,-greatest(0,(select kasa from oyun.sirketler where id=p_id)-v_taahhut-greatest(s.sermaye*0.10,v_mevduat*0.10)));
   end if;
   update oyun.sirketler set kasa=kasa+net where id=p_id;
  else
   distributable:=case when s.sektor='banka' then least(net,greatest(0,(select kasa from oyun.sirketler where id=p_id)+net-s.sermaye-coalesce((select sum(round(m.anapara*(1+m.faiz/100),2)) from oyun.banka_mevduat m where m.banka_id=p_id and not m.kapandi),0))) else least(net,greatest(0,(select kasa from oyun.sirketler where id=p_id)+net)) end;
   for x in select * from oyun.sirket_ortaklari where sirket_id=p_id loop
    if not x.kar_kasada then
      v_odeme:=least(round(distributable*x.pay/100,2),greatest(0,distributable-distributed));
      if v_odeme>0 then
        perform oyun.para_islem(x.user_id,v_odeme,'sirket',format('Sirket #%s haftalik net kar payi',p_id),t);
        distributed:=distributed+v_odeme;
      end if;
    end if;
   end loop;
   update oyun.sirketler set kasa=kasa+net-distributed where id=p_id;
  end if;
  insert into oyun.sirket_hareket(sirket_id,zaman,tutar,aciklama,faaliyet_gelir,faaliyet_gider,dagitilan_kar)
 values(p_id,t,net,'7 günlük faaliyet: gelir - gider = net sonuç; gerçekleşen ortak ödemesi ayrıca kaydedildi',income,cost,distributed);
 end loop;
 update oyun.sirketler set sonraki_kazanc=sonraki_kazanc+n*interval '7 days',son_islem=t where id=p_id;
end $function$;

-- 8) Ruhsat ve paravan kapıları: sistemin kendi açtığı ana faaliyet satırı için atlanır
create or replace function oyun.bel_ruhsat_kapi()
 returns trigger language plpgsql security definer set search_path to ''
as $function$
declare u uuid:=auth.uid(); sid bigint; il smallint; hedef bigint; tip text;
 s oyun.sirketler; r oyun.bel_yatirim_ruhsat; tutar numeric; matrah numeric; il_ad text;
begin
 if coalesce(current_setting('oyun.ekonomi3_oto', true), '') = '1' then return new; end if;
 if u is null then raise exception 'Yatırım işlemi için oyuncu oturumu gerekli.';end if;
 if tg_table_name='eko_isletmeler' then
   sid:=new.sirket_id; il:=new.il_id; tip:='kur_'||new.tur;
 elsif tg_table_name='pazar_sirket' then
   sid:=new.sirket_id; il:=new.il_id; tip:='kur_pazar';
 elsif tg_table_name='eko_yapilar' then
   sid:=new.sirket_id; il:=new.il_id; tip:='arsa_insaat'; hedef:=new.arsa_id;
 elsif tg_table_name='eko_projeler' then
   sid:=new.sirket_id; il:=new.il_id; tip:='yeni_proje';
 elsif tg_table_name='eko_subeler' then
   sid:=new.sirket_id; tip:='sube'; hedef:=new.bolum_id;
   select y.il_id into il from oyun.eko_bolumler b join oyun.eko_yapilar y on y.id=b.yapi_id where b.id=hedef;
 else return new; end if;
 select * into s from oyun.sirketler where id=sid;
 if s.id is null or not s.aktif or not oyun.sirket_yonetici_mi(sid,u) then raise exception 'Ruhsat için şirket yönetim yetkisi gerekli.';end if;
 select * into r from oyun.bel_yatirim_ruhsat br
 where br.oyuncu=u and br.il_id=il and br.tur=tip and br.durum='onay'
 and (br.sirket_id=sid or (br.sirket_id is null and br.sirket_adi=s.ad))
 and (br.hedef_id is null or br.hedef_id=hedef)
 and (br.sektor is null or br.sektor=s.sektor)
 and br.karar_zamani>now()-interval '72 hours'
 order by br.id asc limit 1 for update;
 if r.id is null then
  raise exception 'Bu yatırım için % belediyesinden onaylı ruhsat gerekli. Ekonomi veya Belediye menüsündeki Ruhsat Merkezi üzerinden başvur.',(select ad from oyun.iller where id=il);
 end if;
 matrah:=case when tg_table_name in ('eko_yapilar','eko_projeler')
   then coalesce((to_jsonb(new)->>'maliyet')::numeric,0)
   when tg_table_name='eko_subeler' then greatest(0,s.sermaye*0.10)
   else s.sermaye end;
 tutar:=oyun.bel_ruhsat_tutar(r.onay_oran,r.onay_taban,matrah);
 update oyun.sirketler set kasa=kasa-tutar where id=sid and kasa>=tutar;
 if not found then raise exception 'Ruhsat harcı için şirket kasasında % TL gerekli.',tutar;end if;
 update oyun.il_durum set kasa=kasa+tutar/nullif(oyun.pazar_tl_milyar(),0) where il_id=il;
 update oyun.bel_yatirim_ruhsat set durum='kullanildi',odenen_tl=tutar,kullanma=now() where id=r.id;
 insert into oyun.belediye_sehir_hareket(il_id,tur,tutar,aciklama,zaman)
 values(il,'ruhsat_geliri',tutar/nullif(oyun.pazar_tl_milyar(),0),format('%s ruhsatı (#%s) - %s TL belediye geliri',tip,r.id,tutar),oyun.simdi());
 return new;
end $function$;

create or replace function oyun.tg_pazar_paravan()
 returns trigger language plpgsql security definer set search_path to ''
as $function$
declare v_sektor text; u uuid;
begin
  if coalesce(current_setting('oyun.ekonomi3_oto', true), '') = '1' then return new; end if;
  select sektor into v_sektor from oyun.sirketler where id = new.sirket_id;
  for u in select user_id from oyun.sirket_ortaklari where sirket_id = new.sirket_id and pay >= 50 loop
    if exists (select 1 from oyun.pazar_sirket p2 join oyun.sirketler s2 on s2.id = p2.sirket_id
               join oyun.sirket_ortaklari o2 on o2.sirket_id = s2.id and o2.user_id = u and o2.pay >= 50
               where p2.il_id = new.il_id and s2.sektor = v_sektor and s2.aktif and s2.id <> new.sirket_id) then
      raise exception 'Paravan şirket kuralı: bu ilde aynı türde çoğunluğuna sahip olduğun bir şirket zaten var.';
    end if;
  end loop;
  return new;
end $function$;

-- 9) Ana faaliyet satırı açma: pazar satırı olmayan aktif şirketlere (banka, ajans hariç).
--    İl: işletmenin ili, yoksa en büyük ortağın ikamet ili. Kuruluş işlemi tamamlandıktan sonra
--    zamanlayıcı açar; böylece kuruluş ruhsatı akışı değişmez.
create or replace function oyun.ana_faaliyet_ac()
 returns int language plpgsql security definer set search_path to ''
as $function$
declare r record; n int := 0; v_il smallint;
begin
  perform set_config('oyun.ekonomi3_oto', '1', true);
  for r in select s.* from oyun.sirketler s
           where s.aktif and s.sektor in (select kod from oyun.pazar_sektor)
             and not exists (select 1 from oyun.pazar_sirket p where p.sirket_id = s.id)
             and s.kurulus < now() - interval '2 minutes'
           order by s.id limit 100
  loop
    v_il := coalesce((select il_id from oyun.eko_isletmeler where sirket_id = r.id),
                     (select il_id from oyun.profiller where id = oyun.sirket_sahibi(r.id)),
                     (select il_id from oyun.profiller where id = r.kurucu), 34);
    insert into oyun.pazar_sirket(sirket_id, il_id, fiyat, kalite, kaynak)
    values (r.id, v_il, 2, 1, case when r.sektor = 'enerji' then 'dogalgaz' end)
    on conflict (sirket_id) do nothing;
    -- işletmesi (mağaza/fabrika/şantiye) olmayan eski şirketler için en kârlı büyük il seçilir
    if not exists (select 1 from oyun.eko_isletmeler where sirket_id = r.id) then
      declare c smallint; en_il smallint := v_il; en_net numeric; h numeric;
      begin
        en_net := (oyun.pazar_tahmin(r.id)->>'net')::numeric;
        foreach c in array array[34,6,35,16,7,41,1,42,27,33,v_il]::smallint[] loop
          update oyun.pazar_sirket set il_id = c where sirket_id = r.id;
          h := (oyun.pazar_tahmin(r.id)->>'net')::numeric;
          if h > en_net then en_net := h; en_il := c; end if;
        end loop;
        update oyun.pazar_sirket set il_id = en_il where sirket_id = r.id;
      end;
    end if;
    -- günlük kesim kuruluştan bir gün sonra başlar
    update oyun.sirketler set sonraki_kazanc = least(coalesce(sonraki_kazanc, now()), greatest(kurulus + interval '1 day', now() - interval '29 days'))
      where id = r.id;
    n := n + 1;
  end loop;
  perform set_config('oyun.ekonomi3_oto', '', true);
  -- eski haftalık takvimde kalan şirketler günlük takvime çekilir
  update oyun.sirketler s set sonraki_kazanc = s.kurulus + interval '1 day'
    where s.aktif and s.sonraki_kazanc > now() + interval '1 day'
      and exists (select 1 from oyun.pazar_sirket p where p.sirket_id = s.id)
      and not exists (select 1 from oyun.eko_gunluk g where g.sirket_id = s.id);
  return n;
end $function$;

-- 10) Pazar kurma: ana faaliyet satırı varsa çakışmasın
create or replace function public.pazar_sirket_kur(p_ad text, p_sektor text, p_sermaye numeric, p_il integer, p_kaynak text default null::text)
 returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare p oyun.profiller := oyun.profilim(); k oyun.pazar_sektor; v_id bigint; t timestamptz := oyun.simdi(); ilad text;
begin
  select * into k from oyun.pazar_sektor where kod = p_sektor;
  if k.kod is null then raise exception 'Geçersiz şirket türü.'; end if;
  if p_ad is null or char_length(btrim(p_ad)) not between 3 and 50 then raise exception 'Şirket adı 3-50 karakter olmalı.'; end if;
  if not exists (select 1 from oyun.iller where id = p_il) then raise exception 'Geçersiz il.'; end if;
  if p_sermaye is null or p_sermaye <> round(p_sermaye) or p_sermaye < k.min_sermaye or p_sermaye > 100000000 then
    raise exception '% için kuruluş sermayesi en az % ₺, en fazla 100.000.000 ₺ olmalı.', k.ad, oyun.tl(k.min_sermaye);
  end if;
  if p_sektor = 'enerji' and coalesce(p_kaynak, 'dogalgaz') not in ('komur','dogalgaz','yenilenebilir') then raise exception 'Geçersiz enerji kaynağı.'; end if;
  if (select count(*) from oyun.sirket_ortaklari o join oyun.sirketler s on s.id = o.sirket_id
      where o.user_id = p.id and s.kurucu = p.id and s.aktif and s.kurulus > t - interval '24 hours') >= 3 then
    raise exception 'Son 24 saatte en fazla 3 şirket kurabilirsin.';
  end if;
  perform oyun.para_islem(p.id, -p_sermaye, 'sirket', format('%s kuruluş sermayesi', k.ad), t);
  insert into oyun.sirketler(ad, sektor, kurucu, sermaye, kasa, son_islem, kurulus, sonraki_kazanc) values (btrim(p_ad), p_sektor, p.id, p_sermaye, p_sermaye, t, t, t + interval '1 day')
    returning id into v_id;
  insert into oyun.sirket_ortaklari(sirket_id, user_id, pay) values (v_id, p.id, 100);
  insert into oyun.pazar_sirket(sirket_id, il_id, kaynak) values (v_id, p_il,
    case when p_sektor = 'enerji' then coalesce(p_kaynak, 'dogalgaz') end);
  select ad into ilad from oyun.iller where id = p_il;
  perform oyun.olay('ekonomi', format('%s, %s''da %s açtı: %s.', p.kad, ilad, lower(k.ad), btrim(p_ad)), p_il::smallint, null, t);
  return jsonb_build_object('id', v_id, 'tahmin', oyun.pazar_tahmin(v_id));
end $function$;

-- 11) Reklam bütçesi kararı
create or replace function public.sirket_reklam_ayarla(p_sirket bigint, p_seviye integer)
 returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare p oyun.profiller := oyun.profilim(); ps oyun.pazar_sirket;
begin
  select * into ps from oyun.pazar_sirket where sirket_id = p_sirket;
  if ps.sirket_id is null then raise exception 'Şirketin ana faaliyeti henüz açılmadı; birkaç dakika sonra tekrar dene.'; end if;
  if not oyun.sirket_yonetici_mi(p_sirket, p.id) then raise exception 'Reklam bütçesini şirketin yöneticisi belirler.'; end if;
  if p_seviye not between 0 and 3 then raise exception 'Reklam seviyesi 0-3 olmalı.'; end if;
  perform oyun.sirket_hesapla(p_sirket);
  update oyun.pazar_sirket set reklam = p_seviye where sirket_id = p_sirket;
  return oyun.pazar_tahmin(p_sirket);
end $function$;

-- 12) Zamanlayıcı: önce ana faaliyet satırlarını aç, sonra vadesi gelenleri kapat
create or replace function oyun.pazar_tick()
 returns integer language plpgsql security definer set search_path to ''
as $function$
declare r record; n int := 0;
begin
  perform oyun.ana_faaliyet_ac();
  perform oyun.ihale_tick();
  perform oyun.rekabet_tick();
  perform oyun.ajans_tick();
  for r in select s.id from oyun.sirketler s
           where s.aktif and s.sonraki_kazanc <= oyun.simdi()
             and (exists (select 1 from oyun.pazar_sirket ps where ps.sirket_id = s.id) or s.sektor = 'ajans')
           order by s.sonraki_kazanc limit 200 loop
    perform oyun.sirket_hesapla(r.id); n := n + 1;
  end loop;
  perform oyun.piyasa_endeks_tick();
  return n;
end $function$;

-- 13) Yetkiler
revoke all on function public.sirket_reklam_ayarla(bigint, integer) from public, anon;
grant execute on function public.sirket_reklam_ayarla(bigint, integer) to authenticated;
revoke all on function oyun.b2b_ode(bigint, text, numeric, smallint, text, date) from public, anon, authenticated;
revoke all on function oyun.ana_faaliyet_ac() from public, anon, authenticated;
-- 99c · EKONOMİ 3.0 — şirket değeri, piyasa endeksi, genel kurul, hukuki tür, marka filtresi (2026-10-15)
-- İki kez çalıştırılabilir.

-- 1) Hukuki tür ve profesyonel yönetici
alter table oyun.sirketler add column if not exists tur_hukuki text not null default 'ltd';
alter table oyun.sirketler add column if not exists yonetici uuid references oyun.profiller(id) on delete set null;
do $$ begin
  alter table oyun.sirketler add constraint sirketler_tur_hukuki_ck check (tur_hukuki in ('ltd','as'));
exception when duplicate_object then null; end $$;
update oyun.sirketler set tur_hukuki = 'as' where halka_acik and tur_hukuki <> 'as';

-- Yönetim yetkisi: genel kurulun atadığı yönetici (CEO) ya da en az %50 pay sahibi; atanmış yönetici
-- yoksa eskisi gibi en büyük ortak.
create or replace function oyun.sirket_yonetici_mi(p_sirket bigint, u uuid)
 returns boolean language sql stable set search_path to ''
as $function$
  select case
    when (select yonetici from oyun.sirketler where id = p_sirket) is not null then
      u = (select yonetici from oyun.sirketler where id = p_sirket)
      or exists (select 1 from oyun.sirket_ortaklari o where o.sirket_id = p_sirket and o.user_id = u and o.pay >= 50)
    else exists (select 1 from oyun.sirket_ortaklari o where o.sirket_id = p_sirket and o.user_id = u
                 and (o.pay >= 50 or o.pay >= (select max(pay) from oyun.sirket_ortaklari where sirket_id = p_sirket)))
  end
$function$;

-- Halka arz yalnız anonim şirkette (TTK: borsada işlem görmek için A.Ş. olmak gerekir)
create or replace function oyun.tg_halka_arz_as()
 returns trigger language plpgsql security definer set search_path to ''
as $function$
begin
  if (select tur_hukuki from oyun.sirketler where id = new.sirket_id) <> 'as' then
    raise exception 'Halka arz için şirketin anonim şirket (A.Ş.) olması gerekir. Önce şirket karnesinden A.Ş.''ye dönüştür (en az 250.000 ₺ sermaye).';
  end if;
  return new;
end $function$;
create or replace trigger halka_arz_as before insert on oyun.halka_arz for each row execute function oyun.tg_halka_arz_as();

create or replace function public.sirket_as_donustur(p_sirket bigint)
 returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare p oyun.profiller := oyun.profilim(); s oyun.sirketler; harc numeric;
begin
  select * into s from oyun.sirketler where id = p_sirket for update;
  if s.id is null or not s.aktif then raise exception 'Şirket bulunamadı.'; end if;
  if not oyun.sirket_yonetici_mi(s.id, p.id) then raise exception 'Tür değişikliğini şirketin yöneticisi başlatır.'; end if;
  if s.tur_hukuki = 'as' then raise exception 'Şirket zaten anonim şirket.'; end if;
  if s.sermaye < 250000 then raise exception 'Anonim şirket için en az 250.000 ₺ sermaye gerekir (şu an %s ₺). Önce sermaye artır.', oyun.tl(s.sermaye); end if;
  harc := greatest(2500, round(s.sermaye * 0.005));
  if s.kasa < harc then raise exception 'Tescil harcı için şirket kasasında % ₺ gerekli.', oyun.tl(harc); end if;
  update oyun.sirketler set kasa = kasa - harc, tur_hukuki = 'as' where id = s.id;
  update oyun.ulke set hazine = hazine + harc / oyun.pazar_tl_milyar() where id = 1;
  insert into oyun.sirket_hareket(sirket_id, zaman, tutar, aciklama, faaliyet_gelir, faaliyet_gider, dagitilan_kar)
  values (s.id, oyun.simdi(), -harc, 'Anonim şirkete dönüşüm: ticaret sicili tescil harcı', 0, harc, 0);
  perform oyun.olay('ekonomi', format('%s anonim şirkete dönüştü; artık halka arz edilebilir.', s.ad), null, null, oyun.simdi());
  return jsonb_build_object('tamam', true, 'harc', harc);
end $function$;

-- 2) Gerçek şirket ve marka adları kullanılamaz (yalnız yeni kayıt ve ad değişikliğinde)
create or replace function oyun.yasakli_marka(p_ad text)
 returns text language sql immutable set search_path to ''
as $function$
  select m from unnest(array[
    'koç holding','sabancı holding','aselsan','roketsan','tusaş','havelsan','baykar','tüpraş','petkim','erdemir',
    'migros','bim','a101','carrefoursa','turkcell','türk telekom','vodafone','türk hava yolları','thy',
    'pegasus','arçelik','vestel','beko','tofaş','ford','toyota','renault','mercedes','bmw','şişecam','ülker','torku',
    'sütaş','garanti bankası','garanti bbva','iş bankası','akbank','yapı kredi','ziraat bankası','halkbank','vakıfbank','qnb','denizbank',
    'enerjisa','limak','kalyon','kolin','emlak konut','demirören','apple','google','microsoft',
    'nvidia','amazon','tesla','facebook','samsung','coca cola','coca-cola','pepsi','mcdonalds','burger king','starbucks',
    'trendyol','hepsiburada','yemeksepeti','show tv','kanal d','star tv','fox tv','trt','cnn türk','ntv','habertürk',
    'sözcü gazetesi','atv','tv8'
  ]) m
  where lower(translate(coalesce(p_ad,''), 'İIŞĞÜÖÇ', 'iışğüöç')) ~ ('(^|[^[:alnum:]çğıöşü])' || regexp_replace(m, '([.+*?^$(){}|\[\]\\-])', '\\\1', 'g') || '($|[^[:alnum:]çğıöşü])')
  limit 1
$function$;

create or replace function oyun.tg_sirket_ad_kontrol()
 returns trigger language plpgsql security definer set search_path to ''
as $function$
declare m text;
begin
  if tg_op = 'UPDATE' and new.ad is not distinct from old.ad then return new; end if;
  m := oyun.yasakli_marka(new.ad);
  if m is not null then
    raise exception 'Gerçek bir şirketin ya da markanın adı (%) kullanılamaz. Oyun kurgudur; kendi markanı yarat.', m;
  end if;
  return new;
end $function$;
create or replace trigger sirket_ad_kontrol before insert or update of ad on oyun.sirketler for each row execute function oyun.tg_sirket_ad_kontrol();

-- 3) Şirket değeri
create table if not exists oyun.sirket_deger_gecmis(
  sirket_id bigint not null references oyun.sirketler(id) on delete cascade,
  gun date not null, defter numeric not null, kar7 numeric not null, deger numeric not null,
  piyasa numeric, guncelleme timestamptz not null default now(),
  primary key(sirket_id, gun));
create index if not exists sirket_deger_gecmis_gun on oyun.sirket_deger_gecmis(gun);
create table if not exists oyun.piyasa_endeks(
  gun date primary key, deger numeric not null, onceki numeric, toplam numeric not null,
  sirket_sayisi int not null, kapanis boolean not null default false, guncelleme timestamptz not null default now());
alter table oyun.sirket_deger_gecmis enable row level security;
alter table oyun.piyasa_endeks enable row level security;

create or replace function oyun.sirket_kar7(p_sirket bigint)
 returns numeric language sql stable set search_path to ''
as $function$
  select coalesce((select sum(net) from oyun.eko_gunluk where sirket_id = p_sirket
                    and gun > (now() at time zone 'Europe/Istanbul')::date - 7), 0)
       + coalesce((select sum(net_kar) from oyun.eko_kar_kayit where sirket_id = p_sirket
                    and gun > (now() at time zone 'Europe/Istanbul')::date - 7), 0)
       + coalesce((select sum(tutar) from oyun.sirket_hareket where sirket_id = p_sirket
                    and aciklama like '7 günlük faaliyet (ajans)%' and zaman > now() - interval '7 days'), 0)
$function$;

create or replace function oyun.sirket_defter(p_sirket bigint)
 returns numeric language sql stable set search_path to ''
as $function$
  select greatest(0,
     s.kasa
   + coalesce((select sum(adet * maliyet_birim) from oyun.eko_urun_stok where sirket_id = s.id), 0)
   + coalesce((select sum(fiyat) from oyun.eko_arsalar where sahibi_sirket = s.id), 0)
   + coalesce((select sum(maliyet) from oyun.eko_yapilar where sirket_id = s.id), 0)
   + case when s.sektor = 'banka' then
       coalesce((select sum(kalan) from oyun.oyb_kredi where banka_id = s.id and durum = 'aktif'), 0)
     - coalesce((select sum(round(m.anapara * (1 + m.faiz / 100), 2)) from oyun.banka_mevduat m where m.banka_id = s.id and not m.kapandi), 0)
     else 0 end)
  from oyun.sirketler s where s.id = p_sirket
$function$;

-- Değer = defter değeri + son 7 günün net kârı × 10 (zarar ×3 düşer; değer defterin yarısının altına inmez)
create or replace function oyun.sirket_deger(p_sirket bigint)
 returns numeric language sql stable set search_path to ''
as $function$
  select round(greatest(d * 0.5, d + case when k > 0 then k * 10 else k * 3 end))
  from (select oyun.sirket_defter(p_sirket) d, oyun.sirket_kar7(p_sirket) k) x
$function$;

create or replace function oyun.piyasa_degerle()
 returns numeric language plpgsql security definer set search_path to ''
as $function$
declare g date := (now() at time zone 'Europe/Istanbul')::date; onceki oyun.piyasa_endeks; bugun_t numeric; dun_t numeric; e numeric; n int;
begin
  insert into oyun.sirket_deger_gecmis(sirket_id, gun, defter, kar7, deger, piyasa, guncelleme)
  select s.id, g, oyun.sirket_defter(s.id), oyun.sirket_kar7(s.id), oyun.sirket_deger(s.id),
         case when s.halka_acik then oyun.borsa_son_fiyat(s.id) * 100 end, now()
  from oyun.sirketler s where s.aktif
  on conflict on constraint sirket_deger_gecmis_pkey do update set defter = excluded.defter, kar7 = excluded.kar7,
     deger = excluded.deger, piyasa = excluded.piyasa, guncelleme = excluded.guncelleme;
  select * into onceki from oyun.piyasa_endeks where gun < g order by gun desc limit 1;
  select coalesce(sum(coalesce(piyasa, deger)), 0), count(*) into bugun_t, n from oyun.sirket_deger_gecmis d
    join oyun.sirketler s on s.id = d.sirket_id and s.aktif where d.gun = g;
  if onceki.gun is null then
    e := 1000;
  else
    -- zincirleme endeks: yalnız iki günde de var olan şirketlerin değişimi (yeni şirket endeksi şişirmez)
    select coalesce(sum(coalesce(b.piyasa, b.deger)), 0), coalesce(sum(coalesce(a.piyasa, a.deger)), 0) into bugun_t, dun_t
    from oyun.sirket_deger_gecmis b join oyun.sirket_deger_gecmis a on a.sirket_id = b.sirket_id and a.gun = onceki.gun
    where b.gun = g;
    e := round(onceki.deger * case when dun_t > 0 then bugun_t / dun_t else 1 end, 2);
    select coalesce(sum(coalesce(piyasa, deger)), 0) into bugun_t from oyun.sirket_deger_gecmis where gun = g;
  end if;
  insert into oyun.piyasa_endeks(gun, deger, onceki, toplam, sirket_sayisi, guncelleme)
  values (g, e, onceki.deger, bugun_t, n, now())
  on conflict (gun) do update set deger = excluded.deger, onceki = excluded.onceki, toplam = excluded.toplam,
    sirket_sayisi = excluded.sirket_sayisi, guncelleme = excluded.guncelleme;
  return e;
end $function$;

-- 4) Genel kurul
create table if not exists oyun.genel_kurul(
  id bigserial primary key,
  sirket_id bigint not null references oyun.sirketler(id) on delete cascade,
  tur text not null check (tur in ('temettu','yonetici','ad','tasfiye')),
  baslik text not null, veri jsonb not null default '{}'::jsonb,
  acan uuid not null references oyun.profiller(id),
  bas timestamptz not null default now(), bit timestamptz not null,
  durum text not null default 'acik' check (durum in ('acik','kabul','ret','iptal')),
  evet numeric not null default 0, hayir numeric not null default 0, katilim numeric not null default 0,
  sonuc text, sonuc_at timestamptz);
create unique index if not exists genel_kurul_tek_acik on oyun.genel_kurul(sirket_id, tur) where durum = 'acik';
create table if not exists oyun.genel_kurul_oy(
  kurul_id bigint not null references oyun.genel_kurul(id) on delete cascade,
  user_id uuid not null references oyun.profiller(id),
  oy boolean not null, pay numeric not null, zaman timestamptz not null default now(),
  primary key(kurul_id, user_id));
alter table oyun.genel_kurul enable row level security;
alter table oyun.genel_kurul_oy enable row level security;

create or replace function oyun.genel_kurul_say(p_id bigint)
 returns void language plpgsql security definer set search_path to ''
as $function$
begin
  update oyun.genel_kurul k set
    evet = coalesce((select sum(o.pay) from oyun.genel_kurul_oy v join oyun.sirket_ortaklari o
                     on o.sirket_id = k.sirket_id and o.user_id = v.user_id where v.kurul_id = k.id and v.oy), 0),
    hayir = coalesce((select sum(o.pay) from oyun.genel_kurul_oy v join oyun.sirket_ortaklari o
                     on o.sirket_id = k.sirket_id and o.user_id = v.user_id where v.kurul_id = k.id and not v.oy), 0)
  where k.id = p_id;
  update oyun.genel_kurul set katilim = evet + hayir where id = p_id;
end $function$;

create or replace function oyun.genel_kurul_kapat(p_id bigint, p_zorla boolean default false)
 returns text language plpgsql security definer set search_path to ''
as $function$
declare k oyun.genel_kurul; s oyun.sirketler; esik numeric; karar text; t timestamptz := oyun.simdi();
  x record; stopaj numeric; brut numeric; u uuid; v_ad text;
begin
  perform oyun.genel_kurul_say(p_id);
  select * into k from oyun.genel_kurul where id = p_id for update;
  if k.id is null or k.durum <> 'acik' then return null; end if;
  esik := case when k.tur = 'tasfiye' then 75 else 50 end;
  -- erken sonuç: evet eşiği aşıldıysa ya da artık aşılamayacaksa
  if k.evet > esik or (k.tur = 'tasfiye' and k.evet >= esik) then karar := 'kabul';
  elsif k.hayir >= 100 - esik then karar := 'ret';
  elsif p_zorla or k.bit <= t then
    karar := case when k.katilim >= 25 and k.evet > k.hayir and (k.tur <> 'tasfiye' or k.evet >= 75 * k.katilim / 100) then 'kabul' else 'ret' end;
  else return null; end if;

  select * into s from oyun.sirketler where id = k.sirket_id for update;
  if karar = 'kabul' and s.aktif then
    if k.tur = 'temettu' then
      brut := least((k.veri->>'tutar')::numeric, greatest(0, s.kasa));
      if brut > 0 then
        update oyun.sirketler set kasa = kasa - brut where id = s.id;
        stopaj := oyun.eko_vergi_tahsil(s.id, 'dagitim', brut, 'genel_kurul_temettu', k.id);
        for x in select * from oyun.sirket_ortaklari where sirket_id = s.id loop
          perform oyun.para_islem(x.user_id, round((brut - stopaj) * x.pay / 100, 2), 'sirket',
            format('%s genel kurul temettüsü (%%%s stopaj kesildi)', s.ad, oyun.eko_vergi_oran('stopaj')), t, round(stopaj * x.pay / 100, 2));
        end loop;
        insert into oyun.sirket_hareket(sirket_id, zaman, tutar, aciklama, faaliyet_gelir, faaliyet_gider, dagitilan_kar)
        values (s.id, t, -brut, format('Genel kurul kararıyla temettü dağıtıldı (#%s)', k.id), 0, 0, brut);
      end if;
      k.sonuc := format('%s ₺ temettü dağıtıldı.', oyun.tl(brut));
    elsif k.tur = 'yonetici' then
      u := (k.veri->>'user')::uuid;
      update oyun.sirketler set yonetici = u where id = s.id;
      perform oyun.bildir(u, format('%s genel kurulu seni şirketin yöneticisi (CEO) olarak atadı. Fiyat, kalite, reklam ve yatırım kararlarını artık sen veriyorsun.', s.ad), t);
      k.sonuc := format('%s yönetici (CEO) olarak atandı.', coalesce(oyun.kad(u), 'Yönetici'));
    elsif k.tur = 'ad' then
      v_ad := k.veri->>'ad';
      begin
        update oyun.sirketler set ad = v_ad where id = s.id;
        k.sonuc := format('Şirketin yeni adı: %s.', v_ad);
      exception when others then
        karar := 'ret'; k.sonuc := 'Ad değişikliği tescil edilemedi: ' || sqlerrm;
      end;
    elsif k.tur = 'tasfiye' then
      for x in select * from oyun.sirket_ortaklari where sirket_id = s.id loop
        if greatest(0, s.kasa) * x.pay / 100 > 0 then
          perform oyun.para_islem(x.user_id, round(greatest(0, s.kasa) * x.pay / 100, 2), 'sirket', format('%s tasfiye payı', s.ad), t);
        end if;
      end loop;
      update oyun.sirketler set aktif = false, kasa = 0, satilik = null, son_islem = t where id = s.id;
      update oyun.borsa_emir set durum = 'iptal' where sirket_id = s.id and durum = 'acik';
      perform oyun.olay('ekonomi', format('%s genel kurul kararıyla tasfiye edildi; kasası ortaklarına dağıtıldı.', s.ad), null, null, t);
      k.sonuc := 'Şirket tasfiye edildi, kasa ortaklara dağıtıldı.';
    end if;
  end if;
  update oyun.genel_kurul set durum = karar, sonuc = coalesce(k.sonuc, case when karar = 'ret' then 'Önerge reddedildi.' end), sonuc_at = t where id = k.id;
  for x in select user_id from oyun.sirket_ortaklari where sirket_id = k.sirket_id loop
    perform oyun.bildir(x.user_id, format('%s genel kurulu: "%s" önergesi %s. %s', s.ad, k.baslik,
      case when karar = 'kabul' then 'kabul edildi' else 'reddedildi' end, coalesce(k.sonuc, '')), t);
  end loop;
  return karar;
end $function$;

create or replace function public.genel_kurul_ac(p_sirket bigint, p_tur text, p_veri jsonb default '{}'::jsonb)
 returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare p oyun.profiller := oyun.profilim(); s oyun.sirketler; benim numeric; v_id bigint; baslik text; hedef uuid; t timestamptz := oyun.simdi(); x record; sonuc text;
begin
  select * into s from oyun.sirketler where id = p_sirket;
  if s.id is null or not s.aktif then raise exception 'Şirket bulunamadı.'; end if;
  select pay into benim from oyun.sirket_ortaklari where sirket_id = s.id and user_id = p.id;
  if coalesce(benim, 0) < 5 and not oyun.sirket_yonetici_mi(s.id, p.id) then
    raise exception 'Genel kurula önerge vermek için en az %%5 pay sahibi ya da şirketin yöneticisi olmalısın.';
  end if;
  if exists (select 1 from oyun.genel_kurul where sirket_id = s.id and tur = p_tur and durum = 'acik') then
    raise exception 'Bu konuda açık bir önerge zaten var.';
  end if;
  if p_tur = 'temettu' then
    if coalesce((p_veri->>'tutar')::numeric, 0) < 1000 or (p_veri->>'tutar')::numeric > s.kasa * 0.9 then
      raise exception 'Temettü en az 1.000 ₺ ve şirket kasasının en fazla %%90''ı olabilir (kasa %s ₺).', oyun.tl(s.kasa);
    end if;
    baslik := format('%s ₺ temettü dağıtılması', oyun.tl((p_veri->>'tutar')::numeric));
  elsif p_tur = 'yonetici' then
    select id into hedef from oyun.profiller where lower(kad) = lower(btrim(coalesce(p_veri->>'kad', '')));
    if hedef is null then raise exception 'Bu kullanıcı adında oyuncu bulunamadı.'; end if;
    p_veri := jsonb_build_object('user', hedef, 'kad', oyun.kad(hedef));
    baslik := format('%s yönetici (CEO) olarak atansın', oyun.kad(hedef));
  elsif p_tur = 'ad' then
    if char_length(btrim(coalesce(p_veri->>'ad', ''))) not between 3 and 50 then raise exception 'Şirket adı 3-50 karakter olmalı.'; end if;
    if oyun.yasakli_marka(p_veri->>'ad') is not null then raise exception 'Gerçek bir şirketin ya da markanın adı kullanılamaz.'; end if;
    p_veri := jsonb_build_object('ad', btrim(p_veri->>'ad'));
    baslik := format('Şirketin adı "%s" olsun', p_veri->>'ad');
  elsif p_tur = 'tasfiye' then
    p_veri := '{}'::jsonb;
    baslik := 'Şirket tasfiye edilsin, kasa ortaklara dağıtılsın';
  else raise exception 'Geçersiz önerge türü.'; end if;

  insert into oyun.genel_kurul(sirket_id, tur, baslik, veri, acan, bas, bit)
  values (s.id, p_tur, baslik, p_veri, p.id, t, t + interval '24 hours') returning id into v_id;
  if coalesce(benim, 0) > 0 then
    insert into oyun.genel_kurul_oy(kurul_id, user_id, oy, pay) values (v_id, p.id, true, benim);
  end if;
  for x in select user_id from oyun.sirket_ortaklari where sirket_id = s.id and user_id <> p.id loop
    perform oyun.bildir(x.user_id, format('%s genel kuruluna önerge geldi: "%s" (%s). 24 saat içinde oy ver.', s.ad, baslik, p.kad), t);
  end loop;
  sonuc := oyun.genel_kurul_kapat(v_id);
  return jsonb_build_object('id', v_id, 'durum', coalesce(sonuc, 'acik'));
end $function$;

create or replace function public.genel_kurul_oy(p_kurul bigint, p_oy boolean)
 returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare p oyun.profiller := oyun.profilim(); k oyun.genel_kurul; benim numeric; sonuc text;
begin
  select * into k from oyun.genel_kurul where id = p_kurul;
  if k.id is null or k.durum <> 'acik' then raise exception 'Bu önerge oylamaya açık değil.'; end if;
  select pay into benim from oyun.sirket_ortaklari where sirket_id = k.sirket_id and user_id = p.id;
  if coalesce(benim, 0) <= 0 then raise exception 'Genel kurulda yalnız ortaklar oy kullanır.'; end if;
  insert into oyun.genel_kurul_oy(kurul_id, user_id, oy, pay) values (k.id, p.id, p_oy, benim)
  on conflict (kurul_id, user_id) do update set oy = excluded.oy, pay = excluded.pay, zaman = now();
  sonuc := oyun.genel_kurul_kapat(k.id);
  return jsonb_build_object('durum', coalesce(sonuc, 'acik'));
end $function$;

-- 5) Borsa: haftalık net artık günlük faaliyetten
create or replace function oyun.borsa_haftalik_net(p_sirket bigint)
 returns numeric language sql stable set search_path to ''
as $function$
  select case when exists (select 1 from oyun.eko_gunluk where sirket_id = p_sirket)
    then round(oyun.sirket_kar7(p_sirket))
    else coalesce((select round(avg(tutar)) from (select tutar from oyun.sirket_hareket where sirket_id = p_sirket and faaliyet_gelir > 0
      and aciklama like '7 günlük%' order by zaman desc, id desc limit 4) z), 0) end
$function$;

do $$ declare d text; begin
  d := pg_get_functiondef('public.borsa_sirket(bigint)'::regprocedure);
  d := replace(d, $q$'haftalar',coalesce((select jsonb_agg(jsonb_build_object('zaman',h.zaman,'net',h.tutar) order by h.zaman)
       from (select zaman,tutar from oyun.sirket_hareket
         where sirket_id=s.id and faaliyet_gelir>0 and aciklama like '7 günlük%'
         order by zaman desc,id desc limit 8) h),'[]'::jsonb),$q$,
   $q$'haftalar',coalesce((select jsonb_agg(jsonb_build_object('zaman',h.zaman,'net',h.tutar) order by h.zaman)
       from (select zaman,tutar from oyun.sirket_hareket
         where sirket_id=s.id and faaliyet_gelir>0 and aciklama like '7 günlük%'
         union all
         select (date_trunc('week', gun::timestamp) + interval '7 days')::timestamptz, sum(net)
           from oyun.eko_gunluk where sirket_id=s.id group by date_trunc('week', gun::timestamp)
         order by 1 desc limit 8) h),'[]'::jsonb),$q$);
  execute d;
end $$;

-- 6) Piyasa panosu ve şirket karnesi
create or replace function public.piyasa_panosu()
 returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare p oyun.profiller := oyun.profilim(); g date := (now() at time zone 'Europe/Istanbul')::date; e oyun.piyasa_endeks; dun date;
begin
  select * into e from oyun.piyasa_endeks order by gun desc limit 1;
  if e.gun is null or e.guncelleme < now() - interval '70 minutes' then perform oyun.piyasa_degerle(); select * into e from oyun.piyasa_endeks order by gun desc limit 1; end if;
  select max(gun) into dun from oyun.sirket_deger_gecmis where gun < e.gun;
  return jsonb_build_object(
    'endeks', jsonb_build_object('deger', e.deger, 'onceki', e.onceki,
       'degisim', case when coalesce(e.onceki, 0) > 0 then round((e.deger / e.onceki - 1) * 100, 2) end,
       'toplam', round(e.toplam), 'sirket', e.sirket_sayisi, 'guncelleme', e.guncelleme),
    'seri', coalesce((select jsonb_agg(jsonb_build_object('gun', gun, 'deger', deger) order by gun)
       from (select gun, deger from oyun.piyasa_endeks order by gun desc limit 30) z), '[]'::jsonb),
    'buyukler', coalesce((select jsonb_agg(x order by (x->>'deger')::numeric desc) from (
       select jsonb_build_object('id', s.id, 'ad', s.ad, 'sektor', s.sektor, 'sektor_ad', coalesce(k.ad, s.sektor),
         'il', (select i.ad from oyun.pazar_sirket ps join oyun.iller i on i.id = ps.il_id where ps.sirket_id = s.id),
         'deger', coalesce(d.piyasa, d.deger), 'kar7', round(d.kar7), 'halka_acik', s.halka_acik, 'tur', s.tur_hukuki,
         'sahip', oyun.kad(oyun.sirket_sahibi(s.id)),
         'degisim', case when coalesce(dd.deger, 0) > 0 then round((coalesce(d.piyasa, d.deger) / coalesce(dd.piyasa, dd.deger) - 1) * 100, 1) end) x
       from oyun.sirket_deger_gecmis d join oyun.sirketler s on s.id = d.sirket_id and s.aktif
       left join oyun.pazar_sektor k on k.kod = s.sektor
       left join oyun.sirket_deger_gecmis dd on dd.sirket_id = d.sirket_id and dd.gun = dun
       where d.gun = e.gun order by coalesce(d.piyasa, d.deger) desc limit 20) q), '[]'::jsonb),
    'yukselenler', coalesce((select jsonb_agg(x) from (
       select jsonb_build_object('id', s.id, 'ad', s.ad, 'degisim', round((coalesce(d.piyasa, d.deger) / coalesce(dd.piyasa, dd.deger) - 1) * 100, 1)) x
       from oyun.sirket_deger_gecmis d join oyun.sirket_deger_gecmis dd on dd.sirket_id = d.sirket_id and dd.gun = dun
       join oyun.sirketler s on s.id = d.sirket_id and s.aktif
       where d.gun = e.gun and coalesce(dd.piyasa, dd.deger) > 0
       order by coalesce(d.piyasa, d.deger) / coalesce(dd.piyasa, dd.deger) desc limit 5) q), '[]'::jsonb),
    'sektorler', coalesce((select jsonb_agg(x order by (x->>'kar7')::numeric desc) from (
       select jsonb_build_object('kod', s.sektor, 'ad', coalesce(k.ad, s.sektor), 'sirket', count(*),
         'kar7', round(sum(d.kar7)), 'deger', round(sum(coalesce(d.piyasa, d.deger)))) x
       from oyun.sirket_deger_gecmis d join oyun.sirketler s on s.id = d.sirket_id and s.aktif
       left join oyun.pazar_sektor k on k.kod = s.sektor where d.gun = e.gun group by s.sektor, k.ad) q), '[]'::jsonb),
    'zincir', jsonb_build_object(
       'elektrik', coalesce((select round(sum(tutar)) from oyun.eko_b2b where kalem = 'Elektrik faturası' and satici is not null and gun > g - 7), 0),
       'lojistik', coalesce((select round(sum(tutar)) from oyun.eko_b2b where kalem = 'Lojistik ve servis' and satici is not null and gun > g - 7), 0),
       'reklam', coalesce((select round(sum(tutar)) from oyun.eko_b2b where kalem = 'Reklam' and satici is not null and gun > g - 7), 0),
       'npc', coalesce((select round(sum(tutar)) from oyun.eko_b2b where satici is null and gun > g - 7), 0)),
    'benim', jsonb_build_object(
       'portfoy', coalesce((select round(sum(coalesce(d.piyasa, d.deger) * o.pay / 100)) from oyun.sirket_ortaklari o
          join oyun.sirket_deger_gecmis d on d.sirket_id = o.sirket_id and d.gun = e.gun where o.user_id = p.id), 0),
       'bugun', coalesce((select round(sum(gl.net * o.pay / 100)) from oyun.sirket_ortaklari o
          join oyun.eko_gunluk gl on gl.sirket_id = o.sirket_id and gl.gun = g where o.user_id = p.id), 0),
       'hafta', coalesce((select round(sum(gl.net * o.pay / 100)) from oyun.sirket_ortaklari o
          join oyun.eko_gunluk gl on gl.sirket_id = o.sirket_id and gl.gun > g - 7 where o.user_id = p.id), 0),
       'sirketler', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'ad', s.ad, 'pay', o.pay,
          'deger', coalesce(d.piyasa, d.deger), 'kar7', round(d.kar7)) order by coalesce(d.piyasa, d.deger) desc)
          from oyun.sirket_ortaklari o join oyun.sirketler s on s.id = o.sirket_id and s.aktif
          left join oyun.sirket_deger_gecmis d on d.sirket_id = s.id and d.gun = e.gun where o.user_id = p.id), '[]'::jsonb),
       'il', p.il_id, 'bolge', oyun.bolge_tesvik(p.il_id)),
    'bolgeler', (select jsonb_agg(jsonb_build_object('bolge', b, 'vergi_indirim', (array[0,10,20,30,45,60])[b],
       'sgk_destek', (array[0,0,5,10,15,20])[b],
       'ornek', (select string_agg(ad, ', ' order by ad) from (select i.ad from oyun.iller i where oyun.il_bolge(i.id) = b order by i.mv desc limit 3) z))
       order by b) from generate_series(1, 6) b),
    'kurumlar', oyun.eko_vergi_oran('kurumlar'),
    'politika_faizi', oyun.politika_faizi());
end $function$;

create or replace function public.sirket_karnesi(p_sirket bigint)
 returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare p oyun.profiller := oyun.profilim(); s oyun.sirketler; ps oyun.pazar_sirket; g date := (now() at time zone 'Europe/Istanbul')::date;
  benim numeric; yon boolean;
begin
  select * into s from oyun.sirketler where id = p_sirket;
  if s.id is null then raise exception 'Şirket bulunamadı.'; end if;
  select * into ps from oyun.pazar_sirket where sirket_id = s.id;
  select pay into benim from oyun.sirket_ortaklari where sirket_id = s.id and user_id = p.id;
  yon := oyun.sirket_yonetici_mi(s.id, p.id);
  if s.aktif and benim is not null then perform oyun.sirket_hesapla(s.id); select * into s from oyun.sirketler where id = p_sirket; end if;
  return jsonb_build_object(
    'id', s.id, 'ad', s.ad, 'sektor', s.sektor, 'sektor_ad', coalesce((select ad from oyun.pazar_sektor where kod = s.sektor), s.sektor),
    'aktif', s.aktif, 'tur', s.tur_hukuki, 'halka_acik', s.halka_acik, 'kurulus', s.kurulus,
    'sermaye', s.sermaye, 'kasa', round(s.kasa), 'defter', round(oyun.sirket_defter(s.id)), 'kar7', round(oyun.sirket_kar7(s.id)),
    'deger', oyun.sirket_deger(s.id), 'piyasa', case when s.halka_acik then oyun.borsa_son_fiyat(s.id) * 100 end,
    'yonetici', oyun.kad(s.yonetici), 'sahip', oyun.kad(oyun.sirket_sahibi(s.id)),
    'benim_pay', coalesce(benim, 0), 'yonetici_mi', yon,
    'il', (select ad from oyun.iller where id = ps.il_id), 'il_id', ps.il_id,
    'bolge', case when ps.il_id is not null then oyun.bolge_tesvik(ps.il_id) end,
    'fiyat', ps.fiyat, 'kalite', ps.kalite, 'reklam', ps.reklam, 'marka', round(ps.marka), 'otopilot', ps.otopilot,
    'tahmin', case when s.aktif and ps.sirket_id is not null then oyun.pazar_tahmin(s.id) end,
    'gunler', coalesce((select jsonb_agg(jsonb_build_object('gun', gun, 'gelir', round(gelir + b2b_gelir), 'gider', round(gider + ruhsat + ceza),
        'vergi', round(vergi), 'tesvik', round(tesvik), 'net', round(net), 'b2b_gelir', round(b2b_gelir), 'pay', pay, 'rakip', rakip) order by gun)
       from (select * from oyun.eko_gunluk where sirket_id = s.id order by gun desc limit 14) z), '[]'::jsonb),
    'deger_seri', coalesce((select jsonb_agg(jsonb_build_object('gun', gun, 'deger', coalesce(piyasa, deger)) order by gun)
       from (select * from oyun.sirket_deger_gecmis where sirket_id = s.id order by gun desc limit 30) z), '[]'::jsonb),
    'musteriler', coalesce((select jsonb_agg(jsonb_build_object('ad', s2.ad, 'kalem', b.kalem, 'tutar', b.t) order by b.t desc)
       from (select alici, kalem, round(sum(tutar)) t from oyun.eko_b2b where satici = s.id and gun > g - 7 group by 1, 2 order by 3 desc limit 8) b
       join oyun.sirketler s2 on s2.id = b.alici), '[]'::jsonb),
    'tedarikciler', coalesce((select jsonb_agg(jsonb_build_object('ad', coalesce(s2.ad, 'Yurt içi tedarikçiler'), 'kalem', b.kalem, 'tutar', b.t) order by b.t desc)
       from (select satici, kalem, round(sum(tutar)) t from oyun.eko_b2b where alici = s.id and gun > g - 7 group by 1, 2 order by 3 desc limit 8) b
       left join oyun.sirketler s2 on s2.id = b.satici), '[]'::jsonb),
    'ortaklar', coalesce((select jsonb_agg(jsonb_build_object('kad', oyun.kad(o.user_id), 'pay', o.pay) order by o.pay desc)
       from oyun.sirket_ortaklari o where o.sirket_id = s.id), '[]'::jsonb),
    'kurullar', coalesce((select jsonb_agg(jsonb_build_object('id', k.id, 'tur', k.tur, 'baslik', k.baslik, 'durum', k.durum,
        'acan', oyun.kad(k.acan), 'bit', k.bit, 'evet', k.evet, 'hayir', k.hayir, 'katilim', k.katilim, 'sonuc', k.sonuc,
        'benim_oy', (select oy from oyun.genel_kurul_oy v where v.kurul_id = k.id and v.user_id = p.id)) order by k.id desc)
       from (select * from oyun.genel_kurul where sirket_id = s.id order by (durum = 'acik') desc, id desc limit 8) k), '[]'::jsonb),
    'as_esik', 250000, 'as_harc', greatest(2500, round(s.sermaye * 0.005)));
end $function$;

-- 7) Ekonomi başarımları
create or replace function oyun.basarim_durum(u uuid)
 returns table(kod text, ad text, aciklama text, sinif text, sira integer, kazandi boolean)
 language plpgsql stable
as $function$
declare t timestamptz := oyun.simdi(); hesap timestamptz; n_akis int; n_begeni int; mv_gun numeric; portfoy numeric; sg date;
begin
  select pr.olusturma into hesap from oyun.profiller pr where pr.id = u;
  select count(*) into n_akis from oyun.akis where user_id = u;
  select count(*) into n_begeni from oyun.akis_begeni b join oyun.akis a on a.id = b.akis_id where a.user_id = u and b.user_id <> u;
  select coalesce(sum(extract(epoch from coalesce(m.bit, t) - m.bas) / 86400), 0) into mv_gun from oyun.makamlar m where m.user_id = u and m.tur = 'mv';
  select max(d.gun) into sg from oyun.sirket_deger_gecmis d;
  select coalesce(sum(coalesce(d.piyasa, d.deger) * o.pay / 100), 0) into portfoy
    from oyun.sirket_ortaklari o join oyun.sirket_deger_gecmis d on d.sirket_id = o.sirket_id and d.gun = sg where o.user_id = u;
  return query select * from (values
    ('yerlesik',   'Yerleşik Vatandaş',  'Hesabın 7 günü geçti.',                                'bronz', 1, hesap is not null and hesap <= t - interval '7 days'),
    ('koklu',      'Köklü Vatandaş',     'Hesabın 30 günü geçti.',                               'gumus', 2, hesap is not null and hesap <= t - interval '30 days'),
    ('ilk_soz',    'İlk Söz',            'İlk kısa paylaşımını yaptın.',                         'bronz', 3, n_akis >= 1),
    ('gundem',     'Gündem Belirleyici', '25 paylaşıma ulaştın.',                                'gumus', 4, n_akis >= 25),
    ('sesini',     'Sesini Duyuran',     'Paylaşımların 50 beğeni topladı.',                     'gumus', 5, n_begeni >= 50),
    ('kurucu',     'Parti Kurucusu',     'Bir parti kurdun.',                                    'gumus', 6, exists (select 1 from oyun.partiler pa where pa.kurucu = u)),
    ('genel_baskan','Genel Başkan',      'Bir partinin genel başkanısın.',                       'gumus', 7, exists (select 1 from oyun.partiler pa where pa.gb = u and not pa.kapali)),
    ('vekil',      'Meclis Kürsüsü',     'Milletvekili seçildin.',                               'gumus', 8, exists (select 1 from oyun.makamlar m where m.user_id = u and m.tur = 'mv')),
    ('belediye',   'Şehrin Başkanı',     'Belediye başkanı seçildin.',                           'gumus', 9, exists (select 1 from oyun.makamlar m where m.user_id = u and m.tur = 'bel')),
    ('bakan',      'Kabine Üyesi',       'Bakan oldun.',                                         'altin', 10, exists (select 1 from oyun.makamlar m where m.user_id = u and m.tur = 'bakan')),
    ('kidemli',    'Kıdemli Vekil',      'Meclis''te toplam 30 gün görev yaptın.',               'altin', 11, mv_gun >= 30),
    ('cumhurbaskani','Çankaya',          'Cumhurbaşkanı seçildin.',                              'altin', 12, exists (select 1 from oyun.makamlar m where m.user_id = u and m.tur = 'cb')),
    ('girisimci',  'Girişimci',          'İlk şirketini kurdun.',                                'bronz', 13, exists (select 1 from oyun.sirketler s where s.kurucu = u)),
    ('ilk_kar',    'İlk Kâr',            'Ortağı olduğun bir şirket günü kârla kapattı.',        'bronz', 14, exists (select 1 from oyun.eko_gunluk g join oyun.sirket_ortaklari o on o.sirket_id = g.sirket_id where o.user_id = u and g.net > 0)),
    ('patron',     'Patron',             'Şirket paylarının değeri 1 milyon ₺''yi aştı.',        'gumus', 15, portfoy >= 1000000),
    ('gong',       'Gong Çaldı',         'Kurduğun bir şirket halka arz edildi.',               'gumus', 16, exists (select 1 from oyun.sirketler s where s.kurucu = u and s.halka_acik)),
    ('holding',    'Holding',            'Üç farklı sektörde çoğunluk sahibi olduğun şirket var.','altin', 17, (select count(distinct s.sektor) from oyun.sirket_ortaklari o join oyun.sirketler s on s.id = o.sirket_id and s.aktif where o.user_id = u and o.pay >= 50) >= 3),
    ('sektor_devi','Sektör Devi',        'Şirketin Türkiye''nin en değerli 10 şirketi arasında.', 'altin', 18, exists (select 1 from (select d.sirket_id from oyun.sirket_deger_gecmis d join oyun.sirketler s on s.id = d.sirket_id and s.aktif where d.gun = sg order by coalesce(d.piyasa, d.deger) desc limit 10) z join oyun.sirket_ortaklari o on o.sirket_id = z.sirket_id where o.user_id = u and o.pay >= 50))
  ) v(kod, ad, aciklama, sinif, sira, kazandi);
end $function$;

-- 8) Ekonomi zamanlayıcısı: genel kurullar, saatlik değerleme, 18:00 borsa kapanışı, 20:00 gün sonu bilançosu
create or replace function oyun.ekonomi3_tick()
 returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare k record; yerel timestamp := now() at time zone 'Europe/Istanbul'; g date := (now() at time zone 'Europe/Istanbul')::date;
  e oyun.piyasa_endeks; x record; metin text; n_kurul int := 0; kapanis boolean := false; bilanco int := 0; son timestamptz;
begin
  if not pg_try_advisory_xact_lock(424299) then return jsonb_build_object('kilitli', true); end if;
  for k in select id from oyun.genel_kurul where durum = 'acik' and bit <= now() order by id limit 50 loop
    perform oyun.genel_kurul_kapat(k.id, true); n_kurul := n_kurul + 1;
  end loop;

  select guncelleme into son from oyun.piyasa_endeks where gun = g;
  if son is null or son < now() - interval '55 minutes' then perform oyun.piyasa_degerle(); end if;

  -- 18:00 borsa kapanışı (günde bir kez)
  if extract(hour from yerel) >= 18 and not exists (select 1 from oyun.ekonomi3_kayit where kod = 'kapanis_' || g) then
    perform oyun.piyasa_degerle();
    update oyun.piyasa_endeks set kapanis = true where gun = g;
    select * into e from oyun.piyasa_endeks where gun = g;
    select string_agg(format('%s (%s%s%%)', z.ad, case when z.d >= 0 then '+' else '' end, replace(to_char(z.d, 'FM990.0'), '.', ',')), ', ') into metin
    from (select s.ad, round((coalesce(a.piyasa, a.deger) / nullif(coalesce(b.piyasa, b.deger), 0) - 1) * 100, 1) d
          from oyun.sirket_deger_gecmis a join oyun.sirket_deger_gecmis b on b.sirket_id = a.sirket_id
            and b.gun = (select max(gun) from oyun.sirket_deger_gecmis where gun < g)
          join oyun.sirketler s on s.id = a.sirket_id and s.aktif
          where a.gun = g and coalesce(b.piyasa, b.deger) > 0 order by 2 desc limit 3) z;
    perform oyun.olay('ekonomi', format('Piyasa kapanışı: Şirketler Endeksi %s puan%s. Günün yükselenleri: %s. Piyasadaki toplam şirket değeri %s ₺.',
      replace(to_char(e.deger, 'FM9999990.00'), '.', ','),
      case when coalesce(e.onceki, 0) > 0 then format(' (%s%s%%)', case when e.deger >= e.onceki then '+' else '' end,
        replace(to_char(round((e.deger / e.onceki - 1) * 100, 2), 'FM990.00'), '.', ',')) else '' end,
      coalesce(metin, 'veri yok'), oyun.tl(e.toplam)), null, null, now());
    -- pazar günleri haftanın en değerli şirketleri listesi
    if extract(isodow from yerel) = 7 then
      select string_agg(format('%s. %s (%s ₺)', z.r, z.ad, oyun.tl(z.v)), ' · ') into metin
      from (select row_number() over (order by coalesce(d.piyasa, d.deger) desc) r, s.ad, coalesce(d.piyasa, d.deger) v
            from oyun.sirket_deger_gecmis d join oyun.sirketler s on s.id = d.sirket_id and s.aktif where d.gun = g
            order by 3 desc limit 10) z;
      perform oyun.olay('ekonomi', 'Haftanın listesi — Türkiye''nin en değerli 10 şirketi: ' || coalesce(metin, '—'), null, null, now());
    end if;
    insert into oyun.ekonomi3_kayit(kod, deger) values ('kapanis_' || g, e.deger) on conflict (kod) do nothing;
    kapanis := true;
  end if;

  -- 20:00 gün sonu bilançosu: ortaklara günün kârından kendi payı
  if extract(hour from yerel) >= 20 and not exists (select 1 from oyun.ekonomi3_kayit where kod = 'bilanco_' || g) then
    insert into oyun.ekonomi3_kayit(kod, deger) values ('bilanco_' || g, 1) on conflict (kod) do nothing;
    for x in select o.user_id, round(sum(gl.net * o.pay / 100)) pay_net,
               string_agg(format('%s %s%s ₺', s.ad, case when gl.net >= 0 then '+' else '' end, oyun.tl(gl.net)), ', ' order by gl.net desc) liste
             from oyun.sirket_ortaklari o join oyun.eko_gunluk gl on gl.sirket_id = o.sirket_id and gl.gun = g
             join oyun.sirketler s on s.id = o.sirket_id
             group by o.user_id loop
      perform oyun.bildir(x.user_id, format('Günün bilançosu: %s. Senin payına düşen net: %s ₺.', left(x.liste, 300), oyun.tl(x.pay_net)), now());
      bilanco := bilanco + 1;
    end loop;
  end if;
  return jsonb_build_object('kurul', n_kurul, 'kapanis', kapanis, 'bilanco', bilanco);
end $function$;

do $$ begin
  if exists (select 1 from pg_namespace where nspname = 'cron') then
    if not exists (select 1 from cron.job where jobname = 'ekonomi-3') then
      perform cron.schedule('ekonomi-3', '2-59/10 * * * *', 'select oyun.ekonomi3_tick()');
    end if;
  end if;
end $$;

