CREATE OR REPLACE FUNCTION public.kamu_butce_panel()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid();
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giris gerekli'; END IF;
 RETURN jsonb_build_object(
  'hazine',(SELECT hazine FROM oyun.ulke WHERE id=1),
  'ekonomi',(SELECT jsonb_build_object('buyume',buyume,'enflasyon',enflasyon,'issizlik',issizlik,'memnuniyet',memnuniyet) FROM oyun.ulke WHERE id=1),
  'bakanliklar',COALESCE((SELECT jsonb_agg(jsonb_build_object('kod',kod,'kasa',kasa) ORDER BY kod) FROM oyun.bakanlik_kasa),'[]'::jsonb),
  'yetkili',EXISTS(SELECT 1 FROM oyun.makamlar WHERE tur='cb' AND user_id=u AND bit IS NULL),
  'son_karar',(SELECT tarih FROM oyun.kamu_butce_kararlar ORDER BY id DESC LIMIT 1),
  'kararlar',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',x.id,'toplam',x.toplam_milyar,'paylar',x.paylar,'tarih',x.tarih) ORDER BY x.id DESC)
   FROM (SELECT * FROM oyun.kamu_butce_kararlar ORDER BY id DESC LIMIT 20)x),'[]'::jsonb)
 );
END $function$;

CREATE OR REPLACE FUNCTION public.kamu_butce_dagit(p_toplam numeric, p_paylar jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); total numeric:=0; c record; t timestamptz:=oyun.simdi();
BEGIN
 IF NOT EXISTS(SELECT 1 FROM oyun.makamlar WHERE user_id=u AND tur='cb' AND bit IS NULL) THEN
  RAISE EXCEPTION 'Yalnizca gorevdeki cumhurbaskani butce dagitabilir';
 END IF;
 IF p_toplam IS NULL OR p_toplam<0.001 OR p_toplam>5 OR p_toplam<>round(p_toplam,3)
  OR p_paylar IS NULL OR jsonb_typeof(p_paylar)<>'object' OR
  (SELECT COUNT(*) FROM jsonb_object_keys(p_paylar))<>5 THEN
  RAISE EXCEPTION 'Dagitilacak tutar 0.001-5 milyar TL ve tam 5 butce kalemi olmali';
 END IF;
 FOR c IN SELECT key,value FROM jsonb_each_text(p_paylar) LOOP
  IF c.key NOT IN ('egitim','saglik','savunma','icisleri','ulastirma') OR
    c.value !~ '^[0-9]+([.][0-9]+)?$' OR (c.value)::numeric>100
  THEN RAISE EXCEPTION 'Gecersiz butce payi: %',c.key;END IF;
  total:=total+(c.value)::numeric;
 END LOOP;
 IF total<>100 THEN RAISE EXCEPTION 'Butce paylari toplamda %%100 olmali'; END IF;
 PERFORM pg_advisory_xact_lock(920044,1);
 IF EXISTS(SELECT 1 FROM oyun.kamu_butce_kararlar WHERE tarih>t-interval '24 hours') THEN
  RAISE EXCEPTION 'Ulusal butce en erken 24 saat sonra yeniden dagitilabilir';
 END IF;
 UPDATE oyun.ulke SET hazine=hazine-p_toplam WHERE id=1 AND hazine>=p_toplam;
 IF NOT FOUND THEN RAISE EXCEPTION 'Hazinede yeterli kaynak yok'; END IF;
 FOR c IN SELECT key,value FROM jsonb_each_text(p_paylar) LOOP
  UPDATE oyun.bakanlik_kasa SET kasa=kasa+round(p_toplam*(c.value)::numeric/100,6) WHERE kod=c.key;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bakanlik kasasi eksik: %',c.key;END IF;
 END LOOP;
 INSERT INTO oyun.kamu_butce_kararlar(karar_veren,toplam_milyar,paylar,tarih)
 VALUES(u,p_toplam,p_paylar,t);
 RETURN public.kamu_butce_panel();
END $function$;

CREATE OR REPLACE FUNCTION public.kamu_toptan_panel()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid();
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giris gerekli'; END IF;
 RETURN jsonb_build_object(
  'sirketler',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',s.id,'ad',s.ad,'tur',e.tur,'kasa',s.kasa))
   FROM oyun.sirketler s JOIN oyun.eko_isletmeler e ON e.sirket_id=s.id
   WHERE s.aktif AND oyun.sirket_yonetici_mi(s.id,u)),'[]'::jsonb),
  'stoklar',COALESCE((SELECT jsonb_agg(jsonb_build_object('sirket',s.id,'ad',s.ad,'urun',st.urun,'adet',st.adet,'fiyat',st.satis_fiyati))
   FROM oyun.eko_urun_stok st JOIN oyun.sirketler s ON s.id=st.sirket_id
   JOIN oyun.eko_isletmeler e ON e.sirket_id=s.id AND e.tur='fabrika'
   WHERE s.aktif AND st.adet>0 AND st.satis_fiyati>0),'[]'::jsonb),
  'teklifler',COALESCE((SELECT jsonb_agg(jsonb_build_object(
   'id',x.id,'alici',x.alici,'satici',x.satici,'alici_ad',a.ad,'satici_ad',s.ad,'urun',x.urun,
   'adet',x.adet,'birim',x.birim_fiyat,'toplam',x.birim_fiyat*x.adet,'durum',x.durum,
   'teklif_eden',x.teklif_eden,'son_tarih',x.son_tarih,'olusturma',x.olusturma,
   'alici_yetkili',oyun.sirket_yonetici_mi(x.alici,u),
   'satici_yetkili',oyun.sirket_yonetici_mi(x.satici,u)) ORDER BY x.id DESC)
   FROM (SELECT * FROM oyun.kamu_toptan_teklif
      WHERE EXISTS(SELECT 1 FROM oyun.sirket_ortaklari o WHERE o.user_id=u AND o.sirket_id IN (alici,satici))
      ORDER BY id DESC LIMIT 80)x
   JOIN oyun.sirketler a ON a.id=x.alici JOIN oyun.sirketler s ON s.id=x.satici),'[]'::jsonb)
 );
END $function$;

CREATE OR REPLACE FUNCTION public.kamu_toptan_islem(p_eylem text, p_id bigint DEFAULT NULL::bigint, p_alici bigint DEFAULT NULL::bigint, p_satici bigint DEFAULT NULL::bigint, p_urun text DEFAULT NULL::text, p_adet integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); d oyun.kamu_toptan_teklif; st oyun.eko_urun_stok; i bigint; res jsonb;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giris gerekli';END IF;
 IF p_eylem='teklif' THEN
  IF p_alici IS NULL OR p_satici IS NULL OR p_alici=p_satici OR p_adet NOT BETWEEN 1 AND 500
     OR NOT oyun.sirket_yonetici_mi(p_alici,u)
     OR NOT EXISTS(SELECT 1 FROM oyun.eko_isletmeler WHERE sirket_id=p_alici AND tur='magaza')
  THEN RAISE EXCEPTION 'Yalnizca yonettigin magazadan gecerli bir siparis verebilirsin';END IF;
  SELECT * INTO st FROM oyun.eko_urun_stok WHERE sirket_id=p_satici AND urun=p_urun;
  IF st.sirket_id IS NULL OR st.adet<p_adet OR st.satis_fiyati<=0
    OR NOT EXISTS(SELECT 1 FROM oyun.eko_isletmeler WHERE sirket_id=p_satici AND tur='fabrika')
    OR NOT EXISTS(SELECT 1 FROM oyun.sirketler WHERE id=p_satici AND aktif)
  THEN RAISE EXCEPTION 'Fabrikada yeterli satilik stok bulunmuyor';END IF;
  IF NOT EXISTS(SELECT 1 FROM oyun.sirketler WHERE id=p_alici AND aktif AND kasa>=st.satis_fiyati*p_adet) THEN
   RAISE EXCEPTION 'Magaza kasasi teklif tutarini karsilamiyor'; END IF;
  INSERT INTO oyun.kamu_toptan_teklif(alici,satici,urun,adet,birim_fiyat,teklif_eden)
  VALUES(p_alici,p_satici,p_urun,p_adet,st.satis_fiyati,u) RETURNING id INTO i;
  RETURN jsonb_build_object('id',i,'durum','teklif','birim_fiyat',st.satis_fiyati);
 END IF;
 SELECT * INTO d FROM oyun.kamu_toptan_teklif WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR d.durum<>'teklif' THEN RAISE EXCEPTION 'Acik teklif bulunamadi';END IF;
 IF d.son_tarih<oyun.simdi() THEN
   UPDATE oyun.kamu_toptan_teklif SET durum='suresi_doldu',bitis=now() WHERE id=d.id;
   RETURN jsonb_build_object('durum','suresi_doldu');
 END IF;
 IF p_eylem='iptal' AND oyun.sirket_yonetici_mi(d.alici,u) THEN
  UPDATE oyun.kamu_toptan_teklif SET durum='iptal',bitis=now() WHERE id=d.id;
 ELSIF p_eylem='ret' AND oyun.sirket_yonetici_mi(d.satici,u) THEN
  UPDATE oyun.kamu_toptan_teklif SET durum='ret',bitis=now() WHERE id=d.id;
 ELSIF p_eylem='kabul' AND oyun.sirket_yonetici_mi(d.satici,u) THEN
  SELECT * INTO st FROM oyun.eko_urun_stok WHERE sirket_id=d.satici AND urun=d.urun FOR UPDATE;
  IF st.sirket_id IS NULL OR st.adet<d.adet OR st.satis_fiyati<>d.birim_fiyat THEN
   RAISE EXCEPTION 'Stok veya birim fiyat degisti; yeni teklif isteyin';END IF;
  res:=oyun.eko_urun_toptan(d.alici,d.satici,d.urun,d.adet,u);
  UPDATE oyun.kamu_toptan_teklif SET durum='tamam',bitis=now() WHERE id=d.id;
  RETURN jsonb_build_object('durum','tamam','sonuc',res);
 ELSE RAISE EXCEPTION 'Bu teklif icin yetkili degilsin';END IF;
 RETURN jsonb_build_object('durum',p_eylem,'id',d.id);
END $function$;

CREATE OR REPLACE FUNCTION public.kamu_kurum_panel()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid();
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giris gerekli';END IF;
 RETURN jsonb_build_object(
  'cb',EXISTS(SELECT 1 FROM oyun.makamlar WHERE tur='cb' AND user_id=u AND bit IS NULL),
  'belediye_iller',COALESCE((SELECT jsonb_agg(il_id) FROM oyun.makamlar WHERE tur='bel' AND user_id=u AND bit IS NULL),'[]'::jsonb),
  'atamalar',COALESCE((SELECT jsonb_agg(jsonb_build_object(
   'id',a.id,'gorev',a.gorev,'il_id',a.il_id,'aday',p.kad,'benim_teklifim',a.aday=u,'ben_atadim',a.atayan=u,
   'durum',a.durum,'tarih',a.teklif_at) ORDER BY a.id DESC)
   FROM (SELECT * FROM oyun.kamu_kurum_atama
    WHERE durum='aktif' OR aday=u OR atayan=u ORDER BY id DESC LIMIT 150)a
    JOIN oyun.profiller p ON p.id=a.aday),'[]'::jsonb)
 );
END $function$;

CREATE OR REPLACE FUNCTION public.kamu_kurum_islem(p_eylem text, p_id bigint DEFAULT NULL::bigint, p_gorev text DEFAULT NULL::text, p_il smallint DEFAULT NULL::smallint, p_kad text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); a oyun.kamu_kurum_atama; v_aday uuid; i bigint; authorized boolean;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giris gerekli';END IF;
 IF p_eylem='teklif' THEN
  IF p_gorev NOT IN ('vali','emniyet_muduru','spk_baskani','rekabet_baskani','vergi_idaresi_baskani','belediye_genel_sekreteri')
   OR (p_gorev IN ('vali','emniyet_muduru','belediye_genel_sekreteri') AND (p_il IS NULL OR NOT EXISTS(SELECT 1 FROM oyun.iller WHERE id=p_il)))
   OR (p_gorev NOT IN ('vali','emniyet_muduru','belediye_genel_sekreteri') AND p_il IS NOT NULL)
  THEN RAISE EXCEPTION 'Gorev veya il uygun degil';END IF;
  authorized:=CASE WHEN p_gorev='belediye_genel_sekreteri' THEN
   EXISTS(SELECT 1 FROM oyun.makamlar WHERE tur='bel' AND il_id=p_il AND user_id=u AND bit IS NULL)
   ELSE EXISTS(SELECT 1 FROM oyun.makamlar WHERE tur='cb' AND user_id=u AND bit IS NULL) END;
  IF NOT authorized THEN RAISE EXCEPTION 'Bu kuruma atama teklifi yapma yetkin yok';END IF;
  SELECT id INTO v_aday FROM oyun.profiller WHERE lower(kad)=lower(trim(p_kad)) AND NOT yasakli LIMIT 1;
  IF v_aday IS NULL THEN RAISE EXCEPTION 'Oyuncu adi bulunamadi';END IF;
  IF v_aday=u THEN RAISE EXCEPTION 'Kendine gorev teklif edemezsin';END IF;
  INSERT INTO oyun.kamu_kurum_atama(gorev,il_id,aday,atayan) VALUES(p_gorev,p_il,v_aday,u) RETURNING id INTO i;
  RETURN jsonb_build_object('id',i,'durum','teklif');
 END IF;
 SELECT * INTO a FROM oyun.kamu_kurum_atama WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Atama kaydi bulunamadi';END IF;
 authorized:=CASE WHEN a.gorev='belediye_genel_sekreteri' THEN
   EXISTS(SELECT 1 FROM oyun.makamlar WHERE tur='bel' AND il_id=a.il_id AND user_id=u AND bit IS NULL)
   ELSE EXISTS(SELECT 1 FROM oyun.makamlar WHERE tur='cb' AND user_id=u AND bit IS NULL) END;
 IF p_eylem='cevap_kabul' AND a.aday=u AND a.durum='teklif' THEN
  IF a.teklif_at+interval '24 hours'<now() THEN RAISE EXCEPTION 'Teklif suresi dolmus';END IF;
  IF EXISTS(SELECT 1 FROM oyun.makamlar WHERE user_id=u AND bit IS NULL AND tur IN ('cb','bakan','mv','bel','cb_yardimcisi'))
  THEN RAISE EXCEPTION 'Secilmis veya siyasi gorev ile bu atanmis gorev birlestirilemez';END IF;
  -- Eski yönetici kayıtları silinmez, sadece görev sonlandırılır.
  UPDATE oyun.kamu_kurum_atama SET durum='gorevden_alindi',yanit_at=now()
   WHERE gorev=a.gorev AND il_id IS NOT DISTINCT FROM a.il_id AND durum='aktif';
  UPDATE oyun.kamu_kurum_atama SET durum='aktif',yanit_at=now() WHERE id=a.id;
 ELSIF p_eylem='cevap_ret' AND a.aday=u AND a.durum='teklif' THEN
  UPDATE oyun.kamu_kurum_atama SET durum='ret',yanit_at=now() WHERE id=a.id;
 ELSIF p_eylem='iptal' AND authorized AND a.durum='teklif' THEN
  UPDATE oyun.kamu_kurum_atama SET durum='geri_cekildi',yanit_at=now() WHERE id=a.id;
 ELSIF p_eylem='gorevden_al' AND authorized AND a.durum='aktif' THEN
  UPDATE oyun.kamu_kurum_atama SET durum='gorevden_alindi',yanit_at=now() WHERE id=a.id;
 ELSE RAISE EXCEPTION 'Bu atama islemine yetkin yok';END IF;
 RETURN jsonb_build_object('id',a.id,'durum',p_eylem);
END $function$;

CREATE OR REPLACE FUNCTION oyun.icra_kalan_hesapla(p_id bigint)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE d oyun.icra_takip; v numeric;
BEGIN
 SELECT * INTO d FROM oyun.icra_takip WHERE id=p_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Dosya yok'; END IF;
 IF d.kaynak='kredi' THEN
  SELECT greatest(0,kalan) INTO v FROM oyun.oyb_kredi WHERE id=d.kaynak_id;
 ELSE
  SELECT greatest(0,vergi_borc) INTO v FROM oyun.yatirim_mulkleri WHERE id=d.kaynak_id;
 END IF;
 RETURN coalesce(v,0);
END $function$;

CREATE OR REPLACE FUNCTION oyun.icra_tahsil_et(p_id bigint, p_tutar numeric, p_tur text)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE d oyun.icra_takip; k oyun.oyb_kredi; em oyun.yatirim_mulkleri;
 v numeric:=0;
BEGIN
 SELECT * INTO d FROM oyun.icra_takip WHERE id=p_id FOR UPDATE;
 IF d.id IS NULL OR d.durum NOT IN ('teblig','haciz') THEN RAISE EXCEPTION 'Aktif takip yok'; END IF;
 IF p_tutar<=0 THEN RETURN 0;END IF;
 IF d.kaynak='kredi' THEN
  SELECT * INTO k FROM oyun.oyb_kredi WHERE id=d.kaynak_id FOR UPDATE;
  IF k.id IS NULL THEN RAISE EXCEPTION 'Kredi bulunamadi';END IF;
  v:=least(p_tutar,greatest(0,k.kalan));
  IF v>0 THEN
   UPDATE oyun.oyb_kredi SET kalan=kalan-v,
    anapara_odendi=anapara_odendi+least(v,greatest(0,anapara-anapara_odendi)),
    durum=CASE WHEN kalan<=v THEN 'odendi' ELSE durum END,
    kapanis=CASE WHEN kalan<=v THEN oyun.simdi() ELSE kapanis END WHERE id=k.id;
   UPDATE oyun.sirketler SET kasa=kasa+v WHERE id=d.alacakli_sirket;
   IF k.kalan<=v THEN
    UPDATE oyun.oyb_icra SET durum='kapandi' WHERE kredi_id=k.id AND durum='kabul';
    UPDATE oyun.oyb_icra_haciz SET durum='iptal' WHERE icra_id IN
      (SELECT id FROM oyun.oyb_icra WHERE kredi_id=k.id) AND durum='acik';
   END IF;
  END IF;
 ELSE
  SELECT * INTO em FROM oyun.yatirim_mulkleri WHERE id=d.kaynak_id FOR UPDATE;
  IF em.id IS NULL THEN RAISE EXCEPTION 'Vergi borcu bulunamadi';END IF;
  v:=least(p_tutar,greatest(0,em.vergi_borc));
  IF v>0 THEN
   UPDATE oyun.yatirim_mulkleri SET vergi_borc=greatest(0,vergi_borc-v) WHERE id=em.id;
   UPDATE oyun.ulke SET hazine=hazine+v/1000000000 WHERE id=1;
  END IF;
 END IF;
 IF v>0 THEN
  INSERT INTO oyun.icra_haciz_hareket(takip_id,tur,tutar,notlar)
  VALUES(p_id,p_tur,v,'Kesinleşmiş alacağa mahsup');
 END IF;
 IF oyun.icra_kalan_hesapla(p_id)<=0 THEN
  UPDATE oyun.icra_takip SET durum='kapandi' WHERE id=p_id;
  -- Açık artırmadaki yatırılmış en yüksek teklifler ilgili sonlandırıcı RPC ile iadeye çıkar.
 END IF;
 RETURN v;
END $function$;

CREATE OR REPLACE FUNCTION public.icra_takip_ac(p_kaynak text, p_kaynak_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); b uuid; s bigint; miktar numeric; cid bigint; d oyun.oyb_icra;
 t timestamptz:=oyun.simdi(); son timestamptz;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giriş yap';END IF;
 IF p_kaynak='kredi' THEN
  SELECT * INTO d FROM oyun.oyb_icra WHERE kredi_id=p_kaynak_id AND durum='kabul'
    AND kesin_son<=t ORDER BY id DESC LIMIT 1;
  IF d.id IS NULL THEN RAISE EXCEPTION 'Kesinleşmiş yargı kararı yok';END IF;
  IF NOT EXISTS(SELECT 1 FROM oyun.sirket_ortaklari WHERE sirket_id=d.banka_id AND user_id=u AND pay>=50)
  THEN RAISE EXCEPTION 'Alacaklı bankayı temsil etmiyorsun';END IF;
  SELECT borclu,kalan,banka_id INTO b,miktar,s FROM oyun.oyb_kredi WHERE id=p_kaynak_id;
  son:=t+interval '7 days';
 ELSIF p_kaynak='emlak_vergisi' THEN
  IF NOT EXISTS(SELECT 1 FROM oyun.makamlar WHERE user_id=u AND bit IS NULL
      AND (tur='cb' OR (tur='bakan' AND bakanlik='maliye')))
  THEN RAISE EXCEPTION 'Vergi tahsil yetkin yok'; END IF;
  SELECT user_id,vergi_borc INTO b,miktar FROM oyun.yatirim_mulkleri WHERE id=p_kaynak_id;
  son:=t+interval '15 days';
 ELSE RAISE EXCEPTION 'Takip kaynağı geçersiz';END IF;
 IF b IS NULL OR coalesce(miktar,0)<=0 THEN RAISE EXCEPTION 'Tahsil edilecek muaccel borç yok';END IF;
 INSERT INTO oyun.icra_takip(kaynak,kaynak_id,borclu,alacakli_sirket,baslangic_borc,teblig,odeme_son)
 VALUES(p_kaynak,p_kaynak_id,b,s,miktar,t,son)
 ON CONFLICT(kaynak,kaynak_id) DO UPDATE SET teblig=oyun.icra_takip.teblig
 RETURNING id INTO cid;
 PERFORM oyun.bildir(b,'İcra ödeme emri # '||cid||' ('||miktar||' TL). Son tarih: '||
     to_char(son AT TIME ZONE 'Europe/Istanbul','DD.MM.YYYY HH24:MI')||'. İtiraz ve mal bildirimi haklarını incele.',t);
 RETURN jsonb_build_object('id',cid,'odeme_son',son);
END $function$;

CREATE OR REPLACE FUNCTION public.icra_itiraz_et(p_id bigint, p_gerekce text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d oyun.icra_takip;
BEGIN
 IF char_length(trim(coalesce(p_gerekce,''))) NOT BETWEEN 10 AND 1500 THEN RAISE EXCEPTION 'İtiraz gerekçesi 10-1500 karakter olmalı';END IF;
 SELECT * INTO d FROM oyun.icra_takip WHERE id=p_id AND borclu=auth.uid() FOR UPDATE;
 IF d.id IS NULL OR d.durum<>'teblig' OR d.odeme_son<oyun.simdi() THEN RAISE EXCEPTION 'İtiraz süresi doldu';END IF;
 UPDATE oyun.icra_takip SET durum='itiraz',itiraz=trim(p_gerekce),itiraz_tarih=oyun.simdi() WHERE id=d.id;
 RETURN jsonb_build_object('id',d.id,'durum','itiraz');
END $function$;

CREATE OR REPLACE FUNCTION public.icra_itiraz_karar(p_id bigint, p_ret boolean, p_gerekce text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d oyun.icra_takip; u uuid:=auth.uid();
BEGIN
 IF u IS NULL OR NOT EXISTS(SELECT 1 FROM oyun.mahkeme_uye WHERE user_id=u)
  THEN RAISE EXCEPTION 'Yetkili mahkeme üyesi olmalısın';END IF;
 IF char_length(trim(coalesce(p_gerekce,'')))<12 THEN RAISE EXCEPTION 'Gerekçeli karar zorunlu';END IF;
 SELECT * INTO d FROM oyun.icra_takip WHERE id=p_id FOR UPDATE;
 IF d.id IS NULL OR d.durum<>'itiraz' THEN RAISE EXCEPTION 'Karar bekleyen itiraz yok';END IF;
 IF u=d.borclu OR (d.alacakli_sirket IS NOT NULL AND EXISTS
   (SELECT 1 FROM oyun.sirket_ortaklari WHERE sirket_id=d.alacakli_sirket AND user_id=u AND pay>0))
 THEN RAISE EXCEPTION 'Tarafsız olmayan yargıç karar veremez'; END IF;
 -- Vergi itirazlarında kamu idaresinin muhatap olduğu yargı simüle edilir; üretimde bağımsız inceleme önerilir.
 UPDATE oyun.icra_takip SET durum=CASE WHEN p_ret THEN 'haciz' ELSE 'iptal' END,
 karar_gerekce=trim(p_gerekce),karar_tarih=oyun.simdi() WHERE id=d.id;
 RETURN jsonb_build_object('durum',CASE WHEN p_ret THEN 'haciz' ELSE 'iptal' END);
END $function$;

CREATE OR REPLACE FUNCTION public.icra_dosya_panel()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid();
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giriş gerekli';END IF;
 RETURN jsonb_build_object(
 'dosyalar',COALESCE((SELECT jsonb_agg(jsonb_build_object(
   'id',d.id,'kaynak',d.kaynak,'kaynak_id',d.kaynak_id,'borclu',p.kad,'borclu_id',d.borclu,
   'alacakli_sirket',d.alacakli_sirket,'durum',d.durum,'baslangic',d.baslangic_borc,
   'kalan',oyun.icra_kalan_hesapla(d.id),'teblig',d.teblig,'odeme_son',d.odeme_son,
   'itiraz',d.itiraz,'gerekce',d.karar_gerekce,'ben_borclu',d.borclu=u,
   'ben_alacakli',EXISTS(SELECT 1 FROM oyun.sirket_ortaklari o
     WHERE o.sirket_id=d.alacakli_sirket AND o.user_id=u AND o.pay>=50)
     OR (d.kaynak='emlak_vergisi' AND EXISTS(SELECT 1 FROM oyun.makamlar m
       WHERE m.user_id=u AND m.bit IS NULL AND (m.tur='cb' OR(m.tur='bakan' AND m.bakanlik='maliye')))),
   'ben_hakim',EXISTS(SELECT 1 FROM oyun.mahkeme_uye m WHERE m.user_id=u),
   'hareket',COALESCE((SELECT jsonb_agg(jsonb_build_object('tur',h.tur,'tutar',h.tutar,'zaman',h.zaman))
       FROM oyun.icra_haciz_hareket h WHERE h.takip_id=d.id),'[]'::jsonb)
    ) ORDER BY d.id DESC) FROM
   (SELECT * FROM oyun.icra_takip WHERE borclu=u OR
      (alacakli_sirket IS NOT NULL AND EXISTS(SELECT 1 FROM oyun.sirket_ortaklari o WHERE o.sirket_id=alacakli_sirket AND o.user_id=u))
     OR (kaynak='emlak_vergisi' AND EXISTS(SELECT 1 FROM oyun.makamlar m
       WHERE m.user_id=u AND m.bit IS NULL AND (m.tur='cb' OR (m.tur='bakan' AND m.bakanlik='maliye'))))
     OR EXISTS(SELECT 1 FROM oyun.mahkeme_uye WHERE user_id=u)
      ORDER BY id DESC LIMIT 100)d JOIN oyun.profiller p ON p.id=d.borclu),'[]'::jsonb),
 'ihaleler',COALESCE((SELECT jsonb_agg(jsonb_build_object(
     'id',h.id,'dosya',h.takip_id,'tur',h.tur,'varlik',h.varlik_id,'deger',h.deger,
     'pay',h.haczedilen_pay,'durum',h.durum,'son',h.satis_son,'teklif',h.teklif,'borclu',p.kad,
     'teklif_veren_benim',h.teklif_veren=u) ORDER BY h.id DESC)
      FROM oyun.icra_haciz_yeni h JOIN oyun.icra_takip d ON d.id=h.takip_id
      JOIN oyun.profiller p ON p.id=d.borclu WHERE h.durum='ilan'),'[]'::jsonb)
 );
END $function$;

CREATE OR REPLACE FUNCTION public.icra_haczet(p_id bigint, p_tur text, p_varlik bigint DEFAULT NULL::bigint, p_kod text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); d oyun.icra_takip; n numeric; v numeric; t timestamptz:=oyun.simdi();
 qty numeric; fiyat numeric; pay numeric; hid bigint; korunan numeric:=0;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giriş yap';END IF;
 SELECT * INTO d FROM oyun.icra_takip WHERE id=p_id FOR UPDATE;
 IF d.id IS NULL OR d.durum NOT IN ('teblig','haciz') OR
   (d.durum='teblig' AND d.odeme_son>t) THEN RAISE EXCEPTION 'Ödeme emri süresi veya itiraz süreci devam ediyor';END IF;
 IF d.kaynak='kredi' AND NOT EXISTS(SELECT 1 FROM oyun.sirket_ortaklari
    WHERE sirket_id=d.alacakli_sirket AND user_id=u AND pay>=50)
  OR d.kaynak='emlak_vergisi' AND NOT EXISTS(SELECT 1 FROM oyun.makamlar
    WHERE user_id=u AND bit IS NULL AND (tur='cb' OR(tur='bakan' AND bakanlik='maliye')))
 THEN RAISE EXCEPTION 'Takip yetkin yok';END IF;
 n:=oyun.icra_kalan_hesapla(d.id);
 IF n<=0 THEN UPDATE oyun.icra_takip SET durum='kapandi' WHERE id=d.id;RETURN jsonb_build_object('durum','kapandi');END IF;
 -- Aynı borç için birden fazla açık artırma borç tutarını aşamasın.
 IF p_tur IN ('gayrimenkul','sirket_payi') THEN
  IF EXISTS(SELECT 1 FROM oyun.icra_haciz_yeni h WHERE h.takip_id=d.id AND h.durum='ilan'
    AND h.tur=p_tur AND h.varlik_id=p_varlik) THEN RAISE EXCEPTION 'Bu varlık zaten hacizli';END IF;
  IF p_tur='gayrimenkul' THEN
    SELECT alis_bedeli INTO v FROM oyun.yatirim_mulkleri WHERE id=p_varlik AND user_id=d.borclu;
    -- Tek konut istisnası oyun içi ihtiyatlı koruma, İİK 82 koşulları somut olayda değişir.
    IF EXISTS(SELECT 1 FROM oyun.yatirim_mulkleri WHERE id=p_varlik AND tip='daire')
      AND (SELECT COUNT(*) FROM oyun.yatirim_mulkleri WHERE user_id=d.borclu AND tip='daire')=1
    THEN RAISE EXCEPTION 'Borçlunun tek konutu koruma incelemesine tabi; otomatik haciz yapılamaz';END IF;
    IF EXISTS(SELECT 1 FROM oyun.icra_haciz_yeni h JOIN oyun.icra_takip x ON x.id=h.takip_id
      WHERE h.tur=p_tur AND h.varlik_id=p_varlik AND h.durum='ilan') THEN
      RAISE EXCEPTION 'Taşınmaz başka dosyada satışta';END IF;
  ELSE
    SELECT s.sermaye*o.pay/100,o.pay INTO v,pay FROM oyun.sirket_ortaklari o
     JOIN oyun.sirketler s ON s.id=o.sirket_id
     WHERE o.sirket_id=p_varlik AND o.user_id=d.borclu;
    IF EXISTS(SELECT 1 FROM oyun.icra_haciz_yeni h JOIN oyun.icra_takip x ON x.id=h.takip_id
      WHERE h.tur=p_tur AND h.varlik_id=p_varlik AND x.borclu=d.borclu AND h.durum='ilan')
    THEN RAISE EXCEPTION 'Bu pay başka dosyada satışta';END IF;
  END IF;
  IF v IS NULL OR v<=0 THEN RAISE EXCEPTION 'Borçluya ait pozitif değerli varlık yok';END IF;
  IF EXISTS(SELECT 1 FROM oyun.icra_haciz_yeni h WHERE h.takip_id=d.id AND h.durum='ilan'
       HAVING COALESCE(SUM(h.deger),0)>n*2) THEN
    RAISE EXCEPTION 'Ölçüsüz haciz: satışta yeterli teminat var';END IF;
  INSERT INTO oyun.icra_haciz_yeni(takip_id,tur,varlik_id,deger,haczedilen_pay,satis_son)
  VALUES(d.id,p_tur,p_varlik,round(v,2),pay,t+interval '48 hours') RETURNING id INTO hid;
  UPDATE oyun.icra_takip SET durum='haciz' WHERE id=d.id;
  RETURN jsonb_build_object('haciz_id',hid,'deger',v,'satis_son',t+interval '48 hours');
 ELSIF p_tur='cuzdan' THEN
  SELECT greatest(0,coalesce(sum(tutar),0)*0.75) INTO korunan FROM oyun.hesap_hareket
   WHERE user_id=d.borclu AND tur IN ('maas','gorev') AND tutar>0 AND zaman>t-interval '24 hours';
  SELECT greatest(0,para-least(para,korunan)) INTO v FROM oyun.cuzdan WHERE user_id=d.borclu FOR UPDATE;
  v:=least(n,coalesce(v,0));
  IF v>0 THEN
   PERFORM oyun.para_islem(d.borclu,-v,'icra_haciz','İcra dosyası #'||d.id||' cüzdan haczi',t);
  END IF;
 ELSIF p_tur='banka' THEN
  SELECT greatest(0,vadesiz) INTO v FROM oyun.banka_musteri WHERE user_id=d.borclu FOR UPDATE;
  v:=least(n,coalesce(v,0));
  IF v>0 THEN
   UPDATE oyun.banka_musteri SET vadesiz=vadesiz-v WHERE user_id=d.borclu;
   INSERT INTO oyun.banka_hareket(user_id,zaman,hesap,tutar,aciklama)
    VALUES(d.borclu,t,'vadesiz',-v,'İcra dosyası #'||d.id||' banka haczi');
  END IF;
 ELSIF p_tur='borsa' THEN
  SELECT p.miktar,a.fiyat INTO qty,fiyat FROM oyun.piyasa_pozisyon p
   JOIN oyun.piyasa_varlik a ON a.kod=p.kod
   WHERE p.user_id=d.borclu AND p.kod=p_kod AND p.miktar>0 AND a.aktif AND a.fiyat>0
   FOR UPDATE OF p;
  IF qty IS NULL THEN RAISE EXCEPTION 'Satılabilir borsa varlığı bulunamadı';END IF;
  pay:=least(qty,trunc(n/fiyat,8));
  IF pay<=0 THEN RAISE EXCEPTION 'Kalan alacak bu varlığın en küçük satış biriminin altında'; END IF;
  v:=least(n,round(pay*fiyat,2));
  UPDATE oyun.piyasa_pozisyon SET miktar=miktar-pay,
   maliyet=CASE WHEN miktar<=pay THEN 0 ELSE round(maliyet*(miktar-pay)/miktar,2) END
   WHERE user_id=d.borclu AND kod=p_kod;
  INSERT INTO oyun.piyasa_islem(user_id,kod,yon,miktar,fiyat,brut,komisyon,zaman)
   VALUES(d.borclu,p_kod,'sat',pay,fiyat,v,0,t);
 ELSE RAISE EXCEPTION 'Haciz türü geçersiz';END IF;
 IF v IS NULL OR v<=0 THEN RAISE EXCEPTION 'Haczedilebilir tutar bulunamadı'; END IF;
 v:=oyun.icra_tahsil_et(d.id,v,p_tur);
 UPDATE oyun.icra_takip SET durum=CASE WHEN oyun.icra_kalan_hesapla(d.id)<=0 THEN 'kapandi' ELSE 'haciz' END WHERE id=d.id;
 RETURN jsonb_build_object('tahsil',v,'kalan',oyun.icra_kalan_hesapla(d.id));
END $function$;

CREATE OR REPLACE FUNCTION public.icra_ihale_teklif(p_haciz bigint, p_tutar numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE h oyun.icra_haciz_yeni; d oyun.icra_takip; u uuid:=auth.uid();t timestamptz:=oyun.simdi();
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giriş yap';END IF;
 SELECT * INTO h FROM oyun.icra_haciz_yeni WHERE id=p_haciz FOR UPDATE;
 IF h.id IS NULL OR h.durum<>'ilan' OR h.satis_son<=t THEN RAISE EXCEPTION 'İhale açık değil'; END IF;
 SELECT * INTO d FROM oyun.icra_takip WHERE id=h.takip_id;
 IF d.durum NOT IN ('haciz','teblig') OR oyun.icra_kalan_hesapla(d.id)<=0 THEN RAISE EXCEPTION 'İhale dosyası kapandı'; END IF;
 IF d.borclu=u OR (d.alacakli_sirket IS NOT NULL AND EXISTS
    (SELECT 1 FROM oyun.sirket_ortaklari WHERE sirket_id=d.alacakli_sirket AND user_id=u AND pay>0))
 THEN RAISE EXCEPTION 'Borçlu veya alacaklı banka ihalede teklif veremez';END IF;
 IF p_tutar IS NULL OR p_tutar<>round(p_tutar) OR p_tutar<ceil(h.deger*0.5) OR
    (h.teklif IS NOT NULL AND p_tutar<h.teklif*1.01)
 THEN RAISE EXCEPTION 'Teklif kıymet takdirinin yarısından az olamaz; mevcut teklifi en az %%1 aş';END IF;
 PERFORM oyun.para_islem(u,-p_tutar,'icra_tem',format('İcra ihalesi #%s bloke bedel',h.id),t);
 IF h.teklif_veren IS NOT NULL THEN
   PERFORM oyun.para_islem(h.teklif_veren,h.teklif,'icra_tem_iade',format('İcra ihalesi #%s önceki teklif iadesi',h.id),t);
 END IF;
 UPDATE oyun.icra_haciz_yeni SET teklif=p_tutar,teklif_veren=u WHERE id=h.id;
 RETURN jsonb_build_object('teklif',p_tutar,'son',h.satis_son);
END $function$;

CREATE OR REPLACE FUNCTION public.icra_ihale_sonuclandir(p_haciz bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE h oyun.icra_haciz_yeni;d oyun.icra_takip;v numeric; k numeric; u uuid:=auth.uid();
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giriş yap';END IF;
 SELECT * INTO h FROM oyun.icra_haciz_yeni WHERE id=p_haciz FOR UPDATE;
 IF h.id IS NULL OR h.durum<>'ilan' OR h.satis_son>oyun.simdi() THEN RAISE EXCEPTION 'Satış süresi tamamlanmadı'; END IF;
 SELECT * INTO d FROM oyun.icra_takip WHERE id=h.takip_id FOR UPDATE;
 IF h.teklif_veren IS NULL OR d.durum NOT IN ('teblig','haciz') OR oyun.icra_kalan_hesapla(d.id)<=0 THEN
  IF h.teklif_veren IS NOT NULL THEN
    PERFORM oyun.para_islem(h.teklif_veren,h.teklif,'icra_tem_iade','İcra ihalesi iptal edilerek bedel iade edildi',oyun.simdi());
  END IF;
  UPDATE oyun.icra_haciz_yeni SET durum='iptal' WHERE id=h.id;
  RETURN jsonb_build_object('durum','iptal');
 END IF;
 IF h.tur='gayrimenkul' THEN
  UPDATE oyun.yatirim_mulkleri SET user_id=h.teklif_veren WHERE id=h.varlik_id AND user_id=d.borclu;
  IF NOT FOUND THEN RAISE EXCEPTION 'Mülkiyet değişmiş, ihale devri yapılamaz';END IF;
 ELSIF h.tur='sirket_payi' THEN
  PERFORM 1 FROM oyun.sirket_ortaklari
   WHERE sirket_id=h.varlik_id AND user_id=d.borclu AND pay=h.haczedilen_pay FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Şirket ortaklık payı değişmiş, satış engellendi';END IF;
  INSERT INTO oyun.sirket_ortaklari(sirket_id,user_id,pay,kar_kasada)
   VALUES(h.varlik_id,h.teklif_veren,h.haczedilen_pay,false)
   ON CONFLICT(sirket_id,user_id) DO UPDATE SET pay=oyun.sirket_ortaklari.pay+excluded.pay;
  DELETE FROM oyun.sirket_ortaklari WHERE sirket_id=h.varlik_id AND user_id=d.borclu;
 ELSE RAISE EXCEPTION 'İhale varlık türü uygun değil';END IF;
 v:=oyun.icra_tahsil_et(d.id,h.teklif,'acik_artirma');
 k:=h.teklif-v;
 IF k>0 THEN
  PERFORM oyun.para_islem(d.borclu,k,'icra_artik','İcra satışından artan bedel iadesi',oyun.simdi());
 END IF;
 UPDATE oyun.icra_haciz_yeni SET durum='satildi',satis_at=oyun.simdi() WHERE id=h.id;
 RETURN jsonb_build_object('durum','satildi','tahsil',v,'borcluya_artik',k);
END $function$;

CREATE OR REPLACE FUNCTION public.icra_baslatilabilir()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid();vergi_yetkili boolean;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giriş yap';END IF;
 vergi_yetkili:=EXISTS(SELECT 1 FROM oyun.makamlar WHERE user_id=u AND bit IS NULL
   AND (tur='cb' OR(tur='bakan' AND bakanlik='maliye')));
 RETURN jsonb_build_object(
  'krediler',coalesce((SELECT jsonb_agg(jsonb_build_object('id',k.id,'banka',s.ad,'borclu',p.kad,'kalan',k.kalan))
   FROM oyun.oyb_icra i JOIN oyun.oyb_kredi k ON k.id=i.kredi_id
    JOIN oyun.sirketler s ON s.id=k.banka_id JOIN oyun.profiller p ON p.id=k.borclu
   WHERE i.durum='kabul' AND i.kesin_son<=oyun.simdi() AND k.kalan>0
    AND EXISTS(SELECT 1 FROM oyun.sirket_ortaklari o WHERE o.sirket_id=i.banka_id AND o.user_id=u AND o.pay>=50)
    AND NOT EXISTS(SELECT 1 FROM oyun.icra_takip d WHERE d.kaynak='kredi' AND d.kaynak_id=k.id)),'[]'::jsonb),
  'vergiler',CASE WHEN vergi_yetkili THEN coalesce((SELECT jsonb_agg(jsonb_build_object(
     'id',m.id,'borclu',p.kad,'tutar',m.vergi_borc,'tip',m.tip))
     FROM oyun.yatirim_mulkleri m JOIN oyun.profiller p ON p.id=m.user_id
      WHERE m.vergi_borc>0 AND NOT EXISTS(SELECT 1 FROM oyun.icra_takip d WHERE d.kaynak='emlak_vergisi' AND d.kaynak_id=m.id)),'[]'::jsonb)
   ELSE '[]'::jsonb END
 );
END $function$;

CREATE OR REPLACE FUNCTION public.icra_varliklar(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d oyun.icra_takip; u uuid:=auth.uid();yetkili boolean;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'Giriş yap';END IF;
 SELECT * INTO d FROM oyun.icra_takip WHERE id=p_id;
 IF d.id IS NULL THEN RAISE EXCEPTION 'Dosya yok';END IF;
 yetkili:=d.borclu=u OR (d.kaynak='kredi' AND EXISTS
   (SELECT 1 FROM oyun.sirket_ortaklari WHERE sirket_id=d.alacakli_sirket AND user_id=u AND pay>=50))
 OR (d.kaynak='emlak_vergisi' AND EXISTS(SELECT 1 FROM oyun.makamlar
     WHERE user_id=u AND bit IS NULL AND (tur='cb' OR(tur='bakan' AND bakanlik='maliye'))));
 IF NOT yetkili THEN RAISE EXCEPTION 'Bu dosyanın varlıklarını görme yetkin yok';END IF;
 RETURN jsonb_build_object(
  'bankadaki',coalesce((SELECT vadesiz FROM oyun.banka_musteri WHERE user_id=d.borclu),0),
  'cuzdan',coalesce((SELECT para FROM oyun.cuzdan WHERE user_id=d.borclu),0),
  'borsa',coalesce((SELECT jsonb_agg(jsonb_build_object('kod',p.kod,'miktar',p.miktar,'fiyat',v.fiyat))
   FROM oyun.piyasa_pozisyon p JOIN oyun.piyasa_varlik v ON v.kod=p.kod
   WHERE p.user_id=d.borclu AND p.miktar>0 AND v.fiyat>0),'[]'::jsonb),
  'mulk',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'tip',tip,'deger',alis_bedeli))
   FROM oyun.yatirim_mulkleri WHERE user_id=d.borclu),'[]'::jsonb),
  'sirketler',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.sirket_id,'ad',s.ad,'pay',o.pay,'deger',round(s.sermaye*o.pay/100,2)))
   FROM oyun.sirket_ortaklari o JOIN oyun.sirketler s ON s.id=o.sirket_id
   WHERE o.user_id=d.borclu AND o.pay>0),'[]'::jsonb)
 );
END $function$;

REVOKE EXECUTE ON FUNCTION oyun.icra_kalan_hesapla(p_id bigint),oyun.icra_tahsil_et(p_id bigint, p_tutar numeric, p_tur text) FROM PUBLIC,anon,authenticated;

