-- 131 · Mahkemede avukat zorunluluğu + Parti Sözcüsü resmî açıklama makamı (23.10.2026)
-- * Dava açma, savunma/beyan, istinaf, seçim itirazı ve parti kapatma savunması yalnız avukat eliyle yapılır.
--   Oyuncu, parti (genel başkan), kurum/dernek/şirket yetkilisi müvekkil olur; avukat onun adına işlem yapar.
-- * Dava açmak isteyen "hukuki iş" talebi oluşturur, avukatlar teklif verir, ücret emanete alınır,
--   avukat dilekçeyi mahkemeye sununca ücret avukata geçer. Sunulmadan iptal/çekilmede iade edilir.
-- * İlgili taraf (yargıcın çağırdığı tanık) kendi beyanını verebilir; bu savunma değildir.
-- * Parti sözcüsü mahkemede temsil yapamaz; partisi adına resmî açıklama yapar (akışa da düşer).
-- Yalnız ekleme / create or replace. Mevcut dava ve para kayıtları değişmez; geçişten önce açılmış
-- davaların istinafı eski usulle (sözcü hariç) sürer.

-- ---------------------------------------------------------------- 1) Ayar, yardımcılar, tablolar
alter table oyun.ayarlar add column if not exists avukat_zorunlu_bas timestamptz;
alter table oyun.ayarlar add column if not exists avukat_savunma_saat int not null default 24;
update oyun.ayarlar set avukat_zorunlu_bas=now() where id=1 and avukat_zorunlu_bas is null;

create or replace function oyun.avukat_zorunlu_mu(p_acilis timestamptz) returns boolean language sql stable set search_path='' as $f$
 select p_acilis>=coalesce((select avukat_zorunlu_bas from oyun.ayarlar where id=1),'-infinity'::timestamptz)
$f$;

create or replace function oyun.vekil_islem_mi() returns boolean language sql stable set search_path='' as $f$
 select coalesce(current_setting('oyun.vekil_islem',true),'')<>''
$f$;

-- Avukat, müvekkilin adına mahkeme işlemi yapar: istek bu işlem boyunca müvekkil kimliğiyle çalışır.
create or replace function oyun.vekil_basla(p_muvekkil uuid,p_avukat uuid) returns text language plpgsql set search_path='' as $f$
declare onceki text:=coalesce(current_setting('request.jwt.claim.sub',true),'');
begin
 perform set_config('request.jwt.claim.sub',p_muvekkil::text,true);
 perform set_config('oyun.vekil_islem',p_avukat::text,true);
 return onceki;
end $f$;

create or replace function oyun.vekil_bitir(p_onceki text) returns void language plpgsql set search_path='' as $f$
begin
 perform set_config('request.jwt.claim.sub',coalesce(p_onceki,''),true);
 perform set_config('oyun.vekil_islem','',true);
end $f$;

-- Dosyanın bir tarafı adına avukat tutabilecek kişi: kişi, partinin genel başkanı ya da kurum yetkilisi
create or replace function oyun.dava_muvekkil_mi(d oyun.adliye_davalar,p_taraf text,u uuid) returns boolean language sql stable set search_path='' as $f$
 select case when u is null then false
  when p_taraf='davaci' then (d.davaci=u or exists(select 1 from oyun.partiler pa where pa.id=d.davaci_parti and pa.gb=u))
  when p_taraf='davali' then (d.davali=u or exists(select 1 from oyun.partiler pa where pa.id=d.davali_parti and pa.gb=u)
     or (d.davali_kurum_tur is not null and oyun.adliye_kurum_yetkili(d.davali_kurum_tur,d.davali_kurum_id,u)))
  else false end
$f$;

create table if not exists oyun.hukuk_isleri(
 id bigserial primary key,
 tur text not null check(tur in ('dava','secim_itiraz','pkd_savunma')),
 muvekkil uuid not null references oyun.profiller(id),
 parti_id bigint references oyun.partiler(id),
 hedef_tur text,
 hedef text,
 hedef_ad text,
 dava_tur text,
 tazminat_talep numeric,
 secim_id bigint,
 pkd_id bigint,
 metin text not null,
 delil text not null default '',
 durum text not null default 'avukat_bekliyor' check(durum in ('avukat_bekliyor','vekil_atandi','sunuldu','iptal')),
 avukat_id uuid references oyun.profiller(id),
 ucret numeric not null default 0,
 prim numeric not null default 0,
 emanet numeric not null default 0 check(emanet>=0),
 dava_id bigint references oyun.adliye_davalar(id),
 olusturma timestamptz not null default now(),
 atama_at timestamptz,
 sunum_at timestamptz,
 iptal_at timestamptz
);
create index if not exists hukuk_isleri_durum on oyun.hukuk_isleri(durum,id desc);
create index if not exists hukuk_isleri_muvekkil on oyun.hukuk_isleri(muvekkil,id desc);
create table if not exists oyun.hukuk_is_teklifleri(
 id bigserial primary key,
 is_id bigint not null references oyun.hukuk_isleri(id),
 avukat_id uuid not null references oyun.profiller(id),
 tutar numeric not null check(tutar between 0 and 1000000000000),
 prim numeric not null default 0 check(prim between 0 and 25),
 aciklama text not null default '',
 durum text not null default 'bekliyor' check(durum in ('bekliyor','kabul','ret','iptal')),
 zaman timestamptz not null default now()
);
create unique index if not exists hukuk_is_tek_bekleyen on oyun.hukuk_is_teklifleri(is_id,avukat_id) where durum='bekliyor';
create table if not exists oyun.parti_aciklamalar(
 id bigserial primary key,
 parti_id bigint not null references oyun.partiler(id),
 yazar uuid not null references oyun.profiller(id),
 rol text not null check(rol in ('sozcu','gb')),
 baslik text not null check(char_length(baslik) between 3 and 120),
 metin text not null check(char_length(metin) between 10 and 2000),
 zaman timestamptz not null default now(),
 silindi boolean not null default false
);
create index if not exists parti_aciklamalar_parti on oyun.parti_aciklamalar(parti_id,id desc) where not silindi;
do $guard$
declare t text;
begin
 foreach t in array array['hukuk_isleri','hukuk_is_teklifleri','parti_aciklamalar'] loop
  execute format('alter table oyun.%I enable row level security',t);
  execute format('revoke all on oyun.%I from public, anon, authenticated',t);
 end loop;
end $guard$;

-- ---------------------------------------------------------------- 2) Mahkeme kapıları
create or replace function public.adliye_dava_ac(p_hedef_tur text,p_hedef text,p_tur text,p_iddia text,p_delil text default '',p_davaci_parti bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); u oyun.profiller; hedef_parti bigint; t timestamptz:=oyun.simdi(); yeni bigint; h numeric:=(select harc from oyun.mahkeme_ayar);
 sure int:=coalesce((select avukat_savunma_saat from oyun.ayarlar where id=1),24);
begin
 if not oyun.vekil_islem_mi() then raise exception 'Dava açmak için avukat tutmalısın: Adliye > Dava aç ile hukuki iş talebi oluştur, avukatın davayı senin adına mahkemeye sunar.'; end if;
 if p_tur not in('hakaret','iftira','rusvet','yolsuzluk','usulsuzluk','dolandiricilik','diger') then raise exception 'Dava türü geçersiz.'; end if;
 if char_length(trim(coalesce(p_iddia,''))) not between 20 and 1600 then raise exception 'Dava açıklaması 20–1600 karakter olmalı.'; end if;
 if char_length(coalesce(p_delil,''))>1600 then raise exception 'Delil açıklaması 1600 karakteri aşamaz.'; end if;
 if p_hedef_tur='oyuncu' then
  select * into u from oyun.profiller where lower(kad)=lower(trim(p_hedef)) and not yasakli;
  if u.id is null then raise exception 'Davalı oyuncu bulunamadı.'; end if;
  if u.id=p.id then raise exception 'Kendinize dava açamazsınız.'; end if;
 elsif p_hedef_tur='parti' then
  begin hedef_parti:=p_hedef::bigint; exception when invalid_text_representation then raise exception 'Geçersiz parti.'; end;
  if not exists(select 1 from oyun.partiler where id=hedef_parti and not kapali) then raise exception 'Parti bulunamadı.'; end if;
 else raise exception 'Davalı türü geçersiz.'; end if;
 if p_davaci_parti is not null and not exists(select 1 from oyun.partiler pa where pa.id=p_davaci_parti and not pa.kapali and pa.gb=p.id)
  then raise exception 'Parti adına davayı yalnız genel başkanın tuttuğu avukat açabilir.'; end if;
 if hedef_parti is not null and hedef_parti=p_davaci_parti then raise exception 'Bir parti kendisine dava açamaz.'; end if;
 if (select count(*) from oyun.adliye_davalar where davaci=p.id and durum='acik')>=3 then raise exception 'Müvekkilin en fazla üç açık davası olabilir.'; end if;
 if exists(select 1 from oyun.adliye_davalar where davaci=p.id and acilis>t-interval '10 minutes') then raise exception 'Müvekkil adına yeni dava için 10 dakika bekleyin.'; end if;
 if h>0 then perform oyun.para_islem(p.id,-h,'adliye','Dava harcı',t); end if;
 insert into oyun.adliye_davalar(davaci,davaci_parti,davali,davali_parti,tur,iddia,delil,acilis,savunma_son,karar_son,harc,harc_durum,kesin)
 values(p.id,p_davaci_parti,u.id,hedef_parti,p_tur,trim(p_iddia),coalesce(p_delil,''),t,t+make_interval(hours=>sure),
        t+make_interval(hours=>sure)+make_interval(hours=>(select karar_saat from oyun.mahkeme_ayar)),h,case when h>0 then 'yatirildi' end,false) returning id into yeni;
 if u.id is not null then
  perform oyun.bildir(u.id,format('#%s numaralı davada hakkınızda iddia var. Savunmanızı %s saat içinde avukatınız sunabilir: dosyadaki teklifleri inceleyin ya da Baro''dan adli yardım isteyin.',yeni,sure),t);
 end if;
 if hedef_parti is not null then
  perform oyun.bildir(pa.gb,format('#%s numaralı davada partiniz davalıdır. Savunma için %s saat içinde parti adına avukat tutun (Adliye > dosya).',yeni,sure),t)
   from oyun.partiler pa where pa.id=hedef_parti and pa.gb is not null;
 end if;
 perform oyun.bildir(m.user_id,'Yüksek Mahkeme: #'||yeni||' numaralı yeni dava dosyası açıldı.',t)
  from oyun.mahkeme_uye m where m.user_id is not null and m.user_id<>p.id and m.user_id is distinct from u.id;
 return jsonb_build_object('tamam',true,'id',yeni,'harc',h);
end $f$;

create or replace function public.adliye_kurum_dava_ac(p_hedef_tur text,p_hedef text,p_tur text,p_iddia text,p_delil text default '',p_davaci_parti bigint default null,p_tazminat_talep numeric default null)
returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); kurum_ad text; t timestamptz:=oyun.simdi(); yeni bigint;
 h numeric:=coalesce((select harc from oyun.mahkeme_ayar),0); sure int:=coalesce((select avukat_savunma_saat from oyun.ayarlar where id=1),24);
begin
 if not oyun.vekil_islem_mi() then raise exception 'Dava açmak için avukat tutmalısın: Adliye > Dava aç ile hukuki iş talebi oluştur, avukatın davayı senin adına mahkemeye sunar.'; end if;
 if p_hedef_tur not in ('sirket','dernek','belediye','makam','bakanlik','gazete') then raise exception 'Kurum türü geçersiz.'; end if;
 kurum_ad:=oyun.adliye_kurum_adi(p_hedef_tur,p_hedef);
 if kurum_ad is null then raise exception 'Kurum bulunamadı veya faal değil.'; end if;
 if oyun.adliye_kurum_yetkili(p_hedef_tur,p_hedef,p.id) then raise exception 'Temsil ettiğiniz kuruma dava açamazsınız.'; end if;
 if p_tur not in ('hakaret','iftira','rusvet','yolsuzluk','usulsuzluk','dolandiricilik','diger','tazminat') then raise exception 'Dava türü geçersiz.'; end if;
 if char_length(trim(coalesce(p_iddia,''))) not between 20 and 1600 then raise exception 'İddia 20–1600 karakter olmalıdır.'; end if;
 if char_length(coalesce(p_delil,''))>1600 then raise exception 'Delil en fazla 1600 karakter olabilir.'; end if;
 if p_tur='tazminat' and (p_hedef_tur='makam' or p_tazminat_talep is null or
  p_tazminat_talep<1000 or p_tazminat_talep>500000 or p_tazminat_talep<>trunc(p_tazminat_talep))
  then raise exception 'Tazminat için 1.000–500.000 TL arasında tam sayı tutar gerekir; makamın kasası yoktur.'; end if;
 if p_davaci_parti is not null and not exists(select 1 from oyun.partiler pa where pa.id=p_davaci_parti and not pa.kapali and pa.gb=p.id)
  then raise exception 'Parti adına davayı yalnız genel başkanın tuttuğu avukat açabilir.'; end if;
 if (select count(*) from oyun.adliye_davalar where davaci=p.id and durum='acik')>=3 then raise exception 'Müvekkilin en fazla üç açık davası olabilir.'; end if;
 if exists(select 1 from oyun.adliye_davalar where davaci=p.id and acilis>t-interval '10 minutes') then raise exception 'Müvekkil adına yeni dava için 10 dakika bekleyin.'; end if;
 if h>0 then perform oyun.para_islem(p.id,-h,'adliye','Dava harcı',t); end if;
 insert into oyun.adliye_davalar(davaci,davaci_parti,davali_kurum_tur,davali_kurum_id,davali_kurum_ad,tur,iddia,delil,acilis,savunma_son,karar_son,harc,harc_durum,kesin,tazminat_talep)
 values(p.id,p_davaci_parti,p_hedef_tur,p_hedef,kurum_ad,p_tur,trim(p_iddia),coalesce(p_delil,''),t,t+make_interval(hours=>sure),
  t+make_interval(hours=>sure)+make_interval(hours=>(select karar_saat from oyun.mahkeme_ayar)),
  h,case when h>0 then 'yatirildi' end,false,case when p_tur='tazminat' then p_tazminat_talep end) returning id into yeni;
 perform oyun.bildir(q.id,format('Adliye #%s: %s aleyhine dava açıldı. Kurum adına %s saat içinde avukat tutun; savunmayı avukat sunar.',yeni,kurum_ad,sure),t)
  from oyun.profiller q where oyun.adliye_kurum_yetkili(p_hedef_tur,p_hedef,q.id) and q.id<>p.id;
 perform oyun.bildir(q.user_id,format('Yüksek Mahkeme: yeni kurum davası #%s',yeni),t)
  from oyun.mahkeme_uye q where q.user_id is not null and q.user_id<>p.id and not oyun.adliye_kurum_yetkili(p_hedef_tur,p_hedef,q.user_id);
 return jsonb_build_object('tamam',true,'id',yeni,'harc',h);
end $f$;

-- Taraflar ve sözcüler mahkemeye doğrudan yazamaz; yalnız yargıcın çağırdığı ilgili taraf (tanık) beyan verir.
create or replace function public.adliye_beyan_ver(p_dava bigint,p_metin text) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); d oyun.adliye_davalar;
begin
 select * into d from oyun.adliye_davalar where id=p_dava for update;
 if d.id is null or d.durum<>'acik' then raise exception 'Dava beyana açık değil.'; end if;
 if not exists(select 1 from oyun.adliye_ek_taraf e where e.dava_id=d.id and e.user_id=p.id) then
  raise exception 'Mahkemeye savunma ve beyanı yalnız dosyadaki avukatın sunabilir. Avukat tutmak için dosyadaki teklifleri incele veya Baro''dan adli yardım iste.';
 end if;
 if char_length(trim(coalesce(p_metin,''))) not between 10 and 2500 then raise exception 'Beyan 10-2500 karakter olmalı.'; end if;
 if exists(select 1 from oyun.adliye_beyan where dava_id=d.id and yazar=p.id and zaman>oyun.simdi()-interval '30 seconds') then raise exception 'Yeni beyan için 30 saniye bekleyin.'; end if;
 insert into oyun.adliye_beyan(dava_id,yazar,rol,metin,zaman) values(d.id,p.id,'ilgili',trim(p_metin),oyun.simdi());
 return jsonb_build_object('tamam',true,'tip','ilgili_beyani');
end $f$;

create or replace function public.adliye_temsil_yetkisi(p_dava bigint,p_izin boolean) returns jsonb language plpgsql security definer set search_path='' as $f$
begin
 perform oyun.profilim();
 raise exception 'Parti sözcüleri artık mahkemede temsil yapamaz. Davanda seni yalnız tuttuğun avukat temsil eder.';
end $f$;

create or replace function public.adliye_secim_itiraz_ac(p_secim bigint,p_parti bigint,p_gerekce text,p_deliller text default '') returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); s oyun.secimler; t timestamptz:=oyun.simdi(); yeni_id bigint;
begin
 if not oyun.vekil_islem_mi() then raise exception 'Seçim itirazını partinin avukatı yapar: Adliye > Seçim sonuçlarına itiraz ile hukuki iş talebi oluştur.'; end if;
 if not exists(select 1 from oyun.partiler pa where pa.id=p_parti and not pa.kapali and pa.gb=p.id)
 then raise exception 'İtirazı yalnız genel başkanın tuttuğu avukat yapabilir.'; end if;
 select * into s from oyun.secimler where id=p_secim;
 if s.id is null then raise exception 'Seçim bulunamadı.'; end if;
 if s.sonuc is null or s.sonuc_at is null or t<s.sonuc_at then raise exception 'Yalnız sonuçlanmış seçimlere itiraz edilebilir.'; end if;
 if t>s.sonuc_at+interval '48 hours' then raise exception '48 saatlik itiraz süresi doldu.'; end if;
 if char_length(trim(coalesce(p_gerekce,''))) not between 30 and 1600 then raise exception 'İtiraz gerekçesi 30-1600 karakter olmalı.'; end if;
 if char_length(coalesce(p_deliller,''))>3000 then raise exception 'Deliller en fazla 3000 karakter olabilir.'; end if;
 insert into oyun.adliye_secim_itirazlari(secim_id,parti_id,yapan,gerekce,deliller,zaman)
 values(s.id,p_parti,p.id,trim(p_gerekce),trim(coalesce(p_deliller,'')),t) returning id into yeni_id;
 return jsonb_build_object('tamam',true,'id',yeni_id);
end $f$;

create or replace function public.parti_kapatma_savunma(p_dava bigint,p_metin text) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); t timestamptz:=oyun.simdi(); d oyun.pkd_dava; pa oyun.partiler; m text;
begin
 if not oyun.vekil_islem_mi() then raise exception 'Parti kapatma davasında savunmayı partinin avukatı sunar: genel başkan hukuki iş talebi oluşturmalı.'; end if;
 select * into d from oyun.pkd_dava where id=p_dava for update;
 if d.id is null or d.durum<>'savunma' or t>=d.savunma_son then raise exception 'Bu dava savunma aşamasında değil.'; end if;
 select * into pa from oyun.partiler where id=d.parti_id;
 if p.id is distinct from pa.gb and p.id is distinct from pa.gb_vekil then raise exception 'Savunmayı yalnız davalı partinin genel başkanının tuttuğu avukat verebilir.'; end if;
 m:=oyun.metin_temizle(p_metin,3000);
 if length(m)<50 then raise exception 'Savunma en az 50 karakter olmalı.'; end if;
 update oyun.pkd_dava set savunma=m,savunan=p.id,savunma_at=t where id=d.id;
 perform oyun.pkd_yargilamaya_al(d.id,t);
 return public.parti_kapatma_davalari(null);
end $f$;

create or replace function public.adliye_sozcu_ata(p_parti bigint,p_kad text default null) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); u oyun.profiller; eski uuid; t timestamptz:=oyun.simdi();
begin
 if not exists(select 1 from oyun.partiler where id=p_parti and gb=p.id and not kapali) then raise exception 'Parti sözcüsünü yalnız partinin genel başkanı belirleyebilir.'; end if;
 if p_kad is not null and trim(p_kad)<>'' then
  select * into u from oyun.profiller where lower(kad)=lower(trim(p_kad)) and parti_id=p_parti and not yasakli;
  if u.id is null then raise exception 'Bu partide böyle bir üye bulunamadı.'; end if;
 end if;
 select user_id into eski from oyun.parti_sozcu where parti_id=p_parti for update;
 insert into oyun.parti_sozcu(parti_id,user_id,atayan,zaman) values(p_parti,u.id,p.id,t)
 on conflict (parti_id) do update set user_id=excluded.user_id,atayan=excluded.atayan,zaman=excluded.zaman;
 insert into oyun.parti_sozcu_kayit(parti_id,yapan,eski,yeni,zaman) values(p_parti,p.id,eski,u.id,t);
 if eski is not null and eski is distinct from u.id then
  perform oyun.bildir(eski,'Parti sözcülüğü göreviniz sona erdi; artık parti adına resmî açıklama yapamazsınız.',t);
 end if;
 if u.id is not null then
  perform oyun.bildir(u.id,'Genel başkanınız sizi Parti Sözcüsü olarak atadı. Partiniz adına resmî açıklama yapabilirsiniz (Partiler > partiniz > Parti Sözcüsü).',t);
 end if;
 return jsonb_build_object('tamam',true);
end $f$;

-- İstinaf: yeni usul davalarda yalnız kaybeden tarafın avukatı; sözcü hiçbir davada başvuramaz.
do $patch$
declare def text; yeni text;
begin
 select pg_get_functiondef('public.adliye_istinaf(bigint,text)'::regprocedure) into def;
 yeni:=replace(def,'(pa.gb = p.id or s.user_id = p.id)','pa.gb = p.id');
 if position('oyun.vekil_islem_mi()' in yeni)=0 then
  if position('raise exception ''Bu karar istinafa açık değil.''; end if;' in yeni)=0 then raise exception 'adliye_istinaf beklenen ifade bulunamadı'; end if;
  yeni:=replace(yeni,'raise exception ''Bu karar istinafa açık değil.''; end if;',
   'raise exception ''Bu karar istinafa açık değil.''; end if;'||chr(10)||
   '  if oyun.avukat_zorunlu_mu(d.acilis) and not oyun.vekil_islem_mi() then raise exception ''İstinaf başvurusunu kaybeden tarafın avukatı yapar (dava dosyasındaki avukat paneli).''; end if;');
 end if;
 if yeni<>def then execute yeni; end if;
end $patch$;

-- ---------------------------------------------------------------- 3) Avukat–müvekkil (kurum ve parti dahil)
create or replace function public.avukat_teklif_ver(p_dava bigint,p_taraf text,p_tutar numeric,p_prim numeric default 0,p_aciklama text default '') returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); d oyun.adliye_davalar; tid bigint; engel text;
begin
 engel:=oyun.avukat_engel(p.id);
 if engel is not null then raise exception '%',engel; end if;
 select * into d from oyun.adliye_davalar where id=p_dava;
 if d.id is null or d.durum<>'acik' then raise exception 'Açık dava bulunamadı.'; end if;
 if p_taraf not in ('davaci','davali') or p_tutar is null or p_tutar<0 or p_tutar>1000000000000 then raise exception 'Teklif bilgileri geçersiz.'; end if;
 if p_prim is null or p_prim<0 or p_prim>25 then raise exception 'Başarı primi %%0 ile %%25 arasında olmalı (Avukatlık Kanunu m.164).'; end if;
 if not exists(select 1 from oyun.profiller q where oyun.dava_muvekkil_mi(d,p_taraf,q.id)) then raise exception 'Bu tarafta avukat tutabilecek bir oyuncu yok.'; end if;
 if oyun.dava_muvekkil_mi(d,'davaci',p.id) or oyun.dava_muvekkil_mi(d,'davali',p.id) then raise exception 'Kendi davanızda ya da temsil ettiğiniz kurumun davasında avukatlık yapamazsınız.'; end if;
 if exists(select 1 from oyun.mahkeme_uye where user_id=p.id) then raise exception 'Yargıç avukatlık yapamaz.'; end if;
 if exists(select 1 from oyun.avukat_vekaletleri where dava_id=p_dava and avukat_id=p.id and aktif) then raise exception 'Bu davada zaten vekilsiniz.'; end if;
 if exists(select 1 from oyun.avukat_vekaletleri where dava_id=p_dava and taraf=p_taraf and aktif) then raise exception 'Bu tarafın aktif avukatı var.'; end if;
 if exists(select 1 from oyun.avukat_teklifleri where dava_id=p_dava and avukat_id=p.id and taraf=p_taraf and durum='bekliyor') then raise exception 'Bu taraf için bekleyen bir teklifin zaten var.'; end if;
 insert into oyun.avukat_teklifleri(dava_id,avukat_id,taraf,tutar,prim_orani,aciklama)
 values(p_dava,p.id,p_taraf,round(p_tutar),p_prim,left(trim(coalesce(p_aciklama,'')),500)) returning id into tid;
 perform oyun.bildir(q.id,format('Adliye #%s için Av. %s teklif verdi: %s ₺, başarı primi %%%s.',p_dava,p.kad,oyun.tl(round(p_tutar)),p_prim),oyun.simdi())
  from oyun.profiller q where oyun.dava_muvekkil_mi(d,p_taraf,q.id);
 return jsonb_build_object('tamam',true,'id',tid);
end $f$;

create or replace function public.avukat_karsi_teklif(p_teklif bigint,p_tutar numeric,p_prim numeric) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); t oyun.avukat_teklifleri; d oyun.adliye_davalar;
begin
 select * into t from oyun.avukat_teklifleri where id=p_teklif for update;
 if t.id is null or t.durum<>'bekliyor' then raise exception 'Teklif kapandı.'; end if;
 select * into d from oyun.adliye_davalar where id=t.dava_id;
 if d.durum<>'acik' then raise exception 'Dava kapandı.'; end if;
 if not oyun.dava_muvekkil_mi(d,t.taraf,p.id) then raise exception 'Bu davada müvekkil yetkiniz yok.'; end if;
 if p_tutar is null or p_tutar<0 or p_tutar>1000000000000 then raise exception 'Karşı teklif geçersiz.'; end if;
 if p_prim is null or p_prim<0 or p_prim>25 then raise exception 'Başarı primi %%0 ile %%25 arasında olmalı (Avukatlık Kanunu m.164).'; end if;
 insert into oyun.avukat_pazarlik(teklif_id,muvekkil,tutar,prim) values(t.id,p.id,round(p_tutar),p_prim)
 on conflict(teklif_id) do update set muvekkil=excluded.muvekkil,tutar=excluded.tutar,prim=excluded.prim,durum='bekliyor',zaman=now();
 perform oyun.bildir(t.avukat_id,format('Dava #%s için müvekkil karşı teklif sundu: %s ₺, prim %%%s. Dava dosyasından yanıtla.',d.id,oyun.tl(round(p_tutar)),p_prim),oyun.simdi());
 return jsonb_build_object('tamam',true);
end $f$;

create or replace function public.avukat_teklif_karar(p_teklif bigint,p_kabul boolean) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); t oyun.avukat_teklifleri; d oyun.adliye_davalar;
begin
 select * into t from oyun.avukat_teklifleri where id=p_teklif for update;
 if t.id is null or t.durum<>'bekliyor' then raise exception 'Teklif beklemede değil.'; end if;
 select * into d from oyun.adliye_davalar where id=t.dava_id for update;
 if d.durum<>'acik' then raise exception 'Dava kapandı.'; end if;
 if not oyun.dava_muvekkil_mi(d,t.taraf,p.id) then raise exception 'Teklifin müvekkili değilsiniz.'; end if;
 if not p_kabul then update oyun.avukat_teklifleri set durum='ret' where id=t.id; return jsonb_build_object('durum','ret'); end if;
 if not oyun.avukat_mi(t.avukat_id) then raise exception 'Avukat şu anda mesleği icra edemiyor.'; end if;
 if exists(select 1 from oyun.avukat_vekaletleri where dava_id=d.id and taraf=t.taraf and aktif) then raise exception 'Bu tarafın zaten avukatı var.'; end if;
 if exists(select 1 from oyun.avukat_vekaletleri where dava_id=d.id and avukat_id=t.avukat_id and aktif) then raise exception 'Aynı avukat karşı tarafı temsil edemez.'; end if;
 if t.tutar>0 then
  perform oyun.para_islem(p.id,-t.tutar,'adliye','Dava #'||d.id||' avukatlık ücreti',oyun.simdi());
  perform oyun.para_islem(t.avukat_id,t.tutar,'adliye','Dava #'||d.id||' avukatlık ücreti',oyun.simdi());
 end if;
 insert into oyun.avukat_vekaletleri(teklif_id,dava_id,avukat_id,muvekkil,taraf,ucret,prim_orani)
 values(t.id,d.id,t.avukat_id,p.id,t.taraf,t.tutar,t.prim_orani);
 update oyun.avukat_teklifleri set durum='kabul',kabul_at=now() where id=t.id;
 update oyun.avukat_teklifleri set durum='iptal' where dava_id=d.id and taraf=t.taraf and id<>t.id and durum='bekliyor';
 perform oyun.bildir(t.avukat_id,format('Dava #%s avukatlık teklifiniz kabul edildi.',d.id),oyun.simdi());
 return jsonb_build_object('durum','kabul');
end $f$;

create or replace function public.avukat_dava_durum(p_dava bigint) returns jsonb language plpgsql stable security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); d oyun.adliye_davalar;
begin
 select * into d from oyun.adliye_davalar where id=p_dava;
 if d.id is null then raise exception 'Dava bulunamadı.'; end if;
 return jsonb_build_object(
  'teklifler',(select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'avukat',oyun.kad(t.avukat_id),'taraf',t.taraf,'tutar',t.tutar,'prim',t.prim_orani,'aciklama',t.aciklama,'durum',t.durum,'benim',t.avukat_id=p.id,
      'cevaplayabilirim',oyun.dava_muvekkil_mi(d,t.taraf,p.id)) order by t.id desc),'[]'::jsonb)
    from oyun.avukat_teklifleri t where t.dava_id=p_dava and (t.avukat_id=p.id or oyun.dava_muvekkil_mi(d,t.taraf,p.id) or t.durum='kabul')),
  'vekaletler',(select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'avukat',oyun.kad(v.avukat_id),'taraf',v.taraf,'muvekkil',oyun.kad(v.muvekkil),'ucret',v.ucret,'aktif',v.aktif,
      'benim',v.avukat_id=p.id or v.muvekkil=p.id,'avukat_miyim',v.avukat_id=p.id) order by v.id desc),'[]'::jsonb)
    from oyun.avukat_vekaletleri v where v.dava_id=p_dava)
 );
end $f$;

create or replace function public.avukat_istinaf(p_dava bigint,p_gerekce text) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); d oyun.adliye_davalar; v oyun.avukat_vekaletleri; tr text; onceki text; r jsonb; engel text;
begin
 engel:=oyun.avukat_engel(p.id);
 if engel is not null then raise exception '%',engel; end if;
 select * into d from oyun.adliye_davalar where id=p_dava;
 if d.id is null or d.durum<>'karar' or d.kesin then raise exception 'Bu karar istinafa açık değil.'; end if;
 tr:=case when d.karar='beraat' then 'davaci' else 'davali' end;
 select * into v from oyun.avukat_vekaletleri where dava_id=d.id and taraf=tr and avukat_id=p.id and aktif order by id desc limit 1;
 if v.id is null then raise exception 'Bu dosyada kararı kaybeden tarafın aktif vekili değilsin.'; end if;
 onceki:=oyun.vekil_basla(v.muvekkil,p.id);
 r:=public.adliye_istinaf(p_dava,p_gerekce);
 perform oyun.vekil_bitir(onceki);
 perform oyun.bildir(v.muvekkil,format('Av. %s, Dava #%s kararına senin adına istinaf başvurusu yaptı.',p.kad,d.id),oyun.simdi());
 return r;
end $f$;

-- ---------------------------------------------------------------- 4) Hukuki iş talepleri (dava açma, seçim itirazı, parti kapatma savunması)
create or replace function public.hukuk_is_olustur(p_tur text,p_parti bigint default null,p_hedef_tur text default null,p_hedef text default null,
 p_dava_tur text default null,p_tazminat numeric default null,p_secim bigint default null,p_pkd bigint default null,p_metin text default '',p_delil text default '')
returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); m text:=trim(coalesce(p_metin,'')); dl text:=trim(coalesce(p_delil,'')); had text; u oyun.profiller; s oyun.secimler; k oyun.pkd_dava; pa oyun.partiler; yid bigint; hp bigint;
begin
 if p_tur not in ('dava','secim_itiraz','pkd_savunma') then raise exception 'İş türü geçersiz.'; end if;
 if (select count(*) from oyun.hukuk_isleri where muvekkil=p.id and durum in ('avukat_bekliyor','vekil_atandi'))>=3 then raise exception 'Aynı anda en fazla üç açık hukuki işin olabilir.'; end if;
 if p_parti is not null then
  select * into pa from oyun.partiler where id=p_parti and not kapali;
  if pa.id is null then raise exception 'Parti bulunamadı.'; end if;
  if pa.gb is distinct from p.id and not (p_tur='pkd_savunma' and coalesce(pa.gb_vekil=p.id,false)) then raise exception 'Parti adına avukatı yalnız genel başkan tutabilir.'; end if;
 end if;
 if p_tur='dava' then
  if p_dava_tur not in ('hakaret','iftira','rusvet','yolsuzluk','usulsuzluk','dolandiricilik','diger','tazminat') then raise exception 'Dava türü geçersiz.'; end if;
  if char_length(m) not between 20 and 1600 then raise exception 'İddia 20–1600 karakter olmalı.'; end if;
  if char_length(dl)>1600 then raise exception 'Delil en fazla 1600 karakter olabilir.'; end if;
  if p_hedef_tur='oyuncu' then
   select * into u from oyun.profiller where lower(kad)=lower(trim(coalesce(p_hedef,''))) and not yasakli;
   if u.id is null then raise exception 'Davalı oyuncu bulunamadı.'; end if;
   if u.id=p.id then raise exception 'Kendinize dava açamazsınız.'; end if;
   had:=u.kad;
  elsif p_hedef_tur='parti' then
   begin hp:=p_hedef::bigint; exception when others then raise exception 'Geçersiz parti.'; end;
   select ad into had from oyun.partiler where id=hp and not kapali;
   if had is null then raise exception 'Parti bulunamadı.'; end if;
   if hp=p_parti then raise exception 'Bir parti kendisine dava açamaz.'; end if;
  elsif p_hedef_tur in ('sirket','dernek','belediye','makam','bakanlik','gazete') then
   had:=oyun.adliye_kurum_adi(p_hedef_tur,p_hedef);
   if had is null then raise exception 'Kurum bulunamadı veya faal değil.'; end if;
   if oyun.adliye_kurum_yetkili(p_hedef_tur,p_hedef,p.id) then raise exception 'Temsil ettiğiniz kuruma dava açamazsınız.'; end if;
  else raise exception 'Davalı türü geçersiz.'; end if;
  if p_dava_tur='tazminat' then
   if p_hedef_tur='parti' or p_hedef_tur='makam' then raise exception 'Tazminat partiye ya da makama karşı istenemez.'; end if;
   if p_hedef_tur='oyuncu' and p_parti is not null then raise exception 'Oyuncudan tazminatı yalnız kendi adına isteyebilirsin.'; end if;
   if p_tazminat is null or p_tazminat<1000 or p_tazminat>500000 or p_tazminat<>trunc(p_tazminat) then raise exception 'Tazminat talebi 1.000–500.000 ₺ arasında tam sayı olmalı.'; end if;
  end if;
  insert into oyun.hukuk_isleri(tur,muvekkil,parti_id,hedef_tur,hedef,hedef_ad,dava_tur,tazminat_talep,metin,delil)
  values('dava',p.id,p_parti,p_hedef_tur,case when p_hedef_tur='oyuncu' then u.kad else p_hedef end,had,p_dava_tur,case when p_dava_tur='tazminat' then p_tazminat end,m,dl) returning id into yid;
 elsif p_tur='secim_itiraz' then
  if p_parti is null then raise exception 'İtiraz eden partiyi seç.'; end if;
  select * into s from oyun.secimler where id=p_secim;
  if s.id is null or s.sonuc is null or s.sonuc_at is null or now()<s.sonuc_at then raise exception 'Yalnız sonuçlanmış seçimlere itiraz edilebilir.'; end if;
  if now()>s.sonuc_at+interval '48 hours' then raise exception '48 saatlik itiraz süresi doldu.'; end if;
  if exists(select 1 from oyun.hukuk_isleri where tur='secim_itiraz' and secim_id=s.id and parti_id=p_parti and durum in ('avukat_bekliyor','vekil_atandi')) then raise exception 'Bu seçim için bekleyen bir itiraz işiniz var.'; end if;
  if char_length(m) not between 30 and 1600 then raise exception 'İtiraz gerekçesi 30-1600 karakter olmalı.'; end if;
  if char_length(dl)>3000 then raise exception 'Deliller en fazla 3000 karakter olabilir.'; end if;
  insert into oyun.hukuk_isleri(tur,muvekkil,parti_id,secim_id,hedef_ad,metin,delil)
  values('secim_itiraz',p.id,p_parti,s.id,format('Seçim #%s · %s · %s',s.id,s.tur,s.donem),m,dl) returning id into yid;
 else
  select * into k from oyun.pkd_dava where id=p_pkd;
  if k.id is null or k.durum<>'savunma' or now()>=k.savunma_son then raise exception 'Bu parti kapatma davası savunma aşamasında değil.'; end if;
  select * into pa from oyun.partiler where id=k.parti_id;
  if p.id is distinct from pa.gb and p.id is distinct from pa.gb_vekil then raise exception 'Bu iş için avukatı davalı partinin genel başkanı tutar.'; end if;
  if char_length(m) not between 50 and 3000 then raise exception 'Savunma taslağı 50-3000 karakter olmalı.'; end if;
  insert into oyun.hukuk_isleri(tur,muvekkil,parti_id,pkd_id,hedef_ad,metin)
  values('pkd_savunma',p.id,pa.id,k.id,'Parti kapatma davası #'||k.id,m) returning id into yid;
 end if;
 perform oyun.bildir(b.user_id,format('Yeni hukuki iş #%s avukat arıyor (%s). Türkiye Barosu > Davalar bölümünden teklif verebilirsin.',yid,
   case p_tur when 'dava' then 'dava açılışı' when 'secim_itiraz' then 'seçim itirazı' else 'parti kapatma savunması' end),oyun.simdi())
  from oyun.baro_uyeleri b where b.durum='aktif' and b.user_id<>p.id and oyun.avukat_mi(b.user_id);
 return jsonb_build_object('tamam',true,'id',yid);
end $f$;

create or replace function public.hukuk_is_davet(p_is bigint,p_kad text) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); h oyun.hukuk_isleri; u uuid;
begin
 select * into h from oyun.hukuk_isleri where id=p_is;
 if h.id is null or h.muvekkil<>p.id or h.durum<>'avukat_bekliyor' then raise exception 'Avukat arayan bir işin bulunamadı.'; end if;
 select id into u from oyun.profiller where lower(kad)=lower(trim(coalesce(p_kad,''))) and not yasakli;
 if u is null or not oyun.avukat_mi(u) then raise exception 'Mesleği icra edebilen böyle bir avukat bulunamadı.'; end if;
 perform oyun.bildir(u,format('%s seni hukuki iş #%s için davet etti (%s). Türkiye Barosu > Davalar bölümünden teklif verebilirsin.',p.kad,h.id,coalesce(h.hedef_ad,'')),oyun.simdi());
 return jsonb_build_object('tamam',true);
end $f$;

create or replace function public.hukuk_is_teklif_ver(p_is bigint,p_tutar numeric,p_prim numeric default 0,p_aciklama text default '') returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); h oyun.hukuk_isleri; engel text:=oyun.avukat_engel(p.id); tid bigint;
begin
 if engel is not null then raise exception '%',engel; end if;
 select * into h from oyun.hukuk_isleri where id=p_is;
 if h.id is null or h.durum<>'avukat_bekliyor' then raise exception 'Bu iş artık avukat aramıyor.'; end if;
 if h.muvekkil=p.id then raise exception 'Kendi işine avukat olamazsın.'; end if;
 if exists(select 1 from oyun.mahkeme_uye where user_id=p.id) then raise exception 'Yargıç avukatlık yapamaz.'; end if;
 if h.tur='dava' and ((h.hedef_tur='oyuncu' and lower(h.hedef)=lower(p.kad))
   or (h.hedef_tur='parti' and exists(select 1 from oyun.partiler pa where pa.id::text=h.hedef and pa.gb=p.id))
   or (h.hedef_tur in ('sirket','dernek','belediye','makam','bakanlik','gazete') and oyun.adliye_kurum_yetkili(h.hedef_tur,h.hedef,p.id)))
  then raise exception 'Davalı tarafta olduğun işe avukat olamazsın.'; end if;
 if p_tutar is null or p_tutar<0 or p_tutar>1000000000000 then raise exception 'Ücret geçersiz.'; end if;
 if p_prim is null or p_prim<0 or p_prim>25 then raise exception 'Başarı primi %%0 ile %%25 arasında olmalı (Avukatlık Kanunu m.164).'; end if;
 if p_prim>0 and coalesce(h.dava_tur,'')<>'tazminat' then raise exception 'Başarı primi yalnız tazminat davalarında kararlaştırılabilir.'; end if;
 if exists(select 1 from oyun.hukuk_is_teklifleri where is_id=h.id and avukat_id=p.id and durum='bekliyor') then raise exception 'Bu işe bekleyen bir teklifin zaten var.'; end if;
 insert into oyun.hukuk_is_teklifleri(is_id,avukat_id,tutar,prim,aciklama) values(h.id,p.id,round(p_tutar),p_prim,left(trim(coalesce(p_aciklama,'')),500)) returning id into tid;
 perform oyun.bildir(h.muvekkil,format('Hukuki iş #%s için Av. %s teklif verdi: %s ₺%s. Adliye > Hukuki işlerim.',h.id,p.kad,oyun.tl(round(p_tutar)),case when p_prim>0 then format(', başarı primi %%%s',p_prim) else '' end),oyun.simdi());
 return jsonb_build_object('tamam',true,'id',tid);
end $f$;

create or replace function public.hukuk_is_teklif_karar(p_teklif bigint,p_kabul boolean) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); t oyun.hukuk_is_teklifleri; h oyun.hukuk_isleri;
begin
 select * into t from oyun.hukuk_is_teklifleri where id=p_teklif for update;
 if t.id is null or t.durum<>'bekliyor' then raise exception 'Teklif beklemede değil.'; end if;
 select * into h from oyun.hukuk_isleri where id=t.is_id for update;
 if h.muvekkil<>p.id then raise exception 'Bu işin müvekkili değilsin.'; end if;
 if h.durum<>'avukat_bekliyor' then raise exception 'Bu işe zaten avukat atandı.'; end if;
 if not p_kabul then
  update oyun.hukuk_is_teklifleri set durum='ret' where id=t.id;
  perform oyun.bildir(t.avukat_id,format('Hukuki iş #%s teklifin reddedildi.',h.id),oyun.simdi());
  return jsonb_build_object('durum','ret');
 end if;
 if not oyun.avukat_mi(t.avukat_id) then raise exception 'Avukat şu anda mesleği icra edemiyor.'; end if;
 if t.tutar>0 then perform oyun.para_islem(p.id,-t.tutar,'adliye','Hukuki iş #'||h.id||' avukatlık ücreti (iş sunulana kadar emanette)',oyun.simdi()); end if;
 update oyun.hukuk_isleri set durum='vekil_atandi',avukat_id=t.avukat_id,ucret=t.tutar,prim=t.prim,emanet=t.tutar,atama_at=now() where id=h.id;
 update oyun.hukuk_is_teklifleri set durum='kabul' where id=t.id;
 update oyun.hukuk_is_teklifleri set durum='iptal' where is_id=h.id and id<>t.id and durum='bekliyor';
 perform oyun.bildir(t.avukat_id,format('Hukuki iş #%s teklifin kabul edildi. Dilekçeyi hazırlayıp mahkemeye sun; ücretin sunumda emanetten ödenir.',h.id),oyun.simdi());
 return jsonb_build_object('durum','kabul');
end $f$;

create or replace function public.hukuk_is_iptal(p_is bigint) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); h oyun.hukuk_isleri;
begin
 select * into h from oyun.hukuk_isleri where id=p_is for update;
 if h.id is null or h.durum not in ('avukat_bekliyor','vekil_atandi') then raise exception 'İş iptal edilebilir durumda değil.'; end if;
 if h.muvekkil=p.id then
  if h.emanet>0 then perform oyun.para_islem(h.muvekkil,h.emanet,'adliye','Hukuki iş #'||h.id||' emanet iadesi',oyun.simdi()); end if;
  update oyun.hukuk_isleri set durum='iptal',emanet=0,iptal_at=now() where id=h.id;
  update oyun.hukuk_is_teklifleri set durum='iptal' where is_id=h.id and durum='bekliyor';
  if h.avukat_id is not null then perform oyun.bildir(h.avukat_id,format('Müvekkil hukuki iş #%s talebini geri çekti.',h.id),oyun.simdi()); end if;
  return jsonb_build_object('durum','iptal','iade',h.emanet);
 elsif h.avukat_id=p.id and h.durum='vekil_atandi' then
  if h.emanet>0 then perform oyun.para_islem(h.muvekkil,h.emanet,'adliye','Hukuki iş #'||h.id||' emanet iadesi (avukat çekildi)',oyun.simdi()); end if;
  update oyun.hukuk_isleri set durum='avukat_bekliyor',avukat_id=null,ucret=0,prim=0,emanet=0,atama_at=null where id=h.id;
  perform oyun.bildir(h.muvekkil,format('Av. %s hukuki iş #%s vekâletinden çekildi; ücretin iade edildi, yeni avukat arayabilirsin.',p.kad,h.id),oyun.simdi());
  return jsonb_build_object('durum','avukat_bekliyor','iade',h.emanet);
 end if;
 raise exception 'Bu işte iptal yetkin yok.';
end $f$;

create or replace function public.hukuk_is_sun(p_is bigint,p_metin text default null,p_delil text default null) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); h oyun.hukuk_isleri; engel text:=oyun.avukat_engel(p.id); m text; dl text; onceki text; r jsonb; yeni bigint; tid bigint; v_harc numeric;
begin
 if engel is not null then raise exception '%',engel; end if;
 select * into h from oyun.hukuk_isleri where id=p_is for update;
 if h.id is null or h.avukat_id is distinct from p.id or h.durum<>'vekil_atandi' then raise exception 'Bu işin vekili değilsin ya da iş sunulmaya hazır değil.'; end if;
 m:=coalesce(nullif(trim(coalesce(p_metin,'')),''),h.metin);
 dl:=coalesce(p_delil,h.delil);
 if h.tur='dava' then
  v_harc:=coalesce((select ma.harc from oyun.mahkeme_ayar ma),0);
  if v_harc>0 and coalesce((select c.para from oyun.cuzdan c where c.user_id=h.muvekkil),0)<v_harc then
   raise exception 'Müvekkilin cüzdanında dava harcı (% ₺) yok; müvekkiline haber ver.',oyun.tl(v_harc);
  end if;
  onceki:=oyun.vekil_basla(h.muvekkil,p.id);
  if h.hedef_tur in ('sirket','dernek','belediye','makam','bakanlik','gazete') then
   r:=public.adliye_kurum_dava_ac(h.hedef_tur,h.hedef,h.dava_tur,m,dl,h.parti_id,h.tazminat_talep);
  elsif h.dava_tur='tazminat' then
   r:=public.adliye_tazminat_davasi_ac(h.hedef,h.tazminat_talep,m,dl);
  else
   r:=public.adliye_dava_ac(h.hedef_tur,h.hedef,h.dava_tur,m,dl,h.parti_id);
  end if;
  perform oyun.vekil_bitir(onceki);
  yeni:=(r->>'id')::bigint;
  insert into oyun.avukat_teklifleri(dava_id,avukat_id,taraf,tutar,prim_orani,aciklama,durum,kabul_at)
  values(yeni,p.id,'davaci',h.ucret,h.prim,'Hukuki iş #'||h.id||' ile dava açılışı','kabul',now()) returning id into tid;
  insert into oyun.avukat_vekaletleri(teklif_id,dava_id,avukat_id,muvekkil,taraf,ucret,prim_orani) values(tid,yeni,p.id,h.muvekkil,'davaci',h.ucret,h.prim);
 elsif h.tur='secim_itiraz' then
  onceki:=oyun.vekil_basla(h.muvekkil,p.id);
  r:=public.adliye_secim_itiraz_ac(h.secim_id,h.parti_id,m,dl);
  perform oyun.vekil_bitir(onceki);
 else
  onceki:=oyun.vekil_basla(h.muvekkil,p.id);
  r:=public.parti_kapatma_savunma(h.pkd_id,m);
  perform oyun.vekil_bitir(onceki);
 end if;
 if h.emanet>0 then perform oyun.para_islem(p.id,h.emanet,'adliye','Hukuki iş #'||h.id||' avukatlık ücreti',oyun.simdi()); end if;
 update oyun.hukuk_isleri set durum='sunuldu',sunum_at=now(),emanet=0,dava_id=yeni,metin=m,delil=dl where id=h.id;
 perform oyun.bildir(h.muvekkil,case when yeni is not null then format('Av. %s davanı açtı: Adliye #%s. Dosyada vekilin olarak görünüyor.',p.kad,yeni)
   else format('Av. %s hukuki iş #%s kapsamında başvurunu mahkemeye sundu.',p.kad,h.id) end,oyun.simdi());
 return jsonb_build_object('tamam',true,'dava_id',yeni,'sonuc',r);
end $f$;

create or replace function oyun.hukuk_is_json(h oyun.hukuk_isleri,ben uuid) returns jsonb language sql stable set search_path='' as $f$
 select jsonb_build_object('id',h.id,'tur',h.tur,'muvekkil',oyun.kad(h.muvekkil),'parti',(select pa.ad from oyun.partiler pa where pa.id=h.parti_id),
  'hedef_tur',h.hedef_tur,'hedef_ad',h.hedef_ad,'dava_tur',h.dava_tur,'tazminat',h.tazminat_talep,'metin',h.metin,'delil',h.delil,'durum',h.durum,
  'avukat',oyun.kad(h.avukat_id),'ucret',h.ucret,'prim',h.prim,'emanet',h.emanet,'dava_id',h.dava_id,'olusturma',h.olusturma,'sunum_at',h.sunum_at,
  'muvekkilim',h.muvekkil=ben,'vekilim',h.avukat_id=ben,
  'teklifler',(select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'avukat',oyun.kad(t.avukat_id),'tutar',t.tutar,'prim',t.prim,'aciklama',t.aciklama,'durum',t.durum,'benim',t.avukat_id=ben) order by t.id desc),'[]'::jsonb)
    from oyun.hukuk_is_teklifleri t where t.is_id=h.id and (h.muvekkil=ben or t.avukat_id=ben) and t.durum in ('bekliyor','kabul')),
  'teklif_sayi',(select count(*) from oyun.hukuk_is_teklifleri t where t.is_id=h.id and t.durum='bekliyor'))
$f$;

create or replace function public.hukuk_islerim() returns jsonb language plpgsql stable security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); avk boolean:=oyun.baro_uyesi(p.id);
begin
 return jsonb_build_object(
  'avukat_miyim',oyun.avukat_mi(p.id),
  'benim',(select coalesce(jsonb_agg(oyun.hukuk_is_json(h,p.id) order by h.id desc),'[]'::jsonb) from oyun.hukuk_isleri h
    where h.id in (select x.id from oyun.hukuk_isleri x where x.muvekkil=p.id and (x.durum in ('avukat_bekliyor','vekil_atandi') or coalesce(x.sunum_at,x.iptal_at,x.olusturma)>now()-interval '3 days') order by x.id desc limit 20)),
  'ustlendigim',(select coalesce(jsonb_agg(oyun.hukuk_is_json(h,p.id) order by h.id desc),'[]'::jsonb) from oyun.hukuk_isleri h
    where h.id in (select x.id from oyun.hukuk_isleri x where x.avukat_id=p.id and (x.durum='vekil_atandi' or x.sunum_at>now()-interval '3 days') order by x.id desc limit 20)),
  'acik',case when avk or coalesce(p.yonetici,false) then (select coalesce(jsonb_agg(oyun.hukuk_is_json(h,p.id) order by h.id desc),'[]'::jsonb) from oyun.hukuk_isleri h
    where h.id in (select x.id from oyun.hukuk_isleri x where x.durum='avukat_bekliyor' order by x.id desc limit 40)) else '[]'::jsonb end
 );
end $f$;

-- ---------------------------------------------------------------- 5) Parti Sözcüsü: resmî açıklama makamı
create or replace function public.parti_aciklama_yap(p_parti bigint,p_baslik text,p_metin text) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); pa oyun.partiler; rol text; b text:=trim(coalesce(p_baslik,'')); m text:=trim(coalesce(p_metin,'')); yid bigint; t timestamptz:=oyun.simdi();
begin
 select * into pa from oyun.partiler where id=p_parti and not kapali;
 if pa.id is null then raise exception 'Parti bulunamadı.'; end if;
 if exists(select 1 from oyun.parti_sozcu s where s.parti_id=pa.id and s.user_id=p.id) and p.parti_id=pa.id then rol:='sozcu';
 elsif pa.gb=p.id then rol:='gb';
 else raise exception 'Parti adına resmî açıklamayı yalnız parti sözcüsü ya da genel başkan yapabilir.'; end if;
 if coalesce(p.susturma_bitis,'-infinity'::timestamptz)>t or coalesce(p.adliye_susturma_bitis,'-infinity'::timestamptz)>t then raise exception 'Susturma cezan sürerken açıklama yapamazsın.'; end if;
 if char_length(b) not between 3 and 120 then raise exception 'Başlık 3-120 karakter olmalı.'; end if;
 if char_length(m) not between 10 and 2000 then raise exception 'Açıklama 10-2000 karakter olmalı.'; end if;
 if m ~* '(https?://|www\.|t\.me/)' then raise exception 'Açıklamalarda bağlantı kullanılamaz.'; end if;
 if exists(select 1 from oyun.parti_aciklamalar where parti_id=pa.id and not silindi and zaman>now()-interval '15 minutes') then raise exception 'Parti adına yeni açıklama için 15 dakika bekleyin.'; end if;
 insert into oyun.parti_aciklamalar(parti_id,yazar,rol,baslik,metin) values(pa.id,p.id,rol,b,m) returning id into yid;
 insert into oyun.akis(user_id,metin,zaman,il_id,parti_id)
 values(p.id,left('📢 '||pa.kisa||' resmî açıklaması — '||b||': '||m,280),t,p.il_id,pa.id);
 perform oyun.bildir(u.id,format('%s resmî açıklaması: %s',pa.kisa,left(b,100)),t)
  from oyun.profiller u where u.parti_id=pa.id and u.id<>p.id and not u.yasakli;
 return jsonb_build_object('tamam',true,'id',yid);
end $f$;

create or replace function public.parti_aciklamalari(p_parti bigint) returns jsonb language plpgsql stable security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); pa oyun.partiler; soz uuid;
begin
 select * into pa from oyun.partiler where id=p_parti;
 if pa.id is null then raise exception 'Parti bulunamadı.'; end if;
 select s.user_id into soz from oyun.parti_sozcu s where s.parti_id=pa.id;
 return jsonb_build_object(
  'sozcu',oyun.kad(soz),'gb_miyim',pa.gb=p.id,
  'yazabilirim',not pa.kapali and (pa.gb=p.id or (soz=p.id and p.parti_id=pa.id)),
  'aciklamalar',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'yazar',oyun.kad(a.yazar),'rol',a.rol,'baslik',a.baslik,'metin',a.metin,'zaman',a.zaman,
      'silebilirim',a.yazar=p.id or pa.gb=p.id) order by a.id desc),'[]'::jsonb)
    from (select * from oyun.parti_aciklamalar where parti_id=pa.id and not silindi order by id desc limit 20) a)
 );
end $f$;

create or replace function public.parti_aciklama_sil(p_id bigint) returns jsonb language plpgsql security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); a oyun.parti_aciklamalar;
begin
 select * into a from oyun.parti_aciklamalar where id=p_id and not silindi for update;
 if a.id is null then raise exception 'Açıklama bulunamadı.'; end if;
 if not (a.yazar=p.id or exists(select 1 from oyun.partiler pa where pa.id=a.parti_id and pa.gb=p.id)) then raise exception 'Bu açıklamayı kaldırma yetkin yok.'; end if;
 update oyun.parti_aciklamalar set silindi=true where id=a.id;
 return jsonb_build_object('tamam',true);
end $f$;

-- ---------------------------------------------------------------- 6) Dosya bilgisi (arayüz için)
create or replace function public.baro_dava_bilgi(p_dava bigint) returns jsonb language plpgsql stable security definer set search_path='' as $f$
declare p oyun.profiller:=oyun.profilim(); d oyun.adliye_davalar; tr text; b oyun.baro; taraf_mi boolean; kayb text; ist boolean;
begin
 select * into d from oyun.adliye_davalar where id=p_dava;
 if d.id is null then raise exception 'Dava bulunamadı.'; end if;
 select * into b from oyun.baro where id=1;
 tr:=case when d.davaci=p.id and d.davaci_parti is null then 'davaci' when d.davali=p.id then 'davali' end;
 taraf_mi:=oyun.dava_muvekkil_mi(d,'davaci',p.id) or oyun.dava_muvekkil_mi(d,'davali',p.id) or exists(select 1 from oyun.avukat_vekaletleri v where v.dava_id=d.id and v.muvekkil=p.id);
 kayb:=case when d.durum='karar' then case when d.karar='beraat' then 'davaci' else 'davali' end end;
 ist:=d.durum='karar' and not d.kesin and now()<=coalesce(d.istinaf_son,now()) and not exists(select 1 from oyun.adliye_istinaf i where i.dava_id=d.id);
 return jsonb_build_object(
  'benim_taraf',tr,
  'vekilim_var',tr is not null and exists(select 1 from oyun.avukat_vekaletleri v where v.dava_id=d.id and v.taraf=tr and v.aktif),
  'dava_acik',d.durum='acik',
  'zorunlu',oyun.avukat_zorunlu_mu(d.acilis),
  'ilgili_miyim',exists(select 1 from oyun.adliye_ek_taraf e where e.dava_id=d.id and e.user_id=p.id),
  'muvekkil_taraf',case when oyun.dava_muvekkil_mi(d,'davaci',p.id) then 'davaci' when oyun.dava_muvekkil_mi(d,'davali',p.id) then 'davali' end,
  'istinaf_vekili',ist and exists(select 1 from oyun.avukat_vekaletleri v where v.dava_id=d.id and v.taraf=kayb and v.avukat_id=p.id and v.aktif),
  'istinaf_acik',ist,'kaybeden',kayb,'istinaf_son',d.istinaf_son,
  'sinir',b.adli_yardim_sinir,
  'cuzdan',(select c.para from oyun.cuzdan c where c.user_id=p.id),
  'baro_uye_sayi',(select count(*) from oyun.baro_uyeleri where durum='aktif'),
  'talepler',(select coalesce(jsonb_agg(jsonb_build_object('id',y.id,'taraf',y.taraf,'durum',y.durum,'avukat',oyun.kad(y.avukat_id),'karar_gerekce',y.karar_gerekce,'zaman',y.zaman) order by y.id desc),'[]'::jsonb)
     from oyun.baro_adli_yardim y where y.dava_id=d.id and (y.talep_eden=p.id or oyun.baro_uyesi(p.id))),
  'sikayet_edilebilir',case when taraf_mi then
     (select coalesce(jsonb_agg(distinct jsonb_build_object('id',v.avukat_id,'kad',oyun.kad(v.avukat_id))),'[]'::jsonb) from oyun.avukat_vekaletleri v where v.dava_id=d.id and v.avukat_id<>p.id)
     else '[]'::jsonb end
 );
end $f$;

-- ---------------------------------------------------------------- 7) Yetkiler
do $grants$
declare f record;
begin
 for f in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.proname in ('adliye_dava_ac','adliye_kurum_dava_ac','adliye_beyan_ver','adliye_temsil_yetkisi','adliye_secim_itiraz_ac','parti_kapatma_savunma','adliye_sozcu_ata',
   'avukat_teklif_ver','avukat_karsi_teklif','avukat_teklif_karar','avukat_dava_durum','avukat_istinaf','hukuk_is_olustur','hukuk_is_davet','hukuk_is_teklif_ver','hukuk_is_teklif_karar',
   'hukuk_is_iptal','hukuk_is_sun','hukuk_islerim','parti_aciklama_yap','parti_aciklamalari','parti_aciklama_sil','baro_dava_bilgi')
 loop execute format('revoke all on function %s from public, anon; grant execute on function %s to authenticated',f.sig,f.sig); end loop;
 for f in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='oyun' and p.proname in ('avukat_zorunlu_mu','vekil_islem_mi','vekil_basla','vekil_bitir','dava_muvekkil_mi','hukuk_is_json')
 loop execute format('revoke all on function %s from public, anon, authenticated',f.sig); end loop;
end $grants$;
-- Parti kasası yalnızca parti amaçları için kullanılabilir. Mevcut veri değişmez.
create table if not exists oyun.parti_yatirim_pozisyon (
  parti_id bigint not null references oyun.partiler(id),
  kod text not null references oyun.piyasa_varlik(kod),
  miktar numeric(28,8) not null default 0 check (miktar >= 0),
  maliyet numeric not null default 0 check (maliyet >= 0),
  primary key (parti_id,kod)
);
create table if not exists oyun.parti_yatirim_islem (
  id bigint generated by default as identity primary key,
  parti_id bigint not null references oyun.partiler(id),
  yapan uuid not null,
  kod text not null references oyun.piyasa_varlik(kod),
  yon text not null check (yon in ('al','sat')),
  miktar numeric(28,8) not null check (miktar > 0),
  fiyat numeric not null check (fiyat > 0),
  brut numeric not null check (brut >= 100),
  komisyon numeric not null check (komisyon >= 0),
  zaman timestamptz not null default now()
);
create index if not exists parti_yatirim_islem_parti_idx on oyun.parti_yatirim_islem(parti_id,zaman desc);
create table if not exists oyun.parti_kampanya_gider (
  id bigint generated by default as identity primary key,
  parti_id bigint not null references oyun.partiler(id),
  yapan uuid not null,
  amac text not null check (amac in ('genel_secim','yerel_secim','cumhurbaskanligi','rutin')),
  kanal text not null check (kanal in ('reklam','tanitim')),
  secim_id bigint references oyun.secimler(id),
  il_id smallint references oyun.iller(id),
  baslik text not null,
  tutar numeric not null check (tutar >= 100),
  zaman timestamptz not null default now()
);
create index if not exists parti_kampanya_gider_parti_idx on oyun.parti_kampanya_gider(parti_id,zaman desc);
alter table oyun.parti_yatirim_pozisyon enable row level security;
alter table oyun.parti_yatirim_islem enable row level security;
alter table oyun.parti_kampanya_gider enable row level security;
-- Tabloya istemciden doğrudan yazma izni yok; yalnızca kimlik denetimli RPC fonksiyonları işlem yapar.
revoke all on oyun.parti_yatirim_pozisyon, oyun.parti_yatirim_islem, oyun.parti_kampanya_gider from anon, authenticated;

-- Önceki sürümdeki parti kasasından üyelerin kişisel cüzdanlarına para gönderme açığını kesin kapat.
create or replace function public.parti_destek(p_kad text, p_miktar numeric)
returns jsonb language plpgsql security definer set search_path to ''
as $$
begin
  raise exception 'Parti kasasından kişisel cüzdana ödeme yapılamaz. Seçim kampanyası, miting, reklam, kurum bağışı veya parti adına yatırım kullanın.';
end $$;
revoke all on function public.parti_destek(text,numeric) from public,anon;
grant execute on function public.parti_destek(text,numeric) to authenticated;

create or replace function public.parti_finans_durum(p_parti bigint)
returns jsonb language plpgsql security definer set search_path to ''
as $$
declare
  u uuid := auth.uid();
  pa oyun.partiler;
  yetki boolean;
begin
  if u is null or not exists(select 1 from oyun.profiller where id=u) then raise exception 'Önce giriş yapmalısın.'; end if;
  select * into pa from oyun.partiler where id=p_parti;
  if pa.id is null then raise exception 'Parti bulunamadı.'; end if;
  yetki := not pa.kapali and oyun.parti_gorevli(u,array['mali'])=pa.id;
  return jsonb_build_object(
    'parti',pa.ad, 'kasa',round(pa.kasa), 'yetkili',yetki,
    'portfoy',coalesce((select jsonb_agg(jsonb_build_object(
       'kod',v.kod,'ad',v.ad,'sinif',v.sinif,'fiyat',v.fiyat,
       'miktar',coalesce(pos.miktar,0),'maliyet',coalesce(pos.maliyet,0),
       'deger',round(coalesce(pos.miktar,0)*v.fiyat,2)) order by v.sinif,v.kod)
       from oyun.piyasa_varlik v
       left join oyun.parti_yatirim_pozisyon pos on pos.parti_id=pa.id and pos.kod=v.kod
       where v.aktif or coalesce(pos.miktar,0)>0),'[]'::jsonb),
    'yatirim_degeri',coalesce((select round(sum(p.miktar*v.fiyat),2)
       from oyun.parti_yatirim_pozisyon p join oyun.piyasa_varlik v on v.kod=p.kod
       where p.parti_id=pa.id),0),
    'hareketler',coalesce((select jsonb_agg(jsonb_build_object('zaman',h.zaman,'aciklama',h.aciklama,'tutar',h.tutar,'tur',h.tur)
       order by h.zaman desc,h.id desc)
       from (select * from oyun.parti_hareket where parti_id=pa.id order by zaman desc,id desc limit 30) h),'[]'::jsonb),
    'dernekler',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'ad',d.ad) order by d.ad)
       from oyun.dernekler d where not d.kapali),'[]'::jsonb),
    'medya',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'ad',s.ad,'sektor',s.sektor) order by s.ad)
       from oyun.sirketler s where s.aktif and s.sektor in ('medya','ajans')),'[]'::jsonb),
    'gazeteler',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'ad',g.ad) order by g.ad)
       from oyun.oyuncu_gazeteleri g where g.aktif),'[]'::jsonb));
end $$;

create or replace function public.parti_finans_bagis(p_hedef_tur text, p_hedef_id bigint, p_tutar numeric)
returns jsonb language plpgsql security definer set search_path to ''
as $$
declare
  u uuid:=auth.uid(); pa oyun.partiler; d oyun.dernekler; s oyun.sirketler;
  g oyun.oyuncu_gazeteleri; tut numeric; hedef text; sahib uuid;
  t timestamptz:=oyun.simdi();
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  tut:=round(coalesce(p_tutar,0));
  if tut<100 or p_tutar<>trunc(p_tutar) or tut>100000000 then raise exception 'Bağış tutarı 100 - 100.000.000 ₺ arasında tam sayı olmalı.'; end if;
  select * into pa from oyun.partiler where id=oyun.parti_gorevli(u,array['mali']) and not kapali for update;
  if pa.id is null then raise exception 'Parti kasası için genel başkan veya mali işlerden sorumlu yardımcı olmalısın.'; end if;
  if p_hedef_tur='dernek' then
    select * into d from oyun.dernekler where id=p_hedef_id and not kapali for update;
    if d.id is null then raise exception 'Aktif dernek bulunamadı.'; end if;
    if d.baskan in (u,pa.gb) or d.kurucu in (u,pa.gb) then
      raise exception 'Yönettiğin veya genel başkanın yönettiği derneğe parti kasasından bağış yapılamaz.'; end if;
    hedef:=d.ad;
  elsif p_hedef_tur='medya' then
    select * into s from oyun.sirketler where id=p_hedef_id and aktif and sektor in ('medya','ajans') for update;
    if s.id is null then raise exception 'Aktif medya şirketi bulunamadı.'; end if;
    if s.kurucu in (u,pa.gb) or s.yonetici in (u,pa.gb)
      or exists(select 1 from oyun.sirket_ortaklari o where o.sirket_id=s.id and o.user_id in (u,pa.gb) and o.pay>0) then
      raise exception 'Kendine veya genel başkanın şirketine parti kasasından bağış yapılamaz.'; end if;
    hedef:=s.ad;
  elsif p_hedef_tur='gazete' then
    select * into g from oyun.oyuncu_gazeteleri where id=p_hedef_id and aktif for update;
    if g.id is null then raise exception 'Aktif gazete bulunamadı.'; end if;
    if g.sahip in (u,pa.gb) then raise exception 'Kendi gazetenize parti kasasından bağış yapılamaz.'; end if;
    hedef:=g.ad;
  else
    raise exception 'Parti yalnızca dernek, medya şirketi ve gazeteye bağış yapabilir.';
  end if;
  update oyun.partiler set kasa=kasa-tut where id=pa.id and kasa>=tut;
  if not found then raise exception 'Parti kasasında yeterli para yok.'; end if;
  if p_hedef_tur='dernek' then
    update oyun.dernekler set kasa=kasa+tut where id=d.id;
    insert into oyun.dernek_hareket(dernek_id,zaman,tutar,tur,aciklama,user_id)
       values(d.id,t,tut,'bagis',pa.ad||' tarafından kurumsal bağış',null);
    sahib:=d.baskan;
  elsif p_hedef_tur='medya' then
    update oyun.sirketler set kasa=kasa+tut where id=s.id;
    insert into oyun.sirket_hareket(sirket_id,zaman,tutar,aciklama)
       values(s.id,t,tut,pa.ad||' tarafından kurumsal bağış');
    sahib:=oyun.sirket_sahibi(s.id);
  else
    update oyun.oyuncu_gazeteleri set kasa=kasa+tut where id=g.id;
    insert into oyun.gazete_hareket(gazete_id,zaman,tutar,tur,aciklama)
       values(g.id,t,tut,'bagis',pa.ad||' tarafından kurumsal bağış');
    sahib:=g.sahip;
  end if;
  insert into oyun.parti_hareket(parti_id,zaman,tutar,tur,aciklama)
    values(pa.id,t,-tut,'kurum_bagisi',format('%s kurumuna bağış: %s',p_hedef_tur,hedef));
  if sahib is not null and sahib<>u then
    perform oyun.bildir(sahib,format('%s, %s kuruluşuna %s ₺ bağışladı.',pa.ad,hedef,oyun.tl(tut)),t);
  end if;
  return jsonb_build_object('tamam',true,'parti',pa.id,'hedef',hedef,'tutar',tut);
end $$;

create or replace function public.parti_finans_emir(p_parti bigint,p_kod text,p_yon text,p_tutar numeric)
returns jsonb language plpgsql security definer set search_path to ''
as $$
declare
  u uuid:=auth.uid(); pa oyun.partiler; v oyun.piyasa_varlik;
  pos oyun.parti_yatirim_pozisyon; adet numeric(28,8); brut numeric; kom numeric; toplam numeric;
  t timestamptz:=oyun.simdi();
begin
  if u is null then raise exception 'Giriş gerekli.'; end if;
  if p_yon not in ('al','sat') or p_yon is null then raise exception 'Alış veya satış seç.'; end if;
  if p_tutar is null or p_tutar <> trunc(p_tutar) or p_tutar<100 or p_tutar>100000000 then
    raise exception 'İşlem tutarı 100 - 100.000.000 ₺ tam sayı olmalı.'; end if;
  perform oyun.piyasa_guncelle();
  select * into pa from oyun.partiler where id=p_parti and not kapali for update;
  if pa.id is null or oyun.parti_gorevli(u,array['mali']) is distinct from pa.id then
    raise exception 'Parti yatırımlarını yalnız genel başkan veya mali işlerden sorumlu yardımcı yapabilir.'; end if;
  select * into v from oyun.piyasa_varlik where kod=p_kod and aktif for update;
  if v.kod is null or v.fiyat<=0 then raise exception 'Varlık şu anda işleme açık değil.'; end if;
  insert into oyun.parti_yatirim_pozisyon(parti_id,kod) values(pa.id,v.kod) on conflict do nothing;
  select * into pos from oyun.parti_yatirim_pozisyon where parti_id=pa.id and kod=v.kod for update;
  brut:=p_tutar;
  adet:=trunc(brut/v.fiyat,8);
  if adet<=0 then raise exception 'Bu tutarla alınabilecek miktar yok.'; end if;
  if p_yon='al' then
    kom:=greatest(1,round(brut*0.003)); toplam:=brut+kom;
    update oyun.partiler set kasa=kasa-toplam where id=pa.id and kasa>=toplam;
    if not found then raise exception 'Parti kasasında alış bedeli ve komisyon için para yok.'; end if;
    update oyun.parti_yatirim_pozisyon set miktar=miktar+adet,maliyet=maliyet+brut
      where parti_id=pa.id and kod=v.kod;
    insert into oyun.parti_hareket(parti_id,zaman,tutar,tur,aciklama)
      values(pa.id,t,-toplam,'yatirim_al',format('%s parti portföyüne alındı (%s adet, komisyon %s ₺)',v.kod,adet,kom));
  else
    if pos.miktar<adet then raise exception 'Parti portföyünde bu satış için yeterli varlık yok.'; end if;
    brut:=round(adet*v.fiyat);
    if brut<100 then raise exception 'Satış en az 100 ₺ olmalı.'; end if;
    kom:=greatest(1,round(brut*0.003)); toplam:=brut-kom;
    update oyun.parti_yatirim_pozisyon set
      miktar=miktar-adet,
      maliyet=case when miktar-adet<0.00000001 then 0 else round(maliyet*(miktar-adet)/miktar,2) end
      where parti_id=pa.id and kod=v.kod and miktar>=adet;
    if not found then raise exception 'Parti portföyünde yeterli varlık yok.'; end if;
    update oyun.partiler set kasa=kasa+toplam where id=pa.id;
    insert into oyun.parti_hareket(parti_id,zaman,tutar,tur,aciklama)
      values(pa.id,t,toplam,'yatirim_sat',format('%s parti portföyünden satıldı (%s adet, komisyon %s ₺)',v.kod,adet,kom));
  end if;
  update oyun.ulke set hazine=hazine+kom/oyun.pazar_tl_milyar() where id=1;
  insert into oyun.parti_yatirim_islem(parti_id,yapan,kod,yon,miktar,fiyat,brut,komisyon,zaman)
    values(pa.id,u,v.kod,p_yon,adet,v.fiyat,brut,kom,t);
  return jsonb_build_object('tamam',true,'yon',p_yon,'kod',v.kod,'adet',adet,
    'fiyat',v.fiyat,'komisyon',kom,'net',case when p_yon='al' then -toplam else toplam end,'parti_id',pa.id);
end $$;

create or replace function public.parti_finans_kampanya(
  p_parti bigint,p_amac text,p_kanal text,p_tutar numeric,p_baslik text,p_il integer default null)
returns jsonb language plpgsql security definer set search_path to ''
as $$
declare
  u uuid:=auth.uid(); pa oyun.partiler; t timestamptz:=oyun.simdi();
  tut numeric; b text; v_secim bigint; v_il smallint;
begin
  if u is null then raise exception 'Oturum açmalısın.'; end if;
  if p_amac not in ('genel_secim','yerel_secim','cumhurbaskanligi','rutin') or p_amac is null then
    raise exception 'Geçerli bir seçim veya rutin faaliyet amacı seç.'; end if;
  if p_kanal not in ('reklam','tanitim') or p_kanal is null then raise exception 'Reklam veya tanıtım seç.'; end if;
  tut:=round(coalesce(p_tutar,0));
  if tut<100 or p_tutar<>trunc(p_tutar) or tut>100000000 then
    raise exception 'Kampanya bedeli 100 - 100.000.000 ₺ arasında tam sayı olmalı.'; end if;
  b:=oyun.metin_temizle(coalesce(p_baslik,''),120);
  if char_length(b)<10 then raise exception 'Tanıtım açıklaması en az 10 karakter olmalı.'; end if;
  if p_il is not null then
    if not exists(select 1 from oyun.iller where id=p_il) then raise exception 'Geçersiz il.'; end if;
    v_il:=p_il::smallint;
  end if;
  select * into pa from oyun.partiler where id=p_parti and not kapali for update;
  if pa.id is null or oyun.parti_gorevli(u,array['mali','tanitim','secim']) is distinct from pa.id then
    raise exception 'Partinin genel başkanı veya yetkili yardımcısı kampanya harcaması yapabilir.'; end if;
  if p_amac<>'rutin' then
    select s.id into v_secim from oyun.secimler s where s.durum='bekliyor' and s.oy_bit>t
      and s.tur=case p_amac when 'genel_secim' then 'mv' when 'yerel_secim' then 'bel' else 'cb' end
      order by s.oy_bit limit 1;
    if v_secim is null then raise exception 'Bu seçim türü için yaklaşan aktif bir seçim bulunmuyor. Rutin tanıtımı seçebilirsin.'; end if;
  end if;
  if exists(select 1 from oyun.parti_kampanya_gider where parti_id=pa.id and zaman>t-interval '15 minutes') then
    raise exception 'Parti adına yeni tanıtım duyurusu için 15 dakika beklemelisin.'; end if;
  update oyun.partiler set kasa=kasa-tut where id=pa.id and kasa>=tut;
  if not found then raise exception 'Parti kasasında yeterli para yok.'; end if;
  insert into oyun.parti_kampanya_gider(parti_id,yapan,amac,kanal,secim_id,il_id,baslik,tutar,zaman)
    values(pa.id,u,p_amac,p_kanal,v_secim,v_il,b,tut,t);
  insert into oyun.parti_hareket(parti_id,zaman,tutar,tur,aciklama)
    values(pa.id,t,-tut,'kampanya',format('%s / %s: %s',p_amac,p_kanal,b));
  perform oyun.olay('parti',format('%s seçim ve tanıtım faaliyeti: %s',pa.kisa,b),v_il,pa.id,t);
  return jsonb_build_object('tamam',true,'parti_id',pa.id,'tutar',tut,'amac',p_amac,'kanal',p_kanal);
end $$;

revoke all on function public.parti_finans_durum(bigint) from public,anon;
revoke all on function public.parti_finans_bagis(text,bigint,numeric) from public,anon;
revoke all on function public.parti_finans_emir(bigint,text,text,numeric) from public,anon;
revoke all on function public.parti_finans_kampanya(bigint,text,text,numeric,text,integer) from public,anon;
grant execute on function public.parti_finans_durum(bigint) to authenticated;
grant execute on function public.parti_finans_bagis(text,bigint,numeric) to authenticated;
grant execute on function public.parti_finans_emir(bigint,text,text,numeric) to authenticated;
grant execute on function public.parti_finans_kampanya(bigint,text,text,numeric,text,integer) to authenticated;
-- 2026-10-23: Milli Piyango ve Kazı Kazan kalıcı olarak kaldırıldı.
-- Oyuncuların geçmiş işlemleri, ikramiyeleri ve kayıtları silinmez.
-- Çekilişi yapılmamış biletlerin bedeli tam iade edilir (idempotent).
-- Eski mobil sürümlerin RPC üzerinden işlem yapması da önlenir.

-- Piyango fonksiyonunun kullandığı kilit: eşzamanlı bilet alışları kapanmadan iade başlamasın.
select pg_advisory_xact_lock(77890011);

create table if not exists oyun.piyango_iadeleri (
  bilet_id bigint primary key references oyun.piyango_bilet(id),
  user_id uuid not null references auth.users(id),
  tutar numeric not null check (tutar >= 0),
  iade_at timestamptz not null default now()
);
alter table oyun.piyango_iadeleri enable row level security;
revoke all on oyun.piyango_iadeleri from public, anon, authenticated;
alter table oyun.piyango_donem add column if not exists iptal_edildi boolean not null default false;

-- İşlev imzalarını koru: yayımlanmış eski uygulamalar hata alır, cüzdanlara dokunmaz.
create or replace function public.piyango_bilet_al(p_adet integer default 1)
returns jsonb language plpgsql security definer
set search_path = 'oyun','public','pg_temp' as $$
begin
  raise exception 'Milli Piyango oyundan kaldırıldı. Bekleyen bilet ücretleri iade edildi.';
end $$;

create or replace function public.kazikazan_oyna()
returns jsonb language plpgsql security definer
set search_path = 'oyun','public','pg_temp' as $$
begin
  raise exception 'Kazı Kazan oyundan kaldırıldı.';
end $$;

create or replace function public.piyango_durum()
returns jsonb language plpgsql security definer
set search_path = 'oyun','public','pg_temp' as $$
begin
  raise exception 'Milli Piyango oyundan kaldırıldı. Bekleyen bilet ücretleri iade edildi.';
end $$;

create or replace function public.kazikazan_durum()
returns jsonb language plpgsql security definer
set search_path = 'oyun','public','pg_temp' as $$
begin
  raise exception 'Kazı Kazan oyundan kaldırıldı.';
end $$;

-- Haftalık çekilişleri ve yeni dönem açılışlarını durdur, mevcut dönemi sakla.
create or replace function oyun.piyango_guncelle()
returns bigint language plpgsql security definer
set search_path = 'oyun','public','pg_temp' as $$
begin
  return (select id from oyun.piyango_donem order by id desc limit 1);
end $$;
revoke all on function oyun.piyango_guncelle() from public, anon, authenticated;

-- Açık dönemleri iptal et, her bilet için tekil iade kayıtlarını tut.
update oyun.piyango_donem set iptal_edildi = true
where not cekildi and not iptal_edildi;

do $$
declare
  kisi record;
  iade numeric;
  adet integer;
begin
  for kisi in
    select distinct b.user_id
    from oyun.piyango_bilet b
    join oyun.piyango_donem d on d.id = b.donem_id
    where d.iptal_edildi and not d.cekildi
  loop
    with yeni as (
      insert into oyun.piyango_iadeleri (bilet_id, user_id, tutar)
      select b.id, b.user_id, b.bedel
      from oyun.piyango_bilet b
      join oyun.piyango_donem d on d.id = b.donem_id
      where d.iptal_edildi and not d.cekildi and b.user_id = kisi.user_id
      on conflict (bilet_id) do nothing
      returning tutar
    )
    select coalesce(sum(tutar),0), count(*)::integer into iade, adet from yeni;
    if iade > 0 then
      perform oyun.para_islem(kisi.user_id, iade, 'piyango',
        format('Milli Piyango kaldırıldı: %s biletin %s TL iadesi', adet, iade), now());
      perform oyun.bildir(kisi.user_id,
        format('Milli Piyango kaldırıldı. %s biletinin toplam %s TL bedeli cüzdanına iade edildi.',
          adet, oyun.tl(iade)), now());
    end if;
  end loop;
end $$;
-- 25.10.2026: banka hesaplari ve sirket kâr tercihleri (yalnizca oturum sahibi).
create or replace function public.sirket_kar_tercihleri()
returns jsonb language sql stable security definer set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'sirket_id', o.sirket_id,
    'kar_kasada', o.kar_kasada
  ) order by o.sirket_id), '[]'::jsonb)
  from oyun.sirket_ortaklari o
  join oyun.sirketler s on s.id=o.sirket_id and s.aktif
  where o.user_id=auth.uid()
$$;
revoke all on function public.sirket_kar_tercihleri() from public, anon;
grant execute on function public.sirket_kar_tercihleri() to authenticated;

create or replace function public.internet_banka_hesaplarim()
returns jsonb language sql stable security definer set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'banka_id', h.banka_id,
    'ad', s.ad,
    'acilis', h.acilis
  ) order by s.ad), '[]'::jsonb)
  from oyun.oyb_hesap h
  join oyun.sirketler s on s.id=h.banka_id and s.aktif and s.sektor='banka'
  where h.user_id=auth.uid() and h.kapanis is null
$$;
revoke all on function public.internet_banka_hesaplarim() from public, anon;
grant execute on function public.internet_banka_hesaplarim() to authenticated;
-- =====================================================================
--  135 · BANKACILIK 2.0 (25.10.2026)
--  1) Kasa gizliliği: şirket, banka, dernek ve gazete kasaları sahibi /
--     yöneticisi dışında görünmez; sahibi isterse herkese (dernekte
--     yalnız üyelere) açar. Herkese açık 45+ ekran fonksiyonu
--     oyun.kasa_goster() ile yamalanır (iki kez çalıştırmak güvenli).
--  2) Banka bilançosu: vadesiz mevduat artık bankanın borcu sayılır
--     (önceden kâr payı / kredi kapasitesi hesabında unutuluyordu).
--  3) Banka Genel Müdürlüğü: tek ekranda bilanço, oranlar, güven notu,
--     gelir tablosu, başvurular, ürün ve risk ayarları, DİBS (devlet
--     tahvili), kâr payı (stopajlı), sermaye artır / azalt, emniyet payı,
--     banka rengi ve sloganı.
--  4) Mobil Şube: müşterinin tüm hesap, kart, kredi ve birikimleri tek
--     sorguda; FAST ile her bankaya (Devlet Bankası dahil) para gönderme
--     ve hesaplar arası aktarım.
--  5) Devlet Bankası kredi kartı ödemelerindeki Hazine birim hatası.
--  Oyuncu bakiyelerine dokunmaz; yalnız yeni tablo / fonksiyon ekler.
-- =====================================================================

-- ---------------------------------------------------------------------
-- A. TABLOLAR
-- ---------------------------------------------------------------------
create table if not exists oyun.kasa_gizlilik(
  tur         text not null check (tur in ('sirket','dernek','gazete')),
  kimlik      bigint not null,
  gorunurluk  text not null default 'gizli' check (gorunurluk in ('gizli','uyeler','herkes')),
  guncelleyen uuid,
  guncelleme  timestamptz not null default now(),
  primary key (tur, kimlik)
);
alter table oyun.kasa_gizlilik enable row level security;

create table if not exists oyun.banka_politika(
  banka_id     bigint primary key references oyun.sirketler(id),
  emniyet_payi numeric not null default 0 check (emniyet_payi >= 0 and emniyet_payi <= 100000000),
  risk_profili text not null default 'ozel' check (risk_profili in ('ozel','temkinli','dengeli','atak','manuel')),
  renk         text not null default 'lacivert'
               check (renk in ('lacivert','bordo','zumrut','turuncu','mor','altin','turkuaz','gece','kirmizi','gumus')),
  slogan       text check (slogan is null or char_length(slogan) <= 80),
  guncelleme   timestamptz not null default now()
);
alter table oyun.banka_politika enable row level security;

create table if not exists oyun.banka_dibs(
  id       bigserial primary key,
  banka_id bigint not null references oyun.sirketler(id),
  tutar    numeric(18,2) not null check (tutar > 0),
  gun      smallint not null check (gun in (1,7,30)),
  oran     numeric(9,4) not null check (oran >= 0),
  acilis   timestamptz not null,
  vade     timestamptz not null,
  durum    text not null default 'acik' check (durum in ('acik','odendi','bozuldu')),
  odenen   numeric(18,2),
  kapanis  timestamptz,
  alan     uuid
);
create index if not exists banka_dibs_banka_durum on oyun.banka_dibs(banka_id, durum);
create index if not exists banka_dibs_vade on oyun.banka_dibs(vade) where durum = 'acik';
alter table oyun.banka_dibs enable row level security;

create table if not exists oyun.banka_temettu(
  id       bigserial primary key,
  banka_id bigint not null references oyun.sirketler(id),
  tur      text not null check (tur in ('temettu','sermaye_iade')),
  brut     numeric(18,2) not null default 0,
  stopaj   numeric(18,2) not null default 0,
  net      numeric(18,2) not null default 0,
  yapan    uuid,
  zaman    timestamptz not null
);
create index if not exists banka_temettu_banka on oyun.banka_temettu(banka_id, id desc);
alter table oyun.banka_temettu enable row level security;

-- FAST: Devlet Bankası ile özel bankalar arasındaki anlık transferler
create table if not exists oyun.banka_fast(
  id           bigserial primary key,
  gonderen     uuid not null,
  alici        uuid not null,
  kaynak_banka bigint,          -- null = Devlet Bankası
  hedef_banka  bigint,          -- null = Devlet Bankası
  tutar        numeric(18,2) not null check (tutar > 0),
  aciklama     text,
  zaman        timestamptz not null
);
create index if not exists banka_fast_gonderen on oyun.banka_fast(gonderen, zaman desc);
alter table oyun.banka_fast enable row level security;

-- ---------------------------------------------------------------------
-- B. YARDIMCI FONKSİYONLAR
-- ---------------------------------------------------------------------
create or replace function oyun.banka_vadesiz_toplam(p_banka bigint)
returns numeric language plpgsql stable set search_path = '' as $$
begin
  if to_regclass('oyun.ib_vadesiz') is null then return 0; end if;
  return coalesce((select sum(bakiye) from oyun.ib_vadesiz where banka_id = p_banka), 0);
end $$;

-- Kasa rakamını görmeye yetkili mi? (sahip / ortak / yönetici)
create or replace function oyun.kasa_yetkili(p_tur text, p_id bigint, u uuid)
returns boolean language plpgsql stable security definer set search_path = '' as $$
begin
  if u is null or p_id is null then return false; end if;
  if p_tur = 'sirket' then
    return exists(select 1 from oyun.sirket_ortaklari o where o.sirket_id = p_id and o.user_id = u and o.pay > 0)
        or exists(select 1 from oyun.sirketler s where s.id = p_id and s.yonetici = u);
  elsif p_tur = 'dernek' then
    return exists(select 1 from oyun.dernekler d where d.id = p_id and d.baskan = u)
        or exists(select 1 from oyun.dernek_uyeler x where x.dernek_id = p_id and x.user_id = u and x.rol in ('baskan','yonetim'));
  elsif p_tur = 'gazete' then
    return exists(select 1 from oyun.oyuncu_gazeteleri g where g.id = p_id and g.sahip = u);
  end if;
  return false;
end $$;

-- Ekranlara giden kasa rakamı: yetkisi yoksa null döner (arayüz "Gizli" yazar).
-- Zamanlayıcı / SQL Editor gibi oturumsuz sistem çağrılarında değer aynen döner.
create or replace function oyun.kasa_goster(p_tur text, p_id bigint, p_deger numeric)
returns numeric language plpgsql stable security definer set search_path = '' as $$
declare u uuid := auth.uid(); g text;
begin
  if p_deger is null then return null; end if;
  if u is null then
    if coalesce(auth.role(), '') in ('', 'service_role', 'postgres', 'supabase_admin') then return p_deger; end if;
    return null;
  end if;
  if exists(select 1 from oyun.profiller where id = u and yonetici) then return p_deger; end if;
  if oyun.kasa_yetkili(p_tur, p_id, u) then return p_deger; end if;
  select gorunurluk into g from oyun.kasa_gizlilik where tur = p_tur and kimlik = p_id;
  if g = 'herkes' then return p_deger; end if;
  if g = 'uyeler' and p_tur = 'dernek'
     and exists(select 1 from oyun.dernek_uyeler x where x.dernek_id = p_id and x.user_id = u) then
    return p_deger;
  end if;
  return null;
end $$;

-- Hesap numarası (IBAN biçiminde, kişiye ve bankaya özel, kalıcı). 0 = Devlet Bankası.
create or replace function oyun.banka_iban(p_banka bigint, u uuid)
returns text language plpgsql stable set search_path = '' as $$
declare h bigint; s text;
begin
  h := (hashtext(u::text || ':' || coalesce(p_banka, 0)::text)::bigint & 2147483647);
  s := lpad(h::text, 10, '0');
  return 'TR' || lpad(((hashtext(coalesce(p_banka, 0)::text || '/' || u::text)::bigint & 2147483647) % 89 + 10)::text, 2, '0')
      || ' ' || lpad(coalesce(p_banka, 0)::text, 4, '0')
      || ' ' || substr(s, 1, 4) || ' ' || substr(s, 5, 4) || ' ' || substr(s, 9, 2);
end $$;

create or replace function oyun.banka_dibs_orani(p_gun integer)
returns numeric language sql stable set search_path = '' as $$
  select round(oyun.politika_faizi() * p_gun / 365.0
               * case p_gun when 30 then 1.05 when 1 then 0.90 else 1 end, 4)
$$;

-- ---------------------------------------------------------------------
-- C. BİLANÇO, ORANLAR, GÜVEN NOTU, GELİR TABLOSU
-- ---------------------------------------------------------------------
create or replace function oyun.banka_bilanco(p_banka bigint)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  s oyun.sirketler; t timestamptz := oyun.simdi();
  nakit numeric; kredi numeric := 0; kredi_gec numeric := 0; kart numeric := 0; kart_gec numeric := 0; dibs numeric := 0;
  vadesiz numeric := 0; vadeli_ana numeric := 0; vadeli_yuk numeric := 0; yakin numeric := 0; gecik_mev numeric := 0;
  tampon numeric; rezerv numeric; riskli numeric; ozk numeric; emniyet numeric := 0; al numeric;
  kv numeric; dag numeric; azalt numeric; lik numeric; syr numeric; npl numeric; km numeric;
  puan int := 100; harf text; v_durum text;
begin
  select * into s from oyun.sirketler where id = p_banka and sektor = 'banka';
  if s.id is null then raise exception 'Banka bulunamadı.'; end if;
  nakit := coalesce(s.kasa, 0);

  select coalesce(sum(k.kalan), 0),
         coalesce(sum(k.kalan) filter (where k.vade < t or exists(
           select 1 from oyun.oyb_kredi_taksit x where x.kredi_id = k.id and x.odenen < x.tutar and x.vade < t)), 0)
    into kredi, kredi_gec
    from oyun.oyb_kredi k where k.banka_id = p_banka and k.durum in ('aktif','takip');

  if to_regclass('oyun.kredi_kartlari') is not null then
    select coalesce(sum(borc), 0),
           coalesce(sum(borc) filter (where gecikmis_asgari > 0 or durum in ('takip','kapali')), 0)
      into kart, kart_gec
      from oyun.kredi_kartlari where banka_id = p_banka and borc > 0;
  end if;

  select coalesce(sum(tutar), 0) into dibs from oyun.banka_dibs where banka_id = p_banka and durum = 'acik';
  vadesiz := oyun.banka_vadesiz_toplam(p_banka);

  select coalesce(sum(anapara), 0),
         coalesce(sum(round(anapara * (1 + faiz / 100), 2)), 0),
         coalesce(sum(round(anapara * (1 + faiz / 100), 2)) filter (where vade <= t + interval '24 hours'), 0),
         coalesce(sum(round(anapara * (1 + faiz / 100), 2)) filter (where vade <= t), 0)
    into vadeli_ana, vadeli_yuk, yakin, gecik_mev
    from oyun.banka_mevduat where banka_id = p_banka and not kapandi;

  emniyet := coalesce((select emniyet_payi from oyun.banka_politika where banka_id = p_banka), 0);

  -- Yasal tampon: sermayenin ya da toplam mevduatın %10'u (hangisi büyükse)
  tampon := greatest(round(s.sermaye * .10, 2), round((vadeli_ana + vadesiz) * .10, 2));
  -- Likidite rezervi: vadesizin %30'u + (vadelilerin yarısı ya da 24 saatte ödenecekler) + tampon
  rezerv := round(vadesiz * .30, 2) + greatest(round(vadeli_ana * .50, 2), yakin) + tampon;
  -- Risk ağırlıklı varlıklar (DİBS risksiz)
  riskli := (kredi - kredi_gec) + kredi_gec * 1.5 + (kart - kart_gec) + kart_gec * 1.5;
  -- Özkaynak = varlıklar - borçlar
  ozk := nakit + kredi + kart + dibs - vadesiz - vadeli_yuk;
  -- Kredi kapasitesi (eski oyb_saglik formülü + vadesiz mevduat + emniyet payı)
  al := (kredi - kredi_gec) * .70 + kredi_gec * .25;
  kv := greatest(0, least(nakit - rezerv - emniyet, (nakit + al - vadeli_yuk - vadesiz - tampon) / .30));
  -- Dağıtılabilir kâr: birikmiş kâr, kasadaki serbest nakit ve %12 sermaye yeterliliği sınırı
  dag := greatest(0, least(ozk - s.sermaye, nakit - rezerv, ozk - riskli * .12));
  -- Sermaye azaltımı: asgari 1.000.000 ₺ sermaye, nakit ve %12 sınırı
  azalt := greatest(0, least(s.sermaye - 1000000, nakit - rezerv, ozk - riskli * .12));

  lik := case when (vadesiz + yakin + vadeli_ana * .5) > 0 then round(nakit / (vadesiz + yakin + vadeli_ana * .5), 2) end;
  syr := case when riskli > 0 then round(ozk / riskli * 100, 1) end;
  npl := case when (kredi + kart) > 0 then round((kredi_gec + kart_gec) / (kredi + kart) * 100, 1) else 0 end;
  km  := case when (vadesiz + vadeli_ana) > 0 then round((kredi + kart) / (vadesiz + vadeli_ana) * 100, 1) end;

  if lik is not null then puan := puan - case when lik < 1 then 35 when lik < 1.2 then 15 else 0 end; end if;
  if syr is not null then puan := puan - case when syr < 8 then 40 when syr < 12 then 20 when syr < 15 then 8 else 0 end; end if;
  puan := puan - case when npl > 20 then 30 when npl > 10 then 15 when npl > 5 then 6 else 0 end;
  if gecik_mev > 0 and nakit < gecik_mev then puan := puan - 40; end if;
  if ozk < s.sermaye * .5 then puan := puan - 20; end if;
  harf := case when puan >= 95 then 'AAA' when puan >= 88 then 'AA' when puan >= 80 then 'A' when puan >= 70 then 'BBB'
               when puan >= 60 then 'BB' when puan >= 45 then 'B' else 'C' end;
  v_durum := case when puan >= 80 then 'saglam' when puan >= 60 then 'dikkat' else 'riskli' end;

  return jsonb_build_object(
    'nakit', round(nakit, 2), 'krediler', round(kredi, 2), 'krediler_geciken', round(kredi_gec, 2),
    'kart_alacak', round(kart, 2), 'kart_geciken', round(kart_gec, 2), 'dibs', round(dibs, 2),
    'varlik', round(nakit + kredi + kart + dibs, 2),
    'vadesiz', round(vadesiz, 2), 'vadeli_anapara', round(vadeli_ana, 2), 'vadeli_yukumluluk', round(vadeli_yuk, 2),
    'yaklasan_odeme', round(yakin, 2), 'geciken_mevduat', round(gecik_mev, 2),
    'borc', round(vadesiz + vadeli_yuk, 2),
    'ozkaynak', round(ozk, 2), 'sermaye', s.sermaye, 'birikmis_kar', round(ozk - s.sermaye, 2),
    'tampon', round(tampon, 2), 'rezerv', round(rezerv, 2), 'emniyet_payi', emniyet,
    'riskli_varlik', round(riskli, 2),
    'kredi_verilebilir', round(kv, 2), 'dagitilabilir_kar', round(dag, 2), 'sermaye_azaltilabilir', round(azalt, 2),
    'dibs_alinabilir', round(greatest(0, nakit - rezerv), 2),
    'likidite', lik, 'sermaye_yeterlilik', syr, 'takipteki_oran', npl, 'kredi_mevduat', km,
    'puan', greatest(0, puan), 'not', harf, 'durum', v_durum);
end $$;

-- Eski oyb_saglik aynı anahtarları döndürmeye devam eder; artık vadesiz mevduatı da borç sayar.
create or replace function oyun.oyb_saglik(p_banka bigint)
returns jsonb language plpgsql stable set search_path = '' as $$
declare b jsonb := oyun.banka_bilanco(p_banka);
begin
  return jsonb_build_object(
    'kasa', b->'nakit', 'sermaye', b->'sermaye',
    'mevduat_anapara', b->'vadeli_anapara', 'mevduat_yukumluluk', b->'vadeli_yukumluluk',
    'vadesiz_mevduat', b->'vadesiz',
    'yaklasan_odeme', b->'yaklasan_odeme',
    'riskli_kredi_varligi', round(((b->>'krediler')::numeric - (b->>'krediler_geciken')::numeric) * .70
                                  + (b->>'krediler_geciken')::numeric * .25, 2),
    'tampon', b->'tampon', 'asgari_likidite', b->'rezerv',
    'kredi_verilebilir', b->'kredi_verilebilir', 'dagitilabilir_kar', b->'dagitilabilir_kar',
    'not', b->'not', 'durum', b->'durum');
end $$;

-- Şirket defter değeri: bankada vadesiz mevduat, kart alacağı ve DİBS de hesaba girer.
create or replace function oyun.sirket_defter(p_sirket bigint)
returns numeric language plpgsql stable set search_path = '' as $$
declare s oyun.sirketler; d numeric;
begin
  select * into s from oyun.sirketler where id = p_sirket;
  if s.id is null then return 0; end if;
  d := s.kasa
     + coalesce((select sum(adet * maliyet_birim) from oyun.eko_urun_stok where sirket_id = s.id), 0)
     + coalesce((select sum(fiyat) from oyun.eko_arsalar where sahibi_sirket = s.id), 0)
     + coalesce((select sum(maliyet) from oyun.eko_yapilar where sirket_id = s.id), 0);
  if s.sektor = 'banka' then
    d := d + coalesce((select sum(kalan) from oyun.oyb_kredi where banka_id = s.id and durum in ('aktif','takip')), 0)
           + coalesce((select sum(borc) from oyun.kredi_kartlari where banka_id = s.id and borc > 0), 0)
           + coalesce((select sum(tutar) from oyun.banka_dibs where banka_id = s.id and durum = 'acik'), 0)
           - coalesce((select sum(round(m.anapara * (1 + m.faiz / 100), 2)) from oyun.banka_mevduat m where m.banka_id = s.id and not m.kapandi), 0)
           - oyun.banka_vadesiz_toplam(s.id);
  end if;
  return greatest(0, d);
end $$;

create or replace function oyun.banka_gelir(p_banka bigint, p_gun integer)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare t timestamptz := oyun.simdi(); bas timestamptz := oyun.simdi() - make_interval(days => p_gun);
  kf numeric := 0; fa numeric := 0; pk numeric := 0; kt numeric := 0; db numeric := 0; mf numeric := 0; td numeric := 0;
begin
  select coalesce(sum(tutar) filter (where aciklama ilike '%faiz geliri%'), 0),
         coalesce(sum(tutar) filter (where aciklama ilike '%günlük faaliyet%' or aciklama ilike '%gunluk faaliyet%'), 0)
    into kf, fa from oyun.sirket_hareket where sirket_id = p_banka and zaman >= bas;
  if to_regclass('oyun.kart_pos_talepleri') is not null then
    select coalesce(sum(z.komisyon_tl), 0) into pk
      from oyun.kart_pos_talepleri z join oyun.sirket_pos x on x.id = z.pos_id
     where x.banka_id = p_banka and z.durum = 'odendi' and z.odendi >= bas;
    select coalesce(sum(h.tutar), 0) into kt
      from oyun.kart_hareketler h join oyun.kredi_kartlari c on c.id = h.kart_id
     where c.banka_id = p_banka and h.tur in ('faiz','gecikme','avans_masraf') and h.zaman >= bas;
  end if;
  select coalesce(sum(odenen - tutar), 0) into db from oyun.banka_dibs where banka_id = p_banka and durum = 'odendi' and kapanis >= bas;
  select coalesce(sum(round(anapara * faiz / 100, 2)), 0) into mf
    from oyun.banka_mevduat where banka_id = p_banka and kapandi and not iptal and vade >= bas and vade <= t;
  select coalesce(sum(brut), 0) into td from oyun.banka_temettu where banka_id = p_banka and tur = 'temettu' and zaman >= bas;
  return jsonb_build_object('gun', p_gun, 'kredi_faiz', round(kf, 2), 'pos_komisyon', round(pk, 2), 'kart_faiz', round(kt, 2),
    'dibs', round(db, 2), 'faaliyet', round(fa, 2), 'mevduat_faiz', round(mf, 2),
    'net', round(kf + pk + kt + db + fa - mf, 2), 'dagitilan', round(td, 2));
end $$;

-- Herkese açık banka künyesi: kasa YOK, yalnız güven notu ve ürünler
create or replace function oyun.banka_kunye(p_banka bigint, u uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare s oyun.sirketler; bp oyun.banka_politika; b jsonb;
begin
  select * into s from oyun.sirketler where id = p_banka and sektor = 'banka' and aktif;
  if s.id is null then return null; end if;
  select * into bp from oyun.banka_politika where banka_id = p_banka;
  b := oyun.banka_bilanco(p_banka);
  return jsonb_build_object(
    'id', s.id, 'ad', s.ad, 'kurulus', s.kurulus,
    'renk', coalesce(bp.renk, 'lacivert'), 'slogan', bp.slogan,
    'not', b->'not', 'durum', b->'durum',
    'mevduat7', least(s.banka_faiz, 1.8), 'kredi24', least(s.banka_kredi_faiz, 1.0),
    'vadeler', jsonb_build_object('1', oyun.oyb_oran(s.id, 1), '6', oyun.oyb_oran(s.id, 6),
                                  '24', oyun.oyb_oran(s.id, 24), '168', oyun.oyb_oran(s.id, 168)),
    'paket_sayisi', (select count(*) from oyun.oyb_kredi_paket p where p.banka_id = s.id and p.aktif and p.silindi_at is null),
    'en_dusuk_kredi', (select min(p.faiz) from oyun.oyb_kredi_paket p where p.banka_id = s.id and p.aktif and p.silindi_at is null),
    'musteri', (select count(*) from oyun.oyb_hesap h where h.banka_id = s.id and h.kapanis is null),
    'hesabim', oyun.oyb_hesap_acik(s.id, u),
    'bankam', exists(select 1 from oyun.sirket_ortaklari o where o.sirket_id = s.id and o.user_id = u and o.pay > 0),
    'kart_otomatik', coalesce((select kart_otomatik from oyun.banka_yonetim_ayar a where a.banka_id = s.id), false),
    'kredi_otomatik', coalesce((select kredi_otomatik from oyun.banka_yonetim_ayar a where a.banka_id = s.id), false));
end $$;

-- ---------------------------------------------------------------------
-- D. DİBS (Devlet İç Borçlanma Senedi) — bankanın atıl parası
-- ---------------------------------------------------------------------
create or replace function oyun.banka_dibs_tahsil(p_banka bigint default null)
returns integer language plpgsql security definer set search_path = '' as $$
declare d oyun.banka_dibs; t timestamptz := oyun.simdi(); n int := 0; odeme numeric; tlm numeric;
begin
  tlm := coalesce(nullif(oyun.pazar_tl_milyar(), 0), 1000000000);
  for d in select * from oyun.banka_dibs
            where durum = 'acik' and vade <= t and (p_banka is null or banka_id = p_banka)
            order by id for update skip locked loop
    odeme := round(d.tutar * (1 + d.oran / 100), 2);
    update oyun.sirketler set kasa = kasa + odeme where id = d.banka_id;
    update oyun.banka_dibs set durum = 'odendi', odenen = odeme, kapanis = t where id = d.id;
    update oyun.ulke set hazine = hazine - odeme / tlm where id = 1;
    insert into oyun.sirket_hareket(sirket_id, zaman, tutar, aciklama)
    values (d.banka_id, t, odeme, format('DİBS itfası #%s: %s gün vadeli tahvil kasaya döndü (anapara %s ₺ + getiri %s ₺)',
            d.id, d.gun, oyun.tl(d.tutar), oyun.tl(odeme - d.tutar)));
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.banka_dibs_al(p_banka bigint, p_tutar numeric, p_gun integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); t timestamptz := oyun.simdi(); s oyun.sirketler; b jsonb; ora numeric; x bigint; tlm numeric;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  if not oyun.sirket_yonetici_mi(p_banka, u) then raise exception 'DİBS alımına bankanın yöneticisi ya da en az %%50 ortağı karar verir.'; end if;
  if p_gun not in (1, 7, 30) then raise exception 'DİBS vadesi 1, 7 ya da 30 gün olabilir.'; end if;
  if p_tutar is null or p_tutar <> round(p_tutar) or p_tutar < 10000 or p_tutar > 50000000 then
    raise exception 'DİBS tutarı 10.000 – 50.000.000 ₺ arasında tam sayı olmalı.'; end if;
  perform oyun.banka_dibs_tahsil(p_banka);
  select * into s from oyun.sirketler where id = p_banka and sektor = 'banka' and aktif for update;
  if s.id is null then raise exception 'Faal banka bulunamadı.'; end if;
  b := oyun.banka_bilanco(p_banka);
  if p_tutar > (b->>'dibs_alinabilir')::numeric then
    raise exception 'Likidite rezervi korunmalı. Bu bankayla en fazla % ₺ DİBS alınabilir.', oyun.tl((b->>'dibs_alinabilir')::numeric); end if;
  ora := oyun.banka_dibs_orani(p_gun);
  tlm := coalesce(nullif(oyun.pazar_tl_milyar(), 0), 1000000000);
  update oyun.sirketler set kasa = kasa - p_tutar, son_islem = t where id = p_banka and kasa >= p_tutar;
  if not found then raise exception 'Kasa yetersiz.'; end if;
  insert into oyun.banka_dibs(banka_id, tutar, gun, oran, acilis, vade, alan)
  values (p_banka, p_tutar, p_gun, ora, t, t + make_interval(days => p_gun), u) returning id into x;
  update oyun.ulke set hazine = hazine + p_tutar / tlm where id = 1;
  insert into oyun.sirket_hareket(sirket_id, zaman, tutar, aciklama)
  values (p_banka, t, -p_tutar, format('DİBS alımı #%s: %s gün vadeli devlet tahvili, %%%s getiri (%s)', x, p_gun, ora, oyun.kad(u)));
  return jsonb_build_object('tamam', true, 'id', x, 'oran', ora, 'vade', t + make_interval(days => p_gun),
                            'getiri', round(p_tutar * ora / 100, 2));
end $$;

create or replace function public.banka_dibs_boz(p_banka bigint, p_id bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); t timestamptz := oyun.simdi(); d oyun.banka_dibs; odeme numeric; tlm numeric;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  if not oyun.sirket_yonetici_mi(p_banka, u) then raise exception 'Bu bankanın yönetim yetkin yok.'; end if;
  select * into d from oyun.banka_dibs where id = p_id and banka_id = p_banka for update;
  if d.id is null or d.durum <> 'acik' then raise exception 'Açık DİBS bulunamadı.'; end if;
  if d.vade <= t then
    perform oyun.banka_dibs_tahsil(p_banka);
    return jsonb_build_object('tamam', true, 'vadeli', true);
  end if;
  tlm := coalesce(nullif(oyun.pazar_tl_milyar(), 0), 1000000000);
  odeme := round(d.tutar * 0.998, 2);   -- vadeden önce satış: getiri yok, %0,2 kırım
  update oyun.sirketler set kasa = kasa + odeme where id = p_banka;
  update oyun.banka_dibs set durum = 'bozuldu', odenen = odeme, kapanis = t where id = d.id;
  update oyun.ulke set hazine = hazine - odeme / tlm where id = 1;
  insert into oyun.sirket_hareket(sirket_id, zaman, tutar, aciklama)
  values (p_banka, t, odeme, format('DİBS #%s vadeden önce satıldı (getirisiz, %%0,2 kırım)', d.id));
  return jsonb_build_object('tamam', true, 'odenen', odeme);
end $$;

-- ---------------------------------------------------------------------
-- E. KASA YÖNETİMİ: sermaye koy, kâr payı (stopajlı), sermaye azalt,
--    emniyet payı, kimlik, risk profili
-- ---------------------------------------------------------------------
create or replace function public.banka_sermaye_koy(p_banka bigint, p_tutar numeric)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare r jsonb;
begin
  if not exists(select 1 from oyun.sirketler where id = p_banka and sektor = 'banka' and aktif) then
    raise exception 'Faal banka bulunamadı.'; end if;
  r := public.sirket_kasa_yatir(p_banka, p_tutar);
  return r || jsonb_build_object('bilanco', oyun.banka_bilanco(p_banka));
end $$;

create or replace function public.banka_kar_dagit(p_banka bigint, p_tutar numeric)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); t timestamptz := oyun.simdi(); s oyun.sirketler; b jsonb; dag numeric; x record; tid bigint;
  brut numeric; st numeric; net numeric; tb numeric := 0; ts numeric := 0; tn numeric := 0;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  if not oyun.sirket_yonetici_mi(p_banka, u) then
    raise exception 'Kâr payı dağıtımına bankanın yöneticisi ya da en az %%50 ortağı karar verir.'; end if;
  if p_tutar is null or p_tutar <> round(p_tutar) or p_tutar < 1000 then
    raise exception 'Kâr payı en az 1.000 ₺ ve tam sayı olmalı.'; end if;
  perform oyun.sirket_hesapla(p_banka);
  perform oyun.banka_dibs_tahsil(p_banka);
  select * into s from oyun.sirketler where id = p_banka and sektor = 'banka' and aktif for update;
  if s.id is null then raise exception 'Faal banka bulunamadı.'; end if;
  b := oyun.banka_bilanco(p_banka);
  dag := floor(coalesce((b->>'dagitilabilir_kar')::numeric, 0));
  if p_tutar > dag then
    raise exception 'Dağıtılabilir kâr % ₺. Sermaye, mevduat sahiplerinin parası ve yasal karşılık dağıtılamaz.', oyun.tl(dag); end if;
  insert into oyun.banka_temettu(banka_id, tur, yapan, zaman) values (p_banka, 'temettu', u, t) returning id into tid;
  for x in select user_id, pay from oyun.sirket_ortaklari where sirket_id = p_banka and pay > 0 order by pay desc, user_id loop
    brut := round(p_tutar * x.pay / 100);
    if brut <= 0 then continue; end if;
    st := oyun.eko_vergi_tahsil(p_banka, 'dagitim', brut, 'banka_temettu', tid, x.user_id);
    net := brut - st;
    perform oyun.para_islem(x.user_id, net, 'sirket',
      format('%s kâr payı (brüt %s ₺, stopaj %s ₺)', s.ad, oyun.tl(brut), oyun.tl(st)), t, st);
    perform oyun.bildir(x.user_id, format('🏦 %s ortaklarına kâr payı dağıttı. Payına düşen net %s ₺ cüzdanına geçti.', s.ad, oyun.tl(net)), t);
    tb := tb + brut; ts := ts + st; tn := tn + net;
  end loop;
  if tb <= 0 then raise exception 'Dağıtılacak ortak bulunamadı.'; end if;
  update oyun.sirketler set kasa = kasa - tb, son_islem = t where id = p_banka and kasa >= tb;
  if not found then raise exception 'Kasa yetersiz.'; end if;
  update oyun.banka_temettu set brut = tb, stopaj = ts, net = tn where id = tid;
  insert into oyun.sirket_hareket(sirket_id, zaman, tutar, aciklama, dagitilan_kar)
  values (p_banka, t, -tb, format('Kâr payı dağıtımı: brüt %s ₺, stopaj %s ₺ Hazine''ye, ortaklara net %s ₺', oyun.tl(tb), oyun.tl(ts), oyun.tl(tn)), tb);
  return jsonb_build_object('tamam', true, 'brut', tb, 'stopaj', ts, 'net', tn);
end $$;

create or replace function public.banka_sermaye_azalt(p_banka bigint, p_tutar numeric)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); t timestamptz := oyun.simdi(); s oyun.sirketler; b jsonb; mx numeric; x record; tid bigint; pay numeric; top numeric := 0;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  if not oyun.sirket_yonetici_mi(p_banka, u) then
    raise exception 'Sermaye azaltımına bankanın yöneticisi ya da en az %%50 ortağı karar verir.'; end if;
  if p_tutar is null or p_tutar <> round(p_tutar) or p_tutar < 10000 then
    raise exception 'Sermaye azaltımı en az 10.000 ₺ ve tam sayı olmalı.'; end if;
  perform oyun.banka_dibs_tahsil(p_banka);
  select * into s from oyun.sirketler where id = p_banka and sektor = 'banka' and aktif for update;
  if s.id is null then raise exception 'Faal banka bulunamadı.'; end if;
  b := oyun.banka_bilanco(p_banka);
  mx := floor(coalesce((b->>'sermaye_azaltilabilir')::numeric, 0));
  if p_tutar > mx then
    raise exception 'En fazla % ₺ sermaye azaltılabilir. Bankanın sermayesi 1.000.000 ₺ altına düşemez; mevduat ve %%12 sermaye yeterliliği korunur.', oyun.tl(mx); end if;
  insert into oyun.banka_temettu(banka_id, tur, yapan, zaman) values (p_banka, 'sermaye_iade', u, t) returning id into tid;
  for x in select user_id, o.pay from oyun.sirket_ortaklari o where sirket_id = p_banka and o.pay > 0 order by o.pay desc, user_id loop
    pay := round(p_tutar * x.pay / 100);
    if pay <= 0 then continue; end if;
    perform oyun.para_islem(x.user_id, pay, 'sirket', format('%s sermaye iadesi (vergisiz)', s.ad), t);
    perform oyun.bildir(x.user_id, format('🏦 %s sermayesini azalttı. Payına düşen %s ₺ cüzdanına iade edildi.', s.ad, oyun.tl(pay)), t);
    top := top + pay;
  end loop;
  if top <= 0 then raise exception 'İade edilecek ortak bulunamadı.'; end if;
  update oyun.sirketler set kasa = kasa - top, sermaye = sermaye - top, son_islem = t where id = p_banka and kasa >= top;
  if not found then raise exception 'Kasa yetersiz.'; end if;
  update oyun.banka_temettu set brut = top, net = top where id = tid;
  insert into oyun.sirket_hareket(sirket_id, zaman, tutar, aciklama)
  values (p_banka, t, -top, format('Sermaye azaltımı: ortaklara %s ₺ iade edildi; yeni sermaye %s ₺', oyun.tl(top), oyun.tl(s.sermaye - top)));
  return jsonb_build_object('tamam', true, 'iade', top, 'yeni_sermaye', s.sermaye - top);
end $$;

create or replace function public.banka_politika_kaydet(p_banka bigint, p_emniyet numeric default null,
  p_renk text default null, p_slogan text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); sl text;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  if not exists(select 1 from oyun.sirketler where id = p_banka and sektor = 'banka') then raise exception 'Banka bulunamadı.'; end if;
  if not oyun.sirket_yonetici_mi(p_banka, u) then raise exception 'Bu bankanın yönetim yetkin yok.'; end if;
  if p_emniyet is not null and (p_emniyet < 0 or p_emniyet > 100000000 or p_emniyet <> round(p_emniyet)) then
    raise exception 'Emniyet payı 0 – 100.000.000 ₺ arasında tam sayı olmalı.'; end if;
  if p_renk is not null and p_renk not in ('lacivert','bordo','zumrut','turuncu','mor','altin','turkuaz','gece','kirmizi','gumus') then
    raise exception 'Geçersiz banka rengi.'; end if;
  if p_slogan is not null then
    sl := nullif(btrim(regexp_replace(p_slogan, '[<>]', '', 'g')), '');
    if sl is not null and char_length(sl) > 80 then raise exception 'Slogan en fazla 80 karakter olabilir.'; end if;
  end if;
  insert into oyun.banka_politika(banka_id, emniyet_payi, renk, slogan, guncelleme)
  values (p_banka, coalesce(p_emniyet, 0), coalesce(p_renk, 'lacivert'), sl, now())
  on conflict (banka_id) do update set
    emniyet_payi = coalesce(p_emniyet, oyun.banka_politika.emniyet_payi),
    renk = coalesce(p_renk, oyun.banka_politika.renk),
    slogan = case when p_slogan is null then oyun.banka_politika.slogan else sl end,
    guncelleme = now();
  return jsonb_build_object('tamam', true);
end $$;

create or replace function public.banka_risk_profili(p_banka bigint, p_profil text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); a oyun.banka_yonetim_ayar; pos boolean; kart boolean; kredi boolean; mn int; kmx numeric; krmx numeric;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  if p_profil not in ('temkinli','dengeli','atak','manuel') then raise exception 'Risk profili temkinli, dengeli, atak ya da manuel olmalı.'; end if;
  select * into a from oyun.banka_yonetim_ayar where banka_id = p_banka;
  if p_profil = 'temkinli' then pos := true; kart := true; kredi := true; mn := 1500; kmx := 100000;  krmx := 100000;
  elsif p_profil = 'dengeli' then pos := true; kart := true; kredi := true; mn := 1100; kmx := 300000;  krmx := 300000;
  elsif p_profil = 'atak' then pos := true; kart := true; kredi := true; mn := 900;  kmx := 1000000; krmx := 1000000;
  else pos := false; kart := false; kredi := false; mn := coalesce(a.asgari_not, 850);
       kmx := coalesce(a.kart_azami, 500000); krmx := coalesce(a.kredi_azami, 500000);
  end if;
  perform public.banka_yonetim_ayar_kaydet(p_banka, pos, kart, kredi, mn, kmx, krmx);
  insert into oyun.banka_politika(banka_id, risk_profili, guncelleme) values (p_banka, p_profil, now())
  on conflict (banka_id) do update set risk_profili = excluded.risk_profili, guncelleme = now();
  return jsonb_build_object('tamam', true, 'profil', p_profil, 'asgari_not', mn, 'kart_max', kmx, 'kredi_max', krmx);
end $$;

-- ---------------------------------------------------------------------
-- F. KASA GİZLİLİĞİ RPC'LERİ
-- ---------------------------------------------------------------------
create or replace function public.kasa_gizlilik_ayarla(p_tur text, p_id bigint, p_gorunurluk text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); ok boolean;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  if p_tur not in ('sirket','dernek','gazete') then raise exception 'Geçersiz kurum türü.'; end if;
  if p_gorunurluk not in ('gizli','uyeler','herkes') then raise exception 'Görünürlük gizli, üyeler ya da herkes olmalı.'; end if;
  if p_gorunurluk = 'uyeler' and p_tur <> 'dernek' then raise exception '“Yalnız üyeler” seçeneği dernekler içindir.'; end if;
  ok := case p_tur
    when 'sirket' then oyun.sirket_yonetici_mi(p_id, u)
    when 'dernek' then exists(select 1 from oyun.dernekler d where d.id = p_id and d.baskan = u)
    else exists(select 1 from oyun.oyuncu_gazeteleri g where g.id = p_id and g.sahip = u) end;
  if not coalesce(ok, false) then raise exception 'Kasa görünürlüğünü yalnız kurumun sahibi ya da yöneticisi değiştirebilir.'; end if;
  insert into oyun.kasa_gizlilik(tur, kimlik, gorunurluk, guncelleyen, guncelleme)
  values (p_tur, p_id, p_gorunurluk, u, now())
  on conflict (tur, kimlik) do update set gorunurluk = excluded.gorunurluk, guncelleyen = excluded.guncelleyen, guncelleme = excluded.guncelleme;
  return jsonb_build_object('tamam', true, 'tur', p_tur, 'id', p_id, 'gorunurluk', p_gorunurluk);
end $$;

create or replace function public.kasa_gizlilik_listem()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare u uuid := auth.uid();
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  return jsonb_build_object(
    'sirketler', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'ad', s.ad, 'sektor', s.sektor, 'kasa', s.kasa,
        'gorunurluk', coalesce(g.gorunurluk, 'gizli'), 'ayarlayabilir', oyun.sirket_yonetici_mi(s.id, u)) order by s.sektor <> 'banka', s.ad)
      from oyun.sirketler s left join oyun.kasa_gizlilik g on g.tur = 'sirket' and g.kimlik = s.id
     where s.aktif and oyun.kasa_yetkili('sirket', s.id, u)), '[]'::jsonb),
    'dernekler', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'ad', d.ad, 'kasa', d.kasa,
        'gorunurluk', coalesce(g.gorunurluk, 'gizli'), 'ayarlayabilir', d.baskan = u) order by d.ad)
      from oyun.dernekler d left join oyun.kasa_gizlilik g on g.tur = 'dernek' and g.kimlik = d.id
     where not d.kapali and oyun.kasa_yetkili('dernek', d.id, u)), '[]'::jsonb),
    'gazeteler', coalesce((select jsonb_agg(jsonb_build_object('id', z.id, 'ad', z.ad, 'kasa', z.kasa,
        'gorunurluk', coalesce(g.gorunurluk, 'gizli'), 'ayarlayabilir', true) order by z.ad)
      from oyun.oyuncu_gazeteleri z left join oyun.kasa_gizlilik g on g.tur = 'gazete' and g.kimlik = z.id
     where z.aktif and z.sahip = u), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------------
-- G. MÜŞTERİ: MOBİL ŞUBE
-- ---------------------------------------------------------------------
create or replace function public.banka_sube()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); t timestamptz := oyun.simdi(); p oyun.profiller; m oyun.banka_musteri; c record; cuz numeric;
  vadeli_devlet numeric; mev numeric; kredi numeric; kart numeric; vadesiz_ozel numeric; dk oyun.krediler;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  select * into p from oyun.profiller where id = u;
  if p.id is null then raise exception 'Profil bulunamadı.'; end if;
  m := oyun.vadesiz_isle(u, t);
  for c in select id from oyun.kredi_kartlari where user_id = u loop perform oyun.kart_donem_isle(c.id); end loop;
  perform public.banka_mevduat_tahsil();
  cuz := coalesce((select para from oyun.cuzdan where user_id = u), 0);
  vadeli_devlet := coalesce((select sum(anapara) from oyun.vadeli where user_id = u and durum = 'acik'), 0);
  mev := coalesce((select sum(anapara) from oyun.banka_mevduat where user_id = u and not kapandi), 0);
  vadesiz_ozel := coalesce((select sum(bakiye) from oyun.ib_vadesiz where user_id = u), 0);
  kredi := coalesce((select sum(kalan) from oyun.oyb_kredi where borclu = u and durum in ('aktif','takip')), 0)
         + coalesce((select sum(kalan) from oyun.krediler where user_id = u and durum in ('aktif','takip')), 0);
  kart := coalesce((select sum(borc) from oyun.kredi_kartlari where user_id = u), 0);
  select * into dk from oyun.krediler where user_id = u and durum in ('aktif','takip') order by id desc limit 1;

  return jsonb_build_object(
    'kad', p.kad, 'cuzdan', cuz, 'simdi', t,
    'kredi_notu', coalesce(m.kredi_notu, 1100), 'not_ad', oyun.not_ad(coalesce(m.kredi_notu, 1100)),
    'kara_liste', case when m.kara_liste > t then m.kara_liste end,
    'toplam', jsonb_build_object(
       'varlik', round(cuz + coalesce(m.vadesiz, 0) + vadesiz_ozel + vadeli_devlet + mev, 2),
       'banka', round(coalesce(m.vadesiz, 0) + vadesiz_ozel + vadeli_devlet + mev, 2),
       'borc', round(kredi + kart, 2)),
    'devlet', jsonb_build_object(
       'iban', oyun.banka_iban(0, u), 'vadesiz', round(coalesce(m.vadesiz, 0), 2),
       'oranlar', oyun.banka_oranlar(),
       'vadeliler', coalesce((select jsonb_agg(jsonb_build_object('id', v.id, 'anapara', v.anapara, 'oran', v.oran,
            'gun', v.gun, 'vade_saat', v.vade_saat, 'oran_tur', v.oran_tur, 'acilis', v.acilis, 'vade', v.vade,
            'biriken', oyun.vadeli_biriken(v, t)) order by v.vade)
          from oyun.vadeli v where v.user_id = u and v.durum = 'acik'), '[]'::jsonb),
       'kredi', case when dk.id is not null then jsonb_build_object('id', dk.id, 'anapara', dk.anapara, 'kalan', dk.kalan,
            'taksit', dk.taksit, 'gecikmis', dk.gecikmis, 'gun', dk.gun, 'durum', dk.durum, 'acilis', dk.acilis,
            'erken_kapama', oyun.erken_kapama(dk)) end),
    'hesaplar', coalesce((select jsonb_agg(jsonb_build_object(
         'banka_id', s.id, 'ad', s.ad, 'renk', coalesce(bp.renk, 'lacivert'), 'slogan', bp.slogan,
         'iban', oyun.banka_iban(s.id, u), 'acilis', h.acilis,
         'vadesiz', coalesce((select v.bakiye from oyun.ib_vadesiz v where v.banka_id = s.id and v.user_id = u), 0),
         'vadeli', coalesce((select sum(x.anapara) from oyun.banka_mevduat x where x.banka_id = s.id and x.user_id = u and not x.kapandi), 0),
         'kredi', coalesce((select sum(x.kalan) from oyun.oyb_kredi x where x.banka_id = s.id and x.borclu = u and x.durum in ('aktif','takip')), 0),
         'kart', coalesce((select sum(x.borc) from oyun.kredi_kartlari x where x.banka_id = s.id and x.user_id = u), 0)
       ) order by h.acilis)
       from oyun.oyb_hesap h join oyun.sirketler s on s.id = h.banka_id and s.aktif and s.sektor = 'banka'
       left join oyun.banka_politika bp on bp.banka_id = s.id
       where h.user_id = u and h.kapanis is null), '[]'::jsonb),
    'kartlar', coalesce((select jsonb_agg(jsonb_build_object(
         'id', k.id, 'banka_id', k.banka_id, 'banka', coalesce(s.ad, 'Devlet Bankası'),
         'renk', case when k.banka_id is null then 'devlet' else coalesce(bp.renk, 'lacivert') end,
         'limit', k.limit_tl, 'borc', k.borc, 'kullanilabilir', greatest(k.limit_tl - k.borc, 0), 'durum', k.durum,
         'son_dort', lpad((k.id % 10000)::text, 4, '0'), 'kesim_at', k.kesim_at, 'gecikmis_asgari', k.gecikmis_asgari,
         'nakit_avans', k.nakit_avans_bakiye,
         'ekstre', (select jsonb_build_object('id', e.id, 'kesim', e.kesim, 'son_odeme', e.son_odeme, 'toplam', e.toplam,
                    'asgari', e.asgari, 'odenen', e.odenen) from oyun.kart_ekstreler e
                    where e.kart_id = k.id and e.durum = 'acik' order by e.son_odeme limit 1),
         'hareketler', coalesce((select jsonb_agg(jsonb_build_object('tur', a.tur, 'tutar', a.tutar, 'aciklama', a.aciklama, 'zaman', a.zaman) order by a.id desc)
                    from (select * from oyun.kart_hareketler where kart_id = k.id order by id desc limit 8) a), '[]'::jsonb)
       ) order by k.id desc)
       from oyun.kredi_kartlari k left join oyun.sirketler s on s.id = k.banka_id
       left join oyun.banka_politika bp on bp.banka_id = k.banka_id
       where k.user_id = u and k.durum <> 'iptal'), '[]'::jsonb),
    'kart_basvurulari', coalesce((select jsonb_agg(jsonb_build_object('id', b.id, 'banka_id', b.banka_id,
         'banka', coalesce(s.ad, 'Devlet Bankası'), 'istek', b.istek, 'istenen', b.istenen, 'izin', b.izin,
         'teklif_limit', b.teklif_limit, 'basvuru', b.basvuru) order by b.id desc)
       from oyun.kart_basvurular b left join oyun.sirketler s on s.id = b.banka_id
       where b.user_id = u and b.durum = 'bekliyor'), '[]'::jsonb),
    'krediler', coalesce((select jsonb_agg(jsonb_build_object(
         'id', k.id, 'banka_id', k.banka_id, 'banka', s.ad, 'renk', coalesce(bp.renk, 'lacivert'),
         'anapara', k.anapara, 'toplam', k.toplam, 'kalan', k.kalan, 'oran', k.oran, 'durum', k.durum,
         'vade_gun', round(k.saat / 24.0, 1), 'acilis', k.acilis, 'vade', k.vade, 'basvuru', k.basvuru,
         'taksit_sayisi', k.taksit_sayisi,
         'odenen_taksit', (select count(*) from oyun.oyb_kredi_taksit x where x.kredi_id = k.id and x.odenen >= x.tutar),
         'siradaki', (select jsonb_build_object('sira', x.sira, 'vade', x.vade, 'kalan', x.tutar - x.odenen)
                      from oyun.oyb_kredi_taksit x where x.kredi_id = k.id and x.odenen < x.tutar order by x.sira limit 1),
         'geciken', (select coalesce(sum(x.tutar - x.odenen), 0) from oyun.oyb_kredi_taksit x
                     where x.kredi_id = k.id and x.odenen < x.tutar and x.vade < t),
         'erken_kapama', case when k.durum = 'aktif' then oyun.oyb_erken_kapama_tutari(k, t) end,
         'icra', (select i.durum from oyun.oyb_icra i where i.kredi_id = k.id)
       ) order by (k.durum = 'basvuru') desc, k.id desc)
       from oyun.oyb_kredi k join oyun.sirketler s on s.id = k.banka_id
       left join oyun.banka_politika bp on bp.banka_id = k.banka_id
       where k.borclu = u and k.durum in ('basvuru','aktif','takip')), '[]'::jsonb),
    'mevduatlar', coalesce((select jsonb_agg(jsonb_build_object(
         'id', x.id, 'banka_id', x.banka_id, 'banka', s.ad, 'renk', coalesce(bp.renk, 'lacivert'),
         'anapara', x.anapara, 'oran', x.faiz, 'getiri', round(x.anapara * x.faiz / 100, 2),
         'saat', coalesce(x.vade_saat, 168), 'acilis', x.acilis, 'vade', x.vade, 'vadesi_doldu', x.vade <= t) order by x.vade)
       from oyun.banka_mevduat x join oyun.sirketler s on s.id = x.banka_id
       left join oyun.banka_politika bp on bp.banka_id = x.banka_id
       where x.user_id = u and not x.kapandi), '[]'::jsonb),
    'bekleyen', jsonb_build_object(
       'teklifler', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'banka', s.ad, 'banka_id', x.banka_id,
            'tutar', x.tutar, 'vade_gun', x.vade_gun, 'taksit_sayisi', x.taksit_sayisi, 'faiz', x.faiz, 'mesaj', x.mesaj,
            'son', x.son, 'plan', oyun.oyb_plan(x.tutar, x.vade_gun, x.taksit_sayisi, x.faiz, t)) order by x.id desc)
          from oyun.oyb_kredi_teklifi x join oyun.sirketler s on s.id = x.banka_id
          where x.user_id = u and x.durum = 'teklif' and x.son > t), '[]'::jsonb),
       'bilgi', coalesce((select jsonb_agg(jsonb_build_object('banka_id', b.banka_id, 'banka', s.ad, 'istenen', b.istenen, 'istek_at', b.istek_at))
          from oyun.oyb_hesap_bilgi b join oyun.sirketler s on s.id = b.banka_id
          where b.user_id = u and b.durum = 'bekliyor'), '[]'::jsonb),
       'kredi_bilgi', coalesce((select jsonb_agg(jsonb_build_object('kredi_id', b.kredi_id, 'banka', s.ad, 'istenen', b.istenen))
          from oyun.oyb_bilgi_izin b join oyun.sirketler s on s.id = b.banka_id
          where b.borclu = u and b.durum = 'bekliyor'), '[]'::jsonb),
       'pos', coalesce((select jsonb_agg(jsonb_build_object('id', z.id, 'sirket', s.ad, 'tutar', z.tutar, 'aciklama', z.aciklama,
            'olusturma', z.olusturma) order by z.id desc)
          from oyun.kart_pos_talepleri z join oyun.sirketler s on s.id = z.sirket_id
          where z.musteri = u and z.durum = 'bekliyor'), '[]'::jsonb)),
    'hareketler', coalesce((select jsonb_agg(q.j order by q.z desc) from (
         (select jsonb_build_object('kaynak', 'Devlet Bankası', 'renk', 'devlet', 'tutar', h.tutar, 'aciklama', h.aciklama, 'zaman', h.zaman) j, h.zaman z
            from oyun.banka_hareket h where h.user_id = u order by h.zaman desc limit 25)
         union all
         (select jsonb_build_object('kaynak', s.ad, 'renk', coalesce(bp.renk, 'lacivert'), 'tutar', h.tutar, 'aciklama', h.aciklama, 'zaman', h.zaman), h.zaman
            from oyun.ib_hareket h join oyun.sirketler s on s.id = h.banka_id left join oyun.banka_politika bp on bp.banka_id = h.banka_id
           where h.user_id = u order by h.zaman desc limit 25)
         union all
         (select jsonb_build_object('kaynak', 'Kart •••• ' || lpad((k.id % 10000)::text, 4, '0'), 'renk', 'kart',
                 'tutar', case when a.tur = 'odeme' then a.tutar else -a.tutar end, 'aciklama', a.aciklama, 'zaman', a.zaman), a.zaman
            from oyun.kart_hareketler a join oyun.kredi_kartlari k on k.id = a.kart_id
           where k.user_id = u order by a.zaman desc limit 15)
       ) q), '[]'::jsonb),
    'bankalar', coalesce((select jsonb_agg(oyun.banka_kunye(s.id, u) order by s.kurulus)
       from oyun.sirketler s where s.sektor = 'banka' and s.aktif), '[]'::jsonb));
end $$;

-- Alıcının hangi bankalarda hesabı var? (yalnız banka adları; bakiye yok)
create or replace function public.banka_alici(p_kad text)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare u uuid := auth.uid(); h oyun.profiller;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  select * into h from oyun.profiller where lower(kad) = lower(btrim(coalesce(p_kad, '')));
  if h.id is null then raise exception 'Bu kullanıcı adıyla oyuncu bulunamadı.'; end if;
  if h.id = u then raise exception 'Kendi hesapların arasında aktarım için “Hesaplarım arası”nı kullan.'; end if;
  return jsonb_build_object('kad', h.kad, 'yasakli', h.yasakli,
    'hesaplar', jsonb_build_array(jsonb_build_object('hedef', 'devlet', 'ad', 'Devlet Bankası', 'renk', 'devlet'))
      || coalesce((select jsonb_agg(jsonb_build_object('hedef', 'b:' || s.id, 'ad', s.ad, 'renk', coalesce(bp.renk, 'lacivert')) order by s.ad)
           from oyun.oyb_hesap x join oyun.sirketler s on s.id = x.banka_id and s.aktif
           left join oyun.banka_politika bp on bp.banka_id = s.id
          where x.user_id = h.id and x.kapanis is null), '[]'::jsonb));
end $$;

-- Günlük aktarım sınırı artık FAST transferlerini de sayar
create or replace function oyun.gunluk_aktarim(u uuid, t timestamp with time zone)
returns numeric language plpgsql stable set search_path = '' as $$
begin
  return coalesce((select sum(tutar) from oyun.banka_transfer where gonderen = u and zaman >= oyun.bugun_bas(t)), 0)
       + coalesce((select sum(tutar) from oyun.serbest_bagis_kayit where gonderen = u and alici_tur in ('oyuncu','sirket','gazete')
                   and zaman >= oyun.bugun_bas(t)), 0)
       + coalesce((select sum(tutar) from oyun.banka_fast where gonderen = u and zaman >= oyun.bugun_bas(t)), 0);
end $$;

-- FAST: her hesaptan her hesaba (aynı banka = havale, başka banka = EFT, Devlet ↔ özel = FAST)
create or replace function public.banka_fast(p_kaynak text, p_alici text, p_hedef text, p_tutar numeric, p_aciklama text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); t timestamptz := oyun.simdi(); p oyun.profiller; h oyun.profiller; m numeric; kb bigint; hb bigint;
  ack text; v numeric; bugun numeric; tavan numeric; sad text; had text; r jsonb;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  p := oyun.profilim();
  if p_kaynak is null or (p_kaynak <> 'devlet' and p_kaynak !~ '^b:[0-9]+$') then raise exception 'Gönderen hesabı seç.'; end if;
  if p_hedef is null or (p_hedef <> 'devlet' and p_hedef !~ '^b:[0-9]+$') then raise exception 'Alıcının hesabını seç.'; end if;
  kb := case when p_kaynak = 'devlet' then null else substr(p_kaynak, 3)::bigint end;
  hb := case when p_hedef = 'devlet' then null else substr(p_hedef, 3)::bigint end;
  h := oyun.profil_bul(p_alici);
  if h.id = u then raise exception 'Kendi hesapların arasında aktarım için “Hesaplarım arası”nı kullan.'; end if;
  if h.yasakli then raise exception 'Bu oyuncunun hesabı kapatılmış.'; end if;
  m := round(coalesce(p_tutar, 0));
  if m < 100 then raise exception 'En az 100 ₺ gönderebilirsin.'; end if;
  if m > 10000000 then raise exception 'Tek işlemde en fazla 10.000.000 ₺ gönderebilirsin.'; end if;
  if oyun.uyari(p, t) is not null then raise exception 'Para göndermek için seçmen kartın hazır olmalı: %', oyun.uyari(p, t); end if;
  if (select coklu_kontrol from oyun.ayarlar where id = 1)
     and exists(select 1 from oyun.bagli_hesaplar(u) b where b = h.id) then
    raise exception 'Aynı cihazda açılmış hesaplar arasında banka transferi yapılamaz.'; end if;
  if oyun.engelli(h.id, u) then raise exception 'Bu oyuncu seni engellediği için ona para gönderemezsin.'; end if;
  perform oyun.takip_engel(u, 'banka transferi yapamazsın');

  -- Mevcut kanallar (kurallarıyla birlikte)
  if kb is null and hb is null then
    return public.para_gonder(h.kad, m, p_aciklama) || jsonb_build_object('yol', 'havale', 'kanal', 'Devlet Bankası');
  end if;
  if kb is not null and hb is not null then
    if kb = hb then
      r := public.ib_havale(kb, h.kad, m);
      return r || jsonb_build_object('yol', 'havale');
    end if;
    r := public.ib_eft(kb, hb, h.kad, m);
    return r || jsonb_build_object('yol', 'eft');
  end if;

  -- Devlet Bankası ↔ özel banka: FAST
  if nullif(btrim(coalesce(p_aciklama, '')), '') is not null then ack := oyun.metin_temizle(p_aciklama, 100); end if;
  bugun := oyun.gunluk_aktarim(u, t);
  tavan := round((select asgari from oyun.ulke where id = 1) * (select havale_sinir from oyun.ayarlar where id = 1));
  if bugun + m > tavan then
    raise exception 'Günlük para aktarma sınırı % ₺ (bugün % ₺ gönderdin).', oyun.tl(tavan), oyun.tl(bugun); end if;

  if kb is null then
    select ad into had from oyun.sirketler where id = hb and sektor = 'banka' and aktif for update;
    if had is null then raise exception 'Alıcının bankası faal değil.'; end if;
    if not oyun.oyb_hesap_acik(hb, h.id) then raise exception 'Alıcının % bankasında açık hesabı yok.', had; end if;
    perform oyun.vadesiz_isle(u, t);
    update oyun.banka_musteri set vadesiz = vadesiz - m where user_id = u and vadesiz >= m;
    if not found then raise exception 'Devlet Bankası vadesiz hesabında yeterli para yok.'; end if;
    update oyun.sirketler set kasa = kasa + m where id = hb;
    insert into oyun.ib_vadesiz(banka_id, user_id, bakiye, guncelleme) values (hb, h.id, m, t)
    on conflict (banka_id, user_id) do update set bakiye = oyun.ib_vadesiz.bakiye + excluded.bakiye, guncelleme = excluded.guncelleme;
    perform oyun.banka_kayit(u, 'vadesiz', -m, format('FAST giden: %s · %s%s', h.kad, had, coalesce(': ' || ack, '')), t);
    insert into oyun.ib_hareket(banka_id, user_id, tutar, aciklama, zaman)
    values (hb, h.id, m, format('FAST gelen: %s · Devlet Bankası%s', p.kad, coalesce(': ' || ack, '')), t);
  else
    select ad into sad from oyun.sirketler where id = kb and sektor = 'banka' and aktif for update;
    if sad is null then raise exception 'Banka faal değil.'; end if;
    if not oyun.oyb_hesap_acik(kb, u) then raise exception '% bankasında açık hesabın yok.', sad; end if;
    select bakiye into v from oyun.ib_vadesiz where banka_id = kb and user_id = u for update;
    if coalesce(v, 0) < m then raise exception 'Banka hesabında yeterli bakiye yok.'; end if;
    perform oyun.vadesiz_isle(h.id, t);
    if oyun.mevduat_toplam(h.id) + m > oyun.banka_tavani() then
      raise exception 'Alıcının Devlet Bankası mevduatı üst sınıra çok yakın.'; end if;
    update oyun.sirketler set kasa = kasa - m where id = kb and kasa >= m;
    if not found then raise exception 'Banka şu an bu ödemeyi karşılayamıyor; biraz sonra tekrar dene.'; end if;
    update oyun.ib_vadesiz set bakiye = bakiye - m, guncelleme = t where banka_id = kb and user_id = u;
    update oyun.banka_musteri set vadesiz = vadesiz + m where user_id = h.id;
    insert into oyun.ib_hareket(banka_id, user_id, tutar, aciklama, zaman)
    values (kb, u, -m, format('FAST giden: %s · Devlet Bankası%s', h.kad, coalesce(': ' || ack, '')), t);
    perform oyun.banka_kayit(h.id, 'vadesiz', m, format('FAST gelen: %s · %s%s', p.kad, sad, coalesce(': ' || ack, '')), t);
  end if;
  insert into oyun.banka_fast(gonderen, alici, kaynak_banka, hedef_banka, tutar, aciklama, zaman)
  values (u, h.id, kb, hb, m, ack, t);
  perform oyun.bildir(h.id, format('💸 %s sana FAST ile %s ₺ gönderdi (%s hesabına).%s', p.kad, oyun.tl(m),
          coalesce(had, 'Devlet Bankası'), coalesce(' Not: “' || ack || '”', '')), t);
  return jsonb_build_object('tamam', true, 'yol', 'fast', 'tutar', m, 'alici', h.kad,
                            'gunluk_kalan', greatest(0, tavan - bugun - m));
end $$;

-- Hesaplarım arası (cüzdan, Devlet Bankası, özel bankalar)
create or replace function public.banka_hesaplar_arasi(p_kaynak text, p_hedef text, p_tutar numeric)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); m numeric;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  if p_kaynak is null or (p_kaynak not in ('cuzdan','devlet') and p_kaynak !~ '^b:[0-9]+$') then raise exception 'Kaynak hesabı seç.'; end if;
  if p_hedef is null or (p_hedef not in ('cuzdan','devlet') and p_hedef !~ '^b:[0-9]+$') then raise exception 'Hedef hesabı seç.'; end if;
  if p_kaynak = p_hedef then raise exception 'Kaynak ve hedef aynı hesap olamaz.'; end if;
  m := round(coalesce(p_tutar, 0));
  if m < 1 then raise exception 'Geçerli bir tutar gir.'; end if;
  -- Kaynaktan cüzdana
  if p_kaynak = 'devlet' then perform public.banka_cek(m);
  elsif p_kaynak like 'b:%' then perform public.ib_vadesiz_islem(substr(p_kaynak, 3)::bigint, m, 'cek');
  end if;
  -- Cüzdandan hedefe
  if p_hedef = 'devlet' then perform public.banka_yatir(m);
  elsif p_hedef like 'b:%' then perform public.ib_vadesiz_islem(substr(p_hedef, 3)::bigint, m, 'yatir');
  end if;
  return jsonb_build_object('tamam', true, 'tutar', m);
end $$;

-- ---------------------------------------------------------------------
-- H. BANKA GENEL MÜDÜRLÜĞÜ (banka sahibi paneli, tek sorgu)
-- ---------------------------------------------------------------------
create or replace function public.banka_yonettiklerim()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare u uuid := auth.uid();
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'ad', s.ad, 'aktif', s.aktif,
      'renk', coalesce(bp.renk, 'lacivert'), 'yonetebilir', oyun.sirket_yonetici_mi(s.id, u),
      'not', (oyun.banka_bilanco(s.id))->'not',
      'bekleyen', (select count(*) from oyun.oyb_kredi k where k.banka_id = s.id and k.durum = 'basvuru')
                + (select count(*) from oyun.kart_basvurular b where b.banka_id = s.id and b.durum = 'bekliyor')
                + (select count(*) from oyun.sirket_pos x where x.banka_id = s.id and x.durum = 'bekliyor')) order by s.id)
    from oyun.sirketler s left join oyun.banka_politika bp on bp.banka_id = s.id
    where s.sektor = 'banka' and s.aktif
      and (s.yonetici = u or exists(select 1 from oyun.sirket_ortaklari o where o.sirket_id = s.id and o.user_id = u and o.pay > 0))), '[]'::jsonb);
end $$;

create or replace function public.banka_genel_mudurluk(p_banka bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); t timestamptz := oyun.simdi(); s oyun.sirketler; yon boolean; bp oyun.banka_politika;
  ay oyun.banka_yonetim_ayar; b jsonb;
begin
  if u is null then raise exception 'Oturum gerekli.'; end if;
  select * into s from oyun.sirketler where id = p_banka and sektor = 'banka';
  if s.id is null then raise exception 'Banka bulunamadı.'; end if;
  yon := oyun.sirket_yonetici_mi(p_banka, u);
  if not (yon or s.yonetici = u
          or exists(select 1 from oyun.sirket_ortaklari o where o.sirket_id = p_banka and o.user_id = u and o.pay > 0)
          or exists(select 1 from oyun.profiller where id = u and yonetici)) then
    raise exception 'Banka Genel Müdürlüğü''ne yalnız bankanın ortakları girebilir.'; end if;
  if not s.aktif then raise exception 'Bu banka faal değil.'; end if;
  perform oyun.banka_dibs_tahsil(p_banka);
  select * into s from oyun.sirketler where id = p_banka;
  select * into bp from oyun.banka_politika where banka_id = p_banka;
  select * into ay from oyun.banka_yonetim_ayar where banka_id = p_banka;
  b := oyun.banka_bilanco(p_banka);
  return jsonb_build_object(
    'simdi', t, 'politika_faizi', oyun.politika_faizi(),
    'banka', jsonb_build_object('id', s.id, 'ad', s.ad, 'kurulus', s.kurulus, 'sermaye', s.sermaye, 'kasa', s.kasa,
       'yonetici', oyun.kad(s.yonetici), 'yonetebilir', yon,
       'renk', coalesce(bp.renk, 'lacivert'), 'slogan', bp.slogan, 'emniyet_payi', coalesce(bp.emniyet_payi, 0),
       'risk_profili', coalesce(bp.risk_profili, 'ozel'),
       'gizlilik', coalesce((select gorunurluk from oyun.kasa_gizlilik where tur = 'sirket' and kimlik = p_banka), 'gizli'),
       'ortaklar', coalesce((select jsonb_agg(jsonb_build_object('kad', oyun.kad(o.user_id), 'pay', o.pay, 'ben', o.user_id = u,
            'kar_kasada', o.kar_kasada) order by o.pay desc) from oyun.sirket_ortaklari o where o.sirket_id = p_banka and o.pay > 0), '[]'::jsonb)),
    'bilanco', b,
    'gelir7', oyun.banka_gelir(p_banka, 7), 'gelir30', oyun.banka_gelir(p_banka, 30),
    'urunler', jsonb_build_object(
       'mevduat7', least(s.banka_faiz, 1.8), 'kredi24', least(s.banka_kredi_faiz, 1.0),
       'vadeler', jsonb_build_object('1', oyun.oyb_oran(p_banka, 1), '3', oyun.oyb_oran(p_banka, 3), '6', oyun.oyb_oran(p_banka, 6),
                                     '12', oyun.oyb_oran(p_banka, 12), '24', oyun.oyb_oran(p_banka, 24)),
       'paketler', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'ad', x.ad, 'vade_gun', x.vade_gun, 'taksit_sayisi', x.taksit_sayisi,
            'faiz', x.faiz, 'min_tutar', x.min_tutar, 'max_tutar', x.max_tutar, 'otomatik', x.otomatik, 'min_not', x.min_not, 'aktif', x.aktif,
            'kullanan', (select count(*) from oyun.oyb_kredi k where k.paket_id = x.id and k.durum in ('aktif','takip'))) order by x.vade_gun, x.id)
          from oyun.oyb_kredi_paket x where x.banka_id = p_banka and x.silindi_at is null), '[]'::jsonb),
       'pos_komisyon', 2,
       'otomatik', jsonb_build_object('pos', coalesce((select otomatik_onay from oyun.pos_banka_ayar where banka_id = p_banka), false),
                                      'kart', coalesce(ay.kart_otomatik, false), 'kredi', coalesce(ay.kredi_otomatik, false)),
       'asgari_not', coalesce(ay.asgari_not, 850), 'kart_max', coalesce(ay.kart_azami, 500000), 'kredi_max', coalesce(ay.kredi_azami, 500000)),
    'bekleyen', jsonb_build_object(
       'krediler', coalesce((select jsonb_agg(jsonb_build_object('id', k.id, 'kad', oyun.kad(k.borclu), 'anapara', k.anapara,
            'vade_gun', round(k.saat / 24.0, 1), 'taksit_sayisi', k.taksit_sayisi, 'oran', k.oran, 'toplam', k.toplam, 'basvuru', k.basvuru,
            'not', coalesce((select kredi_notu from oyun.banka_musteri where user_id = k.borclu), 1100),
            'hesap', oyun.oyb_hesap_acik(p_banka, k.borclu),
            'risk', oyun.oyb_kredi_limit(k.borclu, k.saat)) order by k.id)
          from oyun.oyb_kredi k where k.banka_id = p_banka and k.durum = 'basvuru'), '[]'::jsonb),
       'kartlar', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'kad', oyun.kad(x.user_id), 'istek', x.istek,
            'istenen', x.istenen, 'izin', x.izin, 'bilgi', case when x.izin <> '[]'::jsonb then x.bilgi else '{}'::jsonb end,
            'teklif_limit', x.teklif_limit, 'basvuru', x.basvuru, 'hesap', oyun.oyb_hesap_acik(p_banka, x.user_id),
            'kapasite', oyun.kart_kredi_kapasite(x.user_id, p_banka)) order by x.id)
          from oyun.kart_basvurular x where x.banka_id = p_banka and x.durum = 'bekliyor'), '[]'::jsonb),
       'poslar', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'sirket', z.ad, 'sektor', z.sektor,
            'kad', oyun.kad(x.basvuran), 'basvuru', x.basvuru, 'hesap', oyun.oyb_hesap_acik(p_banka, x.basvuran)) order by x.id)
          from oyun.sirket_pos x join oyun.sirketler z on z.id = x.sirket_id where x.banka_id = p_banka and x.durum = 'bekliyor'), '[]'::jsonb)),
    'musteriler', coalesce((select jsonb_agg(q.j order by q.iliski desc) from (
         select jsonb_build_object('kad', oyun.kad(h.user_id), 'acilis', h.acilis,
           'not', coalesce(bm.kredi_notu, 1100), 'not_ad', oyun.not_ad(coalesce(bm.kredi_notu, 1100)),
           'vadesiz', coalesce(v.bakiye, 0), 'vadeli', coalesce(md.tp, 0), 'kredi', coalesce(kr.tp, 0), 'kart', coalesce(kc.tp, 0),
           'teklif', (select jsonb_build_object('id', x.id, 'tutar', x.tutar, 'son', x.son) from oyun.oyb_kredi_teklifi x
                      where x.banka_id = p_banka and x.user_id = h.user_id and x.durum = 'teklif' and x.son > t limit 1),
           'bilgi', (select b2.durum from oyun.oyb_hesap_bilgi b2 where b2.banka_id = p_banka and b2.user_id = h.user_id)) j,
           coalesce(v.bakiye, 0) + coalesce(md.tp, 0) + coalesce(kr.tp, 0) + coalesce(kc.tp, 0) iliski
         from oyun.oyb_hesap h
         left join oyun.banka_musteri bm on bm.user_id = h.user_id
         left join oyun.ib_vadesiz v on v.banka_id = p_banka and v.user_id = h.user_id
         left join lateral (select sum(anapara) tp from oyun.banka_mevduat x where x.banka_id = p_banka and x.user_id = h.user_id and not x.kapandi) md on true
         left join lateral (select sum(kalan) tp from oyun.oyb_kredi x where x.banka_id = p_banka and x.borclu = h.user_id and x.durum in ('aktif','takip')) kr on true
         left join lateral (select sum(borc) tp from oyun.kredi_kartlari x where x.banka_id = p_banka and x.user_id = h.user_id) kc on true
         where h.banka_id = p_banka and h.kapanis is null and h.user_id <> u
         order by h.acilis desc limit 200) q), '[]'::jsonb),
    'krediler', coalesce((select jsonb_agg(jsonb_build_object('id', k.id, 'kad', oyun.kad(k.borclu), 'anapara', k.anapara,
         'toplam', k.toplam, 'kalan', k.kalan, 'oran', k.oran, 'vade_gun', round(k.saat / 24.0, 1), 'durum', k.durum,
         'acilis', k.acilis, 'vade', k.vade,
         'geciken', (select coalesce(sum(x.tutar - x.odenen), 0) from oyun.oyb_kredi_taksit x where x.kredi_id = k.id and x.odenen < x.tutar and x.vade < t),
         'dava_acilabilir', k.durum = 'aktif' and exists(select 1 from oyun.oyb_kredi_taksit x where x.kredi_id = k.id and x.odenen < x.tutar
                              and x.vade + interval '12 hours' <= t) and not exists(select 1 from oyun.oyb_icra i where i.kredi_id = k.id),
         'icra', (select jsonb_build_object('id', i.id, 'durum', i.durum) from oyun.oyb_icra i where i.kredi_id = k.id)) order by k.id desc)
       from oyun.oyb_kredi k where k.banka_id = p_banka and k.durum in ('aktif','takip')), '[]'::jsonb),
    'kartlar', coalesce((select jsonb_agg(jsonb_build_object('id', k.id, 'kad', oyun.kad(k.user_id), 'limit', k.limit_tl, 'borc', k.borc,
         'durum', k.durum, 'gecikmis_asgari', k.gecikmis_asgari, 'son_dort', lpad((k.id % 10000)::text, 4, '0')) order by k.borc desc)
       from oyun.kredi_kartlari k where k.banka_id = p_banka and k.durum <> 'iptal'), '[]'::jsonb),
    'dibs', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'tutar', d.tutar, 'gun', d.gun, 'oran', d.oran, 'acilis', d.acilis,
         'vade', d.vade, 'durum', d.durum, 'odenen', d.odenen, 'getiri', round(d.tutar * d.oran / 100, 2)) order by d.durum <> 'acik', d.id desc)
       from (select * from oyun.banka_dibs where banka_id = p_banka order by id desc limit 20) d), '[]'::jsonb),
    'dibs_oran', jsonb_build_object('1', oyun.banka_dibs_orani(1), '7', oyun.banka_dibs_orani(7), '30', oyun.banka_dibs_orani(30)),
    'temettuler', coalesce((select jsonb_agg(jsonb_build_object('tur', x.tur, 'brut', x.brut, 'stopaj', x.stopaj, 'net', x.net,
         'yapan', oyun.kad(x.yapan), 'zaman', x.zaman) order by x.id desc)
       from (select * from oyun.banka_temettu where banka_id = p_banka order by id desc limit 10) x), '[]'::jsonb),
    'hareketler', coalesce((select jsonb_agg(q.j order by q.z desc) from (
         (select jsonb_build_object('zaman', h.zaman, 'tutar', h.tutar, 'aciklama', h.aciklama, 'tur', 'banka') j, h.zaman z
            from oyun.sirket_hareket h where h.sirket_id = p_banka order by h.id desc limit 40)
         union all
         (select jsonb_build_object('zaman', h.zaman, 'tutar', h.tutar, 'aciklama', oyun.kad(h.user_id) || ' · ' || h.aciklama, 'tur', 'musteri'), h.zaman
            from oyun.ib_hareket h where h.banka_id = p_banka order by h.id desc limit 40)) q), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------------
-- I. ZAMANLAYICI: vadesi gelen DİBS'ler kasaya döner (sahibi paneli açmasa da)
-- ---------------------------------------------------------------------
do $cron$
begin
  if exists(select 1 from pg_extension where extname = 'pg_cron') then
    if not exists(select 1 from cron.job where jobname = 'banka-dibs-itfa') then
      perform cron.schedule('banka-dibs-itfa', '12-59/15 * * * *', 'select oyun.banka_dibs_tahsil(null)');
    end if;
  end if;
end $cron$;

-- ---------------------------------------------------------------------
-- J. CANLI FONKSİYON YAMALARI (canlı tanımı okur, tek ifadeyi değiştirir;
--    ifade yoksa atlar → iki kez çalıştırmak güvenlidir)
-- ---------------------------------------------------------------------
do $yama$
declare r record; f record; tanim text; yeni text; adet int := 0; atla text := '';
begin
  for f in
    with liste(ad, tur, takma) as (values
      ('oyb_liste','sirket','s'), ('ib_hesap_ozet','sirket','s'), ('banka_mevduat_teklif','sirket','s'),
      ('oyb_kredi_masasi','sirket','s'), ('borsa_sirket','sirket','s'), ('sirket_vitrini','sirket','s'),
      ('sirket_karnesi','sirket','s'), ('pazar_detay','sirket','s'), ('pazar_katalog','sirket','s'),
      ('eko_panel','sirket','s'), ('halka_arz_durum','sirket','s'), ('ajans_yonetim','sirket','s'),
      ('npc_isletme_panel','sirket','s'), ('sirket_finans_ozeti','sirket','s'), ('sirket_sube_finans','sirket','s'),
      ('sirket_liste','sirket','s'), ('cek_panel','sirket','s'), ('siyasi_bagislar','sirket','s'),
      ('konkordato_durum','sirket','s'), ('konkordato_ekrani','sirket','s'), ('ihale_ekrani','sirket','s'),
      ('eko_ticaret_panel','sirket','s'), ('eko_vergi_panel','sirket','s'), ('kamu_toptan_panel','sirket','s'),
      ('eko_emlak_panel','sirket','s'), ('ortak_sirket_panel','sirket','s'), ('sigorta_afet_panel','sirket','s'),
      ('sigorta_isletme_panel','sirket','s'), ('uc_etkinlik_panel','sirket','s'), ('uc_tarim_panel','sirket','s'),
      ('pos_banka_panel','sirket','b'), ('banka_yonetilen_liste','sirket','b'), ('banka_yonetim_panel','sirket','b'),
      ('dernek_detay','dernek','d'), ('dernek_faaliyetler','dernek','d'), ('dernek_program_ozet','dernek','d'),
      ('dernek_uye_destek_liste','dernek','d'), ('basin','gazete','g'))
    select l.*, p.oid from liste l join pg_proc p on p.proname = l.ad and p.pronamespace = 'public'::regnamespace
  loop
    tanim := pg_get_functiondef(f.oid);
    if tanim !~ ('(oyun\.(sirketler|dernekler|oyuncu_gazeteleri)\s+(as\s+)?' || f.takma || '\M)|(\m' || f.takma || '\s+oyun\.(sirketler|dernekler|oyuncu_gazeteleri)\M)') then
      atla := atla || f.ad || '(takma ad), '; continue;
    end if;
    yeni := regexp_replace(tanim,
      '''kasa''(\s*),(\s*)(round\(\s*)?' || f.takma || '\.kasa\M',
      '''kasa''\1,\2\3oyun.kasa_goster(''' || f.tur || ''', ' || f.takma || '.id, ' || f.takma || '.kasa)', 'g');
    if f.ad = 'oyb_kredi_masasi' then
      yeni := replace(yeni, '''kredi_verilebilir'', greatest(0, (sag->>''kredi_verilebilir'')::numeric)',
                            '''kredi_verilebilir'', oyun.kasa_goster(''sirket'', s.id, greatest(0, (sag->>''kredi_verilebilir'')::numeric))');
    elsif f.ad = 'sirket_karnesi' then
      yeni := replace(yeni, '''defter'', round(oyun.sirket_defter(s.id))',
                            '''defter'', round(oyun.kasa_goster(''sirket'', s.id, oyun.sirket_defter(s.id)))');
      yeni := replace(yeni, '''deger'', oyun.sirket_deger(s.id)',
                            '''deger'', oyun.kasa_goster(''sirket'', s.id, oyun.sirket_deger(s.id))');
    elsif f.tur = 'dernek' then
      yeni := regexp_replace(yeni, '''serbest''(\s*),(\s*)oyun\.dernek_serbest_kasa\(d\.id\)',
                                   '''serbest''\1,\2oyun.kasa_goster(''dernek'', d.id, oyun.dernek_serbest_kasa(d.id))', 'g');
    end if;
    if yeni <> tanim then execute yeni; adet := adet + 1; end if;
  end loop;

  -- Takma adı olmayan liste sorguları (from oyun.sirketler where sektor=...)
  for f in select p.oid, p.proname from pg_proc p
            where p.pronamespace = 'public'::regnamespace and p.proname in ('oyuncu_banka_liste','kart_panel','uc_kitap_panel') loop
    tanim := pg_get_functiondef(f.oid);
    yeni := replace(tanim, '''ad'',ad,''kasa'',kasa)', '''ad'',ad,''kasa'',oyun.kasa_goster(''sirket'',id,kasa))');
    yeni := replace(yeni, '''faiz'',least(banka_faiz,1.8),''kasa'',kasa)', '''faiz'',least(banka_faiz,1.8),''kasa'',oyun.kasa_goster(''sirket'',id,kasa))');
    if yeni <> tanim then execute yeni; adet := adet + 1; end if;
  end loop;

  -- Bankalarda vadesiz mevduat da borçtur: eski kâr payı fonksiyonu banka için yeni kurala yönlenir
  for f in select p.oid from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = 'sirket_kar_payi' loop
    tanim := pg_get_functiondef(f.oid);
    if position('banka_kar_dagit' in tanim) = 0 then
      yeni := regexp_replace(tanim, '(\nbegin\n)',
        E'\\1 if (select sektor from oyun.sirketler where id=p_sirket)=''banka'' then return public.banka_kar_dagit(p_sirket,p_tutar); end if;\n', '');
      if yeni <> tanim then execute yeni; adet := adet + 1; else atla := atla || 'sirket_kar_payi, '; end if;
    end if;
  end loop;

  -- Haftalık şirket hesabında banka zararı / dağıtımı vadesiz mevduatı korur
  for f in select p.oid from pg_proc p where p.pronamespace = 'oyun'::regnamespace and p.proname = 'sirket_hesapla' loop
    tanim := pg_get_functiondef(f.oid);
    yeni := replace(tanim, '(select kasa from oyun.sirketler where id=p_id)-v_taahhut-greatest(',
                           '(select kasa from oyun.sirketler where id=p_id)-v_taahhut-oyun.banka_vadesiz_toplam(p_id)-greatest(');
    yeni := replace(yeni, 'where m.banka_id=p_id and not m.kapandi),0))) else least(net',
                          'where m.banka_id=p_id and not m.kapandi),0)-oyun.banka_vadesiz_toplam(p_id))) else least(net');
    if yeni <> tanim then execute yeni; adet := adet + 1; end if;
  end loop;

  -- Devlet Bankası kredi kartı: Hazine milyar birimiyle çalışır (TL / pazar_tl_milyar)
  for f in select p.oid, p.proname from pg_proc p
            where p.pronamespace in ('public'::regnamespace, 'oyun'::regnamespace)
              and p.proname in ('kart_harca','kart_nakit_avans','kart_ode','kart_pos_iade') loop
    tanim := pg_get_functiondef(f.oid);
    yeni := regexp_replace(tanim, 'hazine\s*=\s*hazine\s*-\s*n(\s+where\s+id\s*=\s*1\s+and\s+hazine\s*>=\s*)n\M',
                                  'hazine=hazine-n/oyun.pazar_tl_milyar()\1n/oyun.pazar_tl_milyar()', 'gi');
    yeni := regexp_replace(yeni, 'hazine\s*=\s*hazine\s*\+\s*o(\s+where\s+id\s*=\s*1)', 'hazine=hazine+o/oyun.pazar_tl_milyar()\1', 'gi');
    yeni := regexp_replace(yeni, 'hazine\s*=\s*hazine\s*\+\s*karta(\s+where\s+id\s*=\s*1)', 'hazine=hazine+karta/oyun.pazar_tl_milyar()\1', 'gi');
    if yeni <> tanim then execute yeni; adet := adet + 1; end if;
  end loop;

  -- POS otomatik onayı: hesabı olmayan eski başvurular toplu onayı kilitlemesin
  for f in select p.oid from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = 'pos_banka_otomatik' loop
    tanim := pg_get_functiondef(f.oid);
    yeni := replace(tanim, E'where banka_id=p_banka and durum=''bekliyor''\n    returning basvuran',
                           E'where banka_id=p_banka and durum=''bekliyor'' and oyun.oyb_hesap_acik(p_banka,basvuran)\n    returning basvuran');
    if yeni <> tanim then execute yeni; adet := adet + 1; end if;
  end loop;

  raise notice 'bankacilik_v2 yamalari: % fonksiyon guncellendi; atlanan: %', adet, coalesce(nullif(atla, ''), 'yok');
end $yama$;

-- ---------------------------------------------------------------------
-- K. YETKİLER
-- ---------------------------------------------------------------------
do $yetki$
declare f text;
begin
  foreach f in array array[
    'public.banka_dibs_al(bigint,numeric,integer)', 'public.banka_dibs_boz(bigint,bigint)',
    'public.banka_sermaye_koy(bigint,numeric)', 'public.banka_kar_dagit(bigint,numeric)', 'public.banka_sermaye_azalt(bigint,numeric)',
    'public.banka_politika_kaydet(bigint,numeric,text,text)', 'public.banka_risk_profili(bigint,text)',
    'public.kasa_gizlilik_ayarla(text,bigint,text)', 'public.kasa_gizlilik_listem()',
    'public.banka_sube()', 'public.banka_alici(text)', 'public.banka_fast(text,text,text,numeric,text)',
    'public.banka_hesaplar_arasi(text,text,numeric)', 'public.banka_yonettiklerim()', 'public.banka_genel_mudurluk(bigint)']
  loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
  foreach f in array array[
    'oyun.kasa_goster(text,bigint,numeric)', 'oyun.kasa_yetkili(text,bigint,uuid)', 'oyun.banka_bilanco(bigint)',
    'oyun.banka_gelir(bigint,integer)', 'oyun.banka_kunye(bigint,uuid)', 'oyun.banka_dibs_tahsil(bigint)']
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
end $yetki$;

-- 2026-10-25 | Kuyumcu ve doviz burosu; mevcut oyun bakiyeleri degismez.
create table if not exists oyun.meslek_kur(
 kod text primary key check(kod in ('USD','EUR','GBP','CHF','ALTIN')),
 fiyat numeric(22,8) not null check(fiyat>0),
 kaynak text not null,
 veri_tarihi timestamptz not null,
 guncelleme timestamptz not null default now()
);
create table if not exists oyun.meslek_dukkan(
 id bigint generated always as identity primary key,
 sahibi uuid not null references auth.users(id),
 tur text not null check(tur in ('doviz','kuyumcu')),
 ad text not null check(length(ad) between 3 and 60),
 il_id smallint,
 kasa numeric(24,2) not null default 0 check(kasa>=0),
 makas numeric(6,3) not null default 1 check(makas between 0.25 and 6),
 aktif boolean not null default true,
 acilis timestamptz not null default now(),
 unique(sahibi,tur)
);
create table if not exists oyun.meslek_stok(
 dukkan_id bigint not null references oyun.meslek_dukkan(id),
 kod text not null check(kod in ('USD','EUR','GBP','CHF','ALTIN')),
 miktar numeric(24,4) not null default 0 check(miktar>=0),
 primary key(dukkan_id,kod)
);
create table if not exists oyun.meslek_portfoy(
 user_id uuid not null references auth.users(id),
 kod text not null check(kod in ('USD','EUR','GBP','CHF','ALTIN')),
 miktar numeric(24,4) not null default 0 check(miktar>=0),
 primary key(user_id,kod)
);
create table if not exists oyun.meslek_islemler(
 id bigint generated always as identity primary key,
 dukkan_id bigint not null references oyun.meslek_dukkan(id),
 user_id uuid not null references auth.users(id),
 kod text not null,
 yon text not null check(yon in ('al','sat','tedarik')),
 miktar numeric(24,4) not null check(miktar>0),
 birim_fiyat numeric(22,8) not null,
 tutar numeric(24,2) not null,
 tarih timestamptz not null default now()
);
create index if not exists meslek_islem_dukkan on oyun.meslek_islemler(dukkan_id,tarih desc);
create index if not exists meslek_islem_user on oyun.meslek_islemler(user_id,tarih desc);
do $z$ declare t text; begin
 foreach t in array array['meslek_kur','meslek_dukkan','meslek_stok','meslek_portfoy','meslek_islemler'] loop
  execute format('alter table oyun.%I enable row level security',t);
  execute format('revoke all on table oyun.%I from public,anon,authenticated',t);
 end loop;
end $z$;

-- Yalniz Edge Function sunucu anahtari bu RPC ile fiyat gunceller.
create or replace function public.meslek_kur_kaydet(p_kod text,p_fiyat numeric,p_kaynak text,p_veri_tarihi timestamptz)
returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if coalesce(auth.jwt()->>'role','') <> 'service_role' then raise exception 'Yetkisiz kur guncellemesi'; end if;
 if p_kod not in ('USD','EUR','GBP','CHF','ALTIN') or p_fiyat is null or p_fiyat<=0 or p_fiyat>100000000
  or p_kaynak not in ('TCMB','Gold-API/TCMB') or p_veri_tarihi is null
  or p_veri_tarihi>now()+interval '10 minutes' then raise exception 'Gecersiz piyasa verisi';end if;
 insert into oyun.meslek_kur(kod,fiyat,kaynak,veri_tarihi,guncelleme)
 values(p_kod,round(p_fiyat,8),p_kaynak,p_veri_tarihi,now())
 on conflict(kod) do update set fiyat=excluded.fiyat,kaynak=excluded.kaynak,
 veri_tarihi=excluded.veri_tarihi,guncelleme=now();
 return jsonb_build_object('kod',p_kod,'ok',true);
end; $$;
revoke all on function public.meslek_kur_kaydet(text,numeric,text,timestamptz) from public,anon,authenticated;
grant execute on function public.meslek_kur_kaydet(text,numeric,text,timestamptz) to service_role;

create or replace function oyun.meslek_kur_kontrol(p_kod text)
returns numeric language plpgsql stable set search_path='' as $$
declare r record;
begin
 select fiyat,guncelleme into r from oyun.meslek_kur where kod=p_kod;
 if not found then raise exception 'Piyasa kuru henuz baglanmadi. Kur guncelle butonunu kullan.';end if;
 if r.guncelleme<now()-interval '20 minutes' then raise exception 'Piyasa kuru eski. Islemden once kuru yenile.';end if;
 return r.fiyat;
end; $$;

create or replace function public.meslek_panel()
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); c numeric;
begin
 if u is null or not exists(select 1 from oyun.profiller where id=u and not yasakli) then raise exception 'Oturum gerekli';end if;
 select para into c from oyun.cuzdan where user_id=u;
 return jsonb_build_object(
  'cuzdan',coalesce(c,0),
  'kurlar',coalesce((select jsonb_agg(jsonb_build_object('kod',kod,'fiyat',fiyat,'kaynak',kaynak,'veri_tarihi',veri_tarihi,'guncelleme',guncelleme) order by kod) from oyun.meslek_kur),'[]'::jsonb),
  'dukkanlar',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'ad',d.ad,'tur',d.tur,'il_id',d.il_id,'makas',d.makas,'benim',d.sahibi=u,'kasa',case when d.sahibi=u then d.kasa else null end,'stok',(select coalesce(jsonb_object_agg(st.kod,st.miktar),'{}'::jsonb) from oyun.meslek_stok st where st.dukkan_id=d.id)) order by d.id desc) from oyun.meslek_dukkan d where d.aktif),'[]'::jsonb),
  'portfoy',coalesce((select jsonb_object_agg(kod,miktar) from oyun.meslek_portfoy where user_id=u),'{}'::jsonb),
  'islemler',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'dukkan_id',q.dukkan_id,'kod',q.kod,'yon',q.yon,'tutar',q.tutar,'miktar',q.miktar,'tarih',q.tarih)) from (select * from oyun.meslek_islemler where user_id=u or dukkan_id in(select id from oyun.meslek_dukkan where sahibi=u) order by tarih desc limit 30) q),'[]'::jsonb));
end; $$;
revoke all on function public.meslek_panel() from public,anon;
grant execute on function public.meslek_panel() to authenticated;

create or replace function public.meslek_dukkan_ac(p_tur text,p_ad text,p_sermaye numeric)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); il smallint; did bigint; bedel numeric:=5000;
begin
 if u is null or not exists(select 1 from oyun.profiller where id=u and not yasakli) then raise exception 'Giris gerekli';end if;
 if p_tur not in ('doviz','kuyumcu') or p_ad is null or length(btrim(p_ad)) not between 3 and 60 then raise exception 'Dukkan turu veya adi gecersiz';end if;
 if p_sermaye is null or p_sermaye<>trunc(p_sermaye) or p_sermaye<100000 or p_sermaye>100000000 then raise exception 'Sermaye 100.000 ile 100.000.000 TL arasinda tam sayi olmali';end if;
 if exists(select 1 from oyun.meslek_dukkan where sahibi=u and tur=p_tur) then raise exception 'Bu turde zaten dukkanin var';end if;
 perform oyun.para_islem(u,-p_sermaye,'meslek','Dukkan acma ve sermaye: '||p_ad,now());
 select il_id into il from oyun.profiller where id=u;
 insert into oyun.meslek_dukkan(sahibi,tur,ad,il_id,kasa,makas) values(u,p_tur,btrim(p_ad),il,p_sermaye-bedel,case when p_tur='doviz' then 0.7 else 1.5 end) returning id into did;
 update oyun.ulke set hazine=hazine+bedel/oyun.pazar_tl_milyar() where id=1;
 return jsonb_build_object('id',did,'kasa',p_sermaye-bedel,'ruhsat',bedel);
end; $$;
revoke all on function public.meslek_dukkan_ac(text,text,numeric) from public,anon;
grant execute on function public.meslek_dukkan_ac(text,text,numeric) to authenticated;

create or replace function public.meslek_makas_ayarla(p_dukkan bigint,p_makas numeric)
returns jsonb language plpgsql security definer set search_path='' as $$
declare d oyun.meslek_dukkan%rowtype;
begin
 select * into d from oyun.meslek_dukkan where id=p_dukkan and sahibi=auth.uid() for update;
 if not found then raise exception 'Bu dukkan sana ait degil';end if;
 if p_makas is null or p_makas<0.25 or p_makas>6 then raise exception 'Gecersiz makas orani';end if;
 if (d.tur='doviz' and p_makas>3) or (d.tur='kuyumcu' and p_makas<0.5) then raise exception 'Bu dukkan icin makas siniri disinda';end if;
 update oyun.meslek_dukkan set makas=round(p_makas,3) where id=p_dukkan;
 return jsonb_build_object('makas',round(p_makas,3));
end; $$;
revoke all on function public.meslek_makas_ayarla(bigint,numeric) from public,anon;
grant execute on function public.meslek_makas_ayarla(bigint,numeric) to authenticated;

create or replace function public.meslek_kasa(p_dukkan bigint,p_yon text,p_tutar numeric)
returns jsonb language plpgsql security definer set search_path='' as $$
declare d oyun.meslek_dukkan%rowtype;
begin
 if p_yon not in ('yatir','cek') or p_tutar is null or p_tutar<>trunc(p_tutar) or p_tutar<100 or p_tutar>100000000 then raise exception 'Gecersiz kasa islemi';end if;
 select * into d from oyun.meslek_dukkan where id=p_dukkan and sahibi=auth.uid() and aktif for update;
 if not found then raise exception 'Dukkan yetkin yok';end if;
 if p_yon='yatir' then
  perform oyun.para_islem(auth.uid(),-p_tutar,'meslek','Dukkan kasasina sermaye',now());
  update oyun.meslek_dukkan set kasa=kasa+p_tutar where id=d.id;
 else
  if d.kasa<p_tutar then raise exception 'Kasada yeterli para yok';end if;
  update oyun.meslek_dukkan set kasa=kasa-p_tutar where id=d.id;
  perform oyun.para_islem(auth.uid(),p_tutar,'meslek','Dukkan kasasindan aktarim',now());
 end if;
 return jsonb_build_object('kasa',(select kasa from oyun.meslek_dukkan where id=d.id));
end; $$;
revoke all on function public.meslek_kasa(bigint,text,numeric) from public,anon;
grant execute on function public.meslek_kasa(bigint,text,numeric) to authenticated;

create or replace function public.meslek_stok_tedarik(p_dukkan bigint,p_kod text,p_miktar numeric)
returns jsonb language plpgsql security definer set search_path='' as $$
declare d oyun.meslek_dukkan%rowtype; fiyat numeric; tutar numeric;
begin
 if p_miktar is null or p_miktar<=0 or p_miktar>100000 or p_miktar<>round(p_miktar,4) then raise exception 'Miktar 0-100.000 arasinda, en cok 4 ondalik olmali';end if;
 select * into d from oyun.meslek_dukkan where id=p_dukkan and sahibi=auth.uid() and aktif for update;
 if not found then raise exception 'Dukkan yetkin yok';end if;
 if not ((d.tur='doviz' and p_kod in ('USD','EUR','GBP','CHF')) or (d.tur='kuyumcu' and p_kod='ALTIN')) then raise exception 'Bu urun dukkaninda satilamaz';end if;
 fiyat:=oyun.meslek_kur_kontrol(p_kod);
 tutar:=ceil(p_miktar*fiyat*1.001);
 if d.kasa<tutar then raise exception 'Tedarik icin dukkan kasasinda % TL olmali',tutar;end if;
 update oyun.meslek_dukkan set kasa=kasa-tutar where id=d.id;
 insert into oyun.meslek_stok(dukkan_id,kod,miktar) values(d.id,p_kod,p_miktar)
 on conflict(dukkan_id,kod) do update set miktar=oyun.meslek_stok.miktar+excluded.miktar;
 insert into oyun.meslek_islemler(dukkan_id,user_id,kod,yon,miktar,birim_fiyat,tutar) values(d.id,auth.uid(),p_kod,'tedarik',p_miktar,fiyat,tutar);
 return jsonb_build_object('stok',p_miktar,'odenen',tutar);
end; $$;
revoke all on function public.meslek_stok_tedarik(bigint,text,numeric) from public,anon;
grant execute on function public.meslek_stok_tedarik(bigint,text,numeric) to authenticated;

create or replace function public.meslek_ticaret(p_dukkan bigint,p_kod text,p_yon text,p_miktar numeric)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); d oyun.meslek_dukkan%rowtype; fiyat numeric; birim numeric; tutar numeric; mevcut numeric;
begin
 if u is null or not exists(select 1 from oyun.profiller where id=u and not yasakli) then raise exception 'Giris gerekli';end if;
 if p_yon not in ('al','sat') or p_miktar is null or p_miktar<=0 or p_miktar>100000 or p_miktar<>round(p_miktar,4) then raise exception 'Gecersiz islem miktari';end if;
 select * into d from oyun.meslek_dukkan where id=p_dukkan and aktif for update;
 if not found then raise exception 'Dukkan bulunamadi';end if;
 if d.sahibi=u then raise exception 'Kendi dukkanindan kendine alis-satis yapamazsin';end if;
 if not ((d.tur='doviz' and p_kod in ('USD','EUR','GBP','CHF')) or (d.tur='kuyumcu' and p_kod='ALTIN')) then raise exception 'Urun bu dukkanda islem gormuyor';end if;
 fiyat:=oyun.meslek_kur_kontrol(p_kod);
 birim:=round(fiyat*(case when p_yon='al' then 1+d.makas/100 else 1-d.makas/100 end),8);
 tutar:=case when p_yon='al' then ceil(birim*p_miktar) else floor(birim*p_miktar) end;
 if tutar<100 then raise exception 'Islem tutari en az 100 TL olmali';end if;
 insert into oyun.meslek_stok(dukkan_id,kod,miktar) values(d.id,p_kod,0) on conflict do nothing;
 insert into oyun.meslek_portfoy(user_id,kod,miktar) values(u,p_kod,0) on conflict do nothing;
 select miktar into mevcut from oyun.meslek_stok where dukkan_id=d.id and kod=p_kod for update;
 perform 1 from oyun.meslek_portfoy where user_id=u and kod=p_kod for update;
 if p_yon='al' then
  if mevcut<p_miktar then raise exception 'Dukkanda yeterli stok yok';end if;
  perform oyun.para_islem(u,-tutar,'meslek','Dukkandan '||p_kod||' alimi',now());
  update oyun.meslek_stok set miktar=miktar-p_miktar where dukkan_id=d.id and kod=p_kod;
  update oyun.meslek_portfoy set miktar=miktar+p_miktar where user_id=u and kod=p_kod;
  update oyun.meslek_dukkan set kasa=kasa+tutar where id=d.id;
 else
  if (select miktar from oyun.meslek_portfoy where user_id=u and kod=p_kod)<p_miktar then raise exception 'Portfoyunde yeterli varlik yok';end if;
  if d.kasa<tutar then raise exception 'Dukkan kasasi bu alim icin yetersiz';end if;
  update oyun.meslek_portfoy set miktar=miktar-p_miktar where user_id=u and kod=p_kod;
  update oyun.meslek_stok set miktar=miktar+p_miktar where dukkan_id=d.id and kod=p_kod;
  update oyun.meslek_dukkan set kasa=kasa-tutar where id=d.id;
  perform oyun.para_islem(u,tutar,'meslek','Dukkana '||p_kod||' satisi',now());
 end if;
 insert into oyun.meslek_islemler(dukkan_id,user_id,kod,yon,miktar,birim_fiyat,tutar) values(d.id,u,p_kod,p_yon,p_miktar,birim,tutar);
 return jsonb_build_object('yon',p_yon,'kod',p_kod,'miktar',p_miktar,'birim',birim,'tutar',tutar,'dukkan',d.ad);
end; $$;
revoke all on function public.meslek_ticaret(bigint,text,text,numeric) from public,anon;
grant execute on function public.meslek_ticaret(bigint,text,text,numeric) to authenticated;
-- 2026-10-25 | Seffaf islem komisyonu, kasa ve stok korumasini bozmaz.
alter table oyun.meslek_dukkan add column if not exists komisyon_orani numeric(5,3) not null default 0.35
 check (komisyon_orani between 0 and 2);
alter table oyun.meslek_islemler add column if not exists komisyon numeric(24,2) not null default 0
 check (komisyon>=0);

create or replace function public.meslek_komisyon_ayarla(p_dukkan bigint,p_oran numeric)
returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if p_oran is null or p_oran<0 or p_oran>2 then raise exception 'Komisyon orani 0 ile 2 yuzde arasinda olmali';end if;
 update oyun.meslek_dukkan set komisyon_orani=round(p_oran,3)
 where id=p_dukkan and sahibi=auth.uid() and aktif;
 if not found then raise exception 'Bu dukkan sana ait degil';end if;
 return jsonb_build_object('komisyon',round(p_oran,3));
end; $$;
revoke all on function public.meslek_komisyon_ayarla(bigint,numeric) from public,anon;
grant execute on function public.meslek_komisyon_ayarla(bigint,numeric) to authenticated;

create or replace function public.meslek_panel()
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); c numeric;
begin
 if u is null or not exists(select 1 from oyun.profiller where id=u and not yasakli) then raise exception 'Oturum gerekli';end if;
 select para into c from oyun.cuzdan where user_id=u;
 return jsonb_build_object(
  'cuzdan',coalesce(c,0),
  'kurlar',coalesce((select jsonb_agg(jsonb_build_object('kod',kod,'fiyat',fiyat,'kaynak',kaynak,'veri_tarihi',veri_tarihi,'guncelleme',guncelleme) order by kod) from oyun.meslek_kur),'[]'::jsonb),
  'dukkanlar',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'ad',d.ad,'tur',d.tur,'il_id',d.il_id,'makas',d.makas,'komisyon',d.komisyon_orani,'benim',d.sahibi=u,'kasa',case when d.sahibi=u then d.kasa else null end,'stok',(select coalesce(jsonb_object_agg(st.kod,st.miktar),'{}'::jsonb) from oyun.meslek_stok st where st.dukkan_id=d.id)) order by d.id desc) from oyun.meslek_dukkan d where d.aktif),'[]'::jsonb),
  'portfoy',coalesce((select jsonb_object_agg(kod,miktar) from oyun.meslek_portfoy where user_id=u),'{}'::jsonb),
  'islemler',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'dukkan_id',q.dukkan_id,'kod',q.kod,'yon',q.yon,'tutar',q.tutar,'miktar',q.miktar,'tarih',q.tarih)) from (select * from oyun.meslek_islemler where user_id=u or dukkan_id in(select id from oyun.meslek_dukkan where sahibi=u) order by tarih desc limit 30) q),'[]'::jsonb));
end; $$;

create or replace function public.meslek_ticaret(p_dukkan bigint,p_kod text,p_yon text,p_miktar numeric)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); d oyun.meslek_dukkan%rowtype; fiyat numeric; birim numeric; tutar numeric; mevcut numeric; brut numeric; kom numeric;
begin
 if u is null or not exists(select 1 from oyun.profiller where id=u and not yasakli) then raise exception 'Giris gerekli';end if;
 if p_yon not in ('al','sat') or p_miktar is null or p_miktar<=0 or p_miktar>100000 or p_miktar<>round(p_miktar,4) then raise exception 'Gecersiz islem miktari';end if;
 select * into d from oyun.meslek_dukkan where id=p_dukkan and aktif for update;
 if not found then raise exception 'Dukkan bulunamadi';end if;
 if d.sahibi=u then raise exception 'Kendi dukkanindan kendine alis-satis yapamazsin';end if;
 if not ((d.tur='doviz' and p_kod in ('USD','EUR','GBP','CHF')) or (d.tur='kuyumcu' and p_kod='ALTIN')) then raise exception 'Urun bu dukkanda islem gormuyor';end if;
 fiyat:=oyun.meslek_kur_kontrol(p_kod);
 birim:=round(fiyat*(case when p_yon='al' then 1+d.makas/100 else 1-d.makas/100 end),8);
 brut:=case when p_yon='al' then ceil(birim*p_miktar) else floor(birim*p_miktar) end;
 kom:=ceil(brut*d.komisyon_orani/100);
 tutar:=case when p_yon='al' then brut+kom else greatest(0,brut-kom) end;
 if tutar<100 then raise exception 'Islem tutari en az 100 TL olmali';end if;
 insert into oyun.meslek_stok(dukkan_id,kod,miktar) values(d.id,p_kod,0) on conflict do nothing;
 insert into oyun.meslek_portfoy(user_id,kod,miktar) values(u,p_kod,0) on conflict do nothing;
 select miktar into mevcut from oyun.meslek_stok where dukkan_id=d.id and kod=p_kod for update;
 perform 1 from oyun.meslek_portfoy where user_id=u and kod=p_kod for update;
 if p_yon='al' then
  if mevcut<p_miktar then raise exception 'Dukkanda yeterli stok yok';end if;
  perform oyun.para_islem(u,-tutar,'meslek','Dukkandan '||p_kod||' alimi',now());
  update oyun.meslek_stok set miktar=miktar-p_miktar where dukkan_id=d.id and kod=p_kod;
  update oyun.meslek_portfoy set miktar=miktar+p_miktar where user_id=u and kod=p_kod;
  update oyun.meslek_dukkan set kasa=kasa+tutar where id=d.id;
 else
  if (select miktar from oyun.meslek_portfoy where user_id=u and kod=p_kod)<p_miktar then raise exception 'Portfoyunde yeterli varlik yok';end if;
  if d.kasa<tutar then raise exception 'Dukkan kasasi bu alim icin yetersiz';end if;
  update oyun.meslek_portfoy set miktar=miktar-p_miktar where user_id=u and kod=p_kod;
  update oyun.meslek_stok set miktar=miktar+p_miktar where dukkan_id=d.id and kod=p_kod;
  update oyun.meslek_dukkan set kasa=kasa-tutar where id=d.id;
  perform oyun.para_islem(u,tutar,'meslek','Dukkana '||p_kod||' satisi',now());
 end if;
 insert into oyun.meslek_islemler(dukkan_id,user_id,kod,yon,miktar,birim_fiyat,tutar,komisyon) values(d.id,u,p_kod,p_yon,p_miktar,birim,tutar,kom);
 return jsonb_build_object('yon',p_yon,'kod',p_kod,'miktar',p_miktar,'birim',birim,'tutar',tutar,'komisyon',kom,'dukkan',d.ad);
end; $$;
-- Kişisel yatırım kasası. Mevcut pozisyonları taşımadan veya nakde çevirmeden okur.
create or replace function public.yatirim_kasam() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare u uuid := auth.uid(); a jsonb; nakit numeric;
begin
 if u is null or not exists(select 1 from oyun.profiller where id=u and not yasakli) then
  raise exception 'Oturum gerekli';
 end if;
 perform oyun.piyasa_guncelle();
 select para into nakit from oyun.cuzdan where user_id=u;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.kaynak,x.ad),'[]'::jsonb) into a from (
  select 'piyasa'::text kaynak, p.kod, v.ad, v.sinif, p.miktar,
   v.fiyat, round(p.miktar*v.fiyat,2) deger, p.maliyet,
   round(p.miktar*v.fiyat-p.maliyet,2) kar, v.aktif islem_acik,
   v.saat fiyat_zamani, false eski, null::bigint sirket_id,
   'Yatırım borsası'::text aciklama
  from oyun.piyasa_pozisyon p join oyun.piyasa_varlik v using(kod) where p.user_id=u and p.miktar>0
  union all
  select 'carsi',p.kod,case p.kod when 'ALTIN' then 'Gram altın' else p.kod end,
   case when p.kod='ALTIN' then 'altin' else 'doviz' end,p.miktar,k.fiyat,
   round(p.miktar*k.fiyat,2),null::numeric,null::numeric,
   coalesce(k.guncelleme>=now()-interval '20 minutes',false),k.guncelleme,
   coalesce(k.guncelleme<now()-interval '20 minutes',true),null::bigint,'Kuyumcu / döviz ofisi'
  from oyun.meslek_portfoy p left join oyun.meslek_kur k using(kod) where p.user_id=u and p.miktar>0
  union all
  select 'sirket',s.id::text,s.ad,'hisse',o.pay,
   case when s.aktif then oyun.borsa_son_fiyat(s.id) else null end,
   case when s.aktif then round(o.pay*oyun.borsa_son_fiyat(s.id),2) else null end,
   null::numeric,null::numeric,s.aktif and s.halka_acik,null::timestamptz,false,s.id,
   case when not s.aktif then 'Şirket faal değil; değer hesaplanmadı' when s.halka_acik then 'Borsada işlem gören şirket payı' else 'Halka açık olmayan şirket payı; tahmini değer' end
  from oyun.sirket_ortaklari o join oyun.sirketler s on s.id=o.sirket_id where o.user_id=u and o.pay>0
 ) x;
 return jsonb_build_object('nakit',coalesce(nakit,0),'varliklar',a,'zaman',now(),
  'yatirim_degeri',(select coalesce(sum((v->>'deger')::numeric),0) from jsonb_array_elements(a) v),
  'eksik_deger',(select count(*) from jsonb_array_elements(a) v where v->>'deger' is null));
end $$;
revoke all on function public.yatirim_kasam() from public,anon;
grant execute on function public.yatirim_kasam() to authenticated;
-- =====================================================================
--  139 · İLAN MEYDANI (25.10.2026)
--  Oyuncudan oyuncuya ilan pazarı: konut, işyeri, arsa, satılık şirket,
--  şirket hissesi. İlan ücreti ve öne çıkarma paketleri Hazine'ye gelir
--  yazılır. Alıcı "Hemen al" der ya da teklif verir; teklif tutarı
--  Güvenli Ödeme ile bloke edilir (emanet), satıcı kabul edince devir
--  anında tamamlanır, ret / süre dolumu / ilan kapanışında iade edilir.
--  Devir kuralları mevcut pazarlarla aynı: tapu harcı alıcı %2 + satıcı
--  %2, şirket devrinde damga vergisi, icra / konkordato / ilişkili hesap
--  / MASAK kontrolleri (ticaret_devir_kayit tetikleyicileri), fiyat
--  bantları (emlakta il rayicinin %40–%400'ü, şirkette pay bandı).
--  Eski "satılık şirket" ilanları (sirketler.satilik) İlan Meydanı ile
--  eşlenir: mevcutlar ücretsiz aktarılır, eski ekrandan verilen ilan da
--  buraya düşer. Oyuncu bakiyelerine dokunmaz; yalnız yeni tablo /
--  fonksiyon ekler. İki kez çalıştırmak güvenlidir.
-- =====================================================================

-- ---------------------------------------------------------------------
-- A. TABLOLAR
-- ---------------------------------------------------------------------
create table if not exists oyun.ilan_ayar (
  kod text primary key,
  ad text not null,
  tutar numeric not null check (tutar >= 0),
  gun integer not null default 0 check (gun >= 0),
  aciklama text,
  sira integer not null default 0
);
insert into oyun.ilan_ayar(kod, ad, tutar, gun, aciklama, sira) values
  ('ilan_emlak',  'Emlak ilanı',            750, 30, 'Konut, işyeri ve arsa ilanı 30 gün yayında kalır.', 1),
  ('ilan_hisse',  'Şirket hissesi ilanı',  1000, 30, 'Şirket hissesi ilanı 30 gün yayında kalır.', 2),
  ('ilan_sirket', 'Satılık şirket ilanı',  2000, 30, 'Şirketin tamamı için ilan 30 gün yayında kalır.', 3),
  ('vitrin',      'Vitrin',                3000,  3, 'İlan Meydanı açılışındaki vitrinde fotoğraflı kart olarak görünür.', 10),
  ('ust_sira',    'Üst sıra',              1500,  3, 'Kategori ve arama sonuçlarında ilanların en üstünde durur.', 11),
  ('acil',        'Acil satılık',           750,  7, 'Kırmızı "Acil" etiketi alır, Acil ilanlar listesinde görünür.', 12),
  ('renkli',      'Renkli çerçeve',         500,  7, 'Listede renkli çerçeve ve kalın başlıkla dikkat çeker.', 13),
  ('yukari',      'Yukarı taşı',            300,  0, 'İlan yeni verilmiş gibi listenin başına taşınır (tek sefer).', 14)
on conflict (kod) do nothing;

create table if not exists oyun.ilanlar (
  id bigint generated by default as identity primary key,
  kategori text not null check (kategori in ('konut','isyeri','arsa','sirket','hisse')),
  varlik text not null check (varlik in ('tapu','bolum','sirket','hisse')),
  varlik_id bigint not null,
  pay numeric check (pay is null or (pay > 0 and pay <= 100)),
  satici uuid not null references oyun.profiller(id),
  baslik text not null check (char_length(baslik) between 5 and 70),
  aciklama text check (aciklama is null or char_length(aciklama) <= 1200),
  fiyat numeric not null check (fiyat >= 1000 and fiyat <= 1000000000 and fiyat = round(fiyat)),
  ilk_fiyat numeric not null,
  onceki_fiyat numeric,
  pazarlik boolean not null default true,
  mali_goster boolean not null default false,
  il_id smallint references oyun.iller(id),
  sektor text,
  durum text not null default 'yayinda' check (durum in ('yayinda','satildi','kaldirildi','suresi_doldu','gecersiz')),
  kaynak text not null default 'oyuncu' check (kaynak in ('oyuncu','aktarim')),
  olusturma timestamptz not null default now(),
  siralama timestamptz not null default now(),
  bitis timestamptz not null,
  kapanis timestamptz,
  alici uuid references oyun.profiller(id),
  satis_bedeli numeric,
  vitrin_bitis timestamptz,
  ust_bitis timestamptz,
  acil_bitis timestamptz,
  renkli_bitis timestamptz,
  goruntulenme integer not null default 0
);
create unique index if not exists ilanlar_tek_yayinda on oyun.ilanlar(varlik, varlik_id, satici) where durum = 'yayinda';
create index if not exists ilanlar_yayinda_idx on oyun.ilanlar(kategori, siralama desc) where durum = 'yayinda';
create index if not exists ilanlar_satici_idx on oyun.ilanlar(satici, olusturma desc);

create table if not exists oyun.ilan_teklifler (
  id bigint generated by default as identity primary key,
  ilan_id bigint not null references oyun.ilanlar(id),
  alici uuid not null references oyun.profiller(id),
  tutar numeric not null check (tutar >= 1000 and tutar = round(tutar)),
  karsi numeric check (karsi is null or (karsi > 0 and karsi = round(karsi))),
  emanet numeric not null default 0 check (emanet >= 0),
  not_metni text check (not_metni is null or char_length(not_metni) <= 280),
  durum text not null default 'bekliyor' check (durum in ('bekliyor','karsi','kabul','red','geri_cekildi','suresi_doldu','kapandi')),
  olusturma timestamptz not null default now(),
  bitis timestamptz not null,
  sonuc timestamptz
);
create unique index if not exists ilan_teklif_tek on oyun.ilan_teklifler(ilan_id, alici) where durum in ('bekliyor','karsi');
create index if not exists ilan_teklif_alici_idx on oyun.ilan_teklifler(alici, olusturma desc);
create index if not exists ilan_teklif_ilan_idx on oyun.ilan_teklifler(ilan_id, olusturma desc);

create table if not exists oyun.ilan_favori (
  user_id uuid not null references oyun.profiller(id),
  ilan_id bigint not null references oyun.ilanlar(id),
  zaman timestamptz not null default now(),
  primary key (user_id, ilan_id)
);
create table if not exists oyun.ilan_bakan (
  ilan_id bigint not null references oyun.ilanlar(id),
  user_id uuid not null references oyun.profiller(id),
  zaman timestamptz not null default now(),
  primary key (ilan_id, user_id)
);
create table if not exists oyun.ilan_odeme (
  id bigint generated by default as identity primary key,
  ilan_id bigint not null references oyun.ilanlar(id),
  user_id uuid not null references oyun.profiller(id),
  kod text not null,
  tutar numeric not null,
  zaman timestamptz not null default now()
);

alter table oyun.ilan_ayar enable row level security;
alter table oyun.ilanlar enable row level security;
alter table oyun.ilan_teklifler enable row level security;
alter table oyun.ilan_favori enable row level security;
alter table oyun.ilan_bakan enable row level security;
alter table oyun.ilan_odeme enable row level security;

-- ---------------------------------------------------------------------
-- B. YARDIMCI FONKSİYONLAR
-- ---------------------------------------------------------------------
create or replace function oyun.ilan_no(p_id bigint) returns bigint
language sql immutable set search_path = '' as $$ select 1000000 + p_id $$;

create or replace function oyun.ilan_tarih(p_t timestamptz) returns text
language sql stable set search_path = '' as $$
  select to_char(p_t at time zone 'Europe/Istanbul', 'DD.MM.YYYY')
$$;

create or replace function oyun.ilan_harc(p_varlik text, p_bedel numeric) returns numeric
language sql immutable set search_path = '' as $$
  select case when p_varlik in ('tapu','bolum') then round(coalesce(p_bedel, 0) * 0.02) else 0 end
$$;

create or replace function oyun.ilan_sektor_ad(p_k text) returns text
language sql immutable set search_path = '' as $$
  select case p_k
    when 'ajans' then 'Reklam ajansı' when 'akaryakit' then 'Akaryakıt' when 'banka' then 'Banka'
    when 'danismanlik' then 'Danışmanlık' when 'e_ticaret' then 'E-ticaret' when 'elektronik_magaza' then 'Elektronik mağazası'
    when 'enerji' then 'Enerji' when 'insaat' then 'İnşaat' when 'lojistik' then 'Lojistik' when 'market' then 'Market'
    when 'medya' then 'Medya' when 'oto_galeri' then 'Oto galeri' when 'oto_servis' then 'Oto servis'
    when 'ozel_hastane' then 'Özel hastane' when 'ozel_okul' then 'Özel okul' when 'sanayi' then 'Sanayi'
    when 'tarim' then 'Tarım' when 'teknoloji' then 'Teknoloji' when 'ticaret' then 'Ticaret' when 'turizm' then 'Turizm'
    when 'ulasim' then 'Ulaşım'
    else initcap(replace(coalesce(p_k, ''), '_', ' ')) end
$$;

create or replace function oyun.ilan_tip_ad(p_tip text) returns text
language sql immutable set search_path = '' as $$
  select case p_tip when 'daire' then 'Daire' when 'dukkan' then 'Dükkân' when 'arsa' then 'Arsa'
                    when 'sirket' then 'Şirket' when 'hisse' then 'Şirket hissesi' else p_tip end
$$;

create or replace function oyun.ilan_pay_yaz(p_pay numeric) returns text
language sql immutable set search_path = '' as $$
  select '%' || replace(trim_scale(round(p_pay, 2))::text, '.', ',')
$$;

-- Şirketin il bilgisi: merkez kaydı, yoksa en büyük ortağın ili
create or replace function oyun.ilan_sirket_il(p_sirket bigint) returns smallint
language sql stable set search_path = '' as $$
  select coalesce(
    (select m.il_id from oyun.sirket_merkezleri m where m.sirket_id = p_sirket limit 1),
    (select p.il_id from oyun.profiller p where p.id = oyun.sirket_sahibi(p_sirket)))
$$;

-- Satıcının ilana çıkarabileceği pay (borsa emirleri, eski hisse ilanları ve diğer ilanları düşülür)
create or replace function oyun.ilan_kullanilabilir_pay(p_sirket bigint, p_user uuid, p_haric bigint default null)
returns numeric language plpgsql stable set search_path = '' as $$
declare v_pay numeric; v_borsa numeric := 0; v_eski numeric; v_ilan numeric;
begin
  select o.pay into v_pay from oyun.sirket_ortaklari o where o.sirket_id = p_sirket and o.user_id = p_user;
  if v_pay is null then return 0; end if;
  if to_regclass('oyun.borsa_emir') is not null then
    execute 'select coalesce(sum(kalan),0) from oyun.borsa_emir where sirket_id=$1 and satici=$2 and durum=''acik'''
      into v_borsa using p_sirket, p_user;
  end if;
  select coalesce(sum(h.pay), 0) into v_eski from oyun.sirket_hisse_ilanlari h
   where h.sirket_id = p_sirket and h.satici = p_user and h.durum = 'acik';
  select coalesce(sum(i.pay), 0) into v_ilan from oyun.ilanlar i
   where i.varlik = 'hisse' and i.varlik_id = p_sirket and i.satici = p_user and i.durum = 'yayinda'
     and i.id is distinct from p_haric;
  return greatest(0, v_pay - coalesce(v_borsa, 0) - v_eski - v_ilan);
end $$;

-- Fiyat bandı: emlakta il rayicinin %40–%400'ü; şirket ve hissede pay bandı (kasa ve sermayeye göre)
create or replace function oyun.ilan_bant(p_varlik text, p_id bigint, p_pay numeric,
  out alt numeric, out ust numeric, out rayic numeric)
language plpgsql stable set search_path = '' as $$
declare v_il smallint; v_tip text; v_b record; v_carpan numeric;
begin
  if p_varlik = 'tapu' then
    select tp.il_id, tp.tip into v_il, v_tip from oyun.yatirim_pazar_tapu tp where tp.id = p_id;
  elsif p_varlik = 'bolum' then
    select y.il_id, bo.tur into v_il, v_tip from oyun.eko_bolumler bo join oyun.eko_yapilar y on y.id = bo.yapi_id where bo.id = p_id;
  end if;
  if p_varlik in ('tapu','bolum') then
    rayic := oyun.yatirim_pazar_fiyat(v_il, v_tip);
    alt := round(rayic * 0.4); ust := round(rayic * 4);
  elsif oyun.bant_acik() then
    select * into v_b from oyun.pay_bandi(p_id);
    v_carpan := case when p_varlik = 'sirket' then 100 else coalesce(p_pay, 0) end;
    alt := round(coalesce(v_b.alt, 0) * v_carpan); ust := round(coalesce(v_b.ust, 0) * v_carpan);
  else
    alt := 1000; ust := 1000000000;
  end if;
  alt := greatest(1000, coalesce(alt, 1000));
  ust := least(1000000000, greatest(alt, coalesce(ust, 1000000000)));
end $$;

-- İlan hâlâ geçerli mi? (varlık satıcıda mı, satılabilir mi)
create or replace function oyun.ilan_gecerli(p_ilan bigint) returns boolean
language plpgsql stable set search_path = '' as $$
declare i oyun.ilanlar;
begin
  select * into i from oyun.ilanlar where id = p_ilan;
  if i.id is null then return false; end if;
  if exists (select 1 from oyun.profiller p where p.id = i.satici and p.yasakli
             and (p.engel_bitis is null or p.engel_bitis > oyun.simdi())) then return false; end if;
  if i.varlik = 'tapu' then
    return exists (select 1 from oyun.yatirim_pazar_tapu tp where tp.id = i.varlik_id and tp.sahip = i.satici);
  elsif i.varlik = 'bolum' then
    return exists (select 1 from oyun.eko_bolumler b where b.id = i.varlik_id and b.sahibi = i.satici)
       and not exists (select 1 from oyun.eko_subeler sb where sb.bolum_id = i.varlik_id and sb.aktif);
  elsif i.varlik = 'sirket' then
    return exists (select 1 from oyun.sirketler s where s.id = i.varlik_id and s.aktif and s.sektor <> 'banka')
       and exists (select 1 from oyun.sirket_ortaklari o where o.sirket_id = i.varlik_id and o.user_id = i.satici and o.pay = 100);
  else
    return exists (select 1 from oyun.sirketler s where s.id = i.varlik_id and s.aktif and s.sektor <> 'banka')
       and oyun.ilan_kullanilabilir_pay(i.varlik_id, i.satici, i.id) >= i.pay;
  end if;
end $$;

-- Listede görünen kısa ilan kartı
create or replace function oyun.ilan_ozet(p_id bigint, p_u uuid) returns jsonb
language plpgsql stable set search_path = '' as $$
declare i oyun.ilanlar; v_t timestamptz := oyun.simdi(); v_oz text; v_gorsel text; v_il text; v_kad text;
begin
  select * into i from oyun.ilanlar where id = p_id;
  if i.id is null then return null; end if;
  select x.ad into v_il from oyun.iller x where x.id = i.il_id;
  select pr.kad into v_kad from oyun.profiller pr where pr.id = i.satici;
  if i.varlik = 'tapu' then
    select tp.tip, concat_ws(' · ', tp.alan_m2 || ' m²',
             case when tp.haftalik_kira > 0 then 'haftalık kira ' || oyun.tl(tp.haftalik_kira) || ' ₺' end)
      into v_gorsel, v_oz from oyun.yatirim_pazar_tapu tp where tp.id = i.varlik_id;
  elsif i.varlik = 'bolum' then
    select bo.tur, concat_ws(' · ', bo.alan_m2 || ' m²', y.ad)
      into v_gorsel, v_oz from oyun.eko_bolumler bo join oyun.eko_yapilar y on y.id = bo.yapi_id where bo.id = i.varlik_id;
  elsif i.varlik = 'sirket' then
    v_gorsel := 'sirket'; v_oz := concat_ws(' · ', oyun.ilan_sektor_ad(i.sektor), 'şirketin tamamı');
  else
    v_gorsel := 'hisse'; v_oz := concat_ws(' · ', oyun.ilan_sektor_ad(i.sektor), oyun.ilan_pay_yaz(i.pay) || ' hisse');
  end if;
  return jsonb_build_object(
    'id', i.id, 'no', oyun.ilan_no(i.id), 'kategori', i.kategori, 'varlik', i.varlik, 'baslik', i.baslik,
    'fiyat', i.fiyat, 'dustu', coalesce(i.onceki_fiyat > i.fiyat, false), 'il', v_il, 'il_id', i.il_id,
    'tarih', i.olusturma, 'siralama', i.siralama, 'sektor', i.sektor, 'pay', i.pay, 'satici', v_kad,
    'benim', i.satici = p_u, 'acil', coalesce(i.acil_bitis > v_t, false), 'vitrin', coalesce(i.vitrin_bitis > v_t, false),
    'ust', coalesce(i.ust_bitis > v_t, false), 'renkli', coalesce(i.renkli_bitis > v_t, false),
    'gorsel', coalesce(v_gorsel, i.varlik), 'ozellik', v_oz, 'pazarlik', i.pazarlik, 'durum', i.durum,
    'bitis', i.bitis, 'goruntulenme', i.goruntulenme, 'kaynak', i.kaynak, 'satis_bedeli', i.satis_bedeli);
end $$;

-- Teklifi kapat ve emanetini iade et
create or replace function oyun.ilan_teklif_kapat(p_teklif bigint, p_durum text, p_mesaj text default null)
returns void language plpgsql security definer set search_path = '' as $$
declare tk oyun.ilan_teklifler; v_t timestamptz := oyun.simdi();
begin
  select * into tk from oyun.ilan_teklifler where id = p_teklif for update;
  if tk.id is null or tk.durum not in ('bekliyor','karsi') then return; end if;
  if tk.emanet > 0 then
    perform oyun.para_islem(tk.alici, tk.emanet, 'iade',
      format('İlan #%s: teklif emaneti iade edildi', oyun.ilan_no(tk.ilan_id)), v_t);
  end if;
  update oyun.ilan_teklifler set durum = p_durum, emanet = 0, sonuc = v_t where id = tk.id;
  if p_mesaj is not null then perform oyun.bildir(tk.alici, p_mesaj, v_t); end if;
end $$;

-- İlanı kapat (kaldırıldı / süresi doldu / geçersiz); açık teklifler iade edilir
create or replace function oyun.ilan_kapat(p_ilan bigint, p_durum text, p_bildir boolean default true)
returns void language plpgsql security definer set search_path = '' as $$
declare i oyun.ilanlar; r record; v_t timestamptz := oyun.simdi(); v_mesaj text;
begin
  select * into i from oyun.ilanlar where id = p_ilan for update;
  if i.id is null or i.durum <> 'yayinda' then return; end if;
  update oyun.ilanlar set durum = p_durum, kapanis = v_t where id = i.id;
  v_mesaj := format('“%s” ilanı yayından kalktı; teklif emanetin iade edildi.', i.baslik);
  for r in select tk.id from oyun.ilan_teklifler tk where tk.ilan_id = i.id and tk.durum in ('bekliyor','karsi') loop
    perform oyun.ilan_teklif_kapat(r.id, 'kapandi', v_mesaj);
  end loop;
  if i.varlik = 'sirket' then
    perform set_config('oyun.ilan_senkron', '1', true);
    update oyun.sirketler set satilik = null where id = i.varlik_id and satilik is not null;
    perform set_config('oyun.ilan_senkron', '', true);
  end if;
  if p_bildir and p_durum = 'suresi_doldu' then
    perform oyun.bildir(i.satici, format('“%s” ilanının 30 günlük yayın süresi doldu. İstersen İlan Meydanı’ndan yeniden ilan verebilirsin.', i.baslik), v_t);
  elsif p_bildir and p_durum = 'gecersiz' then
    perform oyun.bildir(i.satici, format('“%s” ilanı yayından kalktı: ilandaki varlık artık satılabilir durumda değil.', i.baslik), v_t);
  end if;
end $$;

-- Bir varlık el değiştirince aynı varlığa / şirkete ait geçersiz kalan ilanları kapat
create or replace function oyun.ilan_varlik_temizle(p_varlik text, p_id bigint)
returns void language plpgsql security definer set search_path = '' as $$
declare r record;
begin
  for r in select i.id from oyun.ilanlar i where i.durum = 'yayinda'
            and ((p_varlik in ('sirket','hisse') and i.varlik in ('sirket','hisse') and i.varlik_id = p_id)
              or (p_varlik in ('tapu','bolum') and i.varlik = p_varlik and i.varlik_id = p_id)) loop
    if not oyun.ilan_gecerli(r.id) then perform oyun.ilan_kapat(r.id, 'gecersiz'); end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- C. DEVİR (satışın kalbi): hemen al ve kabul edilen teklif buradan geçer
-- ---------------------------------------------------------------------
create or replace function oyun.ilan_devret(p_ilan bigint, p_alici uuid, p_bedel numeric, p_emanet numeric, p_teklif bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  i oyun.ilanlar; v_t timestamptz := oyun.simdi(); v_harc_a numeric; v_harc_s numeric; v_tur text;
  tp oyun.yatirim_pazar_tapu; bo oyun.eko_bolumler; s oyun.sirketler; v_pay numeric; v_odenecek numeric;
  v_il smallint; v_tip text; r record; v_alici_kad text; v_satici_kad text;
begin
  select * into i from oyun.ilanlar where id = p_ilan for update;
  if i.id is null or i.durum <> 'yayinda' or i.bitis <= v_t then raise exception 'Bu ilan artık yayında değil.'; end if;
  if i.satici = p_alici then raise exception 'Kendi ilanını satın alamazsın.'; end if;
  if p_bedel is null or p_bedel < 1000 or p_bedel <> round(p_bedel) then raise exception 'Geçersiz satış bedeli.'; end if;
  if not exists (select 1 from oyun.profiller p where p.id = i.satici and not p.yasakli) then
    raise exception 'Satıcının hesabı şu an işlem yapamıyor.'; end if;
  if oyun.iliskili(i.satici, p_alici) then perform oyun.iliskili_hata(); end if;
  v_harc_a := oyun.ilan_harc(i.varlik, p_bedel); v_harc_s := v_harc_a;
  v_tur := case when i.varlik in ('tapu','bolum') then 'emlak' else 'sirket' end;
  select kad into v_alici_kad from oyun.profiller where id = p_alici;
  select kad into v_satici_kad from oyun.profiller where id = i.satici;

  -- 1) Varlığı kilitle, satıcıda olduğunu doğrula
  if i.varlik = 'tapu' then
    perform oyun.yatirim_pazar_kira_tahsil(i.satici);
    select * into tp from oyun.yatirim_pazar_tapu where id = i.varlik_id for update;
    if tp.id is null or tp.sahip <> i.satici then raise exception 'Satıcı artık bu tapunun sahibi değil; ilan geçersiz.'; end if;
    v_il := tp.il_id; v_tip := tp.tip;
  elsif i.varlik = 'bolum' then
    select * into bo from oyun.eko_bolumler where id = i.varlik_id for update;
    if bo.id is null or bo.sahibi is distinct from i.satici then raise exception 'Satıcı artık bu taşınmazın sahibi değil; ilan geçersiz.'; end if;
    if exists (select 1 from oyun.eko_subeler sb where sb.bolum_id = bo.id and sb.aktif) then
      raise exception 'Kiracısı olan dükkân devredilemez; satıcı önce kira sözleşmesini bitirmeli.'; end if;
    select y.il_id into v_il from oyun.eko_yapilar y where y.id = bo.yapi_id; v_tip := bo.tur;
  else
    if not oyun.uzaktan_modul_acik('sirket_pazari') then raise exception 'Şirket pazarı geçici olarak kapalı.'; end if;
    perform pg_advisory_xact_lock(98763, hashtext(i.varlik_id::text));
    perform oyun.sirket_hesapla(i.varlik_id);
    select * into s from oyun.sirketler where id = i.varlik_id for update;
    if s.id is null or not s.aktif then raise exception 'Şirket artık faal değil; ilan geçersiz.'; end if;
    if s.sektor = 'banka' then raise exception 'Bankalar ilanla devredilemez.'; end if;
    select o.pay into v_pay from oyun.sirket_ortaklari o where o.sirket_id = s.id and o.user_id = i.satici for update;
    if i.varlik = 'sirket' and v_pay is distinct from 100::numeric then
      raise exception 'Satıcı artık şirketin tamamına sahip değil; ilan geçersiz.'; end if;
    if i.varlik = 'hisse' and oyun.ilan_kullanilabilir_pay(s.id, i.satici, i.id) < i.pay then
      raise exception 'Satıcının satılabilir hissesi artık yetersiz; ilan geçersiz.'; end if;
  end if;

  -- 2) Para: alıcı (emanetten düşülür, eksik varsa cüzdandan) ve satıcı
  v_odenecek := p_bedel + v_harc_a - coalesce(p_emanet, 0);
  if v_odenecek > 0 then
    perform oyun.para_islem(p_alici, -v_odenecek, v_tur,
      format('İlan #%s: %s alımı%s', oyun.ilan_no(i.id), i.baslik, case when v_harc_a > 0 then ' (alıcı %2 tapu harcı dahil)' else '' end),
      v_t, v_harc_a);
  elsif v_odenecek < 0 then
    perform oyun.para_islem(p_alici, -v_odenecek, 'iade', format('İlan #%s: emanet farkı iade edildi', oyun.ilan_no(i.id)), v_t);
  end if;
  perform oyun.para_islem(i.satici, p_bedel - v_harc_s, v_tur,
    format('İlan #%s: %s satışı%s', oyun.ilan_no(i.id), i.baslik, case when v_harc_s > 0 then ' (satıcı %2 tapu harcı düşüldü)' else '' end),
    v_t, v_harc_s);

  -- 3) Devir
  if i.varlik = 'tapu' then
    update oyun.yatirim_pazar_tapu set sahip = p_alici, alis_bedeli = p_bedel, satin_alma = v_t, sonraki_kira = v_t + interval '7 days'
     where id = tp.id;
    update oyun.yatirim_pazar_ilan set durum = 'iptal', kapanma = v_t where kaynak = 'yatirim' and ref_id = tp.id and durum = 'acik';
    insert into oyun.yatirim_pazar_islem(kaynak, ref_id, il_id, tip, satici, alici, bedel, alici_harc, satici_harc)
      values ('ilan', tp.id, v_il, v_tip, i.satici, p_alici, p_bedel, v_harc_a, v_harc_s);
  elsif i.varlik = 'bolum' then
    update oyun.eko_bolumler set sahibi = p_alici, satildi = v_t where id = bo.id;
    update oyun.yatirim_pazar_ilan set durum = 'iptal', kapanma = v_t where kaynak = 'proje' and ref_id = bo.id and durum = 'acik';
    insert into oyun.yatirim_pazar_islem(kaynak, ref_id, il_id, tip, satici, alici, bedel, alici_harc, satici_harc)
      values ('ilan', bo.id, v_il, v_tip, i.satici, p_alici, p_bedel, v_harc_a, v_harc_s);
  elsif i.varlik = 'hisse' then
    if v_pay = i.pay then
      delete from oyun.sirket_ortaklari where sirket_id = s.id and user_id = i.satici;
    else
      update oyun.sirket_ortaklari set pay = pay - i.pay where sirket_id = s.id and user_id = i.satici;
    end if;
    insert into oyun.sirket_ortaklari(sirket_id, user_id, pay) values (s.id, p_alici, i.pay)
      on conflict (sirket_id, user_id) do update set pay = oyun.sirket_ortaklari.pay + excluded.pay;
    perform set_config('oyun.ilan_senkron', '1', true);
    update oyun.sirketler set satilik = null where id = s.id and satilik is not null;
    perform set_config('oyun.ilan_senkron', '', true);
    update oyun.sirket_teklif set durum = 'iptal' where sirket_id = s.id and satici = i.satici and durum = 'bekliyor'
      and pay > coalesce((select o.pay from oyun.sirket_ortaklari o where o.sirket_id = s.id and o.user_id = i.satici), 0);
    insert into oyun.ticaret_devir_kayit(tur, varlik_id, satici, alici, bedel, pay, zaman, aciklama)
      values ('sirket_hisse', s.id, i.satici, p_alici, p_bedel, i.pay, v_t,
              format('İlan Meydanı #%s: %s şirketinden %s pay devri', oyun.ilan_no(i.id), s.ad, oyun.ilan_pay_yaz(i.pay)));
  else
    delete from oyun.sirket_ortaklari where sirket_id = s.id;
    insert into oyun.sirket_ortaklari(sirket_id, user_id, pay) values (s.id, p_alici, 100);
    perform set_config('oyun.ilan_senkron', '1', true);
    update oyun.sirketler set satilik = null where id = s.id and satilik is not null;
    perform set_config('oyun.ilan_senkron', '', true);
    update oyun.sirket_teklif set durum = 'iptal' where sirket_id = s.id and durum = 'bekliyor';
    insert into oyun.ticaret_devir_kayit(tur, varlik_id, satici, alici, bedel, pay, zaman, aciklama)
      values ('sirket_tam', s.id, i.satici, p_alici, p_bedel, 100, v_t,
              format('İlan Meydanı #%s: %s şirketinin tamamı devredildi', oyun.ilan_no(i.id), s.ad));
  end if;

  -- 4) Tapu harçları Hazine'ye (milyar birimi); emlakta MASAK tekrar kontrolü
  if v_harc_a + v_harc_s > 0 then
    update oyun.ulke set hazine = hazine + (v_harc_a + v_harc_s) / oyun.pazar_tl_milyar() where id = 1;
    perform oyun.masak_cift_kontrol(i.satici, p_alici, p_bedel);
  end if;

  -- 5) İlanı ve teklifleri kapat
  update oyun.ilanlar set durum = 'satildi', alici = p_alici, satis_bedeli = p_bedel, kapanis = v_t where id = i.id;
  if p_teklif is not null then
    update oyun.ilan_teklifler set durum = 'kabul', emanet = 0, sonuc = v_t where id = p_teklif;
  end if;
  for r in select tk.id from oyun.ilan_teklifler tk where tk.ilan_id = i.id and tk.durum in ('bekliyor','karsi')
             and tk.id is distinct from p_teklif loop
    perform oyun.ilan_teklif_kapat(r.id, 'kapandi', format('“%s” ilanı başka bir alıcıya satıldı; teklif emanetin iade edildi.', i.baslik));
  end loop;
  perform oyun.ilan_varlik_temizle(i.varlik, i.varlik_id);

  perform oyun.bildir(i.satici, format('Satış tamamlandı: “%s” %s ₺ bedelle %s adlı oyuncuya geçti.', i.baslik, oyun.tl(p_bedel), v_alici_kad), v_t);
  perform oyun.bildir(p_alici, format('Hayırlı olsun! “%s” artık senin (%s ₺, satıcı %s).', i.baslik, oyun.tl(p_bedel), v_satici_kad), v_t);
  return jsonb_build_object('tamam', true, 'ilan', i.id, 'bedel', p_bedel, 'odenen', p_bedel + v_harc_a,
                            'saticiya', p_bedel - v_harc_s, 'harc', v_harc_a);
end $$;

-- ---------------------------------------------------------------------
-- D. VİTRİN, ARAMA, DETAY
-- ---------------------------------------------------------------------
create or replace function public.ilan_meydani(p_filtre jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi();
  v_k text := coalesce(nullif(p_filtre->>'kategori', ''), 'tumu');
  v_il smallint := nullif(p_filtre->>'il', '')::smallint;
  v_min numeric := nullif(p_filtre->>'min', '')::numeric;
  v_max numeric := nullif(p_filtre->>'max', '')::numeric;
  v_sek text := nullif(p_filtre->>'sektor', '');
  v_ara text := left(nullif(btrim(coalesce(p_filtre->>'ara', '')), ''), 60);
  v_sir text := coalesce(nullif(p_filtre->>'sirala', ''), 'akilli');
  v_acil boolean := coalesce((p_filtre->>'acil')::boolean, false);
  v_sat uuid; v_sayfa int := greatest(1, least(50, coalesce(nullif(p_filtre->>'sayfa', '')::int, 1)));
  v_boy int := 20; v_kats text[]; v_toplam int; v_liste jsonb; v_vitrin jsonb; v_kat jsonb; v_mut jsonb;
  v_desen text; v_sektorler jsonb;
begin
  if nullif(p_filtre->>'satici', '') is not null then
    select pr.id into v_sat from oyun.profiller pr where lower(pr.kad) = lower(p_filtre->>'satici');
    if v_sat is null then v_sat := '00000000-0000-0000-0000-000000000000'; end if;
  end if;
  v_kats := case v_k when 'tumu' then array['konut','isyeri','arsa','sirket','hisse']
                     when 'emlak' then array['konut','isyeri','arsa']
                     when 'sirketler' then array['sirket','hisse']
                     when 'muteahhit' then array[]::text[]
                     else array[v_k] end;
  if v_ara is not null then
    v_desen := '%' || replace(replace(replace(v_ara, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;

  with f as (
    select i.id, i.fiyat, i.olusturma, i.siralama, i.ust_bitis from oyun.ilanlar i
     where i.durum = 'yayinda' and i.bitis > v_t and i.kategori = any(v_kats)
       and (v_il is null or i.il_id = v_il)
       and (v_min is null or i.fiyat >= v_min) and (v_max is null or i.fiyat <= v_max)
       and (v_sek is null or i.sektor = v_sek)
       and (not v_acil or i.acil_bitis > v_t)
       and (v_sat is null or i.satici = v_sat)
       and (v_desen is null or i.baslik ilike v_desen or coalesce(i.aciklama, '') ilike v_desen
            or exists (select 1 from oyun.iller x where x.id = i.il_id and x.ad ilike v_desen)
            or exists (select 1 from oyun.sirketler s where i.varlik in ('sirket','hisse') and s.id = i.varlik_id and s.ad ilike v_desen))
  ), sirali as (
    select f.id, count(*) over () as n,
           row_number() over (order by
             case when v_sir = 'akilli' and f.ust_bitis > v_t then 0 else 1 end,
             case when v_sir = 'ucuz' then f.fiyat end asc nulls last,
             case when v_sir = 'pahali' then f.fiyat end desc nulls last,
             case when v_sir = 'yeni' then f.olusturma end desc nulls last,
             f.siralama desc, f.id desc) as rn
      from f
  )
  select coalesce(max(n), 0)::int,
         coalesce(jsonb_agg(oyun.ilan_ozet(id, p.id) order by rn) filter (where rn > (v_sayfa - 1) * v_boy and rn <= v_sayfa * v_boy), '[]'::jsonb)
    into v_toplam, v_liste from sirali;

  select coalesce(jsonb_agg(oyun.ilan_ozet(x.id, p.id)), '[]'::jsonb) into v_vitrin
    from (select i.id from oyun.ilanlar i
           where i.durum = 'yayinda' and i.bitis > v_t and i.vitrin_bitis > v_t and i.kategori = any(v_kats)
           order by random() limit 8) x;

  select jsonb_build_object(
      'konut',  count(*) filter (where i.kategori = 'konut'),
      'isyeri', count(*) filter (where i.kategori = 'isyeri'),
      'arsa',   count(*) filter (where i.kategori = 'arsa'),
      'sirket', count(*) filter (where i.kategori = 'sirket'),
      'hisse',  count(*) filter (where i.kategori = 'hisse'),
      'acil',   count(*) filter (where i.acil_bitis > v_t),
      'toplam', count(*),
      'muteahhit', (select count(*) from oyun.eko_bolumler bo join oyun.eko_yapilar y on y.id = bo.yapi_id
                     join oyun.sirketler s on s.id = y.sirket_id
                    where bo.sahibi is null and bo.satis_fiyati is not null and y.bitis <= v_t and s.aktif))
    into v_kat from oyun.ilanlar i where i.durum = 'yayinda' and i.bitis > v_t;

  -- Müteahhitten sıfır (ilk satış; satın alma mevcut eko_emlak_islem('bolum_al') ile)
  if v_k in ('tumu','emlak','konut','isyeri','muteahhit') and v_sat is null and not v_acil and v_sek is null then
    select coalesce(jsonb_agg(g order by g->>'il', (g->>'fiyat')::numeric), '[]'::jsonb) into v_mut from (
      select jsonb_build_object(
               'bolum', min(bo.id) filter (where bo.satis_fiyati = mn.fiyat), 'yapi', y.id, 'proje', y.ad, 'tur', bo.tur,
               'kategori', case bo.tur when 'daire' then 'konut' else 'isyeri' end,
               'il', x.ad, 'il_id', y.il_id, 'fiyat', mn.fiyat, 'adet', count(*), 'alan_m2', min(bo.alan_m2),
               'firma', s.ad, 'harc', oyun.ilan_harc('bolum', mn.fiyat)) g
        from oyun.eko_bolumler bo
        join oyun.eko_yapilar y on y.id = bo.yapi_id
        join oyun.sirketler s on s.id = y.sirket_id and s.aktif
        join oyun.iller x on x.id = y.il_id
        cross join lateral (select min(b2.satis_fiyati) fiyat from oyun.eko_bolumler b2
                             where b2.yapi_id = y.id and b2.tur = bo.tur and b2.sahibi is null and b2.satis_fiyati is not null) mn
       where bo.sahibi is null and bo.satis_fiyati is not null and y.bitis <= v_t
         and (v_k not in ('konut','isyeri') or bo.tur = case v_k when 'konut' then 'daire' else 'dukkan' end)
         and (v_il is null or y.il_id = v_il)
         and (v_min is null or mn.fiyat >= v_min) and (v_max is null or mn.fiyat <= v_max)
         and (v_desen is null or y.ad ilike v_desen or x.ad ilike v_desen or s.ad ilike v_desen)
       group by y.id, y.ad, bo.tur, x.ad, y.il_id, s.ad, mn.fiyat
       limit 24) q;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('kod', z.sektor, 'ad', oyun.ilan_sektor_ad(z.sektor)) order by oyun.ilan_sektor_ad(z.sektor)), '[]'::jsonb)
    into v_sektorler from (select distinct s.sektor from oyun.sirketler s where s.aktif and s.sektor <> 'banka') z;

  return jsonb_build_object(
    'liste', v_liste, 'toplam', v_toplam, 'sayfa', v_sayfa, 'boy', v_boy,
    'vitrin', v_vitrin, 'kategoriler', v_kat, 'muteahhit', coalesce(v_mut, '[]'::jsonb), 'sektorler', v_sektorler,
    'benim', jsonb_build_object(
      'aktif_ilan', (select count(*) from oyun.ilanlar i where i.satici = p.id and i.durum = 'yayinda'),
      'gelen', (select count(*) from oyun.ilan_teklifler tk join oyun.ilanlar i on i.id = tk.ilan_id
                 where i.satici = p.id and tk.durum = 'bekliyor'),
      'giden', (select count(*) from oyun.ilan_teklifler tk where tk.alici = p.id and tk.durum in ('bekliyor','karsi')),
      'karsi', (select count(*) from oyun.ilan_teklifler tk where tk.alici = p.id and tk.durum = 'karsi'),
      'favori', coalesce((select jsonb_agg(fv.ilan_id) from oyun.ilan_favori fv where fv.user_id = p.id), '[]'::jsonb),
      'cuzdan', (select c.para from oyun.cuzdan c where c.user_id = p.id)),
    'tarife', (select jsonb_agg(jsonb_build_object('kod', a.kod, 'ad', a.ad, 'tutar', a.tutar, 'gun', a.gun, 'aciklama', a.aciklama) order by a.sira)
                 from oyun.ilan_ayar a));
end $$;

create or replace function public.ilan_detay(p_ilan bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); i oyun.ilanlar;
  v_bilgi jsonb := '[]'::jsonb; v_mali jsonb; v_satici jsonb; v_teklifler jsonb; v_teklifim jsonb; v_benzer jsonb;
  v_benim boolean; v_alt numeric; v_ust numeric; v_rayic numeric; tp oyun.yatirim_pazar_tapu; bo oyun.eko_bolumler; y oyun.eko_yapilar; s oyun.sirketler;
  v_il text; v_mali_izin boolean; v_ekledi int; v_damga numeric;
begin
  select * into i from oyun.ilanlar where id = p_ilan;
  if i.id is null then raise exception 'İlan bulunamadı.'; end if;
  v_benim := i.satici = p.id;
  if i.durum = 'yayinda' and (i.bitis <= v_t or not oyun.ilan_gecerli(i.id)) then
    perform oyun.ilan_kapat(i.id, case when i.bitis <= v_t then 'suresi_doldu' else 'gecersiz' end);
    select * into i from oyun.ilanlar where id = p_ilan;
  end if;
  if not v_benim then
    insert into oyun.ilan_bakan(ilan_id, user_id, zaman) values (i.id, p.id, v_t) on conflict do nothing;
    get diagnostics v_ekledi = row_count;
    if v_ekledi > 0 then update oyun.ilanlar set goruntulenme = goruntulenme + 1 where id = i.id; i.goruntulenme := i.goruntulenme + 1; end if;
  end if;
  select x.ad into v_il from oyun.iller x where x.id = i.il_id;

  if i.varlik = 'tapu' then
    select * into tp from oyun.yatirim_pazar_tapu where id = i.varlik_id;
    v_bilgi := jsonb_build_array(
      jsonb_build_array('Emlak tipi', oyun.ilan_tip_ad(tp.tip)),
      jsonb_build_array('İl', v_il),
      jsonb_build_array('Alan', tp.alan_m2 || ' m²'),
      jsonb_build_array('Haftalık kira geliri', case when tp.haftalik_kira > 0 then oyun.tl(tp.haftalik_kira) || ' ₺' else 'Yok' end),
      jsonb_build_array('Tapu durumu', 'Tapulu, belediyeden alınmış'),
      jsonb_build_array('İl rayici', oyun.tl(oyun.yatirim_pazar_fiyat(tp.il_id, tp.tip)) || ' ₺'));
  elsif i.varlik = 'bolum' then
    select * into bo from oyun.eko_bolumler where id = i.varlik_id;
    select * into y from oyun.eko_yapilar where id = bo.yapi_id;
    v_bilgi := jsonb_build_array(
      jsonb_build_array('Emlak tipi', oyun.ilan_tip_ad(bo.tur)),
      jsonb_build_array('İl', v_il),
      jsonb_build_array('Proje', y.ad),
      jsonb_build_array('Bağımsız bölüm', bo.sira || ' numara'),
      jsonb_build_array('Alan', bo.alan_m2 || ' m²'),
      jsonb_build_array('Yapım', 'Tamamlandı ' || oyun.ilan_tarih(y.bitis)),
      jsonb_build_array('Müteahhit', coalesce((select s2.ad from oyun.sirketler s2 where s2.id = y.sirket_id), '—')),
      jsonb_build_array('Kira bedeli', case when bo.kira_bedeli is not null then oyun.tl(bo.kira_bedeli) || ' ₺ / hafta' else 'Belirlenmemiş' end),
      jsonb_build_array('İl rayici', oyun.tl(oyun.yatirim_pazar_fiyat(y.il_id, bo.tur)) || ' ₺'));
  else
    select * into s from oyun.sirketler where id = i.varlik_id;
    v_bilgi := jsonb_build_array(
      jsonb_build_array('Şirket', s.ad),
      jsonb_build_array('Sektör', oyun.ilan_sektor_ad(s.sektor)),
      jsonb_build_array('Hukuki tür', case s.tur_hukuki when 'as' then 'Anonim şirket (A.Ş.)' when 'ltd' then 'Limited şirket' else coalesce(s.tur_hukuki, '—') end),
      jsonb_build_array('Kuruluş', oyun.ilan_tarih(s.kurulus)),
      jsonb_build_array('Merkez', coalesce(v_il, '—')),
      jsonb_build_array('Şube', ((select count(*) from oyun.sirket_il_subeleri sb where sb.sirket_id = s.id)
                               + (select count(*) from oyun.eko_subeler sb where sb.sirket_id = s.id and sb.aktif)) || ' şube'),
      jsonb_build_array('Ortak sayısı', (select count(*) from oyun.sirket_ortaklari o where o.sirket_id = s.id) || ' ortak'),
      jsonb_build_array('Satılan', case when i.varlik = 'sirket' then 'Şirketin tamamı (%100)' else oyun.ilan_pay_yaz(i.pay) || ' hisse' end),
      jsonb_build_array('Borsada', case when s.halka_acik then 'İşlem görüyor' else 'Hayır' end));
    v_mali_izin := i.mali_goster or v_benim or p.yonetici;
    if v_mali_izin then
      v_mali := jsonb_build_object('kasa', s.kasa, 'sermaye', s.sermaye, 'defter', round(oyun.sirket_defter(s.id)),
                                   'acik', i.mali_goster);
    end if;
  end if;
  v_bilgi := v_bilgi || jsonb_build_array(
    jsonb_build_array('İlan no', oyun.ilan_no(i.id)::text),
    jsonb_build_array('İlan tarihi', oyun.ilan_tarih(i.olusturma)),
    jsonb_build_array('Pazarlık', case when i.pazarlik then 'Teklif kabul ediliyor' else 'Yok, sabit fiyat' end));

  v_satici := (select jsonb_build_object('kad', pr.kad, 'uye', oyun.ilan_tarih(pr.olusturma),
                 'il', (select x.ad from oyun.iller x where x.id = pr.il_id), 'son_gorulme', pr.son_gorulme,
                 'satis', (select count(*) from oyun.ilanlar z where z.satici = pr.id and z.durum = 'satildi'),
                 'aktif', (select count(*) from oyun.ilanlar z where z.satici = pr.id and z.durum = 'yayinda' and z.bitis > v_t))
                 from oyun.profiller pr where pr.id = i.satici);

  if v_benim then
    select coalesce(jsonb_agg(jsonb_build_object('id', tk.id, 'alici', (select kad from oyun.profiller where id = tk.alici),
             'tutar', tk.tutar, 'karsi', tk.karsi, 'durum', tk.durum, 'bitis', tk.bitis, 'not', tk.not_metni, 'zaman', tk.olusturma)
             order by (tk.durum in ('bekliyor','karsi')) desc, tk.tutar desc, tk.id desc), '[]'::jsonb)
      into v_teklifler from oyun.ilan_teklifler tk where tk.ilan_id = i.id;
    select b.alt, b.ust, b.rayic into v_alt, v_ust, v_rayic from oyun.ilan_bant(i.varlik, i.varlik_id, i.pay) b;
  else
    select jsonb_build_object('id', tk.id, 'tutar', tk.tutar, 'karsi', tk.karsi, 'durum', tk.durum, 'bitis', tk.bitis,
                              'emanet', tk.emanet, 'not', tk.not_metni)
      into v_teklifim from oyun.ilan_teklifler tk where tk.ilan_id = i.id and tk.alici = p.id
     order by (tk.durum in ('bekliyor','karsi')) desc, tk.id desc limit 1;
  end if;

  select coalesce(jsonb_agg(oyun.ilan_ozet(z.id, p.id)), '[]'::jsonb) into v_benzer from (
    select z.id from oyun.ilanlar z where z.durum = 'yayinda' and z.bitis > v_t and z.kategori = i.kategori and z.id <> i.id
     order by (z.il_id is not distinct from i.il_id) desc, abs(z.fiyat - i.fiyat), z.id desc limit 4) z;

  v_damga := case when i.varlik in ('sirket','hisse') then greatest(0, coalesce(oyun.eko_vergi_oran('damga'), 1)) end;
  return oyun.ilan_ozet(i.id, p.id) || jsonb_build_object(
    'aciklama', i.aciklama, 'bilgi', v_bilgi, 'mali', v_mali, 'mali_goster', i.mali_goster, 'satici_bilgi', v_satici,
    'ilk_fiyat', i.ilk_fiyat, 'onceki_fiyat', i.onceki_fiyat,
    'favori', exists (select 1 from oyun.ilan_favori fv where fv.user_id = p.id and fv.ilan_id = i.id),
    'favori_sayisi', (select count(*) from oyun.ilan_favori fv where fv.ilan_id = i.id),
    'teklifler', v_teklifler, 'teklifim', v_teklifim, 'benzer', v_benzer,
    'alici_harc', oyun.ilan_harc(i.varlik, i.fiyat), 'satici_harc_oran', case when i.varlik in ('tapu','bolum') then 2 else v_damga end,
    'bant', case when v_benim then jsonb_build_object('alt', v_alt, 'ust', v_ust, 'rayic', v_rayic) end,
    'paketler', case when v_benim then jsonb_build_object('vitrin', i.vitrin_bitis, 'ust_sira', i.ust_bitis, 'acil', i.acil_bitis, 'renkli', i.renkli_bitis) end,
    'cuzdan', (select c.para from oyun.cuzdan c where c.user_id = p.id),
    'yonetici', p.yonetici);
end $$;

-- ---------------------------------------------------------------------
-- E. İLAN VER / DÜZENLE / ÖNE ÇIKAR / KALDIR
-- ---------------------------------------------------------------------
create or replace function public.ilan_varliklarim()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi();
begin
  return jsonb_build_object(
    'tapular', coalesce((select jsonb_agg(jsonb_build_object(
        'varlik', 'tapu', 'id', tp.id, 'tip', tp.tip, 'kategori', case tp.tip when 'daire' then 'konut' when 'dukkan' then 'isyeri' else 'arsa' end,
        'il', x.ad, 'il_id', tp.il_id, 'alan_m2', tp.alan_m2, 'kira', tp.haftalik_kira, 'alis', tp.alis_bedeli,
        'rayic', b.rayic, 'alt', b.alt, 'ust', b.ust,
        'ilanda', exists (select 1 from oyun.ilanlar i where i.varlik = 'tapu' and i.varlik_id = tp.id and i.durum = 'yayinda'),
        'baska_pazar', exists (select 1 from oyun.yatirim_pazar_ilan yi where yi.kaynak = 'yatirim' and yi.ref_id = tp.id and yi.durum = 'acik'))
        order by tp.id)
      from oyun.yatirim_pazar_tapu tp join oyun.iller x on x.id = tp.il_id
      cross join lateral oyun.ilan_bant('tapu', tp.id, null) b
      where tp.sahip = p.id), '[]'::jsonb),
    'bolumler', coalesce((select jsonb_agg(jsonb_build_object(
        'varlik', 'bolum', 'id', bo.id, 'tip', bo.tur, 'kategori', case bo.tur when 'daire' then 'konut' else 'isyeri' end,
        'il', x.ad, 'il_id', y.il_id, 'alan_m2', bo.alan_m2, 'kira', bo.kira_bedeli, 'proje', y.ad, 'sira', bo.sira,
        'rayic', b.rayic, 'alt', b.alt, 'ust', b.ust,
        'kirada', exists (select 1 from oyun.eko_subeler sb where sb.bolum_id = bo.id and sb.aktif),
        'ilanda', exists (select 1 from oyun.ilanlar i where i.varlik = 'bolum' and i.varlik_id = bo.id and i.durum = 'yayinda'),
        'baska_pazar', exists (select 1 from oyun.yatirim_pazar_ilan yi where yi.kaynak = 'proje' and yi.ref_id = bo.id and yi.durum = 'acik'))
        order by bo.id)
      from oyun.eko_bolumler bo join oyun.eko_yapilar y on y.id = bo.yapi_id join oyun.iller x on x.id = y.il_id
      cross join lateral oyun.ilan_bant('bolum', bo.id, null) b
      where bo.sahibi = p.id), '[]'::jsonb),
    'sirketler', coalesce((select jsonb_agg(jsonb_build_object(
        'id', s.id, 'ad', s.ad, 'sektor', s.sektor, 'sektor_ad', oyun.ilan_sektor_ad(s.sektor), 'pay', o.pay,
        'tam', o.pay = 100, 'banka', s.sektor = 'banka', 'il', (select x.ad from oyun.iller x where x.id = oyun.ilan_sirket_il(s.id)),
        'kullanilabilir', oyun.ilan_kullanilabilir_pay(s.id, p.id, null),
        'sirket_alt', bs.alt, 'sirket_ust', bs.ust, 'bant_acik', oyun.bant_acik(), 'birim_alt', pb.alt, 'birim_ust', pb.ust,
        'ilanda_sirket', exists (select 1 from oyun.ilanlar i where i.varlik = 'sirket' and i.varlik_id = s.id and i.durum = 'yayinda'),
        'ilanda_hisse', exists (select 1 from oyun.ilanlar i where i.varlik = 'hisse' and i.varlik_id = s.id and i.satici = p.id and i.durum = 'yayinda'))
        order by s.ad)
      from oyun.sirket_ortaklari o join oyun.sirketler s on s.id = o.sirket_id and s.aktif
      cross join lateral oyun.ilan_bant('sirket', s.id, 100) bs
      cross join lateral oyun.pay_bandi(s.id) pb
      where o.user_id = p.id), '[]'::jsonb),
    'aktif', (select count(*) from oyun.ilanlar i where i.satici = p.id and i.durum = 'yayinda'),
    'limit', 10,
    'cuzdan', (select c.para from oyun.cuzdan c where c.user_id = p.id),
    'sirket_pazari', oyun.uzaktan_modul_acik('sirket_pazari'),
    'tarife', (select jsonb_agg(jsonb_build_object('kod', a.kod, 'ad', a.ad, 'tutar', a.tutar, 'gun', a.gun, 'aciklama', a.aciklama) order by a.sira)
                 from oyun.ilan_ayar a));
end $$;

create or replace function public.ilan_ver(p_veri jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi();
  v_varlik text := p_veri->>'varlik'; v_id bigint := nullif(p_veri->>'id', '')::bigint;
  v_pay numeric := nullif(p_veri->>'pay', '')::numeric;
  v_baslik text := btrim(regexp_replace(coalesce(p_veri->>'baslik', ''), '\s+', ' ', 'g'));
  v_aciklama text := nullif(btrim(regexp_replace(coalesce(p_veri->>'aciklama', ''), '[\r\n]{3,}', E'\n\n', 'g')), '');
  v_fiyat numeric := nullif(p_veri->>'fiyat', '')::numeric;
  v_pazarlik boolean := coalesce((p_veri->>'pazarlik')::boolean, true);
  v_mali boolean := coalesce((p_veri->>'mali_goster')::boolean, false);
  v_paketler text[]; v_kategori text; v_il smallint; v_sektor text; v_bant record;
  tp oyun.yatirim_pazar_tapu; bo oyun.eko_bolumler; s oyun.sirketler; v_sahip_pay numeric;
  v_ucret numeric := 0; v_kod text; v_ilan bigint; a oyun.ilan_ayar;
begin
  select coalesce(array_agg(distinct e), array[]::text[]) into v_paketler
    from jsonb_array_elements_text(case when jsonb_typeof(p_veri->'paketler') = 'array' then p_veri->'paketler' else '[]'::jsonb end) e
   where e in ('vitrin','ust_sira','acil','renkli');
  if v_varlik is null or v_varlik not in ('tapu','bolum','sirket','hisse') or v_id is null then raise exception 'İlana çıkarılacak varlığı seç.'; end if;
  if char_length(v_baslik) < 5 or char_length(v_baslik) > 70 then raise exception 'İlan başlığı 5 ile 70 karakter arasında olmalı.'; end if;
  if v_aciklama is not null and char_length(v_aciklama) > 1200 then raise exception 'Açıklama en fazla 1.200 karakter olabilir.'; end if;
  if oyun.kufurlu(v_baslik) or (v_aciklama is not null and oyun.kufurlu(v_aciklama)) then
    raise exception 'İlan metninde uygunsuz bir ifade var. Hakaret ve küfür yasaktır.'; end if;
  if v_fiyat is null or v_fiyat <> round(v_fiyat) or v_fiyat < 1000 or v_fiyat > 1000000000 then
    raise exception 'Fiyat 1.000 ₺ ile 1 milyar ₺ arasında, kuruşsuz olmalı.'; end if;
  if (select count(*) from oyun.ilanlar i where i.satici = p.id and i.durum = 'yayinda') >= 10 then
    raise exception 'Aynı anda en fazla 10 ilanın yayında olabilir. Önce bir ilanını kaldır.'; end if;
  perform pg_advisory_xact_lock(99511, hashtext(v_varlik || ':' || v_id::text));

  if v_varlik = 'tapu' then
    select * into tp from oyun.yatirim_pazar_tapu where id = v_id for update;
    if tp.id is null or tp.sahip <> p.id then raise exception 'Bu tapu sana ait değil.'; end if;
    if exists (select 1 from oyun.yatirim_pazar_ilan yi where yi.kaynak = 'yatirim' and yi.ref_id = tp.id and yi.durum = 'acik') then
      raise exception 'Bu tapu Yatırım Pazarı’nda zaten satılık. Önce oradaki ilanı kaldır.'; end if;
    v_kategori := case tp.tip when 'daire' then 'konut' when 'dukkan' then 'isyeri' else 'arsa' end; v_il := tp.il_id; v_pay := null;
  elsif v_varlik = 'bolum' then
    select * into bo from oyun.eko_bolumler where id = v_id for update;
    if bo.id is null or bo.sahibi is distinct from p.id then raise exception 'Bu konut ya da dükkân sana ait değil.'; end if;
    if exists (select 1 from oyun.eko_subeler sb where sb.bolum_id = bo.id and sb.aktif) then
      raise exception 'Kiracısı olan dükkân satılığa çıkarılamaz.'; end if;
    if exists (select 1 from oyun.yatirim_pazar_ilan yi where yi.kaynak = 'proje' and yi.ref_id = bo.id and yi.durum = 'acik') then
      raise exception 'Bu taşınmaz Yatırım Pazarı’nda zaten satılık. Önce oradaki ilanı kaldır.'; end if;
    v_kategori := case bo.tur when 'daire' then 'konut' else 'isyeri' end;
    select y.il_id into v_il from oyun.eko_yapilar y where y.id = bo.yapi_id; v_pay := null;
  else
    if not oyun.uzaktan_modul_acik('sirket_pazari') then raise exception 'Şirket pazarı geçici olarak kapalı.'; end if;
    perform pg_advisory_xact_lock(98763, hashtext(v_id::text));
    select * into s from oyun.sirketler where id = v_id for update;
    if s.id is null or not s.aktif then raise exception 'Yalnız faal şirketler ilana çıkarılabilir.'; end if;
    if s.sektor = 'banka' then raise exception 'Bankalar İlan Meydanı’nda satılamaz; banka devri ayrı izin gerektirir.'; end if;
    select o.pay into v_sahip_pay from oyun.sirket_ortaklari o where o.sirket_id = s.id and o.user_id = p.id;
    if v_sahip_pay is null then raise exception 'Bu şirkette payın yok.'; end if;
    v_kategori := v_varlik; v_il := oyun.ilan_sirket_il(s.id); v_sektor := s.sektor;
    if v_varlik = 'sirket' then
      if v_sahip_pay <> 100 then raise exception 'Şirketin tamamını yalnız %%100 sahibi satabilir. Payını satmak için “Şirket hissesi” seç.'; end if;
      if exists (select 1 from oyun.ilanlar i where i.varlik = 'hisse' and i.varlik_id = s.id and i.durum = 'yayinda') then
        raise exception 'Bu şirketin hisse ilanı yayında. Önce onu kaldır.'; end if;
      if exists (select 1 from oyun.sirket_hisse_ilanlari h where h.sirket_id = s.id and h.durum = 'acik') then
        raise exception 'Bu şirketin eski hisse pazarında açık ilanı var. Önce onu kaldır.'; end if;
      v_pay := 100;
    else
      if v_pay is null or v_pay <= 0 or v_pay > 100 or v_pay <> round(v_pay, 2) then
        raise exception 'Satılacak pay 0,01 ile 100 arasında, en fazla 2 ondalıklı olmalı.'; end if;
      if v_sahip_pay = 100 and v_pay = 100 then raise exception 'Şirketin tamamını satmak için “Satılık şirket” kategorisini seç.'; end if;
      if exists (select 1 from oyun.ilanlar i where i.varlik = 'sirket' and i.varlik_id = s.id and i.durum = 'yayinda') then
        raise exception 'Bu şirketin tamamı için verdiğin ilan yayında. Önce onu kaldır.'; end if;
      if oyun.ilan_kullanilabilir_pay(s.id, p.id, null) < v_pay then
        raise exception 'Satabileceğin pay %. Borsadaki emirler ve diğer ilanlar düşüldü.', oyun.ilan_pay_yaz(oyun.ilan_kullanilabilir_pay(s.id, p.id, null)); end if;
    end if;
  end if;

  if exists (select 1 from oyun.ilanlar i where i.varlik = v_varlik and i.varlik_id = v_id and i.satici = p.id and i.durum = 'yayinda') then
    raise exception 'Bu varlık için zaten yayında bir ilanın var.'; end if;
  select * into v_bant from oyun.ilan_bant(v_varlik, v_id, v_pay);
  if v_fiyat < v_bant.alt or v_fiyat > v_bant.ust then
    raise exception 'Bu ilan için fiyat % ₺ ile % ₺ arasında olmalı.', oyun.tl(v_bant.alt), oyun.tl(v_bant.ust); end if;

  v_kod := case when v_varlik in ('tapu','bolum') then 'ilan_emlak' when v_varlik = 'hisse' then 'ilan_hisse' else 'ilan_sirket' end;
  select coalesce(sum(a2.tutar), 0) into v_ucret from oyun.ilan_ayar a2 where a2.kod = v_kod or a2.kod = any(v_paketler);
  if v_ucret > 0 then
    perform oyun.para_islem(p.id, -v_ucret, 'reklam',
      format('İlan Meydanı: “%s” ilan ücreti%s', v_baslik, case when cardinality(v_paketler) > 0 then ' ve öne çıkarma' else '' end), v_t);
    update oyun.ulke set hazine = hazine + v_ucret / oyun.pazar_tl_milyar() where id = 1;
  end if;

  insert into oyun.ilanlar(kategori, varlik, varlik_id, pay, satici, baslik, aciklama, fiyat, ilk_fiyat, pazarlik, mali_goster,
                           il_id, sektor, olusturma, siralama, bitis)
    values (v_kategori, v_varlik, v_id, v_pay, p.id, v_baslik, v_aciklama, v_fiyat, v_fiyat, v_pazarlik,
            v_mali and v_varlik in ('sirket','hisse'), v_il, v_sektor, v_t, v_t,
            v_t + make_interval(days => (select a3.gun from oyun.ilan_ayar a3 where a3.kod = v_kod)))
    returning id into v_ilan;
  for a in select * from oyun.ilan_ayar a4 where a4.kod = v_kod or a4.kod = any(v_paketler) loop
    insert into oyun.ilan_odeme(ilan_id, user_id, kod, tutar, zaman) values (v_ilan, p.id, a.kod, a.tutar, v_t);
    if a.kod = 'vitrin' then update oyun.ilanlar set vitrin_bitis = v_t + make_interval(days => a.gun) where id = v_ilan;
    elsif a.kod = 'ust_sira' then update oyun.ilanlar set ust_bitis = v_t + make_interval(days => a.gun) where id = v_ilan;
    elsif a.kod = 'acil' then update oyun.ilanlar set acil_bitis = v_t + make_interval(days => a.gun) where id = v_ilan;
    elsif a.kod = 'renkli' then update oyun.ilanlar set renkli_bitis = v_t + make_interval(days => a.gun) where id = v_ilan;
    end if;
  end loop;

  -- Şirketin tamamı: eski "satılık şirket" alanı da eşlenir (eski ekranlar aynı fiyatı görür)
  perform set_config('oyun.ilan_senkron', '1', true);
  if v_varlik = 'sirket' then
    update oyun.sirketler set satilik = v_fiyat where id = v_id;
  elsif v_varlik = 'hisse' then
    update oyun.sirketler set satilik = null where id = v_id and satilik is not null;
  end if;
  perform set_config('oyun.ilan_senkron', '', true);

  return jsonb_build_object('tamam', true, 'id', v_ilan, 'no', oyun.ilan_no(v_ilan), 'ucret', v_ucret);
end $$;

create or replace function public.ilan_duzenle(p_ilan bigint, p_veri jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); i oyun.ilanlar; v_bant record; v_fiyat numeric; v_baslik text; v_aciklama text;
begin
  select * into i from oyun.ilanlar where id = p_ilan for update;
  if i.id is null or i.satici <> p.id then raise exception 'Bu ilan sana ait değil.'; end if;
  if i.durum <> 'yayinda' then raise exception 'Yalnız yayındaki ilanlar düzenlenebilir.'; end if;
  if p_veri ? 'baslik' then
    v_baslik := btrim(regexp_replace(coalesce(p_veri->>'baslik', ''), '\s+', ' ', 'g'));
    if char_length(v_baslik) < 5 or char_length(v_baslik) > 70 then raise exception 'İlan başlığı 5 ile 70 karakter arasında olmalı.'; end if;
    if oyun.kufurlu(v_baslik) then raise exception 'İlan metninde uygunsuz bir ifade var.'; end if;
    update oyun.ilanlar set baslik = v_baslik where id = i.id;
  end if;
  if p_veri ? 'aciklama' then
    v_aciklama := nullif(btrim(regexp_replace(coalesce(p_veri->>'aciklama', ''), '[\r\n]{3,}', E'\n\n', 'g')), '');
    if v_aciklama is not null and (char_length(v_aciklama) > 1200 or oyun.kufurlu(v_aciklama)) then
      raise exception 'Açıklama en fazla 1.200 karakter olmalı ve uygunsuz ifade içermemeli.'; end if;
    update oyun.ilanlar set aciklama = v_aciklama where id = i.id;
  end if;
  if p_veri ? 'pazarlik' then update oyun.ilanlar set pazarlik = (p_veri->>'pazarlik')::boolean where id = i.id; end if;
  if p_veri ? 'mali_goster' and i.varlik in ('sirket','hisse') then
    update oyun.ilanlar set mali_goster = (p_veri->>'mali_goster')::boolean where id = i.id; end if;
  if p_veri ? 'fiyat' then
    v_fiyat := (p_veri->>'fiyat')::numeric;
    if v_fiyat is null or v_fiyat <> round(v_fiyat) or v_fiyat < 1000 or v_fiyat > 1000000000 then raise exception 'Geçerli bir fiyat yaz.'; end if;
    if v_fiyat <> i.fiyat then
      select * into v_bant from oyun.ilan_bant(i.varlik, i.varlik_id, i.pay);
      if v_fiyat < v_bant.alt or v_fiyat > v_bant.ust then
        raise exception 'Bu ilan için fiyat % ₺ ile % ₺ arasında olmalı.', oyun.tl(v_bant.alt), oyun.tl(v_bant.ust); end if;
      update oyun.ilanlar set onceki_fiyat = i.fiyat, fiyat = v_fiyat where id = i.id;
      if i.varlik = 'sirket' then
        perform set_config('oyun.ilan_senkron', '1', true);
        update oyun.sirketler set satilik = v_fiyat where id = i.varlik_id;
        perform set_config('oyun.ilan_senkron', '', true);
      end if;
    end if;
  end if;
  return jsonb_build_object('tamam', true);
end $$;

create or replace function public.ilan_one_cikar(p_ilan bigint, p_paket text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); i oyun.ilanlar; a oyun.ilan_ayar; v_bitis timestamptz;
begin
  select * into i from oyun.ilanlar where id = p_ilan for update;
  if i.id is null or i.satici <> p.id then raise exception 'Bu ilan sana ait değil.'; end if;
  if i.durum <> 'yayinda' or i.bitis <= v_t then raise exception 'Yalnız yayındaki ilanlar öne çıkarılabilir.'; end if;
  select * into a from oyun.ilan_ayar where kod = p_paket and kod in ('vitrin','ust_sira','acil','renkli','yukari');
  if a.kod is null then raise exception 'Geçersiz öne çıkarma paketi.'; end if;
  if a.tutar > 0 then
    perform oyun.para_islem(p.id, -a.tutar, 'reklam', format('İlan Meydanı: “%s” için %s', i.baslik, a.ad), v_t);
    update oyun.ulke set hazine = hazine + a.tutar / oyun.pazar_tl_milyar() where id = 1;
  end if;
  insert into oyun.ilan_odeme(ilan_id, user_id, kod, tutar, zaman) values (i.id, p.id, a.kod, a.tutar, v_t);
  if a.kod = 'yukari' then
    update oyun.ilanlar set siralama = v_t where id = i.id; v_bitis := v_t;
  elsif a.kod = 'vitrin' then
    update oyun.ilanlar set vitrin_bitis = greatest(coalesce(vitrin_bitis, v_t), v_t) + make_interval(days => a.gun) where id = i.id returning vitrin_bitis into v_bitis;
  elsif a.kod = 'ust_sira' then
    update oyun.ilanlar set ust_bitis = greatest(coalesce(ust_bitis, v_t), v_t) + make_interval(days => a.gun) where id = i.id returning ust_bitis into v_bitis;
  elsif a.kod = 'acil' then
    update oyun.ilanlar set acil_bitis = greatest(coalesce(acil_bitis, v_t), v_t) + make_interval(days => a.gun) where id = i.id returning acil_bitis into v_bitis;
  else
    update oyun.ilanlar set renkli_bitis = greatest(coalesce(renkli_bitis, v_t), v_t) + make_interval(days => a.gun) where id = i.id returning renkli_bitis into v_bitis;
  end if;
  return jsonb_build_object('tamam', true, 'paket', a.kod, 'bitis', v_bitis, 'ucret', a.tutar);
end $$;

create or replace function public.ilan_kaldir(p_ilan bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); i oyun.ilanlar;
begin
  select * into i from oyun.ilanlar where id = p_ilan;
  if i.id is null then raise exception 'İlan bulunamadı.'; end if;
  if i.satici <> p.id and not p.yonetici then raise exception 'Bu ilan sana ait değil.'; end if;
  if i.durum <> 'yayinda' then raise exception 'İlan zaten yayında değil.'; end if;
  perform oyun.ilan_kapat(i.id, 'kaldirildi', false);
  if i.satici <> p.id then
    perform oyun.bildir(i.satici, format('“%s” ilanın oyun yönetimi tarafından yayından kaldırıldı.', i.baslik), oyun.simdi());
  end if;
  return jsonb_build_object('tamam', true);
end $$;

-- ---------------------------------------------------------------------
-- F. SATIN AL / TEKLİF
-- ---------------------------------------------------------------------
create or replace function public.ilan_hemen_al(p_ilan bigint, p_fiyat numeric)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); i oyun.ilanlar;
begin
  select * into i from oyun.ilanlar where id = p_ilan for update;
  if i.id is null or i.durum <> 'yayinda' then raise exception 'Bu ilan artık yayında değil.'; end if;
  if i.fiyat <> p_fiyat then raise exception 'İlan fiyatı değişti; güncel fiyat % ₺. Sayfayı yenileyip tekrar dene.', oyun.tl(i.fiyat); end if;
  return oyun.ilan_devret(i.id, p.id, i.fiyat, 0, null);
end $$;

create or replace function public.ilan_teklif_ver(p_ilan bigint, p_tutar numeric, p_not text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); i oyun.ilanlar; tk oyun.ilan_teklifler;
  v_bant record; v_harc numeric; v_emanet numeric; v_not text; v_tur text; v_id bigint;
begin
  select * into i from oyun.ilanlar where id = p_ilan for update;
  if i.id is null or i.durum <> 'yayinda' or i.bitis <= v_t then raise exception 'Bu ilan artık yayında değil.'; end if;
  if i.satici = p.id then raise exception 'Kendi ilanına teklif veremezsin.'; end if;
  if not i.pazarlik then raise exception 'Satıcı bu ilanda teklif kabul etmiyor; ilan fiyatından satın alabilirsin.'; end if;
  if p_tutar is null or p_tutar <> round(p_tutar) or p_tutar < 1000 then raise exception 'Teklif en az 1.000 ₺ ve kuruşsuz olmalı.'; end if;
  if p_tutar >= i.fiyat then raise exception 'Teklifin ilan fiyatına eşit ya da yüksek; doğrudan “Hemen al” ile satın alabilirsin.'; end if;
  if p_tutar < ceil(i.fiyat * 0.5) then raise exception 'Teklif, ilan fiyatının en az yarısı olmalı (% ₺).', oyun.tl(ceil(i.fiyat * 0.5)); end if;
  select * into v_bant from oyun.ilan_bant(i.varlik, i.varlik_id, i.pay);
  if p_tutar < v_bant.alt then raise exception 'Bu teklif, bu varlık için izin verilen fiyat aralığının altında kalıyor.'; end if;
  if oyun.iliskili(i.satici, p.id) then perform oyun.iliskili_hata(); end if;
  v_not := nullif(btrim(coalesce(p_not, '')), '');
  if v_not is not null and (char_length(v_not) > 280 or oyun.kufurlu(v_not)) then
    raise exception 'Not en fazla 280 karakter olmalı ve uygunsuz ifade içermemeli.'; end if;
  select * into tk from oyun.ilan_teklifler where ilan_id = i.id and alici = p.id and durum in ('bekliyor','karsi') for update;
  if tk.id is null and (select count(*) from oyun.ilan_teklifler z where z.alici = p.id and z.durum in ('bekliyor','karsi')) >= 10 then
    raise exception 'Aynı anda en fazla 10 açık teklifin olabilir.'; end if;
  v_harc := oyun.ilan_harc(i.varlik, p_tutar); v_emanet := p_tutar + v_harc;
  v_tur := case when i.varlik in ('tapu','bolum') then 'emlak' else 'sirket' end;
  if tk.id is null then
    perform oyun.para_islem(p.id, -v_emanet, v_tur,
      format('İlan #%s: %s ₺ teklif Güvenli Ödeme’de bloke edildi%s', oyun.ilan_no(i.id), oyun.tl(p_tutar),
             case when v_harc > 0 then ' (tapu harcı dahil)' else '' end), v_t);
    insert into oyun.ilan_teklifler(ilan_id, alici, tutar, emanet, not_metni, durum, olusturma, bitis)
      values (i.id, p.id, p_tutar, v_emanet, v_not, 'bekliyor', v_t, v_t + interval '48 hours') returning id into v_id;
  else
    if v_emanet > tk.emanet then
      perform oyun.para_islem(p.id, -(v_emanet - tk.emanet), v_tur,
        format('İlan #%s: teklif %s ₺ olarak güncellendi, fark bloke edildi', oyun.ilan_no(i.id), oyun.tl(p_tutar)), v_t);
    elsif v_emanet < tk.emanet then
      perform oyun.para_islem(p.id, tk.emanet - v_emanet, 'iade',
        format('İlan #%s: teklif %s ₺ olarak güncellendi, fark iade edildi', oyun.ilan_no(i.id), oyun.tl(p_tutar)), v_t);
    end if;
    update oyun.ilan_teklifler set tutar = p_tutar, karsi = null, emanet = v_emanet, not_metni = v_not, durum = 'bekliyor',
                                   olusturma = v_t, bitis = v_t + interval '48 hours' where id = tk.id;
    v_id := tk.id;
  end if;
  perform oyun.bildir(i.satici, format('“%s” ilanına %s ₺ teklif geldi (%s). 48 saat içinde İlan Meydanı’ndan yanıtla.',
                                       i.baslik, oyun.tl(p_tutar), p.kad), v_t);
  return jsonb_build_object('tamam', true, 'teklif', v_id, 'emanet', v_emanet);
end $$;

create or replace function public.ilan_teklif_yanit(p_teklif bigint, p_karar text, p_karsi numeric default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); tk oyun.ilan_teklifler; i oyun.ilanlar; v_bant record;
begin
  select * into tk from oyun.ilan_teklifler where id = p_teklif for update;
  if tk.id is null then raise exception 'Teklif bulunamadı.'; end if;
  select * into i from oyun.ilanlar where id = tk.ilan_id for update;
  if i.satici <> p.id then raise exception 'Bu teklif senin ilanına ait değil.'; end if;
  if i.durum <> 'yayinda' then raise exception 'İlan artık yayında değil.'; end if;
  if p_karar = 'kabul' then
    if tk.durum <> 'bekliyor' then raise exception 'Bu teklif artık yanıt beklemiyor.'; end if;
    if tk.bitis <= v_t then raise exception 'Teklifin süresi dolmuş.'; end if;
    return oyun.ilan_devret(i.id, tk.alici, tk.tutar, tk.emanet, tk.id);
  elsif p_karar = 'red' then
    if tk.durum not in ('bekliyor','karsi') then raise exception 'Bu teklif artık açık değil.'; end if;
    perform oyun.ilan_teklif_kapat(tk.id, 'red',
      format('“%s” ilanına verdiğin %s ₺ teklif kabul edilmedi; emanetin iade edildi.', i.baslik, oyun.tl(tk.tutar)));
    return jsonb_build_object('tamam', true);
  elsif p_karar = 'karsi' then
    if tk.durum <> 'bekliyor' then raise exception 'Bu teklife zaten yanıt verdin.'; end if;
    if p_karsi is null or p_karsi <> round(p_karsi) or p_karsi <= tk.tutar or p_karsi > i.fiyat then
      raise exception 'Karşı teklif, alıcının teklifinden yüksek ve ilan fiyatından düşük ya da eşit olmalı.'; end if;
    select * into v_bant from oyun.ilan_bant(i.varlik, i.varlik_id, i.pay);
    if p_karsi > v_bant.ust then raise exception 'Karşı teklif izin verilen fiyat aralığının üstünde.'; end if;
    update oyun.ilan_teklifler set karsi = p_karsi, durum = 'karsi', bitis = v_t + interval '48 hours' where id = tk.id;
    perform oyun.bildir(tk.alici, format('Satıcı “%s” ilanı için karşı teklif verdi: %s ₺. 48 saat içinde İlan Meydanı’ndan yanıtla.',
                                         i.baslik, oyun.tl(p_karsi)), v_t);
    return jsonb_build_object('tamam', true);
  end if;
  raise exception 'Geçersiz karar.';
end $$;

create or replace function public.ilan_karsi_yanit(p_teklif bigint, p_kabul boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); tk oyun.ilan_teklifler; i oyun.ilanlar;
begin
  select * into tk from oyun.ilan_teklifler where id = p_teklif for update;
  if tk.id is null or tk.alici <> p.id then raise exception 'Teklif bulunamadı.'; end if;
  if tk.durum <> 'karsi' then raise exception 'Bu teklifte yanıt bekleyen bir karşı teklif yok.'; end if;
  select * into i from oyun.ilanlar where id = tk.ilan_id for update;
  if p_kabul then
    if tk.bitis <= v_t then raise exception 'Karşı teklifin süresi dolmuş.'; end if;
    return oyun.ilan_devret(i.id, p.id, tk.karsi, tk.emanet, tk.id);
  end if;
  perform oyun.ilan_teklif_kapat(tk.id, 'geri_cekildi', null);
  perform oyun.bildir(i.satici, format('%s, “%s” ilanı için verdiğin %s ₺ karşı teklifi kabul etmedi.', p.kad, i.baslik, oyun.tl(tk.karsi)), v_t);
  return jsonb_build_object('tamam', true);
end $$;

create or replace function public.ilan_teklif_geri_cek(p_teklif bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); tk oyun.ilan_teklifler; i oyun.ilanlar;
begin
  select * into tk from oyun.ilan_teklifler where id = p_teklif for update;
  if tk.id is null or tk.alici <> p.id then raise exception 'Teklif bulunamadı.'; end if;
  if tk.durum not in ('bekliyor','karsi') then raise exception 'Bu teklif artık açık değil.'; end if;
  select * into i from oyun.ilanlar where id = tk.ilan_id;
  perform oyun.ilan_teklif_kapat(tk.id, 'geri_cekildi', null);
  perform oyun.bildir(i.satici, format('%s, “%s” ilanına verdiği teklifi geri çekti.', p.kad, i.baslik), oyun.simdi());
  return jsonb_build_object('tamam', true);
end $$;

create or replace function public.ilan_favori(p_ilan bigint, p_ekle boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim();
begin
  if not exists (select 1 from oyun.ilanlar where id = p_ilan) then raise exception 'İlan bulunamadı.'; end if;
  if p_ekle then
    if (select count(*) from oyun.ilan_favori where user_id = p.id) >= 100 then raise exception 'En fazla 100 ilanı favorilerine ekleyebilirsin.'; end if;
    insert into oyun.ilan_favori(user_id, ilan_id, zaman) values (p.id, p_ilan, oyun.simdi()) on conflict do nothing;
  else
    delete from oyun.ilan_favori where user_id = p.id and ilan_id = p_ilan;
  end if;
  return jsonb_build_object('tamam', true, 'favori', p_ekle);
end $$;

create or replace function public.ilan_hesabim()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi();
begin
  return jsonb_build_object(
    'ilanlar', coalesce((select jsonb_agg(oyun.ilan_ozet(i.id, p.id) || jsonb_build_object(
        'teklif', (select count(*) from oyun.ilan_teklifler tk where tk.ilan_id = i.id and tk.durum in ('bekliyor','karsi')),
        'en_yuksek', (select max(tk.tutar) from oyun.ilan_teklifler tk where tk.ilan_id = i.id and tk.durum in ('bekliyor','karsi')),
        'favori_sayisi', (select count(*) from oyun.ilan_favori fv where fv.ilan_id = i.id),
        'kapanis', i.kapanis,
        'paketler', jsonb_build_object('vitrin', i.vitrin_bitis, 'ust_sira', i.ust_bitis, 'acil', i.acil_bitis, 'renkli', i.renkli_bitis))
        order by (i.durum = 'yayinda') desc, i.olusturma desc)
      from (select * from oyun.ilanlar z where z.satici = p.id order by (z.durum = 'yayinda') desc, z.olusturma desc limit 50) i), '[]'::jsonb),
    'gelen', coalesce((select jsonb_agg(jsonb_build_object(
        'id', tk.id, 'ilan', i.id, 'no', oyun.ilan_no(i.id), 'baslik', i.baslik, 'fiyat', i.fiyat, 'gorsel', i.varlik, 'kategori', i.kategori,
        'kisi', (select kad from oyun.profiller where id = tk.alici), 'tutar', tk.tutar, 'karsi', tk.karsi, 'durum', tk.durum,
        'bitis', tk.bitis, 'not', tk.not_metni, 'zaman', tk.olusturma)
        order by (tk.durum in ('bekliyor','karsi')) desc, tk.olusturma desc)
      from (select z.* from oyun.ilan_teklifler z join oyun.ilanlar zi on zi.id = z.ilan_id where zi.satici = p.id
             order by (z.durum in ('bekliyor','karsi')) desc, z.olusturma desc limit 50) tk
      join oyun.ilanlar i on i.id = tk.ilan_id), '[]'::jsonb),
    'giden', coalesce((select jsonb_agg(jsonb_build_object(
        'id', tk.id, 'ilan', i.id, 'no', oyun.ilan_no(i.id), 'baslik', i.baslik, 'fiyat', i.fiyat, 'gorsel', i.varlik, 'kategori', i.kategori,
        'kisi', (select kad from oyun.profiller where id = i.satici), 'tutar', tk.tutar, 'karsi', tk.karsi, 'durum', tk.durum,
        'emanet', tk.emanet, 'bitis', tk.bitis, 'not', tk.not_metni, 'zaman', tk.olusturma, 'ilan_durum', i.durum,
        'harc', oyun.ilan_harc(i.varlik, coalesce(tk.karsi, tk.tutar)))
        order by (tk.durum in ('bekliyor','karsi')) desc, tk.olusturma desc)
      from (select * from oyun.ilan_teklifler z where z.alici = p.id
             order by (z.durum in ('bekliyor','karsi')) desc, z.olusturma desc limit 50) tk
      join oyun.ilanlar i on i.id = tk.ilan_id), '[]'::jsonb),
    'favoriler', coalesce((select jsonb_agg(oyun.ilan_ozet(fv.ilan_id, p.id) order by fv.zaman desc)
      from (select * from oyun.ilan_favori z where z.user_id = p.id order by z.zaman desc limit 100) fv), '[]'::jsonb),
    'cuzdan', (select c.para from oyun.cuzdan c where c.user_id = p.id),
    'tarife', (select jsonb_agg(jsonb_build_object('kod', a.kod, 'ad', a.ad, 'tutar', a.tutar, 'gun', a.gun, 'aciklama', a.aciklama) order by a.sira)
                 from oyun.ilan_ayar a));
end $$;

-- ---------------------------------------------------------------------
-- G. BAKIM (zamanlayıcı): süresi dolan teklif ve ilanlar, geçersiz ilanlar
-- ---------------------------------------------------------------------
create or replace function oyun.ilan_bakim()
returns integer language plpgsql security definer set search_path = '' as $$
declare r record; v_t timestamptz := oyun.simdi(); v_n int := 0;
begin
  for r in select tk.id, i.baslik from oyun.ilan_teklifler tk join oyun.ilanlar i on i.id = tk.ilan_id
            where tk.durum in ('bekliyor','karsi') and tk.bitis <= v_t loop
    begin
      perform oyun.ilan_teklif_kapat(r.id, 'suresi_doldu',
        format('“%s” ilanına verdiğin teklifin süresi doldu; emanetin iade edildi.', r.baslik));
      v_n := v_n + 1;
    exception when others then raise warning 'ilan_bakim teklif %: %', r.id, sqlerrm;
    end;
  end loop;
  for r in select i.id, i.bitis from oyun.ilanlar i where i.durum = 'yayinda' loop
    begin
      if r.bitis <= v_t then perform oyun.ilan_kapat(r.id, 'suresi_doldu'); v_n := v_n + 1;
      elsif not oyun.ilan_gecerli(r.id) then perform oyun.ilan_kapat(r.id, 'gecersiz'); v_n := v_n + 1;
      end if;
    exception when others then raise warning 'ilan_bakim ilan %: %', r.id, sqlerrm;
    end;
  end loop;
  return v_n;
end $$;

-- ---------------------------------------------------------------------
-- H. ESKİ "SATILIK ŞİRKET" ALANIYLA EŞLEME
--    Eski ekrandan satilik verilirse ücretsiz ilan açılır / fiyat güncellenir;
--    satilik kaldırılırsa ilan kapanır. İlan Meydanı'nın kendi güncellemeleri atlanır.
-- ---------------------------------------------------------------------
create or replace function oyun.tg_ilan_satilik_senkron()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_ilan oyun.ilanlar; v_sahip uuid; v_t timestamptz := oyun.simdi();
begin
  if coalesce(current_setting('oyun.ilan_senkron', true), '') = '1' then return new; end if;
  if new.satilik is not distinct from old.satilik then return new; end if;
  select * into v_ilan from oyun.ilanlar i where i.varlik = 'sirket' and i.varlik_id = new.id and i.durum = 'yayinda' limit 1;
  if new.satilik is null then
    if v_ilan.id is not null then perform oyun.ilan_kapat(v_ilan.id, 'kaldirildi', false); end if;
    return new;
  end if;
  if v_ilan.id is not null then
    if new.satilik between 1000 and 1000000000 and new.satilik = round(new.satilik) and new.satilik <> v_ilan.fiyat then
      update oyun.ilanlar set onceki_fiyat = fiyat, fiyat = new.satilik where id = v_ilan.id;
    end if;
    return new;
  end if;
  select o.user_id into v_sahip from oyun.sirket_ortaklari o where o.sirket_id = new.id and o.pay = 100;
  if v_sahip is null or new.sektor = 'banka' or not new.aktif or new.satilik < 1000 or new.satilik > 1000000000
     or new.satilik <> round(new.satilik) then return new; end if;
  insert into oyun.ilanlar(kategori, varlik, varlik_id, pay, satici, baslik, aciklama, fiyat, ilk_fiyat, pazarlik,
                           il_id, sektor, kaynak, olusturma, siralama, bitis)
    values ('sirket', 'sirket', new.id, 100, v_sahip, left(new.ad, 52) || ' — devren satılık',
            'Şirketin tamamı devren satılık.', new.satilik, new.satilik, true,
            oyun.ilan_sirket_il(new.id), new.sektor, 'aktarim', v_t, v_t, v_t + interval '30 days')
    on conflict do nothing;
  return new;
end $$;

create or replace trigger ilan_satilik_senkron after update of satilik on oyun.sirketler
  for each row execute function oyun.tg_ilan_satilik_senkron();

-- Mevcut satılık şirketleri İlan Meydanı'na ücretsiz aktar (bir kez; tekrarında atlanır)
insert into oyun.ilanlar(kategori, varlik, varlik_id, pay, satici, baslik, aciklama, fiyat, ilk_fiyat, pazarlik,
                         il_id, sektor, kaynak, olusturma, siralama, bitis)
select 'sirket', 'sirket', s.id, 100, o.user_id, left(s.ad, 52) || ' — devren satılık',
       'Şirketin tamamı devren satılık.', s.satilik, s.satilik, true,
       oyun.ilan_sirket_il(s.id), s.sektor, 'aktarim', now(), now(), now() + interval '30 days'
  from oyun.sirketler s join oyun.sirket_ortaklari o on o.sirket_id = s.id and o.pay = 100
 where s.aktif and s.satilik is not null and s.sektor <> 'banka'
   and s.satilik between 1000 and 1000000000 and s.satilik = round(s.satilik)
   and exists (select 1 from oyun.profiller pr where pr.id = o.user_id and not pr.yasakli)
   and not exists (select 1 from oyun.ilanlar i where i.varlik = 'sirket' and i.varlik_id = s.id and i.durum = 'yayinda');

-- ---------------------------------------------------------------------
-- I. CANLI YAMA: müteahhitten ilk satışta ve Yatırım Pazarı'nda tapu harcı
--    Hazine'ye TL olarak yazılıyordu; Hazine milyar biriminde tutulur.
-- ---------------------------------------------------------------------
do $yama$
declare v_tanim text; v_yeni text; v_adet int := 0;
begin
  v_tanim := pg_get_functiondef('public.eko_emlak_islem(text,jsonb)'::regprocedure);
  v_yeni := replace(v_tanim, 'update oyun.ulke set hazine=hazine+harc where id=1;',
                             'update oyun.ulke set hazine=hazine+harc/oyun.pazar_tl_milyar() where id=1;');
  if v_yeni <> v_tanim then execute v_yeni; v_adet := v_adet + 1; end if;
  v_tanim := pg_get_functiondef('public.yatirim_pazar_islem(text,jsonb)'::regprocedure);
  v_yeni := replace(v_tanim, 'hazine=hazine+harc/1000000.0 where id=1', 'hazine=hazine+harc/oyun.pazar_tl_milyar() where id=1');
  v_yeni := replace(v_yeni, 'hazine=hazine+2*harc/1000000.0 where id=1', 'hazine=hazine+2*harc/oyun.pazar_tl_milyar() where id=1');
  if v_yeni <> v_tanim then execute v_yeni; v_adet := v_adet + 1; end if;
  raise notice 'ilan_meydani yamalari: % fonksiyon', v_adet;
exception when undefined_function then raise notice 'ilan_meydani yamasi atlandi: %', sqlerrm;
end $yama$;

-- ---------------------------------------------------------------------
-- J. ZAMANLAYICI VE YETKİLER
-- ---------------------------------------------------------------------
do $cron$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if exists (select 1 from cron.job where jobname = 'ilan-meydani-bakim') then perform cron.unschedule('ilan-meydani-bakim'); end if;
    perform cron.schedule('ilan-meydani-bakim', '3-59/10 * * * *', 'select oyun.ilan_bakim()');
  end if;
end $cron$;

do $yetki$
declare f text;
begin
  foreach f in array array[
    'public.ilan_meydani(jsonb)', 'public.ilan_detay(bigint)', 'public.ilan_varliklarim()', 'public.ilan_ver(jsonb)',
    'public.ilan_duzenle(bigint,jsonb)', 'public.ilan_one_cikar(bigint,text)', 'public.ilan_kaldir(bigint)',
    'public.ilan_hemen_al(bigint,numeric)', 'public.ilan_teklif_ver(bigint,numeric,text)',
    'public.ilan_teklif_yanit(bigint,text,numeric)', 'public.ilan_karsi_yanit(bigint,boolean)',
    'public.ilan_teklif_geri_cek(bigint)', 'public.ilan_favori(bigint,boolean)', 'public.ilan_hesabim()']
  loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
  foreach f in array array[
    'oyun.ilan_devret(bigint,uuid,numeric,numeric,bigint)', 'oyun.ilan_teklif_kapat(bigint,text,text)',
    'oyun.ilan_kapat(bigint,text,boolean)', 'oyun.ilan_varlik_temizle(text,bigint)', 'oyun.ilan_bakim()',
    'oyun.tg_ilan_satilik_senkron()']
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
end $yetki$;
-- =====================================================================
--  140 · MÜZAYEDE EVİ (25.10.2026)
--  Koleksiyon eserleri (tablo, siyasi tarih belgesi, sikke, pul, antika,
--  saat, klasik otomobil, mücevher, halı) açık artırmayla satılır.
--  · Müzayede evi kataloğdan sınırlı sayıda eser basar (her eserin baskı
--    adedi sabittir: sıradan 4, nadir 3, çok nadir 2, efsanevi 1) ve
--    sürekli ~6 lot açık tutar. Satış bedeli Hazine'ye gelir (para yutağı).
--  · Oyuncu pey verir; pey tutarı cüzdandan bloke edilir, pey geçilince
--    eski lidere anında iade edilir. Son 5 dakikada gelen pey süreyi
--    5 dakika uzatır (en fazla 2 saat).
--  · Eserin tahmini değeri = taban × kategori endeksi × kondisyon × prim
--    (× 1,25 set tamamlama). Kategori endeksi her gün gerçek satış
--    fiyatlarına (talep) göre yükselir ya da düşer; eserin kendi primi
--    son satış fiyatıyla şekillenir ve zamanla 1'e döner.
--  · Oyuncu eserini yeniden açık artırmaya çıkarabilir (%1 ilan ücreti,
--    satışta %7 komisyon), özel müzesinde sergileyip günlük sergi geliri
--    alabilir (günde en fazla 2.000 ₺), müzayede evine değerinin %50'sine
--    satabilir (alımdan 72 saat sonra) ya da Devlet Müzesi'ne bağışlayıp
--    kıdem puanı kazanabilir (bağış başına en fazla +5, toplam +20).
--  Yalnız yeni tablo / fonksiyon ekler; iki kez çalıştırmak güvenlidir.
-- =====================================================================

-- ---------------------------------------------------------------------
-- A. TABLOLAR
-- ---------------------------------------------------------------------
create table if not exists oyun.muzayede_kategori (
  kod text primary key,
  ad text not null,
  endeks numeric not null default 1 check (endeks > 0),
  guncelleme timestamptz,
  sira integer not null default 0
);
create table if not exists oyun.muzayede_endeks_gecmis (
  kategori text not null references oyun.muzayede_kategori(kod) on delete cascade,
  gun date not null,
  endeks numeric not null,
  primary key (kategori, gun)
);
create table if not exists oyun.muzayede_katalog (
  kod text primary key,
  ad text not null,
  kategori text not null references oyun.muzayede_kategori(kod),
  seri text not null,
  nadirlik text not null check (nadirlik in ('siradan','nadir','cok_nadir','efsanevi')),
  taban numeric not null check (taban > 0),
  adet integer not null check (adet between 1 and 10),
  motif text not null,
  renk text not null default '#c9a227',
  donem text,
  aciklama text not null
);
create table if not exists oyun.muzayede_eserler (
  id bigserial primary key,
  katalog text not null references oyun.muzayede_katalog(kod),
  no integer not null,
  kondisyon numeric not null check (kondisyon between 0.5 and 1.5),
  prim numeric not null default 1 check (prim between 0.3 and 3),
  sahip uuid references oyun.profiller(id) on delete set null,
  durum text not null default 'havuz' check (durum in ('havuz','kasa','sergide','artirmada','muzede')),
  alis_bedeli numeric,
  alis_zaman timestamptz,
  son_fiyat numeric,
  son_satis timestamptz,
  sergi_bas timestamptz,
  bagisci uuid references oyun.profiller(id) on delete set null,
  bagis_zaman timestamptz,
  bagis_kidem numeric not null default 0,
  olusturma timestamptz not null default now(),
  unique (katalog, no)
);
create index if not exists muzayede_eser_sahip_idx on oyun.muzayede_eserler(sahip) where sahip is not null;
create index if not exists muzayede_eser_durum_idx on oyun.muzayede_eserler(durum);

create table if not exists oyun.muzayede_lotlar (
  id bigserial primary key,
  eser_id bigint not null references oyun.muzayede_eserler(id),
  satici uuid references oyun.profiller(id) on delete set null,
  baslangic numeric not null check (baslangic >= 100),
  bitis timestamptz not null,
  ilk_bitis timestamptz not null,
  durum text not null default 'acik' check (durum in ('acik','satildi','satilmadi','iptal')),
  en_yuksek numeric,
  lider uuid references oyun.profiller(id) on delete set null,
  pey_sayisi integer not null default 0,
  ucret numeric not null default 0,
  olusturma timestamptz not null default now(),
  kapanis timestamptz
);
create unique index if not exists muzayede_lot_tek_acik on oyun.muzayede_lotlar(eser_id) where durum = 'acik';
create index if not exists muzayede_lot_acik_idx on oyun.muzayede_lotlar(bitis) where durum = 'acik';
create index if not exists muzayede_lot_satici_idx on oyun.muzayede_lotlar(satici, olusturma desc);

create table if not exists oyun.muzayede_peyler (
  id bigserial primary key,
  lot_id bigint not null references oyun.muzayede_lotlar(id) on delete cascade,
  kim uuid not null references oyun.profiller(id) on delete cascade,
  tutar numeric not null check (tutar > 0),
  zaman timestamptz not null default now(),
  durum text not null default 'lider' check (durum in ('lider','gecildi','kazandi','iade'))
);
create index if not exists muzayede_pey_lot_idx on oyun.muzayede_peyler(lot_id, zaman desc);
create index if not exists muzayede_pey_kim_idx on oyun.muzayede_peyler(kim, zaman desc);

create table if not exists oyun.muzayede_satislar (
  id bigserial primary key,
  lot_id bigint references oyun.muzayede_lotlar(id) on delete set null,
  eser_id bigint not null references oyun.muzayede_eserler(id),
  kategori text not null,
  satici uuid,
  alici uuid,
  fiyat numeric not null,
  model_deger numeric not null,
  tur text not null default 'artirma' check (tur in ('artirma','eve_satis','satilmadi')),
  zaman timestamptz not null default now()
);
alter table oyun.muzayede_satislar add column if not exists pey_sayisi integer not null default 0;
create index if not exists muzayede_satis_kat_idx on oyun.muzayede_satislar(kategori, zaman desc);
create index if not exists muzayede_satis_eser_idx on oyun.muzayede_satislar(eser_id, zaman desc);

create table if not exists oyun.muzayede_sergi_odeme (
  user_id uuid not null references oyun.profiller(id) on delete cascade,
  gun date not null,
  tutar numeric not null,
  primary key (user_id, gun)
);
create table if not exists oyun.muzayede_ayar (
  id integer primary key default 1 check (id = 1),
  acik_lot_hedef integer not null default 6,
  son_gunluk date,
  son_efsanevi timestamptz,
  sergi_tavan numeric not null default 2000,
  komisyon numeric not null default 0.07,
  eve_satis_oran numeric not null default 0.5,
  baslangic_oran numeric not null default 0.6
);
insert into oyun.muzayede_ayar(id) values (1) on conflict (id) do nothing;

alter table oyun.muzayede_kategori enable row level security;
alter table oyun.muzayede_endeks_gecmis enable row level security;
alter table oyun.muzayede_katalog enable row level security;
alter table oyun.muzayede_eserler enable row level security;
alter table oyun.muzayede_lotlar enable row level security;
alter table oyun.muzayede_peyler enable row level security;
alter table oyun.muzayede_satislar enable row level security;
alter table oyun.muzayede_sergi_odeme enable row level security;
alter table oyun.muzayede_ayar enable row level security;

