-- ---------------------------------------------------------------------
-- C. YARDIMCILAR
-- ---------------------------------------------------------------------
create or replace function oyun.mz_nadirlik_ad(p text) returns text language sql immutable set search_path = '' as $$
  select case p when 'siradan' then 'Sıradan' when 'nadir' then 'Nadir' when 'cok_nadir' then 'Çok nadir' when 'efsanevi' then 'Efsanevi' else p end
$$;
create or replace function oyun.mz_sergi_oran(p text) returns numeric language sql immutable set search_path = '' as $$
  select case p when 'efsanevi' then 0.0025 when 'cok_nadir' then 0.0022 when 'nadir' then 0.0018 else 0.0015 end
$$;
create or replace function oyun.mz_yuvarla(p numeric) returns numeric language sql immutable set search_path = '' as $$
  select case when p >= 100000 then round(p / 1000) * 1000 when p >= 10000 then round(p / 100) * 100 else round(p / 50) * 50 end
$$;
-- Oyuncu bir serinin bütün eserlerine sahip mi (müzede ya da havuzdakiler hariç)
create or replace function oyun.mz_set_tam(p_sahip uuid, p_seri text) returns boolean
language sql stable set search_path = '' as $$
  select p_sahip is not null and
    (select count(distinct k.kod) from oyun.muzayede_katalog k where k.seri = p_seri) =
    (select count(distinct e.katalog) from oyun.muzayede_eserler e join oyun.muzayede_katalog k on k.kod = e.katalog
      where k.seri = p_seri and e.sahip = p_sahip and e.durum in ('kasa','sergide','artirmada'))
$$;
-- Model değer (prim hariç) ve tahmini değer
create or replace function oyun.mz_model(p_eser bigint) returns numeric
language sql stable set search_path = '' as $$
  select k.taban * c.endeks * e.kondisyon
    from oyun.muzayede_eserler e join oyun.muzayede_katalog k on k.kod = e.katalog join oyun.muzayede_kategori c on c.kod = k.kategori
   where e.id = p_eser
$$;
create or replace function oyun.mz_deger(p_eser bigint) returns numeric
language sql stable set search_path = '' as $$
  select oyun.mz_yuvarla(k.taban * c.endeks * e.kondisyon * e.prim
           * case when e.sahip is not null and oyun.mz_set_tam(e.sahip, k.seri) then 1.25 else 1 end)
    from oyun.muzayede_eserler e join oyun.muzayede_katalog k on k.kod = e.katalog join oyun.muzayede_kategori c on c.kod = k.kategori
   where e.id = p_eser
$$;
create or replace function oyun.mz_kad(p uuid) returns text language sql stable set search_path = '' as $$
  select kad from oyun.profiller where id = p
$$;
-- Bir sonraki geçerli pey alt sınırı
create or replace function oyun.mz_min_pey(p_lot bigint) returns numeric
language sql stable set search_path = '' as $$
  select case when l.pey_sayisi = 0 or l.en_yuksek is null then l.baslangic
              else l.en_yuksek + greatest(100, ceil(l.en_yuksek * 0.05 / 100) * 100) end
    from oyun.muzayede_lotlar l where l.id = p_lot
$$;

create or replace function oyun.mz_eser_ozet(p_eser bigint, p_u uuid) returns jsonb
language sql stable set search_path = '' as $$
  select jsonb_build_object(
    'id', e.id, 'kod', k.kod, 'ad', k.ad, 'kategori', k.kategori, 'kategori_ad', c.ad, 'seri', k.seri,
    'nadirlik', k.nadirlik, 'nadirlik_ad', oyun.mz_nadirlik_ad(k.nadirlik), 'no', e.no, 'adet', k.adet,
    'motif', k.motif, 'renk', k.renk, 'donem', k.donem, 'aciklama', k.aciklama,
    'kondisyon', round(e.kondisyon, 2), 'deger', oyun.mz_deger(e.id), 'durum', e.durum,
    'sahip', oyun.mz_kad(e.sahip), 'benim', e.sahip is not null and e.sahip = p_u,
    'set_tam', e.sahip is not null and oyun.mz_set_tam(e.sahip, k.seri),
    'son_fiyat', e.son_fiyat, 'son_satis', e.son_satis,
    'alis_bedeli', case when e.sahip = p_u then e.alis_bedeli end,
    'alis_zaman', case when e.sahip = p_u then e.alis_zaman end,
    'bagisci', oyun.mz_kad(e.bagisci), 'bagis_zaman', e.bagis_zaman)
  from oyun.muzayede_eserler e join oyun.muzayede_katalog k on k.kod = e.katalog join oyun.muzayede_kategori c on c.kod = k.kategori
  where e.id = p_eser
$$;

create or replace function oyun.mz_lot_ozet(p_lot bigint, p_u uuid) returns jsonb
language sql stable set search_path = '' as $$
  select jsonb_build_object(
    'id', l.id, 'eser', oyun.mz_eser_ozet(l.eser_id, p_u), 'baslangic', l.baslangic, 'bitis', l.bitis,
    'durum', l.durum, 'en_yuksek', l.en_yuksek, 'pey_sayisi', l.pey_sayisi, 'lider', oyun.mz_kad(l.lider),
    'lider_benim', l.lider is not null and l.lider = p_u, 'satici', coalesce(oyun.mz_kad(l.satici), 'Müzayede Evi'),
    'satici_benim', l.satici is not null and l.satici = p_u, 'min_pey', oyun.mz_min_pey(l.id),
    'peyim', (select max(pp.tutar) from oyun.muzayede_peyler pp where pp.lot_id = l.id and pp.kim = p_u),
    'uzadi', l.bitis > l.ilk_bitis)
  from oyun.muzayede_lotlar l where l.id = p_lot
$$;

-- ---------------------------------------------------------------------
-- D. ÇEKİRDEK İŞLEMLER (yalnız sunucu içinden çağrılır)
-- ---------------------------------------------------------------------
-- Kataloğdan yeni bir eser bas (baskı adedi dolmamışsa); kondisyon 0,85–1,25
create or replace function oyun.mz_eser_bas(p_katalog text) returns bigint
language plpgsql security definer set search_path = '' as $$
declare k oyun.muzayede_katalog; v_no integer; v_id bigint; v_kond numeric;
begin
  select * into k from oyun.muzayede_katalog where kod = p_katalog;
  if k.kod is null then return null; end if;
  perform pg_advisory_xact_lock(91407, hashtext(p_katalog));
  select coalesce(max(no), 0) + 1 into v_no from oyun.muzayede_eserler where katalog = k.kod;
  if v_no > k.adet then return null; end if;
  v_kond := round((0.85 + (random() + random() + random()) / 3 * 0.40)::numeric, 2);
  insert into oyun.muzayede_eserler(katalog, no, kondisyon, durum) values (k.kod, v_no, v_kond, 'havuz') returning id into v_id;
  return v_id;
end $$;

-- Müzayede evinin açık lot sayısını hedefte tut (önce havuzdaki eserler, sonra yeni baskı)
create or replace function oyun.mz_sistem_lot_ac(p_adet integer default null) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  a oyun.muzayede_ayar; v_t timestamptz := oyun.simdi(); v_acik integer; v_eksik integer; v_acilan integer := 0;
  v_nad text; v_eser bigint; v_saat numeric; v_deger numeric; r double precision; v_deneme integer;
begin
  if not oyun.uzaktan_modul_acik('muzayede') then return 0; end if;
  perform pg_advisory_xact_lock(91407, 1);
  select * into a from oyun.muzayede_ayar where id = 1 for update;
  select count(*) into v_acik from oyun.muzayede_lotlar where durum = 'acik' and satici is null;
  v_eksik := coalesce(p_adet, a.acik_lot_hedef - v_acik);
  while v_eksik > 0 loop
    v_eser := null; v_deneme := 0;
    while v_eser is null and v_deneme < 6 loop
      v_deneme := v_deneme + 1;
      r := random();
      v_nad := case when r < 0.05 then 'efsanevi' when r < 0.22 then 'cok_nadir' when r < 0.55 then 'nadir' else 'siradan' end;
      if v_nad = 'efsanevi' and (exists (select 1 from oyun.muzayede_lotlar l join oyun.muzayede_eserler e on e.id = l.eser_id
             join oyun.muzayede_katalog k on k.kod = e.katalog where l.durum = 'acik' and k.nadirlik = 'efsanevi')
           or (a.son_efsanevi is not null and a.son_efsanevi > v_t - interval '72 hours')) then
        v_nad := 'cok_nadir';
      end if;
      -- 1) havuzda bekleyen (satılmamış / müzayede evine satılmış) eser
      select e.id into v_eser from oyun.muzayede_eserler e join oyun.muzayede_katalog k on k.kod = e.katalog
       where e.durum = 'havuz' and e.sahip is null and k.nadirlik = v_nad
         and not exists (select 1 from oyun.muzayede_lotlar l where l.eser_id = e.id and l.durum = 'acik')
         and not exists (select 1 from oyun.muzayede_lotlar l where l.eser_id = e.id and l.kapanis > v_t - interval '12 hours')
       order by random() limit 1;
      -- 2) yeni baskı
      if v_eser is null then
        select oyun.mz_eser_bas(x.kod) into v_eser from (
          select k.kod from oyun.muzayede_katalog k
           where k.nadirlik = v_nad and (select count(*) from oyun.muzayede_eserler e where e.katalog = k.kod) < k.adet
           order by random() limit 1) x;
      end if;
    end loop;
    exit when v_eser is null;
    v_saat := case v_nad when 'efsanevi' then 48 when 'cok_nadir' then 24 + random() * 12 when 'nadir' then 20 + random() * 8 else 14 + random() * 8 end;
    v_deger := oyun.mz_deger(v_eser);
    insert into oyun.muzayede_lotlar(eser_id, satici, baslangic, bitis, ilk_bitis)
      values (v_eser, null, greatest(500, oyun.mz_yuvarla(v_deger * a.baslangic_oran)),
              date_trunc('minute', v_t + make_interval(secs => v_saat * 3600)), date_trunc('minute', v_t + make_interval(secs => v_saat * 3600)));
    update oyun.muzayede_eserler set durum = 'artirmada' where id = v_eser;
    if v_nad = 'efsanevi' then update oyun.muzayede_ayar set son_efsanevi = v_t where id = 1; end if;
    v_acilan := v_acilan + 1; v_eksik := v_eksik - 1;
  end loop;
  return v_acilan;
end $$;

-- Süresi dolan lotu sonuçlandır
create or replace function oyun.mz_lot_kapat(p_lot bigint) returns void
language plpgsql security definer set search_path = '' as $$
declare
  l oyun.muzayede_lotlar; e oyun.muzayede_eserler; k oyun.muzayede_katalog; a oyun.muzayede_ayar;
  v_t timestamptz := oyun.simdi(); v_model numeric; v_kom numeric; v_oran numeric;
begin
  select * into l from oyun.muzayede_lotlar where id = p_lot for update;
  if l.id is null or l.durum <> 'acik' or l.bitis > v_t then return; end if;
  select * into a from oyun.muzayede_ayar where id = 1;
  select * into e from oyun.muzayede_eserler where id = l.eser_id for update;
  select * into k from oyun.muzayede_katalog where kod = e.katalog;
  v_model := oyun.mz_model(e.id);
  if l.lider is not null and l.en_yuksek is not null then
    -- Eser kazanana; pey zaten bloke edilmişti
    v_oran := greatest(0.3, least(3, l.en_yuksek / nullif(v_model, 0)));
    update oyun.muzayede_eserler
       set sahip = l.lider, durum = 'kasa', alis_bedeli = l.en_yuksek, alis_zaman = v_t, son_fiyat = l.en_yuksek, son_satis = v_t,
           sergi_bas = null, prim = greatest(0.6, least(2.2, round((e.prim * 0.5 + sqrt(v_oran) * 0.5)::numeric, 4)))
     where id = e.id;
    update oyun.muzayede_peyler set durum = 'kazandi' where lot_id = l.id and kim = l.lider and durum = 'lider';
    update oyun.muzayede_lotlar set durum = 'satildi', kapanis = v_t where id = l.id;
    if l.satici is not null then
      v_kom := round(l.en_yuksek * a.komisyon);
      perform oyun.para_islem(l.satici, l.en_yuksek - v_kom, 'muzayede',
        format('Müzayede: “%s” satıldı (%%%s komisyon düşüldü)', k.ad, round(a.komisyon * 100)), v_t, v_kom);
      update oyun.ulke set hazine = hazine + v_kom / oyun.pazar_tl_milyar() where id = 1;
      perform oyun.bildir(l.satici, format('Müzayede: “%s” eserin %s ₺ bedelle %s adlı oyuncuya satıldı.', k.ad, oyun.tl(l.en_yuksek), oyun.mz_kad(l.lider)), v_t);
    else
      update oyun.ulke set hazine = hazine + l.en_yuksek / oyun.pazar_tl_milyar() where id = 1;
    end if;
    insert into oyun.muzayede_satislar(lot_id, eser_id, kategori, satici, alici, fiyat, model_deger, tur, zaman, pey_sayisi)
      values (l.id, e.id, k.kategori, l.satici, l.lider, l.en_yuksek, v_model, 'artirma', v_t, l.pey_sayisi);
    perform oyun.bildir(l.lider, format('Müzayede: “%s” artık senin! %s ₺ ile açık artırmayı kazandın; eser koleksiyonuna eklendi.', k.ad, oyun.tl(l.en_yuksek)), v_t);
  else
    update oyun.muzayede_lotlar set durum = 'satilmadi', kapanis = v_t where id = l.id;
    if l.satici is not null then
      update oyun.muzayede_eserler set durum = case when sahip = l.satici then 'kasa' else durum end where id = e.id;
      perform oyun.bildir(l.satici, format('Müzayede: “%s” için pey gelmedi; eser koleksiyonuna geri döndü.', k.ad), v_t);
    else
      update oyun.muzayede_eserler set durum = 'havuz', sahip = null where id = e.id;
      insert into oyun.muzayede_satislar(lot_id, eser_id, kategori, satici, alici, fiyat, model_deger, tur, zaman)
        values (l.id, e.id, k.kategori, null, null, 0, v_model, 'satilmadi', v_t);
    end if;
  end if;
end $$;

-- Günlük: kategori endeksleri (talep), primlerin 1'e dönüşü, sergi gelirleri
create or replace function oyun.mz_gunluk() returns void
language plpgsql security definer set search_path = '' as $$
declare
  a oyun.muzayede_ayar; v_t timestamptz := oyun.simdi(); v_gun date := (oyun.simdi() at time zone 'Europe/Istanbul')::date;
  c record; v_talep numeric; v_n integer; v_deg numeric; r record; v_gelir numeric;
begin
  select * into a from oyun.muzayede_ayar where id = 1 for update;
  if a.son_gunluk is not null and a.son_gunluk >= v_gun then return; end if;
  update oyun.muzayede_ayar set son_gunluk = v_gun where id = 1;
  -- 1) Endeks: son 7 günün rekabeti. Her lot için talep puanı: satılmadı −1, tek pey 0, 2–3 pey +0,5,
  --    4+ pey +1; çekiç fiyatı tahmini değeri aşarsa aşan oran kadar (en çok +1) eklenir.
  for c in select * from oyun.muzayede_kategori loop
    select count(*), avg(case when s.tur = 'satilmadi' then -1
                              else (case when s.pey_sayisi >= 4 then 1 when s.pey_sayisi >= 2 then 0.5 else 0 end)
                                   + greatest(0, least(1, s.fiyat / nullif(s.model_deger, 0) - 1)) end)
      into v_n, v_talep
      from oyun.muzayede_satislar s where s.kategori = c.kod and s.zaman > v_t - interval '7 days' and s.tur in ('artirma','satilmadi');
    if v_n = 0 or v_talep is null then v_deg := -0.002;           -- işlem yoksa piyasa çok hafif soğur
    else v_deg := greatest(-0.04, least(0.06, 0.03 * v_talep)); end if;
    v_deg := v_deg + (random() * 0.016 - 0.008);
    update oyun.muzayede_kategori set endeks = greatest(0.4, least(4, round((endeks * (1 + v_deg))::numeric, 4))), guncelleme = v_t where kod = c.kod;
    insert into oyun.muzayede_endeks_gecmis(kategori, gun, endeks)
      select kod, v_gun, endeks from oyun.muzayede_kategori where kod = c.kod
      on conflict (kategori, gun) do update set endeks = excluded.endeks;
  end loop;
  -- 2) Son satıştan gelen prim her gün %3 sönümlenir
  update oyun.muzayede_eserler set prim = round((1 + (prim - 1) * 0.97)::numeric, 4) where prim <> 1 and durum <> 'muzede';
  -- 3) Sergi geliri (en az 20 saattir sergide olan eserler; kişi başı tavan)
  for r in select e.sahip, sum(oyun.mz_deger(e.id) * oyun.mz_sergi_oran(k.nadirlik)) as gelir, count(*) as n
             from oyun.muzayede_eserler e join oyun.muzayede_katalog k on k.kod = e.katalog
             join oyun.profiller p on p.id = e.sahip and not p.yasakli
            where e.durum = 'sergide' and e.sahip is not null and e.sergi_bas <= v_t - interval '20 hours'
            group by e.sahip loop
    v_gelir := least(a.sergi_tavan, round(r.gelir));
    continue when v_gelir < 1;
    insert into oyun.muzayede_sergi_odeme(user_id, gun, tutar) values (r.sahip, v_gun, v_gelir) on conflict do nothing;
    if found then
      perform oyun.para_islem(r.sahip, v_gelir, 'muzayede', format('Müzayede: özel müzendeki %s eserin sergi geliri', r.n), v_t);
      update oyun.ulke set hazine = hazine - v_gelir / oyun.pazar_tl_milyar() where id = 1;
    end if;
  end loop;
end $$;

-- Zamanlayıcı: lotları kapat, günlük işleri yap, salonu doldur
create or replace function oyun.muzayede_bakim() returns void
language plpgsql security definer set search_path = '' as $$
declare r record;
begin
  for r in select id from oyun.muzayede_lotlar where durum = 'acik' and bitis <= oyun.simdi() order by bitis limit 200 loop
    begin
      perform oyun.mz_lot_kapat(r.id);
    exception when others then
      raise warning 'muzayede lot % kapatılamadı: %', r.id, sqlerrm;
    end;
  end loop;
  perform oyun.mz_gunluk();
  perform oyun.mz_sistem_lot_ac();
end $$;

-- ---------------------------------------------------------------------
-- E. OYUNCU İŞLEMLERİ (public RPC)
-- ---------------------------------------------------------------------
-- Salon: açık lotlar, kategori endeksleri, son satışlar, kişisel özet
create or replace function public.muzayede_salon()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); a oyun.muzayede_ayar;
begin
  select * into a from oyun.muzayede_ayar where id = 1;
  -- Zamanlayıcıyı beklemeden süresi dolanları kapat (kısa ve güvenli)
  perform oyun.mz_lot_kapat(l.id) from oyun.muzayede_lotlar l where l.durum = 'acik' and l.bitis <= v_t;
  return jsonb_build_object(
    'simdi', v_t, 'acik', oyun.uzaktan_modul_acik('muzayede'),
    'lotlar', coalesce((select jsonb_agg(oyun.mz_lot_ozet(l.id, p.id) order by l.bitis)
                          from oyun.muzayede_lotlar l where l.durum = 'acik'), '[]'::jsonb),
    'kategoriler', coalesce((select jsonb_agg(jsonb_build_object('kod', c.kod, 'ad', c.ad, 'endeks', round(c.endeks, 4),
          'degisim7', round(((c.endeks / nullif((select g.endeks from oyun.muzayede_endeks_gecmis g where g.kategori = c.kod and g.gun <= (v_t at time zone 'Europe/Istanbul')::date - 7 order by g.gun desc limit 1), 0)) - 1) * 100, 1),
          'seri', coalesce((select jsonb_agg(g.endeks order by g.gun) from (select * from oyun.muzayede_endeks_gecmis g2 where g2.kategori = c.kod order by g2.gun desc limit 30) g), '[]'::jsonb)
        ) order by c.sira) from oyun.muzayede_kategori c), '[]'::jsonb),
    'son_satislar', coalesce((select jsonb_agg(x order by (x->>'zaman') desc) from (
        select jsonb_build_object('eser', k.ad, 'nadirlik', k.nadirlik, 'motif', k.motif, 'renk', k.renk, 'fiyat', s.fiyat,
               'alici', oyun.mz_kad(s.alici), 'zaman', s.zaman, 'oran', round(s.fiyat / nullif(s.model_deger, 0), 2)) x
          from oyun.muzayede_satislar s join oyun.muzayede_eserler e on e.id = s.eser_id join oyun.muzayede_katalog k on k.kod = e.katalog
         where s.tur = 'artirma' order by s.zaman desc limit 12) t), '[]'::jsonb),
    'benim', jsonb_build_object(
      'eser', (select count(*) from oyun.muzayede_eserler e where e.sahip = p.id and e.durum in ('kasa','sergide','artirmada')),
      'deger', coalesce((select sum(oyun.mz_deger(e.id)) from oyun.muzayede_eserler e where e.sahip = p.id and e.durum in ('kasa','sergide','artirmada')), 0),
      'lider', (select count(*) from oyun.muzayede_lotlar l where l.durum = 'acik' and l.lider = p.id),
      'bloke', coalesce((select sum(l.en_yuksek) from oyun.muzayede_lotlar l where l.durum = 'acik' and l.lider = p.id), 0),
      'cuzdan', (select c.para from oyun.cuzdan c where c.user_id = p.id)),
    'kurallar', jsonb_build_object('komisyon', a.komisyon, 'eve_satis_oran', a.eve_satis_oran, 'sergi_tavan', a.sergi_tavan,
      'baslangic_oran', a.baslangic_oran));
end $$;

create or replace function public.muzayede_lot(p_lot bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); l oyun.muzayede_lotlar; k oyun.muzayede_katalog; e oyun.muzayede_eserler;
begin
  select * into l from oyun.muzayede_lotlar where id = p_lot;
  if l.id is null then raise exception 'Lot bulunamadı.'; end if;
  if l.durum = 'acik' and l.bitis <= oyun.simdi() then perform oyun.mz_lot_kapat(l.id); end if;
  select * into e from oyun.muzayede_eserler where id = l.eser_id;
  select * into k from oyun.muzayede_katalog where kod = e.katalog;
  return oyun.mz_lot_ozet(l.id, p.id) || jsonb_build_object(
    'simdi', oyun.simdi(),
    'peyler', coalesce((select jsonb_agg(jsonb_build_object('kim', oyun.mz_kad(x.kim), 'benim', x.kim = p.id, 'tutar', x.tutar, 'zaman', x.zaman, 'durum', x.durum) order by x.zaman desc)
                          from (select * from oyun.muzayede_peyler pp where pp.lot_id = l.id order by pp.zaman desc limit 25) x), '[]'::jsonb),
    'gecmis', coalesce((select jsonb_agg(jsonb_build_object('fiyat', s.fiyat, 'zaman', s.zaman, 'alici', oyun.mz_kad(s.alici)) order by s.zaman desc)
                          from (select * from oyun.muzayede_satislar s2 where s2.eser_id = e.id and s2.tur = 'artirma' order by s2.zaman desc limit 8) s), '[]'::jsonb),
    'endeks', coalesce((select jsonb_agg(g.endeks order by g.gun) from (select * from oyun.muzayede_endeks_gecmis g2 where g2.kategori = k.kategori order by g2.gun desc limit 30) g), '[]'::jsonb),
    'seri_eserler', coalesce((select jsonb_agg(jsonb_build_object('ad', kk.ad, 'nadirlik', kk.nadirlik, 'motif', kk.motif, 'renk', kk.renk,
          'bende', exists (select 1 from oyun.muzayede_eserler ee where ee.katalog = kk.kod and ee.sahip = p.id and ee.durum in ('kasa','sergide','artirmada'))) order by kk.taban)
        from oyun.muzayede_katalog kk where kk.seri = k.seri), '[]'::jsonb));
end $$;

-- Pey ver: tutar bloke edilir, geçilen eski lidere iade edilir; son 5 dakikada süre uzar
create or replace function public.muzayede_pey(p_lot bigint, p_tutar numeric)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); l oyun.muzayede_lotlar; k oyun.muzayede_katalog;
  v_min numeric; v_tutar numeric := round(coalesce(p_tutar, 0)); v_eski uuid; v_eski_tutar numeric; v_bitis timestamptz;
begin
  if not oyun.uzaktan_modul_acik('muzayede') then raise exception 'Müzayede evi şu an geçici olarak kapalı.'; end if;
  select * into l from oyun.muzayede_lotlar where id = p_lot for update;
  if l.id is null then raise exception 'Lot bulunamadı.'; end if;
  if l.durum <> 'acik' or l.bitis <= v_t then raise exception 'Bu açık artırma sona erdi.'; end if;
  if l.satici = p.id then raise exception 'Kendi eserine pey veremezsin.'; end if;
  if l.satici is not null and oyun.iliskili(l.satici, p.id) then perform oyun.iliskili_hata(); end if;
  select k2.* into k from oyun.muzayede_eserler e join oyun.muzayede_katalog k2 on k2.kod = e.katalog where e.id = l.eser_id;
  v_min := oyun.mz_min_pey(l.id);
  if v_tutar < v_min then raise exception 'Pey en az % ₺ olmalı.', oyun.tl(v_min); end if;
  if v_tutar > 100000000 then raise exception 'Pey tutarı çok yüksek.'; end if;
  v_eski := l.lider; v_eski_tutar := l.en_yuksek;
  if v_eski = p.id then
    -- Kendi peyini yükseltiyor: yalnız fark bloke edilir
    perform oyun.para_islem(p.id, -(v_tutar - v_eski_tutar), 'muzayede', format('Müzayede: “%s” peyini %s ₺''ye yükselttin (fark bloke edildi)', k.ad, oyun.tl(v_tutar)), v_t);
    update oyun.muzayede_peyler set durum = 'gecildi' where lot_id = l.id and kim = p.id and durum = 'lider';
  else
    perform oyun.para_islem(p.id, -v_tutar, 'muzayede', format('Müzayede: “%s” için %s ₺ pey (bloke)', k.ad, oyun.tl(v_tutar)), v_t);
    if v_eski is not null then
      perform oyun.para_islem(v_eski, v_eski_tutar, 'iade', format('Müzayede: “%s” peyin geçildi, %s ₺ iade edildi', k.ad, oyun.tl(v_eski_tutar)), v_t);
      update oyun.muzayede_peyler set durum = 'gecildi' where lot_id = l.id and kim = v_eski and durum = 'lider';
      perform oyun.bildir(v_eski, format('Müzayede: “%s” lotunda peyin geçildi! Yeni pey %s ₺. Bloke ettiğin %s ₺ cüzdanına döndü.', k.ad, oyun.tl(v_tutar), oyun.tl(v_eski_tutar)), v_t);
    end if;
  end if;
  insert into oyun.muzayede_peyler(lot_id, kim, tutar, zaman, durum) values (l.id, p.id, v_tutar, v_t, 'lider');
  v_bitis := l.bitis;
  if l.bitis - v_t < interval '5 minutes' then v_bitis := least(l.ilk_bitis + interval '2 hours', v_t + interval '5 minutes'); end if;
  update oyun.muzayede_lotlar set en_yuksek = v_tutar, lider = p.id, pey_sayisi = pey_sayisi + 1, bitis = greatest(bitis, v_bitis) where id = l.id;
  return public.muzayede_lot(l.id);
end $$;

-- Koleksiyonum
create or replace function public.muzayede_koleksiyonum()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); a oyun.muzayede_ayar; v_bagis numeric;
begin
  select * into a from oyun.muzayede_ayar where id = 1;
  select coalesce(sum(bagis_kidem), 0) into v_bagis from oyun.muzayede_eserler where bagisci = p.id;
  return jsonb_build_object(
    'simdi', oyun.simdi(),
    'eserler', coalesce((select jsonb_agg(oyun.mz_eser_ozet(e.id, p.id) || jsonb_build_object(
          'lot', (select l.id from oyun.muzayede_lotlar l where l.eser_id = e.id and l.durum = 'acik'),
          'sergi_gunluk', case when e.durum = 'sergide' then round(oyun.mz_deger(e.id) * oyun.mz_sergi_oran(k.nadirlik)) end,
          'sergi_bas', e.sergi_bas,
          'eve_satis', oyun.mz_yuvarla(oyun.mz_deger(e.id) * a.eve_satis_oran),
          'eve_satis_acilis', e.alis_zaman + interval '72 hours',
          'bagis_kidem', least(5, floor(oyun.mz_deger(e.id) / 20000)))
        order by oyun.mz_deger(e.id) desc)
        from oyun.muzayede_eserler e join oyun.muzayede_katalog k on k.kod = e.katalog
       where e.sahip = p.id and e.durum in ('kasa','sergide','artirmada')), '[]'::jsonb),
    'seriler', coalesce((select jsonb_agg(jsonb_build_object('seri', s.seri, 'toplam', s.toplam, 'bende', s.bende, 'tam', s.bende = s.toplam) order by s.bende desc, s.seri)
        from (select k.seri, count(distinct k.kod) toplam,
                     count(distinct k.kod) filter (where exists (select 1 from oyun.muzayede_eserler e where e.katalog = k.kod and e.sahip = p.id and e.durum in ('kasa','sergide','artirmada'))) bende
                from oyun.muzayede_katalog k group by k.seri) s where s.bende > 0), '[]'::jsonb),
    'peylerim', coalesce((select jsonb_agg(oyun.mz_lot_ozet(l.id, p.id) order by l.bitis)
        from oyun.muzayede_lotlar l where l.durum = 'acik' and exists (select 1 from oyun.muzayede_peyler pp where pp.lot_id = l.id and pp.kim = p.id)), '[]'::jsonb),
    'satistakiler', coalesce((select jsonb_agg(oyun.mz_lot_ozet(l.id, p.id) order by l.bitis) from oyun.muzayede_lotlar l where l.durum = 'acik' and l.satici = p.id), '[]'::jsonb),
    'sergi_bugun', (select tutar from oyun.muzayede_sergi_odeme where user_id = p.id and gun = (oyun.simdi() at time zone 'Europe/Istanbul')::date),
    'sergi_tavan', a.sergi_tavan, 'komisyon', a.komisyon, 'bagis_kidem', v_bagis, 'bagis_kidem_tavan', 20,
    'toplam_deger', coalesce((select sum(oyun.mz_deger(e.id)) from oyun.muzayede_eserler e where e.sahip = p.id and e.durum in ('kasa','sergide','artirmada')), 0),
    'toplam_maliyet', coalesce((select sum(e.alis_bedeli) from oyun.muzayede_eserler e where e.sahip = p.id and e.durum in ('kasa','sergide','artirmada')), 0));
end $$;

-- Eserini açık artırmaya çıkar
create or replace function public.muzayede_lot_ac(p_eser bigint, p_baslangic numeric, p_saat integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); e oyun.muzayede_eserler; k oyun.muzayede_katalog;
  v_bas numeric := round(coalesce(p_baslangic, 0)); v_ucret numeric; v_id bigint;
begin
  if not oyun.uzaktan_modul_acik('muzayede') then raise exception 'Müzayede evi şu an geçici olarak kapalı.'; end if;
  if p_saat not in (6, 12, 24, 48) then raise exception 'Süre 6, 12, 24 ya da 48 saat olabilir.'; end if;
  select * into e from oyun.muzayede_eserler where id = p_eser for update;
  if e.id is null or e.sahip is distinct from p.id then raise exception 'Bu eser senin değil.'; end if;
  if e.durum not in ('kasa','sergide') then raise exception 'Bu eser şu an açık artırmaya çıkarılamaz.'; end if;
  if (select count(*) from oyun.muzayede_lotlar l where l.satici = p.id and l.durum = 'acik') >= 3 then
    raise exception 'Aynı anda en fazla 3 eserini açık artırmaya çıkarabilirsin.'; end if;
  if v_bas < 500 then raise exception 'Başlangıç fiyatı en az 500 ₺ olmalı.'; end if;
  if v_bas > oyun.mz_deger(e.id) * 5 then raise exception 'Başlangıç fiyatı tahmini değerin 5 katını geçemez.'; end if;
  select * into k from oyun.muzayede_katalog where kod = e.katalog;
  v_ucret := greatest(250, least(5000, round(v_bas * 0.01)));
  perform oyun.para_islem(p.id, -v_ucret, 'muzayede', format('Müzayede: “%s” için lot açma ücreti', k.ad), v_t);
  update oyun.ulke set hazine = hazine + v_ucret / oyun.pazar_tl_milyar() where id = 1;
  update oyun.muzayede_eserler set durum = 'artirmada', sergi_bas = null where id = e.id;
  insert into oyun.muzayede_lotlar(eser_id, satici, baslangic, bitis, ilk_bitis, ucret)
    values (e.id, p.id, v_bas, date_trunc('minute', v_t + make_interval(hours => p_saat)), date_trunc('minute', v_t + make_interval(hours => p_saat)), v_ucret)
    returning id into v_id;
  return public.muzayede_lot(v_id);
end $$;

-- Pey gelmemiş lotunu geri çek
create or replace function public.muzayede_lot_iptal(p_lot bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); l oyun.muzayede_lotlar;
begin
  select * into l from oyun.muzayede_lotlar where id = p_lot for update;
  if l.id is null or l.satici is distinct from p.id then raise exception 'Bu lot senin değil.'; end if;
  if l.durum <> 'acik' then raise exception 'Bu açık artırma zaten kapandı.'; end if;
  if l.pey_sayisi > 0 then raise exception 'Pey gelmiş bir açık artırma geri çekilemez.'; end if;
  update oyun.muzayede_lotlar set durum = 'iptal', kapanis = oyun.simdi() where id = l.id;
  update oyun.muzayede_eserler set durum = 'kasa' where id = l.eser_id and sahip = p.id;
  return jsonb_build_object('tamam', true);
end $$;

-- Özel müzede sergile / sergiden kaldır
create or replace function public.muzayede_sergi(p_eser bigint, p_ac boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); e oyun.muzayede_eserler;
begin
  select * into e from oyun.muzayede_eserler where id = p_eser for update;
  if e.id is null or e.sahip is distinct from p.id then raise exception 'Bu eser senin değil.'; end if;
  if p_ac then
    if e.durum <> 'kasa' then raise exception 'Yalnız kasandaki eserler sergilenebilir.'; end if;
    update oyun.muzayede_eserler set durum = 'sergide', sergi_bas = oyun.simdi() where id = e.id;
  else
    if e.durum <> 'sergide' then raise exception 'Bu eser sergide değil.'; end if;
    update oyun.muzayede_eserler set durum = 'kasa', sergi_bas = null where id = e.id;
  end if;
  return oyun.mz_eser_ozet(e.id, p.id);
end $$;

-- Müzayede evine hızlı satış (tahmini değerin %50'si, alımdan 72 saat sonra)
create or replace function public.muzayede_eve_sat(p_eser bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); e oyun.muzayede_eserler; k oyun.muzayede_katalog;
  a oyun.muzayede_ayar; v_bedel numeric; v_model numeric;
begin
  if not oyun.uzaktan_modul_acik('muzayede') then raise exception 'Müzayede evi şu an geçici olarak kapalı.'; end if;
  select * into a from oyun.muzayede_ayar where id = 1;
  select * into e from oyun.muzayede_eserler where id = p_eser for update;
  if e.id is null or e.sahip is distinct from p.id then raise exception 'Bu eser senin değil.'; end if;
  if e.durum not in ('kasa','sergide') then raise exception 'Bu eser şu an satılamaz.'; end if;
  if e.alis_zaman is not null and e.alis_zaman > v_t - interval '72 hours' then
    raise exception 'Müzayede evi bir eseri satın alındıktan 72 saat sonra geri alır (%).', oyun.ilan_tarih(e.alis_zaman + interval '72 hours'); end if;
  select * into k from oyun.muzayede_katalog where kod = e.katalog;
  v_bedel := oyun.mz_yuvarla(oyun.mz_deger(e.id) * a.eve_satis_oran);
  v_model := oyun.mz_model(e.id);
  perform oyun.para_islem(p.id, v_bedel, 'muzayede', format('Müzayede: “%s” müzayede evine satıldı', k.ad), v_t);
  update oyun.ulke set hazine = hazine - v_bedel / oyun.pazar_tl_milyar() where id = 1;
  update oyun.muzayede_eserler set sahip = null, durum = 'havuz', sergi_bas = null, alis_bedeli = null, alis_zaman = null where id = e.id;
  insert into oyun.muzayede_satislar(eser_id, kategori, satici, alici, fiyat, model_deger, tur, zaman)
    values (e.id, k.kategori, p.id, null, v_bedel, v_model, 'eve_satis', v_t);
  return jsonb_build_object('tamam', true, 'bedel', v_bedel);
end $$;

-- Devlet Müzesi'ne bağışla: eser kalıcı olarak müzeye geçer, kıdem puanı kazanılır
create or replace function public.muzayede_bagis(p_eser bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); e oyun.muzayede_eserler; k oyun.muzayede_katalog;
  v_onceki numeric; v_kidem numeric;
begin
  select * into e from oyun.muzayede_eserler where id = p_eser for update;
  if e.id is null or e.sahip is distinct from p.id then raise exception 'Bu eser senin değil.'; end if;
  if e.durum not in ('kasa','sergide') then raise exception 'Bu eser şu an bağışlanamaz.'; end if;
  if e.alis_zaman is not null and e.alis_zaman > v_t - interval '24 hours' then raise exception 'Yeni aldığın eseri en erken 24 saat sonra bağışlayabilirsin.'; end if;
  select * into k from oyun.muzayede_katalog where kod = e.katalog;
  select coalesce(sum(bagis_kidem), 0) into v_onceki from oyun.muzayede_eserler where bagisci = p.id;
  v_kidem := greatest(0, least(5, floor(oyun.mz_deger(e.id) / 20000), 20 - v_onceki));
  update oyun.muzayede_eserler set sahip = null, durum = 'muzede', sergi_bas = null, bagisci = p.id, bagis_zaman = v_t, bagis_kidem = v_kidem where id = e.id;
  if v_kidem > 0 then
    perform oyun.cuzdanim(p.id);
    update oyun.cuzdan set kidem = coalesce(kidem, 0) + v_kidem where user_id = p.id;
  end if;
  perform oyun.bildir(p.id, format('Müzayede: “%s” Devlet Müzesi''ne bağışlandı. Adın müzede bağışçı olarak yazılı%s.', k.ad,
    case when v_kidem > 0 then format('; +%s kıdem puanı kazandın', v_kidem) else '' end), v_t);
  return jsonb_build_object('tamam', true, 'kidem', v_kidem);
end $$;

-- Koleksiyoncular sıralaması ve Devlet Müzesi
create or replace function public.muzayede_siralama()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim();
begin
  return jsonb_build_object(
    'koleksiyoncular', coalesce((select jsonb_agg(x order by (x->>'deger')::numeric desc) from (
        select jsonb_build_object('kad', pr.kad, 'benim', pr.id = p.id, 'parti', (select jsonb_build_object('kisa', pa.kisa, 'renk', pa.renk) from oyun.partiler pa where pa.id = pr.parti_id),
               'eser', count(*), 'deger', sum(oyun.mz_deger(e.id)),
               'efsanevi', count(*) filter (where k.nadirlik = 'efsanevi'),
               'tam_set', (select count(distinct k2.seri) from oyun.muzayede_katalog k2 where oyun.mz_set_tam(pr.id, k2.seri))) x
          from oyun.muzayede_eserler e join oyun.muzayede_katalog k on k.kod = e.katalog join oyun.profiller pr on pr.id = e.sahip
         where e.durum in ('kasa','sergide','artirmada') and not pr.yasakli
         group by pr.id, pr.kad, pr.parti_id order by sum(oyun.mz_deger(e.id)) desc limit 20) t), '[]'::jsonb),
    'muze', coalesce((select jsonb_agg(oyun.mz_eser_ozet(e.id, p.id) order by e.bagis_zaman desc)
        from oyun.muzayede_eserler e where e.durum = 'muzede'), '[]'::jsonb),
    'rekorlar', coalesce((select jsonb_agg(x order by (x->>'fiyat')::numeric desc) from (
        select jsonb_build_object('eser', k.ad, 'nadirlik', k.nadirlik, 'motif', k.motif, 'renk', k.renk, 'fiyat', s.fiyat, 'alici', oyun.mz_kad(s.alici), 'zaman', s.zaman) x
          from oyun.muzayede_satislar s join oyun.muzayede_eserler e on e.id = s.eser_id join oyun.muzayede_katalog k on k.kod = e.katalog
         where s.tur = 'artirma' order by s.fiyat desc limit 10) t), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------------
-- F. ZAMANLAYICI VE YETKİLER
-- ---------------------------------------------------------------------
do $cron$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if exists (select 1 from cron.job where jobname = 'muzayede-bakim') then perform cron.unschedule('muzayede-bakim'); end if;
    perform cron.schedule('muzayede-bakim', '* * * * *', 'select oyun.muzayede_bakim()');
  end if;
end $cron$;

do $yetki$
declare f text;
begin
  foreach f in array array[
    'public.muzayede_salon()', 'public.muzayede_lot(bigint)', 'public.muzayede_pey(bigint,numeric)',
    'public.muzayede_koleksiyonum()', 'public.muzayede_lot_ac(bigint,numeric,integer)', 'public.muzayede_lot_iptal(bigint)',
    'public.muzayede_sergi(bigint,boolean)', 'public.muzayede_eve_sat(bigint)', 'public.muzayede_bagis(bigint)',
    'public.muzayede_siralama()']
  loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
  foreach f in array array[
    'oyun.mz_eser_bas(text)', 'oyun.mz_sistem_lot_ac(integer)', 'oyun.mz_lot_kapat(bigint)', 'oyun.mz_gunluk()', 'oyun.muzayede_bakim()']
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
end $yetki$;

-- Başlangıç: endeks geçmişi bugünle başlar (ilk günlük güncelleme yarın), salon 6 lotla açılır
update oyun.muzayede_ayar set son_gunluk = coalesce(son_gunluk, (now() at time zone 'Europe/Istanbul')::date), sergi_tavan = 2000 where id = 1;
insert into oyun.muzayede_endeks_gecmis(kategori, gun, endeks)
  select kod, (now() at time zone 'Europe/Istanbul')::date, endeks from oyun.muzayede_kategori on conflict do nothing;
select oyun.mz_sistem_lot_ac();
-- =====================================================================
--  141 · KÜRSÜ — oyunun sosyal medya platformu (26.10.2026)
--  Akış'ın üstüne kurulur; gönderiler, beğeni / beğenmeme, yanıtlar ve
--  #etiketler aynı tablolarda (oyun.akis*) kalır. Eklenenler:
--  · takip / takipçi (oyun.kursu_takip)
--  · yeniden paylaşım (oyun.kursu_yp) ve alıntı (oyun.akis.alinti_id)
--  · Kürsü profili: 160 karakterlik biyografi, kapak, sabitlenmiş gönderi
--  · "Sana özel" (etkileşim sıralı) ve "Takip" (zaman sıralı) akışları
--  · gündem: etiketler, en çok konuşulan kişiler, partiler, dernekler
--  · @anma bildirimi, Kürsü bildirimleri (beğeniler kimin verdiği
--    gösterilmeden toplu sayılır — Akış'ın gizlilik kuralı korunur)
--  Yalnız yeni tablo / sütun / fonksiyon ekler; iki kez çalıştırmak güvenlidir.
-- =====================================================================

-- ---------------------------------------------------------------------
-- A. TABLOLAR
-- ---------------------------------------------------------------------
alter table oyun.akis add column if not exists alinti_id bigint references oyun.akis(id) on delete set null;
create index if not exists akis_alinti_idx on oyun.akis(alinti_id) where alinti_id is not null;
create index if not exists akis_user_zaman_idx on oyun.akis(user_id, zaman desc);
create index if not exists akis_yanit_idx on oyun.akis(yanit_id) where yanit_id is not null;

create table if not exists oyun.kursu_takip (
  takipci uuid not null references oyun.profiller(id) on delete cascade,
  takip_edilen uuid not null references oyun.profiller(id) on delete cascade,
  zaman timestamptz not null default now(),
  primary key (takipci, takip_edilen),
  check (takipci <> takip_edilen)
);
create index if not exists kursu_takip_edilen_idx on oyun.kursu_takip(takip_edilen, zaman desc);

-- İlk takipte bir kez bildirim gitsin (takip et / bırak döngüsüyle bildirim yağdırılmasın)
create table if not exists oyun.kursu_takip_gecmis (
  takipci uuid not null references oyun.profiller(id) on delete cascade,
  takip_edilen uuid not null references oyun.profiller(id) on delete cascade,
  primary key (takipci, takip_edilen)
);

create table if not exists oyun.kursu_yp (
  akis_id bigint not null references oyun.akis(id) on delete cascade,
  user_id uuid not null references oyun.profiller(id) on delete cascade,
  zaman timestamptz not null default now(),
  primary key (akis_id, user_id)
);
create index if not exists kursu_yp_user_idx on oyun.kursu_yp(user_id, zaman desc);

create table if not exists oyun.kursu_profil (
  user_id uuid primary key references oyun.profiller(id) on delete cascade,
  bio text check (bio is null or char_length(bio) <= 160),
  kapak text,
  sabit_id bigint references oyun.akis(id) on delete set null,
  bildirim_okundu timestamptz,
  guncelleme timestamptz
);

alter table oyun.kursu_takip enable row level security;
alter table oyun.kursu_takip_gecmis enable row level security;
alter table oyun.kursu_yp enable row level security;
alter table oyun.kursu_profil enable row level security;

-- ---------------------------------------------------------------------
-- B. YARDIMCILAR
-- ---------------------------------------------------------------------
create or replace function oyun.kursu_engelli(a uuid, b uuid) returns boolean
language sql stable set search_path = '' as $$
  select exists (select 1 from oyun.engellemeler g where (g.engelleyen = a and g.engellenen = b) or (g.engelleyen = b and g.engellenen = a))
$$;

create or replace function oyun.kursu_alinti_json(p_id bigint) returns jsonb
language sql stable set search_path = '' as $$
  select jsonb_build_object('id', a.id, 'kad', pr.kad, 'unvan', oyun.unvan(a.user_id), 'parti', oyun.parti_json(a.parti_id),
                            'metin', a.metin, 'zaman', a.zaman)
    from oyun.akis a join oyun.profiller pr on pr.id = a.user_id
   where a.id = p_id and not a.gizli
$$;

-- Akış gönderisi + Kürsü alanları
create or replace function oyun.kursu_json(a oyun.akis, ben uuid) returns jsonb
language sql stable set search_path = '' as $$
  select oyun.akis_json(a, ben) || jsonb_build_object(
    'yp', (select count(*) from oyun.kursu_yp y where y.akis_id = a.id),
    'ypledim', exists (select 1 from oyun.kursu_yp y where y.akis_id = a.id and y.user_id = ben),
    'alinti_sayi', (select count(*) from oyun.akis q where q.alinti_id = a.id and not q.gizli),
    'alinti', case when a.alinti_id is not null then oyun.kursu_alinti_json(a.alinti_id) end,
    'yanit_kad', case when a.yanit_id is not null then (select pr.kad from oyun.akis u join oyun.profiller pr on pr.id = u.user_id where u.id = a.yanit_id) end,
    'takip_ediyorum', exists (select 1 from oyun.kursu_takip t where t.takipci = ben and t.takip_edilen = a.user_id))
$$;

create or replace function oyun.kursu_bio(u uuid) returns text
language sql stable set search_path = '' as $$
  select coalesce((select nullif(btrim(bio), '') from oyun.kursu_profil where user_id = u),
                  (select left(regexp_replace(btrim(k.biyografi), '\s+', ' ', 'g'), 160) from oyun.oyuncu_kimlik k where k.user_id = u))
$$;

create or replace function oyun.kursu_kisi_json(u uuid, ben uuid) returns jsonb
language sql stable set search_path = '' as $$
  select jsonb_build_object('kad', p.kad, 'unvan', oyun.unvan(p.id), 'parti', oyun.parti_json(p.parti_id),
           'bio', oyun.kursu_bio(p.id),
           'takipci', (select count(*) from oyun.kursu_takip t where t.takip_edilen = p.id),
           'takip_ediyorum', exists (select 1 from oyun.kursu_takip t where t.takipci = ben and t.takip_edilen = p.id),
           'beni_takip_ediyor', exists (select 1 from oyun.kursu_takip t where t.takipci = p.id and t.takip_edilen = ben),
           'benim', p.id = ben)
    from oyun.profiller p where p.id = u
$$;

-- @anma bildirimi (gönderi başına en çok 3 kişi)
create or replace function oyun.tg_kursu_anma() returns trigger
language plpgsql security definer set search_path = '' as $$
declare r record; v_kad text; v_u uuid; n integer := 0;
begin
  if new.gizli then return new; end if;
  select kad into v_kad from oyun.profiller where id = new.user_id;
  for r in select distinct lower(m[1]) k from regexp_matches(new.metin, '@([[:alnum:]_.]{2,30})', 'g') m loop
    exit when n >= 3;
    v_u := null;
    select id into v_u from oyun.profiller where lower(kad) = r.k and not yasakli;
    if v_u is not null and v_u <> new.user_id and not oyun.kursu_engelli(v_u, new.user_id)
       and not exists (select 1 from oyun.akis y where y.id = new.yanit_id and y.user_id = v_u) then
      perform oyun.bildir(v_u, format('Kürsü: %s senden bahsetti: %s', v_kad, left(new.metin, 90)), new.zaman);
      n := n + 1;
    end if;
  end loop;
  return new;
end $$;
create or replace trigger kursu_anma after insert on oyun.akis for each row execute function oyun.tg_kursu_anma();

-- ---------------------------------------------------------------------
-- C. AKIŞLAR
-- ---------------------------------------------------------------------
-- p_sekme: 'sana' (etkileşim + tazelik sıralı; p_imlec = atlanacak adet),
--          'takip' / 'il' / 'parti' / 'herkes' (zaman sıralı; p_imlec = son öğenin zamanı)
create or replace function public.kursu_akis(p_sekme text default 'sana', p_imlec text default null, p_limit integer default 20)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_lim integer := least(greatest(coalesce(p_limit, 20), 1), 40);
  v_t timestamptz := oyun.simdi(); v_once timestamptz; v_atla integer := 0; v_liste jsonb;
begin
  if p_sekme not in ('sana','takip','il','parti','herkes') then raise exception 'Geçersiz akış.'; end if;
  if p_sekme = 'sana' then
    v_atla := greatest(0, least(coalesce(nullif(p_imlec, '')::integer, 0), 400));
    select coalesce(jsonb_agg(jsonb_build_object('sira', x.skor, 'yp', null, 'g', oyun.kursu_json(a, p.id)) order by x.skor desc, a.id desc), '[]'::jsonb)
      into v_liste
      from (select a.id, ((
                (select count(*) from oyun.akis_begeni b where b.akis_id = a.id) * 2
              + (select count(*) from oyun.akis y where y.yanit_id = a.id and not y.gizli) * 3
              + (select count(*) from oyun.kursu_yp y where y.akis_id = a.id) * 4
              + (select count(*) from oyun.akis q where q.alinti_id = a.id and not q.gizli) * 3
              - (select count(*) from oyun.akis_begenmeme b where b.akis_id = a.id)
              + case when exists (select 1 from oyun.kursu_takip t where t.takipci = p.id and t.takip_edilen = a.user_id) then 6 else 0 end
              + case when p.parti_id is not null and a.parti_id = p.parti_id then 2 else 0 end
              + case when a.il_id = p.il_id then 1 else 0 end + 1)::numeric
              / power(extract(epoch from (v_t - a.zaman)) / 3600 + 2, 1.35)) as skor
              from oyun.akis a
             where not a.gizli and a.yanit_id is null and a.zaman > v_t - interval '7 days'
               and not oyun.kursu_engelli(p.id, a.user_id)
             order by 2 desc, a.id desc offset v_atla limit v_lim) x
      join oyun.akis a on a.id = x.id;
    return jsonb_build_object('liste', v_liste, 'imlec', case when jsonb_array_length(v_liste) = v_lim then (v_atla + v_lim)::text end);
  end if;
  v_once := coalesce(nullif(p_imlec, '')::timestamptz, 'infinity'::timestamptz);
  with u as (
    select a.id akis_id, a.zaman sira, null::text yp_kad from oyun.akis a
     where not a.gizli and a.yanit_id is null and a.zaman < v_once
       and (p_sekme = 'herkes'
         or (p_sekme = 'il' and a.il_id = p.il_id)
         or (p_sekme = 'parti' and p.parti_id is not null and a.parti_id = p.parti_id)
         or (p_sekme = 'takip' and (a.user_id = p.id or exists (select 1 from oyun.kursu_takip t where t.takipci = p.id and t.takip_edilen = a.user_id))))
    union all
    select y.akis_id, y.zaman, pr.kad from oyun.kursu_yp y join oyun.profiller pr on pr.id = y.user_id
     where p_sekme = 'takip' and y.zaman < v_once
       and (y.user_id = p.id or exists (select 1 from oyun.kursu_takip t where t.takipci = p.id and t.takip_edilen = y.user_id))
  ), d as (
    select distinct on (akis_id) akis_id, sira, yp_kad from u order by akis_id, sira desc
  ), s as (
    select d.* from d join oyun.akis a on a.id = d.akis_id and not a.gizli
     where not oyun.kursu_engelli(p.id, a.user_id) order by d.sira desc limit v_lim
  )
  select coalesce(jsonb_agg(jsonb_build_object('sira', s.sira, 'yp', s.yp_kad, 'g', oyun.kursu_json(a, p.id)) order by s.sira desc), '[]'::jsonb)
    into v_liste from s join oyun.akis a on a.id = s.akis_id;
  return jsonb_build_object('liste', v_liste,
    'imlec', case when jsonb_array_length(v_liste) = v_lim then (v_liste -> (v_lim - 1) ->> 'sira') end);
end $$;

-- Bir gönderi ve konuşması
create or replace function public.kursu_gonderi(p_id bigint)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); a oyun.akis; ana oyun.akis;
begin
  select * into a from oyun.akis where id = p_id and not gizli;
  if a.id is null then raise exception 'Gönderi bulunamadı ya da silinmiş.'; end if;
  ana := a;
  if a.yanit_id is not null then select * into ana from oyun.akis where id = a.yanit_id and not gizli; end if;
  if ana.id is null then ana := a; end if;
  if oyun.kursu_engelli(p.id, ana.user_id) then raise exception 'Bu kullanıcıyla aranızda engelleme var.'; end if;
  return jsonb_build_object('ana', oyun.kursu_json(ana, p.id), 'odak', a.id,
    'yanitlar', coalesce((select jsonb_agg(oyun.kursu_json(y, p.id) order by y.id) from oyun.akis y
                           where y.yanit_id = ana.id and not y.gizli and not oyun.kursu_engelli(p.id, y.user_id)), '[]'::jsonb),
    'alintilar', coalesce((select jsonb_agg(oyun.kursu_json(q, p.id) order by q.id desc) from (select * from oyun.akis q2
                           where q2.alinti_id = ana.id and not q2.gizli and not oyun.kursu_engelli(p.id, q2.user_id) order by q2.id desc limit 10) q), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------------
-- D. ETKİLEŞİM
-- ---------------------------------------------------------------------
create or replace function public.kursu_yp(p_id bigint, p_ac boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); a oyun.akis; v_t timestamptz := oyun.simdi();
begin
  select * into a from oyun.akis where id = p_id and not gizli;
  if a.id is null then raise exception 'Gönderi bulunamadı.'; end if;
  if oyun.kursu_engelli(p.id, a.user_id) then raise exception 'Bu kullanıcıyla aranızda engelleme var.'; end if;
  if p_ac then
    if (select count(*) from oyun.kursu_yp where user_id = p.id and zaman > v_t - interval '1 hour') >= 60 then
      raise exception 'Bir saatte çok fazla yeniden paylaşım yaptın, biraz bekle.'; end if;
    insert into oyun.kursu_yp(akis_id, user_id, zaman) values (a.id, p.id, v_t) on conflict do nothing;
  else
    delete from oyun.kursu_yp where akis_id = a.id and user_id = p.id;
  end if;
  return jsonb_build_object('yp', (select count(*) from oyun.kursu_yp where akis_id = a.id),
                            'ypledim', exists (select 1 from oyun.kursu_yp where akis_id = a.id and user_id = p.id));
end $$;

create or replace function public.kursu_alinti(p_id bigint, p_metin text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); a oyun.akis; r jsonb; v_yeni bigint;
begin
  select * into a from oyun.akis where id = p_id and not gizli;
  if a.id is null then raise exception 'Gönderi bulunamadı.'; end if;
  if oyun.kursu_engelli(p.id, a.user_id) then raise exception 'Bu kullanıcıyla aranızda engelleme var.'; end if;
  r := public.akis_yaz(p_metin);
  v_yeni := (r->>'id')::bigint;
  update oyun.akis set alinti_id = a.id where id = v_yeni;
  if a.user_id <> p.id then
    perform oyun.bildir(a.user_id, format('Kürsü: %s gönderini alıntıladı: %s', p.kad, left(btrim(p_metin), 80)));
  end if;
  return jsonb_build_object('tamam', true, 'id', v_yeni);
end $$;

create or replace function public.kursu_takip_et(p_kad text, p_takip boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_u uuid; v_t timestamptz := oyun.simdi();
begin
  select id into v_u from oyun.profiller where lower(kad) = lower(btrim(p_kad)) and not yasakli;
  if v_u is null then raise exception 'Kullanıcı bulunamadı.'; end if;
  if v_u = p.id then raise exception 'Kendini takip edemezsin.'; end if;
  if p_takip then
    if oyun.kursu_engelli(p.id, v_u) then raise exception 'Bu kullanıcıyla aranızda engelleme var.'; end if;
    if (select count(*) from oyun.kursu_takip where takipci = p.id and zaman > v_t - interval '1 day') >= 150 then
      raise exception 'Bugün çok fazla kişiyi takip ettin; yarın devam edebilirsin.'; end if;
    insert into oyun.kursu_takip(takipci, takip_edilen, zaman) values (p.id, v_u, v_t) on conflict do nothing;
    insert into oyun.kursu_takip_gecmis(takipci, takip_edilen) values (p.id, v_u) on conflict do nothing;
    if found then perform oyun.bildir(v_u, format('Kürsü: %s seni takip etmeye başladı.', p.kad), v_t); end if;
  else
    delete from oyun.kursu_takip where takipci = p.id and takip_edilen = v_u;
  end if;
  return oyun.kursu_kisi_json(v_u, p.id);
end $$;

create or replace function public.kursu_profil_guncelle(p_bio text, p_kapak text, p_sabit bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); b text := nullif(btrim(coalesce(p_bio, '')), '');
begin
  if b is not null and char_length(b) > 160 then raise exception 'Kürsü biyografisi en fazla 160 karakter olabilir.'; end if;
  if b is not null and oyun.kufurlu(b) then raise exception 'Biyografinde uygunsuz bir ifade var. Hakaret ve küfür yasaktır.'; end if;
  if b is not null and b ~* '(https?://|www\.|\.com\b|t\.me/)' then raise exception 'Biyografide bağlantı kullanılamaz.'; end if;
  if p_kapak is not null and p_kapak not in ('mor','gece','gun','deniz','orman','gul','altin','kizil','meclis','yildiz') then raise exception 'Geçersiz kapak.'; end if;
  if p_sabit is not null and not exists (select 1 from oyun.akis where id = p_sabit and user_id = p.id and yanit_id is null and not gizli) then
    raise exception 'Yalnız kendi gönderini sabitleyebilirsin.'; end if;
  insert into oyun.kursu_profil(user_id, bio, kapak, sabit_id, guncelleme) values (p.id, b, p_kapak, p_sabit, oyun.simdi())
  on conflict (user_id) do update set bio = excluded.bio, kapak = excluded.kapak, sabit_id = excluded.sabit_id, guncelleme = excluded.guncelleme;
  return jsonb_build_object('tamam', true);
end $$;

create or replace function public.kursu_sabitle(p_id bigint)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim();
begin
  if p_id is not null and not exists (select 1 from oyun.akis where id = p_id and user_id = p.id and yanit_id is null and not gizli) then
    raise exception 'Yalnız kendi gönderini sabitleyebilirsin.'; end if;
  insert into oyun.kursu_profil(user_id, sabit_id, guncelleme) values (p.id, p_id, oyun.simdi())
  on conflict (user_id) do update set sabit_id = excluded.sabit_id, guncelleme = excluded.guncelleme;
  return jsonb_build_object('tamam', true, 'sabit_id', p_id);
end $$;

-- ---------------------------------------------------------------------
-- E. PROFİL, KİŞİLER
-- ---------------------------------------------------------------------
-- p_sekme: 'gonderi' (gönderiler + yeniden paylaşımlar), 'yanit', 'one_cikan' (en çok etkileşim alanlar)
create or replace function public.kursu_profil(p_kad text, p_sekme text default 'gonderi', p_imlec text default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); h oyun.profiller; kp oyun.kursu_profil; v_once timestamptz; v_liste jsonb; v_lim integer := 20;
begin
  select * into h from oyun.profiller where lower(kad) = lower(btrim(p_kad));
  if h.id is null or (h.yasakli and h.id <> p.id) then raise exception 'Kullanıcı bulunamadı.'; end if;
  if p_sekme not in ('gonderi','yanit','one_cikan') then raise exception 'Geçersiz sekme.'; end if;
  select * into kp from oyun.kursu_profil where user_id = h.id;
  v_once := coalesce(nullif(p_imlec, '')::timestamptz, 'infinity'::timestamptz);
  if oyun.kursu_engelli(p.id, h.id) then
    v_liste := '[]'::jsonb;
  elsif p_sekme = 'gonderi' then
    with u as (
      select a.id akis_id, a.zaman sira, null::text yp_kad from oyun.akis a where a.user_id = h.id and not a.gizli and a.yanit_id is null and a.zaman < v_once
      union all
      select y.akis_id, y.zaman, h.kad from oyun.kursu_yp y join oyun.akis a on a.id = y.akis_id and not a.gizli where y.user_id = h.id and y.zaman < v_once
    ), s as (select distinct on (akis_id) akis_id, sira, yp_kad from u order by akis_id, sira desc),
    l as (select * from s order by sira desc limit v_lim)
    select coalesce(jsonb_agg(jsonb_build_object('sira', l.sira, 'yp', l.yp_kad, 'g', oyun.kursu_json(a, p.id)) order by l.sira desc), '[]'::jsonb)
      into v_liste from l join oyun.akis a on a.id = l.akis_id;
  elsif p_sekme = 'yanit' then
    select coalesce(jsonb_agg(jsonb_build_object('sira', a.zaman, 'yp', null, 'g', oyun.kursu_json(a, p.id)) order by a.zaman desc), '[]'::jsonb)
      into v_liste from (select * from oyun.akis a2 where a2.user_id = h.id and not a2.gizli and a2.yanit_id is not null and a2.zaman < v_once order by a2.zaman desc limit v_lim) a;
  else
    select coalesce(jsonb_agg(jsonb_build_object('sira', x.puan, 'yp', null, 'g', oyun.kursu_json(a, p.id)) order by x.puan desc), '[]'::jsonb)
      into v_liste from (select a2.id, (select count(*) from oyun.akis_begeni b where b.akis_id = a2.id) * 2
                                   + (select count(*) from oyun.kursu_yp y where y.akis_id = a2.id) * 4
                                   + (select count(*) from oyun.akis r where r.yanit_id = a2.id and not r.gizli) * 3 puan
                           from oyun.akis a2 where a2.user_id = h.id and not a2.gizli and a2.yanit_id is null
                          order by 2 desc, a2.id desc limit 10) x join oyun.akis a on a.id = x.id;
    v_once := null;
  end if;
  return jsonb_build_object(
    'kisi', oyun.kursu_kisi_json(h.id, p.id) || jsonb_build_object(
       'il', (select ad from oyun.iller where id = h.il_id), 'katilim', h.olusturma, 'kapak', coalesce(kp.kapak, 'mor'),
       'bio_kendi', kp.bio,
       'takip', (select count(*) from oyun.kursu_takip t where t.takipci = h.id),
       'gonderi', (select count(*) from oyun.akis a where a.user_id = h.id and not a.gizli),
       'begeni_alinan', (select count(*) from oyun.akis_begeni b join oyun.akis a on a.id = b.akis_id where a.user_id = h.id),
       'engelli', oyun.kursu_engelli(p.id, h.id),
       'ortak', (select count(*) from oyun.kursu_takip t1 join oyun.kursu_takip t2 on t2.takip_edilen = t1.takip_edilen
                  where t1.takipci = p.id and t2.takipci = h.id)),
    'sabit', case when kp.sabit_id is not null and p_sekme = 'gonderi' and p_imlec is null then
               (select oyun.kursu_json(a, p.id) from oyun.akis a where a.id = kp.sabit_id and not a.gizli) end,
    'liste', v_liste,
    'imlec', case when p_sekme <> 'one_cikan' and jsonb_array_length(v_liste) = v_lim then (v_liste -> (v_lim - 1) ->> 'sira') end);
end $$;

create or replace function public.kursu_takip_listesi(p_kad text, p_tur text default 'takipci')
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_u uuid;
begin
  select id into v_u from oyun.profiller where lower(kad) = lower(btrim(p_kad));
  if v_u is null then raise exception 'Kullanıcı bulunamadı.'; end if;
  if p_tur = 'takipci' then
    return coalesce((select jsonb_agg(oyun.kursu_kisi_json(t.takipci, p.id) order by t.zaman desc) from oyun.kursu_takip t
                      join oyun.profiller x on x.id = t.takipci and not x.yasakli where t.takip_edilen = v_u), '[]'::jsonb);
  end if;
  return coalesce((select jsonb_agg(oyun.kursu_kisi_json(t.takip_edilen, p.id) order by t.zaman desc) from oyun.kursu_takip t
                    join oyun.profiller x on x.id = t.takip_edilen and not x.yasakli where t.takipci = v_u), '[]'::jsonb);
end $$;

-- ---------------------------------------------------------------------
-- F. GÜNDEM, ARAMA, BİLDİRİMLER
-- ---------------------------------------------------------------------
create or replace function public.kursu_gundem()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); v_bas timestamptz; v_saat integer := 48;
  v_et jsonb; v_kisi jsonb; v_parti jsonb; v_dernek jsonb;
begin
  if (select count(*) from oyun.akis where zaman > v_t - interval '48 hours' and not gizli) < 15 then v_saat := 168; end if;
  v_bas := v_t - make_interval(hours => v_saat);
  -- 1) Etiketler: en çok gönderi atılandan en aza
  select coalesce(jsonb_agg(x order by (x->>'sayi')::int desc, (x->>'kisi')::int desc), '[]'::jsonb) into v_et from (
    select jsonb_build_object('tur', 'etiket', 'ad', '#' || e.etiket, 'anahtar', e.etiket, 'sayi', count(*), 'kisi', count(distinct e.user_id)) x
      from oyun.akis_etiket e join oyun.akis a on a.id = e.akis_id and not a.gizli
     where e.zaman > v_bas group by e.etiket order by count(*) desc, count(distinct e.user_id) desc limit 20) t;
  -- 2) En çok konuşulan kişiler: @anma ×3 + aldığı yanıt ×2 + yeniden paylaşım ×2 + beğeni
  select coalesce(jsonb_agg(x order by (x->>'puan')::numeric desc), '[]'::jsonb) into v_kisi from (
    select jsonb_build_object('tur', 'kisi', 'ad', pr.kad, 'anahtar', pr.kad, 'unvan', oyun.unvan(pr.id), 'parti', oyun.parti_json(pr.parti_id),
             'sayi', z.anma + z.yanit, 'anma', z.anma, 'puan', z.anma * 3 + z.yanit * 2 + z.yp * 2 + z.begeni,
             'takip_ediyorum', exists (select 1 from oyun.kursu_takip t where t.takipci = p.id and t.takip_edilen = pr.id)) x
      from (select u.id,
                   (select count(*) from oyun.akis a where a.zaman > v_bas and not a.gizli and a.user_id <> u.id and a.metin ~* ('@' || regexp_replace(u.kad, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || '($|[^[:alnum:]_])')) anma,
                   (select count(*) from oyun.akis r join oyun.akis a on a.id = r.yanit_id where a.user_id = u.id and r.user_id <> u.id and r.zaman > v_bas and not r.gizli) yanit,
                   (select count(*) from oyun.kursu_yp y join oyun.akis a on a.id = y.akis_id where a.user_id = u.id and y.user_id <> u.id and y.zaman > v_bas) yp,
                   (select count(*) from oyun.akis_begeni b join oyun.akis a on a.id = b.akis_id where a.user_id = u.id and b.zaman > v_bas) begeni
              from oyun.profiller u
             where not u.yasakli and exists (select 1 from oyun.akis a where a.user_id = u.id and a.zaman > v_t - interval '30 days')) z
      join oyun.profiller pr on pr.id = z.id
     where z.anma * 3 + z.yanit * 2 + z.yp * 2 + z.begeni > 0
     order by z.anma * 3 + z.yanit * 2 + z.yp * 2 + z.begeni desc limit 10) t;
  -- 3) Partiler: adı ya da kısaltması geçen gönderi sayısı
  select coalesce(jsonb_agg(x order by (x->>'sayi')::int desc), '[]'::jsonb) into v_parti from (
    select jsonb_build_object('tur', 'parti', 'ad', pa.ad, 'anahtar', pa.id, 'parti', oyun.parti_json(pa.id), 'sayi', c.n) x
      from oyun.partiler pa
      cross join lateral (select count(*) n from oyun.akis a where a.zaman > v_bas and not a.gizli
                            and (lower(a.metin) like '%' || lower(pa.ad) || '%'
                              or (char_length(pa.kisa) >= 2 and a.metin ~ ('(^|[^[:alnum:]])' || regexp_replace(pa.kisa, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || '($|[^[:alnum:]])')))) c
     where not pa.kapali and c.n > 0 order by c.n desc limit 8) t;
  -- 4) Dernekler
  select coalesce(jsonb_agg(x order by (x->>'sayi')::int desc), '[]'::jsonb) into v_dernek from (
    select jsonb_build_object('tur', 'dernek', 'ad', d.ad, 'anahtar', d.id, 'sayi', c.n) x
      from oyun.dernekler d
      cross join lateral (select count(*) n from oyun.akis a where a.zaman > v_bas and not a.gizli and lower(a.metin) like '%' || lower(d.ad) || '%') c
     where not coalesce(d.kapali, false) and c.n > 0 order by c.n desc limit 8) t;
  return jsonb_build_object('saat', v_saat, 'etiketler', v_et, 'kisiler', v_kisi, 'partiler', v_parti, 'dernekler', v_dernek,
    'oneriler', coalesce((select jsonb_agg(oyun.kursu_kisi_json(x.id, p.id) order by x.takipci desc, x.son desc) from (
        select u.id, (select count(*) from oyun.kursu_takip t where t.takip_edilen = u.id) takipci,
               (select max(a.zaman) from oyun.akis a where a.user_id = u.id) son
          from oyun.profiller u
         where not u.yasakli and u.id <> p.id
           and not exists (select 1 from oyun.kursu_takip t where t.takipci = p.id and t.takip_edilen = u.id)
           and not oyun.kursu_engelli(p.id, u.id)
           and exists (select 1 from oyun.akis a where a.user_id = u.id and a.zaman > v_t - interval '7 days')
         order by 2 desc, 3 desc nulls last limit 6) x), '[]'::jsonb));
end $$;

create or replace function public.kursu_ara(p_q text)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); q text := btrim(coalesce(p_q, '')); v_q text;
begin
  if char_length(q) < 2 then return jsonb_build_object('kisiler', '[]'::jsonb, 'etiketler', '[]'::jsonb, 'gonderiler', '[]'::jsonb); end if;
  v_q := replace(replace(replace(lower(regexp_replace(q, '^[#@]', '')), '\', '\\'), '%', '\%'), '_', '\_');
  return jsonb_build_object(
    'kisiler', coalesce((select jsonb_agg(oyun.kursu_kisi_json(u.id, p.id) order by (lower(u.kad) = v_q) desc, char_length(u.kad))
                           from (select * from oyun.profiller u2 where not u2.yasakli and lower(u2.kad) like '%' || v_q || '%' order by char_length(u2.kad) limit 8) u), '[]'::jsonb),
    'etiketler', coalesce((select jsonb_agg(jsonb_build_object('ad', '#' || x.etiket, 'anahtar', x.etiket, 'sayi', x.n) order by x.n desc)
                           from (select e.etiket, count(*) n from oyun.akis_etiket e where e.etiket like v_q || '%' group by e.etiket order by count(*) desc limit 6) x), '[]'::jsonb),
    'gonderiler', coalesce((select jsonb_agg(oyun.kursu_json(a, p.id) order by a.id desc) from (
        select * from oyun.akis a2 where not a2.gizli and a2.zaman > oyun.simdi() - interval '60 days' and lower(a2.metin) like '%' || v_q || '%'
           and not oyun.kursu_engelli(p.id, a2.user_id) order by a2.id desc limit 20) a), '[]'::jsonb));
end $$;

-- Etikete göre gönderiler (en yeniden eskiye)
create or replace function public.kursu_etiket(p_etiket text, p_imlec text default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); et text := lower(regexp_replace(btrim(coalesce(p_etiket, '')), '^#', '')); v_once bigint; v_liste jsonb;
begin
  v_once := coalesce(nullif(p_imlec, '')::bigint, 9223372036854775807);
  select coalesce(jsonb_agg(jsonb_build_object('sira', a.id, 'yp', null, 'g', oyun.kursu_json(a, p.id)) order by a.id desc), '[]'::jsonb) into v_liste
    from (select * from oyun.akis a2 where not a2.gizli and a2.id < v_once
            and exists (select 1 from oyun.akis_etiket e where e.akis_id = a2.id and e.etiket = et)
            and not oyun.kursu_engelli(p.id, a2.user_id) order by a2.id desc limit 20) a;
  return jsonb_build_object('etiket', et, 'liste', v_liste,
    'sayi', (select count(*) from oyun.akis_etiket e join oyun.akis a on a.id = e.akis_id and not a.gizli where e.etiket = et),
    'imlec', case when jsonb_array_length(v_liste) = 20 then (v_liste -> 19 ->> 'sira') end);
end $$;

-- Kürsü bildirimleri (son 7 gün). Beğeniler kimin verdiği gösterilmeden toplu sayılır.
create or replace function public.kursu_bildirimler(p_okundu boolean default false)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_t timestamptz := oyun.simdi(); v_bas timestamptz := oyun.simdi() - interval '7 days';
  v_okundu timestamptz; v_liste jsonb; v_kadre text;
begin
  select bildirim_okundu into v_okundu from oyun.kursu_profil where user_id = p.id;
  v_kadre := '@' || regexp_replace(p.kad, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || '($|[^[:alnum:]_])';
  select coalesce(jsonb_agg(x order by (x->>'zaman') desc), '[]'::jsonb) into v_liste from (
    select * from (
      select jsonb_build_object('tur', 'takip', 'kad', pr.kad, 'zaman', t.zaman, 'kisi', oyun.kursu_kisi_json(pr.id, p.id)) x, t.zaman z
        from oyun.kursu_takip t join oyun.profiller pr on pr.id = t.takipci where t.takip_edilen = p.id and t.zaman > v_bas
      union all
      select jsonb_build_object('tur', 'yp', 'kad', pr.kad, 'zaman', y.zaman, 'g', oyun.kursu_alinti_json(a.id)), y.zaman
        from oyun.kursu_yp y join oyun.akis a on a.id = y.akis_id and a.user_id = p.id join oyun.profiller pr on pr.id = y.user_id
       where y.user_id <> p.id and y.zaman > v_bas
      union all
      select jsonb_build_object('tur', 'yanit', 'kad', pr.kad, 'zaman', r.zaman, 'g', oyun.kursu_json(r, p.id)), r.zaman
        from oyun.akis r join oyun.akis a on a.id = r.yanit_id and a.user_id = p.id join oyun.profiller pr on pr.id = r.user_id
       where r.user_id <> p.id and not r.gizli and r.zaman > v_bas and not oyun.kursu_engelli(p.id, r.user_id)
      union all
      select jsonb_build_object('tur', 'alinti', 'kad', pr.kad, 'zaman', q.zaman, 'g', oyun.kursu_json(q, p.id)), q.zaman
        from oyun.akis q join oyun.akis a on a.id = q.alinti_id and a.user_id = p.id join oyun.profiller pr on pr.id = q.user_id
       where q.user_id <> p.id and not q.gizli and q.zaman > v_bas
      union all
      select jsonb_build_object('tur', 'anma', 'kad', pr.kad, 'zaman', m.zaman, 'g', oyun.kursu_json(m, p.id)), m.zaman
        from oyun.akis m join oyun.profiller pr on pr.id = m.user_id
       where m.user_id <> p.id and not m.gizli and m.zaman > v_bas and m.metin ~* v_kadre and not oyun.kursu_engelli(p.id, m.user_id)
      union all
      select jsonb_build_object('tur', 'begeni', 'sayi', count(*), 'zaman', max(b.zaman), 'g', oyun.kursu_alinti_json(a.id)), max(b.zaman)
        from oyun.akis_begeni b join oyun.akis a on a.id = b.akis_id and a.user_id = p.id
       where b.user_id <> p.id and b.zaman > v_bas group by a.id
    ) u order by z desc limit 60) t;
  if p_okundu then
    insert into oyun.kursu_profil(user_id, bildirim_okundu) values (p.id, v_t)
    on conflict (user_id) do update set bildirim_okundu = excluded.bildirim_okundu;
  end if;
  return jsonb_build_object('liste', v_liste, 'okundu', v_okundu,
    'yeni', (select count(*) from jsonb_array_elements(v_liste) e where (e->>'zaman')::timestamptz > coalesce(v_okundu, '-infinity'::timestamptz)));
end $$;

-- Kürsü özeti (rozet ve kendi profil bilgisi için hafif çağrı)
create or replace function public.kursu_ben()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare p oyun.profiller := oyun.profilim(); v_okundu timestamptz;
begin
  select bildirim_okundu into v_okundu from oyun.kursu_profil where user_id = p.id;
  return oyun.kursu_kisi_json(p.id, p.id) || jsonb_build_object(
    'takip', (select count(*) from oyun.kursu_takip t where t.takipci = p.id),
    'yeni', (select count(*) from oyun.kursu_takip t where t.takip_edilen = p.id and t.zaman > coalesce(v_okundu, oyun.simdi() - interval '7 days'))
          + (select count(*) from oyun.akis r join oyun.akis a on a.id = r.yanit_id and a.user_id = p.id where r.user_id <> p.id and not r.gizli and r.zaman > coalesce(v_okundu, oyun.simdi() - interval '7 days'))
          + (select count(*) from oyun.kursu_yp y join oyun.akis a on a.id = y.akis_id and a.user_id = p.id where y.user_id <> p.id and y.zaman > coalesce(v_okundu, oyun.simdi() - interval '7 days')));
end $$;

-- ---------------------------------------------------------------------
-- G. YETKİLER
-- ---------------------------------------------------------------------
do $yetki$
declare f text;
begin
  foreach f in array array[
    'public.kursu_akis(text,text,integer)', 'public.kursu_gonderi(bigint)', 'public.kursu_yp(bigint,boolean)',
    'public.kursu_alinti(bigint,text)', 'public.kursu_takip_et(text,boolean)', 'public.kursu_profil_guncelle(text,text,bigint)',
    'public.kursu_sabitle(bigint)', 'public.kursu_profil(text,text,text)', 'public.kursu_takip_listesi(text,text)',
    'public.kursu_gundem()', 'public.kursu_ara(text)', 'public.kursu_etiket(text,text)', 'public.kursu_bildirimler(boolean)',
    'public.kursu_ben()']
  loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
  foreach f in array array['oyun.tg_kursu_anma()'] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
end $yetki$;
-- =====================================================================
--  KALICILIK (son): bütünlük kontrolü, silme koruması, sürüm bilgisi, sahibin sıfırlama/geri yükleme araçları
-- =====================================================================
alter table oyun.ayarlar add column if not exists son_uygulama text not null default '0';
alter table oyun.ayarlar add column if not exists min_uygulama text not null default '0';

-- TRUNCATE koruması (tablo bazında): oyun tabloları yalnızca sahibinin sıfırlama/geri yükleme işlemiyle boşaltılabilir
create or replace function oyun.bosaltma_korumasi() returns trigger language plpgsql as $$
begin
  if coalesce(current_setting('oyun.sifirlama', true), '') <> 'evet' then
    raise exception 'Oyun verileri korunuyor: % tablosu boşaltılamaz. Oyunu sıfırlamak için: select oyun.oyunu_sifirla(''OYUNU SIFIRLA'');', tg_table_name;
  end if;
  return null;
end $$;

-- DROP TABLE / DROP COLUMN koruması (olay tetikleyicisi; Supabase izin vermezse atlanır, TRUNCATE koruması yine çalışır)
create or replace function oyun.silme_korumasi() returns event_trigger language plpgsql as $$
declare o record;
begin
  if coalesce(current_setting('oyun.sifirlama', true), '') = 'evet' or coalesce(current_setting('oyun.tablo_kaldir', true), '') = 'evet' then return; end if;
  for o in select * from pg_event_trigger_dropped_objects() loop
    if o.schema_name = 'oyun' and o.object_type in ('table','table column') and not o.is_temporary then
      raise exception 'Oyun verileri korunuyor: % (%) silinemez. Güncellemeler yalnızca ekleme yapar.', o.object_identity, o.object_type;
    end if;
  end loop;
end $$;

create or replace function oyun.koruma_kur() returns void language plpgsql as $$
declare t record;
begin
  for t in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'oyun' and c.relkind = 'r' loop
    execute format('drop trigger if exists bosaltma_korumasi on oyun.%I', t.relname);
    execute format('create trigger bosaltma_korumasi before truncate on oyun.%I for each statement execute function oyun.bosaltma_korumasi()', t.relname);
  end loop;
  begin
    if not exists (select 1 from pg_event_trigger where evtname = 'oyun_silme_korumasi') then
      create event trigger oyun_silme_korumasi on sql_drop execute function oyun.silme_korumasi();
    end if;
  exception when insufficient_privilege or feature_not_supported then
    raise notice 'Bilgi: DROP koruması (olay tetikleyicisi) bu sunucuda kurulamadı; TRUNCATE koruması ve güncelleme bütünlük kontrolü etkin.';
  end;
end $$;

-- Güncellemenin sonu: oyuncu verisi değiştiyse her şey geri alınır
create or replace function oyun.guncelleme_bitti() returns jsonb language plpgsql as $$
declare s oyun.surumler; once jsonb; sonra jsonb := oyun.parmak_izi(); k text; farklar text := '';
begin
  select * into s from oyun.surumler where bitis is null order by id desc limit 1;
  if s.id is null then raise exception 'guncelleme_basla çağrılmadan guncelleme_bitti çağrıldı.'; end if;
  once := coalesce(s.parmak_once, '{}');
  -- hiç oyuncu yokken (ilk kurulum ya da sahibin sıfırlaması) başlangıç verileri yüklenir; korunacak oyuncu verisi yoktur
  if coalesce(once ->> 'oyuncu', '0') = '0' then once := '{}'; end if;
  for k in select jsonb_object_keys(once) loop
    if sonra ->> k is distinct from once ->> k then farklar := farklar || ' ' || k; end if;
  end loop;
  if farklar <> '' then
    raise exception 'GÜNCELLEME DURDURULDU: bu güncelleme oyuncu verisini değiştirecekti (%). Hiçbir değişiklik uygulanmadı; oyun olduğu gibi duruyor.', btrim(farklar);
  end if;
  update oyun.surumler set bitis = clock_timestamp(), parmak_sonra = sonra where id = s.id;
  update oyun.ayarlar set son_uygulama = s.surum where id = 1;
  perform oyun.koruma_kur();
  return jsonb_build_object('surum', s.surum, 'yedek', s.yedek, 'kontrol', 'oyuncu verisi değişmedi', 'oyuncu', sonra ->> 'oyuncu', 'aktif_makam', sonra ->> 'aktif_makam');
end $$;

-- Uygulamanın sürüm kontrolü: eski uygulama sunucuyla uyumsuz hâle gelirse "güncelle" ekranı gösterir
create or replace function public.surum() returns jsonb
language sql security definer set search_path = oyun, public, pg_temp as $$
  select jsonb_build_object('sunucu', (select surum from oyun.surumler where bitis is not null order by id desc limit 1),
                            'son_uygulama', a.son_uygulama, 'min_uygulama', a.min_uygulama)
  from oyun.ayarlar a where a.id = 1
$$;
revoke all on function public.surum() from public;
grant execute on function public.surum() to anon, authenticated;

-- Yönetici: eski uygulamaları zorunlu güncellemeye yönlendir
create or replace function public.admin_min_uygulama(p_surum text) returns jsonb
language plpgsql security definer set search_path = oyun, public, pg_temp as $$
declare y oyun.profiller := oyun.yonetici_zorunlu();
begin
  if p_surum !~ '^[0-9]{4}\.[0-9]{2}\.[0-9]{2}-[0-9]+$' and p_surum <> '0' then raise exception 'Sürüm biçimi YYYY.AA.GG-N olmalı.'; end if;
  update oyun.ayarlar set min_uygulama = p_surum where id = 1;
  return public.surum();
end $$;
revoke all on function public.admin_min_uygulama(text) from public, anon;
grant execute on function public.admin_min_uygulama(text) to authenticated;

-- ---------------------------------------------------------------------
-- SAHİBİN ARAÇLARI (yalnızca Supabase SQL Editor'den; uygulamadan çağrılamaz)
-- ---------------------------------------------------------------------
-- Katalog tabloları sıfırlamada korunur (iller, bakanlıklar, icraat/vaat/kural katalogları, ayarlar, sürümler)
create or replace function oyun.katalog_tablo(t text) returns boolean language sql immutable as $$
  select t in ('ayarlar','iller','bakanliklar','icraatlar','vaat_turleri','duzenleme_tanim','belediye_hizmetleri','belediye_yatirimlari',
               'paketler','gecici_eposta','surumler','yonetici_kimlik')
$$;

-- Oyunu sıfırlar: önce yedek alır, sonra oyun dünyasını boşaltır. Oyuncu hesapları (giriş bilgileri) kalır;
-- herkes yeniden profil oluşturur. Ardından supabase-kurulum.sql bir kez daha çalıştırılmalıdır (başlangıç verileri).
create or replace function oyun.oyunu_sifirla(p_onay text) returns text language plpgsql as $$
declare y text; liste text;
begin
  if p_onay is distinct from 'OYUNU SIFIRLA' then
    raise exception 'Oyunu sıfırlamak için tam olarak şunu yaz: select oyun.oyunu_sifirla(''OYUNU SIFIRLA'');';
  end if;
  y := oyun.yedek_al('Sıfırlama öncesi');
  perform set_config('oyun.sifirlama', 'evet', true);
  select string_agg(format('oyun.%I', c.relname), ', ') into liste
    from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'oyun' and c.relkind = 'r' and not oyun.katalog_tablo(c.relname);
  execute 'truncate ' || liste || ' restart identity cascade';
  return format('Oyun sıfırlandı. Yedek: %s. Şimdi supabase-kurulum.sql dosyasını bir kez daha çalıştır.', y);
end $$;

-- Bir yedeğe geri döner (o anki durumun da yedeği alınır). Sütunu yedekte olmayan yeni tablolar boş kalır.
create or replace function oyun.yedekten_don(p_sema text, p_onay text) returns text language plpgsql as $$
declare y text; t record; liste text; kalan text[]; tur int := 0; sutunlar text; ok boolean; n int;
begin
  if p_onay is distinct from 'GERİ YÜKLE' then
    raise exception 'Geri yüklemek için: select oyun.yedekten_don(''%'', ''GERİ YÜKLE'');', p_sema;
  end if;
  if p_sema !~ '^yedek_' or not exists (select 1 from pg_namespace where nspname = p_sema) then raise exception 'Yedek bulunamadı: %', p_sema; end if;
  y := oyun.yedek_al('Geri yükleme öncesi');
  perform set_config('oyun.sifirlama', 'evet', true);
  select array_agg(c.relname::text) into kalan from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'oyun' and c.relkind = 'r' and c.relname <> 'surumler'
     and exists (select 1 from pg_class c2 join pg_namespace n2 on n2.oid = c2.relnamespace where n2.nspname = p_sema and c2.relname = c.relname);
  select string_agg(format('oyun.%I', x), ', ') into liste from unnest(kalan) x;
  execute 'truncate ' || liste || ' cascade';
  foreach liste in array kalan loop execute format('alter table oyun.%I disable trigger user', liste); end loop;
  -- yabancı anahtar sırası bilinmediği için birkaç turda yükle
  while array_length(kalan, 1) > 0 and tur < 10 loop
    tur := tur + 1;
    foreach liste in array kalan loop
      select string_agg(format('%I', a.attname), ', ') into sutunlar
        from pg_attribute a join pg_class c on c.oid = a.attrelid join pg_namespace n on n.oid = c.relnamespace
       where n.nspname = 'oyun' and c.relname = liste and a.attnum > 0 and not a.attisdropped and a.attgenerated = ''
         and exists (select 1 from pg_attribute b join pg_class c2 on c2.oid = b.attrelid join pg_namespace n2 on n2.oid = c2.relnamespace
                     where n2.nspname = p_sema and c2.relname = liste and b.attname = a.attname and not b.attisdropped);
      ok := true;
      begin
        -- overriding system value: "generated always as identity" sütunlu tablolar da yedekten dönebilsin
        execute format('insert into oyun.%I (%s) overriding system value select %s from %I.%I', liste, sutunlar, sutunlar, p_sema, liste);
      exception when foreign_key_violation then ok := false;
      end;
      if ok then kalan := array_remove(kalan, liste); end if;
    end loop;
  end loop;
  for t in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'oyun' and c.relkind = 'r' loop
    execute format('alter table oyun.%I enable trigger user', t.relname);
  end loop;
  if array_length(kalan, 1) > 0 then raise exception 'Geri yükleme tamamlanamadı (%); hiçbir şey değişmedi.', array_to_string(kalan, ', '); end if;
  -- kimlik sayaçlarını yedekteki en büyük değere getir
  for t in select s.relname seq, tc.relname tablo, a.attname sutun from pg_class s
             join pg_depend d on d.objid = s.oid and d.deptype in ('a','i') join pg_class tc on tc.oid = d.refobjid
             join pg_attribute a on a.attrelid = tc.oid and a.attnum = d.refobjsubid join pg_namespace n on n.oid = tc.relnamespace
            where s.relkind = 'S' and n.nspname = 'oyun' loop
    execute format('select coalesce(max(%I), 0) from oyun.%I', t.sutun, t.tablo) into n;
    if n > 0 then execute format('select setval(%L, %s)', 'oyun.' || t.seq, n); end if;
  end loop;
  return format('%s yedeğine dönüldü. Dönüş öncesi durumun yedeği: %s', p_sema, y);
end $$;

revoke all on function oyun.oyunu_sifirla(text), oyun.yedekten_don(text, text), oyun.yedek_al(text) from public;
select oyun.guncelleme_bitti();
commit;

-- =====================================================================
--  SEÇİM SİMÜLASYONU ONLINE — 4) ZAMANLAYICI (yalnızca Supabase'de)
--  Seçim motorunu her dakika çalıştırır: takvimi üretir, 18:00'de sayar,
--  göreve başlatmaları yapar. Supabase'de "pg_cron" eklentisi gerekir.
-- =====================================================================
create extension if not exists pg_cron with schema pg_catalog;
grant usage on schema cron to postgres;
grant all privileges on all tables in schema cron to postgres;

-- Oyun saatini bu andan başlat (bu andan önceki seçimler oluşturulmaz)
-- İlk kurulumda (henüz hiç seçim yokken) başlangıcı şimdiye al; güncellemelerde takvime dokunma
update oyun.ayarlar set test_simdi = null where id = 1;
update oyun.ayarlar set baslangic = now() where id = 1 and not exists (select 1 from oyun.secimler);

-- Varsa eski zamanlayıcıyı kaldır, yenisini kur
select cron.unschedule(jobid) from cron.job where jobname = 'secim-motoru';
select cron.schedule('secim-motoru', '* * * * *', 'select oyun.tick()');
-- Türkiye Gündem otomatik gazetesi (5 dakikada bir)
select cron.schedule('turkiye-gundem-otomatik-gazete', '*/5 * * * *', 'select oyun.ajans_derle()');
-- Şirket halka arzları: süresi dolanları her dakika sonuçlandır
select cron.schedule('halka-arz', '* * * * *', 'select oyun.halka_arz_tick()');

-- İlk takvimi hemen üret
select oyun.tick();
-- Belediye: bina inşaat/bakım (30 dk) ve kriz masası (saatte bir; açık krizlerin süresini de kapatır)
select cron.schedule('belediye-sehir-bina-tick', '*/30 * * * *', 'select oyun.belediye_bina_tick()');
select cron.schedule('belediye-kriz', '7 * * * *', 'select oyun.belediye_kriz_tick()');
-- Ekonomi kurumları (Merkez Bankası, belediye tahvili, SPK, konkordato): 10 dakikada bir
select cron.unschedule(jobid) from cron.job where jobname = 'ekonomi-2';
select cron.schedule('ekonomi-2', '*/10 * * * *', 'select oyun.ekonomi2_tick()');

-- 102 Siyaset Merkezi (2026-10-16)
select cron.schedule('siyaset-merkezi', '1-59/5 * * * *', 'select oyun.siyaset_merkezi_tick()');

-- 113 Zamanlayıcı geçmişi temizliği (2026-10-22): cron.job_run_details günde ~8.000 satır büyüyordu; son 7 gün tutulur
select cron.schedule('cron-gecmis-temizlik', '23 3 * * *', $$delete from cron.job_run_details where end_time < now() - interval '7 days'$$);
